package am.ik.rontolisp.macro;

import am.ik.rontolisp.ClosRegistry;
import am.ik.rontolisp.LambdaLists;
import am.ik.rontolisp.LispArray;
import am.ik.rontolisp.LispBigInteger;
import am.ik.rontolisp.LispChar;
import am.ik.rontolisp.LispCons;
import am.ik.rontolisp.LispDouble;
import am.ik.rontolisp.LispInstance;
import am.ik.rontolisp.LispInteger;
import am.ik.rontolisp.LispLayout;
import am.ik.rontolisp.LispNames;
import am.ik.rontolisp.LispNil;
import am.ik.rontolisp.LispRatio;
import am.ik.rontolisp.LispString;
import am.ik.rontolisp.LispSymbol;
import am.ik.rontolisp.LispTrue;
import am.ik.rontolisp.LispVal;
import am.ik.rontolisp.PackageRegistry;
import am.ik.rontolisp.PackageResolver;
import am.ik.rontolisp.StructLiteralFolder;

import java.util.ArrayList;
import java.util.List;

import org.jspecify.annotations.Nullable;

/**
 * Macro expander for cond, and, and or forms. Expands into primitive special forms (if,
 * let, progn) that are handled by the evaluator and compilers.
 */
public final class LispMacroExpander {

	private static final String COND_VAR = "__cond";

	private LispMacroExpander() {
	}

	/**
	 * Single-step expansion of a built-in macro call, used by
	 * {@code macroexpand-1}/{@code macroexpand}. The case list must stay in sync with
	 * {@code PackageRegistry.CL_MACROS} (the names {@code rontolisp:list-macros}
	 * reports); function-like operators expanded through this class (e.g. {@code 1+},
	 * {@code member}) are CL functions, not macros, and are deliberately absent.
	 * @param cons the form to expand
	 * @return the expansion, or {@code null} when the operator is not a built-in macro
	 */
	public static @Nullable LispVal expandBuiltinMacro(LispCons cons) {
		if (!(cons.car() instanceof LispSymbol sym)) {
			return null;
		}
		return switch (sym.name()) {
			case LispNames.COND -> expandCond(cons);
			case LispNames.CASE -> expandCase(cons);
			case LispNames.ECASE -> expandEcase(cons);
			case LispNames.CCASE -> expandCcase(cons);
			case LispNames.TYPECASE -> expandTypecase(cons);
			case LispNames.ETYPECASE -> expandEtypecase(cons);
			case LispNames.AND -> expandAnd(cons);
			case LispNames.OR -> expandOr(cons);
			case LispNames.WHEN -> expandWhen(cons);
			case LispNames.UNLESS -> expandUnless(cons);
			case LispNames.DOTIMES -> expandDotimes(cons);
			case LispNames.DOLIST -> expandDolist(cons);
			case LispNames.DO -> expandDo(cons);
			case LispNames.DO_STAR -> expandDoStar(cons);
			case LispNames.LET_STAR -> expandLetStar(cons);
			case LispNames.SETF -> expandSetf(cons);
			case LispNames.PUSH -> expandPush(cons);
			case LispNames.POP -> expandPop(cons);
			case LispNames.REMF -> expandRemf(cons);
			case LispNames.INCF -> expandIncf(cons);
			case LispNames.DECF -> expandDecf(cons);
			case LispNames.FORMAT -> expandFormat(cons);
			case LispNames.WITH_OPEN_FILE -> expandWithOpenFile(cons);
			case LispNames.PROG1 -> expandProg1(cons);
			case LispNames.PROG2 -> expandProg2(cons);
			case LispNames.PSETQ -> expandPsetq(cons);
			case LispNames.ERROR -> expandError(cons);
			case LispNames.CERROR -> expandCerror(cons, EMPTY_CLOS_REGISTRY);
			case LispNames.SIGNAL -> expandSignalMacro(cons);
			case LispNames.TIME -> expandTime(cons);
			case LispNames.LOOP -> expandLoop(cons);
			case LispNames.CHECK_TYPE -> expandCheckType(cons);
			case LispNames.ASSERT -> expandAssert(cons);
			case LispNames.DECLARE -> expandDeclare(cons);
			case LispNames.DECLAIM -> expandDeclaim(cons);
			case LispNames.PROCLAIM -> expandProclaim(cons);
			case LispNames.THE -> expandThe(cons);
			case LispNames.EVAL_WHEN -> expandEvalWhen(cons);
			case LispNames.WRITE_CHAR -> expandWriteChar(cons);
			case LispNames.LOCALLY -> expandLocally(cons);
			case LispNames.WITH_STANDARD_IO_SYNTAX -> expandWithStandardIoSyntax(cons);
			case LispNames.FLET -> expandFlet(cons);
			case LispNames.LABELS -> expandLabels(cons);
			case LispNames.MULTIPLE_VALUE_BIND -> expandMultipleValueBind(cons);
			case LispNames.MULTIPLE_VALUE_LIST -> expandMultipleValueList(cons);
			case LispNames.MULTIPLE_VALUE_CALL -> expandMultipleValueCall(cons);
			case LispNames.NTH_VALUE -> expandNthValue(cons);
			case LispNames.MULTIPLE_VALUE_SETQ -> expandMultipleValueSetq(cons);
			case LispNames.ROTATEF -> expandRotatef(cons);
			case LispNames.DESTRUCTURING_BIND -> expandDestructuringBind(cons);
			case LispNames.WITH_OUTPUT_TO_STRING -> expandWithOutputToString(cons);
			case LispNames.WITH_INPUT_FROM_STRING -> expandWithInputFromString(cons);
			case LispNames.PUSHNEW -> expandPushnew(cons);
			case LispNames.DEFTYPE -> expandDeftype(cons);
			case LispNames.DEFINE_CONDITION -> expandDefineCondition(cons);
			case LispNames.DEFINE_SETF_EXPANDER -> expandDefineSetfExpander(cons);
			case LispNames.DEFINE_COMPILER_MACRO -> expandDefineCompilerMacro(cons);
			case LispNames.RESTART_CASE -> expandRestartCase(cons);
			case LispNames.HANDLER_BIND -> expandHandlerBind(cons, EMPTY_CLOS_REGISTRY);
			case LispNames.RESTART_BIND -> expandRestartBind(cons);
			case LispNames.WITH_SIMPLE_RESTART -> expandWithSimpleRestart(cons);
			case LispNames.MAKE_CONDITION -> expandMakeCondition(cons);
			case LispNames.WITH_SLOTS -> expandWithSlots(cons);
			case LispNames.WITH_ACCESSORS -> expandWithAccessors(cons);
			case LispNames.IGNORE_ERRORS -> expandIgnoreErrors(cons);
			case LispNames.DOCUMENTATION -> expandDocumentation(cons);
			case LispNames.COMPLEMENT -> expandComplement(cons);
			default -> null;
		};
	}

	/**
	 * Expands (cond (test body...) ...) into nested if/let/progn expressions.
	 *
	 * <pre>
	 * (cond)                         -> nil
	 * (cond (test) rest...)          -> (let ((__cond test)) (if __cond __cond (cond rest...)))
	 * (cond (test body) rest...)     -> (if test body (cond rest...))
	 * (cond (test b1 b2...) rest...) -> (if test (progn b1 b2...) (cond rest...))
	 * </pre>
	 * @param cons the cond expression
	 * @return the expanded expression
	 */
	public static LispVal expandCond(LispCons cons) {
		List<LispVal> parts = cons.toList();
		// (cond) -> nil
		if (parts.size() == 1) {
			return LispNil.INSTANCE;
		}
		return expandCondClauses(parts.subList(1, parts.size()));
	}

	private static LispVal expandCondClauses(List<LispVal> clauses) {
		if (clauses.isEmpty()) {
			return LispNil.INSTANCE;
		}
		LispCons clause = (LispCons) clauses.get(0);
		List<LispVal> clauseParts = clause.toList();
		LispVal test = clauseParts.get(0);
		List<LispVal> body = clauseParts.subList(1, clauseParts.size());
		LispVal elseExpr = expandCondClauses(clauses.subList(1, clauses.size()));
		if (body.isEmpty()) {
			// Bodyless clause: (cond (test) ...) -> (let ((__cond test)) (if __cond
			// __cond (cond rest...)))
			return makeLet(COND_VAR, test, makeIf(new LispSymbol(COND_VAR), new LispSymbol(COND_VAR), elseExpr));
		}
		else if (body.size() == 1) {
			// Single body: (cond (test body) ...) -> (if test body (cond rest...))
			return makeIf(test, body.get(0), elseExpr);
		}
		else {
			// Multiple body: (cond (test b1 b2...) ...) -> (if test (progn b1 b2...)
			// (cond rest...))
			return makeIf(test, makeProgn(body), elseExpr);
		}
	}

	/**
	 * Expands (case keyform clause...) into a let/cond expression. The keyform is
	 * evaluated once and bound to a temporary, then each clause's keys are compared with
	 * {@code eq}.
	 *
	 * <pre>
	 * (case x
	 *   (a 1)              ; single key
	 *   ((b c) 2)          ; list of keys (matches b or c)
	 *   (otherwise 3))     ; default clause (also t)
	 * ->
	 * (let ((__case x))
	 *   (cond ((eq __case 'a) 1)
	 *         ((or (eq __case 'b) (eq __case 'c)) 2)
	 *         (t 3)))
	 * </pre>
	 *
	 * The clause keys are object designators and are not evaluated. A clause key of
	 * {@code t} or {@code otherwise} marks the default clause. A list key matches when
	 * the keyform is {@code eql} to any element; any other atom is a single key. (Unlike
	 * Common Lisp, a {@code nil} key is treated as a single key matching {@code nil}, not
	 * as an empty key list.) A clause with no body returns nil.
	 * @param cons the case expression
	 * @return the expanded expression
	 */
	public static LispVal expandCase(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException("case expects a keyform");
		}
		LispVal keyform = parts.get(1);
		List<LispVal> clauses = parts.subList(2, parts.size());
		LispSymbol keyVar = new LispSymbol(CASE_VAR);
		List<LispVal> condParts = new java.util.ArrayList<>();
		condParts.add(new LispSymbol(LispNames.COND));
		for (LispVal clauseVal : clauses) {
			if (!(clauseVal instanceof LispCons clause)) {
				throw new IllegalArgumentException("case clause must be a list, got: " + clauseVal.print());
			}
			List<LispVal> clauseParts = clause.toList();
			LispVal keys = clauseParts.get(0);
			List<LispVal> body = clauseParts.subList(1, clauseParts.size());
			LispVal test;
			if (isCaseDefaultKey(keys)) {
				test = LispTrue.INSTANCE;
			}
			else if (keys instanceof LispCons keyList) {
				List<LispVal> orParts = new java.util.ArrayList<>();
				orParts.add(new LispSymbol(LispNames.OR));
				for (LispVal k : keyList.toList()) {
					orParts.add(makeCaseEq(keyVar, k));
				}
				test = listToCons(orParts);
			}
			else {
				test = makeCaseEq(keyVar, keys);
			}
			List<LispVal> condClause = new java.util.ArrayList<>();
			condClause.add(test);
			if (body.isEmpty()) {
				condClause.add(LispNil.INSTANCE);
			}
			else {
				condClause.addAll(body);
			}
			condParts.add(listToCons(condClause));
		}
		return makeLet(CASE_VAR, keyform, listToCons(condParts));
	}

	private static final String CASE_VAR = "__case";

	private static final String ECASE_VAR = "__ecase";

	/**
	 * Expands {@code (ecase keyform (keys body...) ...)} into the same {@code let}/cond
	 * as {@code case}, but without any default clause: {@code t} and {@code otherwise}
	 * are treated as ordinary keys, and a final {@code (error ...)} clause is appended so
	 * an unmatched key signals an error (Common Lisp's exhaustive {@code ecase}).
	 * @param cons the ecase expression
	 * @return the expanded expression
	 */
	public static LispVal expandEcase(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException("ecase expects a keyform");
		}
		LispVal keyform = parts.get(1);
		List<LispVal> clauses = parts.subList(2, parts.size());
		LispSymbol keyVar = new LispSymbol(ECASE_VAR);
		List<LispVal> condParts = new java.util.ArrayList<>();
		condParts.add(new LispSymbol(LispNames.COND));
		for (LispVal clauseVal : clauses) {
			if (!(clauseVal instanceof LispCons clause)) {
				throw new IllegalArgumentException("ecase clause must be a list, got: " + clauseVal.print());
			}
			List<LispVal> clauseParts = clause.toList();
			LispVal keys = clauseParts.get(0);
			List<LispVal> body = clauseParts.subList(1, clauseParts.size());
			LispVal test;
			// ecase does not treat t/otherwise specially: they are ordinary keys.
			if (keys instanceof LispCons keyList) {
				List<LispVal> orParts = new java.util.ArrayList<>();
				orParts.add(new LispSymbol(LispNames.OR));
				for (LispVal k : keyList.toList()) {
					orParts.add(makeCaseEq(keyVar, k));
				}
				test = listToCons(orParts);
			}
			else {
				test = makeCaseEq(keyVar, keys);
			}
			List<LispVal> condClause = new java.util.ArrayList<>();
			condClause.add(test);
			if (body.isEmpty()) {
				condClause.add(LispNil.INSTANCE);
			}
			else {
				condClause.addAll(body);
			}
			condParts.add(listToCons(condClause));
		}
		condParts.add(makeExhaustiveErrorClause(keyVar, "ECASE"));
		return makeLet(ECASE_VAR, keyform, listToCons(condParts));
	}

	/**
	 * Expands {@code (ccase keyform ...)}. Without a restart (store-value) mechanism,
	 * {@code ccase} behaves exactly like {@code ecase}: an unmatched key signals an
	 * error.
	 * @param cons the ccase expression
	 * @return the expanded expression
	 */
	public static LispVal expandCcase(LispCons cons) {
		return expandEcase(cons);
	}

	/**
	 * Builds the {@code (t (error "..."))} fall-through clause shared by {@code ecase}
	 * and {@code etypecase}: it reports the unmatched value bound to {@code var}.
	 */
	private static LispVal makeExhaustiveErrorClause(LispSymbol var, String label) {
		LispVal errorCall = listToCons(
				List.of(new LispSymbol(LispNames.ERROR), new LispString(label + ": no clause matches ~s"), var));
		return listToCons(List.of(LispTrue.INSTANCE, errorCall));
	}

	private static boolean isCaseDefaultKey(LispVal keys) {
		return keys instanceof LispTrue || (keys instanceof LispSymbol sym && LispNames.OTHERWISE.equals(sym.name()));
	}

	private static LispVal makeCaseEq(LispVal var, LispVal key) {
		// case keys are compared with eql (the Common Lisp default), so numeric keys
		// match by value.
		LispVal quoted = listToCons(List.of(new LispSymbol(LispNames.QUOTE), key));
		LispVal test = listToCons(List.of(new LispSymbol(LispNames.EQL), var, quoted));
		// A bare symbol key is package-qualified by the resolver, while quoted data
		// (the usual source of the runtime value) is not; symbols compare by name, so
		// the qualified key alone would never match. Accept the plain spelling too.
		if (key instanceof LispSymbol keySym && PackageRegistry.splitQualified(keySym.name()) != null
				&& !keySym.name().startsWith(":")) {
			PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(keySym.name());
			LispVal plainQuoted = listToCons(List.of(new LispSymbol(LispNames.QUOTE),
					new LispSymbol(java.util.Objects.requireNonNull(qn).member())));
			LispVal plainTest = listToCons(List.of(new LispSymbol(LispNames.EQL), var, plainQuoted));
			return listToCons(List.of(new LispSymbol(LispNames.OR), test, plainTest));
		}
		return test;
	}

	/**
	 * Expands (and ...) into cond expressions.
	 *
	 * <pre>
	 * (and)            -> t
	 * (and x)          -> x
	 * (and x y ... z)  -> (cond ((not x) nil) ((not y) nil) ... (t z))
	 * </pre>
	 * @param cons the and expression
	 * @return the expanded expression
	 */
	public static LispVal expandAnd(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() == 1) {
			// (and) -> t
			return LispTrue.INSTANCE;
		}
		if (parts.size() == 2) {
			// (and x) -> x
			return parts.get(1);
		}
		// (and x y ... z) -> (cond ((not x) nil) ((not y) nil) ... (t z))
		List<LispVal> args = parts.subList(1, parts.size());
		// Build clauses list from right to left
		LispVal lastClause = listToCons(List.of(LispTrue.INSTANCE, args.get(args.size() - 1)));
		LispVal clauses = new LispCons(lastClause, LispNil.INSTANCE);
		for (int i = args.size() - 2; i >= 0; i--) {
			LispVal notClause = listToCons(List.of(makeNot(args.get(i)), LispNil.INSTANCE));
			clauses = new LispCons(notClause, clauses);
		}
		LispCons condExpr = new LispCons(new LispSymbol(LispNames.COND), clauses);
		return expandCond(condExpr);
	}

	/**
	 * Expands (or ...) into cond expressions.
	 *
	 * <pre>
	 * (or)             -> nil
	 * (or x)           -> x
	 * (or x y ... z)   -> (cond (x) (y) ... (z))
	 * </pre>
	 * @param cons the or expression
	 * @return the expanded expression
	 */
	public static LispVal expandOr(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() == 1) {
			// (or) -> nil
			return LispNil.INSTANCE;
		}
		if (parts.size() == 2) {
			// (or x) -> x
			return parts.get(1);
		}
		// (or x y ... z) -> (cond (x) (y) ... (z))
		// Each clause is a bodyless clause wrapping a single expr
		LispVal clauses = LispNil.INSTANCE;
		for (int i = parts.size() - 1; i >= 1; i--) {
			LispVal clause = new LispCons(parts.get(i), LispNil.INSTANCE);
			clauses = new LispCons(clause, clauses);
		}
		LispCons condExpr = new LispCons(new LispSymbol(LispNames.COND), clauses);
		return expandCond(condExpr);
	}

	/**
	 * Expands (when condition body...) into an if expression.
	 *
	 * <pre>
	 * (when cond body)       -> (if cond body nil)
	 * (when cond b1 b2...)   -> (if cond (progn b1 b2...) nil)
	 * </pre>
	 * @param cons the when expression
	 * @return the expanded expression
	 */
	/**
	 * Expands {@code (rontolisp:async-defun name (ll) body...)} into
	 * {@code (defun name (ll) (rontolisp::%async-run (lambda () body...)))} -- the
	 * lowering shared by the interpreter, the JVM backend and Preview-1 WASM, which
	 * implement asynchrony in the one {@code %async-run} primitive and inherit
	 * lambda-list desugaring, closures and Lisp-2 function values from the ordinary defun
	 * machinery. The {@code --component} backend compiles the form natively instead (a
	 * state machine needs the raw body) and never calls this.
	 * @param cons the async-defun form
	 * @return the expansion
	 */
	public static LispVal expandAsyncDefun(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3 || !(parts.get(1) instanceof LispSymbol)) {
			throw new IllegalArgumentException(
					LispNames.ASYNC_DEFUN_QUALIFIED + " expects a name and a lambda list, got: " + cons.print());
		}
		List<LispVal> defun = new ArrayList<>();
		defun.add(new LispSymbol(LispNames.DEFUN));
		defun.add(parts.get(1));
		defun.add(parts.get(2));
		defun.add(asyncRunForm(parts.subList(3, parts.size())));
		return listToCons(defun);
	}

	/**
	 * Expands {@code (rontolisp:async-lambda (ll) body...)} into
	 * {@code (lambda (ll) (rontolisp::%async-run (lambda () body...)))}; see
	 * {@link #expandAsyncDefun(LispCons)}.
	 * @param cons the async-lambda form
	 * @return the expansion
	 */
	public static LispVal expandAsyncLambda(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException(
					LispNames.ASYNC_LAMBDA_QUALIFIED + " expects a lambda list, got: " + cons.print());
		}
		List<LispVal> lambda = new ArrayList<>();
		lambda.add(new LispSymbol(LispNames.LAMBDA));
		lambda.add(parts.get(1));
		lambda.add(asyncRunForm(parts.subList(2, parts.size())));
		return listToCons(lambda);
	}

	/**
	 * Expands the {@code (rontolisp:async form)} wrapper macro into the canonical
	 * asynchronous defining form: {@code (rontolisp:async (defun name (ll) body...))}
	 * becomes {@code (rontolisp:async-defun name (ll) body...)} and
	 * {@code (rontolisp:async (lambda (ll) body...))} becomes
	 * {@code (rontolisp:async-lambda (ll) body...)}. Anything else inside is an error --
	 * the wrapper accepts exactly one defun or lambda form.
	 * @param cons the async form
	 * @return the expansion
	 */
	public static LispVal expandAsync(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() == 2 && parts.get(1) instanceof LispCons inner && inner.isProperList()
				&& inner.car() instanceof LispSymbol head) {
			String member = unqualifiedClMember(head.name());
			if (LispNames.DEFUN.equals(member)) {
				return new LispCons(new LispSymbol(LispNames.ASYNC_DEFUN_QUALIFIED), inner.cdr());
			}
			if (LispNames.LAMBDA.equals(member)) {
				return new LispCons(new LispSymbol(LispNames.ASYNC_LAMBDA_QUALIFIED), inner.cdr());
			}
		}
		throw new IllegalArgumentException(LispNames.ASYNC_QUALIFIED
				+ " expects a single (defun ...) or (lambda ...) form to make asynchronous, got: " + cons.print());
	}

	/**
	 * Returns whether the given head symbol names the {@code rontolisp:async} wrapper
	 * macro, in the canonical resolved spelling or any {@code rontolisp:}/
	 * {@code rontolisp::}-qualified source spelling (the rewrite runs both before and
	 * after {@code PackageResolver}).
	 * @param name the head symbol name
	 * @return {@code true} for a {@code rontolisp:async} head
	 */
	public static boolean isAsyncSugarHead(String name) {
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(name);
		return qn != null && LispNames.RONTOLISP_PKG.equals(qn.pkg()) && LispNames.ASYNC.equals(qn.member());
	}

	// The member name of a cl-owned head symbol: bare ("defun") or qualified through
	// the cl package ("cl:defun"; splitQualified normalizes the built-in nicknames,
	// so "common-lisp:defun" splits to the cl package too).
	private static @Nullable String unqualifiedClMember(String name) {
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(name);
		if (qn == null) {
			return name;
		}
		return LispNames.CL_PKG.equals(qn.pkg()) ? qn.member() : null;
	}

	/**
	 * Rewrites every {@code (rontolisp:async form)} wrapper in a program -- top-level and
	 * nested -- into its {@code async-defun}/{@code async-lambda} expansion
	 * ({@link #expandAsync(LispCons)}), leaving quoted data and macro-definition bodies
	 * untouched (their expansion output is rewritten instead, like
	 * {@link LispAsync#check}). This is the one frontend pass that makes the wrapper
	 * exist: it runs before every consumer of the canonical async forms (the await
	 * placement check, the {@code %async-run}/state-machine lowerings and the
	 * defun-definition scanners), so none of them ever sees the sugar.
	 * @param program the top-level forms (resolved or unresolved)
	 * @return the program with every wrapper expanded
	 */
	public static List<LispVal> rewriteAsyncSugar(List<LispVal> program) {
		List<LispVal> out = new ArrayList<>(program.size());
		for (LispVal form : program) {
			out.add(rewriteAsyncSugarForm(form));
		}
		return out;
	}

	/**
	 * The single-form variant of {@link #rewriteAsyncSugar(List)}, for callers holding
	 * one form (a macro expansion's output) rather than a whole program.
	 * @param form the form (resolved or unresolved)
	 * @return the form with every wrapper expanded
	 */
	public static LispVal rewriteAsyncSugarForm(LispVal form) {
		if (!(form instanceof LispCons cons) || !cons.isProperList()) {
			return form;
		}
		if (cons.car() instanceof LispSymbol sym) {
			switch (sym.name()) {
				case LispNames.QUOTE, LispNames.DEFMACRO, LispNames.MACROLET -> {
					return form;
				}
				default -> {
					if (isAsyncSugarHead(sym.name())) {
						return rewriteAsyncSugarForm(expandAsync(cons));
					}
				}
			}
		}
		List<LispVal> parts = cons.toList();
		List<LispVal> rewritten = new ArrayList<>(parts.size());
		boolean changed = false;
		for (LispVal part : parts) {
			LispVal r = rewriteAsyncSugarForm(part);
			changed |= (r != part);
			rewritten.add(r);
		}
		return changed ? listToCons(rewritten) : form;
	}

	/** Builds {@code (rontolisp::%async-run (lambda () body...))}. */
	private static LispVal asyncRunForm(List<LispVal> body) {
		List<LispVal> thunk = new ArrayList<>();
		thunk.add(new LispSymbol(LispNames.LAMBDA));
		thunk.add(LispNil.INSTANCE);
		thunk.addAll(body);
		return listToCons(List.of(new LispSymbol(LispNames.ASYNC_RUN_QUALIFIED), listToCons(thunk)));
	}

	/**
	 * Expands {@code (when test body...)} to {@code (if test <body> nil)}, wrapping a
	 * multi-form body in a {@code progn}.
	 * @param cons the when expression
	 * @return the expanded expression
	 */
	public static LispVal expandWhen(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal condition = parts.get(1);
		List<LispVal> body = parts.subList(2, parts.size());
		if (body.size() == 1) {
			return makeIf(condition, body.get(0), LispNil.INSTANCE);
		}
		else {
			return makeIf(condition, makeProgn(body), LispNil.INSTANCE);
		}
	}

	/**
	 * Expands (dotimes (var count-form [result-form]) body...) into a let/while loop.
	 *
	 * <pre>
	 * (dotimes (i n result) body...) ->
	 * (let ((i 0) (__dotimes_limit n))
	 *   (while (&lt; i __dotimes_limit)
	 *     body...
	 *     (setq i (+ i 1)))
	 *   result)
	 * </pre>
	 *
	 * The count form is evaluated once and bound to a temporary so that side effects in
	 * the count expression are not repeated on every iteration. The loop variable is
	 * bound to the integers 0, 1, ..., count-1 in turn; after the loop it holds the count
	 * value when the optional result form is evaluated. Without a result form the
	 * expansion yields nil.
	 * @param cons the dotimes expression
	 * @return the expanded expression
	 */
	public static LispVal expandDotimes(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispCons spec = (LispCons) parts.get(1);
		List<LispVal> specParts = spec.toList();
		LispVal var = specParts.get(0);
		LispVal countForm = specParts.get(1);
		LispVal resultForm = (specParts.size() > 2) ? specParts.get(2) : LispNil.INSTANCE;
		List<LispVal> body = parts.subList(2, parts.size());
		LispSymbol limitSym = new LispSymbol(DOTIMES_LIMIT_VAR);
		// Bindings: ((var 0) (__dotimes_limit count-form))
		LispVal binding1 = listToCons(List.of(var, new LispInteger(0)));
		LispVal binding2 = listToCons(List.of(limitSym, countForm));
		LispVal bindings = listToCons(List.of(binding1, binding2));
		// (< var __dotimes_limit)
		LispVal test = listToCons(List.of(new LispSymbol(LispNames.LT), var, limitSym));
		// (setq var (+ var 1))
		LispVal increment = listToCons(List.of(new LispSymbol(LispNames.ADD), var, new LispInteger(1)));
		LispVal step = listToCons(List.of(new LispSymbol(LispNames.SETQ), var, increment));
		// (while test body... step)
		List<LispVal> whileParts = new java.util.ArrayList<>();
		whileParts.add(new LispSymbol(LispNames.WHILE));
		whileParts.add(test);
		whileParts.addAll(body);
		whileParts.add(step);
		LispVal whileExpr = listToCons(whileParts);
		// (let (bindings) while-expr result-form)
		List<LispVal> letParts = new java.util.ArrayList<>();
		letParts.add(new LispSymbol(LispNames.LET));
		letParts.add(bindings);
		letParts.add(whileExpr);
		letParts.add(resultForm);
		return makeBlock(listToCons(letParts));
	}

	private static final String DOTIMES_LIMIT_VAR = "__dotimes_limit";

	/**
	 * Expands (prog1 first body...) into a let that evaluates first, then the body forms,
	 * and finally returns the saved value of first.
	 *
	 * <pre>
	 * (prog1 first body...) ->
	 * (let ((__prog1_result first))
	 *   body...
	 *   __prog1_result)
	 * </pre>
	 *
	 * The first form is evaluated once and saved before the body runs, so its value is
	 * returned even if the body mutates whatever first referred to. With no body forms
	 * the expansion simply returns the value of first.
	 * @param cons the prog1 expression
	 * @return the expanded expression
	 */
	public static LispVal expandProg1(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal first = parts.get(1);
		List<LispVal> body = parts.subList(2, parts.size());
		LispSymbol resultSym = new LispSymbol(PROG1_RESULT_VAR);
		// ((__prog1_result first))
		LispVal binding = listToCons(List.of(resultSym, first));
		LispVal bindings = new LispCons(binding, LispNil.INSTANCE);
		// (let (bindings) body... __prog1_result)
		List<LispVal> letParts = new java.util.ArrayList<>();
		letParts.add(new LispSymbol(LispNames.LET));
		letParts.add(bindings);
		letParts.addAll(body);
		letParts.add(resultSym);
		return listToCons(letParts);
	}

	private static final String PROG1_RESULT_VAR = "__prog1_result";

	private static final String TIME_START_VAR = "__time_start";

	private static final String TIME_RESULT_VAR = "__time_result";

	/**
	 * Expands (time form) into a let/progn that records the real time before and after
	 * evaluating {@code form}, prints the elapsed milliseconds to standard output, and
	 * returns the form's value.
	 *
	 * <pre>
	 * (time form) ->
	 * (let ((__time_start (get-internal-real-time)))
	 *   (let ((__time_result form))
	 *     (progn
	 *       (princ "; Elapsed real time: ")
	 *       (princ (- (get-internal-real-time) __time_start))
	 *       (princ " ms")
	 *       (terpri)
	 *       __time_result)))
	 * </pre>
	 *
	 * The elapsed value is an integer of milliseconds on the interpreter and JVM backends
	 * and a float of milliseconds on WASM (where {@code get-internal-real-time} returns a
	 * float).
	 * @param cons the time expression
	 * @return the expanded expression
	 */
	public static LispVal expandTime(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal form = parts.get(1);
		LispSymbol startSym = new LispSymbol(TIME_START_VAR);
		LispSymbol resultSym = new LispSymbol(TIME_RESULT_VAR);
		// (- (get-internal-real-time) __time_start)
		LispVal nowCall = listToCons(List.of(new LispSymbol(LispNames.GET_INTERNAL_REAL_TIME)));
		LispVal elapsed = listToCons(List.of(new LispSymbol(LispNames.SUB), nowCall, startSym));
		// (progn (princ ...) (princ elapsed) (princ " ms") (terpri) __time_result)
		LispVal report = makeProgn(
				List.of(listToCons(List.of(new LispSymbol(LispNames.PRINC), new LispString("; Elapsed real time: "))),
						listToCons(List.of(new LispSymbol(LispNames.PRINC), elapsed)),
						listToCons(List.of(new LispSymbol(LispNames.PRINC), new LispString(" ms"))),
						listToCons(List.of(new LispSymbol(LispNames.TERPRI))), resultSym));
		// (let ((__time_result form)) report)
		LispVal inner = makeLet(TIME_RESULT_VAR, form, report);
		// (let ((__time_start (get-internal-real-time))) inner)
		LispVal startCall = listToCons(List.of(new LispSymbol(LispNames.GET_INTERNAL_REAL_TIME)));
		return makeLet(TIME_START_VAR, startCall, inner);
	}

	/**
	 * Expands (do ((var init [step])...) (end-test result...) body...) into a let/while
	 * loop wrapped in a {@code %block} so that {@code return} exits it.
	 *
	 * <pre>
	 * (do ((v1 i1 s1) (v2 i2)) (end r...) body...) ->
	 * (%block
	 *   (let ((v1 i1) (v2 i2))
	 *     (while (not end)
	 *       body...
	 *       (setq v1 s1))       ; only stepped vars are reassigned (in parallel)
	 *     (progn r...)))
	 * </pre>
	 *
	 * Steps are evaluated in parallel: when more than one variable has a step form, all
	 * step forms are first evaluated into temporaries and only then assigned, matching
	 * Common Lisp. A variable without a step keeps its value (mutated only by the body).
	 * @param cons the do expression
	 * @return the expanded expression
	 */
	public static LispVal expandDo(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal bindingsForm = parts.get(1);
		LispVal endClause = parts.get(2);
		List<LispVal> body = parts.subList(3, parts.size());
		List<LispVal> letBindings = new java.util.ArrayList<>();
		// Stepped variables, in source order: each entry is {var, step-form}.
		List<LispVal[]> steps = new java.util.ArrayList<>();
		if (bindingsForm instanceof LispCons bindingsCons) {
			for (LispVal binding : bindingsCons.toList()) {
				if (binding instanceof LispSymbol bare) {
					// (do (x) ...) -- a bare symbol binds x to nil with no step.
					letBindings.add(listToCons(List.of(bare, LispNil.INSTANCE)));
				}
				else {
					List<LispVal> spec = ((LispCons) binding).toList();
					LispVal var = spec.get(0);
					LispVal init = spec.size() > 1 ? spec.get(1) : LispNil.INSTANCE;
					letBindings.add(listToCons(List.of(var, init)));
					if (spec.size() > 2) {
						steps.add(new LispVal[] { var, spec.get(2) });
					}
				}
			}
		}
		// (end-test result...): loop while the test is false, then evaluate the results.
		LispVal endTest = LispNil.INSTANCE;
		List<LispVal> resultForms = List.of();
		if (endClause instanceof LispCons endCons) {
			List<LispVal> endParts = endCons.toList();
			endTest = endParts.get(0);
			resultForms = endParts.subList(1, endParts.size());
		}
		// (while (not end-test) body... step)
		List<LispVal> whileParts = new java.util.ArrayList<>();
		whileParts.add(new LispSymbol(LispNames.WHILE));
		whileParts.add(makeNot(endTest));
		whileParts.addAll(body);
		whileParts.addAll(makeStepForms(steps));
		LispVal whileExpr = listToCons(whileParts);
		// Result: nil with no result forms, the form itself for one, else a progn.
		LispVal resultExpr;
		if (resultForms.isEmpty()) {
			resultExpr = LispNil.INSTANCE;
		}
		else if (resultForms.size() == 1) {
			resultExpr = resultForms.get(0);
		}
		else {
			resultExpr = makeProgn(resultForms);
		}
		// (do () ...) is legal: an empty binding list stays nil.
		LispVal bindings = letBindings.isEmpty() ? LispNil.INSTANCE : listToCons(letBindings);
		LispVal letExpr = listToCons(List.of(new LispSymbol(LispNames.LET), bindings, whileExpr, resultExpr));
		return makeBlock(letExpr);

	}

	/**
	 * Expands (do* ((var init [step])...) (end-test result...) body...) into a
	 * {@code let*} plus {@code while} loop wrapped in a {@code %block}. Unlike
	 * {@code do}, bindings are established sequentially (each init form sees the
	 * variables bound before it) and step forms are assigned sequentially each iteration
	 * (each step sees the updates already made this iteration), matching Common Lisp
	 * {@code do*} semantics.
	 * @param cons the do* expression
	 * @return the expanded expression
	 */
	public static LispVal expandDoStar(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal bindingsForm = parts.get(1);
		LispVal endClause = parts.get(2);
		List<LispVal> body = parts.subList(3, parts.size());
		List<LispVal> letBindings = new java.util.ArrayList<>();
		// Stepped variables, in source order: each entry is {var, step-form}.
		List<LispVal[]> steps = new java.util.ArrayList<>();
		if (bindingsForm instanceof LispCons bindingsCons) {
			for (LispVal binding : bindingsCons.toList()) {
				if (binding instanceof LispSymbol bare) {
					letBindings.add(listToCons(List.of(bare, LispNil.INSTANCE)));
				}
				else {
					List<LispVal> spec = ((LispCons) binding).toList();
					LispVal var = spec.get(0);
					LispVal init = spec.size() > 1 ? spec.get(1) : LispNil.INSTANCE;
					letBindings.add(listToCons(List.of(var, init)));
					if (spec.size() > 2) {
						steps.add(new LispVal[] { var, spec.get(2) });
					}
				}
			}
		}
		LispVal endTest = LispNil.INSTANCE;
		List<LispVal> resultForms = List.of();
		if (endClause instanceof LispCons endCons) {
			List<LispVal> endParts = endCons.toList();
			endTest = endParts.get(0);
			resultForms = endParts.subList(1, endParts.size());
		}
		// (while (not end-test) body... (setq v1 s1) (setq v2 s2) ...) -- sequential
		// steps.
		List<LispVal> whileParts = new java.util.ArrayList<>();
		whileParts.add(new LispSymbol(LispNames.WHILE));
		whileParts.add(makeNot(endTest));
		whileParts.addAll(body);
		for (LispVal[] s : steps) {
			whileParts.add(listToCons(List.of(new LispSymbol(LispNames.SETQ), s[0], s[1])));
		}
		LispVal whileExpr = listToCons(whileParts);
		LispVal resultExpr;
		if (resultForms.isEmpty()) {
			resultExpr = LispNil.INSTANCE;
		}
		else if (resultForms.size() == 1) {
			resultExpr = resultForms.get(0);
		}
		else {
			resultExpr = makeProgn(resultForms);
		}
		LispVal bindings = listToCons(letBindings);
		LispVal letExpr = listToCons(List.of(new LispSymbol(LispNames.LET_STAR), bindings, whileExpr, resultExpr));
		return makeBlock(letExpr);
	}

	/**
	 * The surface keywords recognized by the {@code loop} macro, matched by symbol name
	 * (case-insensitively, ignoring package) only in clause position. The same name used
	 * as an ordinary value in a clause expression (e.g.
	 * {@code (loop repeat (length to) ...)}) is not treated as a keyword because it never
	 * appears where a keyword is expected.
	 */
	private static final java.util.Set<String> LOOP_KEYWORDS = java.util.Set.of("for", "as", "from", "upfrom",
			"downfrom", "to", "upto", "below", "downto", "above", "by", "in", "on", "=", "then", "across", "repeat",
			"while", "until", "do", "doing", "collect", "collecting", "append", "appending", "nconc", "nconcing", "sum",
			"summing", "count", "counting", "maximize", "maximizing", "minimize", "minimizing", "when", "if", "unless",
			"else", "end", "finally", "initially", "return", "with", "and", "into", "thereis", "always", "never",
			// Parsed and discarded: type declarations carry no information here.
			"of-type",
			// The loop's named block: (loop named foo ...) wraps the expansion in
			// (block foo ...), so (return-from foo v) exits it on every backend.
			"named",
			// Recognized so its use fails with a clear "unsupported" error instead of
			// being misparsed as a simple-loop body or a missing for sub-clause.
			"being");

	/**
	 * Expands the {@code loop} macro into the existing core ({@code %block}/{@code let*}/
	 * {@code while}/{@code setq}/{@code return} plus list/number accumulators) so that
	 * all three backends compile it without a dedicated form.
	 *
	 * <p>
	 * Two shapes are recognized. A <em>simple loop</em> — every top-level subform is a
	 * compound form, e.g. {@code (loop (print x) (when done (return)))} — repeats its
	 * body forever until a {@code return}. An <em>extended loop</em> begins with a clause
	 * keyword and supports this bounded subset of the ANSI grammar:
	 *
	 * <ul>
	 * <li>numeric stepping:
	 * {@code for v from LO [to|upto|below|downto|above HI] [by STEP]} (and
	 * {@code upfrom}/{@code downfrom}; a limit keyword with no {@code from} defaults the
	 * start to 0),</li>
	 * <li>list stepping: {@code for v in LIST [by FN]} and {@code for v on LIST [by FN]}
	 * ({@code v} may be a destructuring pattern),</li>
	 * <li>general stepping: {@code for v = INIT [then STEP]} ({@code v} may be a
	 * destructuring pattern),</li>
	 * <li>sequence stepping: {@code for v across SEQ} (a string's characters or a
	 * vector's elements),</li>
	 * <li>parallel {@code for} groups: {@code for a ... and b ...} binds and steps the
	 * group in parallel (each init/step sees the previous iteration's values),</li>
	 * <li>local variables: {@code with v [= INIT]} ({@code v} may be a destructuring
	 * pattern; {@code and}-joined {@code with} bindings are parallel),</li>
	 * <li>accumulation: {@code collect}/{@code append}/{@code nconc}/{@code sum}/
	 * {@code count}/{@code maximize}/{@code minimize}, each with an optional
	 * {@code into v},</li>
	 * <li>termination tests: {@code thereis}/{@code always}/{@code never} (short-circuit
	 * like {@code return}, skipping {@code finally}; {@code always}/{@code never} yield
	 * {@code t} on normal completion),</li>
	 * <li>control: {@code while}/{@code until} (honoring their textual position),
	 * {@code repeat N}, {@code do FORM...}, {@code return EXPR}, {@code (loop-finish)}
	 * inside body forms (jumps to the {@code finally}+result epilogue),
	 * {@code initially FORM...}, {@code finally FORM...}, and the conditionals
	 * {@code when}/{@code if}/{@code unless} with an optional {@code else} and
	 * {@code end} (selectable clauses chainable with {@code and}, supporting the
	 * anaphoric {@code it}).</li>
	 * </ul>
	 *
	 * <p>
	 * The {@code for v being {the|each} {symbols|present-symbols|external-symbols}
	 * {of|in} PACKAGE} clause is accepted but <em>lite</em>: rontolisp has no runtime
	 * intern table, so it iterates the empty sequence (the loop body never runs and
	 * accumulation yields nil). It exists so cl-who's hyperdoc table loads.
	 *
	 * <p>
	 * Limitations: {@code being} hash-table iteration ({@code hash-key}/
	 * {@code hash-value}), {@code named}/ {@code return-from}, and lambda-list keywords
	 * inside destructuring patterns. {@code (loop-finish)} must appear in statement
	 * position and not inside a nested iteration form. Accumulation clauses without
	 * {@code into} must all be of the same kind (collecting clauses build the list in
	 * order; the result list is produced with {@code nreverse}) and cannot be combined
	 * with {@code thereis}/{@code always}/ {@code never}.
	 * @param cons the loop expression
	 * @return the expanded expression
	 */
	public static LispVal expandLoop(LispCons cons) {
		List<LispVal> all = cons.toList();
		List<LispVal> toks = all.subList(1, all.size());
		// (loop) -> an empty endless loop, exited only by a non-local return.
		if (toks.isEmpty()) {
			return makeBlock(listToCons(List.of(new LispSymbol(LispNames.WHILE), LispTrue.INSTANCE, LispNil.INSTANCE)));
		}
		// Simple loop: the body is a sequence of forms repeated forever.
		if (loopKeyword(toks.get(0)) == null) {
			List<LispVal> whileParts = new java.util.ArrayList<>();
			whileParts.add(new LispSymbol(LispNames.WHILE));
			whileParts.add(LispTrue.INSTANCE);
			whileParts.addAll(toks);
			return makeBlock(listToCons(whileParts));
		}
		return new LoopExpander(toks).build();
	}

	/**
	 * Returns the lowercased loop keyword a token denotes, or null if it is not one. As
	 * in CL, loop keywords are matched by symbol name regardless of package, so the
	 * keyword-package spelling ({@code :for}, {@code :collect}, {@code :=}) used by many
	 * libraries is recognized too.
	 */
	private static @Nullable String loopKeyword(LispVal v) {
		if (v instanceof LispSymbol s) {
			String n = s.name();
			// A bare loop keyword inside a user package arrives package-qualified
			// (pkg::into): match by the plain member name, like the keyword spelling.
			PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(n);
			if (qn != null) {
				n = qn.member();
			}
			n = n.toLowerCase(java.util.Locale.ROOT);
			if (n.startsWith(":") && n.length() > 1) {
				n = n.substring(1);
			}
			if (LOOP_KEYWORDS.contains(n)) {
				return n;
			}
		}
		return null;
	}

	/**
	 * Parses an extended {@code loop} clause sequence into the pieces of a {@code let*}/
	 * {@code while} expansion: binding/init forms, per-iteration variable assignments,
	 * the loop body, step forms, termination tests, {@code initially}/{@code finally}
	 * forms and the accumulation result. See {@link LispMacroExpander#expandLoop} for the
	 * grammar.
	 */
	private static final class LoopExpander {

		private final List<LispVal> toks;

		private int pos;

		private int gen;

		private final List<LispVal> bindings = new java.util.ArrayList<>();

		private final List<LispVal> initially = new java.util.ArrayList<>();

		private final List<LispVal> mainBody = new java.util.ArrayList<>();

		// Forms emitted at the START of every iteration body (before any user do form
		// or accumulator). Populated by `for X = init` (no `then`) clauses so the init
		// is re-evaluated per iteration -- a zero-iteration loop never runs it (see
		// ForPiece.bodyPrefix).
		private final List<LispVal> bodyPrefix = new java.util.ArrayList<>();

		private final List<LispVal> steps = new java.util.ArrayList<>();

		// Termination tests other than per-piece driver ends and user
		// while/until (which live in iterationHeads / userEndTests): always /
		// never / thereis contribute here.
		private final List<LispVal> endTests = new java.util.ArrayList<>();

		// Per-clause iteration heads (source order): for each `for` group we emit
		// one composite form that (a) checks the group's driver terminations, and
		// (b) runs the group's `for X = init` setqs. The while cond is
		// (and iterHead-1 iterHead-2 ... userEndTests) so a driver terminating in
		// clause K skips the assigns of clauses K+1..N -- matching CL's per-clause
		// evaluation order (uax-15's compose-hangul relies on driver K firing
		// before the following `for ch = (aref ...)` init runs; parse-number's
		// parse-integers relies on the preceding `for left = ... then (1+ right)`
		// updating left BEFORE the subsequent `for point in splits` driver
		// terminates, so its `finally` sees the fresh left).
		private final List<LispVal> iterationHeads = new java.util.ArrayList<>();

		// User-supplied `while`/`until` end-tests that appear BEFORE any mainBody
		// form. Emitted AFTER every iterationHead so an all-clauses-passed loop
		// still respects the outer termination (CL semantics for
		// `for c = (form) while c`).
		private final List<LispVal> userEndTests = new java.util.ArrayList<>();

		// A shared iteration flag: {@code t} on the first pass through the body,
		// {@code nil} thereafter. Materialized on demand by
		// {@link #iterationCounterVar()}; the outer let* binds it to {@code t} and
		// the last step form flips it to nil. Used by {@code for X = init then step}
		// bodyPrefix expansions to pick init the first time through and step-form
		// afterwards.
		@Nullable private LispSymbol firstIterVar;

		// The (loop named foo ...) block name: the whole expansion is additionally
		// wrapped in (block foo ...), a named return-from target on every backend.
		@Nullable private LispVal blockName;

		// The termination tests contributed by driver clauses (for/repeat) only, in
		// clause order. A later driver's steps are guarded by the earlier drivers'
		// tests so that, as in CL, stepping stops at the first exhausted driver
		// (e.g. `for x in xs for a = ... then (f a x)` must not evaluate the step
		// form once xs runs out).
		private final List<LispVal> driverEndTests = new java.util.ArrayList<>();

		// Per for-group (source order): the group's user-visible DRIVER variables
		// (in/on/across/numeric vars; `=` records excluded). Consulted by
		// retargetSequentialEqualsSteps to detect an `=` form referencing a LATER
		// clause's driver variable.
		private final List<java.util.Set<String>> groupDriverVars = new java.util.ArrayList<>();

		// The sequential `=`-only groups, with everything needed to re-time their
		// step evaluation after the whole clause list is parsed; see
		// retargetSequentialEqualsSteps.
		private final List<SeqEqualsGroup> seqEqualsGroups = new java.util.ArrayList<>();

		private final List<LispVal> finallyForms = new java.util.ArrayList<>();

		private final List<LispVal> postLoop = new java.util.ArrayList<>();

		// The implicit (un-named) accumulator: its variable, the init form establishing
		// it,
		// and whether the collected list must be reversed to restore source order.
		private @Nullable LispSymbol implicitAcc;

		private @Nullable LispVal implicitInit;

		private boolean implicitReverse;

		// Set by always/never (TRUE: normal completion returns t) or thereis (FALSE:
		// normal completion returns nil). Incompatible with implicit accumulation.
		private @Nullable Boolean terminationT;

		/**
		 * Placeholder statement emitted where a positional {@code while}/{@code until}
		 * (or a {@code (loop-finish)} call) exits to the loop epilogue; replaced with the
		 * actual finally+result exit once the whole loop has been parsed.
		 */
		private static final LispSymbol EPILOGUE_MARKER = new LispSymbol("__loop_epilogue_exit");

		/**
		 * Form heads the epilogue-exit substitution must not descend into: quoted data,
		 * function values, and forms that establish their own {@code %block} boundary
		 * (the epilogue exit is a {@code return} to the nearest block, so it is only
		 * valid directly inside this loop's block).
		 */
		private static final java.util.Set<String> EXIT_SKIP_HEADS = java.util.Set.of(LispNames.QUOTE,
				LispNames.FUNCTION, LispNames.LAMBDA, LispNames.DEFUN, LispNames.LOOP, LispNames.DO, LispNames.DO_STAR,
				LispNames.DOLIST, LispNames.DOTIMES, LispNames.BLOCK_INTERNAL);

		/**
		 * Form heads the anaphoric-{@code it} substitution must not descend into: quoted
		 * data and nested loops (whose own conditionals define their own {@code it}).
		 */
		private static final java.util.Set<String> IT_SKIP_HEADS = java.util.Set.of(LispNames.QUOTE, LispNames.FUNCTION,
				LispNames.LOOP);

		LoopExpander(List<LispVal> toks) {
			this.toks = toks;
		}

		LispVal build() {
			parse();
			retargetSequentialEqualsSteps();
			LispVal epilogue = epilogueExit();
			substituteEpilogueExits(initially, epilogue);
			substituteEpilogueExits(iterationHeads, epilogue);
			substituteEpilogueExits(mainBody, epilogue);
			substituteEpilogueExits(steps, epilogue);
			// Per-iteration control order: process for-groups in source order, each
			// group checking its drivers then running its `for X = init` setqs; a
			// terminating driver short-circuits the following groups' setqs. After
			// every group runs its setqs, user `while`/`until` clauses evaluate and
			// finally any leftover `endTests` (from always/never/thereis) fire.
			List<LispVal> conjuncts = new java.util.ArrayList<>();
			conjuncts.addAll(iterationHeads);
			if (!userEndTests.isEmpty()) {
				conjuncts.add(makeNot(orOf(userEndTests)));
			}
			if (!endTests.isEmpty()) {
				conjuncts.add(makeNot(orOf(endTests)));
			}
			LispVal whileCond;
			if (conjuncts.isEmpty()) {
				whileCond = LispTrue.INSTANCE;
			}
			else if (conjuncts.size() == 1) {
				whileCond = conjuncts.get(0);
			}
			else {
				List<LispVal> andParts = new java.util.ArrayList<>(conjuncts.size() + 1);
				andParts.add(new LispSymbol(LispNames.AND));
				andParts.addAll(conjuncts);
				whileCond = listToCons(andParts);
			}
			List<LispVal> whileParts = new java.util.ArrayList<>();
			whileParts.add(new LispSymbol(LispNames.WHILE));
			whileParts.add(whileCond);
			whileParts.addAll(mainBody);
			whileParts.addAll(steps);
			// The shared first-iter flag flips to nil at the tail of the body, so all
			// bodyPrefix reads on the first iteration see t (init picked) and all
			// subsequent iterations see nil (then-form picked).
			if (this.firstIterVar != null) {
				whileParts.add(setq(this.firstIterVar, LispNil.INSTANCE));
			}
			if (whileParts.size() == 2) {
				// while needs a (possibly nil) body form.
				whileParts.add(LispNil.INSTANCE);
			}
			List<LispVal> letBody = new java.util.ArrayList<>();
			letBody.addAll(initially);
			letBody.add(listToCons(whileParts));
			letBody.addAll(postLoop);
			letBody.addAll(finallyForms);
			letBody.add(resultExpr());
			List<LispVal> letParts = new java.util.ArrayList<>();
			letParts.add(new LispSymbol(LispNames.LET_STAR));
			List<LispVal> effectiveBindings = new java.util.ArrayList<>(bindings);
			// Prepend the first-iter flag binding (initial value t) so its var name is
			// in scope for every bodyPrefix setq that reads it (see parseForEquals).
			if (this.firstIterVar != null) {
				effectiveBindings.add(0, pair(this.firstIterVar, LispTrue.INSTANCE));
			}
			letParts.add(effectiveBindings.isEmpty() ? LispNil.INSTANCE : listToCons(effectiveBindings));
			letParts.addAll(letBody);
			LispVal expansion = makeBlock(listToCons(letParts));
			if (this.blockName != null) {
				expansion = listToCons(List.of(new LispSymbol(LispNames.BLOCK), this.blockName, expansion));
			}
			return expansion;
		}

		private void parse() {
			while (pos < toks.size()) {
				String kw = loopKeyword(toks.get(pos));
				if (kw == null) {
					throw new IllegalArgumentException(
							"loop: expected a clause keyword, got: " + toks.get(pos).print());
				}
				pos++;
				parseClause(kw);
			}
		}

		private void parseClause(String kw) {
			switch (kw) {
				case "for", "as" -> parseFor();
				case "with" -> parseWith();
				case "repeat" -> parseRepeat();
				case "while" -> addTerminationTest(nextForm(), false);
				case "until" -> addTerminationTest(nextForm(), true);
				case "thereis" -> parseThereis();
				case "always" -> parseAlwaysNever(false);
				case "never" -> parseAlwaysNever(true);
				case "initially" -> initially.addAll(readForms());
				case "finally" -> finallyForms.addAll(readForms());
				case "do", "doing" -> mainBody.addAll(readForms());
				case "return" -> mainBody.add(makeReturn(nextForm()));
				case "when", "if" -> mainBody.add(parseConditional(false));
				case "unless" -> mainBody.add(parseConditional(true));
				case "collect", "collecting", "append", "appending", "nconc", "nconcing", "sum", "summing", "count",
						"counting", "maximize", "maximizing", "minimize", "minimizing" ->
					mainBody.add(parseAccumulation(kw));
				case "named" -> this.blockName = nextForm();
				default -> throw new UnsupportedOperationException("loop: unsupported clause: " + kw);
			}
		}

		/**
		 * One {@code for} clause's binding/init entry. {@code user} marks a user-visible
		 * variable (as opposed to an internal cursor/limit gensym), whose binding is
		 * deferred behind temporaries when the clause is part of a parallel {@code and}
		 * group.
		 */
		private record ForBinding(LispSymbol var, LispVal init, boolean user) {
		}

		/**
		 * A {@code for X = init [then step]} clause's per-iteration re-assignment record.
		 * {@code then} is null when the loop had no {@code then} form (the init is
		 * re-evaluated on every iteration).
		 */
		private record ForEqualsRecord(LispSymbol var, LispVal init, @Nullable LispVal then) {
		}

		/**
		 * A sequential {@code for X = init [then step]} group's retarget data:
		 * {@code headIndex}/{@code stepInsertPos} locate its iteration head and its
		 * position in the end-of-body step order, {@code earlierDriverEndTests} are the
		 * termination tests of the groups BEFORE it, and {@code groupIndex} its index in
		 * {@link #groupDriverVars}. See {@link #retargetSequentialEqualsSteps}.
		 */
		private record SeqEqualsGroup(int headIndex, int stepInsertPos, List<ForEqualsRecord> records,
				List<LispVal> earlierDriverEndTests, int groupIndex) {
		}

		/**
		 * One {@code for} clause's contributions, kept separate so {@code and}-joined
		 * clauses can bind and step in parallel.
		 */
		private static final class ForPiece {

			final List<ForBinding> binds = new java.util.ArrayList<>();

			// {stepped variable, step expression} pairs (see makeStepForms).
			final List<LispVal[]> steps = new java.util.ArrayList<>();

			// Assignments syncing an iteration variable with its stepped cursor (e.g.
			// the `in` variable from its list cursor). Run after the clause's steps —
			// and, in an `and` group, after the whole group's parallel steps, so the
			// other clauses' step forms still see the previous element.
			final List<LispVal> postSteps = new java.util.ArrayList<>();

			// Per-iteration re-assignment records {var, init, then} for
			// `for X = init [then step]` clauses. Applied at the START of each
			// iteration in a sequential group (see flushForGroup), or promoted to
			// eager outer-bind + parallel-step in a parallel `and` group. `then`
			// may be null (no `then` clause), in which case init is re-evaluated
			// every iteration.
			final List<ForEqualsRecord> bodyPrefix = new java.util.ArrayList<>();

			final List<LispVal> endTests = new java.util.ArrayList<>();

		}

		private void parseFor() {
			List<ForPiece> group = new java.util.ArrayList<>();
			while (true) {
				group.add(parseForPiece());
				if ("and".equals(peekKeyword())) {
					pos++;
					// Tolerate a redundant `for`/`as` after `and`.
					String k = peekKeyword();
					if ("for".equals(k) || "as".equals(k)) {
						pos++;
					}
					continue;
				}
				break;
			}
			flushForGroup(group);
		}

		private ForPiece parseForPiece() {
			LispVal var = nextForm();
			if (!(var instanceof LispSymbol) && !(var instanceof LispCons)) {
				throw new IllegalArgumentException(
						"loop: for expects a variable or destructuring pattern, got: " + var.print());
			}
			skipOfType();
			String sub = peekKeyword();
			if (sub == null) {
				throw new IllegalArgumentException("loop: incomplete for clause for " + var.print());
			}
			ForPiece piece = new ForPiece();
			switch (sub) {
				case "in", "on" -> parseForList(piece, var, sub);
				case "=" -> parseForEquals(piece, var);
				case "from", "upfrom", "downfrom", "to", "upto", "below", "downto", "above", "by" ->
					parseForNumeric(piece, requireSymbol(var, "numeric stepping"));
				case "across" -> parseForAcross(piece, requireSymbol(var, "across"));
				case "being" -> parseForBeing(piece, requireSymbol(var, "being"));
				default -> throw new UnsupportedOperationException("loop: unsupported for clause: " + sub);
			}
			return piece;
		}

		private static LispSymbol requireSymbol(LispVal var, String what) {
			if (var instanceof LispSymbol s) {
				return s;
			}
			throw new IllegalArgumentException("loop: " + what + " does not support destructuring: " + var.print());
		}

		/**
		 * Merges a group of {@code and}-joined {@code for} clauses. A single clause binds
		 * and steps sequentially as before. A parallel group evaluates every init before
		 * binding any user variable (so a later init sees the outer bindings) and steps
		 * all variables against the previous iteration's values via temporaries.
		 */
		private void flushForGroup(List<ForPiece> group) {
			boolean parallel = group.size() > 1;
			List<ForBinding> deferred = new java.util.ArrayList<>();
			List<LispVal[]> groupSteps = new java.util.ArrayList<>();
			// Composite driverEndTests / bodyPrefix for THIS group only.
			List<LispVal> groupDriverEndTests = new java.util.ArrayList<>();
			List<ForEqualsRecord> groupBodyPrefix = new java.util.ArrayList<>();
			for (ForPiece piece : group) {
				for (ForBinding b : piece.binds) {
					if (parallel && b.user()) {
						if (b.init() instanceof LispNil) {
							deferred.add(b);
						}
						else {
							LispSymbol temp = gensym("tmp");
							bindings.add(pair(temp, b.init()));
							deferred.add(new ForBinding(b.var(), temp, true));
						}
					}
					else {
						bindings.add(pair(b.var(), b.init()));
					}
				}
				groupDriverEndTests.addAll(piece.endTests);
				groupSteps.addAll(piece.steps);
				groupBodyPrefix.addAll(piece.bodyPrefix);
			}
			// Flush deferred outer bindings (parallel nil-init and temp-driven
			// entries) BEFORE the parallel bodyPrefix rewrite so replaceBinding
			// finds the freshly added (var, nil) entries to overwrite. Sequential
			// groups have no deferred entries; this is a no-op there.
			for (ForBinding b : deferred) {
				bindings.add(pair(b.var(), b.init()));
			}
			deferred.clear();
			// A PARALLEL `and` group must snapshot every stepping var against the
			// previous iteration's values -- both cursor advances (`for x in xs`)
			// and the `for X = init then step` re-assigns. Move the bodyPrefix
			// records into groupSteps as (var, then-form) step-pairs + eagerly
			// bind their vars to INIT in the outer let*, so on iter 1 the var is
			// `init` (from outer bind) and on iter N > 1 the then-form runs at
			// end of iter N-1 against previous values via makeStepForms's temps
			// (Fibonacci shape). A record with no `then` (init re-evaluated each
			// iter) uses init as its step form.
			//
			// SEQUENTIAL (a single `for` group) picks init or then via the
			// per-loop first-iter flag inside bodyPrefix, so the per-clause
			// order applies: a driver terminating in group K skips the
			// subsequent groups' setqs (uax-15's compose-hangul), while an
			// earlier group's setq still runs even if a later driver terminates
			// the loop this iteration (parse-number).
			if (parallel && !groupBodyPrefix.isEmpty()) {
				List<LispVal[]> stripped = new java.util.ArrayList<>(groupBodyPrefix.size());
				for (ForEqualsRecord rec : groupBodyPrefix) {
					replaceBinding(rec.var(), rec.init());
					stripped.add(new LispVal[] { rec.var(), rec.then() != null ? rec.then() : rec.init() });
				}
				groupBodyPrefix.clear();
				groupSteps.addAll(stripped);
			}
			// Track this group's user-visible driver variables (in/on/across/numeric
			// vars; `=` records excluded) and, for a sequential `=`-only group, the
			// data retargetSequentialEqualsSteps needs to re-time its step forms once
			// the WHOLE clause list is known (see that method).
			java.util.LinkedHashSet<String> userDriverVars = new java.util.LinkedHashSet<>();
			for (ForPiece piece : group) {
				if (piece.bodyPrefix.isEmpty()) {
					for (ForBinding b : piece.binds) {
						if (b.user()) {
							userDriverVars.add(b.var().name());
						}
					}
				}
			}
			groupDriverVars.add(userDriverVars);
			if (!parallel && !groupBodyPrefix.isEmpty() && groupDriverEndTests.isEmpty()) {
				seqEqualsGroups.add(new SeqEqualsGroup(iterationHeads.size(), steps.size(),
						List.copyOf(groupBodyPrefix), List.copyOf(driverEndTests), groupDriverVars.size() - 1));
			}
			// Emit one iterationHead for this group: check its drivers, then run
			// its (sequential) bodyPrefix. A later group's iterationHead runs
			// only after this one signals continue, so a driver terminating
			// here prevents the later group's bodyPrefix from evaluating.
			List<LispVal> groupBodyPrefixForms = sequentialBodyPrefix(groupBodyPrefix);
			LispVal iterHead;
			if (groupDriverEndTests.isEmpty()) {
				iterHead = groupBodyPrefixForms.isEmpty() ? LispTrue.INSTANCE : prognT(groupBodyPrefixForms);
			}
			else if (groupBodyPrefixForms.isEmpty()) {
				iterHead = makeNot(orOf(groupDriverEndTests));
			}
			else {
				// (if (not (or drivers...)) (progn bodyPrefix t) nil)
				iterHead = listToCons(List.of(new LispSymbol(LispNames.IF), makeNot(orOf(groupDriverEndTests)),
						prognT(groupBodyPrefixForms), LispNil.INSTANCE));
			}
			iterationHeads.add(iterHead);
			if (parallel) {
				// All steps compute against the previous iteration's values; the
				// cursor-var syncs run once every cursor has stepped.
				steps.addAll(makeStepForms(groupSteps));
				for (ForPiece piece : group) {
					steps.addAll(piece.postSteps);
				}
			}
			else {
				// Sequential (do*-style): each clause steps fully -- cursor then its
				// variable -- before the next clause's step forms run.
				for (ForPiece piece : group) {
					for (LispVal[] s : piece.steps) {
						steps.add(setq((LispSymbol) s[0], s[1]));
					}
					steps.addAll(piece.postSteps);
				}
			}
			for (ForPiece piece : group) {
				driverEndTests.addAll(piece.endTests);
			}
		}

		private void parseForNumeric(ForPiece piece, LispSymbol var) {
			String k = peekKeyword();
			boolean down = false;
			LispVal from;
			if ("from".equals(k) || "upfrom".equals(k) || "downfrom".equals(k)) {
				down = "downfrom".equals(k);
				pos++;
				from = nextForm();
			}
			else {
				from = new LispInteger(0);
			}
			piece.binds.add(new ForBinding(var, from, true));
			String limitKw = null;
			LispSymbol limitVar = null;
			String lk = peekKeyword();
			if ("to".equals(lk) || "upto".equals(lk) || "below".equals(lk) || "downto".equals(lk)
					|| "above".equals(lk)) {
				limitKw = lk;
				pos++;
				limitVar = gensym("limit");
				piece.binds.add(new ForBinding(limitVar, nextForm(), false));
				if ("downto".equals(lk) || "above".equals(lk)) {
					down = true;
				}
			}
			LispVal by = new LispInteger(1);
			if ("by".equals(peekKeyword())) {
				pos++;
				by = nextForm();
			}
			LispSymbol byVar = gensym("by");
			piece.binds.add(new ForBinding(byVar, by, false));
			piece.steps.add(new LispVal[] { var, call(down ? LispNames.SUB : LispNames.ADD, var, byVar) });
			if (limitVar != null) {
				boolean exclusive = "below".equals(limitKw) || "above".equals(limitKw);
				String cmp;
				if (down) {
					cmp = exclusive ? LispNames.LE : LispNames.LT;
				}
				else {
					cmp = exclusive ? LispNames.GE : LispNames.GT;
				}
				piece.endTests.add(call(cmp, var, limitVar));
			}
		}

		private void parseForList(ForPiece piece, LispVal pattern, String sub) {
			pos++; // consume in/on
			LispVal listForm = nextForm();
			LispVal byFn = null;
			if ("by".equals(peekKeyword())) {
				pos++;
				byFn = normalizeFunctionDesignator(nextForm());
			}
			if ("on".equals(sub)) {
				// The variable is bound to successive tails of the list.
				if (pattern instanceof LispSymbol var) {
					piece.binds.add(new ForBinding(var, listForm, true));
					piece.endTests.add(makeNot(call(LispNames.CONSP, var)));
					piece.steps.add(new LispVal[] { var, stepCdr(var, byFn) });
				}
				else {
					LispSymbol tail = gensym("on");
					piece.binds.add(new ForBinding(tail, listForm, false));
					piece.endTests.add(makeNot(call(LispNames.CONSP, tail)));
					destructureInto(piece, pattern, tail);
					piece.steps.add(new LispVal[] { tail, stepCdr(tail, byFn) });
				}
			}
			else {
				// The variable holds the first element already at binding time (so a
				// later sequential clause's init can reference it, as in CL) and is
				// re-synced from the cursor after each step.
				LispSymbol cursor = gensym("LIST");
				piece.binds.add(new ForBinding(cursor, listForm, false));
				piece.endTests.add(makeNot(call(LispNames.CONSP, cursor)));
				destructureInto(piece, pattern, call(LispNames.CAR, cursor));
				piece.steps.add(new LispVal[] { cursor, stepCdr(cursor, byFn) });
			}
		}

		private void parseForAcross(ForPiece piece, LispSymbol var) {
			pos++; // consume across
			LispVal seqForm = nextForm();
			// `across` walks a random-access sequence (a string's characters or a
			// vector's elements) via an index cursor; the element accessor is chosen at
			// runtime because the sequence type is unknown at expansion time. The
			// element read is bounds-guarded because the variable syncs at binding time
			// and after each step, where the index may sit at the (empty or exhausted)
			// sequence's length.
			LispSymbol seq = gensym("seq");
			LispSymbol idx = gensym("idx");
			piece.binds.add(new ForBinding(seq, seqForm, false));
			piece.binds.add(new ForBinding(idx, new LispInteger(0), false));
			piece.binds.add(new ForBinding(var, guardedElt(seq, idx), true));
			piece.endTests.add(call(LispNames.GE, idx, call(LispNames.LENGTH, seq)));
			piece.steps.add(new LispVal[] { idx, call(LispNames.ADD, idx, new LispInteger(1)) });
			piece.postSteps.add(setq(var, guardedElt(seq, idx)));
		}

		/**
		 * A bounds-checked element read: the sequence's element at the index, or nil when
		 * the index is past the end.
		 */
		private static LispVal guardedElt(LispSymbol seq, LispSymbol idx) {
			LispVal elt = makeIf(call(LispNames.STRINGP, seq), call(LispNames.CHAR, seq, idx),
					call(LispNames.AREF, seq, idx));
			return makeIf(call(LispNames.LT, idx, call(LispNames.LENGTH, seq)), elt, LispNil.INSTANCE);
		}

		/**
		 * The {@code being} clause: {@code for VAR being {the|each} KIND {of|in} SOURCE
		 * [using (...)]}.
		 * <ul>
		 * <li>{@code hash-keys}/{@code hash-key}/{@code hash-values}/{@code hash-value}
		 * of a hash table iterate the table's entries: {@code SOURCE} is snapshotted once
		 * into a {@code (key . value)} alist (via {@code maphash}), then walked like a
		 * list. {@code VAR} takes the key (for {@code hash-keys}) or value (for
		 * {@code hash-values}); an optional {@code using (hash-value V)} /
		 * {@code (hash-key K)} binds the companion variable. Iteration order is
		 * unspecified (it follows the backend's hash-table order).</li>
		 * <li>{@code symbols}/{@code present-symbols}/{@code external-symbols} of a
		 * package are a lite no-op: rontolisp has no runtime intern table (see
		 * {@code .kb/symbol-runtime-api.md}), so {@code SOURCE} is evaluated once for
		 * effect and the empty sequence is iterated ({@code VAR} bound to nil, body never
		 * runs) -- enough for cl-who's hyperdoc table.</li>
		 * </ul>
		 */
		private void parseForBeing(ForPiece piece, LispSymbol var) {
			pos++; // consume being
			// Optional `the`/`each` filler (plain symbols, not loop keywords).
			String filler = plainName(peekToken());
			if ("the".equals(filler) || "each".equals(filler)) {
				pos++;
			}
			String kind = plainName(nextForm());
			boolean hashKeys = "hash-keys".equals(kind) || "hash-key".equals(kind);
			boolean hashValues = "hash-values".equals(kind) || "hash-value".equals(kind);
			if (hashKeys || hashValues) {
				parseForBeingHash(piece, var, hashKeys);
				return;
			}
			// The singular spellings (each symbol / each external-symbol) are the same
			// clause in CL.
			if (!"symbols".equals(kind) && !"symbol".equals(kind) && !"present-symbols".equals(kind)
					&& !"present-symbol".equals(kind) && !"external-symbols".equals(kind)
					&& !"external-symbol".equals(kind)) {
				throw new UnsupportedOperationException(
						"loop: unsupported being clause (only hash-keys/hash-values/{external-,present-,}symbols): "
								+ kind);
			}
			// `of` | `in` (`in` is a loop keyword, `of` is not -- consume either
			// literally).
			String of = plainName(nextForm());
			if (!"of".equals(of) && !"in".equals(of)) {
				throw new IllegalArgumentException("loop: being clause expects of/in, got: " + of);
			}
			LispVal pkg = nextForm();
			// Evaluate PACKAGE for effect, but do not enumerate it (no intern table).
			LispSymbol ignore = gensym("pkg");
			piece.binds.add(new ForBinding(ignore, pkg, false));
			piece.binds.add(new ForBinding(var, LispNil.INSTANCE, true));
			// Iterate the empty sequence: terminate before the first body pass.
			piece.endTests.add(LispTrue.INSTANCE);
		}

		/**
		 * The hash-table {@code being} variants. {@code iterKeys} selects whether
		 * {@code VAR} takes the key or the value; an optional
		 * {@code using (hash-value V)} / {@code (hash-key K)} binds the companion
		 * variable to the other component.
		 */
		private void parseForBeingHash(ForPiece piece, LispSymbol var, boolean iterKeys) {
			String of = plainName(nextForm());
			if (!"of".equals(of) && !"in".equals(of)) {
				throw new IllegalArgumentException("loop: being hash clause expects of/in, got: " + of);
			}
			LispVal hashForm = nextForm();
			LispSymbol usingVar = null;
			boolean usingKey = false;
			if ("using".equals(plainName(peekToken()))) {
				pos++; // consume using
				LispVal spec = nextForm();
				if (!(spec instanceof LispCons specCons) || !(specCons.cdr() instanceof LispCons specTail)
						|| !(specTail.car() instanceof LispSymbol usingSym)) {
					throw new IllegalArgumentException(
							"loop: being hash clause expects using (hash-value V) / (hash-key K)");
				}
				String specKind = plainName(specCons.car());
				usingKey = "hash-key".equals(specKind) || "hash-keys".equals(specKind);
				boolean usingValue = "hash-value".equals(specKind) || "hash-values".equals(specKind);
				if (!usingKey && !usingValue) {
					throw new IllegalArgumentException(
							"loop: being hash `using` expects hash-key/hash-value, got: " + specKind);
				}
				usingVar = usingSym;
			}
			// Snapshot the table into a (key . value) alist once, then walk it like a
			// list.
			LispSymbol cursor = gensym("hcur");
			piece.binds.add(new ForBinding(cursor, hashPairsForm(hashForm), false));
			piece.endTests.add(makeNot(call(LispNames.CONSP, cursor)));
			piece.binds.add(new ForBinding(var, hashComponent(cursor, iterKeys), true));
			piece.steps.add(new LispVal[] { cursor, call(LispNames.CDR, cursor) });
			piece.postSteps.add(setq(var, hashComponent(cursor, iterKeys)));
			if (usingVar != null) {
				piece.binds.add(new ForBinding(usingVar, hashComponent(cursor, usingKey), true));
				piece.postSteps.add(setq(usingVar, hashComponent(cursor, usingKey)));
			}
		}

		/**
		 * The key ({@code (car (car cursor))}) or value ({@code (cdr (car cursor))}) of
		 * the current entry in a {@code (key . value)} alist cursor. Nil-safe: at an
		 * exhausted cursor both reduce to nil (the end test fires before the body reads
		 * them).
		 */
		private static LispVal hashComponent(LispSymbol cursor, boolean key) {
			LispVal entry = call(LispNames.CAR, cursor);
			return key ? call(LispNames.CAR, entry) : call(LispNames.CDR, entry);
		}

		/**
		 * Builds
		 * {@code (let ((acc nil)) (maphash (lambda (k v) (setq acc (cons (cons k v)
		 * acc))) HASH) acc)} -- a self-contained expression snapshotting a hash table's
		 * entries into a {@code (key . value)} alist. Reusing {@code maphash} keeps the
		 * hash iteration backend-neutral (no new primitive).
		 */
		private LispVal hashPairsForm(LispVal hashForm) {
			LispSymbol acc = gensym("hacc");
			LispSymbol k = gensym("hk");
			LispSymbol v = gensym("hv");
			LispVal lambda = listToCons(List.of(new LispSymbol(LispNames.LAMBDA), listToCons(List.of(k, v)),
					setq(acc, call(LispNames.CONS, call(LispNames.CONS, k, v), acc))));
			LispVal maphash = listToCons(List.of(new LispSymbol(LispNames.MAPHASH), lambda, hashForm));
			LispVal bindings = listToCons(List.of(listToCons(List.of(acc, LispNil.INSTANCE))));
			return listToCons(List.of(new LispSymbol(LispNames.LET), bindings, maphash, acc));
		}

		private LispVal stepCdr(LispSymbol cursor, @Nullable LispVal byFn) {
			if (byFn == null) {
				return call(LispNames.CDR, cursor);
			}
			return listToCons(List.of(new LispSymbol(LispNames.FUNCALL), byFn, cursor));
		}

		private void parseForEquals(ForPiece piece, LispVal pattern) {
			pos++; // consume =
			LispVal init = nextForm();
			LispVal then = null;
			if ("then".equals(peekKeyword())) {
				pos++;
				then = nextForm();
			}
			// The variable is bound to nil in the outer let*, then re-assigned at the
			// TOP of every iteration body (bodyPrefix) -- so a zero-iteration loop never
			// evaluates the init at all (uax-15's compose-hangul relies on this: its
			// (aref str i) init form would run out of bounds when the outer let* is
			// entered with i already past the sequence length). Without `then`, the
			// bodyPrefix evaluates init on EVERY iteration. With `then`, the bodyPrefix
			// picks init the first time through and then-form afterwards, using the
			// shared iterationCounterVar() flag so a cross-clause reference (later
			// `for` clauses see the just-assigned value) works correctly.
			if (pattern instanceof LispSymbol var) {
				piece.binds.add(new ForBinding(var, LispNil.INSTANCE, true));
				piece.bodyPrefix.add(new ForEqualsRecord(var, init, then));
			}
			else {
				LispSymbol whole = gensym("d");
				piece.binds.add(new ForBinding(whole, LispNil.INSTANCE, false));
				piece.bodyPrefix.add(new ForEqualsRecord(whole, init, then));
				// Destructure INSIDE bodyPrefix so a `(loop for (a b) = init then
				// step collect a)` sees the just-assigned a on every iteration
				// (destructureInto by itself only rebinds via outer let* + postSteps,
				// which fires at the END of an iteration -- too late for the body's
				// first pass to see a fresh a). The destructured sub-var records
				// have no `then` (the whole var's then already drives them).
				List<LispVal[]> destructureParts = new java.util.ArrayList<>();
				destructurePairs(pattern, whole, destructureParts);
				for (LispVal[] p : destructureParts) {
					piece.binds.add(new ForBinding((LispSymbol) p[0], LispNil.INSTANCE, true));
					piece.bodyPrefix.add(new ForEqualsRecord((LispSymbol) p[0], p[1], null));
				}
			}
		}

		/**
		 * Binds every symbol of a destructuring pattern (or a single variable) to its
		 * accessor over the source expression, and re-destructures after each step.
		 */
		private void destructureInto(ForPiece piece, LispVal pattern, LispVal source) {
			List<LispVal[]> parts = new java.util.ArrayList<>();
			destructurePairs(pattern, source, parts);
			for (LispVal[] p : parts) {
				piece.binds.add(new ForBinding((LispSymbol) p[0], p[1], true));
				piece.postSteps.add(setq((LispSymbol) p[0], p[1]));
			}
		}

		private void parseWith() {
			List<LispVal[]> group = new java.util.ArrayList<>(); // {pattern, init}
			while (true) {
				LispVal var = nextForm();
				if (!(var instanceof LispSymbol) && !(var instanceof LispCons)) {
					throw new IllegalArgumentException("loop: with expects a variable, got: " + var.print());
				}
				skipOfType();
				LispVal val = LispNil.INSTANCE;
				if ("=".equals(peekKeyword())) {
					pos++;
					val = nextForm();
				}
				group.add(new LispVal[] { var, val });
				if ("and".equals(peekKeyword())) {
					pos++;
					continue;
				}
				break;
			}
			if (group.size() == 1) {
				bindWithPattern(group.get(0)[0], group.get(0)[1]);
				return;
			}
			// `and`-joined with bindings are parallel: evaluate every init before binding
			// any variable, so a later init sees the outer bindings.
			List<LispVal[]> deferred = new java.util.ArrayList<>();
			for (LispVal[] g : group) {
				if (g[1] instanceof LispNil) {
					deferred.add(g);
					continue;
				}
				LispSymbol temp = gensym("tmp");
				bindings.add(pair(temp, g[1]));
				deferred.add(new LispVal[] { g[0], temp });
			}
			for (LispVal[] d : deferred) {
				bindWithPattern(d[0], d[1]);
			}
		}

		private void bindWithPattern(LispVal pattern, LispVal init) {
			if (pattern instanceof LispSymbol var) {
				bindings.add(pair(var, init));
				return;
			}
			LispVal source = init;
			if (!(init instanceof LispSymbol)) {
				LispSymbol temp = gensym("tmp");
				bindings.add(pair(temp, init));
				source = temp;
			}
			List<LispVal[]> parts = new java.util.ArrayList<>();
			destructurePairs(pattern, source, parts);
			for (LispVal[] p : parts) {
				bindings.add(pair((LispSymbol) p[0], p[1]));
			}
		}

		/**
		 * A {@code while}/{@code until} before any body clause is hoisted into the loop
		 * head (iteration variables are already current there — they sync at binding time
		 * and at the end of the step forms); once body statements exist, the test runs at
		 * its textual position and exits through the epilogue (finally + result) when it
		 * fires.
		 */
		private void addTerminationTest(LispVal test, boolean until) {
			if (mainBody.isEmpty()) {
				// Route to userEndTests so the per-iteration bodyPrefix (from
				// `for X = init` clauses) runs BEFORE this check -- CL semantics for
				// `for c = (form) while c` requires c to be freshly assigned before
				// the check.
				userEndTests.add(until ? test : makeNot(test));
			}
			else if (until) {
				mainBody.add(makeIf(test, EPILOGUE_MARKER, LispNil.INSTANCE));
			}
			else {
				mainBody.add(makeIf(test, LispNil.INSTANCE, EPILOGUE_MARKER));
			}
		}

		/**
		 * {@code always EXPR} returns nil (skipping {@code finally}, like {@code return})
		 * the first time the expression is nil and t on normal completion;
		 * {@code never EXPR} is the negation.
		 */
		private void parseAlwaysNever(boolean never) {
			setTerminationResult(true);
			LispVal form = nextForm();
			mainBody.add(never ? makeIf(form, makeReturn(LispNil.INSTANCE), LispNil.INSTANCE)
					: makeIf(form, LispNil.INSTANCE, makeReturn(LispNil.INSTANCE)));
		}

		/**
		 * {@code thereis EXPR} returns the first non-nil value of the expression
		 * (skipping {@code finally}, like {@code return}) and nil on normal completion.
		 */
		private void parseThereis() {
			setTerminationResult(false);
			LispSymbol val = gensym("thereis");
			bindings.add(pair(val, LispNil.INSTANCE));
			mainBody.add(makeProgn(List.of(setq(val, nextForm()), makeIf(val, makeReturn(val), LispNil.INSTANCE))));
		}

		private void setTerminationResult(boolean t) {
			if (implicitAcc != null) {
				throw new IllegalArgumentException(
						"loop: cannot combine always/never/thereis with accumulation (use into)");
			}
			if (terminationT != null && terminationT != t) {
				throw new IllegalArgumentException("loop: cannot mix always/never with thereis");
			}
			terminationT = t;
		}

		private void parseRepeat() {
			LispVal n = nextForm();
			LispSymbol counter = gensym("repeat");
			bindings.add(pair(counter, n));
			LispVal test = call(LispNames.LE, counter, new LispInteger(0));
			endTests.add(test);
			if (!steps.isEmpty() && !driverEndTests.isEmpty()) {
				steps.add(makeIf(orOf(driverEndTests), EPILOGUE_MARKER, LispNil.INSTANCE));
			}
			steps.add(setq(counter, call(LispNames.SUB, counter, new LispInteger(1))));
			driverEndTests.add(test);
		}

		/**
		 * Parses a {@code when}/{@code if}/{@code unless} conditional into an if
		 * statement. When a branch references the anaphoric {@code it}, the raw test
		 * value is stored in a per-conditional variable that {@code it} is substituted
		 * with (nested conditionals substitute their own {@code it} first, so each
		 * {@code it} refers to the nearest enclosing test).
		 */
		private LispVal parseConditional(boolean negate) {
			LispVal cond = nextForm();
			LispVal thenStmt = parseConditionalBranch();
			LispVal elseStmt = LispNil.INSTANCE;
			if ("else".equals(peekKeyword())) {
				pos++;
				elseStmt = parseConditionalBranch();
			}
			if ("end".equals(peekKeyword())) {
				pos++;
			}
			LispSymbol itVar = gensym("it");
			LispVal thenSub = substituteIt(thenStmt, itVar);
			LispVal elseSub = substituteIt(elseStmt, itVar);
			if (thenSub == thenStmt && elseSub == elseStmt) {
				return makeIf(negate ? makeNot(cond) : cond, thenStmt, elseStmt);
			}
			bindings.add(pair(itVar, LispNil.INSTANCE));
			return makeProgn(List.of(setq(itVar, cond), makeIf(negate ? makeNot(itVar) : itVar, thenSub, elseSub)));
		}

		/**
		 * Parses one or more selectable clauses joined by {@code and} into a single
		 * statement.
		 */
		private LispVal parseConditionalBranch() {
			List<LispVal> stmts = new java.util.ArrayList<>();
			stmts.add(parseSelectable());
			while ("and".equals(peekKeyword())) {
				pos++;
				stmts.add(parseSelectable());
			}
			return stmts.size() == 1 ? stmts.get(0) : makeProgn(stmts);
		}

		/**
		 * Parses a single clause selectable by {@code when}/{@code unless} into a
		 * statement.
		 */
		private LispVal parseSelectable() {
			String kw = peekKeyword();
			if (kw == null) {
				throw new IllegalArgumentException(
						"loop: expected a clause after when/unless, got: " + toks.get(pos).print());
			}
			pos++;
			return switch (kw) {
				case "do", "doing" -> makeProgn(readForms());
				case "return" -> makeReturn(nextForm());
				case "when", "if" -> parseConditional(false);
				case "unless" -> parseConditional(true);
				case "collect", "collecting", "append", "appending", "nconc", "nconcing", "sum", "summing", "count",
						"counting", "maximize", "maximizing", "minimize", "minimizing" ->
					parseAccumulation(kw);
				default -> throw new UnsupportedOperationException("loop: clause not selectable by when/unless: " + kw);
			};
		}

		private LispVal parseAccumulation(String kw) {
			LispVal value = nextForm();
			skipOfType();
			LispSymbol target;
			LispSymbol tail = null;
			if ("into".equals(peekKeyword())) {
				pos++;
				LispVal v = nextForm();
				if (!(v instanceof LispSymbol intoVar)) {
					throw new IllegalArgumentException("loop: into expects a variable, got: " + v.print());
				}
				target = intoVar;
				registerInto(intoVar, accInit(kw), accReverse(kw));
				tail = intoTails.get(intoVar.name());
			}
			else {
				target = implicitAccumulator(accInit(kw), accReverse(kw));
			}
			// Tolerated after `into` too (e.g. `:sum 1 :into n :of-type fixnum`, the
			// split-sequence spelling), though CL puts of-type before it.
			skipOfType();
			return accStep(kw, target, tail, value);
		}

		/**
		 * Consumes an {@code of-type TYPE} declaration if one is next: the type spec
		 * carries no information for this expansion and is discarded.
		 */
		private void skipOfType() {
			if ("of-type".equals(peekKeyword())) {
				pos++;
				nextForm();
			}
		}

		/** The init form for an accumulator of the given kind. */
		private LispVal accInit(String kw) {
			return switch (canonicalAcc(kw)) {
				case "sum", "count" -> new LispInteger(0);
				default -> LispNil.INSTANCE;
			};
		}

		/** Whether a kind builds a list that must be reversed to restore source order. */
		private boolean accReverse(String kw) {
			return switch (canonicalAcc(kw)) {
				case "collect", "append", "nconc" -> true;
				default -> false;
			};
		}

		/**
		 * Builds the per-iteration accumulation step for the given kind onto {@code acc}.
		 */
		private LispVal accStep(String kw, LispSymbol acc, @Nullable LispSymbol tail, LispVal value) {
			return switch (canonicalAcc(kw)) {
				// The implicit accumulator builds its list reversed and nreverses at
				// the epilogue; an `into` variable is user-visible mid-loop (a
				// `return` may read it before the epilogue), so it accumulates in
				// order through its tail cursor.
				case "collect" -> tail != null ? attachToTail(acc, tail, call(LispNames.CONS, value, LispNil.INSTANCE))
						: setq(acc, call(LispNames.CONS, value, acc));
				case "append" -> tail != null ? attachToTail(acc, tail, call(LispNames.COPY_LIST, value))
						: setq(acc, call(LispNames.REVAPPEND, value, acc));
				case "nconc" ->
					tail != null ? attachToTail(acc, tail, value) : setq(acc, call(LispNames.NRECONC, value, acc));
				case "sum" -> setq(acc, call(LispNames.ADD, acc, value));
				case "count" ->
					makeIf(value, setq(acc, call(LispNames.ADD, acc, new LispInteger(1))), LispNil.INSTANCE);
				case "maximize" -> setq(acc, makeIf(acc, call(LispNames.MAX, acc, value), value));
				case "minimize" -> setq(acc, makeIf(acc, call(LispNames.MIN, acc, value), value));
				default -> throw new UnsupportedOperationException("loop: unsupported accumulation: " + kw);
			};
		}

		/**
		 * Appends the (possibly empty) fresh list produced by {@code elems} at the
		 * accumulator's tail in O(1) amortized:
		 *
		 * <pre>
		 * (let ((__elemsN elems))
		 *   (if acc (rplacd tail __elemsN) (setq acc __elemsN))
		 *   (if __elemsN (setq tail (last __elemsN)) nil))
		 * </pre>
		 */
		private LispVal attachToTail(LispSymbol acc, LispSymbol tail, LispVal elems) {
			LispSymbol elemsVar = gensym("elems");
			LispVal attach = makeIf(acc, call(LispNames.RPLACD, tail, elemsVar), setq(acc, elemsVar));
			LispVal advance = makeIf(elemsVar, setq(tail, call(LispNames.LAST, elemsVar)), LispNil.INSTANCE);
			return makeLet(elemsVar.name(), elems, makeProgn(List.of(attach, advance)));
		}

		private static String canonicalAcc(String kw) {
			return switch (kw) {
				case "collecting" -> "collect";
				case "appending" -> "append";
				case "nconcing" -> "nconc";
				case "summing" -> "sum";
				case "counting" -> "count";
				case "maximizing" -> "maximize";
				case "minimizing" -> "minimize";
				default -> kw;
			};
		}

		private final java.util.Map<String, Boolean> intoVars = new java.util.HashMap<>();

		// The tail cursor of each list-kind `into` variable (see attachToTail).
		private final java.util.Map<String, LispSymbol> intoTails = new java.util.HashMap<>();

		private void registerInto(LispSymbol var, LispVal init, boolean reverse) {
			Boolean seen = intoVars.get(var.name());
			if (seen == null) {
				intoVars.put(var.name(), reverse);
				bindings.add(pair(var, init));
				if (reverse) {
					// List accumulation keeps the into variable in source order at
					// every step (a mid-loop return may read it), so instead of the
					// implicit accumulator's reverse+nreverse it advances a tail
					// cursor bound alongside the variable.
					LispSymbol tail = gensym("tail");
					bindings.add(pair(tail, LispNil.INSTANCE));
					intoTails.put(var.name(), tail);
				}
			}
			else if (seen != reverse) {
				throw new IllegalArgumentException("loop: incompatible accumulation kinds into " + var.name());
			}
		}

		private LispSymbol implicitAccumulator(LispVal init, boolean reverse) {
			if (terminationT != null) {
				throw new IllegalArgumentException(
						"loop: cannot combine always/never/thereis with accumulation (use into)");
			}
			if (implicitAcc == null) {
				implicitAcc = gensym("acc");
				implicitInit = init;
				implicitReverse = reverse;
				bindings.add(pair(implicitAcc, init));
			}
			else if (implicitReverse != reverse || implicitInit == null || !implicitInit.equals(init)) {
				throw new IllegalArgumentException(
						"loop: cannot mix accumulation kinds without into (use distinct into variables)");
			}
			return implicitAcc;
		}

		private LispVal resultExpr() {
			if (implicitAcc == null) {
				return Boolean.TRUE.equals(terminationT) ? LispTrue.INSTANCE : LispNil.INSTANCE;
			}
			return implicitReverse ? call(LispNames.NREVERSE, implicitAcc) : implicitAcc;
		}

		/**
		 * The loop's normal-completion epilogue as an inline exit statement: the
		 * accumulator finish forms, then {@code finally}, then a {@code return} of the
		 * loop result. Substituted for positional {@code while}/{@code until} exits and
		 * {@code (loop-finish)} calls.
		 */
		private LispVal epilogueExit() {
			List<LispVal> parts = new java.util.ArrayList<>();
			parts.add(new LispSymbol(LispNames.PROGN));
			parts.addAll(postLoop);
			parts.addAll(finallyForms);
			parts.add(makeReturn(resultExpr()));
			return listToCons(parts);
		}

		/**
		 * Replaces every epilogue marker and {@code (loop-finish)} call in the given
		 * statements with the epilogue exit.
		 */
		private static void substituteEpilogueExits(List<LispVal> stmts, LispVal epilogue) {
			stmts.replaceAll(stmt -> substituteTree(stmt, EXIT_SKIP_HEADS, v -> isEpilogueExit(v) ? epilogue : null));
		}

		private static boolean isEpilogueExit(LispVal v) {
			if (v instanceof LispSymbol s && EPILOGUE_MARKER.name().equals(s.name())) {
				return true;
			}
			return v instanceof LispCons c && c.car() instanceof LispSymbol head && head.name().equals("LOOP-FINISH");
		}

		/** Substitutes the anaphoric {@code it} symbol with the given variable. */
		private static LispVal substituteIt(LispVal tree, LispSymbol itVar) {
			return substituteTree(tree, IT_SKIP_HEADS,
					v -> (v instanceof LispSymbol s && s.name().equals("IT")) ? itVar : null);
		}

		/**
		 * Rebuilds a form tree with every node the replacer maps swapped out, without
		 * descending into forms whose head is in {@code skipHeads}. Returns the original
		 * instance when nothing was replaced (callers use identity to detect a hit).
		 */
		private static LispVal substituteTree(LispVal tree, java.util.Set<String> skipHeads,
				java.util.function.Function<LispVal, @Nullable LispVal> replacer) {
			LispVal replaced = replacer.apply(tree);
			if (replaced != null) {
				return replaced;
			}
			if (tree instanceof LispCons cons) {
				if (cons.car() instanceof LispSymbol head && skipHeads.contains(head.name())) {
					return tree;
				}
				LispVal car = substituteTree(cons.car(), skipHeads, replacer);
				LispVal cdr = substituteTree(cons.cdr(), skipHeads, replacer);
				if (car == cons.car() && cdr == cons.cdr()) {
					return tree;
				}
				return new LispCons(car, cdr);
			}
			return tree;
		}

		// --- small token / form helpers ---

		private LispVal nextForm() {
			if (pos >= toks.size()) {
				throw new IllegalArgumentException("loop: unexpected end of clauses");
			}
			return toks.get(pos++);
		}

		private @Nullable String peekKeyword() {
			return pos < toks.size() ? loopKeyword(toks.get(pos)) : null;
		}

		private @Nullable LispVal peekToken() {
			return pos < toks.size() ? toks.get(pos) : null;
		}

		/**
		 * The plain, lowercased member name a token denotes (package qualifier and a
		 * leading keyword colon stripped), or null if it is not a symbol. Used to match
		 * {@code being}-clause fillers that are not loop keywords
		 * ({@code the}/{@code each}/ {@code symbols}/{@code of}).
		 */
		private static @Nullable String plainName(@Nullable LispVal v) {
			if (!(v instanceof LispSymbol s)) {
				return null;
			}
			String n = s.name();
			PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(n);
			if (qn != null) {
				n = qn.member();
			}
			n = n.toLowerCase(java.util.Locale.ROOT);
			if (n.startsWith(":") && n.length() > 1) {
				n = n.substring(1);
			}
			return n;
		}

		/**
		 * Reads forms up to (but not consuming) the next clause keyword or end of input.
		 */
		private List<LispVal> readForms() {
			List<LispVal> forms = new java.util.ArrayList<>();
			while (pos < toks.size() && loopKeyword(toks.get(pos)) == null) {
				forms.add(toks.get(pos++));
			}
			if (forms.isEmpty()) {
				forms.add(LispNil.INSTANCE);
			}
			return forms;
		}

		private LispSymbol gensym(String tag) {
			return new LispSymbol("__loop_" + tag + (gen++));
		}

		private LispSymbol iterationCounterVar() {
			if (this.firstIterVar == null) {
				this.firstIterVar = gensym("first");
			}
			return this.firstIterVar;
		}

		private LispVal prognT(List<LispVal> forms) {
			List<LispVal> out = new java.util.ArrayList<>(forms.size() + 2);
			out.add(new LispSymbol(LispNames.PROGN));
			out.addAll(forms);
			out.add(LispTrue.INSTANCE);
			return listToCons(out);
		}

		// Sequential body-prefix: emit `(setq X init)` (or `(setq X (if __first
		// init then))` when a `then` is present) in source order, so a later
		// clause's init sees the earlier clause's just-assigned value.
		/**
		 * Re-times sequential {@code for X = init [then step]} groups whose form
		 * references a driver variable of a LATER clause. CL steps clauses in source
		 * order at the top of each iteration, so such a form must see the PREVIOUS
		 * element of the later driver (s-sql's strcat:
		 * {@code for pos = 0 then (+ pos (length arg)) for arg in args}); the default
		 * head-time evaluation runs after every end-of-body cursor advance and would see
		 * the new one. The fix computes the form into a temp at the group's own position
		 * in the end-of-body step order -- earlier groups' cursors advanced, later ones
		 * not, exactly CL's clause order -- and re-assigns the variable from the temp in
		 * the iteration head (so a driver terminating in an earlier clause still skips
		 * the assignment). The computation is guarded by the earlier groups' termination
		 * tests, which at that point already reflect the next iteration, so a step after
		 * an exhausted driver never runs. Within a group, later records' forms read
		 * earlier records' temps (a destructured {@code (a b) = ... then ...} chain).
		 * Groups whose forms only reference other {@code =} variables (or nothing later)
		 * keep the head-time evaluation, which is already CL's order for them.
		 */
		private void retargetSequentialEqualsSteps() {
			for (int i = this.seqEqualsGroups.size() - 1; i >= 0; i--) {
				SeqEqualsGroup g = this.seqEqualsGroups.get(i);
				java.util.Set<String> laterDrivers = new java.util.HashSet<>();
				for (int j = g.groupIndex() + 1; j < this.groupDriverVars.size(); j++) {
					laterDrivers.addAll(this.groupDriverVars.get(j));
				}
				if (laterDrivers.isEmpty()) {
					continue;
				}
				boolean references = false;
				for (ForEqualsRecord rec : g.records()) {
					if (formReferences(rec.then() != null ? rec.then() : rec.init(), laterDrivers)) {
						references = true;
						break;
					}
				}
				if (!references) {
					continue;
				}
				List<ForEqualsRecord> viaTemps = new java.util.ArrayList<>(g.records().size());
				List<LispVal> tempSetqs = new java.util.ArrayList<>(g.records().size());
				java.util.Map<String, LispSymbol> ownTemps = new java.util.HashMap<>();
				for (ForEqualsRecord rec : g.records()) {
					LispSymbol temp = gensym("then");
					bindings.add(pair(temp, LispNil.INSTANCE));
					LispVal form = rec.then() != null ? rec.then() : rec.init();
					tempSetqs.add(setq(temp, substituteSymbols(form, ownTemps)));
					viaTemps.add(new ForEqualsRecord(rec.var(), rec.init(), temp));
					ownTemps.put(rec.var().name(), temp);
				}
				LispVal stepForm = tempSetqs.size() == 1 ? tempSetqs.get(0) : makeProgn(tempSetqs);
				if (!g.earlierDriverEndTests().isEmpty()) {
					stepForm = makeIf(makeNot(orOf(g.earlierDriverEndTests())), stepForm, LispNil.INSTANCE);
				}
				steps.add(g.stepInsertPos(), stepForm);
				iterationHeads.set(g.headIndex(), prognT(sequentialBodyPrefix(viaTemps)));
			}
		}

		/** Whether the form references (outside quote) any symbol in the name set. */
		private static boolean formReferences(LispVal form, java.util.Set<String> names) {
			if (form instanceof LispSymbol sym) {
				return names.contains(sym.name());
			}
			if (form instanceof LispCons cons) {
				if (cons.car() instanceof LispSymbol head && LispNames.QUOTE.equals(head.name())) {
					return false;
				}
				return formReferences(cons.car(), names) || formReferences(cons.cdr(), names);
			}
			return false;
		}

		/** Replaces bare symbol references (outside quote) per the given map. */
		private static LispVal substituteSymbols(LispVal form, java.util.Map<String, LispSymbol> replacements) {
			if (replacements.isEmpty()) {
				return form;
			}
			if (form instanceof LispSymbol sym) {
				LispSymbol replacement = replacements.get(sym.name());
				return replacement != null ? replacement : form;
			}
			if (form instanceof LispCons cons) {
				if (cons.car() instanceof LispSymbol head && LispNames.QUOTE.equals(head.name())) {
					return form;
				}
				return new LispCons(substituteSymbols(cons.car(), replacements),
						substituteSymbols(cons.cdr(), replacements));
			}
			return form;
		}

		private List<LispVal> sequentialBodyPrefix(List<ForEqualsRecord> records) {
			List<LispVal> forms = new java.util.ArrayList<>(records.size());
			for (ForEqualsRecord rec : records) {
				LispVal effective;
				if (rec.then() == null) {
					effective = rec.init();
				}
				else {
					LispSymbol counter = iterationCounterVar();
					effective = listToCons(List.of(new LispSymbol(LispNames.IF), counter, rec.init(), rec.then()));
				}
				forms.add(setq(rec.var(), effective));
			}
			return forms;
		}

		// Replaces the outer let* binding value for {@code var} in-place. Called
		// when a parallel-group re-classification of a `for X = init` promotes X
		// from lazy-nil to eagerly-init: the same variable was already added to
		// bindings with nil in flushForGroup's binds walk.
		private void replaceBinding(LispSymbol var, LispVal init) {
			for (int i = 0; i < bindings.size(); i++) {
				if (bindings.get(i) instanceof LispCons pair && pair.car() instanceof LispSymbol name
						&& name.name().equals(var.name())) {
					bindings.set(i, pair(var, init));
					return;
				}
			}
			bindings.add(pair(var, init));
		}

		private static LispVal pair(LispSymbol var, LispVal val) {
			return listToCons(List.of(var, val));
		}

		private static LispVal setq(LispSymbol var, LispVal val) {
			return listToCons(List.of(new LispSymbol(LispNames.SETQ), var, val));
		}

		private static LispVal call(String op, LispVal a, LispVal b) {
			return listToCons(List.of(new LispSymbol(op), a, b));
		}

		private static LispVal call(String op, LispVal a) {
			return listToCons(List.of(new LispSymbol(op), a));
		}

		private static LispVal orOf(List<LispVal> tests) {
			if (tests.size() == 1) {
				return tests.get(0);
			}
			List<LispVal> parts = new java.util.ArrayList<>();
			parts.add(new LispSymbol(LispNames.OR));
			parts.addAll(tests);
			return listToCons(parts);
		}

	}

	/**
	 * Builds the per-iteration step assignments for {@code do}. A single stepped variable
	 * becomes a direct {@code setq}; multiple stepped variables are assigned in parallel
	 * via temporaries so a step form sees the previous iteration's values.
	 */
	private static List<LispVal> makeStepForms(List<LispVal[]> steps) {
		if (steps.isEmpty()) {
			return List.of();
		}
		if (steps.size() == 1) {
			LispVal[] s = steps.get(0);
			return List.of(listToCons(List.of(new LispSymbol(LispNames.SETQ), s[0], s[1])));
		}
		List<LispVal> tempBindings = new java.util.ArrayList<>();
		List<LispVal> assignments = new java.util.ArrayList<>();
		for (int i = 0; i < steps.size(); i++) {
			LispVal[] s = steps.get(i);
			LispSymbol temp = new LispSymbol(DO_STEP_VAR + i);
			tempBindings.add(listToCons(List.of(temp, s[1])));
			assignments.add(listToCons(List.of(new LispSymbol(LispNames.SETQ), s[0], temp)));
		}
		List<LispVal> letParts = new java.util.ArrayList<>();
		letParts.add(new LispSymbol(LispNames.LET));
		letParts.add(listToCons(tempBindings));
		letParts.addAll(assignments);
		return List.of(listToCons(letParts));
	}

	private static final String DO_STEP_VAR = "__do_step_";

	/** Wraps a form in the internal {@code %block} return boundary. */
	private static LispVal makeBlock(LispVal body) {
		return listToCons(List.of(new LispSymbol(LispNames.BLOCK_INTERNAL), body));
	}

	/** Builds a {@code (return value)} form for non-local exit from the nearest loop. */
	private static LispVal makeReturn(LispVal value) {
		return listToCons(List.of(new LispSymbol(LispNames.RETURN), value));
	}

	private static LispVal makeIf(LispVal cond, LispVal then, LispVal else_) {
		return listToCons(List.of(new LispSymbol(LispNames.IF), cond, then, else_));
	}

	private static LispVal makeLet(String varName, LispVal value, LispVal body) {
		// (let ((varName value)) body)
		LispVal binding = listToCons(List.of(new LispSymbol(varName), value));
		LispVal bindings = new LispCons(binding, LispNil.INSTANCE);
		return listToCons(List.of(new LispSymbol(LispNames.LET), bindings, body));
	}

	// Variables of the string-sequence dispatch wrappers (seqAsListForm /
	// seqResultDispatchForm). SEQ_IN_VAR and SEQ_LIST_VAR double as the
	// already-wrapped markers checked by wrapSortForStringSeq/wrapReduceForStringSeq.
	private static final String SEQ_IN_VAR = "__seq_in";

	private static final String SEQ_STR_VAR = "__seq_str";

	private static final String SEQ_VEC_VAR = "__seq_vec";

	private static final String SEQ_LIST_VAR = "__seq_lst";

	private static final String SEQ_RES_VAR = "__seq_res";

	/** Builds a {@code (coerce expr 'type)} form. */
	private static LispVal coerceTo(LispVal expr, String type) {
		return listToCons(List.of(new LispSymbol(LispNames.COERCE), expr,
				listToCons(List.of(new LispSymbol(LispNames.QUOTE), new LispSymbol(type)))));
	}

	/**
	 * Wraps a sequence expression so it always scans as a list: the sequence is bound
	 * once and coerced to a list of its elements, matching the {@code list} branch of
	 * {@link #expandCoerce} (a bare list passes through, a string yields its chars, a
	 * general array yields its elements). This lets the list-walking sequence expansions
	 * accept every Common Lisp sequence, not just strings and lists -- uax-15's
	 * {@code (stable-sort <unicode-string> ...)} is the seed vector case.
	 */
	private static LispVal seqAsListForm(LispVal seqExpr) {
		return coerceTo(seqExpr, "LIST");
	}

	/**
	 * Wraps a sequence-returning scan in the string dispatch: the sequence is bound once,
	 * a string is coerced to a list of its characters before the scan (built by
	 * {@code algo} over the list variable), and the scan's result is coerced back to a
	 * string. Non-string sequences run the scan unchanged.
	 *
	 * <p>
	 * {@code arraysExist} false drops the whole vector arm -- the {@code __seq_vec}
	 * binding and the {@code (coerce __seq_res 'vector)} rebuild. This is the one place
	 * that may drop an array-BUILDING form: the rebuild runs only when the input was a
	 * vector, and with no array runtime no vector can reach here, so the guard makes the
	 * builder provably dead (see {@link #expandCoerce(LispCons, boolean)}, which gates
	 * only the reading direction because it cannot see its guard).
	 */
	private static LispVal seqResultDispatchForm(LispVal seqExpr, java.util.function.UnaryOperator<LispVal> algo,
			boolean arraysExist) {
		LispSymbol in = new LispSymbol(SEQ_IN_VAR);
		LispSymbol isStr = new LispSymbol(SEQ_STR_VAR);
		LispSymbol isVec = new LispSymbol(SEQ_VEC_VAR);
		LispSymbol lst = new LispSymbol(SEQ_LIST_VAR);
		LispSymbol res = new LispSymbol(SEQ_RES_VAR);
		// (let ((__seq_in seq))
		// (let ((__seq_str (stringp __seq_in)))
		// (let ((__seq_vec (vectorp __seq_in)))
		// (let ((__seq_lst (if (or __seq_str __seq_vec) (coerce __seq_in 'list)
		// __seq_in)))
		// (let ((__seq_res <algo __seq_lst>))
		// (if __seq_str (coerce __seq_res 'string)
		// (if __seq_vec (coerce __seq_res 'vector) __seq_res)))))))
		LispVal result = arraysExist
				? makeIf(isStr, coerceTo(res, "STRING"), makeIf(isVec, coerceTo(res, "VECTOR"), res))
				: makeIf(isStr, coerceTo(res, "STRING"), res);
		LispVal resLet = makeLet(SEQ_RES_VAR, algo.apply(lst), result);
		LispVal asList = arraysExist ? listToCons(List.of(new LispSymbol(LispNames.OR), isStr, isVec)) : isStr;
		LispVal lstLet = makeLet(SEQ_LIST_VAR, makeIf(asList, coerceTo(in, "LIST"), in), resLet);
		LispVal vecLet = arraysExist ? makeLet(SEQ_VEC_VAR, callOf(LispNames.VECTORP, in), lstLet) : lstLet;
		LispVal strLet = makeLet(SEQ_STR_VAR, callOf(LispNames.STRINGP, in), vecLet);
		return makeLet(SEQ_IN_VAR, seqExpr, strLet);
	}

	/** True for the internal dispatch variables emitted by the wrappers above. */
	private static boolean isSeqDispatchVar(LispVal val) {
		return val instanceof LispSymbol sym && (SEQ_IN_VAR.equals(sym.name()) || SEQ_LIST_VAR.equals(sym.name()));
	}

	/**
	 * Wraps a {@code (sort seq pred)} call in the string dispatch: a string sequence
	 * sorts as a list of its characters and the result is coerced back to a string.
	 * Returns null when the sequence argument is already an internal dispatch variable
	 * (the inner call emitted by a previous wrap), so the compilers fall through to their
	 * native list compilation.
	 * @param cons the sort expression
	 * @return the wrapped expression, or null when the call needs no wrapping
	 */
	public static @Nullable LispVal wrapSortForStringSeq(LispCons cons) {
		return wrapSortForStringSeq(cons, true);
	}

	/**
	 * Like {@link #wrapSortForStringSeq(LispCons)}, but lets a backend drop the vector
	 * arm of the dispatch when no array can exist in this program (see
	 * {@code seqResultDispatchForm} and {@link #expandCoerce(LispCons, boolean)}).
	 * @param cons the sort expression
	 * @param arraysExist whether a general array can exist in this program
	 * @return the wrapped expression, or null when the call needs no wrapping
	 */
	public static @Nullable LispVal wrapSortForStringSeq(LispCons cons, boolean arraysExist) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2 || isSeqDispatchVar(parts.get(1))) {
			return null;
		}
		return seqResultDispatchForm(parts.get(1), lst -> {
			List<LispVal> inner = new java.util.ArrayList<>(parts);
			inner.set(1, lst);
			return listToCons(inner);
		}, arraysExist);
	}

	/**
	 * Wraps a {@code (reduce fn seq ...)} call so a string sequence folds over a list of
	 * its characters (the fold value itself is returned unchanged). Returns null when the
	 * sequence argument is already an internal dispatch variable (the inner call emitted
	 * by a previous wrap), so the compilers fall through to their native list
	 * compilation.
	 * @param cons the reduce expression
	 * @return the wrapped expression, or null when the call needs no wrapping
	 */
	public static @Nullable LispVal wrapReduceForStringSeq(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3 || isSeqDispatchVar(parts.get(2))) {
			return null;
		}
		List<LispVal> inner = new java.util.ArrayList<>(parts);
		inner.set(2, new LispSymbol(SEQ_LIST_VAR));
		return makeLet(SEQ_LIST_VAR, seqAsListForm(parts.get(2)), listToCons(inner));
	}

	private static final String REDUCE_FN_VAR = "__reduce_fn";

	private static final String REDUCE_A_VAR = "__reduce_a";

	private static final String REDUCE_B_VAR = "__reduce_b";

	/**
	 * Lowers the extended keyword forms of {@code reduce} -- {@code :from-end} (right
	 * fold) and {@code :key} (apply a selector to each element before folding) -- into
	 * the plain 2-arg / {@code :initial-value} builtin that every backend already
	 * compiles. Returns {@code null} when the call carries neither keyword (so a plain
	 * {@code (reduce fn seq)} or {@code (reduce fn seq :initial-value i)} falls through
	 * to the native reduce), which also leaves an unsupported/misplaced keyword to error
	 * in the native reduce.
	 *
	 * <p>
	 * Common Lisp right fold combines elements from the right with the accumulator on the
	 * RIGHT: {@code (reduce #'f '(a b c) :from-end t)} = {@code (f a (f b c))} and, with
	 * an initial value, {@code (f a (f b (f c i)))}. It is realized by reversing the
	 * (already {@code :key}-mapped) sequence and folding left with an argument-swapping
	 * wrapper, so the native left fold and the accumulator side stay correct.
	 * {@code :key} maps each element but NOT the initial value.
	 * @param cons the reduce expression
	 * @return the lowered plain-reduce form, or {@code null} when no lowering is needed
	 */
	public static @Nullable LispVal expandReduce(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3) {
			return null; // arity errors surface in the native reduce
		}
		LispVal keyForm = keywordValue(parts, 3, LispNames.KEY_KEYWORD);
		LispVal fromEndForm = keywordValue(parts, 3, LispNames.FROM_END_KEYWORD);
		LispVal startForm = keywordValue(parts, 3, LispNames.START_KEYWORD);
		LispVal endForm = keywordValue(parts, 3, LispNames.END_KEYWORD);
		// Lower whenever :from-end/:key/:start/:end is present at all -- even a nil
		// value must be stripped, since the native reduce rejects those keywords. A nil
		// value is treated as absent (:from-end nil = left fold, :key nil = identity,
		// :end nil = the whole sequence).
		if (keyForm == null && fromEndForm == null && startForm == null && endForm == null) {
			return null;
		}
		boolean hasKey = keyForm != null && !isNilForm(keyForm);
		boolean fromEnd = fromEndForm != null && !isNilForm(fromEndForm);
		LispVal fnForm = parts.get(1);
		LispVal seqForm = parts.get(2);
		LispVal initForm = keywordValue(parts, 3, LispNames.INITIAL_VALUE_KEYWORD);
		// :start/:end restrict the fold to a subsequence (subseq accepts a nil end).
		if (startForm != null || endForm != null) {
			seqForm = listToCons(List.of(new LispSymbol(LispNames.SUBSEQ), seqForm,
					startForm == null ? new LispInteger(0) : startForm, endForm == null ? LispNil.INSTANCE : endForm));
		}
		// :key maps every element (via mapcar, which leaves the initial value untouched;
		// a string sequence is coerced to its character list first, since mapcar is
		// list-only).
		LispVal seqExpr = hasKey
				? listToCons(List.of(new LispSymbol(LispNames.MAPCAR), keyForm, seqAsListForm(seqForm))) : seqForm;
		if (!fromEnd) {
			return buildPlainReduce(fnForm, seqExpr, initForm);
		}
		// Right fold: reverse the (mapped) sequence and swap the folding function's args
		// so
		// the accumulator stays on the right. Bind the function once to avoid
		// re-evaluating
		// the designator expression on every step.
		LispSymbol fnVar = new LispSymbol(REDUCE_FN_VAR);
		LispSymbol a = new LispSymbol(REDUCE_A_VAR);
		LispSymbol b = new LispSymbol(REDUCE_B_VAR);
		LispVal swapped = listToCons(List.of(new LispSymbol(LispNames.LAMBDA), listToCons(List.of(a, b)),
				listToCons(List.of(new LispSymbol(LispNames.FUNCALL), fnVar, b, a))));
		LispVal reversed = listToCons(List.of(new LispSymbol(LispNames.REVERSE), seqExpr));
		return makeLet(REDUCE_FN_VAR, fnForm, buildPlainReduce(swapped, reversed, initForm));
	}

	private static LispVal buildPlainReduce(LispVal fnForm, LispVal seqExpr, @Nullable LispVal initForm) {
		List<LispVal> reduceParts = new java.util.ArrayList<>();
		reduceParts.add(new LispSymbol(LispNames.REDUCE));
		reduceParts.add(fnForm);
		reduceParts.add(seqExpr);
		if (initForm != null) {
			reduceParts.add(new LispSymbol(LispNames.INITIAL_VALUE_KEYWORD));
			reduceParts.add(initForm);
		}
		return listToCons(reduceParts);
	}

	/**
	 * Expands {@code (copy-seq seq)} to {@code (subseq seq 0)}: subseq already returns a
	 * fresh sequence of the argument's kind (list or string; arrays are not sequences
	 * here, matching subseq).
	 * @param cons the copy-seq expression
	 * @return the expanded expression
	 */
	public static LispVal expandCopySeq(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException(LispNames.COPY_SEQ + " expects 1 argument: " + cons.print());
		}
		return listToCons(List.of(new LispSymbol(LispNames.SUBSEQ), parts.get(1), new LispInteger(0)));
	}

	/**
	 * Expands {@code (vectorp x)} to {@code (let ((__vecp x)) (or (stringp __vecp)
	 * (%arrayp __vecp)))}: strings are vectors in CL. Like the {@code vector} type
	 * specifier in {@code makeTypeTest}, the rank is NOT checked (a rank-n array passes
	 * too) so the gated array helpers stay out of programs that only ask the question.
	 * @param cons the vectorp expression
	 * @return the expanded expression
	 */
	/**
	 * Expands {@code (arrayp x)} to {@code (or (stringp x) (%arrayp x))}: a string is an
	 * array in Common Lisp, and the internal predicate answers only for the array
	 * representation.
	 * @param cons the arrayp expression
	 * @return the expanded expression
	 */
	/**
	 * Expands {@code (open-stream-p x)} to {@code (if x t nil)} -- the lite answer for a
	 * backend with no per-stream open/closed record (Preview 1 WASM, and a component
	 * program that never spliced the sockets library). The socket case is exact: the
	 * component rewrite redirects this call to the sockets library's table-backed
	 * dispatch defun before compilation.
	 * @param cons the open-stream-p expression
	 * @return the expanded expression
	 */
	public static LispVal expandOpenStreamPLite(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException(LispNames.OPEN_STREAM_P + " expects 1 argument: " + cons.print());
		}
		return listToCons(List.of(new LispSymbol(LispNames.IF), parts.get(1), LispTrue.INSTANCE, LispNil.INSTANCE));
	}

	/**
	 * Expands {@code (arrayp x)} to {@code (or (stringp x) (%arrayp x))} over a let-bound
	 * temporary, so the argument is evaluated once. A string is an array in CL but is not
	 * one of the array representations {@link am.ik.rontolisp.LispNames#ARRAYP_INTERNAL}
	 * knows, hence the two-part test.
	 * @param cons the arrayp expression
	 * @return the expanded expression
	 */
	public static LispVal expandArrayp(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException(LispNames.ARRAYP + " expects 1 argument: " + cons.print());
		}
		LispSymbol v = new LispSymbol("__arrp");
		LispVal test = listToCons(List.of(new LispSymbol(LispNames.OR), callOf(LispNames.STRINGP, v),
				callOf(LispNames.ARRAYP_INTERNAL, v)));
		return makeLet(v.name(), parts.get(1), test);
	}

	/**
	 * Expands {@code (vectorp x)} the same way {@link #expandArrayp(LispCons)} expands
	 * {@code arrayp}: strings count, and the argument is let-bound so the two-part test
	 * evaluates it once.
	 * @param cons the vectorp expression
	 * @return the expanded expression
	 */
	public static LispVal expandVectorp(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException(LispNames.VECTORP + " expects 1 argument: " + cons.print());
		}
		LispSymbol v = new LispSymbol("__vecp");
		LispVal test = listToCons(List.of(new LispSymbol(LispNames.OR), callOf(LispNames.STRINGP, v),
				callOf(LispNames.ARRAYP_INTERNAL, v)));
		return makeLet(v.name(), parts.get(1), test);
	}

	/**
	 * Expands {@code (stable-sort seq predicate [:key fn])} into a
	 * decorate/{@code sort}/undecorate scan: each element is decorated as
	 * {@code (key-value index . element)}, the decorated list is sorted with the
	 * predicate on key values tie-broken by the original index (which makes the result
	 * stable regardless of the underlying {@code sort} algorithm), and the elements are
	 * extracted back out. Lite: the result is always a fresh list (a vector argument does
	 * not come back as a vector), matching the other sequence scans.
	 *
	 * <pre>
	 * (let* ((__ssort_pred predicate) (__ssort_key key) (__ssort_dec nil) (__ssort_idx 0))
	 *   (do ((__ssort_cur [seq-as-list seq] (cdr __ssort_cur)))
	 *       ((atom __ssort_cur) nil)
	 *     (setq __ssort_dec (cons (cons (funcall __ssort_key (car __ssort_cur))
	 *                                   (cons __ssort_idx (car __ssort_cur))) __ssort_dec))
	 *     (setq __ssort_idx (+ __ssort_idx 1)))
	 *   (mapcar (lambda (__ssort_e) (cdr (cdr __ssort_e)))
	 *           (sort __ssort_dec (lambda (__ssort_a __ssort_b) ...))))
	 * </pre>
	 * @param cons the stable-sort expression
	 * @return the expanded expression
	 */
	/**
	 * If a {@code sort} call carries keyword arguments ({@code :key}) beyond the sequence
	 * and predicate, rewrites it to {@code stable-sort} and expands that (a stable order
	 * is a valid {@code sort}; this is how {@code :key} is supported without a separate
	 * sort codegen path). Returns {@code null} for a plain two-argument
	 * {@code (sort seq pred)}, which keeps the existing string-sequence-aware path.
	 * @param cons the sort expression
	 * @return the {@code stable-sort} expansion, or {@code null} when there are no
	 * keyword arguments
	 */
	public static @Nullable LispVal expandSortWithKey(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() <= 3) {
			return null;
		}
		List<LispVal> stableParts = new ArrayList<>(parts);
		stableParts.set(0, new LispSymbol(LispNames.STABLE_SORT));
		return expandStableSort((LispCons) listToCons(stableParts));
	}

	/**
	 * Expands {@code (stable-sort sequence predicate [:key fn])} into a
	 * decorate-sort-undecorate over the sequence indices, so equal elements keep their
	 * original order (a stable sort) and an optional {@code :key} is applied once per
	 * element.
	 * @param cons the {@code stable-sort} expression
	 * @return the decorate-sort-undecorate expansion
	 */
	public static LispVal expandStableSort(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3) {
			throw new IllegalArgumentException(LispNames.STABLE_SORT + " expects a sequence and a predicate");
		}
		requireKeywords(LispNames.STABLE_SORT, parts, 3, LispNames.KEY_KEYWORD);
		LispVal keyForm = keywordValue(parts, 3, LispNames.KEY_KEYWORD);
		LispSymbol pred = new LispSymbol("__ssort_pred");
		LispSymbol key = new LispSymbol("__ssort_key");
		LispSymbol dec = new LispSymbol("__ssort_dec");
		LispSymbol idx = new LispSymbol("__ssort_idx");
		LispSymbol cur = new LispSymbol("__ssort_cur");
		LispSymbol a = new LispSymbol("__ssort_a");
		LispSymbol b = new LispSymbol("__ssort_b");
		LispSymbol e = new LispSymbol("__ssort_e");
		boolean hasKey = keyForm != null && !isNilForm(keyForm);
		// (cons (funcall key elem) (cons idx elem)) -- without :key the key value IS the
		// element.
		LispVal elem = callOf(LispNames.CAR, cur);
		LispVal keyed = hasKey ? listToCons(List.of(new LispSymbol(LispNames.FUNCALL), key, elem)) : elem;
		LispVal decorated = listToCons(List.of(new LispSymbol(LispNames.CONS), keyed,
				listToCons(List.of(new LispSymbol(LispNames.CONS), idx, elem))));
		LispVal accumulate = listToCons(List.of(new LispSymbol(LispNames.SETQ), dec,
				listToCons(List.of(new LispSymbol(LispNames.CONS), decorated, dec))));
		LispVal increment = listToCons(List.of(new LispSymbol(LispNames.SETQ), idx,
				listToCons(List.of(new LispSymbol(LispNames.ADD), idx, new LispInteger(1)))));
		LispVal bindings = listToCons(
				List.of(listToCons(List.of(cur, seqAsListForm(parts.get(1)), callOf(LispNames.CDR, cur)))));
		LispVal endClause = listToCons(List.of(callOf(LispNames.ATOM, cur), LispNil.INSTANCE));
		LispVal scan = expandDo((LispCons) listToCons(
				List.of(new LispSymbol(LispNames.DO), bindings, endClause, accumulate, increment)));
		// (lambda (a b) (if (pred (car a) (car b)) t
		// (if (pred (car b) (car a)) nil (< (cadr a) (cadr b)))))
		LispVal predAB = listToCons(
				List.of(new LispSymbol(LispNames.FUNCALL), pred, callOf(LispNames.CAR, a), callOf(LispNames.CAR, b)));
		LispVal predBA = listToCons(
				List.of(new LispSymbol(LispNames.FUNCALL), pred, callOf(LispNames.CAR, b), callOf(LispNames.CAR, a)));
		LispVal idxLt = listToCons(List.of(new LispSymbol(LispNames.LT),
				callOf(LispNames.CAR, callOf(LispNames.CDR, a)), callOf(LispNames.CAR, callOf(LispNames.CDR, b))));
		LispVal comparator = listToCons(List.of(new LispSymbol(LispNames.LAMBDA), listToCons(List.of(a, b)),
				makeIf(predAB, LispTrue.INSTANCE, makeIf(predBA, LispNil.INSTANCE, idxLt))));
		LispVal sorted = listToCons(List.of(new LispSymbol(LispNames.SORT), dec, comparator));
		LispVal undecorate = listToCons(List.of(new LispSymbol(LispNames.LAMBDA), listToCons(List.of(e)),
				callOf(LispNames.CDR, callOf(LispNames.CDR, e))));
		LispVal result = listToCons(List.of(new LispSymbol(LispNames.MAPCAR), undecorate, sorted));
		LispVal body = makeProgn(List.of(scan, result));
		result = makeLet(idx.name(), new LispInteger(0), body);
		result = makeLet(dec.name(), LispNil.INSTANCE, result);
		if (hasKey && keyForm != null) {
			result = makeLet(key.name(), keyForm, result);
		}
		return makeLet(pred.name(), parts.get(2), result);
	}

	private static LispVal makeProgn(List<LispVal> exprs) {
		List<LispVal> all = new java.util.ArrayList<>();
		all.add(new LispSymbol(LispNames.PROGN));
		all.addAll(exprs);
		return listToCons(all);
	}

	private static LispVal makeProg1(LispVal value, LispVal... rest) {
		List<LispVal> all = new java.util.ArrayList<>();
		all.add(new LispSymbol(LispNames.PROG1));
		all.add(value);
		all.addAll(List.of(rest));
		return listToCons(all);
	}

	private static LispVal makeNot(LispVal expr) {
		return listToCons(List.of(new LispSymbol(LispNames.NOT), expr));
	}

	/**
	 * Expands car/cdr composition functions into nested car/cdr calls.
	 *
	 * <pre>
	 * (cadr x)  -> (car (cdr x))
	 * (caddr x) -> (car (cdr (cdr x)))
	 * </pre>
	 * @param cons the car/cdr composition expression
	 * @return the expanded expression
	 */
	public static LispVal expandCarCdrComposition(LispCons cons) {
		List<LispVal> parts = cons.toList();
		String name = ((LispSymbol) parts.get(0)).name();
		LispVal arg = parts.get(1);
		// Process middle characters right to left
		for (int i = name.length() - 2; i >= 1; i--) {
			String op = (name.charAt(i) == 'A') ? LispNames.CAR : LispNames.CDR;
			arg = listToCons(List.of(new LispSymbol(op), arg));
		}
		return arg;
	}

	/**
	 * Expands (1+ x) into (+ x 1).
	 * @param cons the 1+ expression
	 * @return the expanded expression
	 */
	public static LispVal expandOnePlus(LispCons cons) {
		LispVal arg = cons.toList().get(1);
		return listToCons(List.of(new LispSymbol(LispNames.ADD), arg, new LispInteger(1)));
	}

	/**
	 * Expands (1- x) into (- x 1).
	 * @param cons the 1- expression
	 * @return the expanded expression
	 */
	public static LispVal expandOneMinus(LispCons cons) {
		LispVal arg = cons.toList().get(1);
		return listToCons(List.of(new LispSymbol(LispNames.SUB), arg, new LispInteger(1)));
	}

	/**
	 * Expands (zerop x) into (= x 0).
	 * @param cons the zerop expression
	 * @return the expanded expression
	 */
	public static LispVal expandZerop(LispCons cons) {
		LispVal arg = cons.toList().get(1);
		return listToCons(List.of(new LispSymbol(LispNames.EQ), arg, new LispInteger(0)));
	}

	/**
	 * Expands (plusp x) into {@code (> x 0)}.
	 * @param cons the plusp expression
	 * @return the expanded expression
	 */
	public static LispVal expandPlusp(LispCons cons) {
		LispVal arg = cons.toList().get(1);
		return listToCons(List.of(new LispSymbol(LispNames.GT), arg, new LispInteger(0)));
	}

	/**
	 * Expands (minusp x) into {@code (< x 0)}.
	 * @param cons the minusp expression
	 * @return the expanded expression
	 */
	public static LispVal expandMinusp(LispCons cons) {
		LispVal arg = cons.toList().get(1);
		return listToCons(List.of(new LispSymbol(LispNames.LT), arg, new LispInteger(0)));
	}

	/**
	 * Expands (evenp x) into (= (mod x 2) 0).
	 * @param cons the evenp expression
	 * @return the expanded expression
	 */
	public static LispVal expandEvenp(LispCons cons) {
		LispVal arg = cons.toList().get(1);
		LispVal modExpr = listToCons(List.of(new LispSymbol(LispNames.MOD), arg, new LispInteger(2)));
		return listToCons(List.of(new LispSymbol(LispNames.EQ), modExpr, new LispInteger(0)));
	}

	/**
	 * Expands (oddp x) into (not (= (mod x 2) 0)).
	 * @param cons the oddp expression
	 * @return the expanded expression
	 */
	public static LispVal expandOddp(LispCons cons) {
		LispVal arg = cons.toList().get(1);
		LispVal modExpr = listToCons(List.of(new LispSymbol(LispNames.MOD), arg, new LispInteger(2)));
		LispVal eqExpr = listToCons(List.of(new LispSymbol(LispNames.EQ), modExpr, new LispInteger(0)));
		return makeNot(eqExpr);
	}

	/**
	 * Expands (unless condition body...) into an if expression.
	 *
	 * <pre>
	 * (unless cond body)       -> (if cond nil body)
	 * (unless cond b1 b2...)   -> (if cond nil (progn b1 b2...))
	 * </pre>
	 * @param cons the unless expression
	 * @return the expanded expression
	 */
	public static LispVal expandUnless(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal condition = parts.get(1);
		List<LispVal> body = parts.subList(2, parts.size());
		if (body.size() == 1) {
			return makeIf(condition, LispNil.INSTANCE, body.get(0));
		}
		else {
			return makeIf(condition, LispNil.INSTANCE, makeProgn(body));
		}
	}

	/**
	 * Expands (first x) into (car x).
	 * @param cons the first expression
	 * @return the expanded expression
	 */
	public static LispVal expandFirst(LispCons cons) {
		LispVal arg = cons.toList().get(1);
		return listToCons(List.of(new LispSymbol(LispNames.CAR), arg));
	}

	/**
	 * Expands (rest x) into (cdr x).
	 * @param cons the rest expression
	 * @return the expanded expression
	 */
	public static LispVal expandRest(LispCons cons) {
		LispVal arg = cons.toList().get(1);
		return listToCons(List.of(new LispSymbol(LispNames.CDR), arg));
	}

	/**
	 * Expands (nth n list) into (car (nthcdr n list)).
	 * @param cons the nth expression
	 * @return the expanded expression
	 */
	public static LispVal expandNth(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal n = parts.get(1);
		LispVal list = parts.get(2);
		LispVal nthcdrExpr = listToCons(List.of(new LispSymbol(LispNames.NTHCDR), n, list));
		return listToCons(List.of(new LispSymbol(LispNames.CAR), nthcdrExpr));
	}

	/**
	 * Expands (second x) into (nth 1 x) -> (car (nthcdr 1 x)).
	 * @param cons the second expression
	 * @return the expanded expression
	 */
	public static LispVal expandSecond(LispCons cons) {
		LispVal arg = cons.toList().get(1);
		LispCons nthCons = listToCons(List.of(new LispSymbol(LispNames.NTH), new LispInteger(1), arg));
		return expandNth(nthCons);
	}

	/**
	 * Expands (third x) into (nth 2 x) -> (car (nthcdr 2 x)).
	 * @param cons the third expression
	 * @return the expanded expression
	 */
	public static LispVal expandThird(LispCons cons) {
		LispVal arg = cons.toList().get(1);
		LispCons nthCons = listToCons(List.of(new LispSymbol(LispNames.NTH), new LispInteger(2), arg));
		return expandNth(nthCons);
	}

	/**
	 * Expands (fourth x) into (nth 3 x) -> (car (nthcdr 3 x)).
	 * @param cons the fourth expression
	 * @return the expanded expression
	 */
	public static LispVal expandFourth(LispCons cons) {
		LispVal arg = cons.toList().get(1);
		LispCons nthCons = listToCons(List.of(new LispSymbol(LispNames.NTH), new LispInteger(3), arg));
		return expandNth(nthCons);
	}

	/**
	 * Expands (setf place value) into the appropriate mutation form.
	 *
	 * <pre>
	 * (setf x val)            -> (setq x val)
	 * (setf (car x) val)      -> (let ((__setf val)) (rplaca x __setf) __setf)
	 * (setf (cdr x) val)      -> (let ((__setf val)) (rplacd x __setf) __setf)
	 * (setf (nth n x) val)    -> (let ((__setf val)) (rplaca (nthcdr n x) __setf) __setf)
	 * (setf (first x) val)    -> same as (setf (car x) val)
	 * (setf (second x) val)   -> (let ((__setf val)) (rplaca (nthcdr 1 x) __setf) __setf)
	 * (setf (third x) val)    -> (let ((__setf val)) (rplaca (nthcdr 2 x) __setf) __setf)
	 * (setf (fourth x) val)   -> (let ((__setf val)) (rplaca (nthcdr 3 x) __setf) __setf)
	 * (setf (caXXXr x) val)   -> rplaca/rplacd on nested cdr chain
	 * </pre>
	 *
	 * Multiple place/value pairs assign sequentially, like several setf forms in a row:
	 * {@code (setf p1 v1 p2 v2)} -> {@code (progn (setf p1 v1) (setf p2 v2))}.
	 * @param cons the setf expression
	 * @return the expanded expression
	 */
	public static LispVal expandSetf(LispCons cons) {
		// The registry-less overload is the --no-gc backend's (and macroexpand-1's):
		// stringsExist=false keeps (setf (aref v i) x) a bare %aset there, since that
		// backend has no string values and no `stringp` to dispatch on.
		return expandSetf(cons, java.util.Map.of(), EMPTY_CLOS_REGISTRY, false);
	}

	/**
	 * Like {@link #expandSetf(LispCons)}, but additionally treats registered
	 * {@code defstruct} accessors as places: {@code (setf (point-x p) val)} expands like
	 * {@code (setf (nth <position> p) val)}. The evaluator and the compilers pass their
	 * accessor registry (built by {@link #expandDefstruct}) here; {@code push}/
	 * {@code pop}/{@code incf}/... expand into {@code setf} forms that are re-dispatched
	 * through the caller, so struct places work with them too.
	 * @param cons the setf expression
	 * @param structAccessors accessor name to 1-based slot position
	 * @return the expanded expression
	 */
	public static LispVal expandSetf(LispCons cons, java.util.Map<String, Integer> structAccessors) {
		return expandSetf(cons, structAccessors, EMPTY_CLOS_REGISTRY, true);
	}

	/**
	 * Like {@link #expandSetf(LispCons, java.util.Map)}, but additionally treats
	 * {@code (slot-value obj 'slot)} as a place through the CLOS class registry:
	 * {@code (setf (slot-value obj 'slot) val)} expands like
	 * {@code (setf (nth <position> obj) val)}.
	 * @param cons the setf expression
	 * @param structAccessors accessor name to 1-based slot position
	 * @param closRegistry the CLOS registry resolving slot-value places
	 * @return the expanded expression
	 */
	public static LispVal expandSetf(LispCons cons, java.util.Map<String, Integer> structAccessors,
			ClosRegistry closRegistry) {
		return expandSetf(cons, structAccessors, closRegistry, true);
	}

	/**
	 * The shared implementation. {@code stringsExist} tells whether the target has string
	 * values at all (false only for the {@code --no-gc} backend), which decides whether
	 * an {@code (setf (aref var i) v)} place gets its string dispatch.
	 */
	private static LispVal expandSetf(LispCons cons, java.util.Map<String, Integer> structAccessors,
			ClosRegistry closRegistry, boolean stringsExist) {
		List<LispVal> parts = cons.toList();
		if (parts.size() > 3) {
			if (parts.size() % 2 == 0) {
				throw new IllegalArgumentException("setf: odd number of arguments: " + cons.print());
			}
			List<LispVal> forms = new java.util.ArrayList<>();
			for (int i = 1; i < parts.size(); i += 2) {
				forms.add(expandSetf(
						(LispCons) listToCons(List.of(new LispSymbol(LispNames.SETF), parts.get(i), parts.get(i + 1))),
						structAccessors, closRegistry));
			}
			return makeProgn(forms);
		}
		LispVal place = parts.get(1);
		LispVal value = parts.get(2);
		// (setf (the TYPE place) val) -> (setf place val): the declaration is a no-op.
		while (place instanceof LispCons theCons && theCons.car() instanceof LispSymbol theSym
				&& LispNames.THE.equals(plainTypeName(theSym)) && theCons.toList().size() == 3) {
			place = theCons.toList().get(2);
		}
		// (setf x val) -> (setq x val)
		if (place instanceof LispSymbol) {
			return listToCons(List.of(new LispSymbol(LispNames.SETQ), place, value));
		}
		// (setf (accessor ...) val)
		if (place instanceof LispCons placeCons) {
			List<LispVal> placeParts = placeCons.toList();
			String accessor = ((LispSymbol) placeParts.get(0)).name();
			return switch (accessor) {
				// (setf (documentation 'name 'doc-type) "...") -> the docstring value:
				// docstrings are not stored anywhere (lite, matching the nil reader).
				case LispNames.DOCUMENTATION -> value;
				// (setf (symbol-function 'f) fn) / (setf (fdefinition 'f) fn): install
				// fn as f's global function binding in the runtime function namespace
				// (the write-side twin of fmakunbound's tombstone); the primitive
				// returns fn, the setf value.
				case LispNames.SYMBOL_FUNCTION, LispNames.FDEFINITION -> listToCons(
						List.of(new LispSymbol(LispNames.SET_SYMBOL_FUNCTION_INTERNAL), placeParts.get(1), value));
				case LispNames.CAR, LispNames.FIRST -> expandSetfWithRplaca(placeParts.get(1), value);
				case LispNames.CDR, LispNames.REST -> expandSetfWithRplacd(placeParts.get(1), value);
				case LispNames.GETHASH ->
					// (setf (gethash key table [default]) val) -> (%puthash key table
					// val).
					// The optional default in the place is only used by gethash in read
					// position, so it is dropped here.
					listToCons(List.of(new LispSymbol(LispNames.PUTHASH), placeParts.get(1), placeParts.get(2), value));
				case LispNames.AREF, LispNames.SVREF -> {
					// (setf (aref array sub...) val) -> (%aset array sub... val);
					// svref is aref restricted to one subscript, so it shares the place.
					List<LispVal> asetParts = new java.util.ArrayList<>();
					asetParts.add(new LispSymbol(LispNames.ASET));
					for (int i = 1; i < placeParts.size(); i++) {
						asetParts.add(placeParts.get(i));
					}
					asetParts.add(value);
					LispVal aset = listToCons(asetParts);
					if (stringsExist && placeParts.size() == 3 && placeParts.get(1) instanceof LispSymbol arrayVar) {
						// A STRING is a rank-1 character array, so (setf (aref s i) c) is
						// legal CL -- and `s` may be a string OR an array at run time
						// (ironclad's byte-array-to-hex-string fills a make-string buffer
						// this way). Dispatch: %aset for an array, the schar-set rebuild
						// for a string. Only a variable place can take the string branch
						// (see expandScharSetFunctional's lite semantics).
						yield makeIf(
								callOf(LispNames.STRINGP, arrayVar), listToCons(List
									.of(new LispSymbol(LispNames.SCHAR_SET), arrayVar, placeParts.get(2), value)),
								aset);
					}
					yield aset;
				}
				case LispNames.GETF -> {
					// (setf (getf place indicator [default]) value): CL's plist place.
					// The
					// indicator either already has a cell -- then the VALUE cell is
					// rplaca'd, so an alias of the same list sees the update -- or the
					// pair
					// is consed onto the front and stored back through `place`. The
					// optional default is read by getf only and is dropped here (the
					// gethash place does the same).
					//
					// Lowered inline rather than onto a runtime helper: the expansion
					// happens during expression compilation, long after the pass that
					// splices prelude defuns, so a synthesized call to one would never be
					// resolved. `place` is evaluated twice (the search and the
					// push-back);
					// for the variable place every caller uses that is free.
					if (placeParts.size() < 3) {
						throw new IllegalArgumentException("setf getf expects (getf place indicator): " + cons.print());
					}
					LispVal plistPlace = placeParts.get(1);
					LispSymbol indVar = new LispSymbol("__setf_getf_ind");
					LispSymbol valVar = new LispSymbol("__setf_getf_val");
					LispSymbol cellVar = new LispSymbol("__setf_getf_cell");
					LispSymbol walkVar = new LispSymbol("__setf_getf_tail");
					// (do ((tail place (cddr tail))) ((or (null tail) (eq (car tail)
					// ind))
					// tail))
					LispVal walk = expandDo((LispCons) listToCons(List
						.of(new LispSymbol(LispNames.DO),
								listToCons(List
									.of(listToCons(List.of(walkVar, plistPlace, callOf(CDDR_COMPOSITION, walkVar))))),
								listToCons(List.of(
										listToCons(
												List.of(new LispSymbol(LispNames.OR), callOf(LispNames.NULL, walkVar),
														listToCons(List.of(new LispSymbol(LispNames.EQ_GENERAL),
																callOf(LispNames.CAR, walkVar), indVar)))),
										walkVar)))));
					LispVal update = makeProgn(List.of(
							listToCons(
									List.of(new LispSymbol(LispNames.RPLACA), callOf(LispNames.CDR, cellVar), valVar)),
							valVar));
					LispVal pushed = listToCons(List.of(new LispSymbol(LispNames.CONS), indVar,
							listToCons(List.of(new LispSymbol(LispNames.CONS), valVar, plistPlace))));
					LispVal store = makeProgn(List.of(expandSetf(
							(LispCons) listToCons(List.of(new LispSymbol(LispNames.SETF), plistPlace, pushed)),
							structAccessors, closRegistry, stringsExist), valVar));
					yield makeLet(indVar.name(), placeParts.get(2), makeLet(valVar.name(), value,
							makeLet(cellVar.name(), walk, makeIf(cellVar, update, store))));
				}
				case LispNames.ROW_MAJOR_AREF ->
					// (setf (row-major-aref array k) val) -> (%row-major-aset array k
					// val).
					listToCons(List.of(new LispSymbol(LispNames.ROW_MAJOR_ASET), placeParts.get(1), placeParts.get(2),
							value));
				case LispNames.VEC_QUALIFIED_AREF ->
					// (setf (vec:aref v i) val) -> (vec:aset v i val). vec:aset
					// returns
					// the stored value, so it already satisfies setf's value semantics
					// (as
					// %aset does for aref).
					listToCons(List.of(new LispSymbol(LispNames.VEC_QUALIFIED_ASET), placeParts.get(1),
							placeParts.get(2), value));
				case LispNames.ELT -> {
					// (setf (elt seq i) val): elt reads from lists, arrays AND strings,
					// so
					// the place dispatches at run time -- rplaca into the nthcdr cell of
					// a
					// list, the schar-set rebuild for a string, %aset for an array. The
					// string arm is the same one (setf (aref s i) v) has above, and
					// carries
					// the same lite restriction: only a VARIABLE place can take it,
					// because
					// the rebuild of an immutable string setq's the result back into the
					// place. So a variable place is dispatched on the variable itself
					// (evaluating a symbol twice is free, and only one arm ever runs);
					// any
					// other place expression is bound to a temp and keeps the two-way
					// list/array dispatch it always had.
					LispSymbol idxVar = new LispSymbol("__setf_idx");
					LispSymbol valVar = new LispSymbol(SETF_VAR);
					boolean varPlace = stringsExist && placeParts.get(1) instanceof LispSymbol;
					LispSymbol seqVar = varPlace ? (LispSymbol) placeParts.get(1) : new LispSymbol("__setf_seq");
					LispVal listSet = listToCons(List.of(new LispSymbol(LispNames.RPLACA),
							listToCons(List.of(new LispSymbol(LispNames.NTHCDR), idxVar, seqVar)), valVar));
					LispVal arraySet = listToCons(List.of(new LispSymbol(LispNames.ASET), seqVar, idxVar, valVar));
					LispVal nonList = varPlace ? makeIf(callOf(LispNames.STRINGP, seqVar),
							listToCons(List.of(new LispSymbol(LispNames.SCHAR_SET), seqVar, idxVar, valVar)), arraySet)
							: arraySet;
					LispVal dispatch = makeIf(callOf(LispNames.CONSP, seqVar), listSet, nonList);
					LispVal body = makeLet(idxVar.name(), placeParts.get(2),
							makeLet(valVar.name(), value, makeProgn(List.of(dispatch, valVar))));
					yield varPlace ? body : makeLet(seqVar.name(), placeParts.get(1), body);
				}
				case LispNames.FILL_POINTER ->
					// (setf (fill-pointer vector) val) -> (%set-fill-pointer vector val).
					listToCons(List.of(new LispSymbol(LispNames.SET_FILL_POINTER), placeParts.get(1), value));
				case LispNames.VALUES -> {
					// (setf (values p1 ... pn) form) -> bind the form's values to temps,
					// then setf each place in order. Lite: yields the first value.
					List<LispVal> tmps = new java.util.ArrayList<>();
					for (int i = 1; i < placeParts.size(); i++) {
						tmps.add(new LispSymbol("__setf_mv" + (i - 1)));
					}
					List<LispVal> mvb = new java.util.ArrayList<>();
					mvb.add(new LispSymbol(LispNames.MULTIPLE_VALUE_BIND));
					mvb.add(tmps.isEmpty() ? LispNil.INSTANCE : listToCons(tmps));
					mvb.add(value);
					for (int i = 1; i < placeParts.size(); i++) {
						mvb.add(listToCons(
								List.of(new LispSymbol(LispNames.SETF), placeParts.get(i), tmps.get(i - 1))));
					}
					mvb.add(tmps.isEmpty() ? LispNil.INSTANCE : tmps.get(0));
					yield listToCons(mvb);
				}
				case LispNames.SCHAR, LispNames.CHAR ->
					// (setf (schar s i) c) / (setf (char s i) c) -> (%schar-set s i c):
					// in-place string mutation returning the stored character.
					listToCons(
							List.of(new LispSymbol(LispNames.SCHAR_SET), placeParts.get(1), placeParts.get(2), value));
				case LispNames.SUBSEQ -> {
					// (setf (subseq seq start [end]) val) -> replace in place; copies
					// min(len(val), end-start) elements like CL, returns val. Subforms
					// are hoisted so evaluation order stays place-then-value.
					LispSymbol seqVar = new LispSymbol("__setf_ss");
					LispSymbol startVar = new LispSymbol("__setf_ss_start");
					LispSymbol endVar = new LispSymbol("__setf_ss_end");
					LispSymbol valVar = new LispSymbol(SETF_VAR);
					LispVal replaceCall = listToCons(List.of(new LispSymbol(LispNames.REPLACE), seqVar, valVar,
							new LispSymbol(":START1"), startVar, new LispSymbol(":END1"), endVar));
					LispVal endInit = placeParts.size() > 3 ? placeParts.get(3) : LispNil.INSTANCE;
					yield makeLet(seqVar.name(), placeParts.get(1),
							makeLet(startVar.name(), placeParts.get(2), makeLet(endVar.name(), endInit,
									makeLet(valVar.name(), value, makeProgn(List.of(replaceCall, valVar))))));
				}
				case LispNames.LDB -> {
					// (setf (ldb bytespec place) val) -> (setf place (dpb val bytespec
					// place)), returning val (the new byte). The bytespec and value hoist
					// to temps so each evaluates once; the inner setf recursion handles
					// the place (a variable in the cl-postgres integer readers).
					LispSymbol specVar = new LispSymbol("__setf_ldb_spec");
					LispSymbol valVar = new LispSymbol("__setf_ldb_val");
					LispVal bytePlace = placeParts.get(2);
					LispVal dpbCall = listToCons(List.of(new LispSymbol(LispNames.DPB), valVar, specVar, bytePlace));
					LispVal inner = listToCons(List.of(new LispSymbol(LispNames.SETF), bytePlace, dpbCall));
					yield makeLet(specVar.name(), placeParts.get(1),
							makeLet(valVar.name(), value, makeProgn(List.of(inner, valVar))));
				}
				case LispNames.SLOT_VALUE -> {
					// (setf (slot-value obj 'slot) val) -> (%obj-set obj <index> val):
					// the index comes from the CLOS class registry.
					LispSymbol litSlot = placeParts.size() == 3 ? quotedSymbol(placeParts.get(2)) : null;
					if (litSlot == null && placeParts.size() == 3) {
						// A runtime slot name: the write-side twin of the runtime-name
						// read -- one shared dispatch defun on the compile paths
						// (runtimeSlotValueSetDefuns), a native builtin on the
						// interpreter. Argument order keeps place subforms ahead of the
						// value, like every other setf expansion.
						yield mvCall(LispNames.SLOT_VALUE_SET_RUNTIME, placeParts.get(1), placeParts.get(2), value);
					}
					if (litSlot != null && ambiguousSlotPosition(litSlot, closRegistry)) {
						// The name sits at different indexes in unrelated types, so no
						// one
						// index can be baked: dispatch on the instance TAG, the
						// write-side
						// twin of the ambiguous READ dispatch. (Routing through the
						// reader
						// generic would only work when the class declares an :accessor.)
						yield expandAmbiguousSlotSet(placeParts.get(1), litSlot, value, closRegistry);
					}
					// The RAW read: a write must reach the %obj-ref place, and storing
					// into
					// an unbound slot is legal (that is how it becomes bound).
					LispVal expandedPlace = expandSlotValueRaw(placeCons, closRegistry);
					yield expandSetf(
							(LispCons) listToCons(List.of(new LispSymbol(LispNames.SETF), expandedPlace, value)),
							structAccessors, closRegistry);
				}
				case LispNames.OBJ_REF ->
					// (setf (%obj-ref obj k) val) -> (%obj-set obj k val). The read
					// primitive is a place in its own right, so every expansion that
					// lowers a slot read -- slot-value, with-slots, a struct accessor --
					// composes with setf/push/incf without a case of its own.
					objSet(placeParts.get(1), (int) ((LispInteger) placeParts.get(2)).value(), value);
				case LispNames.NTH -> {
					// (setf (nth n x) val) -> (let ((__setf val)) (rplaca (nthcdr n x)
					// __setf) __setf)
					LispVal n = placeParts.get(1);
					LispVal list = placeParts.get(2);
					LispVal nthcdrExpr = listToCons(List.of(new LispSymbol(LispNames.NTHCDR), n, list));

					yield expandSetfWithRplaca(nthcdrExpr, value);
				}
				case LispNames.SECOND ->

				{
					LispVal nthcdrExpr = listToCons(
							List.of(new LispSymbol(LispNames.NTHCDR), new LispInteger(1), placeParts.get(1)));

					yield expandSetfWithRplaca(nthcdrExpr, value);
				}
				case LispNames.THIRD ->

				{
					LispVal nthcdrExpr = listToCons(
							List.of(new LispSymbol(LispNames.NTHCDR), new LispInteger(2), placeParts.get(1)));

					yield expandSetfWithRplaca(nthcdrExpr, value);
				}
				case LispNames.FOURTH ->

				{
					LispVal nthcdrExpr = listToCons(
							List.of(new LispSymbol(LispNames.NTHCDR), new LispInteger(3), placeParts.get(1)));

					yield expandSetfWithRplaca(nthcdrExpr, value);
				}
				default ->

				{
					Integer structSlot = structAccessors.get(accessor);
					if (structSlot != null) {
						if (structSlot == SETF_FUNCTION_MARKER) {
							// (setf (name args...) val) -> (funcall #'%setf-name val
							// args...):
							// the CL setf-function convention passes the new value as the
							// first
							// argument (it is the last required param of the setf lambda
							// list).
							List<LispVal> call = new java.util.ArrayList<>();
							call.add(new LispSymbol(LispNames.FUNCALL));
							call.add(listToCons(List.of(new LispSymbol(LispNames.FUNCTION),
									new LispSymbol(setfFunctionName(accessor)))));
							call.add(value);
							for (int i = 1; i < placeParts.size(); i++) {
								call.add(placeParts.get(i));
							}
							yield listToCons(call);
						}
						// (setf (point-x p) val) -> (%obj-set p <index> val)
						yield objSet(placeParts.get(1), structSlot - 1, value);
					}
					if (LispNames.isCarCdrComposition(accessor)) {

						yield expandSetfCarCdr(accessor, placeParts.get(1), value);
					}
					throw new UnsupportedOperationException("setf does not support place: " + accessor);
				}
			};
		}
		throw new UnsupportedOperationException("setf expects a symbol or accessor form as place");
	}

	/**
	 * The {@code cdr}-composition name the {@code setf getf} plist walk steps with; a
	 * car/cdr composition is recognized generically rather than being a named builtin.
	 */
	private static final String CDDR_COMPOSITION = "CDDR";

	private static final String SETF_VAR = "__setf";

	private static final String SETF_TARGET_VAR = "__setf_tgt";

	/**
	 * Registry marker (a struct-accessor "slot position") flagging a setf-function place
	 * rather than a defstruct slot. Slot positions are always 1-based (&gt;= 1), so a
	 * negative value is an unambiguous sentinel that lets {@code (defun (setf NAME) ...)}
	 * share the same {@code structAccessors} map that {@code expandSetf} already threads
	 * through every backend.
	 */
	public static final int SETF_FUNCTION_MARKER = -1;

	/**
	 * The variable a {@code (let ((*package* X)) ...)} binding is renamed to by
	 * {@link #normalizeBindingList}: the resolver's read-time {@code *package*}
	 * substitution leaves a quoted package in the binding-name slot, so the name is
	 * replaced with this marker. The interpreter's {@code evalLet} rebinds its runtime
	 * current package for the binding's extent.
	 */
	public static final String PACKAGE_REBIND_VAR = "__package_rebind";

	/**
	 * Internal function-namespace name for a {@code (setf NAME)} writer function.
	 * {@code (defun (setf html-mode) ...)} installs a plain defun under this mangled
	 * name, and {@code (setf (html-mode) v)} / {@code #'(setf html-mode)} resolve to it.
	 * @param placeName the accessor name in the {@code (setf NAME)} designator
	 * @return the mangled internal function name
	 */
	public static String setfFunctionName(String placeName) {
		return "%setf-" + placeName;
	}

	private static LispVal expandSetfWithRplaca(LispVal target, LispVal value) {
		// (let ((__setf_tgt target)) (let ((__setf value)) (rplaca __setf_tgt __setf)
		// __setf)) -- the place subform is evaluated BEFORE the value (CL evaluation
		// order; the tail-collection idiom (setf (cdr tail) (setf tail (list x)))
		// depends on the old tail being the rplacd target).
		LispVal rplacaExpr = listToCons(
				List.of(new LispSymbol(LispNames.RPLACA), new LispSymbol(SETF_TARGET_VAR), new LispSymbol(SETF_VAR)));
		LispVal body = makeProgn(List.of(rplacaExpr, new LispSymbol(SETF_VAR)));
		return makeLet(SETF_TARGET_VAR, target, makeLet(SETF_VAR, value, body));
	}

	private static LispVal expandSetfWithRplacd(LispVal target, LispVal value) {
		// (let ((__setf_tgt target)) (let ((__setf value)) (rplacd __setf_tgt __setf)
		// __setf)) -- see expandSetfWithRplaca for the evaluation order.
		LispVal rplacdExpr = listToCons(
				List.of(new LispSymbol(LispNames.RPLACD), new LispSymbol(SETF_TARGET_VAR), new LispSymbol(SETF_VAR)));
		LispVal body = makeProgn(List.of(rplacdExpr, new LispSymbol(SETF_VAR)));
		return makeLet(SETF_TARGET_VAR, target, makeLet(SETF_VAR, value, body));
	}

	private static LispVal expandSetfCarCdr(String accessor, LispVal arg, LispVal value) {
		// e.g. (setf (cadr x) val) -> (setf (car (cdr x)) val)
		// The outermost operation (first char after 'c') determines rplaca vs rplacd
		// The remaining inner operations build the target expression
		char outerOp = accessor.charAt(1);
		// Build the inner chain: characters from index 2 to len-2 (right to left)
		LispVal target = arg;
		for (int i = accessor.length() - 2; i >= 2; i--) {
			String op = (accessor.charAt(i) == 'A') ? LispNames.CAR : LispNames.CDR;
			target = listToCons(List.of(new LispSymbol(op), target));
		}
		if (outerOp == 'A') {
			return expandSetfWithRplaca(target, value);
		}
		else {
			return expandSetfWithRplacd(target, value);
		}
	}

	/**
	 * Expands (push item place) into a let/setf/cons expression.
	 *
	 * <pre>
	 * (push item place) -> (let ((__push_item item)) (setf place (cons __push_item place)))
	 * </pre>
	 * @param cons the push expression
	 * @return the expanded expression
	 */
	public static LispVal expandPush(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal item = parts.get(1);
		LispVal place = parts.get(2);
		// (cons __push_item place)
		LispVal consExpr = listToCons(List.of(new LispSymbol(LispNames.CONS), new LispSymbol(PUSH_VAR), place));
		// (setf place (cons __push_item place))
		LispVal setfExpr = listToCons(List.of(new LispSymbol(LispNames.SETF), place, consExpr));
		return makeLet(PUSH_VAR, item, setfExpr);
	}

	private static final String PUSH_VAR = "__push_item";

	/**
	 * Expands (pushnew item place [args...]) into a member-guarded push. Extra arguments
	 * ({@code :test}/{@code :key}) are passed through to {@code member}. Like
	 * {@code push}, the place may be evaluated more than once.
	 *
	 * <pre>
	 * (pushnew item place) ->
	 *   (let ((__push_item item))
	 *     (if (member __push_item place) place (setf place (cons __push_item place))))
	 * </pre>
	 *
	 * A literal quoted-list place is a no-op returning the list unchanged: the one
	 * real-world shape is {@code (pushnew :my-feature *features*)}, where the reader has
	 * already substituted {@code *features*} with its quoted feature list -- the feature
	 * set is fixed at read time, so a runtime registration cannot take effect anyway.
	 * @param cons the pushnew expression
	 * @return the expanded expression
	 */
	public static LispVal expandPushnew(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3) {
			throw new IllegalArgumentException("pushnew expects an item and a place: " + cons.print());
		}
		LispVal item = parts.get(1);
		LispVal place = parts.get(2);
		if (place instanceof LispCons placeCons && placeCons.car() instanceof LispSymbol quoteOp
				&& LispNames.QUOTE.equals(quoteOp.name())) {
			return makeProgn(List.of(item, place));
		}
		List<LispVal> memberParts = new java.util.ArrayList<>();
		memberParts.add(new LispSymbol(LispNames.MEMBER));
		memberParts.add(new LispSymbol(PUSH_VAR));
		memberParts.add(place);
		memberParts.addAll(parts.subList(3, parts.size()));
		LispVal consExpr = listToCons(List.of(new LispSymbol(LispNames.CONS), new LispSymbol(PUSH_VAR), place));
		LispVal setfExpr = listToCons(List.of(new LispSymbol(LispNames.SETF), place, consExpr));
		return makeLet(PUSH_VAR, item, makeIf(listToCons(memberParts), place, setfExpr));
	}

	/**
	 * Expands (pop place) into a prog1 expression: save the head, advance the place, and
	 * return the saved head.
	 *
	 * <pre>
	 * (pop place) -> (prog1 (car place) (setf place (cdr place)))
	 * </pre>
	 * @param cons the pop expression
	 * @return the expanded expression
	 */
	public static LispVal expandPop(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal place = parts.get(1);
		// (car place)
		LispVal carExpr = listToCons(List.of(new LispSymbol(LispNames.CAR), place));
		// (cdr place)
		LispVal cdrExpr = listToCons(List.of(new LispSymbol(LispNames.CDR), place));
		// (setf place (cdr place))
		LispVal setfExpr = listToCons(List.of(new LispSymbol(LispNames.SETF), place, cdrExpr));
		// (prog1 (car place) (setf place (cdr place)))
		LispCons prog1Expr = (LispCons) listToCons(List.of(new LispSymbol(LispNames.PROG1), carExpr, setfExpr));
		return expandProg1(prog1Expr);
	}

	/**
	 * Expands (remf place indicator) into conditional setf/%remf-tail expression.
	 *
	 * <pre>
	 * (remf place indicator) ->
	 * (let ((__plist place))
	 *   (if (null __plist) nil
	 *     (let ((__indicator indicator))
	 *       (if (eq (car __plist) __indicator)
	 *         (progn (setf place (cdr (cdr __plist))) t)
	 *         (%remf-tail __plist __indicator)))))
	 * </pre>
	 * @param cons the remf expression
	 * @return the expanded expression
	 */
	public static LispVal expandRemf(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal place = parts.get(1);
		LispVal indicator = parts.get(2);
		LispSymbol plistSym = new LispSymbol(REMF_PLIST_VAR);
		LispSymbol indSym = new LispSymbol(REMF_IND_VAR);
		// (car __plist)
		LispVal carPlist = listToCons(List.of(new LispSymbol(LispNames.CAR), plistSym));
		// (eq (car __plist) __indicator)
		LispVal eqExpr = listToCons(List.of(new LispSymbol(LispNames.EQ_GENERAL), carPlist, indSym));
		// (cdr (cdr __plist))
		LispVal cddrPlist = listToCons(
				List.of(new LispSymbol(LispNames.CDR), listToCons(List.of(new LispSymbol(LispNames.CDR), plistSym))));
		// (setf place (cdr (cdr __plist)))
		LispVal setfExpr = listToCons(List.of(new LispSymbol(LispNames.SETF), place, cddrPlist));
		// (progn (setf place (cdr (cdr __plist))) t)
		LispVal headMatch = makeProgn(List.of(setfExpr, LispTrue.INSTANCE));
		// (%remf-tail __plist __indicator)
		LispVal tailCall = listToCons(List.of(new LispSymbol(LispNames.REMF_TAIL), plistSym, indSym));
		// (if (eq (car __plist) __indicator) headMatch tailCall)
		LispVal innerIf = makeIf(eqExpr, headMatch, tailCall);
		// (let ((__indicator indicator)) innerIf)
		LispVal innerLet = makeLet(REMF_IND_VAR, indicator, innerIf);
		// (null __plist)
		LispVal nullCheck = listToCons(List.of(new LispSymbol(LispNames.NULL), plistSym));
		// (if (null __plist) nil innerLet)
		LispVal outerIf = makeIf(nullCheck, LispNil.INSTANCE, innerLet);
		return makeLet(REMF_PLIST_VAR, place, outerIf);
	}

	private static final String REMF_PLIST_VAR = "__plist";

	private static final String REMF_IND_VAR = "__indicator";

	/**
	 * Expands (defun name (params...) body...) into (setq name (lambda (params...)
	 * body...)).
	 *
	 * <pre>
	 * (defun f (x y) body1 body2) -> (setq f (lambda (x y) body1 body2))
	 * </pre>
	 * @param cons the defun expression
	 * @return the expanded expression
	 */
	/**
	 * Expands (let* ((x 1) (y x)) body...) into nested let forms so each binding sees the
	 * previous ones.
	 *
	 * <pre>
	 * (let* () body...)                -> (let () body...)
	 * (let* ((x 1) (y x)) body...)    -> (let ((x 1)) (let ((y x)) body...))
	 * </pre>
	 * @param cons the let* expression
	 * @return the expanded expression
	 */
	public static LispVal expandLetStar(LispCons cons) {
		List<LispVal> parts = cons.toList();
		// A bare symbol entry is an init-less binding to nil.
		LispVal bindings = normalizeBindingList(parts.get(1));
		List<LispVal> body = parts.subList(2, parts.size());
		if (!(bindings instanceof LispCons bindingsCons)) {
			// (let* () body...) -> (let () body...)
			List<LispVal> letParts = new java.util.ArrayList<>();
			letParts.add(new LispSymbol(LispNames.LET));
			letParts.add(LispNil.INSTANCE);
			letParts.addAll(body);
			return listToCons(letParts);
		}
		List<LispVal> bindingList = bindingsCons.toList();
		// Build from the innermost let outward
		List<LispVal> innerParts = new java.util.ArrayList<>();
		innerParts.add(new LispSymbol(LispNames.LET));
		innerParts.add(new LispCons(bindingList.get(bindingList.size() - 1), LispNil.INSTANCE));
		innerParts.addAll(body);
		LispVal result = listToCons(innerParts);
		for (int i = bindingList.size() - 2; i >= 0; i--) {
			result = listToCons(
					List.of(new LispSymbol(LispNames.LET), new LispCons(bindingList.get(i), LispNil.INSTANCE), result));
		}
		return result;
	}

	/**
	 * Expands (dolist (var list result?) body...) into a let/while loop.
	 *
	 * <pre>
	 * (dolist (x lst r) body...) ->
	 *   (let ((__dolist lst))
	 *     (while (consp __dolist)
	 *       (let ((x (car __dolist))) body...)
	 *       (setq __dolist (cdr __dolist)))
	 *     (let ((x nil)) r))
	 * </pre>
	 * @param cons the dolist expression
	 * @return the expanded expression
	 */
	public static LispVal expandDolist(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispCons spec = (LispCons) parts.get(1);
		List<LispVal> specParts = spec.toList();
		LispVal var = specParts.get(0);
		LispVal listForm = specParts.get(1);
		LispVal resultForm = (specParts.size() > 2) ? specParts.get(2) : LispNil.INSTANCE;
		List<LispVal> body = parts.subList(2, parts.size());
		LispSymbol cursor = new LispSymbol(DOLIST_CURSOR_VAR);
		// (setq __dolist (cdr __dolist))
		LispVal step = listToCons(List.of(new LispSymbol(LispNames.SETQ), cursor, callOf(LispNames.CDR, cursor)));
		// (while (consp __dolist) iteration? step); the iteration let is omitted for an
		// empty body (a body-less let does not compile)
		List<LispVal> whileParts = new java.util.ArrayList<>();
		whileParts.add(new LispSymbol(LispNames.WHILE));
		whileParts.add(callOf(LispNames.CONSP, cursor));
		if (!body.isEmpty()) {
			// (let ((var (car __dolist))) body...)
			List<LispVal> iterParts = new java.util.ArrayList<>();
			iterParts.add(new LispSymbol(LispNames.LET));
			iterParts.add(new LispCons(listToCons(List.of(var, callOf(LispNames.CAR, cursor))), LispNil.INSTANCE));
			iterParts.addAll(body);
			whileParts.add(listToCons(iterParts));
		}
		whileParts.add(step);
		LispVal whileExpr = listToCons(whileParts);
		// (let ((var nil)) result) -- CL evaluates the result form with var bound to nil
		LispVal resultExpr = listToCons(List.of(new LispSymbol(LispNames.LET),
				new LispCons(listToCons(List.of(var, LispNil.INSTANCE)), LispNil.INSTANCE), resultForm));
		// (let ((__dolist list)) while-expr result-expr), wrapped in a return boundary.
		LispVal bindings = new LispCons(listToCons(List.of(cursor, listForm)), LispNil.INSTANCE);
		return makeBlock(listToCons(List.of(new LispSymbol(LispNames.LET), bindings, whileExpr, resultExpr)));
	}

	/**
	 * Expands (incf place delta?) into (setf place (+ place delta)).
	 * @param cons the incf expression
	 * @return the expanded expression
	 */
	public static LispVal expandIncf(LispCons cons) {
		return expandIncfDecf(cons, LispNames.ADD);
	}

	/**
	 * Expands (decf place delta?) into (setf place (- place delta)).
	 * @param cons the decf expression
	 * @return the expanded expression
	 */
	public static LispVal expandDecf(LispCons cons) {
		return expandIncfDecf(cons, LispNames.SUB);
	}

	private static LispVal expandIncfDecf(LispCons cons, String op) {
		List<LispVal> parts = cons.toList();
		LispVal place = parts.get(1);
		LispVal delta = (parts.size() > 2) ? parts.get(2) : new LispInteger(1);
		LispVal newValue = listToCons(List.of(new LispSymbol(op), place, delta));
		return listToCons(List.of(new LispSymbol(LispNames.SETF), place, newValue));
	}

	/**
	 * Expands (length lst) into a reduce-based count so all backends compile it through
	 * existing primitives.
	 *
	 * <pre>
	 * (length lst) -> (reduce (lambda (__acc __x) (+ __acc 1)) lst :initial-value 0)
	 * </pre>
	 * @param cons the length expression
	 * @return the expanded expression
	 */
	public static LispVal expandLength(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispSymbol acc = new LispSymbol("__length_acc");
		LispSymbol x = new LispSymbol("__length_x");
		LispVal lambda = listToCons(List.of(new LispSymbol(LispNames.LAMBDA), listToCons(List.of(acc, x)),
				listToCons(List.of(new LispSymbol(LispNames.ADD), acc, new LispInteger(1)))));
		return listToCons(List.of(new LispSymbol(LispNames.REDUCE), lambda, parts.get(1),
				new LispSymbol(LispNames.INITIAL_VALUE_KEYWORD), new LispInteger(0)));
	}

	/**
	 * Expands (reverse seq) into a reduce-based reversal wrapped in the string dispatch:
	 * a string reverses as a list of its characters and is coerced back to a string.
	 *
	 * <pre>
	 * (reverse lst) -> (reduce (lambda (__acc __x) (cons __x __acc)) lst :initial-value nil)
	 * </pre>
	 * @param cons the reverse expression
	 * @return the expanded expression
	 */
	public static LispVal expandReverse(LispCons cons) {
		return expandReverse(cons, true);
	}

	/**
	 * Like {@link #expandReverse(LispCons)}, but lets a backend drop the vector arm of
	 * the dispatch when no array can exist in this program (see
	 * {@code seqResultDispatchForm} and {@link #expandCoerce(LispCons, boolean)}).
	 * @param cons the reverse expression
	 * @param arraysExist whether a general array can exist in this program
	 * @return the expanded expression
	 */
	public static LispVal expandReverse(LispCons cons, boolean arraysExist) {
		List<LispVal> parts = cons.toList();
		LispSymbol acc = new LispSymbol("__reverse_acc");
		LispSymbol x = new LispSymbol("__reverse_x");
		LispVal lambda = listToCons(List.of(new LispSymbol(LispNames.LAMBDA), listToCons(List.of(acc, x)),
				listToCons(List.of(new LispSymbol(LispNames.CONS), x, acc))));
		return seqResultDispatchForm(parts.get(1), lst -> listToCons(List.of(new LispSymbol(LispNames.REDUCE), lambda,
				lst, new LispSymbol(LispNames.INITIAL_VALUE_KEYWORD), LispNil.INSTANCE)), arraysExist);
	}

	/**
	 * Expands (member item lst) into a let/while scan returning the tail whose car is
	 * {@code eql} to the item, or nil. With a {@code :test} keyword
	 * ({@code (member item lst :test fn)}) the equality predicate is {@code fn} applied
	 * as {@code (funcall fn item element)} instead of {@code eql}; with a {@code :key}
	 * keyword the element side becomes {@code (funcall key element)}. The designators are
	 * inlined so a literal {@code 'name}/{@code #'name} resolves through the compilers'
	 * function-designator normalization.
	 * @param cons the member expression
	 * @return the expanded expression
	 */
	public static LispVal expandMember(LispCons cons) {
		List<LispVal> parts = cons.toList();
		requireTestKeyKeywords(LispNames.MEMBER, parts, 3);
		LispVal testForm = keywordValue(parts, 3, LispNames.TEST_KEYWORD);
		LispVal keyForm = keywordValue(parts, 3, LispNames.KEY_KEYWORD);
		LispSymbol item = new LispSymbol("__member_item");
		LispSymbol cur = new LispSymbol("__member_cur");
		// (do ((__member_item item) (__member_cur lst (cdr __member_cur)))
		// ((atom __member_cur) nil)
		// (if (eql __member_item (car __member_cur)) (return __member_cur)))
		// With :test fn, the match becomes (funcall fn __member_item <elem>); with :key
		// fn, <elem> becomes (funcall fn (car __member_cur)).
		LispVal bindings = listToCons(List.of(listToCons(List.of(item, parts.get(1))),
				listToCons(List.of(cur, parts.get(2), callOf(LispNames.CDR, cur)))));
		LispVal endClause = listToCons(List.of(callOf(LispNames.ATOM, cur), LispNil.INSTANCE));
		LispVal element = keyedForm(keyForm, callOf(LispNames.CAR, cur));
		LispVal match = testMatchForm(testForm, item, element);
		LispVal body = makeIf(match, makeReturn(cur), LispNil.INSTANCE);
		return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
	}

	// Scans a keyword/value argument tail starting at the given index for the named
	// keyword, returning the form following the first match, or null when absent.
	private static @Nullable LispVal keywordValue(List<LispVal> parts, int start, String keyword) {
		for (int i = start; i + 1 < parts.size(); i += 2) {
			if (parts.get(i) instanceof LispSymbol kw && keyword.equals(kw.name())) {
				return parts.get(i + 1);
			}
		}
		return null;
	}

	// Validates the keyword tail of a sequence/alist call: keyword/value pairs only, and
	// every keyword must be :test or :key. Unsupported keywords (:from-end, :start, ...)
	// are rejected loudly rather than silently ignored.
	private static void requireTestKeyKeywords(String name, List<LispVal> parts, int start) {
		for (int i = start; i < parts.size(); i += 2) {
			if (!(parts.get(i) instanceof LispSymbol kw)
					|| (!LispNames.TEST_KEYWORD.equals(kw.name()) && !LispNames.KEY_KEYWORD.equals(kw.name()))) {
				throw new IllegalArgumentException(
						name + " expects keyword arguments :test/:key, got: " + parts.get(i).print());
			}
			if (i + 1 >= parts.size()) {
				throw new IllegalArgumentException(name + " expects a value after " + kw.name());
			}
		}
	}

	// Applies the :key selector form to an element form ((funcall key elem)), or returns
	// the element form unchanged when no :key was given. Like the member/assoc :test
	// designator, the key designator is inlined at each use site so a literal
	// 'name/#'name resolves through the compilers' function-designator normalization.
	private static LispVal keyedForm(@Nullable LispVal keyForm, LispVal elemForm) {
		return keyForm == null ? elemForm : listToCons(List.of(new LispSymbol(LispNames.FUNCALL), keyForm, elemForm));
	}

	// Builds the equality form of a sequence/alist scan: (eql item elem) by default,
	// (funcall test item elem) with a :test designator. The element side is expected to
	// be pre-wrapped by keyedForm when a :key selector applies.
	private static LispVal testMatchForm(@Nullable LispVal testForm, LispVal item, LispVal keyedElem) {
		return testForm == null ? listToCons(List.of(new LispSymbol(LispNames.EQL), item, keyedElem))
				: listToCons(List.of(new LispSymbol(LispNames.FUNCALL), testForm, item, keyedElem));
	}

	// Builds an inner (member item lst :test ... :key ...) call forwarding the given
	// designator forms. The set-style functions (adjoin/union/intersection/
	// set-difference/remove-duplicates) compare via member, so their item side must be
	// pre-keyed by the caller while member's own :key covers the list side (CL applies
	// :key to both operands for these functions).
	private static LispVal memberCallForm(LispVal item, LispVal lst, @Nullable LispVal testForm,
			@Nullable LispVal keyForm) {
		List<LispVal> parts = new java.util.ArrayList<>(List.of(new LispSymbol(LispNames.MEMBER), item, lst));
		if (testForm != null) {
			parts.add(new LispSymbol(LispNames.TEST_KEYWORD));
			parts.add(testForm);
		}
		if (keyForm != null) {
			parts.add(new LispSymbol(LispNames.KEY_KEYWORD));
			parts.add(keyForm);
		}
		return listToCons(parts);
	}

	/**
	 * Expands (find item seq) into the shared position-family scan, returning the
	 * matching ELEMENT rather than its index (see {@code buildPositionScan}). Like
	 * {@code member} but yields the element itself rather than the tail, and it takes the
	 * position family's full keyword set --
	 * {@code :test}/{@code :test-not}/{@code :key}/{@code :start}/{@code :end}/
	 * {@code :from-end} -- because the two are the same scan; the returned element is the
	 * original one, not the keyed value.
	 * @param cons the find expression
	 * @return the expanded expression
	 */
	public static LispVal expandFind(LispCons cons) {
		List<LispVal> parts = cons.toList();
		requireKeywords(LispNames.FIND, parts, 3, LispNames.TEST_KEYWORD, LispNames.TEST_NOT_KEYWORD,
				LispNames.KEY_KEYWORD, LispNames.START_KEYWORD, LispNames.END_KEYWORD, LispNames.FROM_END_KEYWORD);
		return buildPositionScan(parts, PositionMode.ITEM, PositionResult.ELEMENT);
	}

	/**
	 * Expands (find-if pred seq) into the shared position-family scan returning the first
	 * element for which the predicate is true, or nil. Like {@code find} but tests each
	 * element with {@code (funcall pred element)} rather than {@code eql}; the same
	 * {@code :key}/{@code :start}/{@code :end}/{@code :from-end} keywords apply.
	 * @param cons the find-if expression
	 * @return the expanded expression
	 */
	public static LispVal expandFindIf(LispCons cons) {
		List<LispVal> parts = cons.toList();
		requireKeywords(LispNames.FIND_IF, parts, 3, LispNames.KEY_KEYWORD, LispNames.START_KEYWORD,
				LispNames.END_KEYWORD, LispNames.FROM_END_KEYWORD);
		return buildPositionScan(parts, PositionMode.PREDICATE, PositionResult.ELEMENT);
	}

	/**
	 * Expands (find-if-not pred seq) into the shared position-family scan returning the
	 * first element for which the predicate is false, or nil. The complement of
	 * {@code find-if}, with the same keywords.
	 * @param cons the find-if-not expression
	 * @return the expanded expression
	 */
	public static LispVal expandFindIfNot(LispCons cons) {
		List<LispVal> parts = cons.toList();
		requireKeywords(LispNames.FIND_IF_NOT, parts, 3, LispNames.KEY_KEYWORD, LispNames.START_KEYWORD,
				LispNames.END_KEYWORD, LispNames.FROM_END_KEYWORD);
		return buildPositionScan(parts, PositionMode.PREDICATE_NOT, PositionResult.ELEMENT);
	}

	/**
	 * Expands (position item seq) into a stringp-dispatched do/return scan returning the
	 * 0-based index of the first element {@code eql} to the item, or nil. A string
	 * sequence is scanned by index with {@code char} (its elements are characters); any
	 * other sequence is scanned as a list. Like {@code find} but yields the position
	 * rather than the element.
	 * @param cons the position expression
	 * @return the expanded expression
	 */
	public static LispVal expandPosition(LispCons cons) {
		List<LispVal> parts = cons.toList();
		requireKeywords(LispNames.POSITION, parts, 3, LispNames.TEST_KEYWORD, LispNames.TEST_NOT_KEYWORD,
				LispNames.KEY_KEYWORD, LispNames.START_KEYWORD, LispNames.END_KEYWORD, LispNames.FROM_END_KEYWORD);
		return buildPositionScan(parts, PositionMode.ITEM, PositionResult.INDEX);
	}

	/**
	 * Expands (position-if pred lst) into the shared position scan returning the 0-based
	 * index of the first element for which the predicate is true, or nil. Like
	 * {@code position} but tests each element with {@code (funcall pred element)} rather
	 * than {@code eql}; the same {@code :key}/{@code :start}/{@code :end}/
	 * {@code :from-end} keywords apply.
	 * @param cons the position-if expression
	 * @return the expanded expression
	 */
	public static LispVal expandPositionIf(LispCons cons) {
		List<LispVal> parts = cons.toList();
		requireKeywords(LispNames.POSITION_IF, parts, 3, LispNames.KEY_KEYWORD, LispNames.START_KEYWORD,
				LispNames.END_KEYWORD, LispNames.FROM_END_KEYWORD);
		return buildPositionScan(parts, PositionMode.PREDICATE, PositionResult.INDEX);
	}

	/**
	 * Expands (position-if-not pred lst) into the shared position scan returning the
	 * 0-based index of the first element for which the predicate is false, or nil. The
	 * complement of {@code position-if}, with the same keywords.
	 * @param cons the position-if-not expression
	 * @return the expanded expression
	 */
	public static LispVal expandPositionIfNot(LispCons cons) {
		List<LispVal> parts = cons.toList();
		requireKeywords(LispNames.POSITION_IF_NOT, parts, 3, LispNames.KEY_KEYWORD, LispNames.START_KEYWORD,
				LispNames.END_KEYWORD, LispNames.FROM_END_KEYWORD);
		return buildPositionScan(parts, PositionMode.PREDICATE_NOT, PositionResult.INDEX);
	}

	/**
	 * Expands {@code (complement fn)} into a one-argument lambda answering the opposite
	 * of the given predicate. The function form is evaluated once. Lite: CL's
	 * {@code complement} is variadic, but the result here takes exactly one argument (the
	 * predicate case; a variadic wrapper would need {@code apply}, which drags the whole
	 * eval runtime into every compiled program using it) -- and because this is an
	 * expansion, not a function, {@code #'complement} is not available.
	 *
	 * <pre>
	 * (complement fn) ->
	 *   (let ((__complement_fn fn))
	 *     (lambda (__complement_x) (not (funcall __complement_fn __complement_x))))
	 * </pre>
	 * @param cons the complement expression
	 * @return the expanded expression
	 */
	public static LispVal expandComplement(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException("complement expects exactly one function: " + cons.print());
		}
		LispSymbol fn = new LispSymbol("__complement_fn");
		LispSymbol x = new LispSymbol("__complement_x");
		LispVal call = listToCons(List.of(new LispSymbol(LispNames.FUNCALL), fn, x));
		LispVal lambda = listToCons(List.of(new LispSymbol(LispNames.LAMBDA), listToCons(List.of(x)), makeNot(call)));
		return makeLet(fn.name(), normalizeFunctionDesignator(parts.get(1)), lambda);
	}

	/**
	 * Expands {@code (copy-readtable ...)} into a nil-returning progn over its arguments:
	 * rontolisp's reader is not readtable-driven, so a "readtable" is an opaque nil token
	 * (the ironclad {@code *ironclad-readtable*} header binds one and never uses it for
	 * reading -- its {@code #N@(...)} syntax is native in the lexer).
	 * @param cons the copy-readtable expression
	 * @return the expanded expression
	 */
	public static LispVal expandCopyReadtable(LispCons cons) {
		List<LispVal> forms = new java.util.ArrayList<>(cons.toList().subList(1, cons.toList().size()));
		forms.add(LispNil.INSTANCE);
		return makeProgn(forms);
	}

	/**
	 * Expands {@code (set-dispatch-macro-character c1 c2 fn [readtable])} into a
	 * t-returning progn over its arguments: user dispatch macros cannot extend the
	 * Java-side reader, so the registration is accepted and ignored (see
	 * {@link #expandCopyReadtable}).
	 * @param cons the set-dispatch-macro-character expression
	 * @return the expanded expression
	 */
	public static LispVal expandSetDispatchMacroCharacter(LispCons cons) {
		List<LispVal> forms = new java.util.ArrayList<>(cons.toList().subList(1, cons.toList().size()));
		forms.add(LispTrue.INSTANCE);
		return makeProgn(forms);
	}

	/**
	 * Expands {@code (readtable-case readtable)} into a constant {@code :upcase} progn
	 * over its argument: the reader always upcases unescaped symbol names -- the standard
	 * readtable's {@code :upcase} mode -- and there is no readtable object to consult
	 * (see {@link #expandCopyReadtable}).
	 * @param cons the readtable-case expression
	 * @return the expanded expression
	 */
	public static LispVal expandReadtableCase(LispCons cons) {
		List<LispVal> forms = new java.util.ArrayList<>();
		for (LispVal arg : cons.toList().subList(1, cons.toList().size())) {
			// Only a call can have an effect worth keeping; an atom argument -- usually
			// the bare *readtable*, which has no compiled global cell -- is dropped.
			if (arg instanceof LispCons) {
				forms.add(arg);
			}
		}
		forms.add(new LispSymbol(":UPCASE"));
		return makeProgn(forms);
	}

	/**
	 * Expands {@code (complex real imag)} (or one argument) into a check that the
	 * imaginary part is zero: there is no complex number representation, so a zero
	 * imaginary part yields the real part and anything else signals. This keeps sources
	 * whose complex branch is never taken (e.g. parse-number's #C parser) loadable.
	 * @param cons the complex expression
	 * @return the expanded expression
	 */
	public static LispVal expandComplexLite(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2 || parts.size() > 3) {
			throw new IllegalArgumentException("complex expects a real part and an optional imaginary part");
		}
		if (parts.size() == 2) {
			return parts.get(1);
		}
		LispSymbol re = new LispSymbol("__complex_r");
		LispSymbol im = new LispSymbol("__complex_i");
		LispVal errorCall = listToCons(List.of(new LispSymbol(LispNames.ERROR),
				new LispString("complex numbers are not supported (imaginary part ~s)"), im));
		LispVal body = makeIf(mvCall(LispNames.ZEROP, im), re, errorCall);
		return makeLet(re.name(), parts.get(1), makeLet(im.name(), parts.get(2), body));
	}

	/**
	 * Expands {@code (parse-integer string &key start end radix junk-allowed)} into a
	 * shared digit-accumulation scan over the {@code char}/{@code digit-char-p}
	 * primitives, so every backend gets the full keyword set and BOTH return values (the
	 * integer and the position where parsing stopped, a literal {@code (values ...)} the
	 * multiple-value consumers and the {@code %mv-spill} channel pick up). Semantics:
	 * leading/trailing whitespace is skipped, an optional sign is accepted; without
	 * {@code :junk-allowed} a non-digit (or an empty digit run) signals, with it the scan
	 * stops at the first non-digit and yields nil when no digits were seen.
	 * @param cons the parse-integer expression
	 * @return the expanded expression
	 */
	public static LispVal expandParseInteger(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException("parse-integer expects a string: " + cons.print());
		}
		requireKeywords(LispNames.PARSE_INTEGER, parts, 2, LispNames.START_KEYWORD, LispNames.END_KEYWORD,
				LispNames.RADIX_KEYWORD, LispNames.JUNK_ALLOWED_KEYWORD);
		LispVal startForm = keywordValue(parts, 2, LispNames.START_KEYWORD);
		LispVal endForm = keywordValue(parts, 2, LispNames.END_KEYWORD);
		LispVal radixForm = keywordValue(parts, 2, LispNames.RADIX_KEYWORD);
		LispVal junkForm = keywordValue(parts, 2, LispNames.JUNK_ALLOWED_KEYWORD);
		LispSymbol str = new LispSymbol("__pi_s");
		LispSymbol endRaw = new LispSymbol("__pi_endraw");
		LispSymbol start = new LispSymbol("__pi_start");
		LispSymbol end = new LispSymbol("__pi_end");
		LispSymbol radix = new LispSymbol("__pi_radix");
		LispSymbol junk = new LispSymbol("__pi_junk");
		LispSymbol i = new LispSymbol("__pi_i");
		LispSymbol sign = new LispSymbol("__pi_sign");
		LispSymbol acc = new LispSymbol("__pi_acc");
		LispSymbol saw = new LispSymbol("__pi_saw");
		LispSymbol digit = new LispSymbol("__pi_d");
		LispVal charAt = mvCall(LispNames.CHAR, str, i);
		LispVal advance = piSetq(i, mvCall(LispNames.ADD, i, new LispInteger(1)));
		LispVal atWhitespace = mvCall(LispNames.MEMBER, charAt,
				listToCons(List.of(new LispSymbol(LispNames.QUOTE), listToCons(List.of(new LispChar(' '),
						new LispChar('\t'), new LispChar('\n'), new LispChar('\r'), new LispChar((char) 12))))));
		LispVal pastEnd = mvCall(LispNames.GE, i, end);
		LispVal skipWhitespace = piDo(mvCall(LispNames.OR, pastEnd, makeNot(atWhitespace)), List.of(advance));
		// (if (< i end) (if (eql c #\+) advance (if (eql c #\-) (sign -1; advance))))
		LispVal signStep = makeIf(mvCall(LispNames.LT, i, end),
				makeIf(mvCall(LispNames.EQL, charAt, new LispChar('+')), advance,
						makeIf(mvCall(LispNames.EQL, charAt, new LispChar('-')),
								makeProgn(List.of(piSetq(sign, new LispInteger(-1)), advance)), LispNil.INSTANCE)),
				LispNil.INSTANCE);
		// The digit loop: the end test reads the next digit into __pi_d as a side
		// effect (or short-circuits at the end of the region first).
		LispVal digitTest = mvCall(LispNames.OR, pastEnd,
				makeNot(piSetq(digit, mvCall(LispNames.DIGIT_CHAR_P, charAt, radix))));
		LispVal digitLoop = piDo(digitTest,
				List.of(piSetq(acc, mvCall(LispNames.ADD, mvCall(LispNames.MUL, acc, radix), digit)),
						piSetq(saw, LispTrue.INSTANCE), advance));
		LispVal result = mvCall(LispNames.VALUES, mvCall(LispNames.MUL, sign, acc), i);
		LispVal junkError = listToCons(
				List.of(new LispSymbol(LispNames.ERROR), new LispString("parse-integer: junk in string ~s"), str));
		LispVal emptyError = listToCons(List.of(new LispSymbol(LispNames.ERROR),
				new LispString("parse-integer: no integer in string ~s"), str));
		LispVal strictTail = makeProgn(
				List.of(skipWhitespace, makeIf(mvCall(LispNames.LT, i, end), junkError, LispNil.INSTANCE),
						makeIf(saw, LispNil.INSTANCE, emptyError), result));
		LispVal junkTail = makeIf(saw, result, mvCall(LispNames.VALUES, LispNil.INSTANCE, i));
		LispVal body = makeProgn(List.of(skipWhitespace, signStep, makeLet(digit.name(), LispNil.INSTANCE, digitLoop),
				makeIf(junk, junkTail, strictTail)));
		LispVal expanded = makeLet(saw.name(), LispNil.INSTANCE, body);
		expanded = makeLet(acc.name(), new LispInteger(0), expanded);
		expanded = makeLet(sign.name(), new LispInteger(1), expanded);
		expanded = makeLet(i.name(), start, expanded);
		expanded = makeLet(junk.name(), junkForm == null ? LispNil.INSTANCE : junkForm, expanded);
		expanded = makeLet(radix.name(), radixForm == null ? new LispInteger(10) : radixForm, expanded);
		expanded = makeLet(end.name(), makeIf(endRaw, endRaw, mvCall(LispNames.LENGTH, str)), expanded);
		expanded = makeLet(endRaw.name(), endForm == null ? LispNil.INSTANCE : endForm, expanded);
		expanded = makeLet(start.name(), startForm == null ? new LispInteger(0) : startForm, expanded);
		return makeLet(str.name(), parts.get(1), expanded);
	}

	private static LispVal piSetq(LispSymbol var, LispVal value) {
		return listToCons(List.of(new LispSymbol(LispNames.SETQ), var, value));
	}

	/** Builds a body-only {@code (do () (endTest nil) body...)} loop, pre-expanded. */
	private static LispVal piDo(LispVal endTest, List<LispVal> body) {
		List<LispVal> doParts = new java.util.ArrayList<>();
		doParts.add(new LispSymbol(LispNames.DO));
		doParts.add(LispNil.INSTANCE);
		doParts.add(listToCons(List.of(endTest, LispNil.INSTANCE)));
		doParts.addAll(body);
		return expandDo((LispCons) listToCons(doParts));
	}

	/**
	 * Expands {@code (/= a b ...)} into negated {@code =} tests over every pair (all
	 * arguments must be pairwise different, as in CL). Each argument is evaluated once
	 * through a temp.
	 * @param cons the /= expression
	 * @return the expanded expression
	 */
	public static LispVal expandNumericNotEqual(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException("/= expects at least one number: " + cons.print());
		}
		if (parts.size() == 2) {
			return makeProgn(List.of(parts.get(1), LispTrue.INSTANCE));
		}
		List<LispSymbol> temps = new java.util.ArrayList<>();
		List<MvBinding> bindings = new java.util.ArrayList<>();
		String prefix = "__ne" + MV_COUNTER.getAndIncrement();
		for (int i = 1; i < parts.size(); i++) {
			LispSymbol tmp = new LispSymbol(prefix + "_" + (i - 1));
			bindings.add(new MvBinding(tmp, parts.get(i)));
			temps.add(tmp);
		}
		List<LispVal> tests = new java.util.ArrayList<>();
		tests.add(new LispSymbol(LispNames.AND));
		for (int i = 0; i < temps.size(); i++) {
			for (int j = i + 1; j < temps.size(); j++) {
				tests.add(makeNot(mvCall(LispNames.EQ, temps.get(i), temps.get(j))));
			}
		}
		return nestMvBindings(bindings, listToCons(tests));
	}

	/** The matching flavor of a {@code position}-family scan; see buildPositionScan. */
	private enum PositionMode {

		/**
		 * {@code position}: the first argument is an item compared by :test/:test-not.
		 */
		ITEM,
		/** {@code position-if}: the first argument is a predicate. */
		PREDICATE,
		/** {@code position-if-not}: the first argument is a negated predicate. */
		PREDICATE_NOT

	}

	/**
	 * What a {@code position}-family scan yields on a match: the 0-based INDEX (the
	 * {@code position} family) or the matching ELEMENT (the {@code find} family). The two
	 * families are the same scan over the same keyword set and differ only here.
	 */
	private enum PositionResult {

		/** {@code position}/{@code position-if}/{@code position-if-not}. */
		INDEX,
		/** {@code find}/{@code find-if}/{@code find-if-not}. */
		ELEMENT

	}

	/**
	 * Builds the shared {@code position}/{@code position-if}/{@code position-if-not}
	 * expansion: a single forward do-scan over the sequence (a string is coerced to its
	 * character list first, like the other sequence scans) honoring {@code :start}/
	 * {@code :end}, where a {@code :from-end} match records the index and keeps scanning
	 * (the last match wins) while a normal match returns immediately.
	 *
	 * <pre>
	 * (let* ((__pos_item item) (__pos_lst <seq-as-list seq>)
	 *        (__pos_startv start|0) (__pos_endv end|nil) (__pos_fromv from-end)
	 *        (__pos_found nil))
	 *   (let ((__pos_hit (do ((__pos_idx __pos_startv (+ __pos_idx 1))
	 *                         (__pos_cur (nthcdr __pos_startv __pos_lst) (cdr __pos_cur)))
	 *                        ((or (atom __pos_cur) (if __pos_endv (>= __pos_idx __pos_endv) nil)) nil)
	 *                      (if MATCH
	 *                          (if __pos_fromv (setq __pos_found __pos_idx) (return __pos_idx))
	 *                          nil))))
	 *     (if __pos_hit __pos_hit __pos_found)))
	 * </pre>
	 */
	private static LispVal buildPositionScan(List<LispVal> parts, PositionMode mode, PositionResult resultKind) {
		LispVal testForm = keywordValue(parts, 3, LispNames.TEST_KEYWORD);
		LispVal testNotForm = keywordValue(parts, 3, LispNames.TEST_NOT_KEYWORD);
		LispVal keyForm = keywordValue(parts, 3, LispNames.KEY_KEYWORD);
		LispVal startForm = keywordValue(parts, 3, LispNames.START_KEYWORD);
		LispVal endForm = keywordValue(parts, 3, LispNames.END_KEYWORD);
		LispVal fromEndForm = keywordValue(parts, 3, LispNames.FROM_END_KEYWORD);
		LispSymbol item = new LispSymbol("__pos_item");
		LispSymbol lst = new LispSymbol("__pos_lst");
		LispSymbol startv = new LispSymbol("__pos_startv");
		LispSymbol endv = new LispSymbol("__pos_endv");
		LispSymbol fromv = new LispSymbol("__pos_fromv");
		LispSymbol found = new LispSymbol("__pos_found");
		LispSymbol hit = new LispSymbol("__pos_hit");
		LispSymbol idx = new LispSymbol("__pos_idx");
		LispSymbol cur = new LispSymbol("__pos_cur");
		LispVal idxStep = listToCons(List.of(new LispSymbol(LispNames.ADD), idx, new LispInteger(1)));
		LispVal curInit = listToCons(List.of(new LispSymbol(LispNames.NTHCDR), startv, lst));
		LispVal bindings = listToCons(List.of(listToCons(List.of(idx, startv, idxStep)),
				listToCons(List.of(cur, curInit, callOf(LispNames.CDR, cur)))));
		LispVal atEnd = callOf(LispNames.ATOM, cur);
		if (endForm != null) {
			LispVal pastEnd = makeIf(endv, listToCons(List.of(new LispSymbol(LispNames.GE), idx, endv)),
					LispNil.INSTANCE);
			atEnd = listToCons(List.of(new LispSymbol(LispNames.OR), atEnd, pastEnd));
		}
		LispVal endClause = listToCons(List.of(atEnd, LispNil.INSTANCE));
		LispVal keyedElem = keyedForm(keyForm, callOf(LispNames.CAR, cur));
		LispVal match = switch (mode) {
			case ITEM -> testNotForm != null
					? makeNot(listToCons(List.of(new LispSymbol(LispNames.FUNCALL), testNotForm, item, keyedElem)))
					: testMatchForm(testForm, item, keyedElem);
			case PREDICATE -> listToCons(List.of(new LispSymbol(LispNames.FUNCALL), item, keyedElem));
			case PREDICATE_NOT -> makeNot(listToCons(List.of(new LispSymbol(LispNames.FUNCALL), item, keyedElem)));
		};
		// The find family answers with the element; the position family with the index.
		// A nil element is indistinguishable from "no match" in the (if hit hit found)
		// join below, but both answers are nil either way, so the join stays correct.
		LispVal yield = resultKind == PositionResult.ELEMENT ? callOf(LispNames.CAR, cur) : idx;
		LispVal recordFound = listToCons(List.of(new LispSymbol(LispNames.SETQ), found, yield));
		LispVal onHit = fromEndForm == null ? makeReturn(yield) : makeIf(fromv, recordFound, makeReturn(yield));
		LispVal body = makeIf(match, onHit, LispNil.INSTANCE);
		LispVal scan = expandDo(
				(LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
		LispVal result = makeLet(hit.name(), scan, makeIf(hit, hit, found));
		result = makeLet(found.name(), LispNil.INSTANCE, result);
		if (fromEndForm != null) {
			result = makeLet(fromv.name(), fromEndForm, result);
		}
		result = makeLet(endv.name(), endForm == null ? LispNil.INSTANCE : endForm, result);
		result = makeLet(startv.name(), startForm == null ? new LispInteger(0) : startForm, result);
		result = makeLet(lst.name(), seqAsListForm(parts.get(2)), result);
		return makeLet(item.name(), parts.get(1), result);
	}

	// Validates a keyword/value argument tail against the operator's allowed keyword
	// set; anything else is rejected loudly rather than silently ignored.
	// The affix in the same case as the base name: all-uppercase bases (the upcase
	// reader's user symbols) get an upcased affix, everything else (the
	// lowercase-authored internal sources) keeps it lowercase.
	private static String affixFor(String affix, String base) {
		boolean hasLetter = false;
		for (int i = 0; i < base.length(); i++) {
			char c = base.charAt(i);
			if (Character.isLowerCase(c)) {
				return affix;
			}
			if (Character.isLetter(c)) {
				hasLetter = true;
			}
		}
		return hasLetter ? affix.toUpperCase(java.util.Locale.ROOT) : affix;
	}

	private static void requireKeywords(String name, List<LispVal> parts, int start, String... allowed) {
		for (int i = start; i < parts.size(); i += 2) {
			if (!(parts.get(i) instanceof LispSymbol kw)
					|| List.of(allowed).stream().noneMatch(a -> a.equals(kw.name()))) {
				throw new IllegalArgumentException(name + " expects keyword arguments " + String.join("/", allowed)
						+ ", got: " + parts.get(i).print());
			}
			if (i + 1 >= parts.size()) {
				throw new IllegalArgumentException(name + " expects a value after " + kw.name());
			}
		}
	}

	/**
	 * Expands (count item lst) into a do scan returning the number of elements
	 * {@code eql} to the item. Like {@code position} but accumulates a count of all
	 * matches rather than returning the first index.
	 * @param cons the count expression
	 * @return the expanded expression
	 */
	public static LispVal expandCount(LispCons cons) {
		List<LispVal> parts = cons.toList();
		requireTestKeyKeywords(LispNames.COUNT, parts, 3);
		LispVal testForm = keywordValue(parts, 3, LispNames.TEST_KEYWORD);
		LispVal keyForm = keywordValue(parts, 3, LispNames.KEY_KEYWORD);
		LispSymbol item = new LispSymbol("__count_item");
		LispSymbol n = new LispSymbol("__count_n");
		LispSymbol cur = new LispSymbol("__count_cur");
		// (do ((__count_item item) (__count_n 0)
		// (__count_cur lst (cdr __count_cur)))
		// ((atom __count_cur) __count_n)
		// (if (eql __count_item (car __count_cur))
		// (setq __count_n (+ __count_n 1)) nil))
		LispVal bindings = listToCons(
				List.of(listToCons(List.of(item, parts.get(1))), listToCons(List.of(n, new LispInteger(0))),
						listToCons(List.of(cur, seqAsListForm(parts.get(2)), callOf(LispNames.CDR, cur)))));
		LispVal endClause = listToCons(List.of(callOf(LispNames.ATOM, cur), n));
		LispVal match = testMatchForm(testForm, item, keyedForm(keyForm, callOf(LispNames.CAR, cur)));
		LispVal increment = listToCons(List.of(new LispSymbol(LispNames.ADD), n, new LispInteger(1)));
		LispVal incrementStep = listToCons(List.of(new LispSymbol(LispNames.SETQ), n, increment));
		LispVal body = makeIf(match, incrementStep, LispNil.INSTANCE);
		return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
	}

	/**
	 * Expands (count-if pred lst) into a do scan returning the number of elements for
	 * which the predicate is true. Like {@code count} but tests each element with
	 * {@code (funcall pred element)} rather than {@code eql}.
	 * @param cons the count-if expression
	 * @return the expanded expression
	 */
	public static LispVal expandCountIf(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispSymbol pred = new LispSymbol("__countif_pred");
		LispSymbol n = new LispSymbol("__countif_n");
		LispSymbol cur = new LispSymbol("__countif_cur");
		// (do ((__countif_pred pred) (__countif_n 0)
		// (__countif_cur lst (cdr __countif_cur)))
		// ((atom __countif_cur) __countif_n)
		// (if (funcall __countif_pred (car __countif_cur))
		// (setq __countif_n (+ __countif_n 1)) nil))
		LispVal bindings = listToCons(
				List.of(listToCons(List.of(pred, parts.get(1))), listToCons(List.of(n, new LispInteger(0))),
						listToCons(List.of(cur, seqAsListForm(parts.get(2)), callOf(LispNames.CDR, cur)))));
		LispVal endClause = listToCons(List.of(callOf(LispNames.ATOM, cur), n));
		LispVal test = listToCons(List.of(new LispSymbol(LispNames.FUNCALL), pred, callOf(LispNames.CAR, cur)));
		LispVal increment = listToCons(List.of(new LispSymbol(LispNames.ADD), n, new LispInteger(1)));
		LispVal incrementStep = listToCons(List.of(new LispSymbol(LispNames.SETQ), n, increment));
		LispVal body = makeIf(test, incrementStep, LispNil.INSTANCE);
		return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
	}

	/**
	 * Expands (assoc key alist) into a let/while scan returning the first pair whose car
	 * matches the key, or nil. The comparison is {@code eql} by default; with a
	 * {@code :test} keyword ({@code (assoc key alist :test fn)}) it becomes
	 * {@code (funcall fn key (car pair))}, and a {@code :key} keyword applies a selector
	 * to each pair's car first. Like {@code member}, the designators are inlined so a
	 * literal {@code 'name}/{@code #'name} resolves through the compilers'
	 * function-designator normalization.
	 * @param cons the assoc expression
	 * @return the expanded expression
	 */
	public static LispVal expandAssoc(LispCons cons) {
		List<LispVal> parts = cons.toList();
		requireTestKeyKeywords(LispNames.ASSOC, parts, 3);
		LispVal testForm = keywordValue(parts, 3, LispNames.TEST_KEYWORD);
		LispVal keyForm = keywordValue(parts, 3, LispNames.KEY_KEYWORD);
		LispSymbol key = new LispSymbol("__assoc_key");
		LispSymbol cur = new LispSymbol("__assoc_cur");
		LispVal pair = callOf(LispNames.CAR, cur);
		// (do ((__assoc_key key) (__assoc_cur alist (cdr __assoc_cur)))
		// ((atom __assoc_cur) nil)
		// (if (and (consp (car __assoc_cur)) (eql __assoc_key (car (car __assoc_cur))))
		// (return (car __assoc_cur))))
		LispVal bindings = listToCons(List.of(listToCons(List.of(key, parts.get(1))),
				listToCons(List.of(cur, parts.get(2), callOf(LispNames.CDR, cur)))));
		LispVal endClause = listToCons(List.of(callOf(LispNames.ATOM, cur), LispNil.INSTANCE));
		LispVal comparison = testMatchForm(testForm, key, keyedForm(keyForm, callOf(LispNames.CAR, pair)));
		LispVal match = listToCons(List.of(new LispSymbol(LispNames.AND),
				listToCons(List.of(new LispSymbol(LispNames.CONSP), pair)), comparison));
		LispVal body = makeIf(match, makeReturn(pair), LispNil.INSTANCE);
		return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
	}

	/**
	 * Expands (member-if pred lst) into a do/return scan returning the tail of the list
	 * starting at the first element for which the predicate is true, or nil. Like
	 * {@code member} but tests each element with {@code (funcall pred element)} rather
	 * than {@code eql}, and like {@code find-if} but yields the tail rather than the
	 * element.
	 * @param cons the member-if expression
	 * @return the expanded expression
	 */
	public static LispVal expandMemberIf(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispSymbol pred = new LispSymbol("__memberif_pred");
		LispSymbol cur = new LispSymbol("__memberif_cur");
		// (do ((__memberif_pred pred) (__memberif_cur lst (cdr __memberif_cur)))
		// ((atom __memberif_cur) nil)
		// (if (funcall __memberif_pred (car __memberif_cur)) (return __memberif_cur)
		// nil))
		LispVal bindings = listToCons(List.of(listToCons(List.of(pred, parts.get(1))),
				listToCons(List.of(cur, parts.get(2), callOf(LispNames.CDR, cur)))));
		LispVal endClause = listToCons(List.of(callOf(LispNames.ATOM, cur), LispNil.INSTANCE));
		LispVal test = listToCons(List.of(new LispSymbol(LispNames.FUNCALL), pred, callOf(LispNames.CAR, cur)));
		LispVal body = makeIf(test, makeReturn(cur), LispNil.INSTANCE);
		return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
	}

	/**
	 * Expands (assoc-if pred alist) into a do/return scan returning the first pair whose
	 * car satisfies the predicate, or nil. Like {@code assoc} but tests each pair's car
	 * with {@code (funcall pred (car pair))} rather than {@code eql}.
	 * @param cons the assoc-if expression
	 * @return the expanded expression
	 */
	public static LispVal expandAssocIf(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispSymbol pred = new LispSymbol("__associf_pred");
		LispSymbol cur = new LispSymbol("__associf_cur");
		LispVal pair = callOf(LispNames.CAR, cur);
		// (do ((__associf_pred pred) (__associf_cur alist (cdr __associf_cur)))
		// ((atom __associf_cur) nil)
		// (if (and (consp (car __associf_cur))
		// (funcall __associf_pred (car (car __associf_cur))))
		// (return (car __associf_cur))))
		LispVal bindings = listToCons(List.of(listToCons(List.of(pred, parts.get(1))),
				listToCons(List.of(cur, parts.get(2), callOf(LispNames.CDR, cur)))));
		LispVal endClause = listToCons(List.of(callOf(LispNames.ATOM, cur), LispNil.INSTANCE));
		LispVal match = listToCons(
				List.of(new LispSymbol(LispNames.AND), listToCons(List.of(new LispSymbol(LispNames.CONSP), pair)),
						listToCons(List.of(new LispSymbol(LispNames.FUNCALL), pred, callOf(LispNames.CAR, pair)))));
		LispVal body = makeIf(match, makeReturn(pair), LispNil.INSTANCE);
		return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
	}

	/**
	 * Normalizes the CHARACTER BAG of a {@code string-trim}/{@code string-left-trim}/
	 * {@code string-right-trim} call to a string, which is the one shape the per-backend
	 * trim compilers accept. CL lets the bag be any sequence of characters, and a LIST
	 * bag is what libraries actually write -- postmodern's {@code execute-file} lexer
	 * trims with {@code '(#\Space #\Tab)} at five sites.
	 * <p>
	 * A literal bag (a string, or a quoted list/vector of character literals) folds to a
	 * string constant here, so the emitted code is exactly what a string bag would have
	 * produced and existing programs stay byte-identical. Any other bag gets a
	 * {@code (coerce bag 'string)} wrapper, which is identity on a string.
	 * @param cons the trim expression
	 * @return the same expression with a string-valued bag
	 */
	public static LispCons normalizeCharBag(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			return cons;
		}
		LispVal bag = parts.get(1);
		if (bag instanceof LispString) {
			return cons;
		}
		LispVal folded = literalCharBagString(bag);
		List<LispVal> rewritten = new java.util.ArrayList<>(parts);
		rewritten.set(1, folded != null ? folded : fmtCall(LispNames.COERCE, bag, quoteOf(LispNames.STRING)));
		return (LispCons) listToCons(rewritten);
	}

	/**
	 * The string a literal character-bag denotes, or null when the bag is not a literal
	 * sequence of character literals.
	 */
	@Nullable private static LispVal literalCharBagString(LispVal bag) {
		if (!(bag instanceof LispCons quoted) || !(quoted.car() instanceof LispSymbol q)
				|| !LispNames.QUOTE.equals(q.name()) || !(quoted.cdr() instanceof LispCons rest)) {
			return null;
		}
		LispVal datum = rest.car();
		if (datum instanceof LispNil) {
			return new LispString("");
		}
		if (!(datum instanceof LispCons list) || !list.isProperList()) {
			return null;
		}
		StringBuilder chars = new StringBuilder();
		for (LispVal element : list.toList()) {
			if (!(element instanceof LispChar ch)) {
				return null;
			}
			chars.appendCodePoint(ch.codePoint());
		}
		return new LispString(chars.toString());
	}

	/**
	 * Expands (rassoc-if pred alist) into a do/return scan returning the first pair whose
	 * CDR satisfies the predicate, or nil. The mirror of {@link #expandAssocIf}: it tests
	 * {@code (funcall pred (cdr pair))}. postmodern's json-encoder picks its unicode
	 * escape entry with {@code (rassoc-if #'consp ...)}.
	 * @param cons the rassoc-if expression
	 * @return the expanded expression
	 */
	public static LispVal expandRassocIf(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			throw new IllegalArgumentException(LispNames.RASSOC_IF + " expects a predicate and an alist");
		}
		LispSymbol pred = new LispSymbol("__rassocif_pred");
		LispSymbol cur = new LispSymbol("__rassocif_cur");
		LispVal pair = callOf(LispNames.CAR, cur);
		// (do ((__rassocif_pred pred) (__rassocif_cur alist (cdr __rassocif_cur)))
		// ((atom __rassocif_cur) nil)
		// (if (and (consp (car __rassocif_cur))
		// (funcall __rassocif_pred (cdr (car __rassocif_cur))))
		// (return (car __rassocif_cur))))
		LispVal bindings = listToCons(List.of(listToCons(List.of(pred, parts.get(1))),
				listToCons(List.of(cur, parts.get(2), callOf(LispNames.CDR, cur)))));
		LispVal endClause = listToCons(List.of(callOf(LispNames.ATOM, cur), LispNil.INSTANCE));
		LispVal match = listToCons(
				List.of(new LispSymbol(LispNames.AND), listToCons(List.of(new LispSymbol(LispNames.CONSP), pair)),
						listToCons(List.of(new LispSymbol(LispNames.FUNCALL), pred, callOf(LispNames.CDR, pair)))));
		LispVal body = makeIf(match, makeReturn(pair), LispNil.INSTANCE);
		return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
	}

	/**
	 * Expands (getf plist key [default]) into a do/return scan over a property list,
	 * returning the value following the first key {@code eql} to the indicator. When the
	 * indicator is absent the optional DEFAULT is returned (nil when it is omitted).
	 * {@code getf} is a FUNCTION in CL, so the default is evaluated whether or not the
	 * indicator is found: it is bound in the {@code do} INIT list (evaluated once, before
	 * the loop) rather than left in the result position, where a hit would skip it and
	 * the compile paths would diverge from the interpreter's eager argument evaluation.
	 * The cursor advances two cells at a time ({@code cddr}). The partner of
	 * {@code remf}.
	 * @param cons the getf expression
	 * @return the expanded expression
	 */
	public static LispVal expandGetf(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3 || parts.size() > 4) {
			throw new IllegalArgumentException(
					LispNames.GETF + " expects a property list, an indicator and an" + " optional default");
		}
		LispSymbol key = new LispSymbol("__getf_key");
		LispSymbol cur = new LispSymbol("__getf_cur");
		// (getf plist key default): plist is parts.get(1), the indicator is parts.get(2).
		// (do ((__getf_key key) (__getf_cur plist (cddr __getf_cur)) (__getf_dflt
		// default))
		// ((atom __getf_cur) __getf_dflt)
		// (if (eql __getf_key (car __getf_cur)) (return (cadr __getf_cur)) nil))
		LispVal cddrStep = listToCons(List.of(new LispSymbol("CDDR"), cur));
		List<LispVal> bindingList = new java.util.ArrayList<>(
				List.of(listToCons(List.of(key, parts.get(2))), listToCons(List.of(cur, parts.get(1), cddrStep))));
		// An omitted default stays the nil literal, so a 2-argument getf expands exactly
		// as before and existing programs keep their bytes.
		LispVal dflt = LispNil.INSTANCE;
		if (parts.size() == 4) {
			LispSymbol dfltVar = new LispSymbol("__getf_dflt");
			bindingList.add(listToCons(List.of(dfltVar, parts.get(3))));
			dflt = dfltVar;
		}
		LispVal bindings = listToCons(bindingList);
		LispVal endClause = listToCons(List.of(callOf(LispNames.ATOM, cur), dflt));
		LispVal match = listToCons(List.of(new LispSymbol(LispNames.EQL), key, callOf(LispNames.CAR, cur)));
		LispVal value = listToCons(List.of(new LispSymbol("CADR"), cur));
		LispVal body = makeIf(match, makeReturn(value), LispNil.INSTANCE);
		return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
	}

	/**
	 * Expands (remove-duplicates lst) into a do scan that accumulates (in reverse) every
	 * element that does not occur again later in the list, then reverses the accumulator
	 * back to source order. Elements are compared with {@code eql} via {@code member}, so
	 * the last occurrence of each element is kept (Common Lisp's default). The
	 * {@code :test}/{@code :key} keywords forward to the inner {@code member}; the
	 * {@code :key} selector applies to both sides of the comparison (CL semantics).
	 * @param cons the remove-duplicates expression
	 * @return the expanded expression
	 */
	public static LispVal expandRemoveDuplicates(LispCons cons) {
		return expandRemoveDuplicates(cons, true);
	}

	/**
	 * Like {@link #expandRemoveDuplicates(LispCons)}, but lets a backend drop the vector
	 * arm of the dispatch when no array can exist in this program (see
	 * {@code seqResultDispatchForm} and {@link #expandCoerce(LispCons, boolean)}).
	 * @param cons the remove-duplicates expression
	 * @param arraysExist whether a general array can exist in this program
	 * @return the expanded expression
	 */
	public static LispVal expandRemoveDuplicates(LispCons cons, boolean arraysExist) {
		List<LispVal> parts = cons.toList();
		requireTestKeyKeywords(LispNames.REMOVE_DUPLICATES, parts, 2);
		LispVal testForm = keywordValue(parts, 2, LispNames.TEST_KEYWORD);
		LispVal keyForm = keywordValue(parts, 2, LispNames.KEY_KEYWORD);
		LispSymbol acc = new LispSymbol("__rd_acc");
		LispSymbol cur = new LispSymbol("__rd_cur");
		// (do ((__rd_acc nil) (__rd_cur lst (cdr __rd_cur)))
		// ((atom __rd_cur) (reverse __rd_acc))
		// (if (member (car __rd_cur) (cdr __rd_cur) [:test fn] [:key fn]) nil
		// (setq __rd_acc (cons (car __rd_cur) __rd_acc))))
		return seqResultDispatchForm(parts.get(1), lst -> {
			LispVal bindings = listToCons(List.of(listToCons(List.of(acc, LispNil.INSTANCE)),
					listToCons(List.of(cur, lst, callOf(LispNames.CDR, cur)))));
			LispVal endClause = listToCons(List.of(callOf(LispNames.ATOM, cur), callOf(LispNames.NREVERSE, acc)));
			LispVal dup = memberCallForm(keyedForm(keyForm, callOf(LispNames.CAR, cur)), callOf(LispNames.CDR, cur),
					testForm, keyForm);
			LispVal keep = listToCons(List.of(new LispSymbol(LispNames.SETQ), acc,
					listToCons(List.of(new LispSymbol(LispNames.CONS), callOf(LispNames.CAR, cur), acc))));
			LispVal body = makeIf(dup, LispNil.INSTANCE, keep);
			return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
		}, arraysExist);
	}

	/**
	 * Expands (butlast lst) into a do scan that accumulates (in reverse) every element
	 * except the last, then reverses the accumulator back to source order. An empty or
	 * single-element list yields nil.
	 * @param cons the butlast expression
	 * @return the expanded expression
	 */
	public static LispVal expandButlast(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispSymbol acc = new LispSymbol("__butlast_acc");
		LispSymbol cur = new LispSymbol("__butlast_cur");
		// (do ((__butlast_acc nil) (__butlast_cur lst (cdr __butlast_cur)))
		// ((or (atom __butlast_cur) (atom (cdr __butlast_cur))) (reverse __butlast_acc))
		// (setq __butlast_acc (cons (car __butlast_cur) __butlast_acc)))
		// The (atom __butlast_cur) guard short-circuits so (cdr __butlast_cur) is never
		// evaluated on nil (the compiled cdr requires a cons).
		LispVal bindings = listToCons(List.of(listToCons(List.of(acc, LispNil.INSTANCE)),
				listToCons(List.of(cur, parts.get(1), callOf(LispNames.CDR, cur)))));
		LispVal endTest = listToCons(List.of(new LispSymbol(LispNames.OR), callOf(LispNames.ATOM, cur),
				callOf(LispNames.ATOM, callOf(LispNames.CDR, cur))));
		LispVal endClause = listToCons(List.of(endTest, callOf(LispNames.NREVERSE, acc)));
		LispVal body = listToCons(List.of(new LispSymbol(LispNames.SETQ), acc,
				listToCons(List.of(new LispSymbol(LispNames.CONS), callOf(LispNames.CAR, cur), acc))));
		return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
	}

	/**
	 * Expands the variadic (nconc ...) form. {@code (nconc)} yields nil,
	 * {@code (nconc x)} yields {@code x}, and {@code (nconc a b c ...)} right-associates
	 * into nested 2-arg {@link #expandNconc2} bodies so each non-nil list's last cons is
	 * destructively linked to the following argument, returning the first non-nil
	 * argument. The last argument may be any object.
	 * @param cons the nconc expression
	 * @return the expanded expression
	 */
	public static LispVal expandNconc(LispCons cons) {
		List<LispVal> parts = cons.toList();
		// parts.get(0) is the nconc symbol; the operands follow.
		List<LispVal> operands = parts.subList(1, parts.size());
		if (operands.isEmpty()) {
			return LispNil.INSTANCE;
		}
		LispVal result = operands.get(operands.size() - 1);
		for (int i = operands.size() - 2; i >= 0; i--) {
			result = expandNconc2(operands.get(i), result);
		}
		return result;
	}

	/**
	 * Expands (nconc a b) into a let/while walk that destructively links the last cons of
	 * {@code a} to {@code b} and returns {@code a} (or {@code b} when {@code a} is
	 * empty). Both operands are bound once to avoid re-evaluation.
	 * @param aForm the first operand form
	 * @param bForm the second operand form
	 * @return the expanded expression
	 */
	private static LispVal expandNconc2(LispVal aForm, LispVal bForm) {
		LispSymbol a = new LispSymbol("__nconc_a");
		LispSymbol b = new LispSymbol("__nconc_b");
		LispSymbol tail = new LispSymbol("__nconc_tail");
		// (let ((__nconc_a a) (__nconc_b b))
		// (if (atom __nconc_a) __nconc_b
		// (let ((__nconc_tail __nconc_a))
		// (while (consp (cdr __nconc_tail)) (setq __nconc_tail (cdr __nconc_tail)))
		// (rplacd __nconc_tail __nconc_b)
		// __nconc_a)))
		LispVal whileTest = listToCons(List.of(new LispSymbol(LispNames.CONSP), callOf(LispNames.CDR, tail)));
		LispVal whileStep = listToCons(List.of(new LispSymbol(LispNames.SETQ), tail, callOf(LispNames.CDR, tail)));
		LispVal whileExpr = listToCons(List.of(new LispSymbol(LispNames.WHILE), whileTest, whileStep));
		LispVal rplacd = listToCons(List.of(new LispSymbol(LispNames.RPLACD), tail, b));
		LispVal innerBindings = new LispCons(listToCons(List.of(tail, a)), LispNil.INSTANCE);
		LispVal innerLet = listToCons(List.of(new LispSymbol(LispNames.LET), innerBindings, whileExpr, rplacd, a));
		LispVal ifExpr = makeIf(callOf(LispNames.ATOM, a), b, innerLet);
		LispVal outerBindings = listToCons(List.of(listToCons(List.of(a, aForm)), listToCons(List.of(b, bForm))));
		return listToCons(List.of(new LispSymbol(LispNames.LET), outerBindings, ifExpr));
	}

	/**
	 * Expands (identity x) into the argument form itself.
	 * @param cons the identity expression
	 * @return the expanded expression
	 */
	public static LispVal expandIdentity(LispCons cons) {
		return cons.toList().get(1);
	}

	/**
	 * Expands (nreverse lst) into an in-place reversal loop that rewires the {@code cdr}
	 * of every cons to its predecessor, returning the former last cell as the new head.
	 * This is destructive: the argument's cons cells are reused and the original list
	 * head is left pointing at a single-element list (Common Lisp semantics; use the
	 * return value).
	 * @param cons the nreverse expression
	 * @return the expanded expression
	 */
	public static LispVal expandNreverse(LispCons cons) {
		LispVal list = cons.toList().get(1);
		LispSymbol prev = new LispSymbol("__nrev_prev");
		LispSymbol cur = new LispSymbol("__nrev_cur");
		LispSymbol next = new LispSymbol("__nrev_next");
		// (let ((__nrev_prev nil) (__nrev_cur lst) (__nrev_next nil))
		// (while (consp __nrev_cur)
		// (setq __nrev_next (cdr __nrev_cur))
		// (rplacd __nrev_cur __nrev_prev)
		// (setq __nrev_prev __nrev_cur)
		// (setq __nrev_cur __nrev_next))
		// __nrev_prev)
		LispVal whileTest = listToCons(List.of(new LispSymbol(LispNames.CONSP), cur));
		LispVal saveNext = listToCons(List.of(new LispSymbol(LispNames.SETQ), next, callOf(LispNames.CDR, cur)));
		LispVal relink = listToCons(List.of(new LispSymbol(LispNames.RPLACD), cur, prev));
		LispVal advancePrev = listToCons(List.of(new LispSymbol(LispNames.SETQ), prev, cur));
		LispVal advanceCur = listToCons(List.of(new LispSymbol(LispNames.SETQ), cur, next));
		LispVal whileExpr = listToCons(
				List.of(new LispSymbol(LispNames.WHILE), whileTest, saveNext, relink, advancePrev, advanceCur));
		LispVal bindings = listToCons(List.of(listToCons(List.of(prev, LispNil.INSTANCE)),
				listToCons(List.of(cur, list)), listToCons(List.of(next, LispNil.INSTANCE))));
		return listToCons(List.of(new LispSymbol(LispNames.LET), bindings, whileExpr, prev));
	}

	/**
	 * Expands (copy-list lst) into (append lst nil). {@code append} copies every argument
	 * except the last, so this yields a shallow copy of the list.
	 * @param cons the copy-list expression
	 * @return the expanded expression
	 */
	public static LispVal expandCopyList(LispCons cons) {
		return listToCons(List.of(new LispSymbol(LispNames.APPEND), cons.toList().get(1), LispNil.INSTANCE));
	}

	/**
	 * Expands (make-list n) into a do loop that conses n nil elements. The CL
	 * {@code :initial-element} keyword is not supported.
	 * @param cons the make-list expression
	 * @return the expanded expression
	 */
	public static LispVal expandMakeList(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispSymbol i = new LispSymbol("__ml_i");
		LispSymbol acc = new LispSymbol("__ml_acc");
		LispSymbol elem = new LispSymbol("__ml_elem");
		// The element is bound OUTSIDE the loop so its form runs once, like CL's
		// single evaluation of :initial-element -- every cell shares that one value.
		LispVal element = makeListInitialElement(cons, parts);
		// (do ((__ml_i n (- __ml_i 1)) (__ml_acc nil (cons ELEM __ml_acc)))
		// ((<= __ml_i 0) __ml_acc))
		LispVal iStep = listToCons(List.of(new LispSymbol(LispNames.SUB), i, new LispInteger(1)));
		LispVal accStep = listToCons(
				List.of(new LispSymbol(LispNames.CONS), element == null ? LispNil.INSTANCE : elem, acc));
		LispVal bindings = listToCons(List.of(listToCons(List.of(i, parts.get(1), iStep)),
				listToCons(List.of(acc, LispNil.INSTANCE, accStep))));
		LispVal endTest = listToCons(List.of(new LispSymbol(LispNames.LE), i, new LispInteger(0)));
		LispVal endClause = listToCons(List.of(endTest, acc));
		LispVal loop = expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause)));
		return element == null ? loop : makeLet(elem.name(), element, loop);
	}

	/**
	 * The {@code :initial-element} value form of a {@code make-list} call, or null when
	 * the call has none (then every cell is nil, CL's default). Any other keyword is a
	 * hard error: {@code make-list} has exactly this one.
	 */
	@Nullable private static LispVal makeListInitialElement(LispCons cons, List<LispVal> parts) {
		if (parts.size() == 2) {
			return null;
		}
		if ((parts.size() - 2) % 2 != 0) {
			throw new IllegalArgumentException(
					LispNames.MAKE_LIST + " expects (size &key initial-element): " + cons.print());
		}
		LispVal element = null;
		for (int k = 2; k + 1 < parts.size(); k += 2) {
			if (!(parts.get(k) instanceof LispSymbol key) || !LispNames.INITIAL_ELEMENT_KEYWORD.equals(key.name())) {
				throw new IllegalArgumentException(LispNames.MAKE_LIST + ": unsupported keyword " + parts.get(k).print()
						+ " (only :initial-element): " + cons.print());
			}
			element = parts.get(k + 1);
		}
		return element;
	}

	/**
	 * Expands (adjoin item lst) into a let/if that prepends the item to the list unless
	 * it is already a member (compared with {@code eql}). Both operands are bound once to
	 * avoid re-evaluation. The {@code :test}/{@code :key} keywords forward to the inner
	 * {@code member}; the {@code :key} selector applies to both the item and the list
	 * elements (CL semantics), while the consed item stays unkeyed.
	 * @param cons the adjoin expression
	 * @return the expanded expression
	 */
	public static LispVal expandAdjoin(LispCons cons) {
		List<LispVal> parts = cons.toList();
		requireTestKeyKeywords(LispNames.ADJOIN, parts, 3);
		LispVal testForm = keywordValue(parts, 3, LispNames.TEST_KEYWORD);
		LispVal keyForm = keywordValue(parts, 3, LispNames.KEY_KEYWORD);
		LispSymbol item = new LispSymbol("__adjoin_item");
		LispSymbol lst = new LispSymbol("__adjoin_lst");
		// (let ((__adjoin_item item) (__adjoin_lst lst))
		// (if (member __adjoin_item __adjoin_lst [:test fn] [:key fn]) __adjoin_lst
		// (cons __adjoin_item __adjoin_lst)))
		LispVal memberTest = memberCallForm(keyedForm(keyForm, item), lst, testForm, keyForm);
		LispVal consCall = listToCons(List.of(new LispSymbol(LispNames.CONS), item, lst));
		LispVal ifExpr = makeIf(memberTest, lst, consCall);
		LispVal bindings = listToCons(
				List.of(listToCons(List.of(item, parts.get(1))), listToCons(List.of(lst, parts.get(2)))));
		return listToCons(List.of(new LispSymbol(LispNames.LET), bindings, ifExpr));
	}

	/**
	 * Expands (union a b) into a do scan that starts from {@code a} and prepends each
	 * element of {@code b} not already present (compared with {@code eql}). The result
	 * order is implementation-defined (CL leaves it unspecified). The
	 * {@code :test}/{@code :key} keywords forward to the inner {@code member}; the
	 * {@code :key} selector applies to both sides of the comparison (CL semantics).
	 * @param cons the union expression
	 * @return the expanded expression
	 */
	public static LispVal expandUnion(LispCons cons) {
		List<LispVal> parts = cons.toList();
		requireTestKeyKeywords(LispNames.UNION, parts, 3);
		LispVal testForm = keywordValue(parts, 3, LispNames.TEST_KEYWORD);
		LispVal keyForm = keywordValue(parts, 3, LispNames.KEY_KEYWORD);
		LispSymbol cur = new LispSymbol("__un_cur");
		LispSymbol acc = new LispSymbol("__un_acc");
		// (do ((__un_cur b (cdr __un_cur)) (__un_acc a))
		// ((atom __un_cur) __un_acc)
		// (if (member (car __un_cur) __un_acc [:test fn] [:key fn]) nil
		// (setq __un_acc (cons (car __un_cur) __un_acc))))
		LispVal bindings = listToCons(List.of(listToCons(List.of(cur, parts.get(2), callOf(LispNames.CDR, cur))),
				listToCons(List.of(acc, parts.get(1)))));
		LispVal endClause = listToCons(List.of(callOf(LispNames.ATOM, cur), acc));
		LispVal elem = callOf(LispNames.CAR, cur);
		LispVal match = memberCallForm(keyedForm(keyForm, elem), acc, testForm, keyForm);
		LispVal prepend = listToCons(List.of(new LispSymbol(LispNames.SETQ), acc,
				listToCons(List.of(new LispSymbol(LispNames.CONS), elem, acc))));
		LispVal body = makeIf(match, LispNil.INSTANCE, prepend);
		return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
	}

	/**
	 * Expands (intersection a b) into a do scan that collects each element of {@code a}
	 * that is a member of {@code b} (compared with {@code eql}). The result order is
	 * implementation-defined (CL leaves it unspecified). The {@code :test}/{@code :key}
	 * keywords forward to the inner {@code member}; the {@code :key} selector applies to
	 * both sides of the comparison (CL semantics).
	 * @param cons the intersection expression
	 * @return the expanded expression
	 */
	public static LispVal expandIntersection(LispCons cons) {
		List<LispVal> parts = cons.toList();
		requireTestKeyKeywords(LispNames.INTERSECTION, parts, 3);
		LispVal testForm = keywordValue(parts, 3, LispNames.TEST_KEYWORD);
		LispVal keyForm = keywordValue(parts, 3, LispNames.KEY_KEYWORD);
		LispSymbol cur = new LispSymbol("__in_cur");
		LispSymbol b = new LispSymbol("__in_b");
		LispSymbol acc = new LispSymbol("__in_acc");
		// (do ((__in_cur a (cdr __in_cur)) (__in_b b) (__in_acc nil))
		// ((atom __in_cur) __in_acc)
		// (if (member (car __in_cur) __in_b [:test fn] [:key fn])
		// (setq __in_acc (cons (car __in_cur) __in_acc)) nil))
		LispVal bindings = listToCons(List.of(listToCons(List.of(cur, parts.get(1), callOf(LispNames.CDR, cur))),
				listToCons(List.of(b, parts.get(2))), listToCons(List.of(acc, LispNil.INSTANCE))));
		LispVal endClause = listToCons(List.of(callOf(LispNames.ATOM, cur), acc));
		LispVal elem = callOf(LispNames.CAR, cur);
		LispVal match = memberCallForm(keyedForm(keyForm, elem), b, testForm, keyForm);
		LispVal collect = listToCons(List.of(new LispSymbol(LispNames.SETQ), acc,
				listToCons(List.of(new LispSymbol(LispNames.CONS), elem, acc))));
		LispVal body = makeIf(match, collect, LispNil.INSTANCE);
		return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
	}

	/**
	 * Expands (set-difference a b) into a do scan that collects each element of {@code a}
	 * that is not a member of {@code b} (compared with {@code eql}). The result order is
	 * implementation-defined (CL leaves it unspecified). The {@code :test}/{@code :key}
	 * keywords forward to the inner {@code member}; the {@code :key} selector applies to
	 * both sides of the comparison (CL semantics).
	 * @param cons the set-difference expression
	 * @return the expanded expression
	 */
	public static LispVal expandSetDifference(LispCons cons) {
		List<LispVal> parts = cons.toList();
		requireTestKeyKeywords(LispNames.SET_DIFFERENCE, parts, 3);
		LispVal testForm = keywordValue(parts, 3, LispNames.TEST_KEYWORD);
		LispVal keyForm = keywordValue(parts, 3, LispNames.KEY_KEYWORD);
		LispSymbol cur = new LispSymbol("__sd_cur");
		LispSymbol b = new LispSymbol("__sd_b");
		LispSymbol acc = new LispSymbol("__sd_acc");
		// (do ((__sd_cur a (cdr __sd_cur)) (__sd_b b) (__sd_acc nil))
		// ((atom __sd_cur) __sd_acc)
		// (if (member (car __sd_cur) __sd_b [:test fn] [:key fn]) nil
		// (setq __sd_acc (cons (car __sd_cur) __sd_acc))))
		LispVal bindings = listToCons(List.of(listToCons(List.of(cur, parts.get(1), callOf(LispNames.CDR, cur))),
				listToCons(List.of(b, parts.get(2))), listToCons(List.of(acc, LispNil.INSTANCE))));
		LispVal endClause = listToCons(List.of(callOf(LispNames.ATOM, cur), acc));
		LispVal elem = callOf(LispNames.CAR, cur);
		LispVal match = memberCallForm(keyedForm(keyForm, elem), b, testForm, keyForm);
		LispVal collect = listToCons(List.of(new LispSymbol(LispNames.SETQ), acc,
				listToCons(List.of(new LispSymbol(LispNames.CONS), elem, acc))));
		LispVal body = makeIf(match, LispNil.INSTANCE, collect);
		return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
	}

	/**
	 * Expands (every pred seq...) into a do/return scan that yields t when the predicate
	 * holds for every element tuple and nil at the first tuple for which it fails. Any
	 * number of sequences is accepted, as Common Lisp specifies ({@code every predicate
	 * &amp;rest sequences}); the walk stops as soon as the SHORTEST one runs out.
	 * @param cons the every expression
	 * @return the expanded expression
	 */
	public static LispVal expandEvery(LispCons cons) {
		return expandEverySomeFamily(cons, LispNames.EVERY, true);
	}

	/**
	 * Expands (some pred seq...) into a do/return scan that yields the first non-nil
	 * predicate result, or nil when the predicate fails for every element tuple. Any
	 * number of sequences is accepted, as with {@link #expandEvery(LispCons)}.
	 * @param cons the some expression
	 * @return the expanded expression
	 */
	public static LispVal expandSome(LispCons cons) {
		return expandEverySomeFamily(cons, LispNames.SOME, false);
	}

	/**
	 * Expands {@code every} / {@code some} over ANY number of sequences -- the two differ
	 * only in what they answer, so they share one lockstep walk rather than two
	 * hand-written ones. Each sequence is coerced to a list once (so strings and vectors
	 * work, unlike the {@code map*} family), then one cursor per sequence advances
	 * together and the walk ends as soon as any cursor hits a non-cons.
	 *
	 * <pre>
	 * (do ((#pred P) (#res nil)?                      ; #res: the some arm only
	 *      (#c0 (coerce S0 'list) (cdr #c0))          ; left-to-right: predicate, then
	 *      (#c1 (coerce S1 'list) (cdr #c1)))         ; the sequences
	 *     ((or (atom #c0) (atom #c1)) DEFAULT)         ; shortest-sequence termination
	 *   BODY)
	 * </pre>
	 *
	 * With one sequence the end test is the bare {@code (atom #c0)}, so the
	 * single-sequence expansion every backend already compiled is unchanged in shape.
	 * @param cons the every / some expression
	 * @param name the operator name, for the arity-error message
	 * @param every true for {@code every} (answer t, fail fast on a false result), false
	 * for {@code some} (answer nil, succeed fast on a true result)
	 * @return the expanded expression
	 */
	private static LispVal expandEverySomeFamily(LispCons cons, String name, boolean every) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3) {
			throw new IllegalArgumentException(
					name + " expects at least 2 arguments (a predicate and one sequence), got " + (parts.size() - 1));
		}
		int nSeqs = parts.size() - 2;
		String prefix = "__" + name.toLowerCase(java.util.Locale.ROOT) + "_";
		LispSymbol pred = new LispSymbol(prefix + "pred");
		LispSymbol res = new LispSymbol(prefix + "res");
		List<LispVal> bindings = new java.util.ArrayList<>();
		bindings.add(listToCons(List.of(pred, parts.get(1))));
		if (!every) {
			bindings.add(listToCons(List.of(res, LispNil.INSTANCE)));
		}
		List<LispVal> exhausted = new java.util.ArrayList<>();
		List<LispVal> callArgs = new java.util.ArrayList<>(List.of(new LispSymbol(LispNames.FUNCALL), pred));
		for (int i = 0; i < nSeqs; i++) {
			LispSymbol cursor = new LispSymbol(prefix + "c" + i);
			bindings.add(listToCons(List.of(cursor, seqAsListForm(parts.get(i + 2)), callOf(LispNames.CDR, cursor))));
			exhausted.add(callOf(LispNames.ATOM, cursor));
			callArgs.add(callOf(LispNames.CAR, cursor));
		}
		LispVal endTest = exhausted.get(0);
		if (nSeqs > 1) {
			List<LispVal> orParts = new java.util.ArrayList<>();
			orParts.add(new LispSymbol(LispNames.OR));
			orParts.addAll(exhausted);
			endTest = listToCons(orParts);
		}
		LispVal call = listToCons(callArgs);
		List<LispVal> form = new java.util.ArrayList<>();
		form.add(new LispSymbol(LispNames.DO));
		form.add(listToCons(bindings));
		form.add(listToCons(List.of(endTest, every ? LispTrue.INSTANCE : LispNil.INSTANCE)));
		if (every) {
			form.add(makeIf(call, LispNil.INSTANCE, makeReturn(LispNil.INSTANCE)));
		}
		else {
			form.add(listToCons(List.of(new LispSymbol(LispNames.SETQ), res, call)));
			form.add(makeIf(res, makeReturn(res), LispNil.INSTANCE));
		}
		return expandDo((LispCons) listToCons(form));
	}

	/**
	 * Expands (remove item lst) into a do scan that accumulates, then reverses, the
	 * elements that are not {@code eql} to the item. Accepts the same
	 * {@code :test}/{@code :key} keywords as {@code member}; the kept elements are the
	 * original ones, not the keyed values.
	 * @param cons the remove expression
	 * @return the expanded expression
	 */
	public static LispVal expandRemove(LispCons cons) {
		return expandRemove(cons, true);
	}

	/**
	 * Like {@link #expandRemove(LispCons)}, but lets a backend drop the vector arm of the
	 * dispatch when no array can exist in this program (see {@code seqResultDispatchForm}
	 * and {@link #expandCoerce(LispCons, boolean)}).
	 * @param cons the remove expression
	 * @param arraysExist whether a general array can exist in this program
	 * @return the expanded expression
	 */
	public static LispVal expandRemove(LispCons cons, boolean arraysExist) {
		List<LispVal> parts = cons.toList();
		requireTestKeyKeywords(LispNames.REMOVE, parts, 3);
		LispVal testForm = keywordValue(parts, 3, LispNames.TEST_KEYWORD);
		LispVal keyForm = keywordValue(parts, 3, LispNames.KEY_KEYWORD);
		LispSymbol item = new LispSymbol("__remove_item");
		// The item binds outside the string dispatch to keep the argument evaluation
		// order (item, then sequence); the filter's do rebinds it to itself.
		return makeLet(item.name(), parts.get(1), seqResultDispatchForm(parts.get(2), lst -> expandFilter(item, item,
				lst, "__remove", elem -> testMatchForm(testForm, item, keyedForm(keyForm, elem)), false), arraysExist));
	}

	/**
	 * Expands (remove-if pred lst) into a do scan that accumulates, then reverses, the
	 * elements for which the predicate fails.
	 * @param cons the remove-if expression
	 * @return the expanded expression
	 */
	public static LispVal expandRemoveIf(LispCons cons) {
		return expandRemoveIf(cons, true);
	}

	/**
	 * Like {@link #expandRemoveIf(LispCons)}, but lets a backend drop the vector arm of
	 * the dispatch when no array can exist in this program (see
	 * {@code seqResultDispatchForm} and {@link #expandCoerce(LispCons, boolean)}).
	 * @param cons the remove-if expression
	 * @param arraysExist whether a general array can exist in this program
	 * @return the expanded expression
	 */
	public static LispVal expandRemoveIf(LispCons cons, boolean arraysExist) {
		List<LispVal> parts = cons.toList();
		LispSymbol pred = new LispSymbol("__removeif_pred");
		return makeLet(pred.name(), parts.get(1),
				seqResultDispatchForm(parts.get(2),
						lst -> expandFilter(pred, pred, lst, "__removeif",
								elem -> listToCons(List.of(new LispSymbol(LispNames.FUNCALL), pred, elem)), false),
						arraysExist));
	}

	/**
	 * Expands (remove-if-not pred lst) into a do scan that accumulates, then reverses,
	 * the elements for which the predicate holds (the complement of {@code remove-if}).
	 * @param cons the remove-if-not expression
	 * @return the expanded expression
	 */
	public static LispVal expandRemoveIfNot(LispCons cons) {
		return expandRemoveIfNot(cons, true);
	}

	/**
	 * Like {@link #expandRemoveIfNot(LispCons)}, but lets a backend drop the vector arm
	 * of the dispatch when no array can exist in this program (see
	 * {@code seqResultDispatchForm} and {@link #expandCoerce(LispCons, boolean)}).
	 * @param cons the remove-if-not expression
	 * @param arraysExist whether a general array can exist in this program
	 * @return the expanded expression
	 */
	public static LispVal expandRemoveIfNot(LispCons cons, boolean arraysExist) {
		List<LispVal> parts = cons.toList();
		LispSymbol pred = new LispSymbol("__removeifnot_pred");
		return makeLet(pred.name(), parts.get(1),
				seqResultDispatchForm(parts.get(2),
						lst -> expandFilter(pred, pred, lst, "__removeifnot",
								elem -> listToCons(List.of(new LispSymbol(LispNames.FUNCALL), pred, elem)), true),
						arraysExist));
	}

	/**
	 * Expands (substitute new old lst) into a do scan that accumulates, then reverses, a
	 * copy of the list with every element {@code eql} to {@code old} replaced by
	 * {@code new}. Accepts the same {@code :test}/{@code :key} keywords as {@code member}
	 * (the {@code :key} selector applies to the scanned elements only).
	 * @param cons the substitute expression
	 * @return the expanded expression
	 */
	public static LispVal expandSubstitute(LispCons cons) {
		return expandSubstitute(cons, true);
	}

	/**
	 * Like {@link #expandSubstitute(LispCons)}, but lets a backend drop the vector arm of
	 * the dispatch when no array can exist in this program (see
	 * {@code seqResultDispatchForm} and {@link #expandCoerce(LispCons, boolean)}).
	 * @param cons the substitute expression
	 * @param arraysExist whether a general array can exist in this program
	 * @return the expanded expression
	 */
	public static LispVal expandSubstitute(LispCons cons, boolean arraysExist) {
		List<LispVal> parts = cons.toList();
		requireTestKeyKeywords(LispNames.SUBSTITUTE, parts, 4);
		LispVal testForm = keywordValue(parts, 4, LispNames.TEST_KEYWORD);
		LispVal keyForm = keywordValue(parts, 4, LispNames.KEY_KEYWORD);
		LispSymbol newItem = new LispSymbol("__subst_new");
		LispSymbol oldItem = new LispSymbol("__subst_old");
		LispSymbol acc = new LispSymbol("__subst_acc");
		LispSymbol cur = new LispSymbol("__subst_cur");
		// (do ((__subst_acc nil) (__subst_cur lst (cdr __subst_cur)))
		// ((atom __subst_cur) (reverse __subst_acc))
		// (setq __subst_acc
		// (cons (if (eql __subst_old (car __subst_cur)) __subst_new (car __subst_cur))
		// __subst_acc)))
		// The new/old items bind outside the string dispatch to keep the argument
		// evaluation order (new, old, then sequence).
		LispVal scan = seqResultDispatchForm(parts.get(3), lst -> {
			LispVal bindings = listToCons(List.of(listToCons(List.of(acc, LispNil.INSTANCE)),
					listToCons(List.of(cur, lst, callOf(LispNames.CDR, cur)))));
			LispVal endClause = listToCons(List.of(callOf(LispNames.ATOM, cur), callOf(LispNames.NREVERSE, acc)));
			LispVal match = testMatchForm(testForm, oldItem, keyedForm(keyForm, callOf(LispNames.CAR, cur)));
			LispVal chosen = makeIf(match, newItem, callOf(LispNames.CAR, cur));
			LispVal body = listToCons(List.of(new LispSymbol(LispNames.SETQ), acc,
					listToCons(List.of(new LispSymbol(LispNames.CONS), chosen, acc))));
			return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
		}, arraysExist);
		return makeLet(newItem.name(), parts.get(1), makeLet(oldItem.name(), parts.get(2), scan));
	}

	/**
	 * Expands (nsubstitute new old lst) into an in-place scan that rewrites the
	 * {@code car} of every cons whose value is {@code eql} to {@code old} with
	 * {@code new}, returning the (possibly mutated) original list. This is destructive:
	 * the argument's cons cells are reused (Common Lisp semantics). Accepts the same
	 * {@code :test}/{@code :key} keywords as {@code substitute}.
	 * @param cons the nsubstitute expression
	 * @return the expanded expression
	 */
	public static LispVal expandNsubstitute(LispCons cons) {
		List<LispVal> parts = cons.toList();
		requireTestKeyKeywords(LispNames.NSUBSTITUTE, parts, 4);
		LispVal testForm = keywordValue(parts, 4, LispNames.TEST_KEYWORD);
		LispVal keyForm = keywordValue(parts, 4, LispNames.KEY_KEYWORD);
		LispSymbol newItem = new LispSymbol("__nsub_new");
		LispSymbol oldItem = new LispSymbol("__nsub_old");
		LispSymbol lst = new LispSymbol("__nsub_lst");
		LispSymbol cur = new LispSymbol("__nsub_cur");
		// (let ((__nsub_new new) (__nsub_old old) (__nsub_lst lst) (__nsub_cur nil))
		// (setq __nsub_cur __nsub_lst)
		// (while (consp __nsub_cur)
		// (if (eql __nsub_old (car __nsub_cur)) (rplaca __nsub_cur __nsub_new) nil)
		// (setq __nsub_cur (cdr __nsub_cur)))
		// __nsub_lst)
		LispVal initCur = listToCons(List.of(new LispSymbol(LispNames.SETQ), cur, lst));
		LispVal whileTest = listToCons(List.of(new LispSymbol(LispNames.CONSP), cur));
		LispVal match = testMatchForm(testForm, oldItem, keyedForm(keyForm, callOf(LispNames.CAR, cur)));
		LispVal replace = listToCons(List.of(new LispSymbol(LispNames.RPLACA), cur, newItem));
		LispVal ifExpr = makeIf(match, replace, LispNil.INSTANCE);
		LispVal advance = listToCons(List.of(new LispSymbol(LispNames.SETQ), cur, callOf(LispNames.CDR, cur)));
		LispVal whileExpr = listToCons(List.of(new LispSymbol(LispNames.WHILE), whileTest, ifExpr, advance));
		LispVal bindings = listToCons(
				List.of(listToCons(List.of(newItem, parts.get(1))), listToCons(List.of(oldItem, parts.get(2))),
						listToCons(List.of(lst, parts.get(3))), listToCons(List.of(cur, LispNil.INSTANCE))));
		return listToCons(List.of(new LispSymbol(LispNames.LET), bindings, initCur, whileExpr, lst));
	}

	/**
	 * Expands (substitute-if new pred seq) like {@link #expandSubstitute(LispCons)}, with
	 * the {@code eql} comparison replaced by a call of the predicate on the (optionally
	 * {@code :key}-selected) element.
	 * @param cons the substitute-if expression
	 * @return the expanded expression
	 */
	public static LispVal expandSubstituteIf(LispCons cons) {
		return expandSubstituteIf(cons, true, false);
	}

	/**
	 * Expands (substitute-if-not new pred seq): the complement of
	 * {@link #expandSubstituteIf(LispCons)}, replacing the elements the predicate
	 * rejects.
	 * @param cons the substitute-if-not expression
	 * @return the expanded expression
	 */
	public static LispVal expandSubstituteIfNot(LispCons cons) {
		return expandSubstituteIf(cons, true, true);
	}

	/**
	 * Like {@link #expandSubstituteIf(LispCons)} /
	 * {@link #expandSubstituteIfNot(LispCons)}, but lets a backend drop the vector arm of
	 * the dispatch when no array can exist in this program (see
	 * {@code seqResultDispatchForm} and {@link #expandCoerce(LispCons, boolean)}).
	 * @param cons the substitute-if / substitute-if-not expression
	 * @param arraysExist whether a general array can exist in this program
	 * @param negated whether the predicate's verdict is inverted (the {@code -if-not}
	 * form)
	 * @return the expanded expression
	 */
	public static LispVal expandSubstituteIf(LispCons cons, boolean arraysExist, boolean negated) {
		String name = negated ? LispNames.SUBSTITUTE_IF_NOT : LispNames.SUBSTITUTE_IF;
		List<LispVal> parts = cons.toList();
		requireKeywords(name, parts, 4, LispNames.KEY_KEYWORD);
		LispVal keyForm = keywordValue(parts, 4, LispNames.KEY_KEYWORD);
		LispSymbol newItem = new LispSymbol("__substif_new");
		LispSymbol pred = new LispSymbol("__substif_pred");
		LispSymbol acc = new LispSymbol("__substif_acc");
		LispSymbol cur = new LispSymbol("__substif_cur");
		// The new item and the predicate bind outside the string dispatch to keep the
		// argument evaluation order (new, predicate, then sequence) -- expandSubstitute's
		// shape with (funcall pred elem) in place of the eql test.
		LispVal scan = seqResultDispatchForm(parts.get(3), lst -> {
			LispVal bindings = listToCons(List.of(listToCons(List.of(acc, LispNil.INSTANCE)),
					listToCons(List.of(cur, lst, callOf(LispNames.CDR, cur)))));
			LispVal endClause = listToCons(List.of(callOf(LispNames.ATOM, cur), callOf(LispNames.NREVERSE, acc)));
			LispVal match = listToCons(
					List.of(new LispSymbol(LispNames.FUNCALL), pred, keyedForm(keyForm, callOf(LispNames.CAR, cur))));
			LispVal chosen = negated ? makeIf(match, callOf(LispNames.CAR, cur), newItem)
					: makeIf(match, newItem, callOf(LispNames.CAR, cur));
			LispVal body = listToCons(List.of(new LispSymbol(LispNames.SETQ), acc,
					listToCons(List.of(new LispSymbol(LispNames.CONS), chosen, acc))));
			return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
		}, arraysExist);
		return makeLet(newItem.name(), parts.get(1), makeLet(pred.name(), parts.get(2), scan));
	}

	/**
	 * Expands (nsubstitute-if new pred lst) like {@link #expandNsubstitute(LispCons)},
	 * with the {@code eql} comparison replaced by a call of the predicate on the
	 * (optionally {@code :key}-selected) element.
	 * @param cons the nsubstitute-if expression
	 * @return the expanded expression
	 */
	public static LispVal expandNsubstituteIf(LispCons cons) {
		return expandNsubstituteIf(cons, false);
	}

	/**
	 * Expands (nsubstitute-if-not new pred lst): the complement of
	 * {@link #expandNsubstituteIf(LispCons)}.
	 * @param cons the nsubstitute-if-not expression
	 * @return the expanded expression
	 */
	public static LispVal expandNsubstituteIfNot(LispCons cons) {
		return expandNsubstituteIf(cons, true);
	}

	private static LispVal expandNsubstituteIf(LispCons cons, boolean negated) {
		String name = negated ? LispNames.NSUBSTITUTE_IF_NOT : LispNames.NSUBSTITUTE_IF;
		List<LispVal> parts = cons.toList();
		requireKeywords(name, parts, 4, LispNames.KEY_KEYWORD);
		LispVal keyForm = keywordValue(parts, 4, LispNames.KEY_KEYWORD);
		LispSymbol newItem = new LispSymbol("__nsubif_new");
		LispSymbol pred = new LispSymbol("__nsubif_pred");
		LispSymbol lst = new LispSymbol("__nsubif_lst");
		LispSymbol cur = new LispSymbol("__nsubif_cur");
		LispVal initCur = listToCons(List.of(new LispSymbol(LispNames.SETQ), cur, lst));
		LispVal whileTest = listToCons(List.of(new LispSymbol(LispNames.CONSP), cur));
		LispVal match = listToCons(
				List.of(new LispSymbol(LispNames.FUNCALL), pred, keyedForm(keyForm, callOf(LispNames.CAR, cur))));
		LispVal replace = listToCons(List.of(new LispSymbol(LispNames.RPLACA), cur, newItem));
		LispVal ifExpr = negated ? makeIf(match, LispNil.INSTANCE, replace) : makeIf(match, replace, LispNil.INSTANCE);
		LispVal advance = listToCons(List.of(new LispSymbol(LispNames.SETQ), cur, callOf(LispNames.CDR, cur)));
		LispVal whileExpr = listToCons(List.of(new LispSymbol(LispNames.WHILE), whileTest, ifExpr, advance));
		LispVal bindings = listToCons(
				List.of(listToCons(List.of(newItem, parts.get(1))), listToCons(List.of(pred, parts.get(2))),
						listToCons(List.of(lst, parts.get(3))), listToCons(List.of(cur, LispNil.INSTANCE))));
		return listToCons(List.of(new LispSymbol(LispNames.LET), bindings, initCur, whileExpr, lst));
	}

	/**
	 * Expands (delete item lst) into a destructive splice that removes every cons whose
	 * {@code car} is {@code eql} to {@code item}, reusing the surviving cons cells.
	 * Accepts the same {@code :test}/{@code :key} keywords as {@code member}.
	 * @param cons the delete expression
	 * @return the expanded expression
	 */
	public static LispVal expandDelete(LispCons cons) {
		List<LispVal> parts = cons.toList();
		requireTestKeyKeywords(LispNames.DELETE, parts, 3);
		LispVal testForm = keywordValue(parts, 3, LispNames.TEST_KEYWORD);
		LispVal keyForm = keywordValue(parts, 3, LispNames.KEY_KEYWORD);
		LispSymbol item = new LispSymbol("__delete_item");
		return expandDeleteFilter(item, parts.get(1), parts.get(2), "__delete",
				elem -> testMatchForm(testForm, item, keyedForm(keyForm, elem)), true);
	}

	/**
	 * Expands (delete-if pred lst) into a destructive splice that removes every cons
	 * whose {@code car} satisfies the predicate, reusing the surviving cons cells.
	 * @param cons the delete-if expression
	 * @return the expanded expression
	 */
	public static LispVal expandDeleteIf(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispSymbol pred = new LispSymbol("__deleteif_pred");
		return expandDeleteFilter(pred, parts.get(1), parts.get(2), "__deleteif",
				elem -> listToCons(List.of(new LispSymbol(LispNames.FUNCALL), pred, elem)), true);
	}

	/**
	 * Expands (delete-if-not pred lst) into a destructive splice that removes every cons
	 * whose {@code car} fails the predicate, reusing the surviving cons cells.
	 * @param cons the delete-if-not expression
	 * @return the expanded expression
	 */
	public static LispVal expandDeleteIfNot(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispSymbol pred = new LispSymbol("__deleteifnot_pred");
		return expandDeleteFilter(pred, parts.get(1), parts.get(2), "__deleteifnot",
				elem -> listToCons(List.of(new LispSymbol(LispNames.FUNCALL), pred, elem)), false);
	}

	/**
	 * Shared destructive expansion for
	 * {@code delete}/{@code delete-if}/{@code delete-if-not}: bind the test operand once,
	 * drop matching cons cells from the front by advancing the head, then splice out
	 * matching cons cells in the interior with {@code rplacd}. The deletion test is built
	 * by {@code matchOf} from the {@code (car cursor)} element form; when
	 * {@code deleteWhenMatch} is false the cons is deleted when the test is false
	 * ({@code delete-if-not}). The surviving cons cells are reused (Common Lisp
	 * semantics; use the return value).
	 */
	private static LispVal expandDeleteFilter(LispSymbol operand, LispVal operandInit, LispVal list, String prefix,
			java.util.function.UnaryOperator<LispVal> matchOf, boolean deleteWhenMatch) {
		LispSymbol head = new LispSymbol(prefix + "_head");
		LispSymbol prev = new LispSymbol(prefix + "_prev");
		LispSymbol cur = new LispSymbol(prefix + "_cur");
		LispVal match = matchOf.apply(callOf(LispNames.CAR, cur));
		LispVal deleteForm = deleteWhenMatch ? match : listToCons(List.of(new LispSymbol(LispNames.NOT), match));
		// (let ((operand operandInit) (head list) (prev nil) (cur nil))
		// (while (and (consp head) deleteFormOnHead) (setq head (cdr head))) ; drop
		// leading
		// (setq prev head)
		// (if (consp head) (setq cur (cdr head)) nil)
		// (while (consp cur)
		// (if deleteFormOnCur (rplacd prev (cdr cur)) (setq prev cur))
		// (setq cur (cdr cur)))
		// head)
		LispVal matchOnHead = matchOf.apply(callOf(LispNames.CAR, head));
		LispVal deleteOnHead = deleteWhenMatch ? matchOnHead
				: listToCons(List.of(new LispSymbol(LispNames.NOT), matchOnHead));
		LispVal leadTest = listToCons(List.of(new LispSymbol(LispNames.AND),
				listToCons(List.of(new LispSymbol(LispNames.CONSP), head)), deleteOnHead));
		LispVal leadStep = listToCons(List.of(new LispSymbol(LispNames.SETQ), head, callOf(LispNames.CDR, head)));
		LispVal leadWhile = listToCons(List.of(new LispSymbol(LispNames.WHILE), leadTest, leadStep));
		LispVal setPrev = listToCons(List.of(new LispSymbol(LispNames.SETQ), prev, head));
		LispVal initCur = makeIf(listToCons(List.of(new LispSymbol(LispNames.CONSP), head)),
				listToCons(List.of(new LispSymbol(LispNames.SETQ), cur, callOf(LispNames.CDR, head))),
				LispNil.INSTANCE);
		LispVal mainTest = listToCons(List.of(new LispSymbol(LispNames.CONSP), cur));
		LispVal splice = listToCons(List.of(new LispSymbol(LispNames.RPLACD), prev, callOf(LispNames.CDR, cur)));
		LispVal keepPrev = listToCons(List.of(new LispSymbol(LispNames.SETQ), prev, cur));
		LispVal mainIf = makeIf(deleteForm, splice, keepPrev);
		LispVal mainAdvance = listToCons(List.of(new LispSymbol(LispNames.SETQ), cur, callOf(LispNames.CDR, cur)));
		LispVal mainWhile = listToCons(List.of(new LispSymbol(LispNames.WHILE), mainTest, mainIf, mainAdvance));
		LispVal bindings = listToCons(
				List.of(listToCons(List.of(operand, operandInit)), listToCons(List.of(head, list)),
						listToCons(List.of(prev, LispNil.INSTANCE)), listToCons(List.of(cur, LispNil.INSTANCE))));
		return listToCons(
				List.of(new LispSymbol(LispNames.LET), bindings, leadWhile, setPrev, initCur, mainWhile, head));
	}

	/**
	 * Shared expansion for {@code remove}/{@code remove-if}/{@code remove-if-not}: bind
	 * the test operand, walk the list, and accumulate (in reverse) every element to keep.
	 * The result form reverses the accumulator back to source order. The match form is
	 * built by {@code matchOf} from the {@code (car cursor)} element form; for
	 * {@code remove} it is {@code (eql item (car cursor))} (with optional
	 * {@code :test}/{@code :key} designators) and for the {@code -if} variants it is
	 * {@code (funcall pred (car cursor))}. When {@code keepWhenMatch} is false an element
	 * is kept when the match is false ({@code remove}/{@code remove-if}); when true it is
	 * kept when the match is true ({@code remove-if-not}).
	 */
	private static LispVal expandFilter(LispSymbol operand, LispVal operandInit, LispVal list, String prefix,
			java.util.function.UnaryOperator<LispVal> matchOf, boolean keepWhenMatch) {
		LispSymbol acc = new LispSymbol(prefix + "_acc");
		LispSymbol cur = new LispSymbol(prefix + "_cur");
		LispVal match = matchOf.apply(callOf(LispNames.CAR, cur));
		// (do ((operand operandInit) (acc nil) (cur list (cdr cur)))
		// ((atom cur) (reverse acc))
		// (if match nil (setq acc (cons (car cur) acc)))) ; keepWhenMatch swaps the
		// branches
		LispVal bindings = listToCons(
				List.of(listToCons(List.of(operand, operandInit)), listToCons(List.of(acc, LispNil.INSTANCE)),
						listToCons(List.of(cur, list, callOf(LispNames.CDR, cur)))));
		LispVal endClause = listToCons(List.of(callOf(LispNames.ATOM, cur), callOf(LispNames.NREVERSE, acc)));
		LispVal keep = listToCons(List.of(new LispSymbol(LispNames.SETQ), acc,
				listToCons(List.of(new LispSymbol(LispNames.CONS), callOf(LispNames.CAR, cur), acc))));
		LispVal body = keepWhenMatch ? makeIf(match, keep, LispNil.INSTANCE) : makeIf(match, LispNil.INSTANCE, keep);
		return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
	}

	/**
	 * Expands (last lst [n]) into a let/while walk returning the last cons cell -- or,
	 * with the optional count, the last {@code n} conses (CL's {@code last list
	 * &amp;optional n}). Without the count this is the one-cell walk; with it, the
	 * two-cursor walk of {@link #expandLastN}.
	 * @param cons the last expression
	 * @return the expanded expression
	 */
	public static LispVal expandLast(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2 || parts.size() > 3) {
			throw new UnsupportedOperationException("last expects 1 or 2 arguments, got " + (parts.size() - 1));
		}
		if (parts.size() == 3) {
			return expandLastN(parts.get(1), parts.get(2));
		}
		LispSymbol cur = new LispSymbol("__last_cur");
		// (while (and (consp __cur) (consp (cdr __cur))) (setq __cur (cdr __cur)))
		LispVal test = listToCons(List.of(new LispSymbol(LispNames.AND), callOf(LispNames.CONSP, cur),
				listToCons(List.of(new LispSymbol(LispNames.CONSP), callOf(LispNames.CDR, cur)))));
		LispVal step = listToCons(List.of(new LispSymbol(LispNames.SETQ), cur, callOf(LispNames.CDR, cur)));
		LispVal whileExpr = listToCons(List.of(new LispSymbol(LispNames.WHILE), test, step));
		LispVal bindings = new LispCons(listToCons(List.of(cur, parts.get(1))), LispNil.INSTANCE);
		return listToCons(List.of(new LispSymbol(LispNames.LET), bindings, whileExpr, cur));
	}

	/**
	 * Expands (last lst n) into the two-cursor walk that yields the last {@code n}
	 * conses: a lead cursor runs {@code n} cells ahead, then both advance until the lead
	 * falls off the end, leaving the trailing cursor on the answer.
	 *
	 * <pre>
	 * (let* ((__last_cur lst) (__last_lead __last_cur) (__last_n n))
	 *   (while (and (&gt; __last_n 0) (consp __last_lead))
	 *     (setq __last_lead (cdr __last_lead)) (setq __last_n (- __last_n 1)))
	 *   (while (consp __last_lead)
	 *     (setq __last_lead (cdr __last_lead)) (setq __last_cur (cdr __last_cur)))
	 *   __last_cur)
	 * </pre>
	 *
	 * {@code n} larger than the list answers the whole list, {@code n} of 0 answers the
	 * terminating atom (nil for a proper list, the dotted tail otherwise) -- both are
	 * CL's behavior, and both fall out of the shape rather than needing their own branch.
	 * @param listForm the list expression
	 * @param countForm the count expression
	 * @return the expanded expression
	 */
	private static LispVal expandLastN(LispVal listForm, LispVal countForm) {
		LispSymbol cur = new LispSymbol("__last_cur");
		LispSymbol lead = new LispSymbol("__last_lead");
		LispSymbol n = new LispSymbol("__last_n");
		LispVal stepLead = listToCons(List.of(new LispSymbol(LispNames.SETQ), lead, callOf(LispNames.CDR, lead)));
		LispVal skipTest = listToCons(List.of(new LispSymbol(LispNames.AND),
				listToCons(List.of(new LispSymbol(LispNames.GT), n, new LispInteger(0))),
				callOf(LispNames.CONSP, lead)));
		LispVal decrement = listToCons(List.of(new LispSymbol(LispNames.SETQ), n,
				listToCons(List.of(new LispSymbol(LispNames.SUB), n, new LispInteger(1)))));
		LispVal skip = listToCons(List.of(new LispSymbol(LispNames.WHILE), skipTest, stepLead, decrement));
		LispVal stepBoth = listToCons(List.of(new LispSymbol(LispNames.WHILE), callOf(LispNames.CONSP, lead), stepLead,
				listToCons(List.of(new LispSymbol(LispNames.SETQ), cur, callOf(LispNames.CDR, cur)))));
		// let* so the list is evaluated before the count (left-to-right argument order)
		// and the lead cursor starts from the already-evaluated list.
		LispVal bindings = listToCons(List.of(listToCons(List.of(cur, listForm)), listToCons(List.of(lead, cur)),
				listToCons(List.of(n, countForm))));
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), bindings, skip, stepBoth, cur));
	}

	private static final String DOLIST_CURSOR_VAR = "__dolist";

	/**
	 * Expands (with-open-file (var filename options...) body...) into open/close calls,
	 * closing on every exit via {@code unwind-protect}. The only supported option is
	 * {@code :direction} with a literal {@code :input} (default) or {@code :output}
	 * value, so the direction is known at expansion time and the compilers can pick the
	 * file mode statically.
	 *
	 * <pre>
	 * (with-open-file (s "f.txt" :direction :output) body...) ->
	 *   (let ((s (open "f.txt" :output)))
	 *     (unwind-protect (progn body...) (close s)))
	 * </pre>
	 * @param cons the with-open-file expression
	 * @return the expanded expression
	 */
	public static LispVal expandWithOpenFile(LispCons cons) {
		return expandWithOpenFile(cons, true);
	}

	/**
	 * Expands (with-open-file ...) with a backend switch: the WASM compilers pass
	 * {@code unwindProtect = false} to keep the close-after-body shape (close on normal
	 * exit only), because {@code unwind-protect} does not compile there -- a WASM error
	 * is an uncatchable trap, so there is nothing to clean up after anyway.
	 *
	 * <pre>
	 * unwindProtect = false:
	 * (with-open-file (s "f.txt" :direction :output) body...) ->
	 *   (let ((s (open "f.txt" :output)))
	 *     (let ((__wof_result (progn body...)))
	 *       (close s)
	 *       __wof_result))
	 * </pre>
	 * @param cons the with-open-file expression
	 * @param unwindProtect whether the expansion may use {@code unwind-protect}
	 * @return the expanded expression
	 */
	public static LispVal expandWithOpenFile(LispCons cons, boolean unwindProtect) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2 || !(parts.get(1) instanceof LispCons spec)) {
			throw new IllegalArgumentException(
					LispNames.WITH_OPEN_FILE + " expects a (var filename options...) spec as the first argument");
		}
		List<LispVal> specParts = spec.toList();
		if (specParts.size() < 2) {
			throw new IllegalArgumentException(
					LispNames.WITH_OPEN_FILE + " expects a (var filename options...) spec as the first argument");
		}
		LispVal var = specParts.get(0);
		LispVal filename = specParts.get(1);
		String direction = LispNames.INPUT_KEYWORD;
		boolean binary = false;
		for (int i = 2; i < specParts.size(); i += 2) {
			if (specParts.get(i) instanceof LispSymbol key && LispNames.DIRECTION_KEYWORD.equals(key.name())) {
				if (i + 1 >= specParts.size() || !(specParts.get(i + 1) instanceof LispSymbol dir)
						|| !(LispNames.INPUT_KEYWORD.equals(dir.name())
								|| LispNames.OUTPUT_KEYWORD.equals(dir.name()))) {
					throw new UnsupportedOperationException(
							LispNames.WITH_OPEN_FILE + " :direction must be the literal :input or :output");
				}
				direction = dir.name();
			}
			else if (specParts.get(i) instanceof LispSymbol key && LispNames.ELEMENT_TYPE_KEYWORD.equals(key.name())) {
				if (i + 1 >= specParts.size()) {
					throw new UnsupportedOperationException(LispNames.WITH_OPEN_FILE
							+ " :element-type must be the literal 'character or '(unsigned-byte 8)");
				}
				binary = isBinaryElementTypeLiteral(specParts.get(i + 1));
			}
			else if (specParts.get(i) instanceof LispSymbol key && (":EXTERNAL-FORMAT".equals(key.name())
					|| ":IF-EXISTS".equals(key.name()) || ":IF-DOES-NOT-EXIST".equals(key.name()))) {
				// Accepted and dropped like open's keyword normalization -- but only
				// with the value the native behavior already implements (UTF-8, the
				// create/supersede defaults); any other value must not be silently
				// reinterpreted. It signals at CALL time, not expansion time (the
				// undefined-function policy): the eager compile paths expand every
				// branch of a spliced library, and lack-middleware-backtrace's
				// file-output branch (:if-exists :append) is dead code in the default
				// *error-output* configuration.
				if (i + 1 >= specParts.size() || !ignorableOpenOptionValue(key.name(), specParts.get(i + 1))) {
					return callTimeUnsupportedStub(LispNames.WITH_OPEN_FILE + " " + key.name()
							+ " supports only the native default value (" + (":EXTERNAL-FORMAT".equals(key.name())
									? ":utf-8" : ":IF-EXISTS".equals(key.name()) ? ":supersede" : ":create or :error")
							+ ")");
				}
			}
			else {
				throw new UnsupportedOperationException(
						LispNames.WITH_OPEN_FILE + " supports only the :direction and :element-type options");
			}
		}
		List<LispVal> body = parts.subList(2, parts.size());
		List<LispVal> openParts = new java.util.ArrayList<>(
				List.of(new LispSymbol(LispNames.OPEN), filename, new LispSymbol(direction)));
		return buildWithOpenFile(var, openParts, binary, body, unwindProtect);
	}

	/**
	 * Expands {@code (with-open-stream (var stream-form) body...)}: binds the variable to
	 * an ALREADY-OPEN stream and closes it on exit -- {@code with-open-file}'s tail
	 * without the {@code open}. Same backend switch: the interpreter/JVM close through
	 * {@code unwind-protect}, the WASM compilers keep the close-after-body shape.
	 * @param cons the with-open-stream expression
	 * @param unwindProtect whether the expansion may use {@code unwind-protect}
	 * @return the expanded expression
	 */
	public static LispVal expandWithOpenStream(LispCons cons, boolean unwindProtect) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2 || !(parts.get(1) instanceof LispCons spec) || spec.toList().size() != 2) {
			throw new IllegalArgumentException(
					LispNames.WITH_OPEN_STREAM + " expects a (var stream-form) spec as the first argument");
		}
		List<LispVal> specParts = spec.toList();
		LispVal var = specParts.get(0);
		LispVal bodyExpr = prognOrNil(parts.subList(2, parts.size()));
		LispVal bindings = new LispCons(listToCons(List.of(var, specParts.get(1))), LispNil.INSTANCE);
		if (unwindProtect) {
			return listToCons(List.of(new LispSymbol(LispNames.LET), bindings,
					unwindProtectAround(bodyExpr, callOf(LispNames.CLOSE, var))));
		}
		LispSymbol result = new LispSymbol(WOF_RESULT_VAR);
		LispVal innerBindings = new LispCons(listToCons(List.of(result, bodyExpr)), LispNil.INSTANCE);
		LispVal innerLet = listToCons(
				List.of(new LispSymbol(LispNames.LET), innerBindings, callOf(LispNames.CLOSE, var), result));
		return listToCons(List.of(new LispSymbol(LispNames.LET), bindings, innerLet));
	}

	/**
	 * Whether an ignorable {@code open}/{@code with-open-file} option carries the value
	 * the native file behavior already implements: {@code :external-format :utf-8},
	 * {@code :if-exists :supersede} (output truncates), {@code :if-does-not-exist}
	 * {@code :create} (output) or {@code :error} (input).
	 * @param option the option keyword name
	 * @param value the option value form
	 * @return {@code true} when dropping the pair preserves behavior
	 */
	public static boolean ignorableOpenOptionValue(String option, LispVal value) {
		if (!(value instanceof LispSymbol sym)) {
			return false;
		}
		return switch (option) {
			case ":EXTERNAL-FORMAT" -> ":UTF-8".equals(sym.name()) || ":DEFAULT".equals(sym.name());
			case ":IF-EXISTS" -> ":SUPERSEDE".equals(sym.name());
			case ":IF-DOES-NOT-EXIST" -> ":CREATE".equals(sym.name()) || ":ERROR".equals(sym.name());
			default -> false;
		};
	}

	private static LispVal buildWithOpenFile(LispVal var, List<LispVal> openParts, boolean binary, List<LispVal> body,
			boolean unwindProtect) {
		if (binary) {
			openParts.add(unsignedByte8Literal());
		}
		LispVal openCall = listToCons(openParts);
		LispVal bodyExpr = prognOrNil(body);
		LispVal outerBindings = new LispCons(listToCons(List.of(var, openCall)), LispNil.INSTANCE);
		if (unwindProtect) {
			// (let ((var (open filename direction)))
			// (unwind-protect body-expr (close var)))
			return listToCons(List.of(new LispSymbol(LispNames.LET), outerBindings,
					unwindProtectAround(bodyExpr, callOf(LispNames.CLOSE, var))));
		}
		LispSymbol result = new LispSymbol(WOF_RESULT_VAR);
		// (let ((__wof_result body-expr)) (close var) __wof_result)
		LispVal innerBindings = new LispCons(listToCons(List.of(result, bodyExpr)), LispNil.INSTANCE);
		LispVal innerLet = listToCons(
				List.of(new LispSymbol(LispNames.LET), innerBindings, callOf(LispNames.CLOSE, var), result));
		// (let ((var (open filename direction))) inner-let)
		return listToCons(List.of(new LispSymbol(LispNames.LET), outerBindings, innerLet));
	}

	/**
	 * Wraps a form in {@code (unwind-protect form cleanup)} so the cleanup runs on every
	 * exit -- normal return, an error unwind and a {@code return}/{@code return-from}
	 * non-local exit.
	 */
	private static LispVal unwindProtectAround(LispVal protectedForm, LispVal cleanup) {
		return listToCons(List.of(new LispSymbol(LispNames.UNWIND_PROTECT), protectedForm, cleanup));
	}

	private static final String WOF_RESULT_VAR = "__wof_result";

	/**
	 * Expands (with-output-to-string (var) body...) into a string-builder stream bound to
	 * {@code var}; every stream-directed output form in the body appends, and the whole
	 * form returns the accumulated string.
	 *
	 * <pre>
	 * (with-output-to-string (s) body...) ->
	 *   (let ((s (%make-string-output-stream)))
	 *     (unwind-protect (progn body... (%string-stream-contents s)) (close s)))
	 * </pre>
	 * @param cons the with-output-to-string expression
	 * @return the expanded expression
	 */
	public static LispVal expandWithOutputToString(LispCons cons) {
		return expandWithOutputToString(cons, true);
	}

	/**
	 * Expands (with-output-to-string ...) with a backend switch: the WASM compilers pass
	 * {@code unwindProtect = false} to keep the close-after-body shape (close on normal
	 * exit only), because {@code unwind-protect} does not compile there.
	 *
	 * <pre>
	 * unwindProtect = false:
	 * (with-output-to-string (s) body...) ->
	 *   (let ((s (%make-string-output-stream)))
	 *     (progn body...)
	 *     (let ((__wots_result (%string-stream-contents s)))
	 *       (close s)
	 *       __wots_result))
	 * </pre>
	 * @param cons the with-output-to-string expression
	 * @param unwindProtect whether the expansion may use {@code unwind-protect}
	 * @return the expanded expression
	 */
	public static LispVal expandWithOutputToString(LispCons cons, boolean unwindProtect) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2 || !(parts.get(1) instanceof LispCons spec) || !(spec.car() instanceof LispSymbol var)) {
			throw new IllegalArgumentException(
					LispNames.WITH_OUTPUT_TO_STRING + " expects a (var ...) spec as the first argument");
		}
		// CL spec is (var &optional string-form &key element-type). The fresh-string
		// behaviour (string-form nil/absent) is the supported case; :element-type is
		// accepted and ignored (lite -- cl-who passes (s nil :element-type 'character)).
		// A non-nil string-form (append to an existing fill-pointered string) is not
		// supported.
		List<LispVal> specParts = spec.toList();
		if (specParts.size() >= 2 && specParts.get(1) != LispNil.INSTANCE) {
			throw new UnsupportedOperationException(
					LispNames.WITH_OUTPUT_TO_STRING + " supports only a nil string-form (fresh-string) spec");
		}
		LispVal bindings = new LispCons(
				listToCons(List.of(var,
						listToCons(List.of(new LispSymbol(LispNames.MAKE_STRING_OUTPUT_STREAM_INTERNAL))))),
				LispNil.INSTANCE);
		if (unwindProtect) {
			// (let ((var (%make-string-output-stream)))
			// (unwind-protect (progn body... (%string-stream-contents var)) (close var)))
			List<LispVal> protectedParts = new java.util.ArrayList<>();
			protectedParts.add(new LispSymbol(LispNames.PROGN));
			protectedParts.addAll(parts.subList(2, parts.size()));
			protectedParts.add(callOf(LispNames.STRING_STREAM_CONTENTS_INTERNAL, var));
			return listToCons(List.of(new LispSymbol(LispNames.LET), bindings,
					unwindProtectAround(listToCons(protectedParts), callOf(LispNames.CLOSE, var))));
		}
		LispVal bodyExpr = prognOrNil(parts.subList(2, parts.size()));
		LispSymbol result = new LispSymbol(WOTS_RESULT_VAR);
		// (let ((__wots_result (%string-stream-contents var))) (close var) __wots_result)
		LispVal innerBindings = new LispCons(
				listToCons(List.of(result, callOf(LispNames.STRING_STREAM_CONTENTS_INTERNAL, var))), LispNil.INSTANCE);
		LispVal innerLet = listToCons(
				List.of(new LispSymbol(LispNames.LET), innerBindings, callOf(LispNames.CLOSE, var), result));
		return listToCons(List.of(new LispSymbol(LispNames.LET), bindings, bodyExpr, innerLet));
	}

	private static final String WOTS_RESULT_VAR = "__wots_result";

	/**
	 * Expands (with-input-from-string (var string) body...) into a string-backed input
	 * stream bound to {@code var}; {@code read}/{@code read-line} consume from the
	 * string.
	 *
	 * <pre>
	 * (with-input-from-string (s "text") body...) ->
	 *   (let ((s (%make-string-input-stream "text")))
	 *     (unwind-protect (progn body...) (close s)))
	 * </pre>
	 * @param cons the with-input-from-string expression
	 * @return the expanded expression
	 */
	public static LispVal expandWithInputFromString(LispCons cons) {
		return expandWithInputFromString(cons, true);
	}

	/**
	 * Expands (with-input-from-string ...) with a backend switch: the WASM compilers pass
	 * {@code unwindProtect = false} to keep the close-after-body shape (close on normal
	 * exit only), because {@code unwind-protect} does not compile there.
	 *
	 * <pre>
	 * unwindProtect = false:
	 * (with-input-from-string (s "text") body...) ->
	 *   (let ((s (%make-string-input-stream "text")))
	 *     (let ((__wifs_result (progn body...)))
	 *       (close s)
	 *       __wifs_result))
	 * </pre>
	 * @param cons the with-input-from-string expression
	 * @param unwindProtect whether the expansion may use {@code unwind-protect}
	 * @return the expanded expression
	 */
	public static LispVal expandWithInputFromString(LispCons cons, boolean unwindProtect) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2 || !(parts.get(1) instanceof LispCons spec)) {
			throw new IllegalArgumentException(
					LispNames.WITH_INPUT_FROM_STRING + " expects a (var string) spec as the first argument");
		}
		List<LispVal> specParts = spec.toList();
		if (specParts.size() != 2 || !(specParts.get(0) instanceof LispSymbol var)) {
			throw new UnsupportedOperationException(
					LispNames.WITH_INPUT_FROM_STRING + " supports only a (var string) spec");
		}
		LispVal string = specParts.get(1);
		LispVal bodyExpr = prognOrNil(parts.subList(2, parts.size()));
		LispVal openCall = listToCons(List.of(new LispSymbol(LispNames.MAKE_STRING_INPUT_STREAM_INTERNAL), string));
		LispVal outerBindings = new LispCons(listToCons(List.of(var, openCall)), LispNil.INSTANCE);
		if (unwindProtect) {
			// (let ((var (%make-string-input-stream string)))
			// (unwind-protect body-expr (close var)))
			return listToCons(List.of(new LispSymbol(LispNames.LET), outerBindings,
					unwindProtectAround(bodyExpr, callOf(LispNames.CLOSE, var))));
		}
		LispSymbol result = new LispSymbol(WIFS_RESULT_VAR);
		// (let ((__wifs_result body-expr)) (close var) __wifs_result)
		LispVal innerBindings = new LispCons(listToCons(List.of(result, bodyExpr)), LispNil.INSTANCE);
		LispVal innerLet = listToCons(
				List.of(new LispSymbol(LispNames.LET), innerBindings, callOf(LispNames.CLOSE, var), result));
		return listToCons(List.of(new LispSymbol(LispNames.LET), outerBindings, innerLet));
	}

	private static final String WIFS_RESULT_VAR = "__wifs_result";

	/**
	 * Expands {@code (make-string-output-stream)} -- CL's public spelling of the internal
	 * {@code (%make-string-output-stream)} that {@code with-output-to-string} is built
	 * on. CL's lambda list is {@code (&key element-type)}; every rontolisp stream is a
	 * character stream, so the option is accepted and dropped (the
	 * {@code with-output-to-string} precedent).
	 * @param cons the make-string-output-stream expression
	 * @return the expanded expression
	 */
	public static LispVal expandMakeStringOutputStream(LispCons cons) {
		List<LispVal> parts = cons.toList();
		for (int i = 1; i < parts.size(); i += 2) {
			if (i + 1 >= parts.size() || !(parts.get(i) instanceof LispSymbol key) || !key.isKeyword()) {
				throw new UnsupportedOperationException(
						LispNames.MAKE_STRING_OUTPUT_STREAM + " expects keyword arguments only");
			}
		}
		return listToCons(List.of(new LispSymbol(LispNames.MAKE_STRING_OUTPUT_STREAM_INTERNAL)));
	}

	/**
	 * Expands {@code (get-output-stream-string stream)} into the internal
	 * {@code (%string-stream-contents stream)}, which answers what the string output
	 * stream has accumulated AND clears it -- CL's contract, so a second call sees only
	 * what was written after the first.
	 * @param cons the get-output-stream-string expression
	 * @return the expanded expression
	 */
	public static LispVal expandGetOutputStreamString(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new UnsupportedOperationException(
					LispNames.GET_OUTPUT_STREAM_STRING + " expects 1 argument, got " + (parts.size() - 1));
		}
		return callOf(LispNames.STRING_STREAM_CONTENTS_INTERNAL, parts.get(1));
	}

	/** Fixed temporaries of the {@code peek-char} skip-loop expansion. */
	private static final String PEEK_TYPE_VAR = "__pc_type";

	private static final String PEEK_STREAM_VAR = "__pc_stream";

	private static final String PEEK_ERRP_VAR = "__pc_errp";

	private static final String PEEK_VALUE_VAR = "__pc_value";

	private static final String PEEK_CHAR_VAR = "__pc_char";

	/**
	 * Expands {@code (peek-char [peek-type [stream [eof-error-p [eof-value]]]])}. The
	 * {@code peek-type} nil form -- the one that just looks at the next character --
	 * lowers straight onto the {@code %peek-char} primitive every backend implements. The
	 * two SKIPPING forms are lowered here instead of per backend, so all four share one
	 * loop: {@code t} skips whitespace and a character skips up to that character, in
	 * both cases leaving the character it stopped on in the stream (CL 21.2).
	 *
	 * <pre>
	 * (peek-char t s) ->
	 *   (do ((__pc_char (%peek-char s t nil) (%peek-char s t nil)))
	 *       ((or (not (characterp __pc_char)) (not &lt;whitespace __pc_char&gt;)) __pc_char)
	 *     (read-char s nil nil))
	 * </pre>
	 *
	 * A non-literal {@code peek-type} keeps the same shape behind a runtime
	 * {@code (null __pc_type)} test, so {@code #'peek-char} works as a first-class value
	 * too. The {@code characterp} guard is what ends the loop when {@code eof-error-p} is
	 * nil: the eof-value is returned rather than skipped over forever.
	 * @param cons the peek-char expression
	 * @return the expanded expression
	 */
	public static LispVal expandPeekChar(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() > 5) {
			throw new UnsupportedOperationException(
					LispNames.PEEK_CHAR + " expects 0 to 4 arguments, got " + (parts.size() - 1));
		}
		LispVal peekType = parts.size() > 1 ? parts.get(1) : LispNil.INSTANCE;
		LispVal stream = parts.size() > 2 ? parts.get(2) : LispNil.INSTANCE;
		LispVal eofErrorP = parts.size() > 3 ? parts.get(3) : LispTrue.INSTANCE;
		LispVal eofValue = parts.size() > 4 ? parts.get(4) : LispNil.INSTANCE;
		if (isLiteralNil(peekType)) {
			return fmtCall(LispNames.PEEK_CHAR_INTERNAL, stream, eofErrorP, eofValue);
		}
		LispSymbol streamVar = new LispSymbol(PEEK_STREAM_VAR);
		LispSymbol errpVar = new LispSymbol(PEEK_ERRP_VAR);
		LispSymbol valueVar = new LispSymbol(PEEK_VALUE_VAR);
		LispSymbol charVar = new LispSymbol(PEEK_CHAR_VAR);
		LispSymbol typeVar = new LispSymbol(PEEK_TYPE_VAR);
		boolean literalType = peekType == LispTrue.INSTANCE || peekType instanceof LispChar;
		List<LispVal> bindings = new ArrayList<>();
		if (!literalType) {
			bindings.add(listToCons(List.of(typeVar, peekType)));
		}
		bindings.add(listToCons(List.of(streamVar, stream)));
		bindings.add(listToCons(List.of(errpVar, eofErrorP)));
		bindings.add(listToCons(List.of(valueVar, eofValue)));
		LispVal peek = fmtCall(LispNames.PEEK_CHAR_INTERNAL, streamVar, errpVar, valueVar);
		LispVal stop;
		if (peekType == LispTrue.INSTANCE) {
			stop = callOf(LispNames.NOT, whitespaceCharTest(charVar));
		}
		else if (peekType instanceof LispChar) {
			stop = fmtCall(LispNames.CHAR_EQ, charVar, peekType);
		}
		else {
			stop = listToCons(List.of(new LispSymbol(LispNames.IF),
					fmtCall(LispNames.EQ_GENERAL, typeVar, LispTrue.INSTANCE),
					callOf(LispNames.NOT, whitespaceCharTest(charVar)), fmtCall(LispNames.CHAR_EQ, charVar, typeVar)));
		}
		LispVal endTest = fmtCall(LispNames.OR, callOf(LispNames.NOT, callOf(LispNames.CHARACTERP, charVar)), stop);
		LispVal loop = listToCons(List.of(new LispSymbol(LispNames.DO),
				listToCons(List.of(listToCons(List.of(charVar, peek, peek)))), listToCons(List.of(endTest, charVar)),
				fmtCall(LispNames.READ_CHAR, streamVar, LispNil.INSTANCE, LispNil.INSTANCE)));
		LispVal body = literalType ? loop
				: listToCons(List.of(new LispSymbol(LispNames.IF), callOf(LispNames.NULL, typeVar),
						fmtCall(LispNames.PEEK_CHAR_INTERNAL, streamVar, errpVar, valueVar), loop));
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), listToCons(bindings), body));
	}

	/**
	 * {@code (or (char= c #\Space) ...)} over the five characters CL calls whitespace in
	 * the standard readtable -- the set {@code peek-char}'s {@code t} peek-type skips.
	 */
	private static LispVal whitespaceCharTest(LispSymbol charVar) {
		List<LispVal> tests = new ArrayList<>();
		for (int code : new int[] { ' ', '\t', '\n', '\r', '\f' }) {
			tests.add(fmtCall(LispNames.CHAR_EQ, charVar, new LispChar(code)));
		}
		return fmtCall(LispNames.OR, tests.toArray(new LispVal[0]));
	}

	/**
	 * Expands {@code (make-synonym-stream 'sym)} into a READ of the variable the symbol
	 * names -- {@code (make-synonym-stream '*standard-output*)} is literally
	 * {@code *standard-output*}, so the result is whatever stream designator that
	 * variable holds, and a program that never binds it gets the constant {@code t}
	 * (standard output) with no new machinery on any backend.
	 *
	 * <p>
	 * {@code (make-synonym-stream '*standard-output*)} and its {@code *standard-input*}
	 * twin are the cases that are NOT snapshots: each answers the {@code nil} DESIGNATOR,
	 * which every output (resp. input) operation resolves through
	 * {@code *standard-output*} / {@code *standard-input*} at the time of that operation
	 * ({@code StreamDesignators}, {@code .kb/standard-output-redirect.md}) -- so that
	 * synonym forwards per-operation exactly like CL's, with no new stream kind.
	 *
	 * <p>
	 * For any OTHER symbol the expansion stays LITE, and the divergence is deliberate:
	 * CL's synonym stream forwards every operation to the symbol's value at the time of
	 * that operation, while this one resolves the symbol ONCE, where the stream is
	 * constructed. Reason for the divergence: a per-operation synonym over an ARBITRARY
	 * symbol needs a stream-designator kind carrying that symbol which the write helpers
	 * of all four backends resolve at run time -- {@code nil} is the only designator the
	 * helpers already have, and it names exactly the standard streams. No known consumer
	 * needs more (postmodern's {@code config.lisp:224} {@code *json-output*} defvar
	 * constructs once and never rebinds). RE-EVALUATION TRIGGER: if a consumer ever
	 * rebinds the symbol behind a non-standard synonym stream, the runtime needs that
	 * designator kind and this whole expansion has to go.
	 * @param cons the make-synonym-stream expression
	 * @return the expanded expression
	 */
	public static LispVal expandMakeSynonymStream(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new UnsupportedOperationException(
					LispNames.MAKE_SYNONYM_STREAM + " expects 1 argument, got " + (parts.size() - 1));
		}
		LispSymbol quoted = quotedSymbol(parts.get(1));
		if (quoted == null) {
			return callOf(LispNames.SYMBOL_VALUE, parts.get(1));
		}
		if (LispNames.STANDARD_OUTPUT_VAR.equals(quoted.name()) || LispNames.STANDARD_INPUT_VAR.equals(quoted.name())) {
			return LispNil.INSTANCE;
		}
		return new LispSymbol(quoted.name());
	}

	/** Fixed temporaries of the read-family end-of-file lowering. */
	private static final String EOF_STREAM_VAR = "__eof_stream";

	private static final String EOF_ERRP_VAR = "__eof_errp";

	private static final String EOF_VALUE_VAR = "__eof_value";

	private static final String EOF_RESULT_VAR = "__eof_result";

	/**
	 * Rewrites a {@code read-char} / {@code read-line} / {@code read-byte} call whose
	 * end-of-file must SIGNAL so that it signals the registered {@code end-of-file}
	 * condition class rather than a plain error -- CL 21.2, and the reason
	 * {@code (handler-case ... (end-of-file () ...))} around a lexer loop fires at all.
	 * The three operators share one shape, because on every backend a successful read
	 * answers a character / a string / an integer and NEVER nil: passing the built-in's
	 * own {@code (nil nil)} eof parameters turns end-of-file into a nil result the
	 * expansion can test.
	 *
	 * <pre>
	 * (read-char s) ->
	 *   (let* ((__eof_stream s)
	 *          (__eof_result (read-char __eof_stream nil nil)))
	 *     (if (null __eof_result) (error 'end-of-file) __eof_result))
	 * </pre>
	 *
	 * Returns {@code null} when the call cannot signal (an eof-error-p that is literally
	 * nil, or an omitted one on the operators whose rontolisp default is nil), so the
	 * caller compiles the form unchanged and every such program keeps its existing output
	 * byte for byte. A NON-literal eof-error-p keeps the same shape with the eof-value /
	 * signal choice made at run time.
	 * @param cons the read-family call
	 * @param signalsByDefault whether an omitted eof-error-p means "signal" for this
	 * operator ({@code read-char} / {@code read-byte} yes, {@code read-line} no)
	 * @return the lowered form, or null when the call cannot reach the signalling branch
	 */
	public static @Nullable LispVal expandReadEofSignal(LispCons cons, boolean signalsByDefault) {
		List<LispVal> parts = cons.toList();
		if (parts.size() > 4 || !(cons.car() instanceof LispSymbol op)) {
			return null;
		}
		LispVal eofErrorP = parts.size() > 2 ? parts.get(2) : (signalsByDefault ? LispTrue.INSTANCE : LispNil.INSTANCE);
		if (isLiteralNil(eofErrorP)) {
			return null;
		}
		LispVal stream = parts.size() > 1 ? parts.get(1) : LispNil.INSTANCE;
		LispVal eofValue = parts.size() > 3 ? parts.get(3) : LispNil.INSTANCE;
		LispSymbol streamVar = new LispSymbol(EOF_STREAM_VAR);
		LispSymbol errpVar = new LispSymbol(EOF_ERRP_VAR);
		LispSymbol valueVar = new LispSymbol(EOF_VALUE_VAR);
		LispSymbol resultVar = new LispSymbol(EOF_RESULT_VAR);
		boolean staticSignal = eofErrorP == LispTrue.INSTANCE;
		List<LispVal> bindings = new ArrayList<>();
		bindings.add(listToCons(List.of(streamVar, stream)));
		if (!staticSignal) {
			bindings.add(listToCons(List.of(errpVar, eofErrorP)));
			bindings.add(listToCons(List.of(valueVar, eofValue)));
		}
		bindings.add(listToCons(List.of(resultVar, fmtCall(op.name(), streamVar, LispNil.INSTANCE, LispNil.INSTANCE))));
		LispVal signal = endOfFileSignal();
		LispVal onEof = staticSignal ? signal
				: listToCons(List.of(new LispSymbol(LispNames.IF), errpVar, signal, valueVar));
		LispVal test = listToCons(
				List.of(new LispSymbol(LispNames.IF), callOf(LispNames.NULL, resultVar), onEof, resultVar));
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), listToCons(bindings), test));
	}

	/**
	 * {@code (error 'end-of-file)} -- the seeded condition class, whose {@code :report}
	 * renders the message every backend prints when nothing catches it.
	 * @return the signalling form
	 */
	public static LispVal endOfFileSignal() {
		return callOf(LispNames.ERROR, quoteOf(ClosRegistry.END_OF_FILE_CLASS_NAME));
	}

	/**
	 * Expands {@code (rontolisp:with-arena () body...)} into {@code (progn body...)}.
	 * {@code with-arena} names a reclamation boundary for the {@code --no-gc} WASM
	 * backend, which lowers it natively to a bump heap-pointer mark / body / reset with
	 * the body's value copied down to the mark; on the interpreter, the JVM backend and
	 * wasm-GC a real garbage collector already reclaims, so the boundary is
	 * observationally a plain {@code progn}. The option list is reserved and must be
	 * empty. Escape contract (enforced only by the {@code --no-gc} lowering): nothing
	 * allocated inside the body may be reachable after it, except the body's own value.
	 * @param cons the with-arena expression
	 * @return the expanded expression
	 */
	public static LispVal expandWithArena(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2 || !(parts.get(1) instanceof LispNil)) {
			throw new UnsupportedOperationException(LispNames.WITH_ARENA_QUALIFIED
					+ " expects an empty option list: (rontolisp:with-arena () body...)");
		}
		return prognOrNil(parts.subList(2, parts.size()));
	}

	private static final String MUTEX_ACQUIRE_QUALIFIED = LispNames.RONTOLISP_PKG + ":" + LispNames.MUTEX_ACQUIRE;

	private static final String MUTEX_RELEASE_QUALIFIED = LispNames.RONTOLISP_PKG + ":" + LispNames.MUTEX_RELEASE;

	private static final String MUTEX_VAR = "__mutex_lock";

	private static final String MUTEX_RESULT_VAR = "__mutex_result";

	/**
	 * Expands {@code (rontolisp:with-mutex (mutex-form) body...)} into a {@code let} that
	 * evaluates the mutex form ONCE, acquires it, runs the body and releases it on every
	 * exit. {@code (bordeaux-threads:with-lock-held (lock) body...)} has the same shape
	 * and expands through here.
	 * @param cons the with-mutex / with-lock-held expression
	 * @return the expanded expression
	 */
	public static LispVal expandWithMutex(LispCons cons) {
		return expandWithMutex(cons, true);
	}

	/**
	 * Expands (rontolisp:with-mutex ...) with the backend switch. Without
	 * {@code unwind-protect} the release runs on normal exit only -- exact on the WASM
	 * backends, where acquire and release are no-ops (single-threaded by construction),
	 * and the reason {@code with-mutex} does NOT flip a WASM module into EH mode: paying
	 * the EH lowering to guarantee a no-op runs would buy nothing.
	 * @param cons the with-mutex / with-lock-held expression
	 * @param unwindProtect whether the expansion may use {@code unwind-protect}
	 * @return the expanded expression
	 */
	public static LispVal expandWithMutex(LispCons cons, boolean unwindProtect) {
		List<LispVal> parts = cons.toList();
		String name = parts.get(0).print();
		if (parts.size() < 2 || !(parts.get(1) instanceof LispCons spec) || !(spec.cdr() instanceof LispNil)) {
			throw new UnsupportedOperationException(
					name + " expects a one-element lock spec: (" + name + " (mutex-form) body...)");
		}
		LispSymbol var = new LispSymbol(MUTEX_VAR);
		LispVal bindings = new LispCons(listToCons(List.of(var, spec.car())), LispNil.INSTANCE);
		List<LispVal> body = parts.subList(2, parts.size());
		LispVal release = callOf(MUTEX_RELEASE_QUALIFIED, var);
		LispVal guarded;
		if (unwindProtect) {
			guarded = unwindProtectAround(prognOrNil(body), release);
		}
		else {
			LispSymbol result = new LispSymbol(MUTEX_RESULT_VAR);
			guarded = listToCons(List.of(new LispSymbol(LispNames.LET),
					new LispCons(listToCons(List.of(result, prognOrNil(body))), LispNil.INSTANCE), release, result));
		}
		return listToCons(
				List.of(new LispSymbol(LispNames.LET), bindings, callOf(MUTEX_ACQUIRE_QUALIFIED, var), guarded));
	}

	private static final String USOCKET_SOCKET_CONNECT_QUALIFIED = LispNames.USOCKET_PKG + ":"
			+ LispNames.USOCKET_SOCKET_CONNECT;

	private static final String USOCKET_SOCKET_STREAM_QUALIFIED = LispNames.USOCKET_PKG + ":SOCKET-STREAM";

	private static final String USOCKET_SOCKET_CLOSE_QUALIFIED = LispNames.USOCKET_PKG + ":SOCKET-CLOSE";

	private static final String USOCKET_SOCKET_LISTEN_QUALIFIED = LispNames.USOCKET_PKG + ":SOCKET-LISTEN";

	private static final String USOCKET_RESULT_VAR = "__usocket_result";

	/**
	 * Expands {@code (usocket:with-client-socket (socket stream host port
	 * connect-args...) body...)} into a {@code let*} that connects, binds {@code socket}
	 * and (when the {@code stream} variable is not {@code nil}) its stream, runs the body
	 * and closes the socket on every exit via {@code unwind-protect} (usocket proper's
	 * semantics). On the WASM backends ({@code unwindProtect = false}, no
	 * {@code unwind-protect} there) the socket is closed on normal exit only.
	 * @param cons the with-client-socket expression
	 * @return the expanded expression
	 */
	public static LispVal expandUsocketWithClientSocket(LispCons cons) {
		return expandUsocketWithClientSocket(cons, true);
	}

	/**
	 * Expands (usocket:with-client-socket ...) with the backend switch described above.
	 * @param cons the with-client-socket expression
	 * @param unwindProtect whether the expansion may use {@code unwind-protect}
	 * @return the expanded expression
	 */
	public static LispVal expandUsocketWithClientSocket(LispCons cons, boolean unwindProtect) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2 || !(parts.get(1) instanceof LispCons spec)) {
			throw new UnsupportedOperationException(LispNames.USOCKET_WITH_CLIENT_SOCKET_QUALIFIED
					+ " expects (socket-var stream-var host port connect-args...)");
		}
		List<LispVal> specParts = spec.toList();
		if (specParts.size() < 4 || !(specParts.get(0) instanceof LispSymbol socketVar)) {
			throw new UnsupportedOperationException(LispNames.USOCKET_WITH_CLIENT_SOCKET_QUALIFIED
					+ " expects (socket-var stream-var host port connect-args...)");
		}
		LispVal streamSpec = specParts.get(1);
		List<LispVal> connectCall = new java.util.ArrayList<>();
		connectCall.add(new LispSymbol(USOCKET_SOCKET_CONNECT_QUALIFIED));
		connectCall.addAll(specParts.subList(2, specParts.size()));
		List<LispVal> bindings = new java.util.ArrayList<>();
		bindings.add(listToCons(List.of(socketVar, listToCons(connectCall))));
		if (streamSpec instanceof LispSymbol streamVar) {
			bindings.add(listToCons(List.of(streamVar, callOf(USOCKET_SOCKET_STREAM_QUALIFIED, socketVar))));
		}
		else if (!(streamSpec instanceof LispNil)) {
			throw new UnsupportedOperationException(LispNames.USOCKET_WITH_CLIENT_SOCKET_QUALIFIED
					+ " expects a stream variable (or nil), got: " + streamSpec.print());
		}
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), listToCons(bindings),
				usocketCloseBody(socketVar, parts.subList(2, parts.size()), unwindProtect)));
	}

	/**
	 * Expands {@code (usocket:with-connected-socket (var socket-form) body...)} (and its
	 * alias {@code usocket:with-server-socket}) into a {@code let} that binds {@code var}
	 * to the socket, runs the body and closes it on every exit (normal exit only on the
	 * WASM backends).
	 * @param cons the with-connected-socket / with-server-socket expression
	 * @return the expanded expression
	 */
	public static LispVal expandUsocketWithConnectedSocket(LispCons cons) {
		return expandUsocketWithConnectedSocket(cons, true);
	}

	/**
	 * Expands (usocket:with-connected-socket ...) with the backend switch described
	 * above.
	 * @param cons the with-connected-socket / with-server-socket expression
	 * @param unwindProtect whether the expansion may use {@code unwind-protect}
	 * @return the expanded expression
	 */
	public static LispVal expandUsocketWithConnectedSocket(LispCons cons, boolean unwindProtect) {
		List<LispVal> parts = cons.toList();
		String name = parts.get(0).print();
		if (parts.size() < 2 || !(parts.get(1) instanceof LispCons spec)) {
			throw new UnsupportedOperationException(name + " expects (var socket-form)");
		}
		List<LispVal> specParts = spec.toList();
		if (specParts.size() != 2 || !(specParts.get(0) instanceof LispSymbol var)) {
			throw new UnsupportedOperationException(name + " expects (var socket-form)");
		}
		LispVal bindings = new LispCons(listToCons(List.of(var, specParts.get(1))), LispNil.INSTANCE);
		return listToCons(List.of(new LispSymbol(LispNames.LET), bindings,
				usocketCloseBody(var, parts.subList(2, parts.size()), unwindProtect)));
	}

	/**
	 * Expands {@code (usocket:with-socket-listener (var host port listen-args...)
	 * body...)} into a {@code let} that listens, binds {@code var}, runs the body and
	 * closes the listener on every exit (normal exit only on the WASM backends).
	 * @param cons the with-socket-listener expression
	 * @return the expanded expression
	 */
	public static LispVal expandUsocketWithSocketListener(LispCons cons) {
		return expandUsocketWithSocketListener(cons, true);
	}

	/**
	 * Expands (usocket:with-socket-listener ...) with the backend switch described above.
	 * @param cons the with-socket-listener expression
	 * @param unwindProtect whether the expansion may use {@code unwind-protect}
	 * @return the expanded expression
	 */
	public static LispVal expandUsocketWithSocketListener(LispCons cons, boolean unwindProtect) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2 || !(parts.get(1) instanceof LispCons spec)) {
			throw new UnsupportedOperationException(
					LispNames.USOCKET_WITH_SOCKET_LISTENER_QUALIFIED + " expects (var host port listen-args...)");
		}
		List<LispVal> specParts = spec.toList();
		if (specParts.size() < 3 || !(specParts.get(0) instanceof LispSymbol var)) {
			throw new UnsupportedOperationException(
					LispNames.USOCKET_WITH_SOCKET_LISTENER_QUALIFIED + " expects (var host port listen-args...)");
		}
		List<LispVal> listenCall = new java.util.ArrayList<>();
		listenCall.add(new LispSymbol(USOCKET_SOCKET_LISTEN_QUALIFIED));
		listenCall.addAll(specParts.subList(1, specParts.size()));
		LispVal bindings = new LispCons(listToCons(List.of(var, listToCons(listenCall))), LispNil.INSTANCE);
		return listToCons(List.of(new LispSymbol(LispNames.LET), bindings,
				usocketCloseBody(var, parts.subList(2, parts.size()), unwindProtect)));
	}

	/**
	 * Builds the shared tail of the usocket {@code with-*} expansions:
	 * {@code (unwind-protect (progn body...) (usocket:socket-close var))}, or -- when
	 * {@code unwind-protect} is unavailable ({@code unwindProtect = false}, the WASM
	 * backends) -- the close-after-body shape
	 * {@code (let ((__usocket_result (progn body...))) (usocket:socket-close var)
	 * __usocket_result)}.
	 */
	private static LispVal usocketCloseBody(LispSymbol var, List<LispVal> body, boolean unwindProtect) {
		if (unwindProtect) {
			return unwindProtectAround(prognOrNil(body), callOf(USOCKET_SOCKET_CLOSE_QUALIFIED, var));
		}
		LispSymbol result = new LispSymbol(USOCKET_RESULT_VAR);
		LispVal innerBindings = new LispCons(listToCons(List.of(result, prognOrNil(body))), LispNil.INSTANCE);
		return listToCons(List.of(new LispSymbol(LispNames.LET), innerBindings,
				callOf(USOCKET_SOCKET_CLOSE_QUALIFIED, var), result));
	}

	/**
	 * Expands the {@code (usocket::%usock-guard form)} internal wrapper of the usocket
	 * shim's socket operations. With {@code handlerCase} (interpreter/JVM) the form runs
	 * under {@code (handler-case form (error (c) (usocket::%usock-resignal c)))}, so an
	 * underlying failure is re-signaled as a typed {@code usocket:socket-error}
	 * (catchable, message preserved by the condition's {@code :report}); on WASM
	 * ({@code handlerCase = false}, errors are uncatchable traps) the form passes through
	 * unchanged.
	 * @param cons the %usock-guard expression
	 * @param handlerCase whether the expansion may use {@code handler-case}
	 * @return the expanded expression
	 */
	public static LispVal expandUsocketGuard(LispCons cons, boolean handlerCase) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException(
					LispNames.USOCKET_GUARD_QUALIFIED + " expects exactly one form: " + cons.print());
		}
		if (!handlerCase) {
			return parts.get(1);
		}
		LispSymbol condVar = new LispSymbol("__usock_cond");
		LispVal resignal = callOf(LispNames.USOCKET_PKG + "::%USOCK-RESIGNAL", condVar);
		LispVal clause = listToCons(List.of(new LispSymbol("ERROR"), listToCons(List.<LispVal>of(condVar)), resignal));
		return listToCons(List.of(new LispSymbol(LispNames.HANDLER_CASE), parts.get(1), clause));
	}

	/**
	 * Wraps a macro body in {@code (progn body...)}, or nil for an empty body (a
	 * body-less progn does not compile).
	 * @param body the body forms
	 * @return the single body expression
	 */
	private static LispVal prognOrNil(List<LispVal> body) {
		if (body.isEmpty()) {
			return LispNil.INSTANCE;
		}
		List<LispVal> prognParts = new java.util.ArrayList<>();
		prognParts.add(new LispSymbol(LispNames.PROGN));
		prognParts.addAll(body);
		return listToCons(prognParts);
	}

	/**
	 * Classifies a literal {@code :element-type} argument: {@code '(unsigned-byte 8)} --
	 * or its unparameterized spelling {@code 'unsigned-byte}, which local-time's timezone
	 * reader uses -- is binary, {@code 'character} is text; anything else (including a
	 * non-literal expression) is rejected so the compilers can resolve the file mode at
	 * compile time.
	 * @param val the element-type argument as it appears in the source
	 * @return true for the binary element type
	 */
	private static boolean isBinaryElementTypeLiteral(LispVal val) {
		if (val instanceof LispCons quoteForm) {
			List<LispVal> quoteParts = quoteForm.toList();
			if (quoteParts.size() == 2 && quoteParts.get(0) instanceof LispSymbol q
					&& LispNames.QUOTE.equals(q.name())) {
				LispVal spec = quoteParts.get(1);
				if (spec instanceof LispSymbol sym && LispNames.CHARACTER_TYPE.equals(sym.name())) {
					return false;
				}
				// (unsigned-byte) with no size is (unsigned-byte *); every CL opens such
				// a stream as a byte stream, which for rontolisp is the one 8-bit shape.
				if (spec instanceof LispSymbol sym && LispNames.UNSIGNED_BYTE.equals(sym.name())) {
					return true;
				}
				if (spec instanceof LispCons specCons) {
					List<LispVal> specParts = specCons.toList();
					if (specParts.size() == 2 && specParts.get(0) instanceof LispSymbol ub
							&& LispNames.UNSIGNED_BYTE.equals(ub.name()) && specParts.get(1) instanceof LispInteger bits
							&& bits.value() == 8) {
						return true;
					}
				}
			}
		}
		throw new UnsupportedOperationException(
				LispNames.WITH_OPEN_FILE + " :element-type must be the literal 'character or '(unsigned-byte 8)");
	}

	/**
	 * Builds the {@code (quote (unsigned-byte 8))} literal appended to a binary
	 * {@code open} call.
	 * @return the quoted type specifier
	 */
	private static LispVal unsignedByte8Literal() {
		LispVal spec = listToCons(List.of(new LispSymbol(LispNames.UNSIGNED_BYTE), new LispInteger(8)));
		return listToCons(List.of(new LispSymbol(LispNames.QUOTE), spec));
	}

	/**
	 * Expands {@code (read-sequence seq stream [:start s] [:end e])} into a read loop
	 * over the sequence, yielding the position of the first element not filled (the fill
	 * position). The keywords must be literal; their values are arbitrary expressions.
	 * The sequence must be a rank-1 array.
	 *
	 * <p>
	 * CL fills ANY sequence from a stream of the matching element type, so the element
	 * read is chosen by the BUFFER: a character vector -- what {@code (make-array n
	 * :element-type 'character)} and {@code make-string} build, and the one rank-1 array
	 * that answers {@code stringp} on every backend ({@code .kb/adjustable-arrays.md}) --
	 * reads characters, anything else reads bytes. The test is a runtime one because the
	 * buffer arrives in a variable: {@code alexandria:read-stream-content-into-string}
	 * allocates it from {@code (stream-element-type stream)}, so no expansion-time
	 * inspection could see it ({@code .todo/219}).
	 *
	 * <pre>
	 * (read-sequence seq stream) ->
	 * (let ((__rseq_seq seq) (__rseq_st stream))
	 *   (let ((__rseq_i 0) (__rseq_end (length __rseq_seq)) (__rseq_b nil) (__rseq_eof nil)
	 *         (__rseq_ch (stringp __rseq_seq)))
	 *     (while (if __rseq_eof nil (&lt; __rseq_i __rseq_end))
	 *       (setq __rseq_b (if __rseq_ch (read-char __rseq_st nil nil)
	 *                                    (read-byte __rseq_st nil nil)))
	 *       (if __rseq_b
	 *           (progn (%aset __rseq_seq __rseq_i __rseq_b) (setq __rseq_i (+ __rseq_i 1)))
	 *           (setq __rseq_eof t)))
	 *     __rseq_i))
	 * </pre>
	 * @param cons the read-sequence expression
	 * @return the expanded expression
	 */
	public static LispVal expandReadSequence(LispCons cons) {
		SequenceArgs args = parseSequenceArgs(cons, LispNames.READ_SEQUENCE);
		LispSymbol seq = new LispSymbol("__rseq_seq");
		LispSymbol st = new LispSymbol("__rseq_st");
		LispSymbol i = new LispSymbol("__rseq_i");
		LispSymbol end = new LispSymbol("__rseq_end");
		LispSymbol b = new LispSymbol("__rseq_b");
		LispSymbol eof = new LispSymbol("__rseq_eof");
		LispSymbol chars = new LispSymbol("__rseq_ch");
		LispVal test = listToCons(List.of(new LispSymbol(LispNames.IF), eof, LispNil.INSTANCE,
				listToCons(List.of(new LispSymbol(LispNames.LT), i, end))));
		LispVal readByte = listToCons(
				List.of(new LispSymbol(LispNames.READ_BYTE), st, LispNil.INSTANCE, LispNil.INSTANCE));
		LispVal readChar = listToCons(
				List.of(new LispSymbol(LispNames.READ_CHAR), st, LispNil.INSTANCE, LispNil.INSTANCE));
		LispVal readElement = makeIf(chars, readChar, readByte);
		LispVal store = listToCons(
				List.of(new LispSymbol(LispNames.PROGN), listToCons(List.of(new LispSymbol(LispNames.ASET), seq, i, b)),
						listToCons(List.of(new LispSymbol(LispNames.SETQ), i,
								listToCons(List.of(new LispSymbol(LispNames.ADD), i, new LispInteger(1)))))));
		LispVal loop = listToCons(List.of(new LispSymbol(LispNames.WHILE), test,
				listToCons(List.of(new LispSymbol(LispNames.SETQ), b, readElement)),
				listToCons(List.of(new LispSymbol(LispNames.IF), b, store,
						listToCons(List.of(new LispSymbol(LispNames.SETQ), eof, LispTrue.INSTANCE))))));
		LispVal innerBindings = listToCons(
				List.of(listToCons(List.of(i, args.start())), listToCons(List.of(end, args.end())),
						listToCons(List.of(b, LispNil.INSTANCE)), listToCons(List.of(eof, LispNil.INSTANCE)),
						listToCons(List.of(chars, callOf(LispNames.STRINGP, seq)))));
		LispVal innerLet = listToCons(List.of(new LispSymbol(LispNames.LET), innerBindings, loop, i));
		LispVal outerBindings = listToCons(
				List.of(listToCons(List.of(seq, args.seq())), listToCons(List.of(st, args.stream()))));
		return listToCons(List.of(new LispSymbol(LispNames.LET), outerBindings, innerLet));
	}

	/**
	 * Expands {@code (write-sequence seq stream [:start s] [:end e])} into a
	 * {@code write-byte} loop over the vector, yielding the sequence. The keywords must
	 * be literal; their values are arbitrary expressions. The sequence must be a rank-1
	 * array.
	 *
	 * <pre>
	 * (write-sequence seq stream) ->
	 * (let ((__wseq_seq seq) (__wseq_st stream))
	 *   (let ((__wseq_i 0) (__wseq_end (length __wseq_seq)))
	 *     (while (&lt; __wseq_i __wseq_end)
	 *       (write-byte (aref __wseq_seq __wseq_i) __wseq_st)
	 *       (setq __wseq_i (+ __wseq_i 1)))
	 *     __wseq_seq))
	 * </pre>
	 * @param cons the write-sequence expression
	 * @return the expanded expression
	 */
	public static LispVal expandWriteSequence(LispCons cons) {
		SequenceArgs args = parseSequenceArgs(cons, LispNames.WRITE_SEQUENCE);
		LispSymbol seq = new LispSymbol("__wseq_seq");
		LispSymbol st = new LispSymbol("__wseq_st");
		LispSymbol i = new LispSymbol("__wseq_i");
		LispSymbol end = new LispSymbol("__wseq_end");
		// String branch: write the (start,end) slice as one write-string, yielding seq.
		LispVal writeStr = listToCons(List.of(new LispSymbol(LispNames.WRITE_STRING),
				listToCons(List.of(new LispSymbol(LispNames.SUBSEQ), seq, args.start(), args.end())), st));
		LispVal stringBranch = makeProgn(List.of(writeStr, seq));
		// Array branch: the write-byte loop over the (start,end) range.
		LispVal test = listToCons(List.of(new LispSymbol(LispNames.LT), i, end));
		LispVal writeByte = listToCons(List.of(new LispSymbol(LispNames.WRITE_BYTE),
				listToCons(List.of(new LispSymbol(LispNames.AREF), seq, i)), st));
		LispVal step = listToCons(List.of(new LispSymbol(LispNames.SETQ), i,
				listToCons(List.of(new LispSymbol(LispNames.ADD), i, new LispInteger(1)))));
		LispVal loop = listToCons(List.of(new LispSymbol(LispNames.WHILE), test, writeByte, step));
		LispVal innerBindings = listToCons(
				List.of(listToCons(List.of(i, args.start())), listToCons(List.of(end, args.end()))));
		LispVal arrayBranch = listToCons(List.of(new LispSymbol(LispNames.LET), innerBindings, loop, seq));
		LispVal dispatch = makeIf(callOf(LispNames.STRINGP, seq), stringBranch, arrayBranch);
		LispVal outerBindings = listToCons(
				List.of(listToCons(List.of(seq, args.seq())), listToCons(List.of(st, args.stream()))));
		return listToCons(List.of(new LispSymbol(LispNames.LET), outerBindings, dispatch));
	}

	/**
	 * Expands {@code (make-string size &key initial-element element-type)} into the
	 * equivalent rank-1 character {@code make-array} -- a string IS a character vector in
	 * CL, and that representation is the MUTABLE one on every backend
	 * ({@code .kb/adjustable-arrays.md}): the interpreter builds a {@code LispString}
	 * natively, both compilers build the marked character vector that
	 * {@code expandReplace} / {@code expandScharSetFunctional} write into in place.
	 * {@code initial-element} defaults to a space (implementation defined);
	 * {@code element-type} is parsed and ignored (a character vector is the one string
	 * representation). The keywords must be literal.
	 *
	 * <pre>
	 * (make-string n :initial-element c) ->
	 * (make-array n :element-type 'character :initial-element c)
	 * </pre>
	 *
	 * The previous lowering was a {@code dotimes} that {@code concatenate}d ONE character
	 * per iteration into a fresh immutable string. That made the buffer O(n^2) to
	 * allocate, and -- because the result was immutable -- it silently dropped every
	 * in-place write: {@code (replace buf x)} and {@code (setf (subseq buf ...) x)} took
	 * their functional branch and the rebuilt string was discarded in statement position
	 * (s-sql's {@code strcat} sent BLANK statements to the server). Do not restore it.
	 * @param cons the make-string expression
	 * @return the expanded expression
	 */
	public static LispVal expandMakeString(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2 || parts.size() % 2 != 0) {
			throw new IllegalArgumentException(
					"make-string expects (make-string size [:initial-element c] [:element-type type])");
		}
		LispVal size = parts.get(1);
		LispVal init = new LispChar(' ');
		for (int k = 2; k < parts.size(); k += 2) {
			if (parts.get(k) instanceof LispSymbol key && LispNames.INITIAL_ELEMENT_KEYWORD.equals(key.name())) {
				init = parts.get(k + 1);
			}
			else if (parts.get(k) instanceof LispSymbol key && LispNames.ELEMENT_TYPE_KEYWORD.equals(key.name())) {
				// element-type is parsed and ignored (single string representation).
			}
			else {
				throw new UnsupportedOperationException(
						"make-string supports only the literal :initial-element and :element-type keywords");
			}
		}
		return listToCons(
				List.of(new LispSymbol(LispNames.MAKE_ARRAY), size, new LispSymbol(LispNames.ELEMENT_TYPE_KEYWORD),
						quoteOf("CHARACTER"), new LispSymbol(LispNames.INITIAL_ELEMENT_KEYWORD), init));
	}

	/**
	 * Expands {@code (replace seq1 seq2 &key start1 end1 start2 end2)}. A mutable
	 * {@code seq1} (a general vector, including a fill-pointered character vector) is
	 * updated IN PLACE by an element-copy loop and returned, as in CL; an immutable
	 * string {@code seq1} instead rebuilds a fresh string with {@code concatenate} of the
	 * untouched head/tail around the copied region of {@code seq2}. The branch is chosen
	 * at runtime on {@code %arrayp}; the keywords must be literal.
	 *
	 * <pre>
	 * (replace s1 s2 :start1 a) ->
	 * (let* ((__rpl_1 s1) (__rpl_2 s2)
	 *        (__rpl_s1 a) (__rpl_e1 (length __rpl_1)) (__rpl_s2 0) (__rpl_e2 (length __rpl_2))
	 *        (__rpl_n (min (- __rpl_e1 __rpl_s1) (- __rpl_e2 __rpl_s2))))
	 *   (if (%arrayp __rpl_1)
	 *       (progn (dotimes (__rpl_k __rpl_n)
	 *                (%row-major-aset __rpl_1 (+ __rpl_s1 __rpl_k)
	 *                                 (elt __rpl_2 (+ __rpl_s2 __rpl_k))))
	 *              __rpl_1)
	 *       (concatenate 'string
	 *         (subseq __rpl_1 0 __rpl_s1)
	 *         (subseq __rpl_2 __rpl_s2 (+ __rpl_s2 __rpl_n))
	 *         (subseq __rpl_1 (+ __rpl_s1 __rpl_n) (length __rpl_1)))))
	 * </pre>
	 * @param cons the replace expression
	 * @return the expanded expression
	 */
	public static LispVal expandReplace(LispCons cons) {
		return expandReplace(cons, true);
	}

	/**
	 * Like {@link #expandReplace(LispCons)}, but lets a backend drop the destructive
	 * array arm -- and with it the {@code aref} source read -- when no array can exist in
	 * this program (see {@link #expandCoerce(LispCons, boolean)}). What is left is the
	 * functional string rebuild, which is what the {@code %arrayp} test selects anyway
	 * once no value can answer it.
	 * @param cons the replace expression
	 * @param arraysExist whether a general array can exist in this program
	 * @return the expanded expression
	 */
	public static LispVal expandReplace(LispCons cons, boolean arraysExist) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3 || parts.size() % 2 == 0) {
			throw new IllegalArgumentException(
					"replace expects (replace seq1 seq2 [:start1 s] [:end1 e] [:start2 s] [:end2 e])");
		}
		LispSymbol r1 = new LispSymbol("__rpl_1");
		LispSymbol r2 = new LispSymbol("__rpl_2");
		LispVal s1 = new LispInteger(0);
		LispVal e1 = fmtCall(LispNames.LENGTH, r1);
		LispVal s2 = new LispInteger(0);
		LispVal e2 = fmtCall(LispNames.LENGTH, r2);
		for (int k = 3; k < parts.size(); k += 2) {
			if (!(parts.get(k) instanceof LispSymbol key)) {
				throw new UnsupportedOperationException("replace supports only literal keyword arguments");
			}
			// A nil bound keeps its default (a runtime nil through the or-wrapper), as in
			// the interpreter.
			switch (key.name()) {
				case LispNames.START1_KEYWORD -> s1 = boundOrDefault(parts.get(k + 1), s1);
				case LispNames.END1_KEYWORD -> e1 = boundOrDefault(parts.get(k + 1), e1);
				case LispNames.START2_KEYWORD -> s2 = boundOrDefault(parts.get(k + 1), s2);
				case LispNames.END2_KEYWORD -> e2 = boundOrDefault(parts.get(k + 1), e2);
				default -> throw new UnsupportedOperationException(
						"replace supports only the literal :start1/:end1/:start2/:end2 keywords");
			}
		}
		LispSymbol vs1 = new LispSymbol("__rpl_s1");
		LispSymbol ve1 = new LispSymbol("__rpl_e1");
		LispSymbol vs2 = new LispSymbol("__rpl_s2");
		LispSymbol ve2 = new LispSymbol("__rpl_e2");
		LispSymbol n = new LispSymbol("__rpl_n");
		LispVal nInit = fmtCall(LispNames.MIN, fmtCall(LispNames.SUB, ve1, vs1), fmtCall(LispNames.SUB, ve2, vs2));
		LispVal bindings = listToCons(List.of(listToCons(List.of(r1, parts.get(1))),
				listToCons(List.of(r2, parts.get(2))), listToCons(List.of(vs1, s1)), listToCons(List.of(ve1, e1)),
				listToCons(List.of(vs2, s2)), listToCons(List.of(ve2, e2)), listToCons(List.of(n, nInit))));
		LispVal head = fmtCall(LispNames.SUBSEQ, r1, new LispInteger(0), vs1);
		LispVal mid = fmtCall(LispNames.SUBSEQ, r2, vs2, fmtCall(LispNames.ADD, vs2, n));
		LispVal tail = fmtCall(LispNames.SUBSEQ, r1, fmtCall(LispNames.ADD, vs1, n), fmtCall(LispNames.LENGTH, r1));
		LispVal functional = fmtCall(LispNames.CONCATENATE, quoteOf("STRING"), head, mid, tail);
		if (!arraysExist) {
			// No array can exist, so seq1 is a string or a list and only the functional
			// rebuild is reachable; the destructive loop would just drag the array
			// runtime into every class through the injected #'replace wrapper.
			return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), bindings, functional));
		}
		LispSymbol k = new LispSymbol("__rpl_k");
		// The source reads with aref when seq2 is an array (a string included: aref
		// reads a string's character on every backend) and elt only for a list. The
		// aref shape lets the wasm backend's fused store read a packed integer
		// vector's element raw -- an elt call boxed every byte of a
		// vector-to-vector copy (ironclad's copy-digest, ~7% of the PBKDF2 profile).
		LispVal eltLoop = listToCons(List.of(new LispSymbol(LispNames.DOTIMES), listToCons(List.of(k, n)),
				fmtCall(LispNames.ROW_MAJOR_ASET, r1, fmtCall(LispNames.ADD, vs1, k),
						fmtCall(LispNames.ELT, r2, fmtCall(LispNames.ADD, vs2, k)))));
		LispVal arefLoop = listToCons(List.of(new LispSymbol(LispNames.DOTIMES), listToCons(List.of(k, n)),
				fmtCall(LispNames.ROW_MAJOR_ASET, r1, fmtCall(LispNames.ADD, vs1, k),
						fmtCall(LispNames.AREF, r2, fmtCall(LispNames.ADD, vs2, k)))));
		LispVal copyLoop = makeIf(callOf(LispNames.LISTP, r2), eltLoop, arefLoop);
		LispVal mutating = makeProgn(List.of(copyLoop, r1));
		LispVal body = makeIf(callOf(LispNames.ARRAYP_INTERNAL, r1), mutating, functional);
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), bindings, body));
	}

	/**
	 * A replace/sequence bound expression: a literal nil keeps the default, a literal
	 * integer passes through, and anything else is wrapped in {@code (or expr default)}
	 * so a runtime nil falls back to the default.
	 */
	private static LispVal boundOrDefault(LispVal expr, LispVal defaultExpr) {
		if (expr instanceof LispNil) {
			return defaultExpr;
		}
		if (expr instanceof LispInteger) {
			return expr;
		}
		return fmtCall(LispNames.OR, expr, defaultExpr);
	}

	/**
	 * Expands {@code (lower-case-p c)} into {@code (let ((__cc c)) (not (char= __cc
	 * (char-upcase __cc))))}: a character is lowercase exactly when upcasing changes it.
	 * Follows the platform's Unicode case tables.
	 * @param cons the lower-case-p expression
	 * @return the expanded expression
	 */
	public static LispVal expandLowerCaseP(LispCons cons) {
		return expandCaseTest(cons, LispNames.LOWER_CASE_P, LispNames.CHAR_UPCASE);
	}

	/**
	 * Expands {@code (upper-case-p c)} into {@code (let ((__cc c)) (not (char= __cc
	 * (char-downcase __cc))))}: a character is uppercase exactly when downcasing changes
	 * it.
	 * @param cons the upper-case-p expression
	 * @return the expanded expression
	 */
	public static LispVal expandUpperCaseP(LispCons cons) {
		return expandCaseTest(cons, LispNames.UPPER_CASE_P, LispNames.CHAR_DOWNCASE);
	}

	private static LispVal expandCaseTest(LispCons cons, String name, String flipOp) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException(name + " expects exactly one argument");
		}
		LispSymbol c = new LispSymbol("__cc");
		LispVal test = makeNot(fmtCall(LispNames.CHAR_EQ, c, fmtCall(flipOp, c)));
		return makeLet("__cc", parts.get(1), test);
	}

	/**
	 * Expands {@code (constantp form [env])} into a runtime type test: true for numbers,
	 * strings, characters, keywords, {@code t}/{@code nil}, and {@code (quote x)} forms
	 * (lite -- false negatives only push work to runtime). The optional environment
	 * argument is accepted and ignored (there is no environment object; a macro's
	 * {@code &environment} parameter is bound to nil).
	 * @param cons the constantp expression
	 * @return the expanded expression
	 */
	public static LispVal expandConstantp(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2 && parts.size() != 3) {
			throw new IllegalArgumentException("constantp expects one or two arguments");
		}
		LispSymbol c = new LispSymbol("__cp");
		LispVal quoteForm = fmtCall(LispNames.AND, callOf(LispNames.CONSP, c),
				fmtCall(LispNames.EQ_GENERAL, callOf(LispNames.CAR, c), quoteOf(LispNames.QUOTE)));
		LispVal test = fmtCall(LispNames.OR, callOf(LispNames.NUMBERP, c), callOf(LispNames.STRINGP, c),
				callOf(LispNames.CHARACTERP, c), callOf(LispNames.KEYWORDP, c),
				fmtCall(LispNames.EQ_GENERAL, c, LispTrue.INSTANCE), callOf(LispNames.NULL, c), quoteForm);
		return makeLet("__cp", parts.get(1), test);
	}

	/**
	 * Expands {@code (simple-string-p x)} into {@code (stringp x)} (lite): every
	 * rontolisp string is "simple", so a portable "coerce unless simple-string-p" idiom
	 * (cl-ppcre's maybe-coerce-to-simple-string) keeps the string unchanged.
	 * @param cons the simple-string-p expression
	 * @return the expanded expression
	 */
	public static LispVal expandSimpleStringP(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException(LispNames.SIMPLE_STRING_P + " expects exactly one argument");
		}
		return listToCons(List.of(new LispSymbol(LispNames.STRINGP), parts.get(1)));
	}

	/**
	 * Expands {@code (streamp x)} into {@code (let ((__s x)) (if (eq __s t) t (integerp
	 * __s)))}: streams are opaque integer handles across all backends, and the standard
	 * output designator {@code t} counts as a stream so it survives the
	 * {@code check-type}/{@code streamp} guards of libraries handed
	 * {@code *standard-output*} (lite).
	 * @param cons the streamp expression
	 * @return the expanded expression
	 */
	public static LispVal expandStreamp(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException("streamp expects exactly one argument");
		}
		LispSymbol temp = new LispSymbol("__s");
		LispVal test = listToCons(
				List.of(new LispSymbol(LispNames.IF), fmtCall(LispNames.EQ_GENERAL, temp, LispTrue.INSTANCE),
						LispTrue.INSTANCE, callOf(LispNames.INTEGERP, temp)));
		return makeLet("__s", parts.get(1), test);
	}

	/** Builds a {@code (quote name)} form for the given symbol name. */
	private static LispVal quoteOf(String name) {
		return listToCons(List.of(new LispSymbol(LispNames.QUOTE), new LispSymbol(name)));
	}

	/**
	 * The {@code (quote character)} constant of the lite {@code stream-element-type}
	 * (every stream is a character stream).
	 * @return the quoted type name
	 */
	public static LispVal quotedCharacterTypeName() {
		return quoteOf("CHARACTER");
	}

	/**
	 * Expands {@code (input-stream-p x)} / {@code (output-stream-p x)} into
	 * {@code (streamp x)}: every stream handle is bidirectional-lite, so both predicates
	 * coincide with {@code streamp} (including the {@code t} designator).
	 * @param cons the input-stream-p / output-stream-p expression
	 * @return the expanded expression
	 */
	public static LispVal expandStreamDirectionP(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException(
					((LispSymbol) cons.car()).name() + " expects exactly one argument: " + cons.print());
		}
		return expandStreamp((LispCons) fmtCall(LispNames.STREAMP, parts.get(1)));
	}

	/**
	 * Expands a lite always-constant operator ({@code file-position},
	 * {@code file-length}, {@code pathnamep}, {@code stream-element-type}) into a
	 * {@code progn} evaluating the arguments for effect and yielding the fixed result.
	 * @param cons the expression
	 * @param result the constant result form
	 * @return the expanded expression
	 */
	public static LispVal expandConstantResult(LispCons cons, LispVal result) {
		List<LispVal> parts = cons.toList();
		List<LispVal> body = new java.util.ArrayList<>();
		body.add(new LispSymbol(LispNames.PROGN));
		body.addAll(parts.subList(1, parts.size()));
		body.add(result);
		return listToCons(body);
	}

	/**
	 * Expands {@code (make-broadcast-stream)} into {@code (make-string-output-stream)}: a
	 * discarding sink stream, exactly what the interpreter allocates (component streams
	 * are unsupported everywhere).
	 * @param cons the make-broadcast-stream expression
	 * @return the expanded expression
	 */
	public static LispVal expandMakeBroadcastStream(LispCons cons) {
		if (!(cons.cdr() instanceof LispNil)) {
			throw new UnsupportedOperationException(
					LispNames.MAKE_BROADCAST_STREAM + " with component streams is not supported: " + cons.print());
		}
		return fmtCall(LispNames.MAKE_STRING_OUTPUT_STREAM_INTERNAL);
	}

	/**
	 * Expands {@code (fdefinition x)} into {@code (symbol-function x)}: fdefinition is
	 * the symbol-function alias for symbol designators (no setf-function names).
	 * @param cons the fdefinition expression
	 * @return the expanded expression
	 */
	public static LispVal expandFdefinition(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException(
					LispNames.FDEFINITION + " expects exactly one argument: " + cons.print());
		}
		return fmtCall(LispNames.SYMBOL_FUNCTION, parts.get(1));
	}

	/**
	 * Lowers a {@code (symbol-function EXPR)} whose designator is NOT a quoted symbol
	 * literal into an evaluate-then-signal form: compiled programs have no runtime
	 * name-to-function table (that is {@code --dynamic}'s job), so the branch errors only
	 * if it actually runs -- which lets a library carrying such a branch (e.g. a
	 * symbol-valued {@code :key-fn}) compile as long as the branch stays cold. The
	 * interpreter keeps the real runtime lookup.
	 * @param cons the symbol-function expression
	 * @return the lowered expression
	 */
	/**
	 * If {@code cons} calls a {@code uiop:} member with no real definition (the package
	 * stub: the name resolves, but calling it is an error), lowers the call into an
	 * evaluate-args-then-signal form mirroring the interpreter's undefined-function error
	 * at call time -- so a library carrying such a call on a cold branch (jzon's pathname
	 * handling) still compiles. Returns null for any other operator. The members that DO
	 * have a definition either lower here ({@code file-exists-p},
	 * {@code get-pathname-defaults}) or are dispatched by each backend's expression
	 * compiler before this is consulted ({@code getenv}).
	 * @param cons the call expression
	 * @return the lowered expression, or null when the operator is not a uiop member
	 */
	@Nullable public static LispVal expandUiopStubCall(LispCons cons) {
		if (!(cons.car() instanceof LispSymbol op)) {
			return null;
		}
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(op.name());
		if (qn == null || !LispNames.UIOP_PKG.equals(qn.pkg())) {
			return null;
		}
		List<LispVal> parts = cons.toList();
		if (LispNames.SYMBOL_CALL.equals(qn.member()) && parts.size() >= 3) {
			// REAL since todo-229 (retiring the "no runtime name table" divergence
			// recorded in .kb/asdf.md): late-bind the name through the runtime 2-arg
			// intern and the _lookup registry. The two fixed temps keep the
			// package-before-name evaluation order (.kb/argument-evaluation-order.md);
			// they are un-capturable in practice (no real program names a variable
			// %UIOP-SC-*). An absent package signals through the intern lowering's
			// nil-designator arm; an absent name signals undefined-function at the
			// call, both later than the interpreter's own probes but just as loud.
			LispSymbol pkgVar = new LispSymbol(UIOP_SYMBOL_CALL_PKG_VAR);
			LispSymbol nameVar = new LispSymbol(UIOP_SYMBOL_CALL_NAME_VAR);
			List<LispVal> call = new java.util.ArrayList<>();
			call.add(new LispSymbol(LispNames.FUNCALL));
			call.add(listToCons(List.of(new LispSymbol(LispNames.INTERN),
					listToCons(List.of(new LispSymbol(LispNames.STRING), nameVar)),
					listToCons(List.of(new LispSymbol(LispNames.FIND_PACKAGE), pkgVar)))));
			call.addAll(parts.subList(3, parts.size()));
			LispVal bindings = listToCons(
					List.of(listToCons(List.of(pkgVar, parts.get(1))), listToCons(List.of(nameVar, parts.get(2)))));
			return listToCons(List.of(new LispSymbol(LispNames.LET), bindings, listToCons(call)));
		}
		if (LispNames.GET_PATHNAME_DEFAULTS.equals(qn.member()) && parts.size() == 1) {
			// Not a stub: the one uiop pathname accessor with a real cross-backend
			// answer. See LispNames.GET_PATHNAME_DEFAULTS for why it is "". Only the
			// no-argument shape (the one every call site uses) is answered; the
			// &optional defaults shape falls through to the stub error rather than
			// silently discarding the argument.
			return new LispString("");
		}
		if (LispNames.FILE_EXISTS_P.equals(qn.member()) && parts.size() == 2) {
			// Not a stub either: uiop:file-exists-p IS probe-file (same contract -- the
			// truename on success, nil otherwise), so it lowers onto the primitive on
			// every backend. Only the 1-argument shape (the one real uiop exports) is
			// answered.
			return listToCons(List.of(new LispSymbol(LispNames.PROBE_FILE), parts.get(1)));
		}
		List<LispVal> progn = new java.util.ArrayList<>();
		progn.add(new LispSymbol(LispNames.PROGN));
		progn.addAll(parts.subList(1, parts.size()));
		progn.add(listToCons(List.of(new LispSymbol(LispNames.ERROR),
				new LispString("The function " + op.name() + " is undefined"))));
		return listToCons(progn);
	}

	/**
	 * If {@code cons} is a {@code (read-line ...)} call in CL's 2- or 3-argument shape
	 * with a literal-{@code nil} {@code eof-error-p}, returns a lowered form the
	 * per-backend compilers can consume. Real libraries drive a per-line loop with
	 * {@code (read-line stream nil nil)} (the standard "swallow EOF" idiom) -- uax-15's
	 * {@code precomputed-tables.lisp} is the seed. Returns {@code null} for shapes the
	 * compilers can already handle (0 or 1 argument) and for the {@code eof-error-p}
	 * non-nil branch (the compile paths do not carry a runtime EOF error yet).
	 *
	 * <ul>
	 * <li>{@code (read-line s nil)} -> {@code (read-line s)}</li>
	 * <li>{@code (read-line s nil nil)} -> {@code (read-line s)}</li>
	 * <li>{@code (read-line s nil EOF-VAL)} -> {@code (or (read-line s) EOF-VAL)}</li>
	 * </ul>
	 *
	 * The runtime stream helpers on all backends already return {@code nil} at EOF, so
	 * the "swallow" branch collapses to the 1-arg call without behavior change.
	 * @param cons the call expression
	 * @return the lowered expression, or {@code null} when the shape is not handled here
	 */
	@Nullable public static LispVal expandReadLineCompat(LispCons cons) {
		if (!(cons.car() instanceof LispSymbol op) || !LispNames.READ_LINE.equals(op.name())) {
			return null;
		}
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3 || parts.size() > 4) {
			return null;
		}
		LispVal eofErrorP = parts.get(2);
		if (!isLiteralNil(eofErrorP)) {
			return null;
		}
		LispVal stream = parts.get(1);
		LispVal readLineOnly = listToCons(List.of(new LispSymbol(LispNames.READ_LINE), stream));
		if (parts.size() == 3 || isLiteralNil(parts.get(3))) {
			return readLineOnly;
		}
		return listToCons(List.of(new LispSymbol(LispNames.OR), readLineOnly, parts.get(3)));
	}

	private static boolean isLiteralNil(LispVal expr) {
		return expr instanceof LispNil || (expr instanceof LispSymbol sym && "NIL".equals(sym.name()));
	}

	/**
	 * If {@code cons} is a two-argument {@code (find-symbol NAME PKG)} whose package
	 * designator is a literal, returns the equivalent {@code intern} of the canonical
	 * qualified spelling: {@code (intern (concatenate 'string "PKG:" NAME))}. The
	 * compiled backends have no package registry at runtime, but a symbol IS its
	 * canonical spelling there, so building that spelling is the lookup -- with two
	 * deviations from the interpreter's registry-backed version: an unknown name yields a
	 * symbol instead of nil (harmless where find-symbol feeds a plist/dispatch lookup
	 * that then answers nil anyway), and the qualifier is the single-colon EXTERNAL
	 * spelling, which is what a library's exported API uses. The {@code keyword},
	 * {@code cl} and {@code cl-user} packages need no qualifier work, and a literal
	 * designator naming NO package folds straight to nil -- the backend's baked package
	 * table knows which those are, so the compile paths agree with the interpreter on
	 * postmodern's {@code (find-symbol "TIMESTAMP" :simple-date)} probe. Returns
	 * {@code null} when the package argument is not a literal designator.
	 * @param cons the find-symbol call
	 * @param packageTable the backend's baked package table
	 * ({@code PackageResolver.runtimePackageTable()})
	 * @return the lowered expression, or {@code null}
	 */
	@Nullable public static LispVal expandFindSymbolInPackage(LispCons cons, java.util.Map<String, String> packageTable) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			return null;
		}
		LispVal name = parts.get(1);
		String pkg = literalPackageDesignator(parts.get(2));
		if (pkg != null && !packageTable.isEmpty() && !packageTable.containsKey(pkg)
				&& !packageTable.containsKey(pkg.toUpperCase(java.util.Locale.ROOT))) {
			// No such package: it provides no symbol. (An empty table means the caller
			// has none -- keep the pre-table behavior rather than folding everything
			// away.)
			return LispNil.INSTANCE;
		}
		if (pkg == null) {
			// A computed package value (ironclad's massage-symbol holds one in a local,
			// postmodern's json-intern reads one out of *json-symbols-package*): build
			// the
			// qualified spelling from it at run time. A package value prints as its name,
			// so (string PKG) is the qualifier -- except for the three packages whose
			// members are spelled WITHOUT a qualifier, which the literal path folds away
			// and this one must test for at run time, or a computed :keyword designator
			// would build KEYWORD:X instead of the keyword :X.
			return computedPackageFindSymbol(name, parts.get(2));
		}
		if ("KEYWORD".equalsIgnoreCase(pkg)) {
			return listToCons(List.of(new LispSymbol(LispNames.INTERN), name, new LispSymbol(":KEYWORD")));
		}
		if (LispNames.CL_PKG.equalsIgnoreCase(pkg) || LispNames.CL_USER_PKG.equalsIgnoreCase(pkg)) {
			return listToCons(List.of(new LispSymbol(LispNames.INTERN), name));
		}
		LispVal qualified = listToCons(
				List.of(new LispSymbol(LispNames.CONCATENATE), quoteOf("STRING"), new LispString(pkg + ":"), name));
		return listToCons(List.of(new LispSymbol(LispNames.INTERN), qualified));
	}

	/**
	 * The compiled backends' lowering of a {@code (find-package X)} whose designator is
	 * COMPUTED (a literal one is folded by {@code PackageResolver.resolveCons}, which is
	 * the one pass holding the registry): an {@code assoc} against the package table the
	 * backend baked in from the resolver's FINAL registry, keyed by the upcased
	 * designator, yielding the same {@code :UPCASED-NAME} keyword the fold produces and
	 * nil for a name no package answers to. Frozen at compile time, so a package a
	 * compiled program creates later is invisible here -- only the interpreter, which
	 * keeps the live registry, sees those.
	 * @param designatorForm the (unevaluated) package designator expression
	 * @param table the designator-to-package-name table
	 * ({@code PackageResolver.runtimePackageTable()})
	 * @return the equivalent lookup expression
	 */
	public static LispVal expandRuntimeFindPackage(LispVal designatorForm, java.util.Map<String, String> table) {
		List<LispVal> entries = new java.util.ArrayList<>(table.size());
		table.forEach((designator, canonical) -> entries
			.add(new LispCons(new LispString(designator), new LispSymbol(":" + canonical))));
		// Verbatim, not upcased: package names are case-sensitive, and the table already
		// carries every spelling the resolver's findPackageName would accept.
		LispVal key = listToCons(List.of(new LispSymbol(LispNames.STRING), designatorForm));
		LispVal quotedTable = listToCons(List.of(new LispSymbol(LispNames.QUOTE), listToCons(entries)));
		LispVal lookup = listToCons(List.of(new LispSymbol(LispNames.ASSOC), key, quotedTable, new LispSymbol(":TEST"),
				listToCons(List.of(new LispSymbol(LispNames.FUNCTION), new LispSymbol(LispNames.STRING_EQ)))));
		return listToCons(List.of(new LispSymbol(LispNames.CDR), lookup));
	}

	/**
	 * The compiled backends' lowering of a one-argument {@code (find-symbol NAME)} whose
	 * NAME is not a literal string: {@code (intern NAME)}. A symbol IS its canonical
	 * spelling there, so interning the name IS the lookup -- with the same deviation the
	 * two-argument lowering already carries: an unknown name yields a symbol instead of
	 * nil, because "already interned" is knowledge only an intern table could hold and
	 * rontolisp has none ({@code .kb/symbol-runtime-api.md}). A LITERAL name still folds
	 * against the compile-time view of the image and can answer nil.
	 * {@code postmodern/prepare.lisp} reaches this with
	 * {@code (find-symbol (string-upcase x))}.
	 * @param nameForm the (unevaluated) name expression
	 * @return the equivalent intern form
	 */
	public static LispVal computedFindSymbol(LispVal nameForm) {
		return listToCons(List.of(new LispSymbol(LispNames.INTERN), nameForm));
	}

	/** The temporaries {@link #computedPackageFindSymbol} binds its two arguments to. */
	private static final String FIND_SYMBOL_PKG_VAR = "%FIND-SYMBOL-PKG";

	private static final String FIND_SYMBOL_NAME_VAR = "%FIND-SYMBOL-NAME";

	/** The temporaries the {@code uiop:symbol-call} lowering binds its arguments to. */
	private static final String UIOP_SYMBOL_CALL_PKG_VAR = "%UIOP-SC-PKG";

	private static final String UIOP_SYMBOL_CALL_NAME_VAR = "%UIOP-SC-NAME";

	/**
	 * The runtime form of {@code (find-symbol NAME PKG)} for a COMPUTED package
	 * designator: bind both arguments (each evaluated once), answer nil for a nil
	 * designator (the interpreter's answer for a package that does not exist -- see
	 * {@code .kb/symbol-runtime-api.md}), and otherwise intern the qualified spelling,
	 * treating {@code keyword} / {@code cl} / {@code cl-user} exactly as the literal path
	 * does. The two binding names are fixed rather than generated: {@code let} evaluates
	 * its inits in the enclosing scope, so a nested expansion in an argument position
	 * cannot capture them, and fixed names keep the emitted output deterministic.
	 */
	private static LispVal computedPackageFindSymbol(LispVal name, LispVal packageForm) {
		LispSymbol pkgVar = new LispSymbol(FIND_SYMBOL_PKG_VAR);
		LispVal interned = listToCons(List.of(new LispSymbol(LispNames.INTERN),
				computedQualifiedSpelling(pkgVar, new LispSymbol(FIND_SYMBOL_NAME_VAR))));
		LispVal guarded = listToCons(List.of(new LispSymbol(LispNames.IF),
				listToCons(List.of(new LispSymbol(LispNames.NULL), pkgVar)), LispNil.INSTANCE, interned));
		return bindFindSymbolTemps(name, packageForm, guarded);
	}

	/**
	 * The runtime form of {@code (intern NAME PKG)} for a COMPUTED package designator
	 * (todo-229; clack's handler protocol passes the {@code find-handler} package value
	 * through {@code (apply (intern (string '#:run) handler-package) ...)}): the same
	 * qualified-spelling build as {@link #computedPackageFindSymbol}, except that a nil
	 * designator SIGNALS -- intern's contract has no "package does not exist -> nil"
	 * escape ({@code PackageResolver.internSpellingIn} throws on the interpreter).
	 */
	private static LispVal computedPackageIntern(LispVal name, LispVal packageForm) {
		LispSymbol pkgVar = new LispSymbol(FIND_SYMBOL_PKG_VAR);
		LispVal interned = listToCons(List.of(new LispSymbol(LispNames.INTERN),
				computedQualifiedSpelling(pkgVar, new LispSymbol(FIND_SYMBOL_NAME_VAR))));
		LispVal guarded = listToCons(
				List.of(new LispSymbol(LispNames.IF), listToCons(List.of(new LispSymbol(LispNames.NULL), pkgVar)),
						listToCons(List.of(new LispSymbol(LispNames.ERROR), new LispString("No such package: NIL"))),
						interned));
		return bindFindSymbolTemps(name, packageForm, guarded);
	}

	/**
	 * The {@code cond} building the canonical qualified spelling of {@code nameVar} in
	 * the package held by {@code pkgVar}, shared by the computed-package
	 * {@code find-symbol} and {@code intern} lowerings: {@code keyword} members are
	 * spelled {@code :NAME}, {@code cl}/{@code cl-user} members bare, anything else
	 * {@code PKG:NAME} (the single-colon external spelling -- right for a library's
	 * exported API; internal names resolve through the function registry's alias rows).
	 */
	private static LispVal computedQualifiedSpelling(LispSymbol pkgVar, LispSymbol nameVar) {
		LispVal pkgString = listToCons(List.of(new LispSymbol(LispNames.STRING), pkgVar));
		List<LispVal> clauses = new java.util.ArrayList<>();
		clauses.add(new LispSymbol(LispNames.COND));
		clauses.add(listToCons(
				List.of(listToCons(List.of(new LispSymbol(LispNames.STRING_EQ), pkgString, new LispString("KEYWORD"))),
						listToCons(List.of(new LispSymbol(LispNames.CONCATENATE), quoteOf("STRING"),
								new LispString(":"), nameVar)))));
		for (String bare : List.of(LispNames.CL_PKG, LispNames.CL_USER_PKG)) {
			clauses.add(listToCons(List.of(listToCons(List.of(new LispSymbol(LispNames.STRING_EQ), pkgString,
					new LispString(bare.toUpperCase(java.util.Locale.ROOT)))), nameVar)));
		}
		clauses.add(listToCons(List.of(LispTrue.INSTANCE, listToCons(List.of(new LispSymbol(LispNames.CONCATENATE),
				quoteOf("STRING"), pkgString, new LispString(":"), nameVar)))));
		return listToCons(clauses);
	}

	/** Binds the shared fixed temporaries around {@code body} (see the field docs). */
	private static LispVal bindFindSymbolTemps(LispVal name, LispVal packageForm, LispVal body) {
		LispSymbol pkgVar = new LispSymbol(FIND_SYMBOL_PKG_VAR);
		LispSymbol nameVar = new LispSymbol(FIND_SYMBOL_NAME_VAR);
		LispVal bindings = listToCons(
				List.of(listToCons(List.of(pkgVar, packageForm)), listToCons(List.of(nameVar, name))));
		return listToCons(List.of(new LispSymbol(LispNames.LET), bindings, body));
	}

	/**
	 * The compile-path lowering of a two-argument {@code (intern NAME PKG)} (todo-229):
	 * the same canonical-spelling build as {@link #expandFindSymbolInPackage} -- a symbol
	 * IS its canonical spelling on the compiled backends, so building the spelling IS the
	 * intern -- with intern's two contract differences: the {@code keyword} designator
	 * keeps the existing (byte-identical) keyword lowering, and a package that does not
	 * exist SIGNALS {@code No such package: X} instead of folding to nil (interpreter
	 * parity; the signal is a call-time stub, so a library merely CONTAINING the form
	 * still compiles -- lack/builder.lisp's old-Clack branch interns into
	 * {@code :clack.middleware}, a package that never exists here).
	 * @param cons the intern call (must be the three-part shape)
	 * @param packageTable the backend's baked package table
	 * ({@code PackageResolver.runtimePackageTable()})
	 * @return the lowered expression
	 */
	public static LispVal expandInternInPackage(LispCons cons, java.util.Map<String, String> packageTable) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			throw new IllegalArgumentException("intern with a package expects (intern name package): " + cons.print());
		}
		LispVal name = parts.get(1);
		if (isKeywordPackageDesignator(parts.get(2))) {
			return internKeywordForm(name);
		}
		String pkg = literalPackageDesignator(parts.get(2));
		if (pkg == null) {
			return computedPackageIntern(name, parts.get(2));
		}
		if (!packageTable.isEmpty() && !packageTable.containsKey(pkg)
				&& !packageTable.containsKey(pkg.toUpperCase(java.util.Locale.ROOT))) {
			// No such package: intern SIGNALS where find-symbol answers nil. (An empty
			// table means the caller has none -- treat the package as known.)
			return listToCons(List.of(new LispSymbol(LispNames.ERROR), new LispString("No such package: " + pkg)));
		}
		if (LispNames.CL_PKG.equalsIgnoreCase(pkg) || LispNames.CL_USER_PKG.equalsIgnoreCase(pkg)) {
			return listToCons(List.of(new LispSymbol(LispNames.INTERN), name));
		}
		LispVal qualified = listToCons(
				List.of(new LispSymbol(LispNames.CONCATENATE), quoteOf("STRING"), new LispString(pkg + ":"), name));
		return listToCons(List.of(new LispSymbol(LispNames.INTERN), qualified));
	}

	/**
	 * A literal package designator: a string, a keyword, a quoted symbol, or a
	 * {@code (load-time-value (find-package ...))}-style wrapper the resolver has already
	 * folded to a quoted keyword. Returns null for a computed designator.
	 */
	@Nullable private static String literalPackageDesignator(LispVal arg) {
		if (arg instanceof LispCons cons && cons.car() instanceof LispSymbol op
				&& (LispNames.QUOTE.equals(op.name()) || LispNames.LOAD_TIME_VALUE.equals(op.name()))
				&& cons.cdr() instanceof LispCons rest && rest.cdr() instanceof LispNil) {
			return literalPackageDesignator(rest.car());
		}
		return switch (arg) {
			case LispString str -> str.value();
			// A bare (non-keyword) symbol here is a VARIABLE REFERENCE holding a package
			// value, not a designator literal -- reading its NAME as the package is how
			// (find-symbol n ironclad) once built the doubly-qualified
			// IRONCLAD::IRONCLAD:X.
			case LispSymbol sym ->
				sym.isKeyword() || sym.name().startsWith("#:") ? LispSymbol.displayName(sym.name()) : null;
			default -> null;
		};
	}

	/**
	 * If {@code cons} is a {@code read} call carrying the full CL tail
	 * ({@code (read stream eof-error-p eof-value recursive-p)}), returns the equivalent
	 * one-argument call: {@code recursive-p} is dropped (there is no recursive-read
	 * state), {@code eof-error-p} is dropped (this {@code read} returns nil at end of
	 * input and never signals), and a non-nil {@code eof-value} becomes an {@code or}
	 * default -- the same lowering {@link #expandReadLineCompat} does. So a nil datum and
	 * end-of-input stay indistinguishable, exactly as they already are for the
	 * one-argument call. Returns {@code null} for the 0/1-argument shapes so those keep
	 * their existing (byte-identical) lowering, and for a non-nil literal
	 * {@code eof-error-p} (signalling at EOF is not supported).
	 * @param cons the call expression
	 * @return the lowered expression, or {@code null} when the shape is not handled here
	 */
	@Nullable public static LispVal expandReadCompat(LispCons cons) {
		if (!(cons.car() instanceof LispSymbol op) || !LispNames.READ.equals(op.name())) {
			return null;
		}
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3 || parts.size() > 5) {
			return null;
		}
		if (!isLiteralNil(parts.get(2))) {
			return null;
		}
		LispVal readOnly = listToCons(List.of(new LispSymbol(LispNames.READ), parts.get(1)));
		if (parts.size() == 3 || isLiteralNil(parts.get(3))) {
			return readOnly;
		}
		return listToCons(List.of(new LispSymbol(LispNames.OR), readOnly, parts.get(3)));
	}

	/**
	 * If {@code cons} is a {@code (subseq seq start [end])} call, returns a form that
	 * dispatches on the runtime type of {@code seq}: a general array
	 * ({@link LispNames#ARRAYP_INTERNAL}) is copied element by element into a fresh array
	 * via {@code make-array}/{@code aref}/{@code %aset}, and any other shape falls
	 * through to {@link LispNames#SUBSEQ_CORE} -- the string/list dispatch the
	 * per-backend compilers already emit. Returns {@code null} for the already-lowered
	 * {@code %subseq-core} form so the compilers do not loop, and for any
	 * unusually-shaped {@code subseq} call the compilers would themselves reject.
	 *
	 * <p>
	 * Motivation: the JVM/WASM {@code subseq} runtime lanes cover strings and cons chains
	 * but not vectors, and uax-15's {@code canonical-ordering} exercises
	 * {@code (subseq unicode-string beg end)} at load time. The interpreter dispatches to
	 * {@link am.ik.rontolisp.eval.Environment#seqAsList} directly, so it does not need
	 * this rewrite.
	 * @param cons the call expression
	 * @return the lowered expression, or {@code null} when the shape is not handled here
	 */
	@Nullable public static LispVal expandSubseqCompat(LispCons cons) {
		return expandSubseqCompat(cons, true);
	}

	/**
	 * Like {@link #expandSubseqCompat(LispCons)}, but a backend that cannot hold an array
	 * ({@code arraysExist} false, see {@link #expandCoerce(LispCons, boolean)}) gets
	 * {@code null}: the whole rewrite exists to reach the array arm, and with no array in
	 * the program both arms of its dispatch are the plain {@code %subseq-core} call the
	 * compiler emits anyway.
	 * @param cons the call expression
	 * @param arraysExist whether a general array can exist in this program
	 * @return the lowered expression, or {@code null} when the shape is not handled here
	 */
	@Nullable public static LispVal expandSubseqCompat(LispCons cons, boolean arraysExist) {
		if (!arraysExist) {
			return null;
		}
		if (!(cons.car() instanceof LispSymbol op) || !LispNames.SUBSEQ.equals(op.name())) {
			return null;
		}
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3 || parts.size() > 4) {
			return null;
		}
		LispSymbol seqVar = new LispSymbol("__ss_seq");
		LispSymbol startVar = new LispSymbol("__ss_start");
		LispSymbol endVar = new LispSymbol("__ss_end");
		LispSymbol lenVar = new LispSymbol("__ss_len");
		LispSymbol nVar = new LispSymbol("__ss_n");
		LispSymbol outVar = new LispSymbol("__ss_out");
		LispSymbol iVar = new LispSymbol("__ss_i");
		LispVal endInit = parts.size() > 3 ? parts.get(3) : LispNil.INSTANCE;
		LispVal effectiveEnd = makeIf(endVar, endVar, callOf(LispNames.LENGTH, seqVar));
		LispVal length = listToCons(List.of(new LispSymbol(LispNames.SUB), lenVar, startVar));
		// %array-alike, not make-array: the output keeps the input's representation, so
		// a subsequence of a packed integer vector stays packed at the same width.
		LispVal makeOut = listToCons(List.of(new LispSymbol(LispNames.ARRAY_ALIKE), seqVar, nVar));
		LispVal readSrc = listToCons(List.of(new LispSymbol(LispNames.AREF), seqVar,
				listToCons(List.of(new LispSymbol(LispNames.ADD), startVar, iVar))));
		LispVal writeDst = listToCons(List.of(new LispSymbol(LispNames.ASET), outVar, iVar, readSrc));
		LispVal fillLoop = listToCons(
				List.of(new LispSymbol(LispNames.DOTIMES), listToCons(List.of(iVar, nVar, outVar)), writeDst));
		LispVal vectorBody = listToCons(List.of(new LispSymbol(LispNames.LET_STAR),
				listToCons(List.of(listToCons(List.of(lenVar, effectiveEnd)), listToCons(List.of(nVar, length)),
						listToCons(List.of(outVar, makeOut)))),
				fillLoop));
		List<LispVal> coreParts = new java.util.ArrayList<>();
		coreParts.add(new LispSymbol(LispNames.SUBSEQ_CORE));
		coreParts.add(seqVar);
		coreParts.add(startVar);
		if (parts.size() > 3) {
			coreParts.add(endVar);
		}
		LispVal coreCall = listToCons(coreParts);
		// Stringp first so a mutable character vector (which is stringp on both
		// backends) stays on the string branch and the returned value keeps the
		// caller-expected element type; only a general (non-string) array switches to
		// the fresh make-array copy.
		LispVal arrayDispatch = makeIf(callOf(LispNames.ARRAYP_INTERNAL, seqVar), vectorBody, coreCall);
		LispVal dispatch = makeIf(callOf(LispNames.STRINGP, seqVar), coreCall, arrayDispatch);
		LispVal outerBindings = listToCons(List.of(listToCons(List.of(seqVar, parts.get(1))),
				listToCons(List.of(startVar, parts.get(2))), listToCons(List.of(endVar, endInit))));
		return listToCons(List.of(new LispSymbol(LispNames.LET), outerBindings, dispatch));
	}

	/**
	 * The general-representation fallback of {@code %array-alike}: {@code (progn seq
	 * (make-array n))} -- a fresh general (boxed) vector, evaluation order preserved.
	 * Used by a backend that has no packed integer-vector representation (currently the
	 * JVM, pending its todo-194 stage-2 half).
	 * @param cons the {@code (%array-alike seq n)} call
	 * @return the lowered expression
	 */
	public static LispVal expandArrayAlikeGeneral(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			throw new UnsupportedOperationException("%array-alike expects a sequence and a length");
		}
		return listToCons(List.of(new LispSymbol(LispNames.PROGN), parts.get(1),
				listToCons(List.of(new LispSymbol(LispNames.MAKE_ARRAY), parts.get(2)))));
	}

	/**
	 * Lowers a call to a name that is not a compiled FUNCTION but IS a known global
	 * VARIABLE into {@code (funcall name args...)} -- the function value is read from the
	 * variable at run time. This is how a defun nested inside a top-level {@code let}
	 * (the CL closure-over-let idiom, e.g. cl-ppcre's {@code quote-meta-chars}) is
	 * called: the nested defun compiles to {@code (setq name (lambda ...))} (a lambda
	 * capturing the let variables) and the setq-assigned name is promoted to a global, so
	 * call sites dispatch through it.
	 * @param cons the call expression
	 * @return the funcall lowering
	 */
	public static LispVal expandCallThroughVariable(LispCons cons) {
		List<LispVal> parts = cons.toList();
		List<LispVal> out = new java.util.ArrayList<>(parts.size() + 1);
		out.add(new LispSymbol(LispNames.FUNCALL));
		out.addAll(parts);
		return listToCons(out);
	}

	/**
	 * The runtime argument-list expression of {@code (apply f a1 ... ak lst)}:
	 * {@code (list* a1 ... ak lst)}, or {@code lst} alone when no leading arguments are
	 * given. Used by the backends' apply fast path (a literal {@code #'f} target compiles
	 * to a PHYSICAL direct call binding f's parameters from this list, bypassing the
	 * runtime {@code _apply} dispatch whose per-arity tables stop at
	 * {@code MAX_CALLABLE_ARITY} -- a variadic CLOS dispatcher forwarding 8+ apply
	 * arguments silently yielded nil there, cl-ppcre's create-scanner keyword recursion).
	 * @param cons the apply expression
	 * @return the argument-list expression
	 */
	public static LispVal applyArgumentListExpr(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() == 3) {
			return parts.get(2);
		}
		List<LispVal> listStar = new java.util.ArrayList<>();
		listStar.add(new LispSymbol(LispNames.LIST_STAR));
		listStar.addAll(parts.subList(2, parts.size()));
		return listToCons(listStar);
	}

	/**
	 * The literal function name of an {@code apply} designator ({@code #'f} or
	 * {@code 'f}), or null when the designator is a computed expression.
	 * @param designator the first apply argument
	 * @return the literal name, or null
	 */
	public static @Nullable String applyLiteralTargetName(LispVal designator) {
		if (designator instanceof LispCons cons && cons.car() instanceof LispSymbol op
				&& (LispNames.FUNCTION.equals(op.name()) || LispNames.QUOTE.equals(op.name()))
				&& cons.cdr() instanceof LispCons cell && cell.car() instanceof LispSymbol sym) {
			return sym.name();
		}
		return null;
	}

	/**
	 * Lowers a call the current backend cannot execute into an evaluate-args-then-signal
	 * form, so a library carrying it on a cold branch still compiles and the error names
	 * the operator only when the branch actually runs (the WASM backends' route for the
	 * {@code %ieee754-*} primitives, whose 64-bit unsigned bit model does not exist
	 * there).
	 * @param cons the call expression
	 * @param message the runtime error message
	 * @return the lowered expression
	 */
	public static LispVal expandUnsupportedCall(LispCons cons, String message) {
		List<LispVal> parts = cons.toList();
		List<LispVal> progn = new java.util.ArrayList<>();
		progn.add(new LispSymbol(LispNames.PROGN));
		progn.addAll(parts.subList(1, parts.size()));
		progn.add(listToCons(List.of(new LispSymbol(LispNames.ERROR), new LispString(message))));
		return listToCons(progn);
	}

	/**
	 * The compiled-backend lowering of {@code (symbol-function s)} on a symbol that is
	 * not a compile-time literal: the IDENTITY (todo-229; it used to be a call-time
	 * signal, whose "no runtime symbol-to-function table" reason died with the
	 * {@code _lookup} registry). On the compiled backends a symbol IS a function
	 * designator wherever a function value is consumed -- {@code funcall}/{@code apply}
	 * and the dispatchers resolve it through the registry late, exactly like the
	 * interpreter's live lookup -- so the symbol itself is the most faithful value (the
	 * jzon {@code :key-fn} shape, {@code (funcall (symbol-function sym) str)}). Two
	 * deviations from the interpreter, both documented in
	 * {@code .kb/symbol-runtime-api.md}: {@code functionp} of the result answers nil, and
	 * an undefined name signals at the CALL, not here.
	 * @param cons the symbol-function expression
	 * @return the expanded expression
	 */
	public static LispVal expandRuntimeSymbolFunction(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException(
					LispNames.SYMBOL_FUNCTION + " expects exactly one argument: " + cons.print());
		}
		return parts.get(1);
	}

	/**
	 * Lowers a {@code (write-string str [stream] :start s :end e)} call carrying literal
	 * bounding keywords into {@code (write-string (subseq str start end) [stream])} over
	 * once-evaluated temps, with a runtime {@code nil} {@code :end} defaulting to the
	 * string's length; yields the full string like the interpreter. Returns null for the
	 * plain keyword-free shape, which keeps its dedicated code path.
	 * @param cons the write-string expression
	 * @return the lowered expression, or null when no bounding keywords are present
	 */
	public static @Nullable LispVal lowerWriteStringBounds(LispCons cons) {
		List<LispVal> parts = cons.toList();
		int i = 2;
		if (parts.size() > 2 && !(parts.get(2) instanceof LispSymbol kw && kw.name().startsWith(":"))) {
			i = 3;
		}
		if (parts.size() <= i) {
			return null;
		}
		LispVal startExpr = null;
		LispVal endExpr = null;
		for (; i + 1 < parts.size(); i += 2) {
			if (!(parts.get(i) instanceof LispSymbol key)) {
				throw new UnsupportedOperationException(
						LispNames.WRITE_STRING + " supports only literal keyword arguments: " + cons.print());
			}
			switch (key.name()) {
				case ":START" -> startExpr = parts.get(i + 1);
				case ":END" -> endExpr = parts.get(i + 1);
				default -> throw new UnsupportedOperationException(
						LispNames.WRITE_STRING + ": unsupported keyword " + key.name());
			}
		}
		String prefix = "__ws" + MV_COUNTER.getAndIncrement();
		LispSymbol s = new LispSymbol(prefix + "_s");
		LispSymbol st = new LispSymbol(prefix + "_b");
		LispSymbol e = new LispSymbol(prefix + "_e");
		LispVal startInit = startExpr == null ? new LispInteger(0)
				: fmtCall(LispNames.OR, startExpr, new LispInteger(0));
		LispVal endInit = endExpr == null || endExpr instanceof LispNil ? fmtCall(LispNames.LENGTH, s)
				: fmtCall(LispNames.OR, endExpr, fmtCall(LispNames.LENGTH, s));
		List<LispVal> inner = new java.util.ArrayList<>();
		inner.add(new LispSymbol(LispNames.WRITE_STRING));
		inner.add(fmtCall(LispNames.SUBSEQ, s, st, e));
		boolean hasStream = parts.size() > 2 && !(parts.get(2) instanceof LispSymbol k2 && k2.name().startsWith(":"));
		if (hasStream) {
			inner.add(parts.get(2));
		}
		LispVal body = listToCons(List.of(new LispSymbol(LispNames.PROGN), listToCons(inner), s));
		return nestMvBindings(
				List.of(new MvBinding(s, parts.get(1)), new MvBinding(st, startInit), new MvBinding(e, endInit)), body);
	}

	/**
	 * The parsed {@code (op seq stream [:start s] [:end e])} arguments. {@code start}
	 * defaults to {@code 0} and {@code end} to {@code (length <seq-temp>)} over the
	 * expander's own sequence temp binding.
	 */
	private record SequenceArgs(LispVal seq, LispVal stream, LispVal start, LispVal end) {
	}

	private static SequenceArgs parseSequenceArgs(LispCons cons, String op) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3 || parts.size() % 2 == 0) {
			throw new IllegalArgumentException(op + " expects (sequence stream [:start s] [:end e])");
		}
		LispVal start = new LispInteger(0);
		String seqVar = LispNames.READ_SEQUENCE.equals(op) ? "__rseq_seq" : "__wseq_seq";
		LispVal end = callOf(LispNames.LENGTH, new LispSymbol(seqVar));
		for (int i = 3; i < parts.size(); i += 2) {
			if (parts.get(i) instanceof LispSymbol key && LispNames.START_KEYWORD.equals(key.name())) {
				start = parts.get(i + 1);
			}
			else if (parts.get(i) instanceof LispSymbol key && LispNames.END_KEYWORD.equals(key.name())) {
				end = parts.get(i + 1);
			}
			else {
				throw new UnsupportedOperationException(op + " supports only the literal :start and :end keywords");
			}
		}
		return new SequenceArgs(parts.get(1), parts.get(2), start, end);
	}

	private static LispVal callOf(String op, LispVal arg) {
		return listToCons(List.of(new LispSymbol(op), arg));
	}

	/**
	 * Expands {@code (sleep seconds)}, the waiting form, into the shared
	 * seconds-to-whole-milliseconds conversion plus the backend's wait.
	 *
	 * <p>
	 * {@code spin} false (interpreter, JVM) yields
	 * {@code (let ((__sleep_ms (round (* seconds 1000)))) (if (> __sleep_ms 0) (%sleep-ms __sleep_ms) nil))}
	 * -- the guard is here, not in the primitive, so {@code %sleep-ms} is a straight-line
	 * "park for this many milliseconds" call and a zero/negative duration is a no-op like
	 * every Common Lisp.
	 *
	 * <p>
	 * {@code spin} true is WASM <strong>Preview 1</strong> only: it loops on
	 * {@code get-internal-real-time} until the deadline, because Preview 1's nine imports
	 * include a CLOCK but no host timer, so burning the interval is the only way to
	 * elapse it. {@code --component} never comes here -- {@code sleep} is the spliced
	 * {@code wait.lisp} defun over the real {@code wasi:clocks} timer there. See
	 * {@code .kb/time-environment-builtins.md} for both, and the re-evaluation trigger
	 * for the Preview 1 spin.
	 * @param cons the sleep expression
	 * @param spin whether this backend must loop on the clock instead of parking
	 * @return the expanded expression
	 */
	public static LispVal expandSleep(LispCons cons, boolean spin) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException(LispNames.SLEEP + " expects 1 argument, got " + (parts.size() - 1));
		}
		LispVal millis = callOf(LispNames.ROUND,
				listToCons(List.of(new LispSymbol(LispNames.MUL), parts.get(1), new LispInteger(1000))));
		if (!spin) {
			LispSymbol ms = new LispSymbol("__sleep_ms");
			LispVal positive = listToCons(List.of(new LispSymbol(LispNames.GT), ms, new LispInteger(0)));
			return makeLet(ms.name(), millis, makeIf(positive, callOf(LispNames.SLEEP_MS, ms), LispNil.INSTANCE));
		}
		LispSymbol end = new LispSymbol("__sleep_end");
		LispVal now = listToCons(List.of(new LispSymbol(LispNames.GET_INTERNAL_REAL_TIME)));
		LispVal deadline = listToCons(List.of(new LispSymbol(LispNames.ADD), now, millis));
		LispVal spinLoop = listToCons(List.of(new LispSymbol(LispNames.WHILE),
				listToCons(List.of(new LispSymbol(LispNames.LT), now, end)), LispNil.INSTANCE));
		return makeLet(end.name(), deadline,
				listToCons(List.of(new LispSymbol(LispNames.PROGN), spinLoop, LispNil.INSTANCE)));
	}

	/**
	 * Expands (defun name (params...) body...) into (setq name (lambda (params...)
	 * body...)), the canonical shape the compilers collect in Pass 1. The interpreter
	 * handles defun natively (Lisp-2 function namespace) and does not use this.
	 * @param cons the defun expression
	 * @return the expanded expression
	 */
	public static LispVal expandDefun(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal name = parts.get(1);
		LispVal params = parts.get(2);
		List<LispVal> lambdaParts = new java.util.ArrayList<>();
		lambdaParts.add(new LispSymbol(LispNames.LAMBDA));
		lambdaParts.add(params);
		lambdaParts.addAll(parts.subList(3, parts.size()));
		LispVal lambda = listToCons(lambdaParts);
		return listToCons(List.of(new LispSymbol(LispNames.SETQ), name, lambda));
	}

	/**
	 * Expands {@code (defstruct name slot...)} into the defuns it generates -- a keyword
	 * constructor, a predicate, a copier and one accessor per slot -- and records each
	 * accessor's slot position in {@code structAccessors} so
	 * {@link #expandSetf(LispCons, java.util.Map)} treats accessor calls as places. An
	 * instance is a first-class object built by {@code %obj-new} over the registered
	 * {@link LispLayout}, so it is not a list ({@code consp}/{@code listp} are nil).
	 *
	 * <pre>
	 * (defstruct point x (y 10)) ->
	 * (defun make-point (&amp;key ((:x x) nil) ((:y y) 10)) (%obj-new '%struct-point x y))
	 * (defun point-p (__struct) (%obj-is __struct '%struct-point))
	 * (defun copy-point (__struct) (%obj-new '%struct-point (%obj-ref __struct 0) (%obj-ref __struct 1)))
	 * (defun point-x (__struct) (%obj-ref __struct 0))
	 * (defun point-y (__struct) (%obj-ref __struct 1))
	 * </pre>
	 *
	 * The form is expected in its canonical (package-resolved) spelling; a qualified
	 * struct name derives internal (double-colon) generated names, e.g.
	 * {@code (defstruct foo::point x)} defines {@code foo::make-point},
	 * {@code foo::point-p}, {@code foo::copy-point} and {@code foo::point-x}, and the
	 * constructor keywords come from the unqualified slot names ({@code :x}).
	 *
	 * <p>
	 * The struct type is also registered in {@code closRegistry} so its name is usable as
	 * a {@code defmethod} parameter specializer and its {@link LispLayout} -- the ordered
	 * slot names and initforms -- is available to instance construction, printing and
	 * {@code #S(...)} reading.
	 * @param cons the defstruct expression
	 * @param structAccessors mutated: accessor name to 1-based slot position in the
	 * tagged list
	 * @param closRegistry mutated when non-null: the struct type and its layout are
	 * registered
	 * @return the generated top-level forms, in definition order
	 */
	public static List<LispVal> expandDefstruct(LispCons cons, java.util.Map<String, Integer> structAccessors,
			@org.jspecify.annotations.Nullable ClosRegistry closRegistry) {
		return expandDefstruct(cons, structAccessors, closRegistry, null);
	}

	/**
	 * As {@link #expandDefstruct(LispCons, java.util.Map, ClosRegistry)}, with the export
	 * oracle that decides how a SYNTHESIZED name is spelled.
	 *
	 * <p>
	 * A generated name lands in the struct's package, and the string it is defined under
	 * has to be the one a call site resolves to -- {@code PKG:NAME} for an exported
	 * member, {@code PKG::NAME} otherwise ({@link PackageResolver#spellsAsExternal}).
	 * Without the oracle every generated name takes the internal spelling, which is right
	 * only for a struct whose {@code defpackage} exports none of them; quri's does export
	 * {@code uri-p}/{@code uri-scheme}/{@code make-uri-http}/..., and those resolved to a
	 * name nothing had defined.
	 * @param cons the defstruct expression
	 * @param structAccessors mutated: accessor name to 1-based slot position
	 * @param closRegistry mutated when non-null: the struct type and its layout
	 * @param exported {@code (package, member) -> is it external}, or {@code null} to
	 * spell every generated name internally (the pre-oracle behavior)
	 * @return the generated top-level forms, in definition order
	 */
	public static List<LispVal> expandDefstruct(LispCons cons, java.util.Map<String, Integer> structAccessors,
			@org.jspecify.annotations.Nullable ClosRegistry closRegistry,
			java.util.function.@org.jspecify.annotations.Nullable BiPredicate<String, String> exported) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException(LispNames.DEFSTRUCT + " expects a struct name: " + cons.print());
		}
		// (defstruct (name option...) slot...): the supported options are
		// (:constructor name [boa-lambda-list]), (:conc-name prefix-or-nil),
		// (:copier name-or-nil), (:predicate name-or-nil), (:include parent) and
		// (:type (vector ...)); anything else is a hard error naming the clause.
		LispSymbol nameSym;
		String customConstructor = null;
		LispVal boaLambdaList = null;
		boolean suppressConstructor = false;
		String concNameOverride = null;
		boolean concNameGiven = false;
		String customPredicate = null;
		boolean suppressPredicate = false;
		String customCopier = null;
		boolean suppressCopier = false;
		String includeParent = null;
		// (:include parent (slot new-default) ...): the child's initform overrides for
		// inherited slots, keyed by the slot's unqualified name.
		java.util.Map<String, LispVal> includeOverrides = new java.util.LinkedHashMap<>();
		boolean typedVector = false;
		if (parts.get(1) instanceof LispSymbol plain) {
			nameSym = plain;
		}
		else if (parts.get(1) instanceof LispCons header && header.car() instanceof LispSymbol headerName) {
			nameSym = headerName;
			for (LispVal option : header.toList().subList(1, header.toList().size())) {
				if (!(option instanceof LispCons optCons) || !(optCons.car() instanceof LispSymbol optSym)) {
					throw new UnsupportedOperationException(
							LispNames.DEFSTRUCT + " option is not supported: " + option.print());
				}
				List<LispVal> optParts = optCons.toList();
				String optName = optSym.name();
				LispVal optValue = optParts.size() > 1 ? optParts.get(1) : LispNil.INSTANCE;
				switch (optName) {
					case ":CONSTRUCTOR" -> {
						if (optParts.size() > 3) {
							throw new UnsupportedOperationException(
									LispNames.DEFSTRUCT + " option is not supported: " + option.print());
						}
						if (optValue instanceof LispSymbol s) {
							customConstructor = s.name();
							if (optParts.size() == 3) {
								// A BOA constructor: the explicit lambda list is used
								// verbatim; a slot it binds reads the parameter, any
								// other slot falls back to its initform.
								boaLambdaList = optParts.get(2);
							}
						}
						else {
							suppressConstructor = true;
						}
					}
					case ":CONC-NAME" -> {
						concNameGiven = true;
						if (optValue instanceof LispSymbol s) {
							PackageRegistry.QualifiedName cqn = PackageRegistry.splitQualified(s.name());
							concNameOverride = cqn == null ? s.name() : cqn.member();
						}
						else if (optValue instanceof LispString s) {
							concNameOverride = s.value();
						}
						else {
							concNameOverride = "";
						}
					}
					case ":PREDICATE" -> {
						if (optValue instanceof LispSymbol s) {
							customPredicate = s.name();
						}
						else {
							suppressPredicate = true;
						}
					}
					case ":COPIER" -> {
						if (optValue instanceof LispSymbol s) {
							customCopier = s.name();
						}
						else {
							suppressCopier = true;
						}
					}
					case ":INCLUDE" -> {
						// (:include parent (slot new-default [options...]) ...): each
						// trailing spec re-defaults ONE inherited slot in this child's
						// layout (the parent's own default is untouched). The slot keeps
						// its inherited index, so the parent's accessors still read it.
						if (optParts.size() < 2 || !(optValue instanceof LispSymbol inc)) {
							throw new UnsupportedOperationException(
									LispNames.DEFSTRUCT + " option is not supported: " + option.print());
						}
						includeParent = inc.name();
						for (LispVal override : optParts.subList(2, optParts.size())) {
							if (!(override instanceof LispCons ovCons)
									|| !(ovCons.car() instanceof LispSymbol ovSlot)) {
								throw new UnsupportedOperationException(LispNames.DEFSTRUCT
										+ " :include slot override must be (slot default): " + option.print());
							}
							List<LispVal> ovParts = ovCons.toList();
							PackageRegistry.QualifiedName ovQn = PackageRegistry.splitQualified(ovSlot.name());
							includeOverrides.put(ovQn == null ? ovSlot.name() : ovQn.member(),
									ovParts.size() >= 2 ? ovParts.get(1) : LispNil.INSTANCE);
						}
					}
					case ":TYPE" -> {
						// Only the vector shape: the struct is a plain vector (no
						// instance
						// tag), accessors are aref reads at the slot index. (:type list)
						// is not supported.
						boolean vectorShape = (optValue instanceof LispSymbol ts && "VECTOR".equals(plainTypeName(ts)))
								|| (optValue instanceof LispCons tc && tc.car() instanceof LispSymbol th
										&& "VECTOR".equals(plainTypeName(th)));
						if (!vectorShape) {
							throw new UnsupportedOperationException(
									LispNames.DEFSTRUCT + " option is not supported: " + option.print());
						}
						typedVector = true;
					}
					default -> throw new UnsupportedOperationException(
							LispNames.DEFSTRUCT + " option is not supported: " + option.print());
				}
			}
		}
		else {
			throw new UnsupportedOperationException(
					LispNames.DEFSTRUCT + " options are not supported: " + parts.get(1).print());
		}
		String structName = nameSym.name();
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(structName);
		// A generated name of a qualified struct lands in the struct's package, spelled
		// exactly as the resolver spells that symbol at a CALL site: one colon when the
		// defpackage exports it, two otherwise. Without the oracle (a direct
		// expandDefstruct caller that has no resolver) every generated name takes the
		// internal spelling -- correct for a struct whose names are not exported, which
		// is what every caller before quri had.
		java.util.function.UnaryOperator<String> inPackage = member -> qn == null ? member
				: exported != null && exported.test(qn.pkg(), member) ? PackageRegistry.qualify(qn.pkg(), member)
						: PackageRegistry.qualifyInternal(qn.pkg(), member);
		String base = qn == null ? structName : qn.member();
		String concName = concNameGiven ? (concNameOverride == null ? "" : concNameOverride) : base + "-";
		// Synthesized affixes follow the base name's case: an upcased-reader struct PT
		// gets MAKE-PT/PT-P/COPY-PT (matching the call sites the reader upcases), while
		// a lowercase-authored internal struct keeps make-/-p/copy-.
		String makeAffix = affixFor("make-", base);
		String pAffix = affixFor("-p", base);
		String copyAffix = affixFor("copy-", base);
		String structTag = LispLayout.STRUCT_TAG_PREFIX + structName;
		List<LispSymbol> slotSyms = new java.util.ArrayList<>();
		List<String> slotBases = new java.util.ArrayList<>();
		List<LispVal> slotDefaults = new java.util.ArrayList<>();
		List<LispVal> slotSpecs = parts.subList(2, parts.size());
		if (!slotSpecs.isEmpty() && slotSpecs.get(0) instanceof LispString) {
			// (defstruct name "docstring" slot...): the documentation string is dropped.
			slotSpecs = slotSpecs.subList(1, slotSpecs.size());
		}
		for (LispVal spec : slotSpecs) {
			LispSymbol slot;
			LispVal dflt = LispNil.INSTANCE;
			if (spec instanceof LispSymbol s) {
				slot = s;
			}
			else if (spec instanceof LispCons specCons && specCons.car() instanceof LispSymbol s) {
				slot = s;
				List<LispVal> specParts = specCons.toList();
				if (specParts.size() >= 2) {
					dflt = specParts.get(1);
				}
				// Slot options after the initform: :type and :read-only are parsed and
				// ignored (declarations are no-ops); anything else is a hard error.
				for (int i = 2; i + 1 < specParts.size(); i += 2) {
					if (!(specParts.get(i) instanceof LispSymbol opt)
							|| (!":TYPE".equals(opt.name()) && !":READ-ONLY".equals(opt.name()))) {
						throw new IllegalArgumentException(
								LispNames.DEFSTRUCT + " slot option is not supported: " + spec.print());
					}
				}
			}
			else {
				throw new IllegalArgumentException(
						LispNames.DEFSTRUCT + " expects a slot name or (name default), got " + spec.print());
			}
			PackageRegistry.QualifiedName slotQn = PackageRegistry.splitQualified(slot.name());
			slotSyms.add(slot);
			slotBases.add(slotQn == null ? slot.name() : slotQn.member());
			slotDefaults.add(dflt);
		}
		if (includeParent != null) {
			// (:include parent): the parent's slots (its own layout order, so a chain
			// nests) come first, keeping every inherited slot at the same index in all
			// descendants -- the parent's accessors then work on child instances as-is.
			if (typedVector) {
				throw new UnsupportedOperationException(
						LispNames.DEFSTRUCT + " :include on a :type struct is not supported: " + cons.print());
			}
			if (closRegistry == null) {
				throw new UnsupportedOperationException(
						LispNames.DEFSTRUCT + " :include is not supported here (no type registry): " + cons.print());
			}
			LispLayout parentLayout = closRegistry.findStructLayout(includeParent);
			if (parentLayout == null) {
				throw new IllegalArgumentException(
						LispNames.DEFSTRUCT + " :include names an unknown struct: " + includeParent);
			}
			List<LispSymbol> mergedSyms = new java.util.ArrayList<>();
			List<String> mergedBases = new java.util.ArrayList<>();
			List<LispVal> mergedDefaults = new java.util.ArrayList<>();
			for (int i = 0; i < parentLayout.slotNames().size(); i++) {
				String inherited = parentLayout.slotNames().get(i);
				mergedSyms.add(new LispSymbol(inherited));
				mergedBases.add(inherited);
				LispVal override = includeOverrides.remove(inherited);
				mergedDefaults.add(override != null ? override : parentLayout.initforms().get(i));
			}
			if (!includeOverrides.isEmpty()) {
				throw new IllegalArgumentException(LispNames.DEFSTRUCT + " :include " + includeParent
						+ " overrides slots it does not define: " + includeOverrides.keySet());
			}
			mergedSyms.addAll(slotSyms);
			mergedBases.addAll(slotBases);
			mergedDefaults.addAll(slotDefaults);
			slotSyms = mergedSyms;
			slotBases = mergedBases;
			slotDefaults = mergedDefaults;
		}
		// Registered only after the slot loop: the layout carries the ordered slot names
		// and initforms, which is what makes an instance self-describing to the printer
		// and what #S(...) reading permutes its keyword arguments against. A :type
		// vector struct is NOT registered: its "instances" are plain vectors with no
		// instance tag, so it is not a specializer/typep type (CL agrees -- a typed
		// struct is not a structure-object).
		if (closRegistry != null && !typedVector) {
			closRegistry.registerStruct(structName, includeParent, slotBases, slotDefaults);
		}
		List<LispVal> forms = new java.util.ArrayList<>();
		// (defun make-<base> (&key ((:slot slot) default)...) (%obj-new '%struct-<name>
		// slot...))
		List<LispVal> lambdaList = new java.util.ArrayList<>();
		if (!slotSyms.isEmpty()) {
			lambdaList.add(new LispSymbol(LispNames.LAMBDA_KEY));
			for (int i = 0; i < slotSyms.size(); i++) {
				LispVal keywordAndVar = listToCons(List.of(new LispSymbol(":" + slotBases.get(i)), slotSyms.get(i)));
				lambdaList.add(listToCons(List.of(keywordAndVar, slotDefaults.get(i))));
			}
		}
		if (!suppressConstructor) {
			String constructorName = customConstructor != null ? customConstructor : inPackage.apply(makeAffix + base);
			if (boaLambdaList != null) {
				// (defun name (<boa lambda list>) (%obj-new '%struct-<name> value...)):
				// a slot bound by the lambda list reads that parameter, the rest
				// evaluate their initforms in the constructor body.
				java.util.Map<String, LispSymbol> boaParams = boaParameterSymbols(boaLambdaList);
				List<LispVal> boaValues = new java.util.ArrayList<>();
				for (int i = 0; i < slotSyms.size(); i++) {
					LispSymbol param = boaParams.get(slotBases.get(i));
					boaValues.add(param != null ? param : slotDefaults.get(i));
				}
				forms.add(listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(constructorName),
						boaLambdaList, typedVector ? vectorOf(boaValues) : objNew(structTag, boaValues))));
			}
			else {
				// A slot-less struct has an EMPTY lambda list, which is nil rather than a
				// cons -- listToCons would blow up casting it.
				LispVal params0 = lambdaList.isEmpty() ? LispNil.INSTANCE : listToCons(lambdaList);
				forms.add(listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(constructorName), params0,
						typedVector ? vectorOf(List.copyOf(slotSyms)) : objNew(structTag, List.copyOf(slotSyms)))));
			}
		}
		// (defun <base>-p (__struct) (%obj-is __struct '%struct-<name> ...)): the tag
		// set covers the struct and its :include descendants. Only those registered SO
		// FAR are known here, so the predicate is REGENERATED once a later child widens
		// the set -- by the interpreter's evalDefstruct and, on the compile path, by
		// refreshStructPredicates after the whole program is registered.
		LispSymbol obj = new LispSymbol(STRUCT_VAR);
		LispVal params = listToCons(List.<LispVal>of(obj));
		if (!suppressPredicate && !typedVector) {
			String predicateName = customPredicate != null ? customPredicate : inPackage.apply(base + pAffix);
			forms.add(structPredicateDefun(structName, predicateName, closRegistry));
			if (closRegistry != null) {
				closRegistry.registerStructPredicate(structName, predicateName);
			}
		}
		// (defun copy-<base> (__struct) (%obj-new '%struct-<name> (%obj-ref __struct 0)
		// ...)): a shallow copy, like copy-structure -- the slot values are shared. A
		// :type vector struct copies with copy-seq (it IS a vector).
		if (!suppressCopier) {
			String copierName = customCopier != null ? customCopier : inPackage.apply(copyAffix + base);
			if (typedVector) {
				forms.add(listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(copierName), params,
						callOf(LispNames.COPY_SEQ, obj))));
			}
			else {
				List<LispVal> copied = new java.util.ArrayList<>();
				for (int i = 0; i < slotSyms.size(); i++) {
					copied.add(objRef(obj, i));
				}
				forms.add(listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(copierName), params,
						objNew(structTag, copied))));
			}
		}
		// (defun <conc-name><slot> (__struct) (%obj-ref __struct <index>))
		// The slot part case-matches the struct base: a slot named after a CL symbol
		// (md5's `block`) folds to lowercase while the upcase-read struct name stays
		// upper, and the accessor must match its fully-upcased call sites
		// (MD5-STATE-BLOCK). A :type vector struct reads with aref and writes through a
		// generated %setf-<accessor> writer defun (the setf-function protocol), since
		// there is no instance object to %obj-set.
		for (int i = 0; i < slotSyms.size(); i++) {
			String accessor = inPackage.apply(concName + affixFor(slotBases.get(i), base));
			if (typedVector) {
				LispVal arefRead = listToCons(List.of(new LispSymbol(LispNames.AREF), obj, new LispInteger(i)));
				forms.add(listToCons(
						List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(accessor), params, arefRead)));
				LispSymbol newVal = new LispSymbol("__struct_newval");
				LispVal writerParams = listToCons(List.<LispVal>of(newVal, obj));
				LispVal arefPlace = listToCons(List.of(new LispSymbol(LispNames.AREF), obj, new LispInteger(i)));
				LispVal store = listToCons(List.of(new LispSymbol(LispNames.SETF), arefPlace, newVal));
				forms.add(listToCons(List.of(new LispSymbol(LispNames.DEFUN),
						new LispSymbol(setfFunctionName(accessor)), writerParams, store)));
				structAccessors.put(accessor, SETF_FUNCTION_MARKER);
			}
			else {
				forms.add(listToCons(
						List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(accessor), params, objRef(obj, i))));
				structAccessors.put(accessor, i + 1);
			}
		}
		return forms;
	}

	/** A {@code (vector v...)} construction form (the :type vector struct instance). */
	private static LispVal vectorOf(List<LispVal> values) {
		List<LispVal> call = new java.util.ArrayList<>();
		call.add(new LispSymbol(LispNames.VECTOR));
		call.addAll(values);
		return listToCons(call);
	}

	private static final String STRUCT_VAR = "__struct";

	/**
	 * Collects the parameter symbols a BOA constructor lambda list binds, keyed by their
	 * plain (package-stripped) name so they can be matched against slot names.
	 * Lambda-list markers ({@code &optional}/{@code &rest}/{@code &key}/{@code &aux}/
	 * {@code &allow-other-keys}) are skipped; {@code (name default)} entries bind
	 * {@code name}.
	 * @param lambdaList the BOA lambda list (possibly nil)
	 * @return plain parameter name to the symbol as written
	 */
	private static java.util.Map<String, LispSymbol> boaParameterSymbols(LispVal lambdaList) {
		java.util.Map<String, LispSymbol> bound = new java.util.LinkedHashMap<>();
		LispVal cur = lambdaList;
		while (cur instanceof LispCons c) {
			LispVal item = c.car();
			LispSymbol var = null;
			if (item instanceof LispSymbol s && !s.name().startsWith("&")) {
				var = s;
			}
			else if (item instanceof LispCons pc && pc.car() instanceof LispSymbol s) {
				var = s;
			}
			if (var != null) {
				PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(var.name());
				bound.put(qn == null ? var.name() : qn.member(), var);
			}
			cur = c.cdr();
		}
		return bound;
	}

	private static boolean isDefstructForm(LispVal form) {
		return form instanceof LispCons cons && cons.car() instanceof LispSymbol sym
				&& LispNames.DEFSTRUCT.equals(sym.name());
	}

	/**
	 * Builds a struct predicate defun --
	 * {@code (defun P (__struct) (%obj-is __struct '%struct-<name> <descendant tags>...))}
	 * -- from the registry AS IT STANDS. Every caller that learns about a new
	 * {@code :include} child rebuilds the ancestors' predicates through here, so
	 * {@code (base-p child)} is true whichever order the two defstructs were processed
	 * in.
	 * @param structName the struct name as spelled in its defstruct
	 * @param predicateName the predicate defun name
	 * @param closRegistry the type registry (null yields the struct's own tag only)
	 * @return the predicate defun form
	 */
	public static LispVal structPredicateDefun(String structName, String predicateName,
			@org.jspecify.annotations.Nullable ClosRegistry closRegistry) {
		String ownTag = LispLayout.STRUCT_TAG_PREFIX + structName;
		List<String> tags = (closRegistry == null) ? List.of() : closRegistry.descendantStructTags(structName);
		if (tags.isEmpty()) {
			tags = List.of(ownTag);
		}
		LispSymbol obj = new LispSymbol(STRUCT_VAR);
		return listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(predicateName),
				listToCons(List.<LispVal>of(obj)), objIs(obj, tags)));
	}

	/**
	 * Rebuilds every generated struct predicate in an expanded top-level program, now
	 * that the whole program is registered: a predicate emitted before its
	 * {@code :include} children were seen tests too few tags. Runs in the same "registry
	 * is complete" phase as the method dispatchers. Only a form that still IS the
	 * generated predicate is replaced (name recorded in the registry AND the generated
	 * {@code (%obj-is __struct ...)} body shape), so a program that redefines the name
	 * itself keeps its own defun.
	 * @param out the expanded program, updated in place
	 * @param closRegistry the type registry
	 */
	private static void refreshStructPredicates(List<LispVal> out, @Nullable ClosRegistry closRegistry) {
		if (closRegistry == null || closRegistry.structPredicates().isEmpty()) {
			return;
		}
		java.util.Map<String, String> structByPredicate = new java.util.HashMap<>();
		for (java.util.Map.Entry<String, String> entry : closRegistry.structPredicates().entrySet()) {
			structByPredicate.put(entry.getValue(), entry.getKey());
		}
		for (int i = 0; i < out.size(); i++) {
			if (!(out.get(i) instanceof LispCons form) || !isNamedForm(form, LispNames.DEFUN)) {
				continue;
			}
			List<LispVal> parts = form.toList();
			if (parts.size() != 4 || !(parts.get(1) instanceof LispSymbol name)) {
				continue;
			}
			String structName = structByPredicate.get(name.name());
			if (structName == null || !isGeneratedStructPredicateBody(parts.get(2), parts.get(3))) {
				continue;
			}
			out.set(i, structPredicateDefun(structName, name.name(), closRegistry));
		}
	}

	// The generated shape: a single __struct parameter and a (%obj-is __struct ...) body.
	private static boolean isGeneratedStructPredicateBody(LispVal params, LispVal body) {
		return params instanceof LispCons paramList && paramList.toList().size() == 1
				&& paramList.car() instanceof LispSymbol param && STRUCT_VAR.equals(param.name())
				&& body instanceof LispCons call && call.car() instanceof LispSymbol op
				&& LispNames.OBJ_IS.equals(op.name());
	}

	private static final String CLOS_OBJ_VAR = "__obj";

	/** A shared never-mutated registry for the expandSetf overloads without CLOS. */
	private static final ClosRegistry EMPTY_CLOS_REGISTRY = new ClosRegistry();

	/**
	 * Expands {@code (defclass name (superclass?) ((slot options...)...) options...)}
	 * into the defuns it generates -- an internal keyword constructor plus one defun per
	 * {@code :reader}/{@code :accessor} -- and records the class (slot layout, ancestor
	 * set) in the registry. An instance is a first-class object built by {@code %obj-new}
	 * whose slot layout is the superclass slots (in inheritance order) followed by the
	 * class's own slots, so single inheritance keeps every inherited slot at the same
	 * index in all descendants.
	 *
	 * <pre>
	 * (defclass dog (animal) ((breed :initarg :breed :initform "mixed" :reader dog-breed))) ->
	 * (defun %make-dog (&amp;key ((:name name) nil) ((:breed breed) "mixed")) (%obj-new '%class-dog name breed))
	 * (defun dog-breed (__obj) (%obj-ref __obj 1))
	 * </pre>
	 *
	 * Lite subset: at most one superclass; a slot's {@code :initarg} defaults to the
	 * slot-name keyword and its {@code :initform} to nil (no unbound-slot state);
	 * {@code :accessor} names are also recorded in {@code structAccessors} so they are
	 * {@code setf} places. Unsupported class/slot options throw
	 * {@link UnsupportedOperationException}; the class option
	 * {@code (:documentation ...)} is accepted and ignored.
	 * @param cons the defclass expression (canonical, package-resolved spelling)
	 * @param closRegistry mutated: the class is registered
	 * @param structAccessors mutated: accessor name to 1-based slot position
	 * @return the generated top-level forms, in definition order
	 */
	public static List<LispVal> expandDefclass(LispCons cons, ClosRegistry closRegistry,
			java.util.Map<String, Integer> structAccessors) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3 || !(parts.get(1) instanceof LispSymbol nameSym)) {
			throw new IllegalArgumentException(
					LispNames.DEFCLASS + " expects a class name and a superclass list: " + cons.print());
		}
		String className = nameSym.name();
		// Superclass list: every named superclass must already be registered. The
		// FIRST superclass provides the layout prefix; the others contribute their
		// remaining slots after it (see the merge below).
		List<ClosRegistry.ClassInfo> superInfos = new java.util.ArrayList<>();
		if (parts.get(2) instanceof LispCons superCons) {
			for (LispVal superVal : superCons.toList()) {
				if (!(superVal instanceof LispSymbol superSym)) {
					throw new IllegalArgumentException(
							LispNames.DEFCLASS + " expects a superclass name: " + cons.print());
				}
				ClosRegistry.ClassInfo found = closRegistry.findClass(superSym.name());
				if (found == null) {
					throw new IllegalArgumentException(LispNames.DEFCLASS + ": unknown superclass " + superSym.name()
							+ " (a superclass must be defined by defclass first)");
				}
				if (superInfos.contains(found)) {
					throw new IllegalArgumentException(
							LispNames.DEFCLASS + ": duplicate superclass " + superSym.name() + ": " + cons.print());
				}
				superInfos.add(found);
			}
		}
		else if (!(parts.get(2) instanceof LispNil)) {
			throw new IllegalArgumentException(LispNames.DEFCLASS + " expects a superclass list: " + cons.print());
		}
		ClosRegistry.ClassInfo superInfo = superInfos.isEmpty() ? null : superInfos.get(0);
		List<String> cpl = computeCpl(className, superInfos, closRegistry);
		// Class options after the slot list: (:documentation "...") is accepted and
		// ignored; (:default-initargs :initarg form ...) overrides the matching slots'
		// constructor defaults (evaluated at make-instance time when the initarg is
		// absent, like CL). (:metaclass M) switches on the metaclass protocol: any
		// OTHER unknown class option then becomes a metaclass initarg whose value is
		// the option's tail list (AMOP canonicalization -- postmodern's
		// (:table-name "users") arrives as :table-name ("users")), instead of erroring.
		java.util.Map<String, LispVal> defaultInitargs = new java.util.LinkedHashMap<>();
		String metaclassName = null;
		List<LispVal> classInitargs = new java.util.ArrayList<>();
		for (int i = 4; i < parts.size(); i++) {
			if (parts.get(i) instanceof LispCons optCons && optCons.car() instanceof LispSymbol optSym
					&& ":METACLASS".equals(plainTypeName(optSym))) {
				List<LispVal> option = optCons.toList();
				if (option.size() != 2 || !(option.get(1) instanceof LispSymbol metaclassSym)) {
					throw new IllegalArgumentException(
							LispNames.DEFCLASS + " :metaclass expects a class name: " + cons.print());
				}
				ClosRegistry.ClassInfo metaclassInfo = closRegistry.findClass(metaclassSym.name());
				if (metaclassInfo == null || !metaclassInfo.ancestors().contains(ClosRegistry.STANDARD_CLASS_NAME)) {
					throw new IllegalArgumentException(LispNames.DEFCLASS + " :metaclass must name a class inheriting "
							+ "standard-class, defined before its first use: " + metaclassSym.name());
				}
				metaclassName = metaclassInfo.name();
			}
		}
		for (int i = 4; i < parts.size(); i++) {
			if (parts.get(i) instanceof LispCons optCons && optCons.car() instanceof LispSymbol optSym
					&& (":DOCUMENTATION".equals(plainTypeName(optSym)) || ":METACLASS".equals(plainTypeName(optSym)))) {
				continue;
			}
			if (parts.get(i) instanceof LispCons optCons && optCons.car() instanceof LispSymbol optSym
					&& ":DEFAULT-INITARGS".equals(plainTypeName(optSym))) {
				List<LispVal> pairs = optCons.toList();
				for (int j = 1; j + 1 < pairs.size(); j += 2) {
					if (!(pairs.get(j) instanceof LispSymbol key) || !key.name().startsWith(":")) {
						throw new IllegalArgumentException(
								LispNames.DEFCLASS + " :default-initargs expects keyword/form pairs: " + cons.print());
					}
					defaultInitargs.put(key.name(), pairs.get(j + 1));
				}
				continue;
			}
			if (metaclassName != null && parts.get(i) instanceof LispCons optCons
					&& optCons.car() instanceof LispSymbol optSym && optSym.isKeyword()) {
				classInitargs.add(optSym);
				classInitargs.add(optCons.cdr());
				continue;
			}
			throw new UnsupportedOperationException(
					LispNames.DEFCLASS + " option is not supported: " + parts.get(i).print());
		}
		List<ParsedSlot> ownSlots = new java.util.ArrayList<>();
		if (parts.size() > 3 && parts.get(3) instanceof LispCons slotsCons) {
			for (LispVal spec : slotsCons.toList()) {
				ownSlots.add(parseDefclassSlot(spec, cons, metaclassName != null));
			}
		}
		else if (parts.size() > 3 && !(parts.get(3) instanceof LispNil)) {
			throw new IllegalArgumentException(LispNames.DEFCLASS + " expects a slot list: " + cons.print());
		}
		List<ClosRegistry.SlotSpec> slots = new java.util.ArrayList<>(
				superInfo == null ? List.of() : superInfo.slots());
		if (superInfos.size() > 1) {
			// Multiple inheritance: the first superclass's effective slots keep their
			// indexes (the layout prefix rule), each later superclass appends the slots
			// whose base name is not present yet, and every inherited slot's OPTIONS are
			// then re-merged from the direct specifications along the class precedence
			// list (a diamond re-declaration on a non-first superclass must still win
			// over the shared base's specification).
			for (int s = 1; s < superInfos.size(); s++) {
				for (ClosRegistry.SlotSpec spec : superInfos.get(s).slots()) {
					boolean present = slots.stream().anyMatch(x -> x.baseName().equals(spec.baseName()));
					if (!present) {
						slots.add(spec);
					}
				}
			}
			for (int i = 0; i < slots.size(); i++) {
				slots.set(i, cplMergedSlot(slots.get(i).baseName(), cpl, closRegistry, slots.get(i)));
			}
		}
		// index in `slots` -> the OWN specification contributing there. A slot name the
		// superclass already declares SHADOWS it (CLHS 7.5.3): the storage stays the one
		// inherited slot -- so every descendant keeps the index its ancestors baked --
		// while
		// the subclass specification overrides the initform and the initarg it writes and
		// ADDS its readers/accessors to the inherited ones. postmodern's savepoint-handle
		// re-declares transaction-handle's open-p/connection this way.
		java.util.Map<Integer, ClosRegistry.SlotSpec> ownAt = new java.util.LinkedHashMap<>();
		for (ParsedSlot parsed : ownSlots) {
			ClosRegistry.SlotSpec own = parsed.spec();
			int inheritedAt = -1;
			for (int i = 0; i < slots.size(); i++) {
				if (slots.get(i).baseName().equals(own.baseName())) {
					inheritedAt = i;
					break;
				}
			}
			if (inheritedAt < 0) {
				ownAt.put(slots.size(), own);
				slots.add(own);
				continue;
			}
			slots.set(inheritedAt, shadowSlot(slots.get(inheritedAt), parsed));
			ownAt.put(inheritedAt, own);
		}
		// (:default-initargs :initarg form) overrides the matching slot's effective
		// initform, which is where BOTH construction paths read it: the generated
		// constructor's keyword default and the registry initform the typed-signal
		// (error 'cond ...) instance builder fills unsupplied slots from.
		if (!defaultInitargs.isEmpty()) {
			for (int i = 0; i < slots.size(); i++) {
				LispVal override = defaultInitargs.get(slots.get(i).initargKeyword());
				if (override != null) {
					ClosRegistry.SlotSpec slot = slots.get(i);
					slots.set(i,
							new ClosRegistry.SlotSpec(slot.name(), slot.baseName(), override, true,
									slot.initargKeyword(), slot.initargSupplied(), slot.readers(), slot.accessors(),
									slot.type()));
				}
			}
		}
		java.util.Set<String> ancestors = new java.util.LinkedHashSet<>();
		for (ClosRegistry.ClassInfo info : superInfos) {
			ancestors.addAll(info.ancestors());
		}
		ancestors.add(ClosRegistry.normalize(className));
		List<ClosRegistry.SlotSpec> directSlots = ownSlots.stream().map(ParsedSlot::spec).toList();
		closRegistry.registerClass(
				new ClosRegistry.ClassInfo(className, superInfos.stream().map(ClosRegistry.ClassInfo::name).toList(),
						cpl, directSlots, List.copyOf(slots), java.util.Set.copyOf(ancestors)));
		for (int i = 0; i < slots.size(); i++) {
			closRegistry.registerSlotPosition(slots.get(i).baseName(), i + 1);
		}
		// (defun %make-<base> (&key ((:initarg slot) initform)...) (%obj-new
		// '%class-<name>
		// slot...))
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(className);
		String prefix = qn == null ? "" : qn.pkg() + "::";
		String base = qn == null ? className : qn.member();
		String classTag = LispLayout.CLASS_TAG_PREFIX + className;
		List<LispVal> lambdaList = new java.util.ArrayList<>();
		if (!slots.isEmpty()) {
			lambdaList.add(new LispSymbol(LispNames.LAMBDA_KEY));
			for (ClosRegistry.SlotSpec slot : slots) {
				LispVal keywordAndVar = listToCons(
						List.of(new LispSymbol(slot.initargKeyword()), new LispSymbol(slot.name())));
				lambdaList.add(listToCons(List.of(keywordAndVar, slot.initform())));
			}
			// A non-slot initarg is consumed by an initialize-instance/shared-initialize
			// method, not the constructor (ironclad's (make-instance 'hmac :key ...));
			// the lite model always tolerates extras instead of computing the valid
			// initarg set from the applicable methods.
			lambdaList.add(new LispSymbol(LispNames.LAMBDA_ALLOW_OTHER_KEYS));
		}
		List<LispVal> slotVars = new java.util.ArrayList<>();
		for (ClosRegistry.SlotSpec slot : slots) {
			slotVars.add(new LispSymbol(slot.name()));
		}
		List<LispVal> forms = new java.util.ArrayList<>();
		forms.add(listToCons(
				List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(prefix + affixFor("%make-", base) + base),
						lambdaList.isEmpty() ? LispNil.INSTANCE : listToCons(lambdaList), objNew(classTag, slotVars))));
		// Reader/accessor METHODS for the class's OWN slots (inherited slots keep the
		// methods their defining class generated; positions are shared and the class
		// test covers descendants). A reader is a defmethod, not a plain defun, because
		// several classes may declare the same reader name over DIFFERENT slot
		// positions (cl-ppcre's len lives at a different index in str/repetition/
		// lookbehind/filter) and a defmethod on the same name (len on void) must merge
		// with them instead of shadowing. The write side is a %setf- writer GENERIC
		// registered under the SETF_FUNCTION_MARKER convention, so
		// (setf (accessor x) v) funcalls the dispatcher with the CL setf-function
		// argument order (new value first).
		LispSymbol obj = new LispSymbol(CLOS_OBJ_VAR);
		LispSymbol newVal = new LispSymbol(CLOS_NEW_VAL_VAR);
		LispVal specialized = listToCons(List.<LispVal>of(listToCons(List.of(obj, new LispSymbol(className)))));
		for (java.util.Map.Entry<Integer, ClosRegistry.SlotSpec> entry : ownAt.entrySet()) {
			int i = entry.getKey();
			ClosRegistry.SlotSpec slot = entry.getValue();
			LispVal body = checkedSlotRead(obj, i, slots.get(i).baseName());
			LispVal writeBody = objSet(obj, i, newVal);
			LispVal writerParams = listToCons(List.of(newVal, listToCons(List.of(obj, new LispSymbol(className)))));
			for (String reader : slot.readers()) {
				forms.add(listToCons(
						List.of(new LispSymbol(LispNames.DEFMETHOD), new LispSymbol(reader), specialized, body)));
			}
			for (String accessor : slot.accessors()) {
				forms.add(listToCons(
						List.of(new LispSymbol(LispNames.DEFMETHOD), new LispSymbol(accessor), specialized, body)));
				forms.add(listToCons(List.of(new LispSymbol(LispNames.DEFMETHOD),
						new LispSymbol(setfFunctionName(accessor)), writerParams, writeBody)));
				structAccessors.put(accessor, SETF_FUNCTION_MARKER);
			}
		}
		if (superInfos.size() > 1) {
			// An inherited slot may sit at a DIFFERENT index here than in the ancestor
			// that declared its readers/accessors (only the first superclass's block
			// keeps its indexes). The ancestor's methods bake the ancestor's index and
			// their class test covers this class too, so synthesize overriding methods
			// specialized on THIS class for every shifted slot -- subclass-first
			// dispatch makes them win. Single inheritance never shifts, so nothing is
			// synthesized there.
			java.util.Set<String> ownEmitted = new java.util.HashSet<>();
			for (ClosRegistry.SlotSpec own : ownAt.values()) {
				ownEmitted.addAll(own.readers());
				ownEmitted.addAll(own.accessors());
			}
			for (int i = 0; i < slots.size(); i++) {
				ClosRegistry.SlotSpec slot = slots.get(i);
				if (slot.readers().isEmpty() && slot.accessors().isEmpty()) {
					continue;
				}
				boolean shifted = false;
				for (int c = 1; c < cpl.size() && !shifted; c++) {
					ClosRegistry.ClassInfo ancestor = closRegistry.findClass(cpl.get(c));
					if (ancestor == null) {
						continue;
					}
					for (int j = 0; j < ancestor.slots().size(); j++) {
						if (ancestor.slots().get(j).baseName().equals(slot.baseName()) && j != i) {
							shifted = true;
							break;
						}
					}
				}
				if (!shifted) {
					continue;
				}
				LispVal body = checkedSlotRead(obj, i, slot.baseName());
				LispVal writeBody = objSet(obj, i, newVal);
				LispVal writerParams = listToCons(List.of(newVal, listToCons(List.of(obj, new LispSymbol(className)))));
				for (String reader : slot.readers()) {
					if (!ownEmitted.contains(reader)) {
						forms.add(listToCons(List.of(new LispSymbol(LispNames.DEFMETHOD), new LispSymbol(reader),
								specialized, body)));
					}
				}
				for (String accessor : slot.accessors()) {
					if (ownEmitted.contains(accessor)) {
						continue;
					}
					forms.add(listToCons(
							List.of(new LispSymbol(LispNames.DEFMETHOD), new LispSymbol(accessor), specialized, body)));
					forms.add(listToCons(List.of(new LispSymbol(LispNames.DEFMETHOD),
							new LispSymbol(setfFunctionName(accessor)), writerParams, writeBody)));
					structAccessors.put(accessor, SETF_FUNCTION_MARKER);
				}
			}
		}
		if (metaclassName != null) {
			// The definition-time driver call, LAST among the generated forms: the class
			// is statically registered above, and every consumer evaluates the generated
			// forms in order at definition time (the interpreter's evalDefclass, the
			// compile paths' macro-time evaluator) or at program start in top-level order
			// (the compiled program), so the metaclass protocol runs with the class's
			// own definitions already in place.
			forms.add(ensureClassWithMetaclassCall(className, metaclassName, superInfos, ownSlots, classInitargs));
		}
		return forms;
	}

	/**
	 * Computes the class precedence list of a class being defined (CLHS 4.3.5): a
	 * topological sort of the class and its ancestors over the union of every local
	 * precedence order (each class precedes its direct superclasses, and each direct
	 * superclass list orders left to right), breaking ties by choosing the candidate with
	 * a direct subclass rightmost in the list built so far. Canonical names, the class
	 * itself first, registered classes only.
	 * @param className the class being defined (canonical spelling)
	 * @param superInfos its direct superclasses, in definition order
	 * @param closRegistry the registry resolving the inherited classes
	 * @return the class precedence list
	 */
	private static List<String> computeCpl(String className, List<ClosRegistry.ClassInfo> superInfos,
			ClosRegistry closRegistry) {
		if (superInfos.isEmpty()) {
			return List.of(className);
		}
		if (superInfos.size() == 1) {
			List<String> cpl = new java.util.ArrayList<>();
			cpl.add(className);
			cpl.addAll(superInfos.get(0).cpl());
			return List.copyOf(cpl);
		}
		// Every class reachable from the definition, mapped to its direct superclasses.
		java.util.LinkedHashMap<String, List<String>> directSupers = new java.util.LinkedHashMap<>();
		directSupers.put(className, superInfos.stream().map(ClosRegistry.ClassInfo::name).toList());
		java.util.ArrayDeque<ClosRegistry.ClassInfo> queue = new java.util.ArrayDeque<>(superInfos);
		while (!queue.isEmpty()) {
			ClosRegistry.ClassInfo info = queue.poll();
			if (directSupers.containsKey(info.name())) {
				continue;
			}
			directSupers.put(info.name(), info.superclasses());
			for (String superName : info.superclasses()) {
				ClosRegistry.ClassInfo superInfo = closRegistry.findClass(superName);
				if (superInfo != null) {
					queue.add(superInfo);
				}
			}
		}
		// The precedence pairs (a precedes b) of every local precedence order.
		List<String[]> pairs = new java.util.ArrayList<>();
		for (java.util.Map.Entry<String, List<String>> entry : directSupers.entrySet()) {
			String previous = entry.getKey();
			for (String superName : entry.getValue()) {
				pairs.add(new String[] { previous, superName });
				previous = superName;
			}
		}
		List<String> result = new java.util.ArrayList<>();
		java.util.Set<String> remaining = new java.util.LinkedHashSet<>(directSupers.keySet());
		while (!remaining.isEmpty()) {
			List<String> candidates = new java.util.ArrayList<>();
			for (String candidate : remaining) {
				boolean free = pairs.stream()
					.noneMatch(pair -> pair[1].equals(candidate) && remaining.contains(pair[0]));
				if (free) {
					candidates.add(candidate);
				}
			}
			if (candidates.isEmpty()) {
				throw new IllegalArgumentException(LispNames.DEFCLASS + ": no consistent class precedence order for "
						+ className + " (conflicting local precedence orders over " + remaining + ")");
			}
			String chosen = candidates.get(0);
			if (candidates.size() > 1) {
				int best = -1;
				for (String candidate : candidates) {
					int rightmost = -1;
					for (int i = 0; i < result.size(); i++) {
						List<String> supers = directSupers.get(result.get(i));
						if (supers != null && supers.contains(candidate)) {
							rightmost = i;
						}
					}
					if (rightmost > best) {
						best = rightmost;
						chosen = candidate;
					}
				}
			}
			result.add(chosen);
			remaining.remove(chosen);
		}
		return List.copyOf(result);
	}

	/**
	 * The CPL-merged effective specification of one inherited slot: the DIRECT
	 * specifications of the classes along the precedence list (excluding the class being
	 * defined -- its own slots merge through {@code shadowSlot}) folded least specific
	 * first, so a more specific class's re-declaration overrides the options it writes
	 * while readers/accessors accumulate.
	 */
	private static ClosRegistry.SlotSpec cplMergedSlot(String baseName, List<String> cpl, ClosRegistry closRegistry,
			ClosRegistry.SlotSpec fallback) {
		ClosRegistry.SlotSpec merged = null;
		for (int i = cpl.size() - 1; i >= 1; i--) {
			ClosRegistry.ClassInfo info = closRegistry.findClass(cpl.get(i));
			if (info == null) {
				continue;
			}
			for (ClosRegistry.SlotSpec direct : info.directSlots()) {
				if (direct.baseName().equals(baseName)) {
					merged = merged == null ? direct : shadowSlotSpec(merged, direct);
					break;
				}
			}
		}
		return merged == null ? fallback : merged;
	}

	/**
	 * Builds the {@code (%ensure-class-with-metaclass 'name 'metaclass '(supers)
	 * '(slot-specs) '(class-initargs))} driver call of a {@code :metaclass} defclass.
	 * Every argument is quoted data: the direct slot specs are canonicalized plists
	 * ({@code :name}/{@code :initargs}/{@code :initform}/{@code :type}/{@code :readers}
	 * -- the seeded slot-definition initarg contract -- followed by the slot's
	 * non-standard options verbatim), the class initargs are the unknown class options
	 * keyed by their keyword with the option TAIL as the value.
	 */
	private static LispVal ensureClassWithMetaclassCall(String className, String metaclassName,
			List<ClosRegistry.ClassInfo> superInfos, List<ParsedSlot> ownSlots, List<LispVal> classInitargs) {
		List<LispVal> slotSpecs = new java.util.ArrayList<>();
		for (ParsedSlot parsed : ownSlots) {
			ClosRegistry.SlotSpec slot = parsed.spec();
			List<LispVal> spec = new java.util.ArrayList<>();
			spec.add(new LispSymbol(":NAME"));
			spec.add(new LispSymbol(slot.baseName()));
			spec.add(new LispSymbol(":INITARGS"));
			spec.add(listToCons(List.of(new LispSymbol(slot.initargKeyword()))));
			spec.add(new LispSymbol(":INITFORM"));
			spec.add(slot.initformSupplied() ? slot.initform() : LispNil.INSTANCE);
			spec.add(new LispSymbol(":TYPE"));
			spec.add(new LispSymbol(slot.type()));
			spec.add(new LispSymbol(":READERS"));
			List<String> readerNames = new java.util.ArrayList<>(slot.readers());
			readerNames.addAll(slot.accessors());
			LispVal readers = LispNil.INSTANCE;
			for (int i = readerNames.size() - 1; i >= 0; i--) {
				readers = new LispCons(new LispSymbol(readerNames.get(i)), readers);
			}
			spec.add(readers);
			spec.addAll(parsed.extras());
			slotSpecs.add(listToCons(spec));
		}
		LispVal supers = superInfos.isEmpty() ? LispNil.INSTANCE
				: listToCons(superInfos.stream().<LispVal>map(info -> new LispSymbol(info.name())).toList());
		return listToCons(List.of(new LispSymbol(LispNames.ENSURE_CLASS_WITH_METACLASS), quoteOf(className),
				quoteOf(metaclassName), quotedData(supers),
				quotedData(slotSpecs.isEmpty() ? LispNil.INSTANCE : listToCons(slotSpecs)),
				quotedData(classInitargs.isEmpty() ? LispNil.INSTANCE : listToCons(classInitargs))));
	}

	/** Builds a {@code (quote datum)} form around an arbitrary value. */
	private static LispVal quotedData(LispVal datum) {
		return listToCons(List.of(new LispSymbol(LispNames.QUOTE), datum));
	}

	/** Parameter holding the new value in a generated {@code %setf-} writer method. */
	private static final String CLOS_NEW_VAL_VAR = "__new";

	/**
	 * One parsed {@code defclass} slot specification plus the options it EXPLICITLY
	 * wrote. A shadowing subclass slot inherits every option it does not write (CLHS
	 * 7.5.3), so "written or not" has to survive parsing -- {@code SlotSpec} alone cannot
	 * tell an omitted {@code :initarg} from one that happens to equal the default.
	 * {@code extras} holds the non-standard slot options a {@code :metaclass} class may
	 * carry ({@code :col-type}, {@code :column}, ...), as an alternating keyword/value
	 * list in source order: they are stripped from the static {@code SlotSpec} and handed
	 * to {@code direct-slot-definition-class} as initargs by the definition-time driver
	 * (single occurrence per key, the AMOP canonicalization for one appearance).
	 */
	private record ParsedSlot(ClosRegistry.SlotSpec spec, boolean initargSupplied, List<LispVal> extras) {
	}

	/**
	 * Merges a subclass slot specification onto the inherited one it shadows: the STORAGE
	 * (name, index) stays the superclass's, the initform/initarg/type are overridden only
	 * where the subclass wrote them, and the readers/accessors accumulate (CL computes
	 * the effective slot definition this way, which is why a shadowing slot does not lose
	 * the superclass's accessor).
	 */
	private static ClosRegistry.SlotSpec shadowSlot(ClosRegistry.SlotSpec inherited, ParsedSlot parsed) {
		return shadowSlotSpec(inherited, parsed.spec());
	}

	/**
	 * The {@link #shadowSlot} merge over two effective/direct specifications: the
	 * {@code SlotSpec} suppliedness flags say which options the more specific
	 * specification wrote. Used by the multiple-inheritance CPL fold
	 * ({@link #cplMergedSlot}), where the shadowing specification is an ancestor's direct
	 * spec rather than a just-parsed own slot.
	 */
	private static ClosRegistry.SlotSpec shadowSlotSpec(ClosRegistry.SlotSpec inherited, ClosRegistry.SlotSpec own) {
		List<String> readers = new java.util.ArrayList<>(inherited.readers());
		own.readers().stream().filter(r -> !readers.contains(r)).forEach(readers::add);
		List<String> accessors = new java.util.ArrayList<>(inherited.accessors());
		own.accessors().stream().filter(a -> !accessors.contains(a)).forEach(accessors::add);
		return new ClosRegistry.SlotSpec(inherited.name(), inherited.baseName(),
				own.initformSupplied() ? own.initform() : inherited.initform(),
				own.initformSupplied() || inherited.initformSupplied(),
				own.initargSupplied() ? own.initargKeyword() : inherited.initargKeyword(),
				own.initargSupplied() || inherited.initargSupplied(), List.copyOf(readers), List.copyOf(accessors),
				"T".equals(own.type()) ? inherited.type() : own.type());
	}

	/**
	 * Builds a fresh slot-unbound marker, the value a slot with no {@code :initform} (and
	 * one {@code slot-makunbound} emptied) holds. It is an instance of a layout-only
	 * internal type, so testing for it is the same one-compare {@code %obj-is} every
	 * instance-of test is, on all four backends.
	 * @return the {@code (%obj-new '%class-%UNBOUND%)} expression
	 */
	public static LispVal unboundMarker() {
		return objNew(ClosRegistry.UNBOUND_TAG, List.of());
	}

	/**
	 * Builds a BOUNDNESS-CHECKED read of slot {@code index} of {@code objVar}: the value
	 * unless it is the unbound marker, in which case {@code unbound-slot} is signalled.
	 * {@code objVar} must be a variable (or another expression safe to evaluate twice) --
	 * the helper is handed it again as the condition's {@code instance}.
	 */
	private static LispVal checkedSlotRead(LispVal objVar, int index, String baseName) {
		return slotReadCall(objRef(objVar, index), objVar, baseName);
	}

	/**
	 * Builds {@code (%slot-read value instance 'NAME)}. The test is a CALL, not the
	 * inlined {@code %obj-is} + {@code if}: an inline instance-of test is ~60 bytes of
	 * JVM bytecode, and with one per accessor and per {@code slot-value} the ci-spec
	 * corpus ran the top-level method past the 64 KB method limit
	 * ({@code .kb/jvm-method-size-limits.md}).
	 */
	private static LispVal slotReadCall(LispVal value, LispVal objVar, String baseName) {
		return listToCons(List.of(new LispSymbol(LispNames.SLOT_READ_INTERNAL), value, objVar,
				quoteOf(baseName.toUpperCase(java.util.Locale.ROOT))));
	}

	/** Builds {@code (%slot-bound-p value)} -- the out-of-line unbound-marker test. */
	private static LispVal boundValueTest(LispVal value) {
		return listToCons(List.of(new LispSymbol(LispNames.SLOT_BOUND_P_INTERNAL), value));
	}

	/**
	 * The two one-line helpers every boundness-checked slot read and every
	 * {@code slot-boundp} arm calls, kept out of line so a read stays ONE call no matter
	 * how large the instance-of test and the typed-signal expansion are. The compile path
	 * emits them once per program that needs them ({@code expandTopLevelDefinitions});
	 * the interpreter evaluates them on the first resolution of either name.
	 * @return the {@code %slot-read} and {@code %slot-bound-p} defuns
	 */
	public static List<LispVal> slotUnboundDefuns() {
		LispSymbol value = new LispSymbol("__value");
		LispSymbol instance = new LispSymbol("__instance");
		LispSymbol name = new LispSymbol("__name");
		LispVal isUnbound = objIs(value, List.of(ClosRegistry.UNBOUND_TAG));
		LispVal signal = listToCons(List.of(new LispSymbol(LispNames.ERROR), quoteOf("UNBOUND-SLOT"),
				new LispSymbol(":NAME"), name, new LispSymbol(":INSTANCE"), instance));
		LispVal read = listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.SLOT_READ_INTERNAL),
				listToCons(List.of(value, instance, name)), makeIf(isUnbound, signal, value)));
		LispVal boundp = listToCons(List.of(new LispSymbol(LispNames.DEFUN),
				new LispSymbol(LispNames.SLOT_BOUND_P_INTERNAL), listToCons(List.of(value)),
				makeIf(objIs(value, List.of(ClosRegistry.UNBOUND_TAG)), LispNil.INSTANCE, LispTrue.INSTANCE)));
		return List.of(read, boundp);
	}

	/**
	 * Parses one defclass slot specification; see {@link #expandDefclass}. With
	 * {@code metaclassPresent}, an unknown slot option is collected into the parsed
	 * slot's {@code extras} instead of erroring -- the metaclass protocol's
	 * {@code direct-slot-definition-class} initargs; without a metaclass the strict error
	 * stays.
	 */
	private static ParsedSlot parseDefclassSlot(LispVal spec, LispCons defclassForm, boolean metaclassPresent) {
		LispSymbol slotSym;
		// No :initform means the slot starts UNBOUND (CLHS 7.5.3), not nil.
		LispVal initform = unboundMarker();
		boolean initformSupplied = false;
		String initarg = null;
		String type = "T";
		List<String> readers = new java.util.ArrayList<>();
		List<String> accessors = new java.util.ArrayList<>();
		List<LispVal> extras = new java.util.ArrayList<>();
		if (spec instanceof LispSymbol s) {
			slotSym = s;
		}
		else if (spec instanceof LispCons specCons && specCons.car() instanceof LispSymbol s) {
			slotSym = s;
			List<LispVal> specParts = specCons.toList();
			if (specParts.size() % 2 == 0) {
				throw new IllegalArgumentException(
						LispNames.DEFCLASS + " expects (slot-name option value ...): " + spec.print());
			}
			for (int i = 1; i < specParts.size(); i += 2) {
				if (!(specParts.get(i) instanceof LispSymbol keySym && keySym.isKeyword())) {
					throw new IllegalArgumentException(
							LispNames.DEFCLASS + " expects a keyword slot option, got " + specParts.get(i).print());
				}
				LispVal optValue = specParts.get(i + 1);
				switch (keySym.name()) {
					case ":INITARG" -> {
						if (!(optValue instanceof LispSymbol kw && kw.isKeyword())) {
							throw new IllegalArgumentException(
									LispNames.DEFCLASS + " :initarg expects a keyword: " + spec.print());
						}
						initarg = kw.name();
					}
					case ":INITFORM" -> {
						initform = optValue;
						initformSupplied = true;
					}
					case ":READER" -> readers.add(requireSlotFunctionName(optValue, spec));
					case ":ACCESSOR" -> accessors.add(requireSlotFunctionName(optValue, spec));
					case ":DOCUMENTATION" -> {
						// Accepted and dropped (docstrings are not stored anywhere).
					}
					case ":TYPE" -> {
						// Recorded for introspection only (%class-slot-defs; JSON
						// serializers disambiguate a nil value by declared type); still a
						// no-op for checking, like declare/the. A compound specifier is
						// kept as t (lite).
						if (optValue instanceof LispSymbol typeSym) {
							type = plainTypeName(typeSym);
						}
					}
					default -> {
						if (!metaclassPresent) {
							throw new UnsupportedOperationException(LispNames.DEFCLASS + " slot option " + keySym.name()
									+ " is not supported: " + spec.print());
						}
						for (int e = 0; e < extras.size(); e += 2) {
							if (extras.get(e) instanceof LispSymbol prev && prev.name().equals(keySym.name())) {
								throw new UnsupportedOperationException(LispNames.DEFCLASS + " slot option "
										+ keySym.name() + " may appear only once: " + spec.print());
							}
						}
						extras.add(keySym);
						extras.add(optValue);
					}
				}
			}
		}
		else {
			throw new IllegalArgumentException(LispNames.DEFCLASS + " expects a slot name or (name options...), got "
					+ spec.print() + " in " + defclassForm.print());
		}
		PackageRegistry.QualifiedName slotQn = PackageRegistry.splitQualified(slotSym.name());
		String baseName = slotQn == null ? slotSym.name() : slotQn.member();
		return new ParsedSlot(new ClosRegistry.SlotSpec(slotSym.name(), baseName, initform, initformSupplied,
				initarg == null ? ":" + baseName : initarg, initarg != null, List.copyOf(readers),
				List.copyOf(accessors), type), initarg != null, List.copyOf(extras));
	}

	private static String requireSlotFunctionName(LispVal value, LispVal spec) {
		if (!(value instanceof LispSymbol sym) || sym.isKeyword()) {
			throw new IllegalArgumentException(
					LispNames.DEFCLASS + " :reader/:accessor expects a function name: " + spec.print());
		}
		return sym.name();
	}

	/**
	 * Expands {@code (make-instance 'name :initarg value ...)} into a call of the class's
	 * generated keyword constructor. The class name must be a literal quoted symbol
	 * naming a class already defined by {@code defclass} (the static subset has no
	 * runtime class table).
	 * @param cons the make-instance expression
	 * @param closRegistry the class registry
	 * @return the constructor call
	 */
	public static LispVal expandMakeInstance(LispCons cons, ClosRegistry closRegistry) {
		return expandMakeInstance(cons, closRegistry, false);
	}

	/**
	 * As {@link #expandMakeInstance(LispCons, ClosRegistry)}, but {@code coldBranchOk}
	 * degrades an UNKNOWN class from a compile-time error to a runtime {@code error}
	 * call. The compile paths pass true: they compile every branch eagerly, so a library
	 * whose dispatcher names classes from subsystems that were not loaded (ironclad's
	 * {@code make-kdf} listing scrypt/argon2/bcrypt) would otherwise be uncompilable even
	 * though the branch is never taken -- the same eager-cold-branch tolerance
	 * {@code format} already has. The interpreter passes false (it only expands what it
	 * evaluates, so a genuinely wrong class name still reports at that point).
	 * @param cons the make-instance expression
	 * @param closRegistry the class registry
	 * @param coldBranchOk whether an unknown class lowers to a runtime error
	 * @return the constructor call
	 */
	public static LispVal expandMakeInstance(LispCons cons, ClosRegistry closRegistry, boolean coldBranchOk) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException(LispNames.MAKE_INSTANCE + " expects a class name: " + cons.print());
		}
		LispSymbol classSym = quotedSymbol(parts.get(1));
		if (classSym == null) {
			throw new UnsupportedOperationException(
					LispNames.MAKE_INSTANCE + " requires a literal quoted class name: " + cons.print());
		}
		ClosRegistry.ClassInfo info = closRegistry.findClass(classSym.name());
		if (info == null) {
			if (coldBranchOk) {
				return listToCons(List.of(new LispSymbol(LispNames.ERROR),
						new LispString(LispNames.MAKE_INSTANCE + ": unknown class " + classSym.name())));
			}
			throw new IllegalArgumentException(LispNames.MAKE_INSTANCE + ": unknown class " + classSym.name());
		}
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(info.name());
		String ctor = qn == null ? affixFor("%make-", info.name()) + info.name()
				: qn.pkg() + "::" + affixFor("%make-", qn.member()) + qn.member();
		// CL has ONE initialize-instance generic; the registry keys generics by their
		// package-qualified spelling, so match by plain name (a make-instance in any
		// package must find cl-ppcre::initialize-instance). When only shared-initialize
		// methods exist (ironclad's hmac keying :after), make-instance calls that
		// generic directly with the t slot-names argument -- the same effective chain
		// CL's default initialize-instance primary would run.
		ClosRegistry.GenericInfo init = closRegistry.generics()
			.values()
			.stream()
			.filter(g -> "INITIALIZE-INSTANCE".equals(plainName(g.name())))
			.findFirst()
			.orElse(null);
		boolean sharedInit = false;
		if (init == null) {
			init = closRegistry.generics()
				.values()
				.stream()
				.filter(g -> "SHARED-INITIALIZE".equals(plainName(g.name())))
				.findFirst()
				.orElse(null);
			sharedInit = init != null;
		}
		if (init == null) {
			List<LispVal> call = new java.util.ArrayList<>();
			call.add(new LispSymbol(ctor));
			call.addAll(parts.subList(2, parts.size()));
			return listToCons(call);
		}
		// A user initialize-instance method exists (an :after in practice; make-instance
		// runs it on the fresh instance with the initargs, like CL). Each initarg
		// expression is hoisted into a let* temp so the constructor call and the
		// initialize-instance call cannot evaluate it twice.
		String prefix = "__mi" + MV_COUNTER.getAndIncrement();
		List<LispVal> ctorCall = new java.util.ArrayList<>();
		ctorCall.add(new LispSymbol(ctor));
		List<LispVal> initCall = new java.util.ArrayList<>();
		initCall.add(new LispSymbol(init.name()));
		LispSymbol objVar = new LispSymbol(prefix + "_obj");
		initCall.add(objVar);
		if (sharedInit) {
			// (shared-initialize obj t initargs...): t = all slots, CL's make-instance
			// slot-names argument.
			initCall.add(LispTrue.INSTANCE);
		}
		List<LispVal> bindings = new java.util.ArrayList<>();
		for (int i = 2; i < parts.size(); i++) {
			LispSymbol temp = new LispSymbol(prefix + "_a" + (i - 2));
			bindings.add(listToCons(List.of(temp, parts.get(i))));
			ctorCall.add(temp);
			initCall.add(temp);
		}
		bindings.add(listToCons(List.of(objVar, listToCons(ctorCall))));
		List<LispVal> letParts = new java.util.ArrayList<>();
		letParts.add(new LispSymbol(LispNames.LET_STAR));
		letParts.add(listToCons(bindings));
		letParts.add(listToCons(initCall));
		// CL runs the initialization :before methods BEFORE the initargs fill the
		// slots; the constructor above fills first. For a class a :before method
		// specializes, every declared-initarg slot the call supplies is re-set AFTER
		// the initialization generic returns, so a :before writing such a slot
		// (postmodern's dao-class resetting direct-keys) is overwritten exactly like
		// CL's fill would overwrite it -- while undeclared (slot-name-default)
		// initargs and unsupplied slots keep the hook's writes.
		if (closRegistry.needsInitRefill(info)) {
			List<ClosRegistry.SlotSpec> slots = info.slots();
			for (int s = 0; s < slots.size(); s++) {
				ClosRegistry.SlotSpec slot = slots.get(s);
				if (!slot.initargSupplied()) {
					continue;
				}
				// Leftmost initarg wins, per CL's duplicate-initarg rule.
				for (int k = 2; k < parts.size() - 1; k += 2) {
					LispSymbol keyword = literalKeyword(parts.get(k));
					if (keyword != null && keyword.name().equals(slot.initargKeyword())) {
						letParts.add(listToCons(List.of(new LispSymbol(LispNames.OBJ_SET), objVar, new LispInteger(s),
								new LispSymbol(prefix + "_a" + (k - 1)))));
						break;
					}
				}
			}
		}
		letParts.add(objVar);
		return listToCons(letParts);
	}

	/**
	 * The keyword a literal initarg position of a {@code make-instance} call names:
	 * either the bare keyword symbol or its quote-wrapped spelling (the
	 * {@code %mop-make-instance} builtin re-enters the static expansion with every
	 * argument quoted). Null for a computed key, which the re-fill then skips.
	 */
	private static @org.jspecify.annotations.Nullable LispSymbol literalKeyword(LispVal form) {
		if (form instanceof LispSymbol sym && sym.isKeyword()) {
			return sym;
		}
		LispSymbol quoted = quotedSymbol(form);
		return quoted != null && quoted.isKeyword() ? quoted : null;
	}

	/**
	 * Expands {@code (slot-value obj 'slot)} into the slot's {@code nth} position. The
	 * slot name must be a literal quoted symbol whose position is the same in every class
	 * declaring it (guaranteed within one inheritance chain; two unrelated classes
	 * reusing a slot name at different positions make it ambiguous -- use the accessor
	 * instead).
	 * @param cons the slot-value expression
	 * @param closRegistry the class registry
	 * @return the {@code (nth position obj)} expression
	 */
	public static LispVal expandSlotValue(LispCons cons, ClosRegistry closRegistry) {
		List<LispVal> parts = cons.toList();
		LispSymbol slotSym = parts.size() == 3 ? quotedSymbol(parts.get(2)) : null;
		LispVal raw = expandSlotValueRaw(cons, closRegistry);
		if (slotSym == null) {
			// A runtime slot name already dispatches per layout; wrapping the whole
			// dispatch would need the name at expansion time, so those reads keep the raw
			// value (an unbound slot reads as the marker there -- documented in
			// .kb/clos).
			return raw;
		}
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(slotSym.name());
		String baseName = qn == null ? slotSym.name() : qn.member();
		// The read is boundness-checked: the instance expression is hoisted so the
		// unbound-slot signal can name it without evaluating it twice.
		LispSymbol objVar = new LispSymbol("__sv" + MV_COUNTER.getAndIncrement() + "_o");
		LispVal rawOverVar = expandSlotValueRaw((LispCons) listToCons(List.of(parts.get(0), objVar, parts.get(2))),
				closRegistry);
		return makeLet(objVar.name(), parts.get(1), slotReadCall(rawOverVar, objVar, baseName));
	}

	/**
	 * The UNCHECKED half of {@link #expandSlotValue(LispCons, ClosRegistry)}: the plain
	 * slot read, without the unbound-marker test. It is what the {@code setf} place
	 * expansion needs (a write must reach the {@code %obj-ref} place, and writing an
	 * unbound slot is legal) and what the checked read is built on.
	 * @param cons the slot-value expression
	 * @param closRegistry the class registry
	 * @return the {@code (%obj-ref obj position)} expression, or the dispatch standing in
	 * for it
	 */
	public static LispVal expandSlotValueRaw(LispCons cons, ClosRegistry closRegistry) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			throw new IllegalArgumentException(
					LispNames.SLOT_VALUE + " expects (slot-value obj 'slot): " + cons.print());
		}
		LispSymbol slotSym = quotedSymbol(parts.get(2));
		if (slotSym == null) {
			// A runtime slot name (jzon's class-slots-driven serialization): dispatch
			// over every unambiguously positioned slot the registry knows.
			return expandRuntimeSlotValue(parts.get(1), parts.get(2), closRegistry);
		}
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(slotSym.name());
		String baseName = resolveSlotBaseName(qn == null ? slotSym.name() : qn.member(), closRegistry);
		if (baseName == null) {
			throw new IllegalArgumentException(
					LispNames.SLOT_VALUE + ": unknown slot " + (qn == null ? slotSym.name() : qn.member()));
		}
		Integer index = uniqueLayoutSlotIndex(baseName, closRegistry);
		if (index == null) {
			// Types disagree on the position: dispatch on the instance TAG and read the
			// type-correct index -- the read-side twin of expandAmbiguousSlotSet. The old
			// route read through a same-named READER generic instead, which is wrong
			// whenever that generic belongs to an UNRELATED class: with ironclad and
			// cl-postgres both loaded, (slot-value <protocol-error> 'message) dispatched
			// into IRONCLAD::MESSAGE (whose one method specializes an ironclad condition)
			// and died with "No applicable method" while rendering the protocol error's
			// own report.
			return expandAmbiguousSlotRead(parts.get(1), baseName, closRegistry);
		}
		return objRef(parts.get(1), index);
	}

	/**
	 * The spelling under which the registered layouts declare a slot base name, or null
	 * when none does. A Java-side reader asks with the canonical lowercase name
	 * ({@code simple-condition-format-control} -> {@code "format-control"}) while an
	 * upcase-read user class registered it upcased, so both cases are tried.
	 */
	@Nullable private static String resolveSlotBaseName(String baseName, ClosRegistry closRegistry) {
		for (String candidate : List.of(baseName, baseName.toUpperCase(java.util.Locale.ROOT),
				baseName.toLowerCase(java.util.Locale.ROOT))) {
			for (LispLayout layout : closRegistry.layouts().values()) {
				if (layout.slotNames().contains(candidate)) {
					return candidate;
				}
			}
		}
		return null;
	}

	/**
	 * The 0-based index EVERY registered layout declaring the slot places it at, or null
	 * when they disagree (or none declares it). The layouts are the one truth here --
	 * {@code ClosRegistry.slotPosition} knows CLOS classes only, and a {@code with-slots}
	 * over a {@code defstruct} instance has to resolve against the struct layout too.
	 */
	@Nullable private static Integer uniqueLayoutSlotIndex(String baseName, ClosRegistry closRegistry) {
		Integer found = null;
		for (LispLayout layout : closRegistry.layouts().values()) {
			int index = layout.slotIndex(baseName);
			if (index < 0) {
				continue;
			}
			if (found == null) {
				found = index;
			}
			else if (found != index) {
				return null;
			}
		}
		return found;
	}

	/**
	 * Expands {@code (slot-value obj 'AMBIGUOUS)} -- a literal slot name that unrelated
	 * types place at different indexes -- into an instance-TAG dispatch reading the
	 * type-correct index: the read-side twin of {@link #expandAmbiguousSlotSet}. An
	 * instance of a type that does not declare the slot signals at run time.
	 */
	private static LispVal expandAmbiguousSlotRead(LispVal objExpr, String baseName, ClosRegistry closRegistry) {
		String prefix = "__sr" + MV_COUNTER.getAndIncrement();
		LispSymbol v = new LispSymbol(prefix + "_v");
		List<LispVal> clauses = new java.util.ArrayList<>();
		for (LispLayout layout : closRegistry.layouts().values()) {
			int index = layout.slotNames().indexOf(baseName);
			if (index < 0) {
				continue;
			}
			clauses.add(listToCons(List.of(objIs(v, List.of(layout.tag())), objRef(v, index))));
		}
		clauses.add(listToCons(List.of(LispTrue.INSTANCE, listToCons(List.of(new LispSymbol(LispNames.ERROR),
				new LispString(LispNames.SLOT_VALUE + ": no slot " + baseName + " in this instance"))))));
		List<LispVal> condParts = new java.util.ArrayList<>();
		condParts.add(new LispSymbol(LispNames.COND));
		condParts.addAll(clauses);
		return makeLet(v.name(), objExpr, listToCons(condParts));
	}

	/**
	 * Whether the registered layouts place the named slot at different indexes in
	 * unrelated types, so no single index can be baked into a read or a write.
	 */
	private static boolean ambiguousSlotPosition(LispSymbol slotSym, ClosRegistry closRegistry) {
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(slotSym.name());
		String baseName = resolveSlotBaseName(qn == null ? slotSym.name() : qn.member(), closRegistry);
		return baseName != null && uniqueLayoutSlotIndex(baseName, closRegistry) == null;
	}

	/**
	 * Expands {@code (setf (slot-value obj 'AMBIGUOUS) val)} into an instance-TAG
	 * dispatch that writes the type-correct index: the write-side twin of the ambiguous
	 * read dispatch in {@link #expandSlotValue}. An instance of a type that does not
	 * declare the slot signals at run time.
	 */
	private static LispVal expandAmbiguousSlotSet(LispVal objExpr, LispSymbol slotSym, LispVal value,
			ClosRegistry closRegistry) {
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(slotSym.name());
		String baseName = qn == null ? slotSym.name() : qn.member();
		String prefix = "__ss" + MV_COUNTER.getAndIncrement();
		LispSymbol v = new LispSymbol(prefix + "_v");
		LispSymbol nv = new LispSymbol(prefix + "_n");
		List<LispVal> clauses = new java.util.ArrayList<>();
		for (LispLayout layout : closRegistry.layouts().values()) {
			int index = layout.slotNames().indexOf(baseName);
			if (index < 0) {
				continue;
			}
			clauses.add(
					listToCons(List.of(objIs(v, List.of(layout.tag())), makeProgn(List.of(objSet(v, index, nv), nv)))));
		}
		clauses.add(listToCons(List.of(LispTrue.INSTANCE, listToCons(List.of(new LispSymbol(LispNames.ERROR),
				new LispString(LispNames.SLOT_VALUE + ": no slot " + baseName + " in this instance"))))));
		List<LispVal> condParts = new java.util.ArrayList<>();
		condParts.add(new LispSymbol(LispNames.COND));
		condParts.addAll(clauses);
		return makeLet(v.name(), objExpr, makeLet(nv.name(), value, listToCons(condParts)));
	}

	/**
	 * Expands a {@code slot-value} whose slot name is a runtime value into a call of the
	 * shared {@code %slot-value-runtime} defun ({@link #runtimeSlotValueDefuns}). The
	 * dispatch used to be inlined per call site, but its body grows with the whole
	 * registry, and a call site inside a loop grew the ci-spec corpus's loop body past
	 * the JVM's signed 16-bit branch encoding the day the metaclass protocol added five
	 * classes -- the {@code %class-slot-defs} lesson again.
	 */
	private static LispVal expandRuntimeSlotValue(LispVal objExpr, LispVal nameExpr, ClosRegistry closRegistry) {
		return mvCall(LispNames.SLOT_VALUE_RUNTIME, objExpr, nameExpr);
	}

	/**
	 * Wraps runtime-dispatch cond clauses into a public defun, CHAINING overflow into
	 * {@code <helperPrefix><n>} helper defuns by cons-node budget: each chunk's
	 * fall-through arm calls the next helper, and only the last falls back to
	 * {@code fallback}. A dispatch that fits one chunk stays a single defun,
	 * byte-identical to the pre-chunking shape -- a real library's registry (postmodern
	 * loads ~40 classes with hundreds of slots) otherwise grows one cond past the JVM's
	 * signed 16-bit branch encoding.
	 */
	private static List<LispVal> chainedDispatchDefuns(String publicName, String helperPrefix, List<LispSymbol> params,
			List<LispVal> clauses, LispVal fallback) {
		List<List<LispVal>> chunks = new java.util.ArrayList<>();
		List<LispVal> current = new java.util.ArrayList<>();
		int nodes = 0;
		for (LispVal clause : clauses) {
			current.add(clause);
			nodes += consNodeCount(clause);
			if (nodes >= 600) {
				chunks.add(current);
				current = new java.util.ArrayList<>();
				nodes = 0;
			}
		}
		if (!current.isEmpty() || chunks.isEmpty()) {
			chunks.add(current);
		}
		List<LispVal> defuns = new java.util.ArrayList<>();
		for (int i = 0; i < chunks.size(); i++) {
			String name = i == 0 ? publicName : helperPrefix + i;
			LispVal tail = i == chunks.size() - 1 ? fallback
					: mvCall(helperPrefix + (i + 1), params.toArray(LispVal[]::new));
			List<LispVal> condParts = new java.util.ArrayList<>();
			condParts.add(new LispSymbol(LispNames.COND));
			condParts.addAll(chunks.get(i));
			condParts.add(listToCons(List.of(LispTrue.INSTANCE, tail)));
			defuns.add(listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(name),
					listToCons(new java.util.ArrayList<LispVal>(params)), listToCons(condParts))));
		}
		return defuns;
	}

	/**
	 * Builds the shared {@code %slot-value-runtime} defun: a name dispatch over every
	 * slot name any registered layout declares -- structs included, since the layout
	 * registry is the one source of slot shapes. Names sitting at the same index in every
	 * type that declares them share one {@code member} arm (the common case, and the
	 * whole dispatch when no name is ambiguous); a name at differing indexes gets an
	 * inner instance-TAG dispatch instead of a hard error, so an ambiguous runtime name
	 * resolves rather than failing. An unknown name signals at run time. Injected by
	 * {@link #expandTopLevelDefinitions} AFTER the walk (the registry is complete), and
	 * only when the program contains a non-literal-name {@code slot-value}; chained
	 * chunking via {@link #chainedDispatchDefuns}.
	 */
	private static List<LispVal> runtimeSlotValueDefuns(ClosRegistry closRegistry) {
		LispSymbol v = new LispSymbol("%svr_v");
		LispSymbol n = new LispSymbol("%svr_n");
		LispVal signal = listToCons(List.of(new LispSymbol(LispNames.ERROR),
				new LispString(LispNames.SLOT_VALUE + ": unknown runtime slot name")));
		// slot base name -> index -> the tags placing it there, in registration order.
		java.util.Map<String, java.util.Map<Integer, List<String>>> byName = new java.util.LinkedHashMap<>();
		for (LispLayout layout : closRegistry.layouts().values()) {
			for (int i = 0; i < layout.slotCount(); i++) {
				byName.computeIfAbsent(layout.slotNames().get(i), k -> new java.util.LinkedHashMap<>())
					.computeIfAbsent(i, k -> new java.util.ArrayList<>())
					.add(layout.tag());
			}
		}
		java.util.Map<Integer, List<String>> unambiguousByIndex = new java.util.LinkedHashMap<>();
		java.util.Map<String, java.util.Map<Integer, List<String>>> ambiguous = new java.util.LinkedHashMap<>();
		byName.forEach((name, byIndex) -> {
			if (byIndex.size() == 1) {
				unambiguousByIndex.computeIfAbsent(byIndex.keySet().iterator().next(), k -> new java.util.ArrayList<>())
					.add(name);
			}
			else {
				ambiguous.put(name, byIndex);
			}
		});
		List<LispVal> clauses = new java.util.ArrayList<>();
		for (java.util.Map.Entry<Integer, List<String>> entry : unambiguousByIndex.entrySet()) {
			clauses.add(listToCons(List.of(mvCall(LispNames.MEMBER, n, quotedSymbolList(entry.getValue())),
					objRef(v, entry.getKey()))));
		}
		for (java.util.Map.Entry<String, java.util.Map<Integer, List<String>>> entry : ambiguous.entrySet()) {
			List<LispVal> inner = new java.util.ArrayList<>();
			entry.getValue().forEach((index, tags) -> inner.add(listToCons(List.of(objIs(v, tags), objRef(v, index)))));
			inner.add(listToCons(List.of(LispTrue.INSTANCE, signal)));
			List<LispVal> innerCond = new java.util.ArrayList<>();
			innerCond.add(new LispSymbol(LispNames.COND));
			innerCond.addAll(inner);
			clauses.add(listToCons(List.of(mvCall(LispNames.MEMBER, n, quotedSymbolList(List.of(entry.getKey()))),
					listToCons(innerCond))));
		}
		return chainedDispatchDefuns(LispNames.SLOT_VALUE_RUNTIME, "%SVR-", List.of(v, n), clauses, signal);
	}

	/**
	 * Builds the shared {@code %slot-value-set-runtime} defun: the write-side twin of
	 * {@link #runtimeSlotValueDefuns}, same name dispatch, each arm storing through
	 * {@code %obj-set} and answering the stored value. Injected by
	 * {@link #expandTopLevelDefinitions} gated on a runtime-name
	 * {@code (setf (slot-value ...))} so read-only programs stay byte-identical.
	 */
	private static List<LispVal> runtimeSlotValueSetDefuns(ClosRegistry closRegistry) {
		LispSymbol v = new LispSymbol("%svw_v");
		LispSymbol n = new LispSymbol("%svw_n");
		LispSymbol nv = new LispSymbol("%svw_nv");
		LispVal signal = listToCons(List.of(new LispSymbol(LispNames.ERROR),
				new LispString(LispNames.SLOT_VALUE + ": unknown runtime slot name")));
		java.util.Map<String, java.util.Map<Integer, List<String>>> byName = new java.util.LinkedHashMap<>();
		for (LispLayout layout : closRegistry.layouts().values()) {
			for (int i = 0; i < layout.slotCount(); i++) {
				byName.computeIfAbsent(layout.slotNames().get(i), k -> new java.util.LinkedHashMap<>())
					.computeIfAbsent(i, k -> new java.util.ArrayList<>())
					.add(layout.tag());
			}
		}
		java.util.Map<Integer, List<String>> unambiguousByIndex = new java.util.LinkedHashMap<>();
		java.util.Map<String, java.util.Map<Integer, List<String>>> ambiguous = new java.util.LinkedHashMap<>();
		byName.forEach((name, byIndex) -> {
			if (byIndex.size() == 1) {
				unambiguousByIndex.computeIfAbsent(byIndex.keySet().iterator().next(), k -> new java.util.ArrayList<>())
					.add(name);
			}
			else {
				ambiguous.put(name, byIndex);
			}
		});
		List<LispVal> clauses = new java.util.ArrayList<>();
		for (java.util.Map.Entry<Integer, List<String>> entry : unambiguousByIndex.entrySet()) {
			clauses.add(listToCons(List.of(mvCall(LispNames.MEMBER, n, quotedSymbolList(entry.getValue())),
					makeProgn(List.of(objSet(v, entry.getKey(), nv), nv)))));
		}
		for (java.util.Map.Entry<String, java.util.Map<Integer, List<String>>> entry : ambiguous.entrySet()) {
			List<LispVal> inner = new java.util.ArrayList<>();
			entry.getValue()
				.forEach((index, tags) -> inner
					.add(listToCons(List.of(objIs(v, tags), makeProgn(List.of(objSet(v, index, nv), nv))))));
			inner.add(listToCons(List.of(LispTrue.INSTANCE, signal)));
			List<LispVal> innerCond = new java.util.ArrayList<>();
			innerCond.add(new LispSymbol(LispNames.COND));
			innerCond.addAll(inner);
			clauses.add(listToCons(List.of(mvCall(LispNames.MEMBER, n, quotedSymbolList(List.of(entry.getKey()))),
					listToCons(innerCond))));
		}
		return chainedDispatchDefuns(LispNames.SLOT_VALUE_SET_RUNTIME, "%SVW-", List.of(v, n, nv), clauses, signal);
	}

	/**
	 * Expands {@code (class-of x)} into the class-metaobject view:
	 * {@code (%find-class (%class-designator-dispatch) t)} -- the designator (an instance
	 * tag, whose spelling every {@code %class-meta-table%} entry carries, or a built-in
	 * type name the generated resolver's fallback covers) resolves to the same memoized
	 * metaobject {@code find-class} answers, so {@code (eq (class-of x)
	 * (find-class name))} holds. The {@code class-of}/{@code find-class} reference makes
	 * {@link #expandTopLevelDefinitions} inject the metaobject runtime.
	 * @param cons the class-of expression
	 * @param hashTablesExist see {@link #expandClassDesignator(LispCons, boolean)}
	 * @return the expanded expression
	 */
	public static LispVal expandClassOf(LispCons cons, boolean hashTablesExist) {
		return mvCall(LispNames.FIND_CLASS_INTERNAL, expandClassDesignator(cons, hashTablesExist), LispTrue.INSTANCE);
	}

	/**
	 * Expands {@code (%class-designator x)} into a runtime type dispatch mirroring the
	 * interpreter's semantics (what {@code class-of} was before the metaobject
	 * migration): the instance-tag symbol of a struct/CLOS instance (read straight off
	 * the value, so no tag enumeration has to be kept in step with the registry), else a
	 * built-in type NAME symbol ({@code integer}, {@code string}, ...), with {@code t}
	 * for anything else (arrays included).
	 * @param cons the %class-designator (or class-of) expression
	 * @return the expanded expression
	 */
	public static LispVal expandClassDesignator(LispCons cons) {
		return expandClassDesignator(cons, true);
	}

	/**
	 * Like {@link #expandClassDesignator(LispCons)}, but lets a backend drop the
	 * {@code hash-table-p} clause when no hash table can exist in the program at all.
	 * <p>
	 * The JVM emits its hash-table runtime only for a program that uses a hash-table
	 * operator, so in every other program the clause is a call to a {@code _hashP} that
	 * was never generated -- a dangling reference that survives verification and would
	 * throw {@code NoSuchMethodError} if it could ever be reached (it cannot: with no
	 * runtime to build one, no hash table exists). Dropping it is the same reasoning that
	 * keeps the character-vector arm out of a compiled {@code stringp} when the array
	 * runtime is absent. The interpreter and both WASM backends always pass {@code true}
	 * -- their hash primitives are unconditional.
	 * @param cons the %class-designator (or class-of) expression
	 * @param hashTablesExist whether a hash table can exist in this program
	 * @return the expanded expression
	 */
	public static LispVal expandClassDesignator(LispCons cons, boolean hashTablesExist) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException(
					LispNames.CLASS_DESIGNATOR_INTERNAL + " expects exactly one argument: " + cons.print());
		}
		String prefix = "__co" + MV_COUNTER.getAndIncrement();
		LispSymbol v = new LispSymbol(prefix + "_v");
		List<LispVal> clauses = new java.util.ArrayList<>();
		clauses.add(listToCons(List.of(listToCons(List.of(new LispSymbol(LispNames.OBJ_P), v)), objTag(v))));
		clauses.add(listToCons(List.of(mvCall(LispNames.NULL, v), quoteOf("NULL"))));
		clauses.add(listToCons(List.of(fmtCall(LispNames.EQ_GENERAL, v, LispTrue.INSTANCE), quoteOf("BOOLEAN"))));
		clauses.add(listToCons(List.of(mvCall(LispNames.INTEGERP, v), quoteOf("INTEGER"))));
		clauses.add(listToCons(List.of(mvCall(LispNames.RATIONALP, v), quoteOf("RATIO"))));
		clauses.add(listToCons(List.of(mvCall(LispNames.FLOATP, v), quoteOf("FLOAT"))));
		clauses.add(listToCons(List.of(mvCall(LispNames.STRINGP, v), quoteOf("STRING"))));
		clauses.add(listToCons(List.of(mvCall(LispNames.CHARACTERP, v), quoteOf("CHARACTER"))));
		clauses.add(listToCons(List.of(mvCall(LispNames.KEYWORDP, v), quoteOf("KEYWORD"))));
		clauses.add(listToCons(List.of(mvCall(LispNames.SYMBOLP, v), quoteOf("SYMBOL"))));
		if (hashTablesExist) {
			clauses.add(listToCons(List.of(mvCall(LispNames.HASH_TABLE_P, v), quoteOf("HASH-TABLE"))));
		}
		clauses.add(listToCons(List.of(mvCall(LispNames.FUNCTIONP, v), quoteOf("FUNCTION"))));
		clauses.add(listToCons(List.of(mvCall(LispNames.CONSP, v), quoteOf("CONS"))));
		clauses.add(listToCons(List.of(LispTrue.INSTANCE, quoteOf("T"))));
		List<LispVal> condParts = new java.util.ArrayList<>();
		condParts.add(new LispSymbol(LispNames.COND));
		condParts.addAll(clauses);
		return nestMvBindings(List.of(new MvBinding(v, parts.get(1))), listToCons(condParts));
	}

	/**
	 * Expands {@code (slot-boundp obj 'slot)} (literal slot name) into "the instance's
	 * type declares the slot AND the slot does not hold the unbound marker" -- the real
	 * CL semantics since todo-199 (a slot written without an {@code :initform}, or
	 * emptied by {@code slot-makunbound}, answers nil).
	 * @param cons the slot-boundp expression
	 * @param closRegistry the class registry
	 * @return the expanded expression
	 */
	public static LispVal expandSlotBoundp(LispCons cons, ClosRegistry closRegistry) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			throw new IllegalArgumentException(
					LispNames.SLOT_BOUNDP + " expects (slot-boundp obj 'slot): " + cons.print());
		}
		LispSymbol slotSym = quotedSymbol(parts.get(2));
		if (slotSym == null) {
			// A runtime slot name: a class-tag dispatch over a per-class slot-name
			// membership test, each arm reading that type's index to test the marker.
			return expandRuntimeSlotBoundp(parts.get(1), parts.get(2), closRegistry);
		}
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(slotSym.name());
		String asked = qn == null ? slotSym.name() : qn.member();
		String baseName = resolveSlotBaseName(asked, closRegistry);
		if (baseName == null) {
			return expandConstantResult((LispCons) fmtCall(LispNames.SLOT_BOUNDP, parts.get(1)), LispNil.INSTANCE);
		}
		// One clause per distinct index, so a slot every type places at the same position
		// (the common case) costs a single tag membership test.
		java.util.Map<Integer, List<String>> byIndex = new java.util.LinkedHashMap<>();
		for (LispLayout layout : closRegistry.layouts().values()) {
			int index = layout.slotIndex(baseName);
			if (index >= 0) {
				byIndex.computeIfAbsent(index, k -> new java.util.ArrayList<>()).add(layout.tag());
			}
		}
		String prefix = "__sb" + MV_COUNTER.getAndIncrement();
		LispSymbol v = new LispSymbol(prefix + "_v");
		List<LispVal> clauses = new java.util.ArrayList<>();
		byIndex.forEach(
				(index, tags) -> clauses.add(listToCons(List.of(objIs(v, tags), boundValueTest(objRef(v, index))))));
		clauses.add(listToCons(List.of(LispTrue.INSTANCE, LispNil.INSTANCE)));
		List<LispVal> condParts = new java.util.ArrayList<>();
		condParts.add(new LispSymbol(LispNames.COND));
		condParts.addAll(clauses);
		return makeLet(v.name(), parts.get(1), listToCons(condParts));
	}

	/**
	 * Expands a {@code slot-boundp} whose slot name is a runtime value into a call of the
	 * shared {@code %slot-boundp-runtime} defun -- outlined for the same reason as
	 * {@link #expandRuntimeSlotValue}.
	 */
	private static LispVal expandRuntimeSlotBoundp(LispVal objExpr, LispVal nameExpr, ClosRegistry closRegistry) {
		return mvCall(LispNames.SLOT_BOUNDP_RUNTIME, objExpr, nameExpr);
	}

	/**
	 * Builds the shared {@code %slot-boundp-runtime} defun: a class-tag dispatch over the
	 * registered layouts, each arm testing the runtime name against that type's declared
	 * slot names and, when it matches, the slot against the unbound marker. Injected
	 * beside {@link #runtimeSlotValueDefuns}, same gate, same chained chunking.
	 */
	private static List<LispVal> runtimeSlotBoundpDefuns(ClosRegistry closRegistry) {
		LispSymbol v = new LispSymbol("%sbr_v");
		LispSymbol n = new LispSymbol("%sbr_n");
		List<LispVal> clauses = new java.util.ArrayList<>();
		for (LispLayout layout : closRegistry.layouts().values()) {
			if (layout.slotCount() == 0) {
				continue;
			}
			List<LispVal> inner = new java.util.ArrayList<>();
			for (int i = 0; i < layout.slotCount(); i++) {
				inner.add(listToCons(
						List.of(mvCall(LispNames.MEMBER, n, quotedSymbolList(List.of(layout.slotNames().get(i)))),
								boundValueTest(objRef(v, i)))));
			}
			inner.add(listToCons(List.of(LispTrue.INSTANCE, LispNil.INSTANCE)));
			List<LispVal> innerCond = new java.util.ArrayList<>();
			innerCond.add(new LispSymbol(LispNames.COND));
			innerCond.addAll(inner);
			clauses.add(listToCons(List.of(objIs(v, List.of(layout.tag())), listToCons(innerCond))));
		}
		return chainedDispatchDefuns(LispNames.SLOT_BOUNDP_RUNTIME, "%SBR-", List.of(v, n), clauses, LispNil.INSTANCE);
	}

	/**
	 * Whether the program contains a {@code slot-value} or {@code slot-boundp} whose
	 * slot-name argument is not a literal quoted symbol -- the condition under which
	 * {@link #expandTopLevelDefinitions} injects the shared runtime-slot-name dispatch
	 * defuns (the call sites lower to them during the backend passes). Quoted data is
	 * skipped.
	 */
	private static boolean needsRuntimeSlotNameDispatch(List<LispVal> program) {
		return program.stream().anyMatch(LispMacroExpander::containsRuntimeSlotName);
	}

	/**
	 * Whether the program writes through a runtime slot name -- a {@code (setf
	 * (slot-value obj name-expr) ...)} whose name is not a literal quote -- the gate for
	 * the generated {@code %slot-value-set-runtime} defun. Only a direct single-pair
	 * {@code setf} is recognized; an exotic spelling that reaches the same expansion
	 * without the defun fails loudly at compile time rather than silently.
	 */
	private static boolean needsRuntimeSlotSetDispatch(List<LispVal> program) {
		return program.stream().anyMatch(LispMacroExpander::containsRuntimeSlotSet);
	}

	private static boolean containsRuntimeSlotSet(LispVal form) {
		if (!(form instanceof LispCons cons)) {
			return false;
		}
		if (cons.car() instanceof LispSymbol op) {
			String member = memberOf(op.name());
			if (LispNames.QUOTE.equals(member)) {
				return false;
			}
			if (LispNames.SETF.equals(member) && cons.cdr() instanceof LispCons rest
					&& rest.car() instanceof LispCons place && place.car() instanceof LispSymbol placeOp
					&& LispNames.SLOT_VALUE.equals(memberOf(placeOp.name())) && place.isProperList()) {
				List<LispVal> parts = place.toList();
				if (parts.size() == 3 && quotedSymbol(parts.get(2)) == null) {
					return true;
				}
			}
		}
		return containsRuntimeSlotSet(cons.car()) || containsRuntimeSlotSet(cons.cdr());
	}

	private static boolean containsRuntimeSlotName(LispVal form) {
		if (!(form instanceof LispCons cons)) {
			return false;
		}
		if (cons.car() instanceof LispSymbol op) {
			String member = memberOf(op.name());
			if (LispNames.QUOTE.equals(member)) {
				return false;
			}
			if ((LispNames.SLOT_VALUE.equals(member) || LispNames.SLOT_BOUNDP.equals(member)) && cons.isProperList()) {
				List<LispVal> parts = cons.toList();
				if (parts.size() == 3 && quotedSymbol(parts.get(2)) == null) {
					return true;
				}
			}
		}
		return containsRuntimeSlotName(cons.car()) || containsRuntimeSlotName(cons.cdr());
	}

	/**
	 * Expands {@code (slot-makunbound obj 'slot)} into a store of a fresh unbound marker
	 * through the slot's {@code setf slot-value} place, yielding the instance: the slot
	 * then reads as {@code unbound-slot} and {@code slot-boundp} answers nil.
	 * @param cons the slot-makunbound expression
	 * @param closRegistry the class registry
	 * @return the expanded expression
	 */
	public static LispVal expandSlotMakunbound(LispCons cons, ClosRegistry closRegistry) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			throw new IllegalArgumentException(
					LispNames.SLOT_MAKUNBOUND + " expects (slot-makunbound obj 'slot): " + cons.print());
		}
		String prefix = "__sm" + MV_COUNTER.getAndIncrement();
		LispSymbol v = new LispSymbol(prefix + "_v");
		LispVal write = fmtCall(LispNames.SETF, fmtCall(LispNames.SLOT_VALUE, v, parts.get(2)), unboundMarker());
		LispVal body = listToCons(List.of(new LispSymbol(LispNames.PROGN), write, v));
		return nestMvBindings(List.of(new MvBinding(v, parts.get(1))), body);
	}

	/**
	 * Expands {@code (simple-condition-format-control c)} into a class-tag dispatch over
	 * the condition instance: the built-in simple-* tags carry the rendered message at
	 * slot 1, user condition classes read their declared {@code format-control} slot, and
	 * anything else yields nil -- the interpreter's {@code conditionSlotValue} semantics.
	 * @param cons the simple-condition-format-control expression
	 * @param closRegistry the class registry
	 * @return the expanded expression
	 */
	public static LispVal expandSimpleConditionFormatControl(LispCons cons, ClosRegistry closRegistry) {
		return expandConditionSlotReader(cons, closRegistry, "FORMAT-CONTROL", true);
	}

	/**
	 * Expands {@code (simple-condition-format-arguments c)} like
	 * {@link #expandSimpleConditionFormatControl(LispCons, ClosRegistry)} over the
	 * {@code format-arguments} slot; the built-in simple-* tags carry no argument list,
	 * so they yield nil.
	 * @param cons the simple-condition-format-arguments expression
	 * @param closRegistry the class registry
	 * @return the expanded expression
	 */
	public static LispVal expandSimpleConditionFormatArguments(LispCons cons, ClosRegistry closRegistry) {
		return expandConditionSlotReader(cons, closRegistry, "FORMAT-ARGUMENTS", false);
	}

	private static LispVal expandConditionSlotReader(LispCons cons, ClosRegistry closRegistry, String baseName,
			boolean simpleTagsCarrySlot1) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException(
					((LispSymbol) cons.car()).name() + " expects exactly one argument: " + cons.print());
		}
		String prefix = "__cs" + MV_COUNTER.getAndIncrement();
		LispSymbol v = new LispSymbol(prefix + "_v");
		List<LispVal> clauses = new java.util.ArrayList<>();
		if (simpleTagsCarrySlot1) {
			clauses.add(listToCons(List.of(objIs(v, SIMPLE_CONDITION_TAGS), objRef(v, 0))));
		}
		// Group the classes declaring the slot by its instance position so one membership
		// test covers each layout.
		java.util.Map<Integer, List<String>> byPosition = new java.util.LinkedHashMap<>();
		for (ClosRegistry.ClassInfo info : closRegistry.classes().values()) {
			for (int i = 0; i < info.slots().size(); i++) {
				// Case-insensitive: the canonical Java-side name is lowercase while an
				// upcase-read user condition's slots register upcased.
				if (info.slots().get(i).baseName().equalsIgnoreCase(baseName)) {
					byPosition.computeIfAbsent(i + 1, k -> new java.util.ArrayList<>()).add("%class-" + info.name());
					break;
				}
			}
		}
		for (java.util.Map.Entry<Integer, List<String>> entry : byPosition.entrySet()) {
			clauses.add(listToCons(List.of(objIs(v, entry.getValue()), objRef(v, entry.getKey() - 1))));
		}
		clauses.add(listToCons(List.of(LispTrue.INSTANCE, LispNil.INSTANCE)));
		List<LispVal> condParts = new java.util.ArrayList<>();
		condParts.add(new LispSymbol(LispNames.COND));
		condParts.addAll(clauses);
		return nestMvBindings(List.of(new MvBinding(v, parts.get(1))), listToCons(condParts));
	}

	/**
	 * Expands {@code (%class-slot-defs designator)} into a call of the shared
	 * {@code %class-slot-defs-runtime} dispatch defun, which
	 * {@link #expandTopLevelDefinitions} injects together with its data table -- the
	 * interpreter's semantics: the designator is an instance-tag symbol
	 * ({@code %class-NAME}/{@code %struct-NAME}, what {@code class-of} yields for an
	 * instance) or the plain type name, and anything else (built-in type names included)
	 * yields nil. It used to inline the membership dispatch per call site; that shape
	 * grows with the registry and put the ci-spec corpus's biggest top-level form past
	 * the JVM's 65535-byte method ceiling when the MOP base classes joined the registry.
	 * @param cons the %class-slot-defs expression
	 * @param closRegistry the class registry
	 * @return the expanded expression
	 */
	public static LispVal expandClassSlotDefs(LispCons cons, ClosRegistry closRegistry) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException(
					LispNames.CLASS_SLOT_DEFS_INTERNAL + " expects exactly one argument: " + cons.print());
		}
		return mvCall(LispNames.CLASS_SLOT_DEFS_RUNTIME, parts.get(1));
	}

	/**
	 * Builds the {@code %class-slot-defs-table%} data-table forms backing the shared
	 * runtime {@code %class-slot-defs} defun: one entry per registered class/struct
	 * layout -- the designator spellings (instance tag + print name) as the head,
	 * followed by the {@code (name type)} pairs, so the defun answers {@code (cdr
	 * entry)} directly.
	 */
	private static List<LispVal> classSlotDefsTableForms(ClosRegistry closRegistry) {
		List<LispVal> entries = new java.util.ArrayList<>();
		for (LispLayout layout : closRegistry.layouts().values()) {
			List<ClosRegistry.SlotDef> defs = closRegistry.slotDefs(layout.tag());
			if (defs == null) {
				continue;
			}
			List<LispVal> entryParts = new java.util.ArrayList<>();
			entryParts.add(listToCons(List.of(new LispSymbol(layout.tag()), new LispSymbol(layout.printName()))));
			for (ClosRegistry.SlotDef def : defs) {
				entryParts.add(listToCons(List.of(new LispSymbol(def.name()), new LispSymbol(def.type()))));
			}
			entries.add(listToCons(entryParts));
		}
		return nodeBudgetedTableForms(LispNames.CLASS_SLOT_DEFS_TABLE, entries, 600);
	}

	/**
	 * Builds the shared {@code (defun %class-slot-defs-runtime (v) ...)} dispatch defun:
	 * scans the {@code %class-slot-defs-table%} designator spellings and answers the
	 * entry's pair list, nil for anything unregistered. A class METAOBJECT (what
	 * {@code class-of} answers since the metaobject migration) designates through its
	 * name slot -- the preamble replaces it with that name when {@code standard-class} is
	 * registered (with no MOP surface in the program no metaobject can exist, and the
	 * preamble is dropped).
	 */
	private static LispVal classSlotDefsRuntimeDefun(ClosRegistry closRegistry) {
		LispSymbol v = new LispSymbol("%csd_v");
		LispSymbol hit = new LispSymbol("%csd_hit");
		LispSymbol scan = new LispSymbol("%csd_x");
		LispVal tableScan = listToCons(List.of(new LispSymbol(LispNames.DOLIST),
				listToCons(List.of(scan, new LispSymbol(LispNames.CLASS_SLOT_DEFS_TABLE), LispNil.INSTANCE)),
				makeIf(mvCall(LispNames.MEMBER, v, mvCall(LispNames.CAR, scan)),
						listToCons(List.of(new LispSymbol(LispNames.PROGN),
								listToCons(List.of(new LispSymbol(LispNames.SETQ), hit, scan)),
								listToCons(List.of(new LispSymbol(LispNames.RETURN), LispNil.INSTANCE)))),
						LispNil.INSTANCE)));
		List<LispVal> bodyParts = new java.util.ArrayList<>();
		bodyParts.add(new LispSymbol(LispNames.LET));
		bodyParts.add(listToCons(List.of(listToCons(List.of(hit, LispNil.INSTANCE)))));
		List<String> metaobjectTags = closRegistry.descendantTags(ClosRegistry.STANDARD_CLASS_NAME);
		if (!metaobjectTags.isEmpty()) {
			bodyParts.add(makeIf(objIs(v, List.copyOf(metaobjectTags)),
					listToCons(List.of(new LispSymbol(LispNames.SETQ), v, objRef(v, 0))), LispNil.INSTANCE));
		}
		bodyParts.add(tableScan);
		bodyParts.add(makeIf(hit, mvCall(LispNames.CDR, hit), LispNil.INSTANCE));
		return listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.CLASS_SLOT_DEFS_RUNTIME),
				listToCons(List.of(v)), listToCons(bodyParts)));
	}

	/**
	 * Whether the program calls {@code %class-slot-defs} -- the condition under which
	 * {@link #expandTopLevelDefinitions} injects the shared runtime defun and its data
	 * table (the call sites lower to it via {@link #expandClassSlotDefs} during the
	 * backend passes). Quoted data is skipped.
	 */
	private static boolean needsClassSlotDefsRuntime(List<LispVal> program) {
		return program.stream().anyMatch(LispMacroExpander::referencesClassSlotDefs);
	}

	private static boolean referencesClassSlotDefs(LispVal form) {
		if (!(form instanceof LispCons cons)) {
			return false;
		}
		if (cons.car() instanceof LispSymbol op) {
			String member = memberOf(op.name());
			if (LispNames.QUOTE.equals(member)) {
				return false;
			}
			if (LispNames.CLASS_SLOT_DEFS_INTERNAL.equals(member)) {
				return true;
			}
		}
		return referencesClassSlotDefs(cons.car()) || referencesClassSlotDefs(cons.cdr());
	}

	// --- the instance seam -----------------------------------------------------------
	//
	// Every struct/class/condition instance is built, read, written and type-tested
	// through the %obj-* primitives and NOTHING else. Keeping the expansions behind
	// these five builders is what let the value model move from a tagged list to a real
	// object without touching any expansion logic, and is what keeps the three backends'
	// slot storage from drifting apart -- do not open-code a %obj-* call elsewhere.

	/** Builds {@code (%obj-new '<tag> value...)}. */
	private static LispVal objNew(String tag, List<LispVal> values) {
		List<LispVal> parts = new java.util.ArrayList<>();
		parts.add(new LispSymbol(LispNames.OBJ_NEW));
		parts.add(quoteOf(tag));
		parts.addAll(values);
		return listToCons(parts);
	}

	/** Builds {@code (%obj-ref obj <index>)} over a 0-based slot index. */
	private static LispVal objRef(LispVal obj, int index) {
		return listToCons(List.of(new LispSymbol(LispNames.OBJ_REF), obj, new LispInteger(index)));
	}

	/** Builds {@code (%obj-set obj <index> value)} over a 0-based slot index. */
	private static LispVal objSet(LispVal obj, int index, LispVal value) {
		return listToCons(List.of(new LispSymbol(LispNames.OBJ_SET), obj, new LispInteger(index), value));
	}

	/**
	 * Builds {@code (%obj-is obj '<tag>...)} -- t when the value is an instance of any of
	 * the tags, nil for every other value (a cons included). An empty tag list is the
	 * constant nil, with the object still evaluated for effect.
	 */
	private static LispVal objIs(LispVal obj, List<String> tags) {
		List<LispVal> parts = new java.util.ArrayList<>();
		parts.add(new LispSymbol(LispNames.OBJ_IS));
		parts.add(obj);
		for (String tag : tags) {
			parts.add(quoteOf(tag));
		}
		return listToCons(parts);
	}

	/** Builds {@code (%obj-become obj '<tag>)} -- the in-place layout swap. */
	private static LispVal objBecome(LispVal obj, String tag) {
		return listToCons(List.of(new LispSymbol(LispNames.OBJ_BECOME), obj, quoteOf(tag)));
	}

	/**
	 * Expands {@code (change-class instance 'name initarg value ...)} into an IN-PLACE
	 * class change: the instance keeps its identity and every slot the old and the new
	 * layout share (single inheritance makes the shared part a prefix), the slots the new
	 * class adds are filled from their {@code :initform}s, the supplied initargs are
	 * stored, and the instance is the value.
	 *
	 * <p>
	 * The source class is a RUNTIME property, so the initform fill is a {@code cond} over
	 * the statically-known classes of the target's inheritance chain -- exactly the set
	 * whose instances a change to this class is defined for. An instance of any other
	 * class keeps its slot values and only changes layout, which is what CL's "slots with
	 * the same name are retained" degrades to when the two classes share no chain.
	 * @param cons the change-class expression
	 * @param closRegistry the class registry
	 * @param coldBranchOk whether an unknown target lowers to a runtime error instead of
	 * failing the compile (the compile paths pass true, like {@code make-instance})
	 * @return the expanded expression
	 */
	public static LispVal expandChangeClass(LispCons cons, ClosRegistry closRegistry, boolean coldBranchOk) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3) {
			throw new IllegalArgumentException(LispNames.CHANGE_CLASS
					+ " expects (change-class instance 'class initarg value ...): " + cons.print());
		}
		LispSymbol classSym = quotedSymbol(parts.get(2));
		if (classSym == null) {
			throw new UnsupportedOperationException(
					LispNames.CHANGE_CLASS + " requires a literal quoted class name: " + cons.print());
		}
		ClosRegistry.ClassInfo target = closRegistry.findClass(classSym.name());
		if (target == null) {
			if (coldBranchOk) {
				return listToCons(List.of(new LispSymbol(LispNames.ERROR),
						new LispString(LispNames.CHANGE_CLASS + ": unknown class " + classSym.name())));
			}
			throw new IllegalArgumentException(LispNames.CHANGE_CLASS + ": unknown class " + classSym.name());
		}
		String prefix = "__cc" + MV_COUNTER.getAndIncrement();
		LispSymbol objVar = new LispSymbol(prefix + "_o");
		List<LispVal> bindings = new java.util.ArrayList<>();
		bindings.add(listToCons(List.of(objVar, parts.get(1))));
		// Initarg values are hoisted into temps in argument order, so they evaluate once
		// and BEFORE the layout swap, like every other initarg-taking expansion.
		java.util.Map<String, LispVal> byInitarg = new java.util.LinkedHashMap<>();
		for (int i = 3; i + 1 < parts.size(); i += 2) {
			if (!(parts.get(i) instanceof LispSymbol key) || !key.isKeyword()) {
				throw new IllegalArgumentException(
						LispNames.CHANGE_CLASS + " expects keyword/value initarg pairs: " + cons.print());
			}
			LispSymbol temp = new LispSymbol(prefix + "_a" + i);
			bindings.add(listToCons(List.of(temp, parts.get(i + 1))));
			byInitarg.put(key.name(), temp);
		}
		// The old tag is captured BEFORE the swap: the initform fill has to know which
		// class the instance WAS, but it can only store into the WIDER layout, i.e. after
		// the swap. (A symbol compares with equal, which is content-safe on WASM.)
		LispSymbol tagVar = new LispSymbol(prefix + "_t");
		bindings.add(1, listToCons(List.of(tagVar, objTag(objVar))));
		List<LispVal> body = new java.util.ArrayList<>();
		body.add(objBecome(objVar, LispLayout.CLASS_TAG_PREFIX + target.name()));
		LispVal fill = changeClassInitformFill(objVar, tagVar, target, closRegistry);
		if (fill != null) {
			body.add(fill);
		}
		List<ClosRegistry.SlotSpec> slots = target.slots();
		for (int i = 0; i < slots.size(); i++) {
			LispVal supplied = byInitarg.get(slots.get(i).initargKeyword());
			if (supplied != null) {
				body.add(objSet(objVar, i, supplied));
			}
		}
		body.add(objVar);
		List<LispVal> letParts = new java.util.ArrayList<>();
		letParts.add(new LispSymbol(LispNames.LET_STAR));
		letParts.add(listToCons(bindings));
		letParts.addAll(body);
		return listToCons(letParts);
	}

	/**
	 * The {@code cond} filling the slots the target class adds beyond the instance's
	 * CURRENT class, from the target's initforms -- one arm per class of the target's
	 * inheritance chain that is narrower than it. Null when no class in the chain is
	 * narrower (nothing to fill).
	 */
	@Nullable private static LispVal changeClassInitformFill(LispSymbol objVar, LispSymbol oldTagVar,
			ClosRegistry.ClassInfo target, ClosRegistry closRegistry) {
		String targetKey = ClosRegistry.normalize(target.name());
		List<LispVal> clauses = new java.util.ArrayList<>();
		for (ClosRegistry.ClassInfo source : closRegistry.classes().values()) {
			boolean sameChain = source.ancestors().contains(targetKey)
					|| target.ancestors().contains(ClosRegistry.normalize(source.name()));
			if (!sameChain || source.slots().size() >= target.slots().size()) {
				continue;
			}
			// Multiple inheritance can relate two classes whose layouts do NOT share a
			// prefix (the source's slots sit at shifted indexes in the target). The
			// positional fill below would write the wrong slots there, so such a source
			// degrades to the layout-swap-only behavior unrelated classes get ("slots
			// with the same name are retained" cannot hold positionally).
			boolean prefix = true;
			for (int i = 0; i < source.slots().size(); i++) {
				if (!source.slots().get(i).baseName().equals(target.slots().get(i).baseName())) {
					prefix = false;
					break;
				}
			}
			if (!prefix) {
				continue;
			}
			List<LispVal> stores = new java.util.ArrayList<>();
			for (int i = source.slots().size(); i < target.slots().size(); i++) {
				stores.add(objSet(objVar, i, target.slots().get(i).initform()));
			}
			clauses.add(listToCons(concatForms(
					List.of(fmtCall(LispNames.EQUAL, oldTagVar, quoteOf(LispLayout.CLASS_TAG_PREFIX + source.name()))),
					stores)));
		}
		if (clauses.isEmpty()) {
			return null;
		}
		List<LispVal> condParts = new java.util.ArrayList<>();
		condParts.add(new LispSymbol(LispNames.COND));
		condParts.addAll(clauses);
		return listToCons(condParts);
	}

	/**
	 * Builds {@code (%obj-tag obj)} -- the instance tag symbol, nil for a non-instance.
	 */
	private static LispVal objTag(LispVal obj) {
		return listToCons(List.of(new LispSymbol(LispNames.OBJ_TAG), obj));
	}

	/**
	 * Whether compiling this program can ever CONSTRUCT an instance -- the backends' gate
	 * for emitting the instance representation at all (the WASM struct type and the baked
	 * layout blob, the JVM predicates' instance exclusion). It answers "can an instance
	 * value exist in this module", so the reading primitives ({@code %obj-ref},
	 * {@code %obj-is}, {@code %obj-tag}, {@code %obj-p}) need no gate of their own: with
	 * the gate off they are provably nil.
	 *
	 * <p>
	 * A struct/class constructor is already spliced into the program as an
	 * {@code %obj-new} call by {@link #expandTopLevelDefinitions}, so most of the answer
	 * is a plain scan. The rest are the condition sites that only expand during body
	 * compilation, long after the gate must be fixed: {@code handler-case}/
	 * {@code ignore-errors} synthesize a {@code simple-error}, {@code signal} always
	 * builds a {@code simple-condition}, and {@code error}/{@code warn}/{@code cerror}
	 * build a typed instance for a quoted type, a literal {@code (make-condition ...)}
	 * datum, or (for {@code error}) a runtime datum carrying initargs -- the same case
	 * split {@code expandSignalDesignator} makes, and it must stay in step with it. The
	 * scan is deliberately conservative: over-approximating costs one unused type entry,
	 * under-approximating is a compile failure.
	 *
	 * <p>
	 * A folded {@code #S(...)} literal is an instance sitting in the AST, which the scan
	 * answers for directly -- it does not depend on the constructor defun the same
	 * {@code defstruct} spliced in still being there.
	 * @param program the top-level forms, AFTER {@link #expandTopLevelDefinitions}
	 * @param closRegistry the class registry (its condition {@code :report} forms are
	 * compiled too, but live outside the program)
	 * @return whether an instance can be constructed
	 */
	public static boolean mayCreateInstances(List<LispVal> program, ClosRegistry closRegistry) {
		for (LispVal form : program) {
			if (mayCreateInstance(form)) {
				return true;
			}
		}
		for (LispVal report : closRegistry.conditionReports().values()) {
			if (mayCreateInstance(report)) {
				return true;
			}
		}
		return false;
	}

	private static boolean mayCreateInstance(LispVal form) {
		if (form instanceof LispInstance) {
			return true;
		}
		if (form instanceof LispArray array) {
			// A folded #S(...) literal may sit inside a #(...) vector literal, which is
			// the one container the cons walk below cannot see through.
			for (LispVal element : array.data()) {
				if (mayCreateInstance(element)) {
					return true;
				}
			}
			return false;
		}
		if (!(form instanceof LispCons cons)) {
			return false;
		}
		if (cons.car() instanceof LispSymbol head && constructsInstance(head.name(), cons)) {
			return true;
		}
		return mayCreateInstance(cons.car()) || mayCreateInstance(cons.cdr());
	}

	/** The per-operator half of {@link #mayCreateInstances}. */
	private static boolean constructsInstance(String head, LispCons form) {
		switch (head) {
			case LispNames.OBJ_NEW, LispNames.HANDLER_CASE, LispNames.IGNORE_ERRORS, LispNames.SIGNAL,
					LispNames.MAKE_CONDITION:
				return true;
			case LispNames.READ_CHAR, LispNames.READ_BYTE, LispNames.PEEK_CHAR_INTERNAL:
				// A read whose end of file SIGNALS builds the end-of-file condition
				// instance (expandReadEofSignal).
				return expandReadEofSignal(form, true) != null;
			case LispNames.READ_LINE:
				return expandReadEofSignal(form, false) != null;
			case "RONTOLISP::" + LispNames.READ_CHAR_RAW_INTERNAL, "RONTOLISP::" + LispNames.READ_BYTE_RAW_INTERNAL:
				// Same, under the internal alias sockets.lisp's %io-* dispatchers fall
				// back through on the --component path.
				return expandReadEofSignal(form, true) != null;
			case "RONTOLISP::" + LispNames.READ_LINE_RAW_INTERNAL:
				return expandReadEofSignal(form, false) != null;
			case LispNames.PEEK_CHAR: {
				// Same, one argument later: peek-char's peek-type comes first, and the
				// scan runs on the source program, before expandPeekChar rewrites it.
				List<LispVal> peekParts = form.toList();
				return peekParts.size() <= 3 || !isLiteralNil(peekParts.get(3));
			}
			case LispNames.FUNCTION:
				// #'signal: the generated first-class wrapper re-enters the designator
				// expansion, whose every signal arm builds a simple-condition.
				// #'read-char / #'peek-char / #'read-byte: their wrappers signal
				// end-of-file, and (being REFERENCE_GATED_FUNCTIONS) are injected only
				// because of this very reference.
				return form.cdr() instanceof LispCons rest && rest.car() instanceof LispSymbol fn
						&& (LispNames.SIGNAL.equals(fn.name()) || LispNames.READ_CHAR.equals(fn.name())
								|| LispNames.PEEK_CHAR.equals(fn.name()) || LispNames.READ_BYTE.equals(fn.name()));
			case LispNames.ERROR, LispNames.WARN, LispNames.CERROR: {
				List<LispVal> parts = form.toList();
				// (cerror continue-control datum args...) drops its first argument.
				int datumIndex = LispNames.CERROR.equals(head) ? 2 : 1;
				if (parts.size() <= datumIndex) {
					return false;
				}
				LispVal datum = parts.get(datumIndex);
				if (datum instanceof LispString) {
					// A literal control string signals a plain message; no instance is
					// built for error/warn (signal is handled above).
					return false;
				}
				if (quotedSymbol(datum) != null || isNamedForm(datum, LispNames.MAKE_CONDITION)) {
					return true;
				}
				// A runtime datum WITH initargs takes error's registry dispatch, which
				// constructs; warn keeps the plain object-designator path.
				return !LispNames.WARN.equals(head) && parts.size() > datumIndex + 1;
			}
			default:
				return false;
		}
	}

	/**
	 * Whether a CONDITION instance can exist in this program -- the gate for the
	 * generated {@code %condition-report-str} renderer and, with it, for routing
	 * {@code princ}/{@code ~A} of a condition through its {@code :report}. A program that
	 * can never build a condition keeps every printing operator (and every signal
	 * message) byte-identical to a build that never knew about reports.
	 *
	 * <p>
	 * It is the CONDITION half of {@link #mayCreateInstances}, sharing its
	 * {@code constructsInstance} case split so the two cannot drift: a struct or plain
	 * CLOS instance does not count, a spliced condition-class constructor
	 * ({@code %obj-new} of a {@code %class-} tag whose class descends from
	 * {@code condition}) does, and every signal site with a non-string datum does --
	 * including a bare {@code #'error} reference, whose generated wrapper reaches the
	 * same object-designator expansion. Over-approximating costs an unused renderer;
	 * under-approximating cannot break a build, because every site that calls the
	 * renderer falls back to its pre-report message when it is absent.
	 * @param program the top-level forms, AFTER the library splices
	 * @param closRegistry the class registry
	 * @return whether a condition instance can exist
	 */
	public static boolean mayCreateConditions(List<LispVal> program, ClosRegistry closRegistry) {
		for (LispVal form : program) {
			if (mayCreateCondition(form, closRegistry)) {
				return true;
			}
		}
		return false;
	}

	private static boolean mayCreateCondition(LispVal form, ClosRegistry closRegistry) {
		if (form instanceof LispArray array) {
			for (LispVal element : array.data()) {
				if (mayCreateCondition(element, closRegistry)) {
					return true;
				}
			}
			return false;
		}
		if (!(form instanceof LispCons cons)) {
			// A folded #S(...) literal is a struct instance -- #S reads defstruct types
			// only -- so it can never be a condition.
			return false;
		}
		if (cons.car() instanceof LispSymbol head && constructsCondition(head.name(), cons, closRegistry)) {
			return true;
		}
		return mayCreateCondition(cons.car(), closRegistry) || mayCreateCondition(cons.cdr(), closRegistry);
	}

	/** The per-operator half of {@link #mayCreateConditions}. */
	private static boolean constructsCondition(String head, LispCons form, ClosRegistry closRegistry) {
		if (LispNames.OBJ_NEW.equals(head)) {
			// The spliced constructor of a class: a condition only when the tag names a
			// class descending from condition (a defstruct/defclass one does not).
			return form.cdr() instanceof LispCons rest && quotedSymbol(rest.car()) instanceof LispSymbol tag
					&& tag.name().startsWith(LispLayout.CLASS_TAG_PREFIX)
					&& isConditionClass(closRegistry, tag.name().substring(LispLayout.CLASS_TAG_PREFIX.length()));
		}
		if (LispNames.FUNCTION.equals(head)) {
			// #'error / #'warn / #'cerror join the #'signal of constructsInstance: their
			// generated wrappers reach the object-designator expansion, which renders the
			// datum's report.
			return form.cdr() instanceof LispCons rest && rest.car() instanceof LispSymbol fn
					&& (LispNames.ERROR.equals(fn.name()) || LispNames.WARN.equals(fn.name())
							|| LispNames.CERROR.equals(fn.name()) || constructsInstance(head, form));
		}
		return constructsInstance(head, form);
	}

	/** Whether the named class is registered and descends from {@code condition}. */
	private static boolean isConditionClass(ClosRegistry closRegistry, String className) {
		ClosRegistry.ClassInfo cls = closRegistry.findClass(className);
		return cls != null && cls.ancestors().contains("CONDITION");
	}

	private static final String WITH_SLOTS_OBJ_VAR = "__with_slots_obj";

	/**
	 * Expands {@code (with-slots (slot... | (var slot)...) instance body...)} by
	 * substituting each slot variable in the body with a {@code slot-value} form over a
	 * once-evaluated instance temp -- the symbol-macro semantics of CL's
	 * {@code with-slots}, so {@code setf}/{@code push}/{@code incf} of a slot variable
	 * write through to the slot:
	 *
	 * <pre>
	 * (with-slots (a (bee b)) obj (setf a (1+ bee))) ->
	 *   (let ((__with_slots_obj obj))
	 *     (setf (slot-value __with_slots_obj 'a) (1+ (slot-value __with_slots_obj 'b))))
	 * </pre>
	 *
	 * Lite: the substitution is textual over the body tree (quoted data is skipped); an
	 * inner binding shadowing a slot variable is still substituted.
	 * @param cons the with-slots expression
	 * @return the expanded expression
	 */
	public static LispVal expandWithSlots(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3) {
			throw new IllegalArgumentException(
					LispNames.WITH_SLOTS + " expects (with-slots (slots...) instance body...): " + cons.print());
		}
		LispSymbol obj = new LispSymbol(WITH_SLOTS_OBJ_VAR);
		java.util.Map<String, LispVal> substitutions = new java.util.LinkedHashMap<>();
		List<LispVal> letBindings = new java.util.ArrayList<>();
		if (parts.get(1) instanceof LispCons slotList) {
			for (LispVal entry : slotList.toList()) {
				LispSymbol var;
				LispSymbol slot;
				if (entry instanceof LispSymbol s) {
					var = s;
					slot = s;
				}
				else if (entry instanceof LispCons pair && pair.toList().size() == 2
						&& pair.toList().get(0) instanceof LispSymbol v
						&& pair.toList().get(1) instanceof LispSymbol n) {
					var = v;
					slot = n;
				}
				else {
					throw new IllegalArgumentException(
							LispNames.WITH_SLOTS + " expects slot names or (var slot) pairs: " + cons.print());
				}
				LispVal read = listToCons(List.of(new LispSymbol(LispNames.SLOT_VALUE), obj,
						listToCons(List.of(new LispSymbol(LispNames.QUOTE), slot))));
				substitutions.put(var.name(), read);
				letBindings.add(listToCons(List.of(var, read)));
			}
		}
		else if (!(parts.get(1) instanceof LispNil)) {
			throw new IllegalArgumentException(
					LispNames.WITH_SLOTS + " expects a slot list as the first argument: " + cons.print());
		}
		List<LispVal> body = new java.util.ArrayList<>();
		for (LispVal form : parts.subList(3, parts.size())) {
			body.add(substituteSymbols(form, substitutions));
		}
		// The substituted body no longer mentions the slot variables textually, but code
		// GENERATED at run time inside the body (a macrolet template mentioning a slot
		// variable) still resolves them: the let binds each variable to an entry-time
		// slot read as a fallback (reads only -- a write from generated code updates the
		// local copy; textual writes went through the substitution).
		LispVal inner = letBindings.isEmpty() ? prognOrNil(body)
				: listToCons(concatForms(List.of(new LispSymbol(LispNames.LET), listToCons(letBindings)), body));
		return makeLet(WITH_SLOTS_OBJ_VAR, parts.get(2), inner);
	}

	private static final String WITH_ACCESSORS_OBJ_VAR = "__with_accessors_obj";

	/**
	 * Expands {@code (with-accessors ((var accessor)...) instance body...)} the way
	 * {@link #expandWithSlots} expands its slot variables: each variable is substituted
	 * in the body with a call of its accessor on a once-evaluated instance temp, so a
	 * read is the accessor call and a {@code setf}/{@code incf} of the variable becomes a
	 * {@code setf} of the accessor place -- the symbol-macro semantics CL specifies.
	 *
	 * <pre>
	 * (with-accessors ((x pt-x) (y pt-y)) p (setf x (+ x y))) -&gt;
	 *   (let ((__with_accessors_obj p))
	 *     (setf (pt-x __with_accessors_obj) (+ (pt-x __with_accessors_obj) (pt-y __with_accessors_obj))))
	 * </pre>
	 *
	 * Unlike {@code with-slots} this needs no registry: an accessor is an ordinary
	 * generic function and (through {@code structAccessors}) an ordinary {@code setf}
	 * place.
	 * @param cons the with-accessors expression
	 * @return the expanded expression
	 */
	public static LispVal expandWithAccessors(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3) {
			throw new IllegalArgumentException(LispNames.WITH_ACCESSORS
					+ " expects (with-accessors ((var accessor)...) instance body...): " + cons.print());
		}
		LispSymbol obj = new LispSymbol(WITH_ACCESSORS_OBJ_VAR);
		java.util.Map<String, LispVal> substitutions = new java.util.LinkedHashMap<>();
		List<LispVal> letBindings = new java.util.ArrayList<>();
		if (parts.get(1) instanceof LispCons entryList) {
			for (LispVal entry : entryList.toList()) {
				if (!(entry instanceof LispCons pair) || pair.toList().size() != 2
						|| !(pair.toList().get(0) instanceof LispSymbol var)
						|| !(pair.toList().get(1) instanceof LispSymbol accessor)) {
					throw new IllegalArgumentException(
							LispNames.WITH_ACCESSORS + " expects (var accessor) pairs: " + cons.print());
				}
				LispVal read = listToCons(List.of(accessor, obj));
				substitutions.put(var.name(), read);
				letBindings.add(listToCons(List.of(var, read)));
			}
		}
		else if (!(parts.get(1) instanceof LispNil)) {
			throw new IllegalArgumentException(
					LispNames.WITH_ACCESSORS + " expects an accessor list as the first argument: " + cons.print());
		}
		List<LispVal> body = new java.util.ArrayList<>();
		for (LispVal form : parts.subList(3, parts.size())) {
			body.add(substituteSymbols(form, substitutions));
		}
		// Same fallback let as with-slots: code GENERATED at run time inside the body
		// still resolves the variables, as entry-time reads.
		LispVal inner = letBindings.isEmpty() ? prognOrNil(body)
				: listToCons(concatForms(List.of(new LispSymbol(LispNames.LET), listToCons(letBindings)), body));
		return makeLet(WITH_ACCESSORS_OBJ_VAR, parts.get(2), inner);
	}

	/** Concatenates a form-list head with body forms into one list. */
	private static List<LispVal> concatForms(List<LispVal> head, List<LispVal> body) {
		List<LispVal> out = new java.util.ArrayList<>(head);
		out.addAll(body.isEmpty() ? List.of(LispNil.INSTANCE) : body);
		return out;
	}

	/**
	 * Replaces every occurrence of the mapped symbols in a form with their replacement
	 * expressions, skipping quoted data -- the lite symbol-macro substitution behind
	 * {@code with-slots}.
	 */
	private static LispVal substituteSymbols(LispVal form, java.util.Map<String, LispVal> substitutions) {
		if (form instanceof LispSymbol sym) {
			LispVal replacement = substitutions.get(sym.name());
			return replacement != null ? replacement : form;
		}
		if (!(form instanceof LispCons cons)) {
			return form;
		}
		if (cons.car() instanceof LispSymbol head && LispNames.QUOTE.equals(head.name())) {
			return form;
		}
		// A (setq slot-var value ...) whose target substitutes into a slot-value PLACE
		// is no longer a legal setq; rewrite the operator to setf, which accepts both
		// symbol and place targets (cl-ppcre's flatten setqs inside with-slots).
		if (cons.car() instanceof LispSymbol head && LispNames.SETQ.equals(head.name()) && cons.isProperList()) {
			List<LispVal> parts = cons.toList();
			boolean placeTarget = false;
			List<LispVal> out = new java.util.ArrayList<>(parts.size());
			out.add(parts.get(0));
			for (int i = 1; i < parts.size(); i++) {
				LispVal substituted = substituteSymbols(parts.get(i), substitutions);
				if (i % 2 == 1 && substituted instanceof LispCons) {
					placeTarget = true;
				}
				out.add(substituted);
			}
			if (placeTarget) {
				out.set(0, new LispSymbol(LispNames.SETF));
			}
			return listToCons(out);
		}
		LispVal car = substituteSymbols(cons.car(), substitutions);
		LispVal cdr = substituteSymbols(cons.cdr(), substitutions);
		if (car == cons.car() && cdr == cons.cdr()) {
			return form;
		}
		return new LispCons(car, cdr);
	}

	/** The symbol inside a literal {@code (quote sym)} form, or null. */
	private static @Nullable LispSymbol quotedSymbol(LispVal form) {
		if (form instanceof LispCons cons && cons.car() instanceof LispSymbol q && LispNames.QUOTE.equals(q.name())
				&& cons.cdr() instanceof LispCons cdr && cdr.car() instanceof LispSymbol sym) {
			return sym;
		}
		return null;
	}

	/**
	 * Registers {@code (defgeneric name (params...) options...)} in the registry.
	 * Supported options: {@code (:documentation "...")} and inline {@code (:method
	 * [qualifier] (params...) body...)} clauses -- each is expanded like a standalone
	 * {@code defmethod} and its method-body defun is added to {@code methodDefuns}. The
	 * lambda list may continue past the required parameters ({@code &optional}/
	 * {@code &rest}/{@code &key}): the dispatcher then forwards a {@code &rest} tail with
	 * {@code apply}. A generic implicitly created by an earlier {@code defmethod} is
	 * updated (congruence-checked) instead of redefined.
	 * @param cons the defgeneric expression
	 * @param closRegistry mutated: the generic (and any inline methods) are registered
	 * @param methodDefuns mutated: the generated method-body defuns of inline
	 * {@code (:method ...)} clauses are appended
	 * @return the normalized generic-function name
	 */
	public static String registerDefgeneric(LispCons cons, ClosRegistry closRegistry, List<LispVal> methodDefuns) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3 || !(parts.get(1) instanceof LispSymbol nameSym)) {
			throw new IllegalArgumentException(
					LispNames.DEFGENERIC + " expects a name and a lambda list: " + cons.print());
		}
		GfLambdaList ll = parseGfLambdaList(parts.get(2), LispNames.DEFGENERIC, cons);
		List<String> paramNames = ll.requiredNames();
		String documentation = null;
		List<LispCons> inlineMethods = new java.util.ArrayList<>();
		for (int i = 3; i < parts.size(); i++) {
			if (parts.get(i) instanceof LispCons optCons && optCons.car() instanceof LispSymbol optSym
					&& ":DOCUMENTATION".equals(plainTypeName(optSym)) && optCons.cdr() instanceof LispCons docCons
					&& docCons.car() instanceof LispString doc) {
				documentation = doc.value();
				continue;
			}
			if (parts.get(i) instanceof LispCons optCons && optCons.car() instanceof LispSymbol optSym
					&& ":METHOD".equals(plainTypeName(optSym))) {
				// (:method [qualifier] (params...) body...) = a standalone defmethod.
				List<LispVal> method = new java.util.ArrayList<>();
				method.add(new LispSymbol(LispNames.DEFMETHOD));
				method.add(nameSym);
				method.addAll(optCons.toList().subList(1, optCons.toList().size()));
				inlineMethods.add((LispCons) listToCons(method));
				continue;
			}
			if (parts.get(i) instanceof LispCons optCons && optCons.car() instanceof LispSymbol optSym
					&& (LispNames.DECLARE.equals(plainTypeName(optSym))
							|| ":ARGUMENT-PRECEDENCE-ORDER".equals(plainTypeName(optSym))
							|| ":GENERIC-FUNCTION-CLASS".equals(plainTypeName(optSym))
							|| ":METHOD-CLASS".equals(plainTypeName(optSym)))) {
				// (declare (optimize ...)) is a no-op like every declaration;
				// :argument-precedence-order and the metaclass options are accepted and
				// ignored (lite: leftmost-first ordering, no MOP).
				continue;
			}
			throw new UnsupportedOperationException(
					LispNames.DEFGENERIC + " option is not supported: " + parts.get(i).print());
		}
		ClosRegistry.GenericInfo existing = closRegistry.findGeneric(nameSym.name());
		ClosRegistry.GenericInfo info;
		if (existing != null) {
			if (existing.paramNames().size() != paramNames.size()) {
				throw new IllegalArgumentException(
						LispNames.DEFGENERIC + " " + nameSym.name() + ": lambda list does not match its methods ("
								+ existing.paramNames().size() + " required parameters)");
			}
			existing.paramNames(paramNames);
			existing.documentation(documentation);
			info = existing;
		}
		else {
			info = new ClosRegistry.GenericInfo(nameSym.name(), paramNames);
			info.documentation(documentation);
			closRegistry.registerGeneric(info);
		}
		if (ll.variadic()) {
			info.markVariadic();
		}
		for (LispCons method : inlineMethods) {
			methodDefuns.add(expandDefmethod(method, closRegistry));
		}
		return ClosRegistry.normalize(nameSym.name());
	}

	/**
	 * A parsed generic-function lambda list: the required parameter names and whether the
	 * list continues past them ({@code &optional}/{@code &rest}/{@code &key}).
	 *
	 * @param requiredNames the required parameter names
	 * @param variadic whether a lambda-list keyword follows the required parameters
	 */
	private record GfLambdaList(List<String> requiredNames, boolean variadic) {
	}

	private static GfLambdaList parseGfLambdaList(LispVal lambdaList, String operator, LispCons form) {
		List<String> names = new java.util.ArrayList<>();
		if (lambdaList instanceof LispNil) {
			return new GfLambdaList(names, false);
		}
		if (!(lambdaList instanceof LispCons paramsCons)) {
			throw new IllegalArgumentException(operator + " expects a lambda list: " + form.print());
		}
		for (LispVal param : paramsCons.toList()) {
			if (param instanceof LispSymbol sym && sym.name().startsWith("&")) {
				return new GfLambdaList(names, true);
			}
			if (!(param instanceof LispSymbol sym)) {
				throw new UnsupportedOperationException(
						operator + " expects parameter names in the lambda list: " + form.print());
			}
			names.add(sym.name());
		}
		return new GfLambdaList(names, false);
	}

	/**
	 * Registers {@code (defmethod name (params...) body...)} in the registry and expands
	 * it into the method-body defun ({@code %<name>--m<i>}). Any required parameter may
	 * carry a specializer: {@code (var (eql literal))}, {@code (var class-name)} for a
	 * {@code defclass} class, {@code (var type-name)} for a built-in type, or {@code
	 * (var t)}/plain {@code var} for an unspecialized parameter. Methods are ordered by
	 * CL's leftmost-first specificity (the per-parameter ranks compared
	 * lexicographically). The lambda list may continue past the required parameters
	 * ({@code &optional}/{@code &rest}/{@code &key}): the tail is kept verbatim on the
	 * method-body defun and the dispatcher forwards its own {@code &rest} tail with
	 * {@code apply} (a bare {@code call-next-method} then forwards the required arguments
	 * only -- lite). Defining the same qualifier + specializers again replaces the
	 * previous method. The caller regenerates the dispatcher with
	 * {@link #generateDispatcher}.
	 * @param cons the defmethod expression
	 * @param closRegistry mutated: the method is registered (and the generic implicitly
	 * created when no defgeneric preceded it)
	 * @return the generated method-body defun
	 */
	public static LispVal expandDefmethod(LispCons cons, ClosRegistry closRegistry) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3 || !(parts.get(1) instanceof LispSymbol nameSym)) {
			throw new IllegalArgumentException(
					LispNames.DEFMETHOD + " expects a name and a lambda list: " + cons.print());
		}
		// An optional qualifier (:before/:after/:around) precedes the lambda list.
		String qualifier = "";
		int llIndex = 2;
		if (parts.get(2) instanceof LispSymbol qSym) {
			String qName = plainTypeName(qSym);
			if (":BEFORE".equals(qName) || ":AFTER".equals(qName) || ":AROUND".equals(qName)) {
				qualifier = qName;
				llIndex = 3;
			}
			else {
				throw new UnsupportedOperationException(
						LispNames.DEFMETHOD + " qualifier is not supported (only :before/:after/:around): " + qName
								+ " in " + cons.print());
			}
		}
		if (parts.size() <= llIndex) {
			throw new IllegalArgumentException(LispNames.DEFMETHOD + " expects a lambda list: " + cons.print());
		}
		List<String> paramNames = new java.util.ArrayList<>();
		List<ClosRegistry.Specializer> specializers = new java.util.ArrayList<>();
		List<LispVal> tail = new java.util.ArrayList<>();
		if (parts.get(llIndex) instanceof LispCons paramsCons) {
			List<LispVal> params = paramsCons.toList();
			for (int i = 0; i < params.size(); i++) {
				LispVal param = params.get(i);
				if (param instanceof LispSymbol sym && sym.name().startsWith("&")) {
					tail.addAll(params.subList(i, params.size()));
					break;
				}
				if (param instanceof LispSymbol sym) {
					paramNames.add(sym.name());
					specializers.add(ClosRegistry.Specializer.DEFAULT);
					continue;
				}
				if (!(param instanceof LispCons paramCons) || !(paramCons.car() instanceof LispSymbol varSym)
						|| paramCons.toList().size() != 2) {
					throw new IllegalArgumentException(
							LispNames.DEFMETHOD + " expects var or (var specializer), got " + param.print());
				}
				paramNames.add(varSym.name());
				specializers.add(parseSpecializer(paramCons.toList().get(1), cons, closRegistry));
			}
		}
		else if (!(parts.get(llIndex) instanceof LispNil)) {
			throw new IllegalArgumentException(LispNames.DEFMETHOD + " expects a lambda list: " + cons.print());
		}
		ClosRegistry.GenericInfo generic = closRegistry.findGeneric(nameSym.name());
		if (generic == null) {
			generic = new ClosRegistry.GenericInfo(nameSym.name(), paramNames);
			closRegistry.registerGeneric(generic);
		}
		else if (generic.paramNames().size() != paramNames.size()) {
			throw new IllegalArgumentException(
					LispNames.DEFMETHOD + " " + nameSym.name() + ": lambda list does not match the generic function ("
							+ generic.paramNames().size() + " required parameters)");
		}
		if (!tail.isEmpty()) {
			generic.markVariadic();
			// CL computes a generic call's valid keyword set as the UNION of the
			// generic's
			// and every applicable method's keywords, so a method never rejects a keyword
			// a sibling method accepts: (update-digest state seq :digest d) reaches
			// ironclad's sha256 updater, which declares only :start/:end. The lite model
			// makes every &key method permissive instead of computing that union.
			if (tail.stream().anyMatch(p -> p instanceof LispSymbol s && LispNames.LAMBDA_KEY.equals(s.name())) && tail
				.stream()
				.noneMatch(p -> p instanceof LispSymbol s && LispNames.LAMBDA_ALLOW_OTHER_KEYS.equals(s.name()))) {
				tail.add(new LispSymbol(LispNames.LAMBDA_ALLOW_OTHER_KEYS));
			}
		}
		// A bare (call-next-method) passes the method's ORIGINAL arguments, the optional
		// and keyword ones included -- ironclad's hmac reinitialize-instance forwards its
		// :key that way to the system default. The forwarding needs a rest variable, so
		// one is injected when the method declares a keyword/optional tail without one
		// (CL section order allows &rest before &key; a tail already starting with
		// &optional keeps the required-args-only forwarding).
		String methodRestVar = restVarOf(tail);
		if (methodRestVar == null && !tail.isEmpty() && tail.get(0) instanceof LispSymbol firstMarker
				&& LispNames.LAMBDA_KEY.equals(firstMarker.name())) {
			methodRestVar = "%method-args";
			tail.add(0, new LispSymbol(methodRestVar));
			tail.add(0, new LispSymbol(LispNames.LAMBDA_REST));
		}
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(generic.name());
		String functionName = (qn == null ? "%" + generic.name() : qn.pkg() + "::%" + qn.member()) + "--m"
				+ generic.nextMethodIndex();
		String specKey = specKeyText(specializers);
		// Qualifier + specializers form the registry key, so a :before dog method and a
		// primary dog method coexist while redefining the same qualifier+specializers
		// replaces (CL semantics).
		String key = qualifier.isEmpty() ? specKey : qualifier + " " + specKey;
		List<LispVal> body = parts.subList(llIndex + 1, parts.size());
		boolean usesNext = usesNextMethod(body);
		generic.methods()
			.put(key, new ClosRegistry.MethodInfo(List.copyOf(specializers), functionName, qualifier, usesNext));
		// Every method-body defun takes a leading %next-method thunk; call-next-method
		// and next-method-p in the body are rewritten against it (harmless for methods
		// that do not use them -- the dispatcher passes nil).
		List<LispVal> methodParams = new java.util.ArrayList<>();
		methodParams.add(new LispSymbol(NEXT_METHOD_VAR));
		paramNames.stream().<LispVal>map(LispSymbol::new).forEach(methodParams::add);
		methodParams.addAll(tail);
		List<LispVal> defun = new java.util.ArrayList<>();
		defun.add(new LispSymbol(LispNames.DEFUN));
		defun.add(new LispSymbol(functionName));
		defun.add(listToCons(methodParams));
		// The method body establishes a block named after the GENERIC (not the
		// internal %<generic>--mN defun), so (return-from <generic> v) inside a
		// defmethod exits the method, as in CL (scanner-style code relies on it).
		List<LispVal> blockParts = new java.util.ArrayList<>();
		blockParts.add(new LispSymbol(LispNames.BLOCK));
		blockParts.add(new LispSymbol(generic.name()));
		for (LispVal form : body) {
			blockParts.add(rewriteNextMethod(form, paramNames, methodRestVar));
		}
		defun.add(listToCons(blockParts));
		LispVal methodDefun = listToCons(defun);
		// The instance-initialization generics (initialize-instance /
		// reinitialize-instance / shared-initialize) have no system-supplied primary
		// method in the static subset (make-instance's constructor already fills the
		// slots), so the FIRST user method on one of them -- typically an :after
		// (cl-ppcre's str length computer, ironclad's hmac keying) -- also synthesizes
		// the system default primary; without it the dispatcher would signal "No
		// applicable method" for every other class. The defaults chain like CL's:
		// initialize-instance and reinitialize-instance call shared-initialize (with t
		// and nil slot-names respectively), whose own default returns the instance.
		// The condition is the ABSENCE of an all-default primary (not of any primary):
		// the
		// system method is applicable to every instance, so a class-specialized primary
		// (ironclad's sha256 register reset) does not replace it -- a sibling primary's
		// (call-next-method) must still find it.
		if (isInitProtocolGeneric(plainName(generic.name())) && !hasDefaultPrimary(generic)) {
			List<LispVal> synthesized = new java.util.ArrayList<>();
			synthesizeInitProtocolDefault(generic, closRegistry, synthesized);
			synthesized.add(methodDefun);
			return makeProgn(synthesized);
		}
		return methodDefun;
	}

	/**
	 * Whether the generic already has an unqualified method specialized on nothing (the
	 * shape of both a user default method and the synthesized system default).
	 */
	private static boolean hasDefaultPrimary(ClosRegistry.GenericInfo generic) {
		return generic.methods()
			.values()
			.stream()
			.anyMatch(m -> m.qualifier().isEmpty()
					&& m.specializers().stream().allMatch(s -> s.kind() == ClosRegistry.SpecializerKind.DEFAULT));
	}

	/** Whether the plain generic name is one of the instance-initialization generics. */
	private static boolean isInitProtocolGeneric(String plainName) {
		return "INITIALIZE-INSTANCE".equals(plainName) || "REINITIALIZE-INSTANCE".equals(plainName)
				|| "SHARED-INITIALIZE".equals(plainName);
	}

	/**
	 * Synthesizes the system default primary of one instance-initialization generic into
	 * {@code out} and registers it on the generic: shared-initialize's default returns
	 * the instance; initialize-instance's / reinitialize-instance's defaults
	 * {@code (apply #'shared-initialize instance t/nil initargs)} -- creating the
	 * shared-initialize generic (with its own identity default and dispatcher) when the
	 * program never defines a method on it, so the chain always resolves.
	 */
	private static void synthesizeInitProtocolDefault(ClosRegistry.GenericInfo generic, ClosRegistry closRegistry,
			List<LispVal> out) {
		String plain = plainName(generic.name());
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(generic.name());
		List<ClosRegistry.Specializer> defaults = new java.util.ArrayList<>();
		for (int i = 0; i < generic.paramNames().size(); i++) {
			defaults.add(ClosRegistry.Specializer.DEFAULT);
		}
		String defaultName = (qn == null ? "%" + generic.name() : qn.pkg() + "::%" + qn.member()) + "--m"
				+ generic.nextMethodIndex();
		generic.methods().put(specKeyText(defaults), new ClosRegistry.MethodInfo(defaults, defaultName, "", false));
		generic.markVariadic();
		List<LispVal> defaultParams = new java.util.ArrayList<>();
		defaultParams.add(new LispSymbol(NEXT_METHOD_VAR));
		generic.paramNames().stream().<LispVal>map(LispSymbol::new).forEach(defaultParams::add);
		defaultParams.add(new LispSymbol(LispNames.LAMBDA_REST));
		defaultParams.add(new LispSymbol("%init-args"));
		LispSymbol instanceVar = new LispSymbol(generic.paramNames().get(0));
		LispVal body;
		if ("SHARED-INITIALIZE".equals(plain)) {
			body = instanceVar;
		}
		else {
			ClosRegistry.GenericInfo shared = closRegistry.generics()
				.values()
				.stream()
				.filter(g -> "SHARED-INITIALIZE".equals(plainName(g.name())))
				.findFirst()
				.orElse(null);
			if (shared == null) {
				// No shared-initialize method anywhere yet: create the generic with its
				// own system default so the chain resolves. Its DISPATCHER is emitted by
				// the caller (the compile path reserves a slot per registered generic;
				// the interpreter regenerates every dispatcher after each defmethod).
				String sharedName = qn == null ? "SHARED-INITIALIZE" : qn.pkg() + "::SHARED-INITIALIZE";
				shared = new ClosRegistry.GenericInfo(sharedName, List.of("%obj", "%slot-names"));
				closRegistry.registerGeneric(shared);
				synthesizeInitProtocolDefault(shared, closRegistry, out);
			}
			LispVal slotNamesArg = "INITIALIZE-INSTANCE".equals(plain) ? LispTrue.INSTANCE : LispNil.INSTANCE;
			LispVal applyCall = listToCons(List.of(new LispSymbol(LispNames.APPLY),
					listToCons(List.of(new LispSymbol(LispNames.FUNCTION), new LispSymbol(shared.name()))), instanceVar,
					slotNamesArg, new LispSymbol("%init-args")));
			body = makeProgn(List.of(applyCall, instanceVar));
		}
		out.add(listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(defaultName),
				listToCons(defaultParams), body)));
	}

	/** Strips a package qualifier from a symbol name. */
	private static String plainName(String name) {
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(name);
		return qn == null ? name : qn.member();
	}

	/** Parses one parameter specializer of a {@code defmethod} lambda list. */
	private static ClosRegistry.Specializer parseSpecializer(LispVal spec, LispCons form, ClosRegistry closRegistry) {
		if (spec instanceof LispCons specCons && specCons.car() instanceof LispSymbol specHead
				&& LispNames.EQL.equals(plainTypeName(specHead))) {
			return new ClosRegistry.Specializer(ClosRegistry.SpecializerKind.EQL,
					parseEqlSpecializerValue(specCons, form), null);
		}
		if (spec instanceof LispTrue) {
			return ClosRegistry.Specializer.DEFAULT;
		}
		if (spec instanceof LispSymbol specSym) {
			String plainName = plainTypeName(specSym);
			ClosRegistry.ClassInfo specClass = closRegistry.findClass(specSym.name());
			if ("T".equals(plainName)) {
				return ClosRegistry.Specializer.DEFAULT;
			}
			if (specClass != null) {
				return new ClosRegistry.Specializer(ClosRegistry.SpecializerKind.CLASS, null,
						ClosRegistry.normalize(specClass.name()));
			}
			if (closRegistry.findStructTag(specSym.name()) != null) {
				// A defstruct type as a specializer: a TYPE specializer carrying the
				// struct name; the dispatcher tests the struct instance tag.
				return new ClosRegistry.Specializer(ClosRegistry.SpecializerKind.TYPE, null, specSym.name());
			}
			if (isSupportedTypeSpecializer(plainName)) {
				return new ClosRegistry.Specializer(ClosRegistry.SpecializerKind.TYPE, null, plainName);
			}
			throw new IllegalArgumentException(LispNames.DEFMETHOD + ": unknown specializer " + specSym.name()
					+ " (a class must be defined by defclass before the method)");
		}
		throw new IllegalArgumentException(LispNames.DEFMETHOD + ": unsupported specializer " + spec.print());
	}

	/** The canonical key text of a method's specializer list. */
	private static String specKeyText(List<ClosRegistry.Specializer> specializers) {
		return specializers.stream()
			.map(ClosRegistry.Specializer::keyText)
			.collect(java.util.stream.Collectors.joining(" | "));
	}

	/** The internal name of a method's next-method thunk parameter. */
	private static final String NEXT_METHOD_VAR = "%next-method";

	/**
	 * Whether a method body references {@code call-next-method} or {@code next-method-p}.
	 */
	private static boolean usesNextMethod(List<LispVal> body) {
		return body.stream().anyMatch(LispMacroExpander::treeMentionsNextMethod);
	}

	private static boolean treeMentionsNextMethod(LispVal form) {
		if (form instanceof LispSymbol sym) {
			String plain = plainTypeName(sym);
			return LispNames.CALL_NEXT_METHOD.equals(plain) || LispNames.NEXT_METHOD_P.equals(plain);
		}
		if (form instanceof LispCons cons) {
			return cons.toList().stream().anyMatch(LispMacroExpander::treeMentionsNextMethod);
		}
		return false;
	}

	/**
	 * Rewrites {@code (call-next-method args...)} to a guarded {@code funcall} of the
	 * method's {@code %next-method} thunk (no args reuse the method's own parameters, so
	 * a bare {@code (call-next-method)} passes the current arguments) and
	 * {@code (next-method-p)} to a nil-test of that thunk. Quoted data and other symbols
	 * are left untouched.
	 */
	private static LispVal rewriteNextMethod(LispVal form, List<String> paramNames, @Nullable String restVar) {
		if (!(form instanceof LispCons cons) || !cons.isProperList()) {
			return form;
		}
		if (cons.car() instanceof LispSymbol head && LispNames.QUOTE.equals(head.name())) {
			return form;
		}
		if (cons.car() instanceof LispSymbol head) {
			String plain = plainTypeName(head);
			if (LispNames.CALL_NEXT_METHOD.equals(plain)) {
				List<LispVal> rawArgs = cons.toList().subList(1, cons.toList().size());
				List<LispVal> args = rawArgs.isEmpty() ? paramNames.stream().<LispVal>map(LispSymbol::new).toList()
						: rawArgs.stream().map(a -> rewriteNextMethod(a, paramNames, restVar)).toList();
				List<LispVal> call = new java.util.ArrayList<>();
				// A bare (call-next-method) in a method with a rest tail forwards that
				// tail too (the original arguments, keywords included), so it becomes an
				// apply rather than a funcall.
				String forwardedRest = rawArgs.isEmpty() ? restVar : null;
				call.add(new LispSymbol(forwardedRest != null ? LispNames.APPLY : LispNames.FUNCALL));
				call.add(new LispSymbol(NEXT_METHOD_VAR));
				call.addAll(args);
				if (forwardedRest != null) {
					call.add(new LispSymbol(forwardedRest));
				}
				return makeIf(new LispSymbol(NEXT_METHOD_VAR), listToCons(call), listToCons(
						List.of(new LispSymbol(LispNames.ERROR), new LispString("call-next-method: no next method"))));
			}
			if (LispNames.NEXT_METHOD_P.equals(plain) && cons.toList().size() == 1) {
				return callOf(LispNames.NOT, callOf(LispNames.NULL, new LispSymbol(NEXT_METHOD_VAR)));
			}
		}
		List<LispVal> out = new java.util.ArrayList<>();
		for (LispVal element : cons.toList()) {
			out.add(rewriteNextMethod(element, paramNames, restVar));
		}
		return listToCons(out);
	}

	/**
	 * The {@code &rest}/{@code &body} variable name declared by a lambda-list tail, or
	 * null when it declares none.
	 */
	@Nullable private static String restVarOf(List<LispVal> tail) {
		for (int i = 0; i + 1 < tail.size(); i++) {
			if (tail.get(i) instanceof LispSymbol marker
					&& (LispNames.LAMBDA_REST.equals(marker.name()) || LispNames.LAMBDA_BODY.equals(marker.name()))
					&& tail.get(i + 1) instanceof LispSymbol var) {
				return var.name();
			}
		}
		return null;
	}

	/** The literal compared against by an {@code (eql ...)} specializer. */
	private static LispVal parseEqlSpecializerValue(LispCons specCons, LispCons defmethodForm) {
		List<LispVal> specParts = specCons.toList();
		if (specParts.size() != 2) {
			throw new IllegalArgumentException(LispNames.DEFMETHOD + " expects (eql literal), got " + specCons.print());
		}
		LispVal value = specParts.get(1);
		// (eql 'x) evaluates its form in CL: unwrap a quote around any atom (including
		// the self-evaluating t/nil, which read as (quote t)/(quote nil)).
		if (value instanceof LispCons quoteCons && quoteCons.car() instanceof LispSymbol q
				&& LispNames.QUOTE.equals(q.name()) && quoteCons.cdr() instanceof LispCons quotedRest
				&& !(quotedRest.car() instanceof LispCons)) {
			value = quotedRest.car();
		}
		if (value instanceof LispSymbol || value instanceof LispInteger || value instanceof LispBigInteger
				|| value instanceof LispDouble || value instanceof LispRatio || value instanceof LispChar
				|| value instanceof LispTrue || value instanceof LispNil) {
			return value;
		}
		throw new UnsupportedOperationException(LispNames.DEFMETHOD
				+ " eql specializers support keyword/symbol/number/character literals only: " + defmethodForm.print());
	}

	/** Whether a plain (package-stripped) type name is usable as a TYPE specializer. */
	private static boolean isSupportedTypeSpecializer(String plainName) {
		return atomicTypePredicate(plainName) != null || switch (plainName) {
			case "BOOLEAN", "UNSIGNED-BYTE", "SIGNED-BYTE", "VECTOR", "SIMPLE-VECTOR", "ARRAY", "SIMPLE-ARRAY",
					"SEQUENCE", "STANDARD-OBJECT", "STRUCTURE-OBJECT", "PATHNAME" ->
				true;
			default -> false;
		};
	}

	/**
	 * Generates the dispatcher defun of a generic function: a chain testing the first
	 * argument against each method's specializer, most specific first ({@code eql}
	 * methods, then class methods -- subclass before superclass -- then specific built-in
	 * types, then general built-in types), falling back to the default method or, without
	 * one, to {@code (error "No applicable method: ...")}. The dispatcher is an ordinary
	 * defun, so {@code #'name}/{@code funcall} work naturally.
	 * @param genericName the generic-function name (any spelling)
	 * @param closRegistry the registry holding the generic and the class ancestor sets
	 * @return the dispatcher defun
	 */
	public static LispVal generateDispatcher(String genericName, ClosRegistry closRegistry) {
		ClosRegistry.GenericInfo generic = closRegistry.findGeneric(genericName);
		if (generic == null) {
			throw new IllegalArgumentException("Unknown generic function: " + genericName);
		}
		List<LispVal> params = generic.paramNames().stream().<LispVal>map(LispSymbol::new).toList();
		boolean variadic = generic.variadic();
		// The combined (standard method combination) body is generated only when a
		// qualifier or call-next-method is present; otherwise the historical single-call
		// dispatcher is emitted unchanged.
		boolean combined = generic.methods().values().stream().anyMatch(m -> !m.isPrimary() || m.usesNext());
		LispVal chain = combined ? combinedDispatchBody(generic, params, closRegistry)
				: simpleDispatchBody(generic, params, closRegistry);
		List<LispVal> defun = new java.util.ArrayList<>();
		defun.add(new LispSymbol(LispNames.DEFUN));
		defun.add(new LispSymbol(generic.name()));
		List<LispVal> defunParams = new java.util.ArrayList<>(params);
		if (variadic) {
			defunParams.add(new LispSymbol("&REST"));
			defunParams.add(new LispSymbol(GF_REST_VAR));
		}
		defun.add(defunParams.isEmpty() ? LispNil.INSTANCE : listToCons(defunParams));
		defun.add(chain);
		return listToCons(defun);
	}

	/** The dispatcher's rest parameter of a variadic generic function. */
	private static final String GF_REST_VAR = "%gf-rest";

	/**
	 * The single-method-per-branch dispatcher body (no qualifiers, no call-next-method).
	 */
	private static LispVal simpleDispatchBody(ClosRegistry.GenericInfo generic, List<LispVal> params,
			ClosRegistry closRegistry) {
		List<ClosRegistry.MethodInfo> methods = new java.util.ArrayList<>(generic.methods().values());
		MiRefinement refinement = miRefinement(generic, closRegistry);
		java.util.Set<ClosRegistry.MethodInfo> exactTagBranches = java.util.Collections
			.newSetFromMap(new java.util.IdentityHashMap<>());
		if (refinement != null) {
			// One EXACT-TAG branch per multiply-inheriting class whose applicable
			// methods have no single most-specific member: it calls the method its own
			// class precedence list ranks first, which no per-specializer branch order
			// can get right for both (a b) and (b a) subclasses at once.
			for (ClosRegistry.ClassInfo x : refinement.classes()) {
				ClosRegistry.MethodInfo winner = mostSpecificForClass(generic, refinement.classPos(), x, closRegistry);
				if (winner != null) {
					ClosRegistry.MethodInfo rep = miBranchRep(refinement, x, winner.functionName());
					methods.add(rep);
					exactTagBranches.add(rep);
				}
			}
		}
		methods.sort(specificityOrder(closRegistry));
		boolean variadic = generic.variadic();
		ClosRegistry.MethodInfo defaultMethod = methods.stream()
			.filter(ClosRegistry.MethodInfo::isDefault)
			.findFirst()
			.orElse(null);
		LispVal chain = defaultMethod != null ? methodCall(defaultMethod, params, variadic)
				: noApplicableMethod(generic.name(), params);
		for (ClosRegistry.MethodInfo method : methods.reversed()) {
			if (method.isDefault()) {
				continue;
			}
			LispVal test = exactTagBranches.contains(method)
					? miExactTagTest(method, java.util.Objects.requireNonNull(refinement), params)
					: specializerTest(method, params, closRegistry);
			chain = makeIf(test, methodCall(method, params, variadic), chain);
		}
		return chain;
	}

	/**
	 * The multiple-inheritance dispatch refinement of one generic: the single parameter
	 * position its class-specialized methods dispatch on, and the registered classes
	 * whose applicable class specializers have NO single most-specific member (an
	 * instance inheriting from two unrelated specializers through different parents).
	 * Those classes each get an exact-tag branch; every other class keeps riding the
	 * per-specializer branches, whose most-derived applicable specializer sorts first.
	 *
	 * <p>
	 * Null (no refinement) when the registry has no multiply-inheriting class -- the gate
	 * that keeps single-inheritance dispatchers byte-identical -- when class methods
	 * dispatch on more than one position or carry another specialized position (kept on
	 * the lite per-specializer branches, a documented divergence), or when no class needs
	 * a branch.
	 */
	private static @Nullable MiRefinement miRefinement(ClosRegistry.GenericInfo generic, ClosRegistry closRegistry) {
		if (!closRegistry.hasMultipleInheritance()) {
			return null;
		}
		int classPos = -1;
		java.util.LinkedHashSet<String> classSpecs = new java.util.LinkedHashSet<>();
		for (ClosRegistry.MethodInfo m : generic.methods().values()) {
			List<ClosRegistry.Specializer> specs = m.specializers();
			for (int i = 0; i < specs.size(); i++) {
				if (specs.get(i).kind() != ClosRegistry.SpecializerKind.CLASS) {
					continue;
				}
				if (classPos != -1 && classPos != i) {
					return null;
				}
				for (int j = 0; j < specs.size(); j++) {
					if (j != i && specs.get(j).kind() != ClosRegistry.SpecializerKind.DEFAULT) {
						return null;
					}
				}
				classPos = i;
				classSpecs.add(ClosRegistry.normalize(java.util.Objects.requireNonNull(specs.get(i).name())));
			}
		}
		if (classPos < 0 || classSpecs.size() < 2) {
			return null;
		}
		List<ClosRegistry.ClassInfo> classes = new java.util.ArrayList<>();
		for (ClosRegistry.ClassInfo x : closRegistry.classes().values()) {
			List<String> applicable = classSpecs.stream().filter(c -> x.ancestors().contains(c)).toList();
			if (applicable.size() < 2) {
				continue;
			}
			boolean dominated = false;
			for (String c : applicable) {
				ClosRegistry.ClassInfo info = closRegistry.findClass(c);
				if (info != null && info.ancestors().containsAll(applicable)) {
					dominated = true;
					break;
				}
			}
			if (!dominated) {
				classes.add(x);
			}
		}
		return classes.isEmpty() ? null : new MiRefinement(classPos, classes);
	}

	/**
	 * One generic's multiple-inheritance dispatch refinement (see {@link #miRefinement}).
	 *
	 * @param classPos the single parameter position the class methods dispatch on
	 * @param classes the classes needing an exact-tag branch, in registration order
	 */
	private record MiRefinement(int classPos, List<ClosRegistry.ClassInfo> classes) {
	}

	/** A synthesized branch representative: CLASS {@code x} at the dispatch position. */
	private static ClosRegistry.MethodInfo miBranchRep(MiRefinement refinement, ClosRegistry.ClassInfo x,
			String functionName) {
		List<ClosRegistry.Specializer> specs = new java.util.ArrayList<>();
		for (int i = 0; i < refinement.classPos(); i++) {
			specs.add(ClosRegistry.Specializer.DEFAULT);
		}
		specs.add(new ClosRegistry.Specializer(ClosRegistry.SpecializerKind.CLASS, null, x.name()));
		return new ClosRegistry.MethodInfo(List.copyOf(specs), functionName, "", false);
	}

	/**
	 * The exact-tag test of a synthesized branch: {@code (%obj-is arg '%class-X)} for X
	 * alone. Descendant classes deliberately fall through -- each diamond-affected
	 * descendant carries its own exact-tag branch, and the rest are served correctly by
	 * the ordinary branches (their most-derived applicable specializer sorts first).
	 */
	private static LispVal miExactTagTest(ClosRegistry.MethodInfo rep, MiRefinement refinement, List<LispVal> params) {
		String className = java.util.Objects.requireNonNull(rep.specializers().get(refinement.classPos()).name());
		return objIs(params.get(refinement.classPos()), List.of(LispLayout.CLASS_TAG_PREFIX + className));
	}

	/**
	 * The most specific method applicable to an instance of exactly class {@code x} (by
	 * {@code x}'s class precedence list), among the methods class-specialized at
	 * {@code classPos}. Null when none applies.
	 */
	private static ClosRegistry.@Nullable MethodInfo mostSpecificForClass(ClosRegistry.GenericInfo generic,
			int classPos, ClosRegistry.ClassInfo x, ClosRegistry closRegistry) {
		ClosRegistry.MethodInfo best = null;
		int bestIndex = Integer.MAX_VALUE;
		for (ClosRegistry.MethodInfo m : generic.methods().values()) {
			if (m.isDefault()) {
				continue;
			}
			List<ClosRegistry.Specializer> specs = m.specializers();
			if (classPos >= specs.size() || specs.get(classPos).kind() != ClosRegistry.SpecializerKind.CLASS) {
				continue;
			}
			int index = cplIndexOf(x,
					ClosRegistry.normalize(java.util.Objects.requireNonNull(specs.get(classPos).name())));
			if (index >= 0 && index < bestIndex) {
				bestIndex = index;
				best = m;
			}
		}
		return best;
	}

	/** The position of a (normalized) class name in {@code x}'s CPL, or -1. */
	private static int cplIndexOf(ClosRegistry.ClassInfo x, String normalizedName) {
		for (int i = 0; i < x.cpl().size(); i++) {
			if (ClosRegistry.normalize(x.cpl().get(i)).equals(normalizedName)) {
				return i;
			}
		}
		return -1;
	}

	/**
	 * The standard-method-combination dispatcher body: one branch per distinct
	 * specializer (most specific first) whose value is that branch's effective method
	 * (its applicable {@code :around}/{@code :before}/primary/{@code :after} methods
	 * composed with {@code call-next-method}), with the default methods as the fallback
	 * branch.
	 */
	private static LispVal combinedDispatchBody(ClosRegistry.GenericInfo generic, List<LispVal> params,
			ClosRegistry closRegistry) {
		java.util.LinkedHashMap<String, ClosRegistry.MethodInfo> reps = new java.util.LinkedHashMap<>();
		for (ClosRegistry.MethodInfo m : generic.methods().values()) {
			if (!m.isDefault()) {
				reps.putIfAbsent(specKeyOf(m), m);
			}
		}
		List<ClosRegistry.MethodInfo> branches = new java.util.ArrayList<>(reps.values());
		MiRefinement refinement = miRefinement(generic, closRegistry);
		java.util.Set<ClosRegistry.MethodInfo> exactTagBranches = java.util.Collections
			.newSetFromMap(new java.util.IdentityHashMap<>());
		if (refinement != null) {
			// One exact-tag branch per diamond-affected class: its effective method is
			// computed against THAT class, so the applicable set is complete (a
			// per-specializer branch only sees the methods its own ancestors carry) and
			// ordered by that class's precedence list.
			for (ClosRegistry.ClassInfo x : refinement.classes()) {
				ClosRegistry.MethodInfo rep = miBranchRep(refinement, x, "%mi-branch");
				branches.add(rep);
				exactTagBranches.add(rep);
			}
		}
		branches.sort(specificityOrder(closRegistry));
		LispVal chain = effectiveMethod(null, generic, params, closRegistry);
		for (ClosRegistry.MethodInfo rep : branches.reversed()) {
			LispVal test = exactTagBranches.contains(rep)
					? miExactTagTest(rep, java.util.Objects.requireNonNull(refinement), params)
					: specializerTest(rep, params, closRegistry);
			chain = makeIf(test, effectiveMethod(rep, generic, params, closRegistry), chain);
		}
		return chain;
	}

	/** The specializer key of a method, ignoring its qualifier. */
	private static String specKeyOf(ClosRegistry.MethodInfo m) {
		return specKeyText(m.specializers());
	}

	/**
	 * Builds the effective method for one dispatch branch. {@code branchRep} is a
	 * representative method carrying the branch's specializer, or null for the default
	 * (fallback) branch. The applicable methods of each role are the ones whose
	 * specializer a branch instance satisfies (default methods always apply); primaries
	 * and befores run most specific first, afters least specific first, arounds wrap
	 * everything.
	 */
	private static LispVal effectiveMethod(ClosRegistry.@Nullable MethodInfo branchRep,
			ClosRegistry.GenericInfo generic, List<LispVal> params, ClosRegistry closRegistry) {
		boolean variadic = generic.variadic();
		List<ClosRegistry.MethodInfo> arounds = applicableMethods(generic, branchRep, ":AROUND", closRegistry);
		List<ClosRegistry.MethodInfo> befores = applicableMethods(generic, branchRep, ":BEFORE", closRegistry);
		List<ClosRegistry.MethodInfo> primaries = applicableMethods(generic, branchRep, "", closRegistry);
		List<ClosRegistry.MethodInfo> afters = applicableMethods(generic, branchRep, ":AFTER", closRegistry);
		afters = afters.reversed();
		if (primaries.isEmpty() && arounds.isEmpty()) {
			return noApplicableMethod(generic.name(), params);
		}
		LispVal core = buildCore(befores, primaries, afters, params, generic.name(), variadic);
		if (arounds.isEmpty()) {
			return core;
		}
		LispVal coreThunk = lambdaOf(params, core, variadic);
		LispVal next = buildNextChain(arounds, 1, coreThunk, params, variadic);
		return callWithNext(arounds.get(0).functionName(), next, params, variadic);
	}

	/**
	 * The applicable methods of one qualifier role for a branch, sorted most specific
	 * first.
	 */
	private static List<ClosRegistry.MethodInfo> applicableMethods(ClosRegistry.GenericInfo generic,
			ClosRegistry.@Nullable MethodInfo branchRep, String qualifier, ClosRegistry closRegistry) {
		List<ClosRegistry.MethodInfo> result = new java.util.ArrayList<>();
		for (ClosRegistry.MethodInfo m : generic.methods().values()) {
			if (m.qualifier().equals(qualifier) && appliesToBranch(m, branchRep, closRegistry)) {
				result.add(m);
			}
		}
		result.sort(branchSpecificityOrder(branchRep, closRegistry));
		return result;
	}

	/**
	 * The specificity order WITHIN one branch's applicable methods: like
	 * {@link #specificityOrder}, but where the branch is class-specialized, two class
	 * specializers at that position rank by their place in the BRANCH class's precedence
	 * list -- CL's per-argument method ordering. Under single inheritance the applicable
	 * class specializers form a chain, where the ancestor-set-size proxy and the CPL
	 * agree, so the refinement is gated on multiple inheritance to keep the plain sort
	 * (and its emitted dispatchers) untouched.
	 */
	private static java.util.Comparator<ClosRegistry.MethodInfo> branchSpecificityOrder(
			ClosRegistry.@Nullable MethodInfo branchRep, ClosRegistry closRegistry) {
		if (branchRep == null || !closRegistry.hasMultipleInheritance()) {
			return specificityOrder(closRegistry);
		}
		List<ClosRegistry.Specializer> branchSpecs = branchRep.specializers();
		return (a, b) -> {
			List<ClosRegistry.Specializer> sa = a.specializers();
			List<ClosRegistry.Specializer> sb = b.specializers();
			int n = Math.max(sa.size(), sb.size());
			for (int i = 0; i < n; i++) {
				ClosRegistry.Specializer branchSpec = i < branchSpecs.size() ? branchSpecs.get(i)
						: ClosRegistry.Specializer.DEFAULT;
				int ra = branchAwareRank(i < sa.size() ? sa.get(i) : ClosRegistry.Specializer.DEFAULT, branchSpec,
						closRegistry);
				int rb = branchAwareRank(i < sb.size() ? sb.get(i) : ClosRegistry.Specializer.DEFAULT, branchSpec,
						closRegistry);
				if (ra != rb) {
					return Integer.compare(ra, rb);
				}
			}
			return 0;
		};
	}

	/**
	 * The rank of one specializer within a branch: the branch class's CPL index (kept
	 * inside the 10-99 class band) when both are classes, the global
	 * {@link #specializerRank} otherwise (also the fallback for an ancestor that reaches
	 * the branch class only through a {@code define-condition} extra parent, which joins
	 * the ancestor SET but not the CPL).
	 */
	private static int branchAwareRank(ClosRegistry.Specializer spec, ClosRegistry.Specializer branchSpec,
			ClosRegistry closRegistry) {
		if (spec.kind() == ClosRegistry.SpecializerKind.CLASS
				&& branchSpec.kind() == ClosRegistry.SpecializerKind.CLASS) {
			ClosRegistry.ClassInfo branchClass = closRegistry
				.findClass(java.util.Objects.requireNonNull(branchSpec.name()));
			if (branchClass != null) {
				int index = cplIndexOf(branchClass,
						ClosRegistry.normalize(java.util.Objects.requireNonNull(spec.name())));
				if (index >= 0) {
					return 10 + Math.min(index, 89);
				}
			}
		}
		return specializerRank(spec, closRegistry);
	}

	/**
	 * Whether an instance selecting {@code branchRep}'s branch (null = the default
	 * branch) also satisfies method {@code m}'s specializers -- checked per parameter
	 * position. A default (unspecialized) parameter always applies; a class parameter
	 * applies when the branch's parameter is a descendant class; eql/type parameters
	 * apply only when the branch's parameter matches exactly (cross-type subtyping among
	 * specializers is out of scope).
	 */
	private static boolean appliesToBranch(ClosRegistry.MethodInfo m, ClosRegistry.@Nullable MethodInfo branchRep,
			ClosRegistry closRegistry) {
		if (m.isDefault()) {
			return true;
		}
		if (branchRep == null) {
			return false;
		}
		List<ClosRegistry.Specializer> specs = m.specializers();
		List<ClosRegistry.Specializer> branchSpecs = branchRep.specializers();
		for (int i = 0; i < specs.size(); i++) {
			ClosRegistry.Specializer spec = specs.get(i);
			ClosRegistry.Specializer branch = i < branchSpecs.size() ? branchSpecs.get(i)
					: ClosRegistry.Specializer.DEFAULT;
			if (!specApplies(spec, branch, closRegistry)) {
				return false;
			}
		}
		return true;
	}

	private static boolean specApplies(ClosRegistry.Specializer spec, ClosRegistry.Specializer branch,
			ClosRegistry closRegistry) {
		return switch (spec.kind()) {
			case DEFAULT -> true;
			case EQL ->
				branch.kind() == ClosRegistry.SpecializerKind.EQL && java.util.Objects.requireNonNull(spec.eqlValue())
					.print()
					.equals(java.util.Objects.requireNonNull(branch.eqlValue()).print());
			case CLASS -> {
				if (branch.kind() != ClosRegistry.SpecializerKind.CLASS) {
					yield false;
				}
				ClosRegistry.ClassInfo branchClass = closRegistry.classes().get(branch.name());
				yield branchClass != null && branchClass.ancestors().contains(spec.name());
			}
			case TYPE -> branch.kind() == ClosRegistry.SpecializerKind.TYPE
					&& java.util.Objects.equals(spec.name(), branch.name());
		};
	}

	/**
	 * The before/primary/after core: run the befores for effect, invoke the primary chain
	 * (whose value is returned), then run the afters for effect.
	 */
	private static LispVal buildCore(List<ClosRegistry.MethodInfo> befores, List<ClosRegistry.MethodInfo> primaries,
			List<ClosRegistry.MethodInfo> afters, List<LispVal> params, String genericName, boolean variadic) {
		List<LispVal> sequence = new java.util.ArrayList<>();
		for (ClosRegistry.MethodInfo before : befores) {
			sequence.add(callWithNext(before.functionName(), LispNil.INSTANCE, params, variadic));
		}
		LispVal primaryInvocation;
		if (primaries.isEmpty()) {
			primaryInvocation = listToCons(List.of(new LispSymbol(LispNames.ERROR),
					new LispString("No applicable primary method: " + genericName)));
		}
		else {
			LispVal next = buildNextChain(primaries, 1, LispNil.INSTANCE, params, variadic);
			primaryInvocation = callWithNext(primaries.get(0).functionName(), next, params, variadic);
		}
		sequence.add(primaryInvocation);
		LispVal beforeAndPrimary = sequence.size() == 1 ? sequence.get(0) : prognOf(sequence);
		if (afters.isEmpty()) {
			return beforeAndPrimary;
		}
		List<LispVal> let = new java.util.ArrayList<>();
		let.add(new LispSymbol(LispNames.LET));
		LispSymbol resultVar = new LispSymbol("%clos-result");
		let.add(listToCons(List.of(listToCons(List.of(resultVar, beforeAndPrimary)))));
		for (ClosRegistry.MethodInfo after : afters) {
			let.add(callWithNext(after.functionName(), LispNil.INSTANCE, params, variadic));
		}
		let.add(resultVar);
		return listToCons(let);
	}

	/**
	 * Builds the next-method thunk passed to the {@code i-1}-th method of a chain: a
	 * {@code (lambda (params) (method-i next-{i+1} params))} closing the remaining
	 * methods, or {@code base} once the chain is exhausted.
	 */
	private static LispVal buildNextChain(List<ClosRegistry.MethodInfo> chain, int i, LispVal base,
			List<LispVal> params, boolean variadic) {
		if (i >= chain.size()) {
			return base;
		}
		LispVal next = buildNextChain(chain, i + 1, base, params, variadic);
		return lambdaOf(params, callWithNext(chain.get(i).functionName(), next, params, variadic), variadic);
	}

	/**
	 * {@code (functionName next params...)}, or, for a variadic generic, {@code (apply
	 * (function functionName) next params... %gf-rest)} so the dispatcher's rest tail
	 * reaches the method-body defun's own lambda-list tail.
	 */
	private static LispVal callWithNext(String functionName, LispVal next, List<LispVal> params, boolean variadic) {
		List<LispVal> call = new java.util.ArrayList<>();
		if (variadic) {
			call.add(new LispSymbol(LispNames.APPLY));
			call.add(listToCons(List.of(new LispSymbol(LispNames.FUNCTION), new LispSymbol(functionName))));
		}
		else {
			call.add(new LispSymbol(functionName));
		}
		call.add(next);
		call.addAll(params);
		if (variadic) {
			call.add(new LispSymbol(GF_REST_VAR));
		}
		return listToCons(call);
	}

	/** {@code (lambda (params... [&rest %gf-rest]) body)}. */
	private static LispVal lambdaOf(List<LispVal> params, LispVal body, boolean variadic) {
		List<LispVal> lambdaParams = new java.util.ArrayList<>(params);
		if (variadic) {
			lambdaParams.add(new LispSymbol("&REST"));
			lambdaParams.add(new LispSymbol(GF_REST_VAR));
		}
		return listToCons(List.of(new LispSymbol(LispNames.LAMBDA),
				lambdaParams.isEmpty() ? LispNil.INSTANCE : listToCons(lambdaParams), body));
	}

	private static LispVal prognOf(List<LispVal> forms) {
		List<LispVal> progn = new java.util.ArrayList<>();
		progn.add(new LispSymbol(LispNames.PROGN));
		progn.addAll(forms);
		return listToCons(progn);
	}

	private static LispVal noApplicableMethod(String genericName, List<LispVal> params) {
		if (params.isEmpty()) {
			return listToCons(
					List.of(new LispSymbol(LispNames.ERROR), new LispString("No applicable method: " + genericName)));
		}
		// Name the first argument's class: "No applicable method: X" alone made a
		// cross-package generic-name collision (two `:reader message` generics)
		// undiagnosable at run time. The DESIGNATOR (tag symbol), not class-of: the
		// message needs a name, and class-of would drag the metaobject runtime into
		// every program with a generic function.
		LispVal classOf = listToCons(List.of(new LispSymbol(LispNames.CLASS_DESIGNATOR_INTERNAL), params.get(0)));
		LispVal message = listToCons(List.of(new LispSymbol(LispNames.STRING_CONCAT),
				new LispString("No applicable method: " + genericName + " on "),
				callOf(LispNames.PRINC_TO_STRING, classOf)));
		return listToCons(List.of(new LispSymbol(LispNames.ERROR), message));
	}

	/**
	 * The single-call form of the simple dispatcher:
	 * {@code (functionName nil params...)}.
	 */
	private static LispVal methodCall(ClosRegistry.MethodInfo method, List<LispVal> params, boolean variadic) {
		return callWithNext(method.functionName(), LispNil.INSTANCE, params, variadic);
	}

	/**
	 * The dispatch test of a method: the {@code and} of its per-parameter specializer
	 * tests (unspecialized parameters contribute none; a fully unspecialized method tests
	 * {@code t}).
	 */
	private static LispVal specializerTest(ClosRegistry.MethodInfo method, List<LispVal> params,
			ClosRegistry closRegistry) {
		List<LispVal> tests = new java.util.ArrayList<>();
		List<ClosRegistry.Specializer> specs = method.specializers();
		for (int i = 0; i < specs.size() && i < params.size(); i++) {
			ClosRegistry.Specializer spec = specs.get(i);
			if (spec.kind() == ClosRegistry.SpecializerKind.DEFAULT) {
				continue;
			}
			tests.add(singleSpecializerTest(spec, params.get(i), closRegistry));
		}
		if (tests.isEmpty()) {
			return LispTrue.INSTANCE;
		}
		if (tests.size() == 1) {
			return tests.get(0);
		}
		List<LispVal> and = new java.util.ArrayList<>();
		and.add(new LispSymbol(LispNames.AND));
		and.addAll(tests);
		return listToCons(and);
	}

	private static LispVal singleSpecializerTest(ClosRegistry.Specializer spec, LispVal arg,
			ClosRegistry closRegistry) {
		return switch (spec.kind()) {
			case EQL -> makeEqlSpecializerTest(arg, java.util.Objects.requireNonNull(spec.eqlValue()));
			case CLASS ->
				// (%obj-is arg '%class-X ...): the tag set of the class and its
				// (statically known) descendants.
				makeClassInstanceTest(arg, java.util.Objects.requireNonNull(spec.name()), closRegistry);
			case TYPE -> {
				String structTag = closRegistry.findStructTag(java.util.Objects.requireNonNull(spec.name()));
				if (structTag != null) {
					// A defstruct type: test the tag set of the struct and its :include
					// descendants, exactly like the struct predicate.
					List<String> tags = closRegistry.descendantStructTags(spec.name());
					yield objIs(arg, tags.isEmpty() ? List.of(structTag) : tags);
				}
				// No cons/list/sequence exclusion is needed: an instance is its own
				// value type, so consp/listp are already nil on it.
				yield makeTypeTest(arg, new LispSymbol(spec.name()), closRegistry);
			}
			case DEFAULT -> LispTrue.INSTANCE;
		};
	}

	private static LispVal orOf(List<LispVal> tests) {
		List<LispVal> or = new java.util.ArrayList<>();
		or.add(new LispSymbol(LispNames.OR));
		or.addAll(tests);
		return listToCons(or);
	}

	/**
	 * The test of an {@code (eql literal)} specializer. Symbols (including keywords)
	 * compare with {@code equal} -- content-safe on WASM, where symbols are interned
	 * strings -- and numbers/characters with {@code eql}.
	 */
	private static LispVal makeEqlSpecializerTest(LispVal arg, LispVal value) {
		if (value instanceof LispNil) {
			return callOf(LispNames.NULL, arg);
		}
		if (value instanceof LispSymbol || value instanceof LispTrue) {
			LispVal literal = value instanceof LispSymbol ? listToCons(List.of(new LispSymbol(LispNames.QUOTE), value))
					: value;
			return listToCons(List.of(new LispSymbol(LispNames.EQUAL), arg, literal));
		}
		return listToCons(List.of(new LispSymbol(LispNames.EQL), arg, value));
	}

	/**
	 * The specificity order of methods: the per-parameter ranks compared
	 * lexicographically, leftmost parameter first -- CL's method ordering for
	 * disjoint-ish specializers. The sort is stable, so equally-ranked (disjoint)
	 * specializers keep definition order.
	 */
	private static java.util.Comparator<ClosRegistry.MethodInfo> specificityOrder(ClosRegistry closRegistry) {
		return (a, b) -> {
			List<ClosRegistry.Specializer> sa = a.specializers();
			List<ClosRegistry.Specializer> sb = b.specializers();
			int n = Math.max(sa.size(), sb.size());
			for (int i = 0; i < n; i++) {
				int ra = i < sa.size() ? specializerRank(sa.get(i), closRegistry) : 1000;
				int rb = i < sb.size() ? specializerRank(sb.get(i), closRegistry) : 1000;
				if (ra != rb) {
					return Integer.compare(ra, rb);
				}
			}
			return 0;
		};
	}

	/**
	 * The specificity rank of one parameter specializer (smaller dispatches earlier): eql
	 * (0), classes (10-99, deeper subclass first), built-in types (200s, subtypes before
	 * their supertypes), default (1000).
	 */
	private static int specializerRank(ClosRegistry.Specializer spec, ClosRegistry closRegistry) {
		return switch (spec.kind()) {
			case EQL -> 0;
			case CLASS -> {
				ClosRegistry.ClassInfo info = closRegistry.classes().get(spec.name());
				yield Math.max(10, 100 - (info == null ? 1 : info.ancestors().size()));
			}
			case TYPE -> {
				if (closRegistry.findStructTag(java.util.Objects.requireNonNull(spec.name())) != null) {
					// A defstruct specializer: deeper :include descendants dispatch first
					// (the 100-199 band sits between classes and built-in types).
					yield Math.max(100, 199 - closRegistry.structAncestorCount(spec.name()));
				}
				yield switch (spec.name()) {
					case "NULL" -> 200;
					case "KEYWORD", "UNSIGNED-BYTE" -> 210;
					case "BOOLEAN" -> 212;
					case "STANDARD-CHAR", "BASE-CHAR" -> 215;
					case "DOUBLE-FLOAT", "SINGLE-FLOAT", "SHORT-FLOAT", "LONG-FLOAT" -> 218;
					case "RATIONAL", "RATIO" -> 225;
					case "NUMBER", "REAL", "VECTOR", "SIMPLE-VECTOR", "SIMPLE-STRING", "BASE-STRING" -> 230;
					case "LIST", "ARRAY", "SIMPLE-ARRAY" -> 235;
					case "SEQUENCE", "ATOM" -> 240;
					case "STANDARD-OBJECT", "STRUCTURE-OBJECT" -> 250;
					default -> 220;
				};
			}
			case DEFAULT -> 1000;
		};
	}

	/**
	 * Splices every top-level {@code defstruct}/{@code defclass}/{@code defgeneric}/
	 * {@code defmethod} of a program into its generated defuns. A defstruct is spliced
	 * where it stands, while classes and methods are collected across the WHOLE program
	 * first, then each generic's dispatcher defun is inserted at its defgeneric's
	 * position (or its first defmethod's position when no defgeneric exists), so
	 * class-specializer descendant sets and method sets are complete regardless of
	 * definition order (Pass 1 collects all defuns before compiling bodies). The
	 * compilers run this after package resolution and before lambda-list desugaring (the
	 * generated constructors use {@code &key}); a CLOS form anywhere else is rejected by
	 * the expression compilers.
	 *
	 * <p>
	 * This is also where a {@code #S(...)} source literal becomes an instance: each form
	 * is run through {@link StructLiteralFolder} against the registry as it stands at
	 * that point, which is the compile-path half of CL's read-time construction (the
	 * interpreter's half sits at its top-level {@code eval} entries).
	 * @param program the top-level forms
	 * @param structAccessors mutated: accessor name to 1-based slot position
	 * @param closRegistry mutated: classes, generics, and methods
	 * @return the program with each definition replaced by its generated defuns
	 */
	public static List<LispVal> expandTopLevelDefinitions(List<LispVal> program,
			java.util.Map<String, Integer> structAccessors, ClosRegistry closRegistry) {
		return expandTopLevelDefinitions(program, structAccessors, closRegistry, null);
	}

	/**
	 * Whether the program defines a function in the {@code closer-mop} package -- the
	 * mark of the spliced closer-mop shim library, whose {@code classp} needs the MOP
	 * base classes registered before its {@code (typep x 'standard-class)} expands.
	 * @param program the top-level forms
	 * @return true when a closer-mop defun is present
	 */
	private static boolean definesCloserMopFunction(List<LispVal> program) {
		for (LispVal form : program) {
			if (isNamedForm(form, LispNames.DEFUN) && form instanceof LispCons cons
					&& cons.cdr() instanceof LispCons rest && rest.car() instanceof LispSymbol name) {
				PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(name.name());
				if (qn != null && LispNames.CLOSER_MOP_PKG.equals(qn.pkg())) {
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Whether the program references {@code find-class} -- a call, or
	 * {@code #'find-class} taken as a value -- without bringing its own definition, which
	 * is the condition under which {@link #expandTopLevelDefinitions} injects the
	 * generated PUBLIC {@code find-class} defun (a thin wrapper over
	 * {@code %find-class}). Quoted data is skipped.
	 * @param program the top-level forms
	 * @return true when the public find-class defun is needed
	 */
	private static boolean needsFindClassRuntime(List<LispVal> program) {
		boolean referenced = false;
		for (LispVal form : program) {
			if (definesFunction(form, LispNames.FIND_CLASS)) {
				// The program (or a spliced library) defines find-class itself; its
				// definition wins and the generated defun stays out.
				return false;
			}
			referenced = referenced || referencesFunction(form, LispNames.FIND_CLASS);
		}
		return referenced;
	}

	/**
	 * Whether the program references {@code compile} without defining it -- the gate for
	 * the generated {@code compile} runtime (see {@code CompileRuntime}). A user (or
	 * library) {@code defun compile} wins and suppresses the injection.
	 * @param program the top-level forms
	 * @return true when the runtime is needed
	 */
	private static boolean needsCompileRuntime(List<LispVal> program) {
		boolean referenced = false;
		for (LispVal form : program) {
			if (definesFunction(form, LispNames.COMPILE)) {
				return false;
			}
			referenced = referenced || referencesFunction(form, LispNames.COMPILE);
		}
		return referenced;
	}

	/**
	 * Whether the program references {@code class-of} -- whose expansion resolves through
	 * the generated {@code %find-class} -- and so needs the metaobject runtime even when
	 * {@code find-class} itself is absent (or user-defined). Quoted data is skipped.
	 * @param program the top-level forms
	 * @return true when class-of is referenced
	 */
	private static boolean referencesClassOf(List<LispVal> program) {
		return program.stream().anyMatch(form -> referencesFunction(form, LispNames.CLASS_OF));
	}

	/** The package-stripped member of a possibly qualified name. */
	private static String memberOf(String name) {
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(name);
		return qn == null ? name : qn.member();
	}

	/** Whether the form is {@code (defun <functionName> ...)}, member-name matched. */
	private static boolean definesFunction(LispVal form, String functionName) {
		return isNamedForm(form, LispNames.DEFUN) && form instanceof LispCons cons
				&& cons.cdr() instanceof LispCons rest && rest.car() instanceof LispSymbol name
				&& functionName.equals(memberOf(name.name()));
	}

	// A #'make-instance VALUE reference anywhere outside quoted data -- a literal
	// (make-instance ...) call keeps the static expansion and does not count.
	private static boolean referencesMakeInstanceValue(LispVal form) {
		if (!(form instanceof LispCons cons)) {
			return false;
		}
		if (cons.car() instanceof LispSymbol op) {
			String member = memberOf(op.name());
			if (LispNames.QUOTE.equals(member)) {
				return false;
			}
			if (LispNames.FUNCTION.equals(member) && cons.cdr() instanceof LispCons rest
					&& rest.car() instanceof LispSymbol named
					&& LispNames.MAKE_INSTANCE.equals(memberOf(named.name()))) {
				return true;
			}
		}
		return referencesMakeInstanceValue(cons.car()) || referencesMakeInstanceValue(cons.cdr());
	}

	// A call of the named function, or a #'name reference, anywhere outside quoted data.
	private static boolean referencesFunction(LispVal form, String functionName) {
		if (!(form instanceof LispCons cons)) {
			return false;
		}
		if (cons.car() instanceof LispSymbol op) {
			String member = memberOf(op.name());
			if (LispNames.QUOTE.equals(member)) {
				return false;
			}
			if (functionName.equals(member)) {
				return true;
			}
			if (LispNames.FUNCTION.equals(member) && cons.cdr() instanceof LispCons rest
					&& rest.car() instanceof LispSymbol named && functionName.equals(memberOf(named.name()))) {
				return true;
			}
		}
		return referencesFunction(cons.car(), functionName) || referencesFunction(cons.cdr(), functionName);
	}

	/**
	 * As {@link #expandTopLevelDefinitions(List, java.util.Map, ClosRegistry)}, threading
	 * the export oracle a {@code defstruct} needs to spell its generated names the way
	 * the program's call sites do -- see
	 * {@link #expandDefstruct(LispCons, java.util.Map, ClosRegistry, java.util.function.BiPredicate)}.
	 * Each compiler passes the {@link PackageResolver} it just resolved the program with.
	 * @param program the top-level forms
	 * @param structAccessors mutated: accessor name to 1-based slot position
	 * @param closRegistry mutated: classes, generics, and methods
	 * @param exported {@code (package, member) -> is it external}, or {@code null}
	 * @return the program with each definition replaced by its generated defuns
	 */
	public static List<LispVal> expandTopLevelDefinitions(List<LispVal> program,
			java.util.Map<String, Integer> structAccessors, ClosRegistry closRegistry,
			java.util.function.@org.jspecify.annotations.Nullable BiPredicate<String, String> exported) {
		// The one whole-program pass both compilers already run, so the load-time-value
		// hoist rides along instead of needing its own registration in every pipeline.
		program = hoistLoadTimeValues(program);
		// A defclass carrying (:metaclass M) switches the metaclass protocol on: the
		// protocol's default methods and driver (MopProtocol) are PREPENDED so the walk
		// below registers them like user definitions -- ahead of the reference scans,
		// so the driver's find-class use activates the metaobject runtime by itself --
		// and the %mop-make-instance/%register-class-metaobject runtime is appended
		// after the walk once the registry is complete. A defclass merely EXTENDING one
		// of the seeded MOP base classes (a metaclass definition, a slot-definition
		// subclass) only needs the seeding.
		boolean metaclassProtocol = usesMetaclassProtocol(program);
		if (metaclassProtocol || namesMopBaseSuperclass(program)) {
			closRegistry.ensureMopClassesSeeded();
		}
		if (metaclassProtocol) {
			List<LispVal> withProtocol = new java.util.ArrayList<>(MopProtocol.forms());
			withProtocol.addAll(program);
			program = withProtocol;
		}
		// The closer-mop library's classp is (typep x 'standard-class): when its defuns
		// are in the program (spliced by the system loaders, which have no registry in
		// scope), the MOP base classes must register before any type test over them
		// expands -- including on the fast path below, whose forms still get their
		// bodies compiled. Keyed on the defun package so only closer-mop programs pay
		// the three extra registry classes in their runtime dispatch tables.
		if (definesCloserMopFunction(program)) {
			closRegistry.ensureMopClassesSeeded();
		}
		// A find-class or class-of reference compiles to the generated metaobject
		// runtime injected below; the MOP base classes must register BEFORE the walk so
		// the emitted %obj-new tags, the typep tables and every dispatch answer see one
		// consistent registry. The public find-class defun is separately gated so a
		// program defining its own find-class keeps it without losing class-of.
		boolean findClassDefun = needsFindClassRuntime(program);
		boolean metaobjectRuntime = findClassDefun || referencesClassOf(program);
		if (metaobjectRuntime) {
			closRegistry.ensureMopClassesSeeded();
		}
		// An allocate-instance reference compiles to the generated per-class
		// construction runtime injected below. It needs no MOP seeding of its own: a
		// metaobject argument only ever comes from find-class/class-of, whose own
		// references already seed above.
		boolean allocateInstanceRuntime = needsAllocateInstanceRuntime(program);
		// A compile reference compiles to the generated runtime defun injected below
		// (no-op for the definition-time method construction a splice already carried
		// out, an error for everything else -- see CompileRuntime).
		boolean compileRuntime = needsCompileRuntime(program);
		// #'make-instance taken as a VALUE (the (apply #'make-instance class args)
		// idiom of postmodern's make-dao): the backends inject a wrapper forwarding to
		// %mop-make-instance, so the runtime defun must be emitted with its dispatch
		// arms widened to every registered class. A literal (make-instance 'name ...)
		// call keeps the static expansion and never flips this.
		boolean makeInstanceFunction = program.stream().anyMatch(LispMacroExpander::referencesMakeInstanceValue);
		// A %class-slot-defs call site lowers to the shared runtime defun during the
		// backend passes; the defun and its table are injected below once the registry
		// is complete.
		boolean classSlotDefsRuntime = needsClassSlotDefsRuntime(program);
		// Every change-class target, recorded BEFORE the walk so the capacity reservation
		// below can widen its ancestors the moment the whole registry is known.
		registerChangeClassTargets(program, closRegistry);
		boolean runtimeSubtypep = needsRuntimeSubtypep(program);
		boolean runtimeTypep = needsRuntimeTypep(program);
		boolean runtimeError = needsRuntimeErrorDispatch(program);
		boolean restartMode = usesRestartSystem(program);
		// The condition-report gate, answered TWICE: here on the source program (a
		// program whose only condition is the simple-error a handler-case synthesizes
		// has no definition to splice and would take the fast path below), and again on
		// the expanded program, where a define-condition has become a %obj-new
		// constructor.
		closRegistry.setRoutesConditionReports(mayCreateConditions(program, closRegistry));
		boolean symbolFunctionWrite = usesSymbolFunctionWrite(program);
		if (!runtimeSubtypep && !runtimeTypep && !runtimeError && !restartMode && !metaobjectRuntime
				&& !allocateInstanceRuntime && !compileRuntime && !makeInstanceFunction && !classSlotDefsRuntime
				&& !symbolFunctionWrite && !readsSlots(program) && !closRegistry.routesConditionReports()
				&& program.stream()
					.noneMatch(f -> isDefstructForm(f) || isClosDefinitionForm(f) || isSetfFunctionDefun(f)
							|| isLetWithNestedDefmethod(f) || isNamedForm(f, LispNames.DEFTYPE))) {
			// No definitions to splice, so the registry stays as seeded: a #S(...)
			// literal
			// here can only name an unregistered structure type and the fold says so. It
			// returns the program itself when there is no literal, keeping the fast path.
			// The format renderer is still injected here when the program reaches it:
			// this path carries the plainest runtime-control (format ...) programs.
			return withFormatRenderer(StructLiteralFolder.foldProgram(program, closRegistry));
		}
		List<LispVal> out = new java.util.ArrayList<>(program.size());
		java.util.Map<Integer, String> dispatcherSlots = new java.util.LinkedHashMap<>();
		java.util.Set<String> placedDispatchers = new java.util.HashSet<>();
		for (LispVal rawForm : program) {
			// Fold this form's #S(...) literals against the registry as it stands BEFORE
			// the form is processed, so the defstruct must precede the literal -- CL's
			// read-time rule, which a whole-program fold after the walk would silently
			// relax.
			LispVal form = StructLiteralFolder.fold(rawForm, closRegistry);
			if (isSetfFunctionDefun(form)) {
				// (defun (setf name) ...) -> a plain (defun %setf-name ...); register the
				// place so (setf (name ...) v) expands to a call through the writer
				// defun.
				out.add(rewriteSetfFunctionDefun((LispCons) form, structAccessors));
			}
			else if (isDefstructForm(form)) {
				out.addAll(expandDefstruct((LispCons) form, structAccessors, closRegistry, exported));
			}
			else if (isNamedForm(form, LispNames.DEFCLASS)) {
				// The expansion mixes plain defuns (constructor) with synthesized
				// reader/writer defmethods; the methods go through the same
				// expansion + dispatcher placement as a top-level defmethod.
				for (LispVal generated : expandDefclass((LispCons) form, closRegistry, structAccessors)) {
					addExpandedDefinition(generated, out, closRegistry, dispatcherSlots, placedDispatchers);
				}
			}
			else if (isNamedForm(form, LispNames.DEFINE_CONDITION)) {
				// A condition type is an ordinary CLOS-subset class over the built-in
				// condition hierarchy; the :report form is registered for the
				// error/signal/warn message building.
				for (LispVal generated : expandDefclass(
						(LispCons) defineConditionToDefclass((LispCons) form, closRegistry), closRegistry,
						structAccessors)) {
					addExpandedDefinition(generated, out, closRegistry, dispatcherSlots, placedDispatchers);
				}
			}
			else if (isNamedForm(form, LispNames.DEFGENERIC)) {
				List<LispVal> methodDefuns = new java.util.ArrayList<>();
				String generic = registerDefgeneric(normalizeSetfMethodForm((LispCons) form, structAccessors),
						closRegistry, methodDefuns);
				out.addAll(methodDefuns);
				if (placedDispatchers.add(generic)) {
					dispatcherSlots.put(out.size(), generic);
					out.add(LispNil.INSTANCE);
				}
			}
			else if (isNamedForm(form, LispNames.DEFMETHOD)) {
				addExpandedDefinition(normalizeSetfMethodForm((LispCons) form, structAccessors), out, closRegistry,
						dispatcherSlots, placedDispatchers);
			}
			else if (isNamedForm(form, LispNames.DEFTYPE)) {
				// Register a zero-parameter deftype so a later typep/typecase resolves
				// its name; the form itself is a runtime no-op (replaced by nil).
				out.add(expandDeftype((LispCons) form, closRegistry));
			}
			else if (isLetWithNestedDefmethod(form)) {
				// The closure-over-let method idiom (cl-ppcre's
				// build-replacement-template capturing reg-scanner): each defmethod in
				// the let's body is registered and expanded in place, so its
				// method-body defun stays INSIDE the let and compiles to (setq name
				// (lambda ...)) -- a global closure the dispatcher (placed at top
				// level, after the let) reaches through the call-through-variable
				// fallback.
				expandLetNestedDefmethods((LispCons) form, closRegistry, out, dispatcherSlots, placedDispatchers,
						structAccessors);
			}
			else {
				out.add(form);
			}
		}
		for (java.util.Map.Entry<Integer, String> slot : dispatcherSlots.entrySet()) {
			out.set(slot.getKey(), generateDispatcher(slot.getValue(), closRegistry));
		}
		// Same phase, same reason as the dispatchers: a struct predicate emitted before
		// its :include children were registered tests too few tags.
		refreshStructPredicates(out, closRegistry);
		if (symbolFunctionWrite) {
			// A name bound ONLY by (setf (symbol-function ...)) needs a forwarder defun
			// so its direct call sites compile; appended once the registry is complete
			// (a generic's dispatcher must not be shadowed by a forwarder).
			out.addAll(symbolFunctionForwarderDefuns(setfOnlyFunctionAliasNames(program, closRegistry)));
		}
		if (metaobjectRuntime) {
			// The metaobject runtime: the generated defuns are position-independent and
			// appended; the data table and the memo global are top-level defvars and must
			// run before any top-level find-class/class-of call, so they go FIRST (after
			// the dispatcher slots above were filled by index). Emitted before the
			// instance/condition re-answers below so the %obj-new inside the
			// materializer is in their view.
			out.addAll(findClassRuntimeDefuns(findClassDefun));
			out.addAll(0, classMetaTableForms(closRegistry));
		}
		if (allocateInstanceRuntime) {
			// Position-independent defuns, appended once the registry is complete so
			// the per-class construction arms cover every class the program defines.
			out.addAll(allocateInstanceDefuns(closRegistry));
		}
		if (compileRuntime) {
			// Position-independent defuns, appended: a compiled program's compile is a
			// no-op for the definition-time method construction already spliced into
			// the program, and an error for anything else (see CompileRuntime).
			out.addAll(CompileRuntime.forms());
		}
		if (metaclassProtocol || makeInstanceFunction) {
			// The metaclass-protocol runtime: constructors for the three seeded MOP
			// base classes (their defclass never ran, so nothing else generates them),
			// the %mop-make-instance name dispatch over the metaobject-ancestored
			// classes (widened to EVERY registered class when the program takes
			// make-instance as a value -- the arms must construct whatever class the
			// runtime designator names), and the %register-class-metaobject memo
			// primer. All position-independent defuns; the memo defvar the protocol
			// relies on was injected with the metaobject runtime above (its find-class
			// reference guarantees that gate fired). A #'make-instance program without
			// a :metaclass defclass may never have seeded the MOP base classes, so
			// their constructors (and the primer) are emitted only when they are
			// registered respectively when the protocol runs.
			if (closRegistry.findClass(ClosRegistry.STANDARD_CLASS_NAME) != null) {
				out.addAll(seededMopConstructorDefuns(closRegistry));
			}
			out.addAll(mopMakeInstanceDefuns(closRegistry, makeInstanceFunction));
			if (metaclassProtocol) {
				out.add(registerClassMetaobjectDefun());
			}
		}
		if (classSlotDefsRuntime) {
			// Same shape as the typep runtime: the defun is position-independent and
			// appended; the data table is a top-level defvar and must run before any
			// top-level %class-slot-defs call, so it goes FIRST.
			out.add(classSlotDefsRuntimeDefun(closRegistry));
			out.addAll(0, classSlotDefsTableForms(closRegistry));
		}
		if (needsRuntimeSlotNameDispatch(program)) {
			// The shared runtime-slot-name dispatch defuns: the slot-value/slot-boundp
			// call sites lower to them during the backend passes, and the bodies are
			// built HERE, once the registry is complete -- position-independent defuns,
			// appended.
			out.addAll(runtimeSlotValueDefuns(closRegistry));
			out.addAll(runtimeSlotBoundpDefuns(closRegistry));
		}
		if (needsRuntimeSlotSetDispatch(program)) {
			// The write-side twin, separately gated so read-only programs stay
			// byte-identical.
			out.addAll(runtimeSlotValueSetDefuns(closRegistry));
		}
		// The registry is complete and every class constructor is spliced, so this is the
		// final answer: everything injected below (the runtime-error helpers, the print
		// renderer) reads it, and so does every signal site compiled in Pass 2.
		closRegistry.setRoutesConditionReports(mayCreateConditions(out, closRegistry));
		if (runtimeSubtypep) {
			// Injected once the registry is complete; defuns are collected in a
			// position-independent pass, so appending is safe. The data table is a
			// top-level defvar and must run before any top-level subtypep call, so it
			// goes FIRST (after the dispatcher slots above were filled by index).
			out.add(runtimeSubtypepDefun());
			out.addAll(0, subtypepAncestorTableForms(closRegistry));
		}
		if (runtimeTypep) {
			// The defun is position-independent like the subtypep one; its data table
			// is a top-level defvar and must run before any top-level typep call, so
			// it goes FIRST (after the dispatcher slots above were filled by index).
			out.add(runtimeTypepDefun(closRegistry));
			out.addAll(0, typepTagTableForms(closRegistry));
		}
		if (runtimeError) {
			out.addAll(runtimeErrorDefuns(closRegistry, restartMode));
		}
		if (restartMode) {
			// The restart runtime: defuns are position-independent and appended; the
			// two stack globals are top-level defvars and must run before any
			// restart-establishing form, so they go FIRST (after the dispatcher slots
			// above were filled by index). Names the program defines itself win.
			java.util.Set<String> userDefinedNames = new java.util.HashSet<>();
			for (LispVal form : out) {
				if (form instanceof LispCons defun && defun.car() instanceof LispSymbol head
						&& LispNames.DEFUN.equals(head.name()) && defun.cdr() instanceof LispCons nameCons
						&& nameCons.car() instanceof LispSymbol nameSym) {
					userDefinedNames.add(nameSym.name());
				}
			}
			out.addAll(restartRuntimeDefunForms(userDefinedNames));
			out.addAll(0, restartRuntimeGlobalForms());
		}
		if (needsSlotUnboundHelper(program, out)) {
			out.addAll(slotUnboundDefuns());
		}
		// The condition-report renderer, once per program that can build a condition.
		// Emitted here so its class partition is the COMPLETE registry.
		if (closRegistry.routesConditionReports()) {
			out.addAll(conditionReportDefuns(closRegistry));
		}
		// The print-object renderer, once per program that defines a print-object method
		// or routes condition reports. Emitted here so the tag list is the COMPLETE
		// method set, whatever order the defmethods came in.
		if (!printObjectTags(closRegistry).isEmpty() || closRegistry.routesConditionReports()) {
			out.add(printObjectStrDefun(closRegistry));
		}
		// The runtime format renderer, once per program that can reach it. Emitted here
		// so the scan sees the definitions injected above (the condition report renders a
		// simple-condition's format-control THROUGH the renderer), and gated so a program
		// whose every format call has a literal control -- the overwhelming majority --
		// carries none of it.
		out = withFormatRenderer(out);
		// The registry is complete: reserve, in every ancestor of a change-class target,
		// room for the target's slots. %obj-new reads the reservation at backend-compile
		// time, which is after this pass, so widening here reaches every allocation site.
		closRegistry.applyChangeClassCapacities();
		return out;
	}

	/**
	 * Appends the runtime format renderer's definitions when the program can reach it,
	 * and answers the program unchanged when it cannot.
	 *
	 * <p>
	 * Three ways in, and the scan has to answer for all of them BEFORE the expressions
	 * are expanded (that happens per form, much later, and cannot add a top-level defun):
	 * <ul>
	 * <li>a renderer call is already present -- the condition-report runtime injected
	 * just above, or a library form spliced with one;</li>
	 * <li>{@code #'format} is taken as a value, whose wrapper renders through it;</li>
	 * <li>a {@code (format ...)} call whose control the static expansion will decline --
	 * see {@link #formatUsesRenderer};</li>
	 * <li>an {@code error} / {@code warn} / {@code signal} / {@code cerror} call whose
	 * datum is computed and which carries arguments after it -- a datum that is a STRING
	 * at runtime is a format control, and the designator expansion renders it -- see
	 * {@link #signalRendersRuntimeControl}.</li>
	 * </ul>
	 * @param forms the program to scan
	 * @return the program, with the renderer definitions appended when it needs them
	 */
	private static List<LispVal> withFormatRenderer(List<LispVal> forms) {
		for (LispVal form : forms) {
			if (FormatRenderer.isUsed(form) || reachesFormatRenderer(form)) {
				List<LispVal> withRenderer = new java.util.ArrayList<>(forms);
				withRenderer.addAll(FormatRenderer.defuns());
				return withRenderer;
			}
		}
		return forms;
	}

	private static boolean reachesFormatRenderer(LispVal form) {
		if (!(form instanceof LispCons cons)) {
			return false;
		}
		if (cons.car() instanceof LispSymbol head) {
			if (LispNames.FUNCTION.equals(head.name()) && cons.cdr() instanceof LispCons quoted
					&& quoted.car() instanceof LispSymbol named && LispNames.FORMAT.equals(named.name())) {
				return true;
			}
			if (LispNames.FORMAT.equals(head.name()) && formatUsesRenderer(cons)) {
				return true;
			}
			if (signalRendersRuntimeControl(head.name(), cons)) {
				return true;
			}
		}
		return reachesFormatRenderer(cons.car()) || reachesFormatRenderer(cons.cdr());
	}

	/**
	 * Whether the signal designator will lower this call through the runtime renderer:
	 * the datum is neither a literal control string nor a statically known condition type
	 * (a quoted symbol, a literal {@code make-condition}) AND arguments follow it, so the
	 * expansion carries a {@code %fmt-render} of the datum for the case where it is a
	 * string at run time (see
	 * {@link #expandObjectSignal(String, LispVal, ClosRegistry, boolean, LispVal)}). The
	 * scan runs on the SOURCE program, before the designator expansion, so it has to
	 * repeat that case split rather than look for the renderer call.
	 * @param head the call's operator name, qualified or plain
	 * @param cons the call
	 * @return true when the expansion of this call contains a renderer call
	 */
	private static boolean signalRendersRuntimeControl(String head, LispCons cons) {
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(head);
		String member = qn == null ? head : qn.member();
		boolean signalOperator = LispNames.ERROR.equals(member) || LispNames.WARN.equals(member)
				|| LispNames.SIGNAL.equals(member) || LispNames.CERROR.equals(member);
		if (!signalOperator || !cons.isProperList()) {
			return false;
		}
		List<LispVal> parts = cons.toList();
		// (cerror continue-control datum args...) carries its datum one place later.
		int datumIndex = LispNames.CERROR.equals(member) ? 2 : 1;
		return parts.size() > datumIndex + 1 && isRuntimeErrorDatum(parts.get(datumIndex));
	}

	/**
	 * Whether {@link #expandFormat} will lower this call through the runtime renderer:
	 * the control string is not a literal (a variable, a slot read, a function call), or
	 * it is a literal the static parser declines, or it carries a {@code ~?} (which is a
	 * renderer call by definition). The decision is made by running the SAME parser the
	 * expansion runs, so the two cannot answer differently.
	 * @param cons the {@code (format destination control args...)} call
	 * @return true when the expansion of this call contains a renderer call
	 */
	private static boolean formatUsesRenderer(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3) {
			// Malformed: the expansion signals rather than rendering.
			return false;
		}
		LispVal control = parts.get(2);
		if (control instanceof LispCons ctrl && ctrl.car() instanceof LispSymbol ifSym
				&& LispNames.IF.equals(ifSym.name())) {
			List<LispVal> ifParts = ctrl.toList();
			if (ifParts.size() == 4) {
				// Distributed over the branches, so each branch decides for itself.
				return formatUsesRenderer((LispCons) replaceFormatControl(parts, ifParts.get(2)))
						|| formatUsesRenderer((LispCons) replaceFormatControl(parts, ifParts.get(3)));
			}
		}
		if (!(control instanceof LispString literal)) {
			return true;
		}
		List<LispSymbol> temps = new java.util.ArrayList<>();
		for (int i = 3; i < parts.size(); i++) {
			temps.add(new LispSymbol(FORMAT_ARG_VAR + (i - 3)));
		}
		List<FmtOp> parsed;
		try {
			parsed = truncateAtCut(new FmtParser(literal.value()).parseTop(FmtArgs.forTemps(temps)));
		}
		catch (UnsupportedOperationException declined) {
			return true;
		}
		catch (RuntimeException malformed) {
			// A control the parser rejects outright: the expansion signals the same way.
			return false;
		}
		for (FmtOp op : parsed) {
			if (op instanceof FmtString piece && FormatRenderer.isUsed(piece.expr())) {
				return true;
			}
		}
		return false;
	}

	/**
	 * Records the target class of every {@code (change-class x 'name ...)} the program
	 * contains, wherever it sits (the form lives in a body, not at top level, so the
	 * definition walk would never see it).
	 */
	private static void registerChangeClassTargets(List<LispVal> program, ClosRegistry closRegistry) {
		for (LispVal form : program) {
			collectChangeClassTargets(form, closRegistry);
		}
	}

	private static void collectChangeClassTargets(LispVal form, ClosRegistry closRegistry) {
		if (!(form instanceof LispCons cons)) {
			return;
		}
		if (cons.car() instanceof LispSymbol head && LispNames.CHANGE_CLASS.equals(head.name())
				&& cons.isProperList()) {
			List<LispVal> parts = cons.toList();
			if (parts.size() >= 3 && quotedSymbol(parts.get(2)) instanceof LispSymbol target) {
				closRegistry.registerChangeClassTarget(target.name());
			}
		}
		for (LispVal cur = cons; cur instanceof LispCons cell; cur = cell.cdr()) {
			collectChangeClassTargets(cell.car(), closRegistry);
		}
	}

	/**
	 * Whether the program can reach a boundness-checked slot read whose {@code
	 * %slot-unbound} branch the compile path must therefore define. The generated
	 * accessors that call it are already in the OUTPUT, but a {@code slot-value} /
	 * {@code with-slots} inside a body is expanded much later, by the ExprCompilers, so
	 * the SOURCE has to be consulted for those.
	 */
	private static boolean needsSlotUnboundHelper(List<LispVal> program, List<LispVal> out) {
		return readsSlots(program) || out.stream()
			.anyMatch(
					f -> usesSymbol(f, LispNames.SLOT_READ_INTERNAL) || usesSymbol(f, LispNames.SLOT_BOUND_P_INTERNAL));
	}

	/**
	 * Whether any form mentions an operator whose expansion calls the out-of-line
	 * boundness helpers -- a checked read ({@code slot-value}, {@code with-slots}) or a
	 * boundness test ({@code slot-boundp}).
	 */
	private static boolean readsSlots(List<LispVal> program) {
		return program.stream()
			.anyMatch(f -> usesSymbol(f, LispNames.SLOT_VALUE) || usesSymbol(f, LispNames.WITH_SLOTS)
					|| usesSymbol(f, LispNames.SLOT_BOUNDP));
	}

	/**
	 * Adds one generated definition to the compile-path output: a {@code defmethod} form
	 * (a user one, or a reader/writer method synthesized by {@link #expandDefclass}) is
	 * expanded into its method-body defun and reserves a dispatcher slot for its generic
	 * (filled after the whole program is registered); any other form is added verbatim.
	 */
	private static void addExpandedDefinition(LispVal form, List<LispVal> out, ClosRegistry closRegistry,
			java.util.Map<Integer, String> dispatcherSlots, java.util.Set<String> placedDispatchers) {
		if (!isNamedForm(form, LispNames.DEFMETHOD)) {
			out.add(form);
			return;
		}
		LispVal expandedMethod = expandDefmethod((LispCons) form, closRegistry);
		if (isNamedForm(expandedMethod, LispNames.PROGN) && expandedMethod instanceof LispCons prognCons) {
			// A method expansion may carry a synthesized companion defun (the
			// initialize-instance default primary); splice so Pass 1 collects both.
			List<LispVal> members = prognCons.toList();
			out.addAll(members.subList(1, members.size()));
		}
		else {
			out.add(expandedMethod);
		}
		String generic = ClosRegistry.normalize(((LispSymbol) ((LispCons) form).toList().get(1)).name());
		if (placedDispatchers.add(generic)) {
			dispatcherSlots.put(out.size(), generic);
			out.add(LispNil.INSTANCE);
		}
		// A method expansion may REGISTER a further generic as a side effect (the
		// instance-initialization protocol's shared-initialize), which needs a dispatcher
		// slot of its own. Reserving it here is safe whatever the definition order: the
		// dispatchers are generated after the whole walk, from the complete method set.
		for (ClosRegistry.GenericInfo info : closRegistry.generics().values()) {
			String name = ClosRegistry.normalize(info.name());
			if (placedDispatchers.add(name)) {
				dispatcherSlots.put(out.size(), name);
				out.add(LispNil.INSTANCE);
			}
		}
	}

	private static boolean isSetfFunctionDefun(LispVal form) {
		return form instanceof LispCons cons && cons.car() instanceof LispSymbol op && LispNames.DEFUN.equals(op.name())
				&& cons.cdr() instanceof LispCons rest && LambdaLists.setfFunctionPlaceName(rest.car()) != null;
	}

	/**
	 * Whether the form is a top-level {@code let}/{@code let*} carrying a
	 * {@code defmethod} directly in its body -- the closure-over-let method idiom.
	 */
	private static boolean isLetWithNestedDefmethod(LispVal form) {
		if (!(form instanceof LispCons cons) || !(cons.car() instanceof LispSymbol op)
				|| (!LispNames.LET.equals(op.name()) && !LispNames.LET_STAR.equals(op.name()))
				|| !cons.isProperList()) {
			return false;
		}
		List<LispVal> parts = cons.toList();
		for (int i = 2; i < parts.size(); i++) {
			if (MopEvalCapture.definesMethods(parts.get(i))) {
				return true;
			}
		}
		return false;
	}

	/**
	 * Expands the {@code defmethod} forms in a top-level {@code let}/{@code let*} body in
	 * place: each is registered with the registry and replaced by its method-body defun
	 * (which, being nested, compiles to a global-closure {@code setq}); the rebuilt let
	 * is added to {@code out} and each generic's dispatcher slot is reserved at top level
	 * after it. A defmethod that is a DIRECT body member has its expansion progn spliced
	 * into the body (cl-ppcre's closure-over-let idiom, kept byte-identical); one nested
	 * DEEPER -- under the {@code labels}/{@code when} structure of a captured
	 * {@code build-dao-methods} splice (see {@link MopEvalCapture}) -- is rewritten in
	 * place, its expansion progn standing where the defmethod stood. A method under a
	 * conditional registers unconditionally (dispatch is static); when the guard is false
	 * at run time its body global is never assigned, so calling it fails on the
	 * unassigned global rather than as no-applicable-method -- the static subset's
	 * documented divergence.
	 */
	private static void expandLetNestedDefmethods(LispCons letForm, ClosRegistry closRegistry, List<LispVal> out,
			java.util.Map<Integer, String> dispatcherSlots, java.util.Set<String> placedDispatchers,
			java.util.Map<String, Integer> structAccessors) {
		List<LispVal> parts = letForm.toList();
		List<LispVal> rebuilt = new java.util.ArrayList<>(parts.subList(0, 2));
		List<String> generics = new java.util.ArrayList<>();
		for (LispVal rawBodyForm : parts.subList(2, parts.size())) {
			if (!isNamedForm(rawBodyForm, LispNames.DEFMETHOD)) {
				rebuilt.add(rewriteNestedDefmethods(rawBodyForm, closRegistry, generics, structAccessors));
				continue;
			}
			LispCons bodyForm = normalizeSetfMethodForm((LispCons) rawBodyForm, structAccessors);
			LispVal expandedMethod = expandDefmethod(bodyForm, closRegistry);
			if (isNamedForm(expandedMethod, LispNames.PROGN) && expandedMethod instanceof LispCons prognCons) {
				List<LispVal> members = prognCons.toList();
				rebuilt.addAll(members.subList(1, members.size()));
			}
			else {
				rebuilt.add(expandedMethod);
			}
			generics.add(ClosRegistry.normalize(((LispSymbol) bodyForm.toList().get(1)).name()));
		}
		out.add(listToCons(rebuilt));
		for (String generic : generics) {
			if (placedDispatchers.add(generic)) {
				dispatcherSlots.put(out.size(), generic);
				out.add(LispNil.INSTANCE);
			}
		}
	}

	// Rewrites every defmethod nested below a top-level let body member in place
	// (quoted data skipped): registered like a top-level defmethod, replaced by its
	// expansion progn -- an expression-position form, so no splicing is possible or
	// needed. The method-body defun inside compiles to a global-closure setq exactly
	// like the direct-member case.
	private static LispVal rewriteNestedDefmethods(LispVal form, ClosRegistry closRegistry, List<String> generics,
			java.util.Map<String, Integer> structAccessors) {
		if (!(form instanceof LispCons cons)) {
			return form;
		}
		if (cons.car() instanceof LispSymbol op) {
			String member = memberOf(op.name());
			if (LispNames.QUOTE.equals(member)) {
				return form;
			}
			if (LispNames.DEFMETHOD.equals(member) && cons.isProperList()) {
				LispCons normalized = normalizeSetfMethodForm(cons, structAccessors);
				LispVal expandedMethod = expandDefmethod(normalized, closRegistry);
				generics.add(ClosRegistry.normalize(((LispSymbol) normalized.toList().get(1)).name()));
				return expandedMethod;
			}
		}
		return new LispCons(rewriteNestedDefmethods(cons.car(), closRegistry, generics, structAccessors),
				rewriteNestedDefmethods(cons.cdr(), closRegistry, generics, structAccessors));
	}

	private static LispVal rewriteSetfFunctionDefun(LispCons cons, java.util.Map<String, Integer> structAccessors) {
		List<LispVal> parts = cons.toList();
		LispSymbol place = java.util.Objects.requireNonNull(LambdaLists.setfFunctionPlaceName(parts.get(1)));
		structAccessors.put(place.name(), SETF_FUNCTION_MARKER);
		List<LispVal> rewritten = new java.util.ArrayList<>(parts);
		rewritten.set(1, new LispSymbol(setfFunctionName(place.name())));
		return listToCons(rewritten);
	}

	/**
	 * Normalizes a {@code defmethod}/{@code defgeneric} whose function name is the
	 * {@code (setf name)} form onto the {@code %setf-} writer-generic convention the
	 * {@code defclass} {@code :accessor} writers already use: the definition is rewritten
	 * onto the mangled symbol and the place is registered in {@code structAccessors}, so
	 * {@code (setf (name args...) v)} funcalls the writer dispatcher (CL setf-function
	 * argument order, new value first) and a user setf method MERGES with any
	 * accessor-generated writer method on the same generic instead of shadowing it. A
	 * plain symbol name passes through untouched. The {@code (defun (setf name) ...)}
	 * twin is {@link #rewriteSetfFunctionDefun}.
	 * @param cons the defmethod/defgeneric form
	 * @param structAccessors mutated: the place name maps to the setf-function marker
	 * @return the form with a symbol function name
	 */
	public static LispCons normalizeSetfMethodForm(LispCons cons, java.util.Map<String, Integer> structAccessors) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			return cons;
		}
		LispSymbol place = LambdaLists.setfFunctionPlaceName(parts.get(1));
		if (place == null) {
			return cons;
		}
		structAccessors.put(place.name(), SETF_FUNCTION_MARKER);
		List<LispVal> rewritten = new java.util.ArrayList<>(parts);
		rewritten.set(1, new LispSymbol(setfFunctionName(place.name())));
		return (LispCons) listToCons(rewritten);
	}

	private static boolean isClosDefinitionForm(LispVal form) {
		return isNamedForm(form, LispNames.DEFCLASS) || isNamedForm(form, LispNames.DEFGENERIC)
				|| isNamedForm(form, LispNames.DEFMETHOD) || isNamedForm(form, LispNames.DEFINE_CONDITION);
	}

	/**
	 * Whether the program writes the function namespace through a
	 * {@code (setf (symbol-function ...))} / {@code (setf (fdefinition ...))} place
	 * (anywhere in the tree, quoted data skipped). Forces the eval runtime's function
	 * namespace ({@code _fenv}) onto the compile paths, and gates the setf-only-alias
	 * forwarder injection in {@link #expandTopLevelDefinitions}.
	 * @param program the top-level forms
	 * @return true when such a place is written
	 */
	public static boolean usesSymbolFunctionWrite(List<LispVal> program) {
		return program.stream().anyMatch(LispMacroExpander::containsSymbolFunctionWrite);
	}

	private static boolean containsSymbolFunctionWrite(LispVal form) {
		if (!(form instanceof LispCons cons)) {
			return false;
		}
		if (cons.car() instanceof LispSymbol op) {
			String member = memberOf(op.name());
			if (LispNames.QUOTE.equals(member)) {
				return false;
			}
			if (LispNames.SETF.equals(member) && cons.isProperList()) {
				List<LispVal> parts = cons.toList();
				for (int i = 1; i + 1 < parts.size(); i += 2) {
					if (isSymbolFunctionPlace(parts.get(i))) {
						return true;
					}
				}
			}
		}
		return containsSymbolFunctionWrite(cons.car()) || containsSymbolFunctionWrite(cons.cdr());
	}

	private static boolean isSymbolFunctionPlace(LispVal place) {
		if (!(place instanceof LispCons cons) || !(cons.car() instanceof LispSymbol head)) {
			return false;
		}
		String member = memberOf(head.name());
		return LispNames.SYMBOL_FUNCTION.equals(member) || LispNames.FDEFINITION.equals(member);
	}

	/**
	 * The literal names the program binds through a {@code (setf (symbol-function 'n)
	 * ...)}-family place WITHOUT ever defining them as a defun or a generic -- the alias
	 * idiom ({@code (setf (symbol-function 'write8-le) #'write8)}). Each gets a forwarder
	 * defun so DIRECT call sites (and {@code #'name}) reach the runtime binding: the
	 * forwarder applies {@code %fenv-function}, which probes the runtime function
	 * namespace ONLY -- probing the compiled registry there would find the forwarder
	 * itself -- and signals {@code The function X is undefined} when called before the
	 * setf ran, which is what CL says for a call before the assignment.
	 */
	private static List<String> setfOnlyFunctionAliasNames(List<LispVal> program, ClosRegistry closRegistry) {
		java.util.LinkedHashSet<String> names = new java.util.LinkedHashSet<>();
		for (LispVal form : program) {
			collectSetfSymbolFunctionNames(form, names);
		}
		if (names.isEmpty()) {
			return List.of();
		}
		for (LispVal form : program) {
			if (form instanceof LispCons cons && cons.car() instanceof LispSymbol op
					&& LispNames.DEFUN.equals(memberOf(op.name())) && cons.cdr() instanceof LispCons rest
					&& rest.car() instanceof LispSymbol nameSym) {
				names.remove(nameSym.name());
			}
		}
		names.removeIf(name -> closRegistry.findGeneric(name) != null);
		return List.copyOf(names);
	}

	private static void collectSetfSymbolFunctionNames(LispVal form, java.util.Set<String> names) {
		if (!(form instanceof LispCons cons)) {
			return;
		}
		if (cons.car() instanceof LispSymbol op) {
			String member = memberOf(op.name());
			if (LispNames.QUOTE.equals(member)) {
				return;
			}
			if (LispNames.SETF.equals(member) && cons.isProperList()) {
				List<LispVal> parts = cons.toList();
				for (int i = 1; i + 1 < parts.size(); i += 2) {
					if (isSymbolFunctionPlace(parts.get(i)) && parts.get(i) instanceof LispCons place
							&& place.isProperList() && place.toList().size() > 1
							&& quotedSymbol(place.toList().get(1)) instanceof LispSymbol nameSym) {
						names.add(nameSym.name());
					}
				}
			}
		}
		collectSetfSymbolFunctionNames(cons.car(), names);
		collectSetfSymbolFunctionNames(cons.cdr(), names);
	}

	/** The forwarder defuns of {@link #setfOnlyFunctionAliasNames}. */
	private static List<LispVal> symbolFunctionForwarderDefuns(List<String> names) {
		List<LispVal> defuns = new java.util.ArrayList<>();
		LispSymbol argsVar = new LispSymbol("%SFW-ARGS");
		for (String name : names) {
			defuns.add(listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(name),
					listToCons(List.of(new LispSymbol("&REST"), argsVar)),
					listToCons(List.of(new LispSymbol(LispNames.APPLY),
							listToCons(List.of(new LispSymbol(LispNames.FENV_FUNCTION_INTERNAL), quoteOf(name))),
							argsVar)))));
		}
		return defuns;
	}

	private static boolean isNamedForm(LispVal form, String name) {
		return form instanceof LispCons cons && cons.car() instanceof LispSymbol sym && name.equals(sym.name());
	}

	/**
	 * Expands (format destination control-string args...). The control string must be a
	 * literal string and the destination must be the literal {@code t} (print to standard
	 * output, return nil), {@code nil} (return the formatted string), or a stream
	 * expression (build the string like {@code nil}, write it with one
	 * {@code write-string} call, return nil). Supported directives: {@code ~a}/{@code ~A}
	 * (princ), {@code ~s}/{@code ~S} (prin1), {@code ~d}/{@code ~D} (decimal, with
	 * {@code :} comma grouping and {@code @} sign), {@code ~f}/{@code ~F} (fixed-decimal
	 * float), {@code ~e}/{@code ~E} (exponential float), {@code ~$} (monetary),
	 * {@code ~%} (newline), {@code ~&} (fresh-line) and {@code ~~} (a literal tilde).
	 * Directives accept prefix parameters (numbers, {@code 'c}, {@code v}, {@code #}) and
	 * the {@code :}/{@code @} modifiers; value directives that need
	 * padding/grouping/rounding expand into the {@code %fmt-*} runtime helpers.
	 *
	 * <pre>
	 * (format t "Hello ~a!~%" name) ->
	 * (let ((__format_arg0 name))
	 *   (princ "Hello ")
	 *   (princ __format_arg0)
	 *   (princ "!")
	 *   (terpri)
	 *   nil)
	 *
	 * (format nil "Hello ~a!" name) ->
	 * (let ((__format_arg0 name))
	 *   (%string-concat (%string-concat "Hello " (princ-to-string __format_arg0)) "!"))
	 * </pre>
	 *
	 * All arguments are bound to temporaries up front so they are evaluated left to right
	 * before any output, matching Common Lisp's function-call semantics.
	 * @param cons the format expression
	 * @return the expanded expression
	 */
	public static LispVal expandFormat(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3) {
			throw new IllegalArgumentException("format expects a destination and a control string");
		}
		boolean toString;
		LispVal streamDest = null;
		if (parts.get(1) instanceof LispTrue) {
			toString = false;
		}
		else if (parts.get(1) instanceof LispNil) {
			toString = true;
		}
		else {
			// A stream destination: build the string like format nil, then write it to
			// the
			// stream in one (write-string ...) call and return nil.
			toString = true;
			streamDest = parts.get(1);
		}
		// A conditional control string with per-branch controls: distribute the format
		// over the branches so each compiles with a literal control -- cl-who's
		// escape-char does (format nil (if (eq *html-mode* :xml) "&#x~x;" "&#~d;") code).
		if (parts.get(2) instanceof LispCons ctrl && ctrl.car() instanceof LispSymbol ifSym
				&& LispNames.IF.equals(ifSym.name())) {
			List<LispVal> ifParts = ctrl.toList();
			if (ifParts.size() == 4) {
				LispVal thenFmt = expandFormat((LispCons) replaceFormatControl(parts, ifParts.get(2)));
				LispVal elseFmt = expandFormat((LispCons) replaceFormatControl(parts, ifParts.get(3)));
				return listToCons(List.of(new LispSymbol(LispNames.IF), ifParts.get(1), thenFmt, elseFmt));
			}
		}
		if (!(parts.get(2) instanceof LispString control)) {
			// A computed (non-literal) control string cannot be lowered to string pieces
			// at compile time; fall back to the inline runtime renderer.
			return runtimeRenderFallback(parts, toString, streamDest);
		}
		List<LispVal> args = parts.subList(3, parts.size());
		List<LispVal> bindings = new java.util.ArrayList<>();
		List<LispSymbol> argSyms = new java.util.ArrayList<>();
		for (int i = 0; i < args.size(); i++) {
			LispSymbol g = new LispSymbol(FORMAT_ARG_VAR + i);
			argSyms.add(g);
			bindings.add(listToCons(List.of(g, args.get(i))));
		}
		List<FmtOp> parsed;
		try {
			parsed = truncateAtCut(new FmtParser(control.value()).parseTop(FmtArgs.forTemps(argSyms)));
		}
		catch (UnsupportedOperationException unsupportedDirective) {
			// A directive shape the static expansion cannot lower (an uneven ~[
			// conditional, ~@? ...) falls back to the runtime renderer like a computed
			// control, so a library carrying it on a cold branch still compiles
			// (cl-ppcre's print-symbol-info); the renderer's directive subset applies.
			return runtimeRenderFallback(parts, toString, streamDest);
		}
		List<LispVal> forms = toString ? opsToPieces(parsed) : formatOutputForms(parsed);
		if (toString) {
			// Fold the pieces into nested %string-concat calls (left-associative).
			LispVal result = forms.isEmpty() ? new LispString("") : forms.get(0);
			for (int i = 1; i < forms.size(); i++) {
				result = listToCons(List.of(new LispSymbol(LispNames.STRING_CONCAT), result, forms.get(i)));
			}
			if (streamDest != null) {
				// A computed destination: dispatched at RUN TIME, because nil there is
				// not a stream but the "return the string" destination. The stream temp
				// is bound first so the destination is evaluated before the arguments.
				LispSymbol streamVar = new LispSymbol(FORMAT_STREAM_VAR);
				bindings.add(0, listToCons(List.of(streamVar, streamDest)));
				forms = new java.util.ArrayList<>(List.of(formatDestinationDispatch(result, streamVar)));
			}
			else {
				forms = new java.util.ArrayList<>(List.of(result));
			}
		}
		else {
			// format t returns nil
			forms = new java.util.ArrayList<>(forms);
			forms.add(LispNil.INSTANCE);
		}
		if (bindings.isEmpty()) {
			return forms.size() == 1 ? forms.get(0) : makeProgn(forms);
		}
		List<LispVal> letParts = new java.util.ArrayList<>();
		letParts.add(new LispSymbol(LispNames.LET));
		letParts.add(listToCons(bindings));
		letParts.addAll(forms);
		return listToCons(letParts);
	}

	// The runtime-renderer fallback for a control the static expansion cannot lower: a
	// computed (non-literal) control string (cl-who's escape-string binds its control to
	// a local variable) or a literal one using a directive shape outside the static
	// subset. It calls the shared %fmt-render defuns (FormatRenderer), which understand
	// the whole directive set -- the same renderer #'format and a condition report reach.
	private static LispVal runtimeRenderFallback(List<LispVal> parts, boolean toString, @Nullable LispVal streamDest) {
		List<LispVal> fargs = parts.subList(3, parts.size());
		List<LispVal> listCall = new java.util.ArrayList<>();
		listCall.add(new LispSymbol(LispNames.LIST));
		listCall.addAll(fargs);
		LispVal rendered = FormatRenderer.call(parts.get(2), fargs.isEmpty() ? LispNil.INSTANCE : listToCons(listCall));
		if (streamDest != null) {
			LispSymbol streamVar = new LispSymbol(FORMAT_STREAM_VAR);
			return makeLet(streamVar.name(), streamDest, formatDestinationDispatch(rendered, streamVar));
		}
		if (toString) {
			return rendered;
		}
		return makeProgn(List.of(callOf(LispNames.PRINC, rendered), LispNil.INSTANCE));
	}

	// Rebuilds a (format dest control args...) call with a different control expression,
	// used to distribute format over a conditional control string.
	private static LispVal replaceFormatControl(List<LispVal> parts, LispVal newControl) {
		List<LispVal> rebuilt = new java.util.ArrayList<>(parts);
		rebuilt.set(2, newControl);
		return listToCons(rebuilt);
	}

	private static final String FORMAT_ARG_VAR = "__format_arg";

	private static final String FORMAT_STREAM_VAR = "__format_stream";

	/**
	 * The run-time dispatch on a {@code format} destination that is neither the literal
	 * {@code nil} nor the literal {@code t}: {@code (if dest (progn (write-string STR
	 * dest) nil) STR)}, with a {@code t} destination writing to the default stream.
	 *
	 * <p>
	 * It has to be a run-time test. {@code nil} as a {@code format} destination does not
	 * name a stream -- it is the "build and return the string" destination -- so a call
	 * whose destination is a VARIABLE cannot be lowered to a write: quri's
	 * {@code (render-uri uri &optional stream)} passes its optional straight through, and
	 * lowering the nil case to a write printed the URI to stdout and returned nil where
	 * CL returns the string. The rendered string is bound to a temp so it is built once
	 * whichever branch consumes it.
	 * @param result the form that builds the rendered string
	 * @param streamVar the symbol already bound to the evaluated destination
	 * @return the dispatching form
	 */
	private static LispVal formatDestinationDispatch(LispVal result, LispSymbol streamVar) {
		LispSymbol resultVar = new LispSymbol("__format_result");
		LispVal writeToStream = makeProgn(List
			.of(listToCons(List.of(new LispSymbol(LispNames.WRITE_STRING), resultVar, streamVar)), LispNil.INSTANCE));
		// A t destination is *standard-output*: the one-argument write-string reads it at
		// call time, so a surrounding with-output-to-string capture still applies.
		LispVal writeToDefault = makeProgn(
				List.of(listToCons(List.of(new LispSymbol(LispNames.WRITE_STRING), resultVar)), LispNil.INSTANCE));
		LispVal nonNil = listToCons(List.of(new LispSymbol(LispNames.IF),
				listToCons(List.of(new LispSymbol(LispNames.EQL), streamVar, LispTrue.INSTANCE)), writeToDefault,
				writeToStream));
		return makeLet(resultVar.name(), result,
				listToCons(List.of(new LispSymbol(LispNames.IF), streamVar, nonNil, resultVar)));
	}

	/**
	 * A parsed unit of a format control string: either a literal text run, a
	 * string-valued expression to emit, a run of newlines, or a fresh-line.
	 */
	private sealed interface FmtOp permits FmtLiteral, FmtString, FmtNewline, FmtFreshLine, FmtCut {

	}

	private record FmtLiteral(String text) implements FmtOp {
	}

	private record FmtString(LispVal expr) implements FmtOp {
	}

	private record FmtNewline(int count) implements FmtOp {
	}

	private record FmtFreshLine(int count) implements FmtOp {
	}

	/**
	 * A {@code ~^} escape point. Inside a {@code ~{ ... ~}} body (a runtime item source)
	 * {@code consumed} is the number of items the body has consumed so far: at run time
	 * the escape fires when the list holds no element beyond them, skipping the rest of
	 * the body and (for a flat iteration) ending the loop. Against a static source the
	 * argument count is known at expansion time, so a {@code ~^} with arguments left is
	 * dropped where it is parsed and only the firing case is recorded (as a terminating
	 * cut that truncates the remaining ops).
	 */
	private record FmtCut(int consumed) implements FmtOp {
	}

	/**
	 * A cursor over the arguments a format control string consumes. At the top level the
	 * arguments are the pre-bound {@code __format_arg} temporaries ("static" source, with
	 * a known count); inside a {@code ~{ ... ~}} iteration body they are per-iteration
	 * item temporaries allocated on demand and later bound to successive list elements
	 * ("runtime" source, with an unknown count). Conditional clauses parse against a
	 * {@link #branch()} of the cursor so each clause sees the same starting position.
	 */
	private static final class FmtArgs {

		private final List<LispSymbol> syms;

		@Nullable private final String runtimePrefix;

		private int index;

		/**
		 * Set when a {@code ~^} fired against this (static) source: the remaining
		 * directives are parsed for syntax but their ops are truncated, so an exhausted
		 * cursor hands out throwaway temporaries instead of failing the parse.
		 */
		private boolean cutTerminated;

		private FmtArgs(List<LispSymbol> syms, @Nullable String runtimePrefix, int index) {
			this.syms = syms;
			this.runtimePrefix = runtimePrefix;
			this.index = index;
		}

		static FmtArgs forTemps(List<LispSymbol> temps) {
			return new FmtArgs(temps, null, 0);
		}

		static FmtArgs forRuntimeItems(String prefix) {
			return new FmtArgs(new java.util.ArrayList<>(), prefix, 0);
		}

		boolean isStatic() {
			return this.runtimePrefix == null;
		}

		LispSymbol next(char directive) {
			if (this.runtimePrefix == null && this.index >= this.syms.size()) {
				if (this.cutTerminated) {
					// Everything after the fired ~^ is truncated; this temp is never
					// emitted, it only keeps the syntax-parse of the remainder alive.
					return new LispSymbol("__fmtcut_dropped");
				}
				throw new IllegalArgumentException("format: not enough arguments for directive ~" + directive);
			}
			while (this.syms.size() <= this.index) {
				this.syms.add(new LispSymbol(this.runtimePrefix + this.syms.size()));
			}
			return this.syms.get(this.index++);
		}

		int position() {
			return this.index;
		}

		void move(int delta, char directive) {
			int to = this.index + delta;
			if (to < 0 || (this.runtimePrefix == null && to > this.syms.size())) {
				throw new IllegalArgumentException("format: ~" + directive + " moves outside the argument list");
			}
			this.index = to;
		}

		int remaining(char directive) {
			if (this.runtimePrefix != null) {
				throw new UnsupportedOperationException(
						"format: " + directive + " is not supported inside a ~{ iteration body");
			}
			return this.syms.size() - this.index;
		}

		FmtArgs branch() {
			FmtArgs branched = new FmtArgs(this.syms, this.runtimePrefix, this.index);
			branched.cutTerminated = this.cutTerminated;
			return branched;
		}

		FmtArgs branchAt(int index) {
			FmtArgs branched = new FmtArgs(this.syms, this.runtimePrefix, index);
			branched.cutTerminated = this.cutTerminated;
			return branched;
		}

		void adoptIndex(int index) {
			this.index = index;
		}

		/** Every item temporary this (runtime) source handed out, in index order. */
		List<LispSymbol> items() {
			return this.syms;
		}

	}

	/** A parsed conditional clause: its ops and the argument position it ended at. */
	private record FmtClause(List<FmtOp> ops, int end, boolean isDefault) {
	}

	/**
	 * Recursive-descent parser for a format control string. Parses directives into
	 * {@link FmtOp}s, consuming format arguments (left to right) through a
	 * {@link FmtArgs} cursor as it encounters value directives and {@code v}/{@code #}
	 * prefix parameters. Composite directives (case conversion {@code ~(...~)},
	 * conditionals {@code ~[...~]}, iteration {@code ~{...~}}) parse their bodies
	 * recursively and collapse to a single string-valued {@link FmtString}.
	 */
	private static final class FmtParser {

		/**
		 * How many argument-divergent {@code ~[} remainders one control string may
		 * expand. The fan-out is multiplicative (each divergent conditional re-parses
		 * everything after it once per clause), so this bounds a pathological control
		 * string; real ones carry one or two.
		 */
		private static final int MAX_REMAINDER_EXPANSIONS = 16;

		private final String src;

		private int pos;

		private int gensym;

		/** The terminator directive that ended the last {@link #parseOps} call. */
		private char stopChar;

		/** Whether that terminator carried a {@code :} modifier (for {@code ~:;}). */
		private boolean stopColon;

		/**
		 * Set by {@link #clauseExprs} when an argument-divergent {@code ~[} swallowed the
		 * remainder of the enclosing {@link #parseOps} loop, which must therefore return
		 * at once instead of parsing that remainder a second time.
		 */
		private boolean remainderTaken;

		/** How many times a remainder has been re-parsed, to bound the fan-out. */
		private int remainderExpansions;

		FmtParser(String src) {
			this.src = src;
		}

		List<FmtOp> parseTop(FmtArgs args) {
			return parseOps(args, "");
		}

		/**
		 * Parses ops until the end of the control string (when {@code stoppers} is empty)
		 * or until one of the {@code stoppers} directives ({@code ~;}, {@code ~]},
		 * {@code ~&#125;}, {@code ~)}) is read, recording it in {@link #stopChar}/
		 * {@link #stopColon}.
		 */
		private List<FmtOp> parseOps(FmtArgs args, String stoppers) {
			List<FmtOp> ops = new java.util.ArrayList<>();
			StringBuilder lit = new StringBuilder();
			this.stopChar = 0;
			this.stopColon = false;
			int n = this.src.length();
			while (this.pos < n) {
				char c = this.src.charAt(this.pos);
				if (c != '~') {
					lit.append(c);
					this.pos++;
					continue;
				}
				this.pos++; // skip '~'
				List<LispVal> params = parseParams(args);
				boolean colon = false;
				boolean at = false;
				while (this.pos < n && (this.src.charAt(this.pos) == ':' || this.src.charAt(this.pos) == '@')) {
					if (this.src.charAt(this.pos) == ':') {
						colon = true;
					}
					else {
						at = true;
					}
					this.pos++;
				}
				if (this.pos >= n) {
					throw new IllegalArgumentException("format: control string ends with ~");
				}
				char directive = this.src.charAt(this.pos++);
				if (stoppers.indexOf(directive) >= 0) {
					flushFmtLiteral(lit, ops);
					this.stopChar = directive;
					this.stopColon = colon;
					return ops;
				}
				dispatch(directive, params, colon, at, args, ops, lit, stoppers);
				if (this.remainderTaken) {
					// An argument-divergent ~[ re-parsed everything after itself once per
					// clause; stopChar/stopColon are already those of that tail parse.
					this.remainderTaken = false;
					return ops;
				}
			}
			if (!stoppers.isEmpty()) {
				throw new IllegalArgumentException(
						"format: missing ~" + stoppers.charAt(stoppers.length() - 1) + " in control string");
			}
			flushFmtLiteral(lit, ops);
			return ops;
		}

		/** Parses the comma-separated prefix parameters (numbers, 'char, v, #). */
		private List<LispVal> parseParams(FmtArgs args) {
			List<LispVal> params = new java.util.ArrayList<>();
			int n = this.src.length();
			if (this.pos >= n || (!isParamStart(this.src.charAt(this.pos)) && this.src.charAt(this.pos) != ',')) {
				return params;
			}
			while (true) {
				char p = (this.pos < n) ? this.src.charAt(this.pos) : '\0';
				if (p == '\'') {
					if (this.pos + 1 >= n) {
						throw new IllegalArgumentException("format: ~' prefix with no character");
					}
					params.add(new LispInteger(this.src.charAt(this.pos + 1)));
					this.pos += 2;
				}
				else if (p == 'v' || p == 'V') {
					params.add(args.next('v'));
					this.pos++;
				}
				else if (p == '#') {
					params.add(new LispInteger(args.remaining('#')));
					this.pos++;
				}
				else if (p == '-' || Character.isDigit(p)) {
					int start = this.pos;
					if (p == '-') {
						this.pos++;
					}
					while (this.pos < n && Character.isDigit(this.src.charAt(this.pos))) {
						this.pos++;
					}
					params.add(new LispInteger(Long.parseLong(this.src.substring(start, this.pos))));
				}
				else {
					params.add(LispNil.INSTANCE); // omitted parameter slot
				}
				if (this.pos < n && this.src.charAt(this.pos) == ',') {
					this.pos++;
					continue;
				}
				break;
			}
			return params;
		}

		private void dispatch(char directive, List<LispVal> params, boolean colon, boolean at, FmtArgs args,
				List<FmtOp> ops, StringBuilder lit, String stoppers) {
			switch (Character.toLowerCase(directive)) {
				case '~' -> {
					int count = fmtCount(params, 0, 1, directive);
					lit.append("~".repeat(count));
				}
				// ~<newline> (line continuation): default ignores the newline and the
				// following non-newline whitespace; ~@<newline> keeps the newline but
				// still ignores the whitespace; ~:<newline> keeps the whitespace.
				case '\n', '\r' -> {
					if (at) {
						lit.append('\n');
					}
					if (!colon) {
						int n = this.src.length();
						while (this.pos < n
								&& (this.src.charAt(this.pos) == ' ' || this.src.charAt(this.pos) == '\t')) {
							this.pos++;
						}
					}
				}
				case '%' -> {
					flushFmtLiteral(lit, ops);
					ops.add(new FmtNewline(fmtCount(params, 0, 1, directive)));
				}
				case '&' -> {
					flushFmtLiteral(lit, ops);
					ops.add(new FmtFreshLine(fmtCount(params, 0, 1, directive)));
				}
				case 'a', 's' -> {
					flushFmtLiteral(lit, ops);
					LispVal arg = args.next(directive);
					String op = (Character.toLowerCase(directive) == 's') ? LispNames.PRIN1_TO_STRING
							: LispNames.PRINC_TO_STRING;
					LispVal base = fmtCall(op, arg);
					if (colon) {
						base = makeIf(arg, base, new LispString("()"));
					}
					if (fmtHasParam(params, 0)) {
						base = padExpr(base, fmtParam(params, 0), fmtPadChar(params, 3, ' '), at);
					}
					ops.add(new FmtString(base));
				}
				case 'd' -> {
					flushFmtLiteral(lit, ops);
					LispVal arg = args.next(directive);
					LispVal base = (colon || at)
							? decimalExpr(arg, colon, fmtCommaChar(params, 2), fmtInterval(params, 3), at)
							: fmtCall(LispNames.PRINC_TO_STRING, arg);
					if (fmtHasParam(params, 0)) {
						base = padExpr(base, fmtParam(params, 0), fmtPadChar(params, 1, ' '), true);
					}
					ops.add(new FmtString(base));
				}
				case 'x', 'o', 'b' -> {
					flushFmtLiteral(lit, ops);
					LispVal arg = args.next(directive);
					int base = switch (Character.toLowerCase(directive)) {
						case 'x' -> 16;
						case 'o' -> 8;
						default -> 2;
					};
					LispVal digits = radixIntegerExpr(arg, new LispInteger(base), colon, fmtCommaChar(params, 2),
							fmtInterval(params, 3), at);
					if (fmtHasParam(params, 0)) {
						digits = padExpr(digits, fmtParam(params, 0), fmtPadChar(params, 1, ' '), true);
					}
					ops.add(new FmtString(digits));
				}
				case 'r' -> {
					flushFmtLiteral(lit, ops);
					if (!fmtHasParam(params, 0)) {
						throw new UnsupportedOperationException(
								"format: ~r requires a radix parameter (English cardinal/ordinal output is not supported)");
					}
					LispVal arg = args.next(directive);
					LispVal digits = radixIntegerExpr(arg, fmtParam(params, 0), colon, fmtCommaChar(params, 3),
							fmtInterval(params, 4), at);
					if (fmtHasParam(params, 1)) {
						digits = padExpr(digits, fmtParam(params, 1), fmtPadChar(params, 2, ' '), true);
					}
					ops.add(new FmtString(digits));
				}
				case 'c' -> {
					flushFmtLiteral(lit, ops);
					LispVal arg = args.next(directive);
					LispVal base;
					if (at) {
						base = fmtCall(LispNames.PRIN1_TO_STRING, arg);
					}
					else if (colon) {
						// prin1 of a character is "#\name"; dropping the #\ prefix
						// yields the glyph for graphic characters and the standard
						// name (Newline, Space, ...) for non-graphic ones.
						base = fmtCall(LispNames.SUBSEQ, fmtCall(LispNames.PRIN1_TO_STRING, arg), new LispInteger(2));
					}
					else {
						base = fmtCall(LispNames.PRINC_TO_STRING, arg);
					}
					ops.add(new FmtString(base));
				}
				case 'f' -> {
					flushFmtLiteral(lit, ops);
					LispVal arg = args.next(directive);
					int scale = fmtHasParam(params, 2) ? fmtIntParam(params, 2, directive) : 0;
					LispVal value = (scale == 0) ? arg
							: fmtCall(LispNames.MUL, arg, new LispDouble(Math.pow(10, scale)));
					LispVal base = fmtHasParam(params, 1) ? decimalFloatExpr(value, fmtParam(params, 1), null, at)
							: fmtCall(LispNames.PRINC_TO_STRING, value);
					if (fmtHasParam(params, 0)) {
						base = padExpr(base, fmtParam(params, 0), fmtPadChar(params, 4, ' '), true);
					}
					base = maybeOverflow(base, params, 0, 3, directive);
					ops.add(new FmtString(base));
				}
				case 'e' -> {
					flushFmtLiteral(lit, ops);
					LispVal arg = args.next(directive);
					boolean dGiven = fmtHasParam(params, 1);
					int places = dGiven ? fmtIntParam(params, 1, directive) : DEFAULT_EXP_PLACES;
					if (places < 0) {
						throw new IllegalArgumentException("format: ~e precision must be non-negative");
					}
					int expDigits = fmtHasParam(params, 2) ? fmtIntParam(params, 2, directive) : 0;
					if (fmtHasParam(params, 3) && fmtIntParam(params, 3, directive) != 1) {
						throw new UnsupportedOperationException(
								"format: ~e scale factors other than 1 are not supported");
					}
					char marker = fmtCharParam(params, 6, 'e');
					LispVal base = decimalExpExpr(arg, places, !dGiven, at, expDigits, marker);
					if (fmtHasParam(params, 0)) {
						base = padExpr(base, fmtParam(params, 0), fmtPadChar(params, 5, ' '), true);
					}
					base = maybeOverflow(base, params, 0, 4, directive);
					ops.add(new FmtString(base));
				}
				case 'g' -> {
					flushFmtLiteral(lit, ops);
					for (LispVal p : params) {
						if (!(p instanceof LispNil)) {
							throw new UnsupportedOperationException(
									"format: ~g prefix parameters are not supported; use ~f or ~e");
						}
					}
					LispVal arg = args.next(directive);
					ops.add(new FmtString(generalFloatExpr(arg, at)));
				}
				case '$' -> {
					flushFmtLiteral(lit, ops);
					LispVal arg = args.next(directive);
					LispVal places = fmtHasParam(params, 0) ? fmtParam(params, 0) : new LispInteger(2);
					LispVal nbefore = fmtHasParam(params, 1) ? fmtParam(params, 1) : new LispInteger(1);
					LispVal base = decimalFloatExpr(arg, places, nbefore, at);
					if (fmtHasParam(params, 2)) {
						base = padExpr(base, fmtParam(params, 2), fmtPadChar(params, 3, ' '), true);
					}
					ops.add(new FmtString(base));
				}
				case '*' -> {
					if (at) {
						// ~n@* is an absolute jump to argument n (default 0).
						args.move(fmtCount(params, 0, 0, directive) - args.position(), directive);
					}
					else if (colon) {
						args.move(-fmtCount(params, 0, 1, directive), directive);
					}
					else {
						args.move(fmtCount(params, 0, 1, directive), directive);
					}
				}
				case '(' -> {
					flushFmtLiteral(lit, ops);
					LispVal body = opsToExpr(parseOps(args, ")"));
					LispVal converted;
					if (colon && at) {
						converted = fmtCall(LispNames.STRING_UPCASE, body);
					}
					else if (colon) {
						converted = fmtCall(LispNames.STRING_CAPITALIZE, body);
					}
					else if (at) {
						converted = capitalizeFirstExpr(body);
					}
					else {
						converted = fmtCall(LispNames.STRING_DOWNCASE, body);
					}
					ops.add(new FmtString(converted));
				}
				case '[' -> {
					flushFmtLiteral(lit, ops);
					parseConditional(params, colon, at, args, ops, stoppers);
				}
				case '{' -> {
					flushFmtLiteral(lit, ops);
					parseIteration(params, colon, at, args, ops);
				}
				case '?' -> {
					// ~? (recursive format): the next arg is a control string, the one
					// after a list of its arguments; rendered by the runtime control
					// renderer (its directive subset applies). The ~@? variant (args
					// taken inline) is not supported.
					if (at) {
						throw new UnsupportedOperationException("format: ~@? is not supported");
					}
					flushFmtLiteral(lit, ops);
					LispVal innerCtrl = args.next(directive);
					LispVal innerArgs = args.next(directive);
					ops.add(new FmtString(FormatRenderer.call(innerCtrl, innerArgs)));
				}
				case '^' -> {
					if (colon || at) {
						throw new UnsupportedOperationException("format: ~:^ and ~@^ are not supported");
					}
					for (LispVal p : params) {
						if (!(p instanceof LispNil)) {
							throw new UnsupportedOperationException("format: ~^ prefix parameters are not supported");
						}
					}
					flushFmtLiteral(lit, ops);
					if (args.isStatic()) {
						// The argument count is known at expansion time: with arguments
						// left the escape can never fire and is dropped; with none left
						// it fires here, truncating everything after it (the cursor
						// keeps handing out throwaway temps so the rest still parses).
						if (args.remaining('^') == 0) {
							args.cutTerminated = true;
							ops.add(new FmtCut(0));
						}
					}
					else {
						ops.add(new FmtCut(args.position()));
					}
				}
				case ';', ']', '}', ')' -> throw new IllegalArgumentException("format: misplaced ~" + directive);
				default -> throw new UnsupportedOperationException("format: unsupported directive ~" + directive);
			}
		}

		/**
		 * Parses the clauses of a {@code ~[...~]}, each against a branch of the cursor.
		 */
		private List<FmtClause> parseClauses(FmtArgs args) {
			List<FmtClause> clauses = new java.util.ArrayList<>();
			boolean nextIsDefault = false;
			while (true) {
				FmtArgs branch = args.branch();
				List<FmtOp> body = parseOps(branch, ";]");
				clauses.add(new FmtClause(body, branch.position(), nextIsDefault));
				if (this.stopChar == ']') {
					return clauses;
				}
				nextIsDefault = this.stopColon;
			}
		}

		/**
		 * Folds each clause of a runtime-selected {@code ~[} into one string-valued
		 * expression, in clause order.
		 * <p>
		 * When every clause consumes the same number of arguments the argument position
		 * after the conditional is known statically and each clause folds on its own.
		 * When the clauses consume DIFFERENT numbers -- CL leaves the argument pointer
		 * wherever the selected clause left it, so the position after the conditional is
		 * only known at run time -- the REMAINDER of the enclosing control string is
		 * re-parsed once per clause, each against that clause's own argument position,
		 * and folded into the clause. The conditional then covers everything after itself
		 * and the enclosing {@link #parseOps} loop stops ({@link #remainderTaken}).
		 * postmodern's {@code deftable} constraint strings end with
		 * {@code ~:[NOT DEFERRABLE~;DEFERRABLE INITIALLY ~:[IMMEDIATE~;DEFERRED~]~]},
		 * whose two clauses consume one argument apart.
		 * <p>
		 * Two consequences of folding the tail into a branch: a {@code ~&} in it is
		 * approximated from the branch's own literal text (as in any composite body), and
		 * the fan-out is multiplicative in the number of divergent conditionals, so it is
		 * bounded by {@link #MAX_REMAINDER_EXPANSIONS}.
		 */
		private List<LispVal> clauseExprs(List<FmtClause> clauses, FmtArgs args, String stoppers) {
			int end = clauses.get(0).end();
			boolean diverges = false;
			for (FmtClause clause : clauses) {
				diverges |= clause.end() != end;
			}
			if (!diverges) {
				args.adoptIndex(end);
				return clauses.stream().map(clause -> opsToExpr(clause.ops())).toList();
			}
			if (++this.remainderExpansions > MAX_REMAINDER_EXPANSIONS) {
				throw new UnsupportedOperationException(
						"format: too many argument-divergent ~[ conditionals to expand statically");
			}
			int remainderStart = this.pos;
			List<LispVal> exprs = new java.util.ArrayList<>();
			int tailEnd = -1;
			int tailPos = -1;
			char tailStop = 0;
			boolean tailStopColon = false;
			boolean tailDiverges = false;
			IllegalArgumentException lastFailure = null;
			for (FmtClause clause : clauses) {
				this.pos = remainderStart;
				FmtArgs branch = args.branchAt(clause.end());
				List<FmtOp> whole = new java.util.ArrayList<>(clause.ops());
				try {
					whole.addAll(parseOps(branch, stoppers));
				}
				catch (IllegalArgumentException shortOfArguments) {
					// This branch consumes more arguments than were supplied. CL only
					// notices when the branch actually RUNS, so the clause folds to a
					// call that signals then, and the others still expand statically.
					lastFailure = shortOfArguments;
					String message = shortOfArguments.getMessage();
					exprs.add(fmtCall(LispNames.ERROR,
							new LispString(message == null ? "format: bad control string" : message)));
					continue;
				}
				exprs.add(opsToExpr(whole));
				tailDiverges |= tailEnd >= 0 && branch.position() != tailEnd;
				tailEnd = Math.max(tailEnd, branch.position());
				tailPos = this.pos;
				tailStop = this.stopChar;
				tailStopColon = this.stopColon;
			}
			if (tailPos < 0) {
				// No clause parsed: the control string itself is bad, not the argument
				// count of one branch.
				throw lastFailure;
			}
			if (tailDiverges && !stoppers.isEmpty()) {
				// Nested inside another composite directive, whose own end position would
				// then be branch-dependent too; the runtime renderer takes it instead.
				throw new UnsupportedOperationException(
						"format: an argument-divergent ~[ inside another composite directive is not supported");
			}
			this.pos = tailPos;
			this.stopChar = tailStop;
			this.stopColon = tailStopColon;
			args.adoptIndex(tailEnd);
			this.remainderTaken = true;
			return exprs;
		}

		private void parseConditional(List<LispVal> params, boolean colon, boolean at, FmtArgs args, List<FmtOp> ops,
				String stoppers) {
			if (at) {
				// ~@[str~]: the tested argument is re-used by the clause when non-nil
				// and consumed outright when nil, so the clause must consume exactly it.
				LispSymbol sel = args.next('[');
				FmtArgs branch = args.branchAt(args.position() - 1);
				List<FmtOp> body = parseOps(branch, "]");
				if (branch.position() != args.position()) {
					throw new UnsupportedOperationException(
							"format: the ~@[ clause must consume exactly the tested argument");
				}
				ops.add(new FmtString(makeIf(sel, opsToExpr(body), new LispString(""))));
				return;
			}
			if (colon) {
				LispSymbol sel = args.next('[');
				List<FmtClause> clauses = parseClauses(args);
				if (clauses.size() != 2) {
					throw new IllegalArgumentException("format: ~:[ requires exactly two clauses");
				}
				List<LispVal> exprs = clauseExprs(clauses, args, stoppers);
				ops.add(new FmtString(makeIf(sel, exprs.get(1), exprs.get(0))));
				return;
			}
			LispVal selParam = params.isEmpty() ? LispNil.INSTANCE : params.get(0);
			if (selParam instanceof LispInteger li) {
				// A literal (or #) selector picks the clause at expansion time, so
				// clauses may consume different numbers of arguments. Unselected
				// clauses parse against a throwaway source (they never touch the
				// real arguments); the default clause (after ~:;) is last, so by the
				// time it is reached the numbered selection is decided.
				long nval = li.value();
				List<FmtOp> chosenOps = null;
				int chosenEnd = -1;
				boolean nextIsDefault = false;
				int numberedIdx = 0;
				while (true) {
					boolean isDefault = nextIsDefault;
					boolean choose = (chosenOps == null) && (isDefault || numberedIdx == nval);
					if (!isDefault) {
						numberedIdx++;
					}
					if (choose) {
						FmtArgs branch = args.branch();
						chosenOps = parseOps(branch, ";]");
						chosenEnd = branch.position();
					}
					else {
						parseOps(FmtArgs.forRuntimeItems("__fmtdis" + this.gensym++ + "_"), ";]");
					}
					if (this.stopChar == ']') {
						break;
					}
					nextIsDefault = this.stopColon;
				}
				if (chosenOps != null) {
					ops.addAll(chosenOps);
					args.adoptIndex(chosenEnd);
				}
				return;
			}
			LispVal sel = (selParam instanceof LispNil) ? args.next('[') : selParam;
			List<FmtClause> clauses = parseClauses(args);
			List<LispVal> exprs = clauseExprs(clauses, args, stoppers);
			List<LispVal> numbered = new java.util.ArrayList<>();
			LispVal dflt = null;
			for (int i = 0; i < clauses.size(); i++) {
				if (clauses.get(i).isDefault()) {
					dflt = exprs.get(i);
				}
				else {
					numbered.add(exprs.get(i));
				}
			}
			LispVal chain = (dflt != null) ? dflt : new LispString("");
			for (int i = numbered.size() - 1; i >= 0; i--) {
				chain = makeIf(fmtCall(LispNames.EQL, sel, new LispInteger(i)), numbered.get(i), chain);
			}
			ops.add(new FmtString(chain));
		}

		private void parseIteration(List<LispVal> params, boolean colon, boolean at, FmtArgs args, List<FmtOp> ops) {
			int id = this.gensym++;
			LispVal maxParam = (params.isEmpty()) ? LispNil.INSTANCE : params.get(0);
			if (at) {
				// ~@{ iterates over the remaining top-level arguments, so the passes
				// can be unrolled at expansion time (each pass re-parses the body).
				if (!args.isStatic()) {
					throw new UnsupportedOperationException("format: ~@{ is not supported inside a ~{ iteration body");
				}
				int limit = Integer.MAX_VALUE;
				if (maxParam instanceof LispInteger li) {
					limit = (int) li.value();
				}
				else if (!(maxParam instanceof LispNil)) {
					throw new UnsupportedOperationException("format: a runtime (v) count is not supported for ~@{");
				}
				int bodyStart = this.pos;
				int bodyEnd = -1;
				int passes = 0;
				while (args.remaining('{') > 0 && passes < limit) {
					if (colon) {
						// ~:@{: each remaining argument is one iteration's sublist.
						LispSymbol sub = args.next('{');
						FmtArgs items = FmtArgs.forRuntimeItems("__fmtsub" + id + "_" + passes + "_");
						this.pos = bodyStart;
						List<FmtOp> body = parseOps(items, "}");
						bodyEnd = this.pos;
						ops.add(new FmtString(letItems(items.items(), sub, cutBodyExpr(body, sub, null))));
						passes++;
					}
					else {
						int before = args.position();
						this.pos = bodyStart;
						// A ~^ in the pass fires only when it exhausted the arguments,
						// so truncating the pass also ends the unroll (remaining is 0).
						ops.addAll(truncateAtCut(parseOps(args, "}")));
						bodyEnd = this.pos;
						passes++;
						if (args.position() == before) {
							break; // a pass that consumes nothing would never terminate
						}
					}
				}
				if (bodyEnd < 0) {
					// Zero passes ran; skip the body with a throwaway parse.
					this.pos = bodyStart;
					parseOps(FmtArgs.forRuntimeItems("__fmtskip" + id + "_"), "}");
				}
				else {
					this.pos = bodyEnd;
				}
				return;
			}
			LispSymbol listSym = args.next('{');
			FmtArgs items = FmtArgs.forRuntimeItems("__fmtit" + id + "_");
			List<FmtOp> body = parseOps(items, "}");
			LispVal maxExpr = (maxParam instanceof LispNil) ? null : maxParam;
			if (!colon && items.position() == 0) {
				throw new UnsupportedOperationException("format: the ~{ body must consume at least one argument");
			}
			LispVal loop = colon ? sublistLoopExpr(listSym, items, body, maxExpr, id)
					: flatLoopExpr(listSym, items, body, maxExpr, id);
			ops.add(new FmtString(loop));
		}

	}

	private static boolean isParamStart(char c) {
		return c == '\'' || c == 'v' || c == 'V' || c == '#' || c == '-' || Character.isDigit(c);
	}

	private static LispVal fmtCall(String op, LispVal... args) {
		List<LispVal> parts = new java.util.ArrayList<>();
		parts.add(new LispSymbol(op));
		parts.addAll(List.of(args));
		return listToCons(parts);
	}

	/**
	 * Builds {@code (let ((r strExpr)) (while (< (length r) mincol) (setq r ...)) r)},
	 * which pads {@code strExpr} with the single-character {@code padChar} until it
	 * reaches {@code mincol} columns. When {@code left} is true the padding is prepended
	 * (right-justify), otherwise appended (left-justify). Pure-Lisp so all three backends
	 * share the implementation; {@code mincol} may be a compile-time literal or a runtime
	 * (v) parameter, and {@code padChar} a literal string or a runtime string expression.
	 */
	private static LispVal padExpr(LispVal strExpr, LispVal mincolExpr, LispVal padChar, boolean left) {
		LispSymbol r = new LispSymbol("__fmtr");
		LispVal lenCheck = fmtCall(LispNames.LT, fmtCall(LispNames.LENGTH, r), mincolExpr);
		LispVal concat = left ? fmtCall(LispNames.STRING_CONCAT, padChar, r)
				: fmtCall(LispNames.STRING_CONCAT, r, padChar);
		LispVal loop = fmtCall(LispNames.WHILE, lenCheck, fmtCall(LispNames.SETQ, r, concat));
		LispVal binding = listToCons(List.of(listToCons(List.of(r, strExpr))));
		return listToCons(List.of(new LispSymbol(LispNames.LET), binding, loop, r));
	}

	/**
	 * Builds the string-valued expansion of {@code ~d} with the {@code :} (comma
	 * grouping) and/or {@code @} (explicit plus sign) modifiers.
	 */
	private static LispVal decimalExpr(LispVal arg, boolean comma, String commaChar, int interval, boolean plus) {
		LispSymbol nstr = new LispSymbol("__fmtn");
		LispSymbol neg = new LispSymbol("__fmtneg");
		LispSymbol dig = new LispSymbol("__fmtd");
		LispVal nstrInit = fmtCall(LispNames.PRINC_TO_STRING, arg);
		LispVal negInit = fmtCall(LispNames.LT, arg, new LispInteger(0));
		LispVal digInit = makeIf(neg, fmtCall(LispNames.SUBSEQ, nstr, new LispInteger(1)), nstr);
		LispVal grouped = comma ? groupExpr(dig, commaChar, interval) : dig;
		LispVal sign = makeIf(neg, new LispString("-"), new LispString(plus ? "+" : ""));
		List<LispVal> bindings = List.of(listToCons(List.of(nstr, nstrInit)), listToCons(List.of(neg, negInit)),
				listToCons(List.of(dig, digInit)));
		LispVal body = fmtCall(LispNames.STRING_CONCAT, sign, grouped);
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), listToCons(bindings), body));
	}

	/** Builds the comma-grouping loop over a string of digits. */
	private static LispVal groupExpr(LispVal digitsExpr, String commaChar, int interval) {
		LispSymbol rem = new LispSymbol("__fmtrem");
		LispSymbol out = new LispSymbol("__fmtout");
		LispInteger iv = new LispInteger(interval);
		LispVal tailLen = fmtCall(LispNames.SUB, fmtCall(LispNames.LENGTH, rem), iv);
		LispVal test = fmtCall(LispNames.GT, fmtCall(LispNames.LENGTH, rem), iv);
		LispVal newOut = fmtCall(LispNames.STRING_CONCAT,
				fmtCall(LispNames.STRING_CONCAT, new LispString(commaChar), fmtCall(LispNames.SUBSEQ, rem, tailLen)),
				out);
		LispVal newRem = fmtCall(LispNames.SUBSEQ, rem, new LispInteger(0), tailLen);
		LispVal loop = fmtCall(LispNames.WHILE, test, fmtCall(LispNames.SETQ, out, newOut),
				fmtCall(LispNames.SETQ, rem, newRem));
		List<LispVal> bindings = List.of(listToCons(List.of(rem, digitsExpr)),
				listToCons(List.of(out, new LispString(""))));
		LispVal body = fmtCall(LispNames.STRING_CONCAT, rem, out);
		return listToCons(List.of(new LispSymbol(LispNames.LET), listToCons(bindings), loop, body));
	}

	/**
	 * Builds the string-valued expansion of a fixed-decimal float (~f) or monetary value
	 * (~$). The value is scaled by 10^places, rounded to an integer (round-half-to-even,
	 * matching {@code round} on every backend) and split into integer and fractional
	 * parts by string slicing, so no floating-point string formatting is needed at
	 * runtime. When {@code nbefore} is non-null the integer part is zero-padded to that
	 * many digits (~$).
	 */
	private static LispVal decimalFloatExpr(LispVal arg, LispVal placesExpr, @Nullable LispVal nbefore, boolean plus) {
		boolean zeroPlaces = placesExpr instanceof LispInteger li && li.value() == 0;
		// A floating-point 10^places keeps the scaling multiply in f64 on every backend
		// (an integer expt can widen to bignum and break mixed arithmetic).
		LispVal pow10 = (placesExpr instanceof LispInteger li) ? new LispDouble(pow10(li.value()))
				: fmtCall(LispNames.EXPT, new LispDouble(10.0), placesExpr);
		LispVal nPlus1 = (placesExpr instanceof LispInteger li) ? new LispInteger(li.value() + 1)
				: fmtCall(LispNames.ADD, placesExpr, new LispInteger(1));
		LispSymbol v = new LispSymbol("__fmtv");
		LispSymbol neg = new LispSymbol("__fmtneg");
		LispSymbol sc = new LispSymbol("__fmtsc");
		LispSymbol s2 = new LispSymbol("__fmts");
		LispSymbol len = new LispSymbol("__fmtlen");
		LispSymbol ip = new LispSymbol("__fmtip");
		LispVal vInit = fmtCall(LispNames.MUL, arg, new LispDouble(1.0));
		LispVal negInit = fmtCall(LispNames.LT, v, new LispDouble(0.0));
		// Round to a signed integer, then take the magnitude by integer negation (the
		// integer `abs` runtime path rejects a float operand on the compiled backends).
		LispVal signedScaled = fmtCall(LispNames.ROUND, fmtCall(LispNames.MUL, v, pow10));
		LispVal scInit = makeIf(neg, fmtCall(LispNames.SUB, new LispInteger(0), signedScaled), signedScaled);
		LispVal s2Init = padExpr(fmtCall(LispNames.PRINC_TO_STRING, sc), nPlus1, new LispString("0"), true);
		LispVal lenInit = fmtCall(LispNames.LENGTH, s2);
		LispVal ipSlice = fmtCall(LispNames.SUBSEQ, s2, new LispInteger(0), fmtCall(LispNames.SUB, len, placesExpr));
		LispVal ipInit = (nbefore == null) ? ipSlice : padExpr(ipSlice, nbefore, new LispString("0"), true);
		LispVal sign = makeIf(neg, new LispString("-"), new LispString(plus ? "+" : ""));
		List<LispVal> bindings = new java.util.ArrayList<>(List.of(listToCons(List.of(v, vInit)),
				listToCons(List.of(neg, negInit)), listToCons(List.of(sc, scInit)), listToCons(List.of(s2, s2Init)),
				listToCons(List.of(len, lenInit)), listToCons(List.of(ip, ipInit))));
		LispVal body;
		if (zeroPlaces) {
			body = fmtCall(LispNames.STRING_CONCAT, sign, ip);
		}
		else {
			LispVal fp = fmtCall(LispNames.SUBSEQ, s2, fmtCall(LispNames.SUB, len, placesExpr));
			LispVal withDot = fmtCall(LispNames.STRING_CONCAT,
					fmtCall(LispNames.STRING_CONCAT, ip, new LispString(".")), fp);
			body = fmtCall(LispNames.STRING_CONCAT, sign, withDot);
		}
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), listToCons(bindings), body));
	}

	private static long pow10(long n) {
		long r = 1;
		for (long k = 0; k < n; k++) {
			r *= 10;
		}
		return r;
	}

	/**
	 * The number of fractional digits used by {@code ~e} when the {@code d} parameter is
	 * omitted (matching C's {@code printf("%e")} default). Kept small enough that the
	 * scaled mantissa fits in a WASM {@code i31}, so the directive renders identically on
	 * all three backends.
	 */
	private static final int DEFAULT_EXP_PLACES = 6;

	/**
	 * Builds the string-valued expansion of an exponential-notation float ({@code ~e}).
	 * The magnitude is normalized to a mantissa in {@code [1, 10)} by a runtime
	 * divide/multiply loop that tracks the decimal exponent, rounded to {@code places}
	 * fractional digits via integer scaling (so the digit string is built purely from
	 * integer arithmetic and renders identically on every backend, unlike a direct
	 * {@code princ-to-string} of a float), and assembled as
	 * {@code [sign]d.ddd...e[+/-]xx}. A mantissa that rounds up to {@code 10.0} bumps the
	 * exponent and renormalizes to {@code 1.0}. When {@code strip} is true (the {@code d}
	 * parameter was omitted) trailing fractional zeros are dropped down to a single
	 * digit. On the WASM backend the scaled mantissa must fit in an {@code i31}, so
	 * {@code places} is effectively limited to about 8. When {@code expDigits} is
	 * positive the exponent magnitude is zero-padded to that many digits, and
	 * {@code marker} is the exponent-marker character (default {@code e}).
	 */
	private static LispVal decimalExpExpr(LispVal arg, int places, boolean strip, boolean plus, int expDigits,
			char marker) {
		long pd = pow10(places);
		long pd1 = pow10(places + 1L);
		LispSymbol v = new LispSymbol("__ev");
		LispSymbol neg = new LispSymbol("__eneg");
		LispSymbol a = new LispSymbol("__ea");
		LispSymbol ee = new LispSymbol("__ee");
		LispSymbol sc = new LispSymbol("__esc");
		LispSymbol ovf = new LispSymbol("__eovf");
		LispSymbol sc2 = new LispSymbol("__esc2");
		LispSymbol eef = new LispSymbol("__eef");
		LispSymbol s = new LispSymbol("__es");
		LispSymbol ip = new LispSymbol("__eip");
		LispSymbol fr = new LispSymbol("__efr");

		// Outer let* bindings: coerce to float, capture sign, take magnitude, exponent =
		// 0.
		LispVal vInit = fmtCall(LispNames.MUL, arg, new LispDouble(1.0));
		LispVal negInit = fmtCall(LispNames.LT, v, new LispDouble(0.0));
		LispVal aInit = makeIf(neg, fmtCall(LispNames.SUB, new LispDouble(0.0), v), v);
		// Normalize the mantissa into [1, 10), tracking the decimal exponent in ee.
		LispVal up = fmtCall(LispNames.WHILE, fmtCall(LispNames.GE, a, new LispDouble(10.0)),
				fmtCall(LispNames.SETQ, a, fmtCall(LispNames.DIV, a, new LispDouble(10.0))),
				fmtCall(LispNames.SETQ, ee, fmtCall(LispNames.ADD, ee, new LispInteger(1))));
		LispVal down = fmtCall(LispNames.WHILE, fmtCall(LispNames.LT, a, new LispDouble(1.0)),
				fmtCall(LispNames.SETQ, a, fmtCall(LispNames.MUL, a, new LispDouble(10.0))),
				fmtCall(LispNames.SETQ, ee, fmtCall(LispNames.SUB, ee, new LispInteger(1))));
		// Inner let*: round to (places+1) significant digits, renormalize on overflow.
		LispVal scInit = fmtCall(LispNames.ROUND, fmtCall(LispNames.MUL, a, new LispDouble((double) pd)));
		LispVal ovfInit = fmtCall(LispNames.GE, sc, new LispInteger(pd1));
		LispVal sc2Init = makeIf(ovf, new LispInteger(pd), sc);
		LispVal eefInit = makeIf(ovf, fmtCall(LispNames.ADD, ee, new LispInteger(1)), ee);
		LispVal sInit = fmtCall(LispNames.PRINC_TO_STRING, sc2);
		LispVal ipInit = fmtCall(LispNames.SUBSEQ, s, new LispInteger(0), new LispInteger(1));
		LispVal frInit = fmtCall(LispNames.SUBSEQ, s, new LispInteger(1));
		// Exponent suffix: always-signed, magnitude printed as an integer.
		LispVal eneg = fmtCall(LispNames.LT, eef, new LispInteger(0));
		LispVal esign = makeIf(eneg, new LispString("-"), new LispString("+"));
		LispVal eabs = fmtCall(LispNames.PRINC_TO_STRING,
				makeIf(eneg, fmtCall(LispNames.SUB, new LispInteger(0), eef), eef));
		if (expDigits > 0) {
			eabs = padExpr(eabs, new LispInteger(expDigits), new LispString("0"), true);
		}
		LispVal sign = makeIf(neg, new LispString("-"), new LispString(plus ? "+" : ""));
		LispVal frFinal = strip ? stripTrailingZeros(fr) : fr;
		LispVal mant = (places == 0) ? ip : fmtConcat(ip, new LispString("."), frFinal);
		LispVal body = fmtConcat(sign, mant, new LispString(String.valueOf(marker)), esign, eabs);
		List<LispVal> innerBindings = List.of(listToCons(List.of(sc, scInit)), listToCons(List.of(ovf, ovfInit)),
				listToCons(List.of(sc2, sc2Init)), listToCons(List.of(eef, eefInit)), listToCons(List.of(s, sInit)),
				listToCons(List.of(ip, ipInit)), listToCons(List.of(fr, frInit)));
		LispVal innerLet = listToCons(List.of(new LispSymbol(LispNames.LET_STAR), listToCons(innerBindings), body));
		LispVal normal = listToCons(List.of(new LispSymbol(LispNames.PROGN), up, down, innerLet));
		// Zero needs no normalization (it would loop forever), so short-circuit it.
		String zeroMant = (places == 0) ? "0" : (strip ? "0.0" : "0." + "0".repeat(places));
		LispVal zero = new LispString((plus ? "+" : "") + zeroMant + marker + "+" + "0".repeat(Math.max(1, expDigits)));
		LispVal outerBody = makeIf(fmtCall(LispNames.EQ, a, new LispDouble(0.0)), zero, normal);
		List<LispVal> outerBindings = List.of(listToCons(List.of(v, vInit)), listToCons(List.of(neg, negInit)),
				listToCons(List.of(a, aInit)), listToCons(List.of(ee, new LispInteger(0))));
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), listToCons(outerBindings), outerBody));
	}

	/**
	 * Builds
	 * {@code (let ((g frExpr)) (while (and (> (length g) 1) (string= last "0")) ...)
	 * g)}, trimming trailing {@code 0} characters from a fractional-digit string down to
	 * a single remaining digit. Pure-Lisp so all three backends share it.
	 */
	private static LispVal stripTrailingZeros(LispVal frExpr) {
		LispSymbol g = new LispSymbol("__eg");
		LispVal last = fmtCall(LispNames.SUBSEQ, g,
				fmtCall(LispNames.SUB, fmtCall(LispNames.LENGTH, g), new LispInteger(1)));
		LispVal cond = fmtCall(LispNames.AND, fmtCall(LispNames.GT, fmtCall(LispNames.LENGTH, g), new LispInteger(1)),
				fmtCall(LispNames.STRING_EQ, last, new LispString("0")));
		LispVal trimmed = fmtCall(LispNames.SUBSEQ, g, new LispInteger(0),
				fmtCall(LispNames.SUB, fmtCall(LispNames.LENGTH, g), new LispInteger(1)));
		LispVal loop = fmtCall(LispNames.WHILE, cond, fmtCall(LispNames.SETQ, g, trimmed));
		LispVal binding = listToCons(List.of(listToCons(List.of(g, frExpr))));
		return listToCons(List.of(new LispSymbol(LispNames.LET), binding, loop, g));
	}

	/**
	 * Folds {@code parts} into a right-nested chain of binary {@code %string-concat}
	 * calls.
	 */
	private static LispVal fmtConcat(LispVal... parts) {
		LispVal r = parts[parts.length - 1];
		for (int k = parts.length - 2; k >= 0; k--) {
			r = fmtCall(LispNames.STRING_CONCAT, parts[k], r);
		}
		return r;
	}

	/**
	 * Resolves a compile-time integer prefix parameter, rejecting a runtime {@code v}.
	 */
	private static int fmtIntParam(List<LispVal> params, int idx, char directive) {
		if (params.get(idx) instanceof LispInteger li) {
			return (int) li.value();
		}
		throw new UnsupportedOperationException(
				"format: runtime (v) parameter not supported for directive ~" + directive);
	}

	/**
	 * The pad string for a pad-character parameter: a literal string for a {@code 'c}
	 * parameter, or a {@code (princ-to-string v)} expression for a runtime (v) parameter.
	 */
	private static LispVal fmtPadChar(List<LispVal> params, int idx, char def) {
		if (idx < params.size() && params.get(idx) instanceof LispInteger code) {
			return new LispString(String.valueOf((char) code.value()));
		}
		if (idx < params.size() && params.get(idx) instanceof LispSymbol v) {
			return fmtCall(LispNames.PRINC_TO_STRING, v);
		}
		return new LispString(String.valueOf(def));
	}

	/** A literal character parameter (e.g. the ~e exponent marker), or the default. */
	private static char fmtCharParam(List<LispVal> params, int idx, char def) {
		if (idx < params.size() && params.get(idx) instanceof LispInteger code) {
			return (char) code.value();
		}
		if (idx < params.size() && !(params.get(idx) instanceof LispNil)) {
			throw new UnsupportedOperationException("format: a runtime (v) character parameter is not supported here");
		}
		return def;
	}

	/** The literal comma character for ~:d (default {@code ,}). */
	private static String fmtCommaChar(List<LispVal> params, int idx) {
		if (idx < params.size() && params.get(idx) instanceof LispInteger code) {
			return String.valueOf((char) code.value());
		}
		return ",";
	}

	/** The comma interval for ~:d (default 3). */
	private static int fmtInterval(List<LispVal> params, int idx) {
		if (idx < params.size() && params.get(idx) instanceof LispInteger iv) {
			return (int) iv.value();
		}
		return 3;
	}

	/**
	 * Returns the param at {@code idx}, or nil (the helper's default sentinel) if absent.
	 */
	private static LispVal fmtParam(List<LispVal> params, int idx) {
		return idx < params.size() ? params.get(idx) : LispNil.INSTANCE;
	}

	private static boolean fmtHasParam(List<LispVal> params, int idx) {
		return idx < params.size() && !(params.get(idx) instanceof LispNil);
	}

	/** Resolves a compile-time integer parameter (count) for ~%/~&/~~. */
	private static int fmtCount(List<LispVal> params, int idx, int def, char directive) {
		if (idx >= params.size()) {
			return def;
		}
		LispVal pv = params.get(idx);
		if (pv instanceof LispNil) {
			return def;
		}
		if (pv instanceof LispInteger li) {
			return (int) li.value();
		}
		throw new UnsupportedOperationException("format: runtime (v) count not supported for directive ~" + directive);
	}

	private static void flushFmtLiteral(StringBuilder lit, List<FmtOp> ops) {
		if (!lit.isEmpty()) {
			ops.add(new FmtLiteral(lit.toString()));
			lit.setLength(0);
		}
	}

	/**
	 * Truncates a statically-parsed op run at its first {@code ~^} cut (a cut recorded
	 * against a static source only exists when it fires -- see the {@code ^} dispatch
	 * case). Used for the top-level control and for each unrolled {@code ~@&#123;} pass.
	 */
	private static List<FmtOp> truncateAtCut(List<FmtOp> ops) {
		for (int i = 0; i < ops.size(); i++) {
			if (ops.get(i) instanceof FmtCut) {
				return ops.subList(0, i);
			}
		}
		return ops;
	}

	/**
	 * Renders the parsed ops into output forms for the {@code t} destination: literals
	 * and string-valued directives become {@code (princ ...)}, {@code ~%} becomes
	 * {@code (terpri)}, and {@code ~&} becomes {@code (fresh-line)}.
	 */
	private static List<LispVal> formatOutputForms(List<FmtOp> ops) {
		List<LispVal> forms = new java.util.ArrayList<>();
		for (FmtOp op : ops) {
			switch (op) {
				case FmtLiteral l -> forms.add(fmtCall(LispNames.PRINC, new LispString(l.text())));
				case FmtString f -> forms.add(fmtCall(LispNames.PRINC, f.expr()));
				case FmtNewline nl -> {
					for (int k = 0; k < nl.count(); k++) {
						forms.add(listToCons(List.of(new LispSymbol(LispNames.TERPRI))));
					}
				}
				case FmtFreshLine fl -> {
					forms.add(listToCons(List.of(new LispSymbol(LispNames.FRESH_LINE))));
					for (int k = 1; k < fl.count(); k++) {
						forms.add(listToCons(List.of(new LispSymbol(LispNames.TERPRI))));
					}
				}
				// ~{ bodies and ~@{ passes handle their cuts before rendering; a cut
				// leaking into any other composite body cannot be lowered statically.
				case FmtCut ignored -> throw new UnsupportedOperationException(
						"format: ~^ is only supported at the top level and inside ~{ ... ~}");
			}
		}
		return forms;
	}

	/**
	 * Renders the parsed ops into string-valued pieces for the {@code nil} destination
	 * (and for the bodies of composite directives). Newlines become literal {@code \n}
	 * runs; {@code ~&} is statically approximated from the surrounding literal text (a
	 * value piece is assumed not to end a line).
	 */
	private static List<LispVal> opsToPieces(List<FmtOp> ops) {
		List<LispVal> pieces = new java.util.ArrayList<>();
		boolean atLineStart = true;
		for (FmtOp op : ops) {
			switch (op) {
				case FmtLiteral l -> {
					pieces.add(new LispString(l.text()));
					atLineStart = l.text().endsWith("\n");
				}
				case FmtString f -> {
					pieces.add(f.expr());
					atLineStart = false;
				}
				case FmtNewline nl -> {
					if (nl.count() > 0) {
						pieces.add(new LispString("\n".repeat(nl.count())));
						atLineStart = true;
					}
				}
				case FmtFreshLine fl -> {
					int emit = atLineStart ? fl.count() - 1 : fl.count();
					if (emit > 0) {
						pieces.add(new LispString("\n".repeat(emit)));
					}
					atLineStart = true;
				}
				// ~{ bodies and ~@{ passes handle their cuts before rendering; a cut
				// leaking into any other composite body cannot be lowered statically.
				case FmtCut ignored -> throw new UnsupportedOperationException(
						"format: ~^ is only supported at the top level and inside ~{ ... ~}");
			}
		}
		return pieces;
	}

	/**
	 * Folds a {@code ~&#123;} body that may carry {@code ~^} cuts into one string-valued
	 * expression over {@code base} (the unconsumed tail for a flat pass, the current
	 * sublist for a sublist pass). Each cut checks whether an element remains beyond the
	 * items consumed before it and, when none does, skips the rest of the body; a
	 * non-null {@code doneSym} is additionally set so the enclosing flat loop stops.
	 */
	private static LispVal cutBodyExpr(List<FmtOp> body, LispVal base, @Nullable LispSymbol doneSym) {
		List<List<FmtOp>> segments = new java.util.ArrayList<>();
		List<Integer> cuts = new java.util.ArrayList<>();
		List<FmtOp> current = new java.util.ArrayList<>();
		for (FmtOp op : body) {
			if (op instanceof FmtCut cut) {
				segments.add(current);
				cuts.add(cut.consumed());
				current = new java.util.ArrayList<>();
			}
			else {
				current.add(op);
			}
		}
		if (segments.isEmpty()) {
			return opsToExpr(current);
		}
		segments.add(current);
		LispVal expr = opsToExpr(segments.get(segments.size() - 1));
		for (int i = segments.size() - 2; i >= 0; i--) {
			LispVal exhausted = fmtCall(LispNames.NULL, fmtCall(LispNames.NTHCDR, new LispInteger(cuts.get(i)), base));
			LispVal fired = (doneSym == null) ? new LispString("")
					: makeProgn(List.of(fmtCall(LispNames.SETQ, doneSym, LispTrue.INSTANCE), new LispString("")));
			expr = fmtCall(LispNames.STRING_CONCAT, opsToExpr(segments.get(i)), makeIf(exhausted, fired, expr));
		}
		return expr;
	}

	/**
	 * Folds the string pieces of a composite-directive body into one string-valued
	 * expression (the empty string when the body is empty).
	 */
	private static LispVal opsToExpr(List<FmtOp> ops) {
		List<LispVal> pieces = opsToPieces(ops);
		if (pieces.isEmpty()) {
			return new LispString("");
		}
		LispVal result = pieces.get(0);
		for (int i = 1; i < pieces.size(); i++) {
			result = fmtCall(LispNames.STRING_CONCAT, result, pieces.get(i));
		}
		return result;
	}

	/**
	 * Builds the string-valued expansion of an integer in an arbitrary radix
	 * ({@code ~x}/{@code ~o}/{@code ~b}/{@code ~nR}): a runtime division loop over the
	 * magnitude producing uppercase digits (via {@code code-char}), with the same
	 * sign/grouping handling as {@code ~d}. {@code base} is a literal or a runtime (v)
	 * parameter.
	 */
	private static LispVal radixIntegerExpr(LispVal arg, LispVal base, boolean comma, String commaChar, int interval,
			boolean plus) {
		LispSymbol neg = new LispSymbol("__rxneg");
		LispSymbol m = new LispSymbol("__rxm");
		LispSymbol s = new LispSymbol("__rxs");
		LispSymbol d = new LispSymbol("__rxd");
		LispSymbol g = new LispSymbol("__rxg");
		LispVal negInit = fmtCall(LispNames.LT, arg, new LispInteger(0));
		LispVal mInit = makeIf(neg, fmtCall(LispNames.SUB, new LispInteger(0), arg), arg);
		// Digit character: 0-9 then uppercase A-Z (48 = '0', 55 = 'A' - 10).
		LispVal digitChar = fmtCall(LispNames.PRINC_TO_STRING,
				fmtCall(LispNames.CODE_CHAR,
						makeIf(fmtCall(LispNames.LT, d, new LispInteger(10)),
								fmtCall(LispNames.ADD, new LispInteger(48), d),
								fmtCall(LispNames.ADD, new LispInteger(55), d))));
		LispVal digitStep = listToCons(List.of(new LispSymbol(LispNames.LET),
				listToCons(List.of(listToCons(List.of(d, fmtCall(LispNames.MOD, m, base))))),
				fmtCall(LispNames.SETQ, s, fmtCall(LispNames.STRING_CONCAT, digitChar, s))));
		// Integer division by the base: / yields a rational, truncate the quotient.
		LispVal divStep = fmtCall(LispNames.SETQ, m, fmtCall(LispNames.TRUNCATE, fmtCall(LispNames.DIV, m, base)));
		LispVal loop = fmtCall(LispNames.WHILE, fmtCall(LispNames.GT, m, new LispInteger(0)), digitStep, divStep);
		LispVal gInit = makeIf(fmtCall(LispNames.STRING_EQ, s, new LispString("")), new LispString("0"), s);
		LispVal grouped = comma ? groupExpr(g, commaChar, interval) : g;
		LispVal sign = makeIf(neg, new LispString("-"), new LispString(plus ? "+" : ""));
		LispVal inner = listToCons(List.of(new LispSymbol(LispNames.LET),
				listToCons(List.of(listToCons(List.of(g, gInit)))), fmtCall(LispNames.STRING_CONCAT, sign, grouped)));
		List<LispVal> bindings = List.of(listToCons(List.of(neg, negInit)), listToCons(List.of(m, mInit)),
				listToCons(List.of(s, new LispString(""))));
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), listToCons(bindings), loop, inner));
	}

	/**
	 * Builds the string-valued expansion of {@code ~g}: the plain (backend-native) float
	 * representation when the magnitude is zero or within {@code [0.1, 1e16)}, and the
	 * {@code ~e} default form outside that range. An approximation of the CLHS rule
	 * (which chooses between {@code ~f} and {@code ~e} by the number of significant
	 * digits); prefix parameters are not supported.
	 */
	private static LispVal generalFloatExpr(LispVal arg, boolean plus) {
		LispSymbol v = new LispSymbol("__fmtgv");
		LispSymbol a = new LispSymbol("__fmtga");
		LispVal vInit = fmtCall(LispNames.MUL, arg, new LispDouble(1.0));
		LispVal aInit = makeIf(fmtCall(LispNames.LT, v, new LispDouble(0.0)),
				fmtCall(LispNames.SUB, new LispDouble(0.0), v), v);
		LispVal fixedRange = fmtCall(LispNames.OR, fmtCall(LispNames.EQ, a, new LispDouble(0.0)), fmtCall(LispNames.AND,
				fmtCall(LispNames.GE, a, new LispDouble(0.1)), fmtCall(LispNames.LT, a, new LispDouble(1.0e16))));
		LispVal fixed = fmtCall(LispNames.PRINC_TO_STRING, v);
		if (plus) {
			fixed = fmtCall(LispNames.STRING_CONCAT,
					makeIf(fmtCall(LispNames.LT, v, new LispDouble(0.0)), new LispString(""), new LispString("+")),
					fixed);
		}
		LispVal expo = decimalExpExpr(v, DEFAULT_EXP_PLACES, true, plus, 0, 'e');
		List<LispVal> bindings = List.of(listToCons(List.of(v, vInit)), listToCons(List.of(a, aInit)));
		return listToCons(
				List.of(new LispSymbol(LispNames.LET_STAR), listToCons(bindings), makeIf(fixedRange, fixed, expo)));
	}

	/**
	 * Builds the {@code ~@(} conversion: downcase the whole string, then upcase the first
	 * alphabetic character (capitalize just the first word).
	 */
	private static LispVal capitalizeFirstExpr(LispVal strExpr) {
		LispSymbol s = new LispSymbol("__fmtcs");
		LispSymbol n = new LispSymbol("__fmtcn");
		LispSymbol i = new LispSymbol("__fmtci");
		LispVal notAlpha = fmtCall(LispNames.NOT, fmtCall(LispNames.ALPHA_CHAR_P, fmtCall(LispNames.CHAR, s, i)));
		LispVal scan = fmtCall(LispNames.WHILE, fmtCall(LispNames.AND, fmtCall(LispNames.LT, i, n), notAlpha),
				fmtCall(LispNames.SETQ, i, fmtCall(LispNames.ADD, i, new LispInteger(1))));
		LispVal iPlus1 = fmtCall(LispNames.ADD, i, new LispInteger(1));
		LispVal recombined = fmtConcat(fmtCall(LispNames.SUBSEQ, s, new LispInteger(0), i),
				fmtCall(LispNames.STRING_UPCASE, fmtCall(LispNames.SUBSEQ, s, i, iPlus1)),
				fmtCall(LispNames.SUBSEQ, s, iPlus1));
		LispVal body = makeIf(fmtCall(LispNames.LT, i, n), recombined, s);
		List<LispVal> bindings = List.of(listToCons(List.of(s, fmtCall(LispNames.STRING_DOWNCASE, strExpr))),
				listToCons(List.of(n, fmtCall(LispNames.LENGTH, s))), listToCons(List.of(i, new LispInteger(0))));
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), listToCons(bindings), scan, body));
	}

	/**
	 * Wraps a padded field with the overflow check: when the field width (literal
	 * {@code w} at {@code widthIdx}) and an overflow character (literal at
	 * {@code ovfIdx}) are both given and the formatted text exceeds the width, the field
	 * is replaced by {@code w} copies of the overflow character.
	 */
	private static LispVal maybeOverflow(LispVal strExpr, List<LispVal> params, int widthIdx, int ovfIdx,
			char directive) {
		if (!fmtHasParam(params, ovfIdx)) {
			return strExpr;
		}
		if (!(fmtParam(params, ovfIdx) instanceof LispInteger ovf)
				|| !(fmtParam(params, widthIdx) instanceof LispInteger w)) {
			throw new UnsupportedOperationException(
					"format: the overflow character of ~" + directive + " requires literal width and character");
		}
		LispSymbol r = new LispSymbol("__fmtovf");
		LispVal over = fmtCall(LispNames.GT, fmtCall(LispNames.LENGTH, r), new LispInteger(w.value()));
		LispVal filled = new LispString(String.valueOf((char) ovf.value()).repeat((int) w.value()));
		LispVal binding = listToCons(List.of(listToCons(List.of(r, strExpr))));
		return listToCons(List.of(new LispSymbol(LispNames.LET), binding, makeIf(over, filled, r)));
	}

	/**
	 * The k-th element of a runtime list: {@code (car base)} /
	 * {@code (car (nthcdr k base))}.
	 */
	private static LispVal carChain(LispVal base, int k) {
		return (k == 0) ? fmtCall(LispNames.CAR, base)
				: fmtCall(LispNames.CAR, fmtCall(LispNames.NTHCDR, new LispInteger(k), base));
	}

	/**
	 * Binds the iteration item temporaries to successive elements of {@code base} around
	 * {@code bodyExpr} (no binding when the body consumed no items).
	 */
	private static LispVal letItems(List<LispSymbol> items, LispVal base, LispVal bodyExpr) {
		if (items.isEmpty()) {
			return bodyExpr;
		}
		List<LispVal> bindings = new java.util.ArrayList<>();
		for (int k = 0; k < items.size(); k++) {
			bindings.add(listToCons(List.of(items.get(k), carChain(base, k))));
		}
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), listToCons(bindings), bodyExpr));
	}

	/**
	 * Builds the {@code ~{str~}} loop over a flat runtime list: each pass binds the
	 * body's item temporaries to the next {@code m} elements, appends the body string to
	 * an accumulator, and advances the cursor by {@code m}; an optional {@code maxExpr}
	 * caps the number of passes.
	 */
	private static LispVal flatLoopExpr(LispSymbol listSym, FmtArgs items, List<FmtOp> body, @Nullable LispVal maxExpr,
			int id) {
		int m = items.position();
		LispSymbol l = new LispSymbol("__fmtl" + id);
		LispSymbol o = new LispSymbol("__fmto" + id);
		LispSymbol c = new LispSymbol("__fmtc" + id);
		boolean hasCut = body.stream().anyMatch(op -> op instanceof FmtCut);
		LispSymbol done = new LispSymbol("__fmtdone" + id);
		List<LispVal> bindings = new java.util.ArrayList<>();
		bindings.add(listToCons(List.of(l, listSym)));
		bindings.add(listToCons(List.of(o, new LispString(""))));
		LispVal test = fmtCall(LispNames.CONSP, l);
		if (hasCut) {
			// A fired ~^ ends the whole flat iteration, not just the current pass.
			bindings.add(listToCons(List.of(done, LispNil.INSTANCE)));
			test = fmtCall(LispNames.AND, test, fmtCall(LispNames.NOT, done));
		}
		if (maxExpr != null) {
			bindings.add(listToCons(List.of(c, new LispInteger(0))));
			test = fmtCall(LispNames.AND, test, fmtCall(LispNames.LT, c, maxExpr));
		}
		LispVal bodyExpr = hasCut ? cutBodyExpr(body, l, done) : opsToExpr(body);
		LispVal append = letItems(items.items(), l,
				fmtCall(LispNames.SETQ, o, fmtCall(LispNames.STRING_CONCAT, o, bodyExpr)));
		LispVal advance = fmtCall(LispNames.SETQ, l,
				(m == 1) ? fmtCall(LispNames.CDR, l) : fmtCall(LispNames.NTHCDR, new LispInteger(m), l));
		List<LispVal> loopParts = new java.util.ArrayList<>(
				List.of(new LispSymbol(LispNames.WHILE), test, append, advance));
		if (maxExpr != null) {
			loopParts.add(fmtCall(LispNames.SETQ, c, fmtCall(LispNames.ADD, c, new LispInteger(1))));
		}
		return listToCons(List.of(new LispSymbol(LispNames.LET), listToCons(bindings), listToCons(loopParts), o));
	}

	/**
	 * Builds the {@code ~:{str~}} loop over a runtime list of sublists: each pass binds
	 * the body's item temporaries to the elements of the next sublist and advances by
	 * one.
	 */
	private static LispVal sublistLoopExpr(LispSymbol listSym, FmtArgs items, List<FmtOp> body,
			@Nullable LispVal maxExpr, int id) {
		LispSymbol l = new LispSymbol("__fmtl" + id);
		LispSymbol o = new LispSymbol("__fmto" + id);
		LispSymbol c = new LispSymbol("__fmtc" + id);
		LispSymbol sub = new LispSymbol("__fmtsl" + id);
		List<LispVal> bindings = new java.util.ArrayList<>();
		bindings.add(listToCons(List.of(l, listSym)));
		bindings.add(listToCons(List.of(o, new LispString(""))));
		LispVal test = fmtCall(LispNames.CONSP, l);
		if (maxExpr != null) {
			bindings.add(listToCons(List.of(c, new LispInteger(0))));
			test = fmtCall(LispNames.AND, test, fmtCall(LispNames.LT, c, maxExpr));
		}
		List<LispVal> innerBindings = new java.util.ArrayList<>();
		innerBindings.add(listToCons(List.of(sub, fmtCall(LispNames.CAR, l))));
		List<LispSymbol> syms = items.items();
		for (int k = 0; k < syms.size(); k++) {
			innerBindings.add(listToCons(List.of(syms.get(k), carChain(sub, k))));
		}
		// A ~^ here ends the current sublist's body only, so no loop-exit flag.
		LispVal bodyExpr = cutBodyExpr(body, sub, null);
		LispVal append = listToCons(List.of(new LispSymbol(LispNames.LET_STAR), listToCons(innerBindings),
				fmtCall(LispNames.SETQ, o, fmtCall(LispNames.STRING_CONCAT, o, bodyExpr))));
		LispVal advance = fmtCall(LispNames.SETQ, l, fmtCall(LispNames.CDR, l));
		List<LispVal> loopParts = new java.util.ArrayList<>(
				List.of(new LispSymbol(LispNames.WHILE), test, append, advance));
		if (maxExpr != null) {
			loopParts.add(fmtCall(LispNames.SETQ, c, fmtCall(LispNames.ADD, c, new LispInteger(1))));
		}
		return listToCons(List.of(new LispSymbol(LispNames.LET), listToCons(bindings), listToCons(loopParts), o));
	}

	private static final String ERROR_ARG_VAR = "__error_arg";

	private static final String SIGNAL_COND_VAR = "__signal_cond";

	private static final String SIGNAL_STREAM_VAR = "__signal_stream";

	/** The rendered-message temp of the restart-mode (signal hook) string designator. */
	private static final String SIG_MSG_VAR = "__sig_msg";

	/** The instance tag of the built-in {@code simple-condition} class. */
	private static final String SIMPLE_CONDITION_TAG = LispLayout.CLASS_TAG_PREFIX + "SIMPLE-CONDITION";

	/** The simple-* condition tags whose slot 0 is the message (format-control). */
	private static final List<String> SIMPLE_CONDITION_TAGS = List.of("%class-SIMPLE-ERROR", SIMPLE_CONDITION_TAG,
			"%class-SIMPLE-WARNING");

	/**
	 * Expands {@code (error datum args...)} through the CL condition designators:
	 * {@code (error "control" args...)} builds the message with the {@code format}
	 * machinery (literal control string, {@code ~a}/{@code ~s}/{@code ~%} supported) and
	 * delegates to {@code (%error message)}; {@code (error 'type :initarg v ...)}
	 * constructs a condition instance of the named class and signals through
	 * {@code (%error-cond condition message)}, where the message is the class's
	 * {@code :report} rendering when one was registered by {@code define-condition} and
	 * the {@code Condition ... was signalled.} shape otherwise; {@code (error obj)}
	 * signals a pre-built condition object (or, when the value turns out to be a string
	 * at runtime, signals it as a plain message).
	 * @param cons the error expression
	 * @return the expanded expression
	 */
	public static LispVal expandError(LispCons cons) {
		return expandError(cons, EMPTY_CLOS_REGISTRY);
	}

	/**
	 * Expands {@code (error ...)} with the class registry that resolves condition types
	 * and their {@code :report} forms; see {@link #expandError(LispCons)}.
	 * @param cons the error expression
	 * @param closRegistry the class registry
	 * @return the expanded expression
	 */
	public static LispVal expandError(LispCons cons, ClosRegistry closRegistry) {
		return expandSignalDesignator(cons, LispNames.ERROR, LispNames.ERROR_INTERNAL, closRegistry);
	}

	/**
	 * Expands {@code (error ...)} like {@link #expandError(LispCons, ClosRegistry)},
	 * optionally with the interpreter-only runtime condition-type dispatch: a non-literal
	 * datum evaluating to a symbol re-enters through the {@code error} function value so
	 * the type designator resolves against the class registry at signal time.
	 * @param cons the error expression
	 * @param closRegistry the class registry
	 * @param runtimeTypeDispatch whether a runtime symbol datum re-dispatches (the
	 * interpreter; the compiled backends keep the plain object-designator expansion)
	 * @return the expanded expression
	 */
	public static LispVal expandError(LispCons cons, ClosRegistry closRegistry, boolean runtimeTypeDispatch) {
		return expandError(cons, closRegistry, runtimeTypeDispatch, false);
	}

	/**
	 * Expands {@code (error ...)} like
	 * {@link #expandError(LispCons, ClosRegistry, boolean)}, optionally with the
	 * restart-mode signal hook: the expansion calls {@code %run-handlers} on the
	 * condition instance BEFORE the throwing terminal, so {@code handler-bind} handlers
	 * run at the signal point without unwinding. Only a restart-mode program (see
	 * {@link #usesRestartSystem}) passes true -- every other program stays
	 * byte-identical.
	 * @param cons the error expression
	 * @param closRegistry the class registry
	 * @param runtimeTypeDispatch whether a runtime symbol datum re-dispatches
	 * @param signalHook whether to run {@code handler-bind} handlers at the signal point
	 * @return the expanded expression
	 */
	public static LispVal expandError(LispCons cons, ClosRegistry closRegistry, boolean runtimeTypeDispatch,
			boolean signalHook) {
		return expandSignalDesignator(cons, LispNames.ERROR, LispNames.ERROR_INTERNAL, closRegistry,
				runtimeTypeDispatch, signalHook);
	}

	/**
	 * Expands {@code (cerror continue-format-control datum args...)} to the equivalent
	 * {@code (error datum args...)}: there is no restart machinery, so the error is not
	 * continuable and the continue format control is dropped (lite semantics).
	 * @param cons the cerror expression
	 * @param closRegistry the class registry
	 * @return the expanded expression
	 */
	public static LispVal expandCerror(LispCons cons, ClosRegistry closRegistry) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3) {
			throw new IllegalArgumentException(
					LispNames.CERROR + " expects a continue format control and a datum: " + cons.print());
		}
		List<LispVal> errorParts = new java.util.ArrayList<>();
		errorParts.add(new LispSymbol(LispNames.ERROR));
		errorParts.addAll(parts.subList(2, parts.size()));
		return expandError((LispCons) listToCons(errorParts), closRegistry);
	}

	/**
	 * Expands {@code (cerror ...)} like {@link #expandCerror(LispCons, ClosRegistry)},
	 * but in restart mode the error becomes REAL {@code cerror}: the equivalent
	 * {@code (restart-case (error datum args...) (continue () :report cfc nil))}, so a
	 * handler (or the {@code continue} function) can resume past it with nil. Outside
	 * restart mode nothing can invoke the restart, so the lite lowering is
	 * behavior-identical and keeps the program byte-identical.
	 * @param cons the cerror expression
	 * @param closRegistry the class registry
	 * @param restartMode whether the program uses the restart system
	 * @return the expanded expression
	 */
	public static LispVal expandCerror(LispCons cons, ClosRegistry closRegistry, boolean restartMode) {
		if (!restartMode) {
			return expandCerror(cons, closRegistry);
		}
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3) {
			throw new IllegalArgumentException(
					LispNames.CERROR + " expects a continue format control and a datum: " + cons.print());
		}
		List<LispVal> errorParts = new java.util.ArrayList<>();
		errorParts.add(new LispSymbol(LispNames.ERROR));
		errorParts.addAll(parts.subList(2, parts.size()));
		LispVal clause = listToCons(List.of(new LispSymbol(LispNames.CONTINUE), LispNil.INSTANCE,
				new LispSymbol(":REPORT"), parts.get(1), LispNil.INSTANCE));
		return listToCons(List.of(new LispSymbol(LispNames.RESTART_CASE), listToCons(errorParts), clause));
	}

	/**
	 * Expands {@code (warn datum args...)} with the same designator surface as
	 * {@link #expandError}, delegating to {@code (%warn message)} which writes
	 * {@code WARNING: message} to standard error and returns nil. Nothing can handle or
	 * muffle the warning (no {@code muffle-warning} restart).
	 * @param cons the warn expression
	 * @return the expanded expression
	 */
	public static LispVal expandWarn(LispCons cons) {
		return expandWarn(cons, EMPTY_CLOS_REGISTRY);
	}

	/**
	 * Expands {@code (warn ...)} with the class registry; see
	 * {@link #expandWarn(LispCons)}.
	 * @param cons the warn expression
	 * @param closRegistry the class registry
	 * @return the expanded expression
	 */
	public static LispVal expandWarn(LispCons cons, ClosRegistry closRegistry) {
		return expandSignalDesignator(cons, LispNames.WARN, LispNames.WARN_INTERNAL, closRegistry);
	}

	/**
	 * Expands {@code (warn ...)} like {@link #expandWarn(LispCons, ClosRegistry)}; in
	 * restart mode ({@code signalHook}) the handlers run at the signal point and the
	 * whole warning is wrapped in a {@code muffle-warning} restart, so
	 * {@code (muffle-warning)} from a handler aborts the pending output (the CL
	 * contract).
	 * @param cons the warn expression
	 * @param closRegistry the class registry
	 * @param signalHook whether to run {@code handler-bind} handlers at the signal point
	 * @return the expanded expression
	 */
	public static LispVal expandWarn(LispCons cons, ClosRegistry closRegistry, boolean signalHook) {
		return expandSignalDesignator(cons, LispNames.WARN, LispNames.WARN_INTERNAL, closRegistry, false, signalHook);
	}

	/**
	 * Expands {@code (signal datum args...)} -- the non-fatal signaling operator, with
	 * the same designator surface as {@link #expandError} -- into
	 * {@code (%signal-cond condition message)}: the condition is raised when a
	 * {@code handler-case} handler is established on the current thread of control and
	 * falls through to nil otherwise (always nil on the WASM backends, which have no
	 * handlers).
	 * @param cons the signal expression
	 * @return the expanded expression
	 */
	public static LispVal expandSignalMacro(LispCons cons) {
		return expandSignalMacro(cons, EMPTY_CLOS_REGISTRY);
	}

	/**
	 * Expands {@code (signal ...)} with the class registry; see
	 * {@link #expandSignalMacro(LispCons)}.
	 * @param cons the signal expression
	 * @param closRegistry the class registry
	 * @return the expanded expression
	 */
	public static LispVal expandSignalMacro(LispCons cons, ClosRegistry closRegistry) {
		return expandSignalDesignator(cons, LispNames.SIGNAL, LispNames.SIGNAL_COND_INTERNAL, closRegistry);
	}

	/**
	 * Expands {@code (signal ...)} like
	 * {@link #expandSignalMacro(LispCons, ClosRegistry)}, optionally with the
	 * restart-mode signal hook (see
	 * {@link #expandError(LispCons, ClosRegistry, boolean, boolean)}).
	 * @param cons the signal expression
	 * @param closRegistry the class registry
	 * @param signalHook whether to run {@code handler-bind} handlers at the signal point
	 * @return the expanded expression
	 */
	public static LispVal expandSignalMacro(LispCons cons, ClosRegistry closRegistry, boolean signalHook) {
		return expandSignalDesignator(cons, LispNames.SIGNAL, LispNames.SIGNAL_COND_INTERNAL, closRegistry, false,
				signalHook);
	}

	// The shared error/warn/signal expansion over the CL condition designators: a
	// literal control string (format-machinery message, no condition object on the
	// %error fast path), a quoted condition-type symbol (typed instance construction),
	// a literal (make-condition ...) argument (rewritten to the typed path), or any
	// other expression (a runtime condition object).
	private static LispVal expandSignalDesignator(LispCons cons, String opName, String internalName,
			ClosRegistry closRegistry) {
		return expandSignalDesignator(cons, opName, internalName, closRegistry, false, false);
	}

	private static LispVal expandSignalDesignator(LispCons cons, String opName, String internalName,
			ClosRegistry closRegistry, boolean runtimeTypeDispatch) {
		return expandSignalDesignator(cons, opName, internalName, closRegistry, runtimeTypeDispatch, false);
	}

	private static LispVal expandSignalDesignator(LispCons cons, String opName, String internalName,
			ClosRegistry closRegistry, boolean runtimeTypeDispatch, boolean signalHook) {
		LispVal expansion = expandSignalDesignatorInner(cons, opName, internalName, closRegistry, runtimeTypeDispatch,
				signalHook);
		if (signalHook && LispNames.WARN_INTERNAL.equals(internalName)) {
			// Restart mode: every warn establishes the muffle-warning restart around
			// the handler run and the output, so (muffle-warning) from a handler
			// returns nil from the warn without printing.
			LispVal clause = listToCons(
					List.of(new LispSymbol(LispNames.MUFFLE_WARNING), LispNil.INSTANCE, LispNil.INSTANCE));
			expansion = listToCons(List.of(new LispSymbol(LispNames.RESTART_CASE), expansion, clause));
		}
		return expansion;
	}

	private static LispVal expandSignalDesignatorInner(LispCons cons, String opName, String internalName,
			ClosRegistry closRegistry, boolean runtimeTypeDispatch, boolean signalHook) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException(opName + " expects a condition designator");
		}
		LispVal datum = parts.get(1);
		if (datum instanceof LispCons mc && mc.car() instanceof LispSymbol mcOp
				&& LispNames.MAKE_CONDITION.equals(mcOp.name()) && mc.cdr() instanceof LispCons mcArgs
				&& quotedSymbol(mcArgs.car()) != null) {
			// (error (make-condition 'type args...)): the type is statically known, so
			// route through the typed path (construction + :report-aware message).
			return expandTypedSignal(opName, internalName, java.util.Objects.requireNonNull(quotedSymbol(mcArgs.car())),
					mc.toList().subList(2, mc.toList().size()), closRegistry, signalHook);
		}
		LispSymbol typeSym = quotedSymbol(datum);
		if (typeSym != null) {
			return expandTypedSignal(opName, internalName, typeSym, parts.subList(2, parts.size()), closRegistry,
					signalHook);
		}
		if (datum instanceof LispString control) {
			return expandStringSignal(opName, internalName, control, parts.subList(2, parts.size()), signalHook);
		}
		if (runtimeTypeDispatch) {
			// Interpreter only: the datum is a runtime value. A SYMBOL value is a
			// condition-type designator (jzon's (error type :format-control ...)
			// helper), so re-enter through the error/signal/warn FUNCTION value, whose
			// rebuilt literal call takes the typed expansion against the then-current
			// class registry. Anything else falls to the object-designator expansion.
			LispSymbol datumVar = new LispSymbol("__sig_datum");
			List<LispVal> argList = new java.util.ArrayList<>();
			argList.add(new LispSymbol(LispNames.LIST));
			argList.addAll(parts.subList(2, parts.size()));
			LispVal symbolCase = listToCons(List.of(new LispSymbol(LispNames.APPLY),
					listToCons(List.of(new LispSymbol(LispNames.FUNCTION), new LispSymbol(opName))), datumVar,
					listToCons(argList)));
			// A runtime STRING value is a format control, so the object-designator
			// expansion gets the arguments to render into it (its own string arm tests
			// stringp first, before this branch's symbol test could see one).
			LispVal objectCase = expandObjectSignal(internalName, datumVar, closRegistry, signalHook,
					formatArgumentList(parts));
			LispVal symbolTest = listToCons(List.of(new LispSymbol(LispNames.AND), callOf(LispNames.SYMBOLP, datumVar),
					callOf(LispNames.NOT, callOf(LispNames.NULL, datumVar))));
			return makeLet(datumVar.name(), datum, makeIf(symbolTest, symbolCase, objectCase));
		}
		if (LispNames.ERROR_INTERNAL.equals(internalName) && !closRegistry.classes().isEmpty() && parts.size() > 2) {
			// Compiled backends: a runtime SYMBOL datum WITH initargs (jzon's (error
			// type :format-control ...) helper, cl-postgres' (error (get-error-type
			// code) :code ...)) dispatches through the shared %error-runtime defun
			// (injected by expandTopLevelDefinitions): inlining a typed expansion per
			// registered class at every call site grew one method past the JVM's 64 KB
			// hard limit at cl-postgres scale. A datum-only call (the lite #'error
			// wrapper, a condition-object re-signal) stays on the object path:
			// constructing a slot-less instance would run its :report over nil slots
			// at signal time.
			List<LispVal> listParts = new java.util.ArrayList<>();
			listParts.add(new LispSymbol(LispNames.LIST));
			listParts.addAll(parts.subList(2, parts.size()));
			return listToCons(List.of(new LispSymbol(LispNames.ERROR_RUNTIME), datum, listToCons(listParts)));
		}
		return expandObjectSignal(internalName, datum, closRegistry, signalHook, formatArgumentList(parts));
	}

	/**
	 * The {@code (list args...)} form of a signal call's arguments after the datum -- the
	 * format-argument list of a datum that is a control string at runtime -- or null when
	 * the call has no such arguments (the datum-only shape, whose expansion must stay
	 * exactly as it was).
	 * @param parts the whole signal call, operator first
	 * @return the argument-list form, or null
	 */
	private static @Nullable LispVal formatArgumentList(List<LispVal> parts) {
		if (parts.size() <= 2) {
			return null;
		}
		List<LispVal> listParts = new java.util.ArrayList<>();
		listParts.add(new LispSymbol(LispNames.LIST));
		listParts.addAll(parts.subList(2, parts.size()));
		return listToCons(listParts);
	}

	/**
	 * The literal-control-string designator: builds the message with the format machinery
	 * and delegates to the internal primitive. {@code error} keeps the plain one-argument
	 * {@code (%error message)} shape (a {@code handler-case} synthesizes the
	 * {@code simple-error} instance from the message when needed); {@code signal} wraps
	 * the message in a {@code simple-condition} instance.
	 */
	private static LispVal expandStringSignal(String opName, String internalName, LispString control,
			List<LispVal> args) {
		return expandStringSignal(opName, internalName, control, args, false);
	}

	private static LispVal expandStringSignal(String opName, String internalName, LispString control,
			List<LispVal> args, boolean signalHook) {
		List<LispVal> bindings = new java.util.ArrayList<>();
		List<LispSymbol> argSyms = new java.util.ArrayList<>();
		for (int i = 0; i < args.size(); i++) {
			LispSymbol g = new LispSymbol(ERROR_ARG_VAR + i);
			argSyms.add(g);
			bindings.add(listToCons(List.of(g, args.get(i))));
		}
		LispVal signalCall;
		if (signalHook) {
			// Restart mode: bind the rendered (unprefixed) message, synthesize the
			// simple-* instance the handlers see -- the same shape a handler-case
			// synthesizes from a plain message -- run the handlers, then reach the
			// unchanged throwing/printing terminal.
			LispSymbol msgVar = new LispSymbol(SIG_MSG_VAR);
			LispSymbol condVar = new LispSymbol(SIGNAL_COND_VAR);
			LispVal message = formatMessagePieces(control.value(), argSyms);
			String tag = switch (internalName) {
				case LispNames.WARN_INTERNAL -> "%class-SIMPLE-WARNING";
				case LispNames.SIGNAL_COND_INTERNAL -> SIMPLE_CONDITION_TAG;
				default -> "%class-SIMPLE-ERROR";
			};
			LispVal terminal = switch (internalName) {
				case LispNames.WARN_INTERNAL -> listToCons(List.of(new LispSymbol(internalName), listToCons(
						List.of(new LispSymbol(LispNames.STRING_CONCAT), new LispString("WARNING: "), msgVar))));
				case LispNames.SIGNAL_COND_INTERNAL ->
					listToCons(List.of(new LispSymbol(internalName), condVar, msgVar));
				default -> listToCons(List.of(new LispSymbol(internalName), msgVar));
			};
			signalCall = makeLet(SIG_MSG_VAR, message,
					makeLet(SIGNAL_COND_VAR, objNew(tag, List.of(msgVar, LispNil.INSTANCE)),
							listToCons(List.of(new LispSymbol(LispNames.PROGN),
									callOf(LispNames.RUN_HANDLERS_INTERNAL, condVar), terminal))));
		}
		else if (LispNames.SIGNAL_COND_INTERNAL.equals(internalName)) {
			// (let ((__signal_cond message)) (%signal-cond (%obj-new
			// '%class-SIMPLE-CONDITION
			// __signal_cond nil) __signal_cond))
			LispVal message = formatMessagePieces(control.value(), argSyms);
			LispSymbol msgVar = new LispSymbol(SIGNAL_COND_VAR);
			LispVal instance = objNew(SIMPLE_CONDITION_TAG, List.of(msgVar, LispNil.INSTANCE));
			signalCall = makeLet(SIGNAL_COND_VAR, message,
					listToCons(List.of(new LispSymbol(internalName), instance, msgVar)));
		}
		else {
			// warn prefixes the rendered message so %warn stays a plain write
			// primitive.
			String controlText = LispNames.WARN_INTERNAL.equals(internalName) ? "WARNING: " + control.value()
					: control.value();
			LispVal message = formatMessagePieces(controlText, argSyms);
			signalCall = listToCons(List.of(new LispSymbol(internalName), message));
		}
		if (bindings.isEmpty()) {
			return signalCall;
		}
		List<LispVal> letParts = new java.util.ArrayList<>();
		letParts.add(new LispSymbol(LispNames.LET));
		letParts.add(listToCons(bindings));
		letParts.add(signalCall);
		return listToCons(letParts);
	}

	/**
	 * The quoted-condition-type designator {@code (error 'type :initarg v ...)}: binds
	 * the argument expressions to temps (evaluated once, left to right), constructs the
	 * condition instance -- through the registry's slot layout when the class is known
	 * and the arguments are keyword pairs, as a raw tagged list otherwise -- and signals
	 * it with a message from the class's {@code :report} (a literal string, or a
	 * {@code (lambda (condition stream) ...)} rendered into a string stream) or the
	 * legacy {@code Condition ~s was signalled.} shape when no report is registered.
	 * {@code warn} skips the construction unless a lambda report needs the instance.
	 */
	private static LispVal expandTypedSignal(String opName, String internalName, LispSymbol typeSym, List<LispVal> args,
			ClosRegistry closRegistry) {
		return expandTypedSignal(opName, internalName, typeSym, args, closRegistry, false);
	}

	private static LispVal expandTypedSignal(String opName, String internalName, LispSymbol typeSym, List<LispVal> args,
			ClosRegistry closRegistry, boolean signalHook) {
		List<LispVal> bindings = new java.util.ArrayList<>();
		List<LispVal> items = new java.util.ArrayList<>();
		ClosRegistry.ClassInfo cls = closRegistry.findClass(typeSym.name());
		LispVal construct = buildTypedConstruct(typeSym, args, cls, bindings, items);
		LispVal report = cls == null ? null : closRegistry.findConditionReport(cls.name());
		boolean warn = LispNames.WARN_INTERNAL.equals(internalName);
		// A class with no report of its OWN still reports -- through an ancestor's, or
		// through the simple-condition family's format-control -- and the generated
		// renderer is what knows which. Routing the message through it here is what keeps
		// an uncaught signal's text and (format t "~a" c) identical for the same
		// condition.
		boolean routeReport = report == null && closRegistry.routesConditionReports();
		LispSymbol condVar = new LispSymbol(SIGNAL_COND_VAR);
		boolean needsInstance = !warn || signalHook || routeReport
				|| (report != null && !(report instanceof LispString));
		if (needsInstance) {
			bindings.add(listToCons(List.of(condVar, construct)));
		}
		LispVal message;
		if (report instanceof LispString reportString) {
			message = warn ? new LispString("WARNING: " + reportString.value()) : reportString;
		}
		else if (report != null) {
			LispSymbol streamVar = new LispSymbol(SIGNAL_STREAM_VAR);
			LispVal rendered = listToCons(
					List.of(new LispSymbol(LispNames.WITH_OUTPUT_TO_STRING), listToCons(List.<LispVal>of(streamVar)),
							listToCons(List.of(new LispSymbol(LispNames.FUNCALL), report, condVar, streamVar))));
			message = warn
					? listToCons(
							List.of(new LispSymbol(LispNames.STRING_CONCAT), new LispString("WARNING: "), rendered))
					: rendered;
		}
		else if (routeReport) {
			// The fallback is the same text this site signalled before there was a
			// renderer, so a class the renderer does not cover (no report anywhere, no
			// format-control) is unchanged, and so is a covered one whose format-control
			// is nil at runtime.
			LispVal rendered = conditionReportOr(condVar, suppliedFormatControl(cls, items) instanceof LispVal supplied
					? supplied : legacySignalMessage(typeSym, items, bindings, false));
			message = warn
					? listToCons(
							List.of(new LispSymbol(LispNames.STRING_CONCAT), new LispString("WARNING: "), rendered))
					: rendered;
		}
		else if (suppliedFormatControl(cls, items) instanceof LispVal formatControl) {
			// A simple-* style class with a supplied :format-control: the message is
			// its value (lite: :format-arguments are carried in the instance but not
			// rendered into the message), preserving the (error (make-condition
			// 'simple-error :format-control "...")) idiom's output.
			message = warn ? listToCons(
					List.of(new LispSymbol(LispNames.STRING_CONCAT), new LispString("WARNING: "), formatControl))
					: formatControl;
		}
		else {
			message = legacySignalMessage(typeSym, items, bindings, warn);
		}
		// The two-argument condition-carrying internal: %error maps to %error-cond
		// (signal already is %signal-cond; warn stays the one-argument %warn).
		String condInternal = LispNames.ERROR_INTERNAL.equals(internalName) ? LispNames.ERROR_COND_INTERNAL
				: internalName;
		LispVal signalCall = warn ? listToCons(List.of(new LispSymbol(internalName), message))
				: listToCons(List.of(new LispSymbol(condInternal), condVar, message));
		if (signalHook) {
			// Restart mode: run the handler-bind handlers on the instance at the
			// signal point, before the throwing/printing terminal.
			signalCall = listToCons(List.of(new LispSymbol(LispNames.PROGN),
					callOf(LispNames.RUN_HANDLERS_INTERNAL, condVar), signalCall));
		}
		if (bindings.isEmpty()) {
			return signalCall;
		}
		List<LispVal> letParts = new java.util.ArrayList<>();
		letParts.add(new LispSymbol(LispNames.LET_STAR));
		letParts.add(listToCons(bindings));
		letParts.add(signalCall);
		return listToCons(letParts);
	}

	/**
	 * The pre-condition-system stopgap message of a typed signal whose class reports
	 * nothing: {@code "Condition ~s was signalled."} formatted over
	 * {@code (list 'type args...)}. Kept byte-identical because it is the message every
	 * report-less condition has always signalled.
	 */
	private static LispVal legacySignalMessage(LispSymbol typeSym, List<LispVal> items, List<LispVal> bindings,
			boolean warn) {
		List<LispVal> msgListParts = new java.util.ArrayList<>();
		msgListParts.add(new LispSymbol(LispNames.LIST));
		msgListParts.add(listToCons(List.of(new LispSymbol(LispNames.QUOTE), typeSym)));
		msgListParts.addAll(items);
		LispSymbol msgVar = new LispSymbol(ERROR_ARG_VAR + "m");
		bindings.add(listToCons(List.of(msgVar, listToCons(msgListParts))));
		String control = warn ? "WARNING: Condition ~s was signalled." : "Condition ~s was signalled.";
		return formatMessagePieces(control, List.of(msgVar));
	}

	private static final String IGNORE_ERRORS_COND_VAR = "__ignore_errors_cond";

	/**
	 * Expands {@code (ignore-errors form...)} into {@code (handler-case (progn form...)
	 * (error (c) (values nil c)))}: an error signaled during the forms yields nil (with
	 * the condition as the syntactic-tier secondary value). Interpreter/JVM only, like
	 * {@code handler-case}.
	 * @param cons the ignore-errors expression
	 * @return the expanded expression
	 */
	public static LispVal expandIgnoreErrors(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispSymbol condVar = new LispSymbol(IGNORE_ERRORS_COND_VAR);
		LispVal valuesForm = listToCons(List.of(new LispSymbol("VALUES"), LispNil.INSTANCE, condVar));
		LispVal clause = listToCons(
				List.of(new LispSymbol("ERROR"), listToCons(List.<LispVal>of(condVar)), valuesForm));
		return listToCons(
				List.of(new LispSymbol(LispNames.HANDLER_CASE), prognOrNil(parts.subList(1, parts.size())), clause));
	}

	/**
	 * Builds the condition-type test of a {@code handler-case} clause: the ordinary
	 * {@code makeTypeTest} (built-in type specifiers plus registered classes), falling
	 * back to an exact instance-tag equality test for a type name the registry does not
	 * know (e.g. a condition type defined later or in an unloaded library) instead of
	 * rejecting the clause.
	 * @param value the (temp-bound) condition value form
	 * @param typeSpec the clause's type specifier
	 * @param closRegistry the class registry
	 * @return a truthy test form
	 */
	public static LispVal makeHandlerTypeTest(LispVal value, LispVal typeSpec, ClosRegistry closRegistry) {
		try {
			return makeTypeTest(value, typeSpec, closRegistry);
		}
		catch (IllegalArgumentException unknownType) {
			if (typeSpec instanceof LispSymbol sym) {
				return objIs(value, List.of(LispLayout.CLASS_TAG_PREFIX + sym.name()));
			}
			throw unknownType;
		}
	}

	/**
	 * The supplied {@code :format-control} expression (a temp) of a typed signal whose
	 * class carries a {@code format-control} slot, or null. Only keyword-paired arguments
	 * qualify (in the non-pair fallback the items are all temps, so no keyword literal
	 * matches).
	 */
	private static @Nullable LispVal suppliedFormatControl(ClosRegistry.@Nullable ClassInfo cls, List<LispVal> items) {
		if (cls == null || cls.slots().stream().noneMatch(s -> "FORMAT-CONTROL".equals(s.baseName()))) {
			return null;
		}
		for (int i = 0; i + 1 < items.size(); i += 2) {
			if (items.get(i) instanceof LispSymbol k && k.isKeyword() && ":FORMAT-CONTROL".equals(k.name())) {
				return items.get(i + 1);
			}
		}
		return null;
	}

	/**
	 * The condition-object designator {@code (error obj)}: binds the value, signals it as
	 * a plain message when it is a string at runtime, and otherwise signals the instance
	 * with its carried message -- slot 0 for the simple-* classes, the
	 * {@code Condition of type ... was signalled.} shape derived from the instance tag
	 * otherwise. When the program routes condition reports the message is the datum's
	 * REPORT, rendered by the generated renderer -- the type is not statically known
	 * here, so a runtime dispatch is the only thing that can consult it -- with the
	 * shapes above as the fallback for a class that reports nothing.
	 */
	private static LispVal expandObjectSignal(String internalName, LispVal datumExpr, ClosRegistry closRegistry,
			boolean signalHook) {
		return expandObjectSignal(internalName, datumExpr, closRegistry, signalHook, null);
	}

	/**
	 * The condition-object designator with the call's remaining arguments (see
	 * {@link #expandObjectSignal(String, LispVal, ClosRegistry, boolean)}). Per CL a
	 * STRING datum is a format control and the rest are its format arguments, whatever
	 * the datum's shape in the source -- so when the datum turns out to be a string at
	 * runtime, the message is the control RENDERED over those arguments
	 * ({@code %fmt-render}, the same renderer a computed {@code (format nil ctrl args)}
	 * uses) instead of the raw control with its directives standing (todo-220).
	 * <p>
	 * The rendering is EAGER, exactly as the literal-control designator
	 * ({@link #expandStringSignal}) renders at expansion time: the instance a handler
	 * sees carries the rendered text in {@code format-control} and nil
	 * {@code format-arguments}, so both spellings of the same signal produce the same
	 * condition. Storing the raw control plus the argument list instead would be closer
	 * to CLHS, but only the runtime path could do it -- the literal path renders without
	 * a renderer in the artifact, which is the whole reason there are two paths
	 * ({@code .kb/format.md}) -- and one operator with two condition shapes is worse than
	 * one shared deviation.
	 * @param internalName the internal signalling primitive
	 * @param datumExpr the datum expression
	 * @param closRegistry the class registry
	 * @param signalHook whether to run {@code handler-bind} handlers at the signal point
	 * @param formatArgs a form answering the format-argument LIST, or null when the call
	 * has no arguments after the datum (then the expansion is unchanged)
	 */
	private static LispVal expandObjectSignal(String internalName, LispVal datumExpr, ClosRegistry closRegistry,
			boolean signalHook, @Nullable LispVal formatArgs) {
		boolean warn = LispNames.WARN_INTERNAL.equals(internalName);
		LispSymbol condVar = new LispSymbol(SIGNAL_COND_VAR);
		// The string arm's message: the datum itself when nothing can be rendered into
		// it, the temp holding the rendered text otherwise (bound around the whole arm
		// below, so the renderer runs once).
		LispVal stringMessage = formatArgs == null ? condVar : new LispSymbol(SIG_MSG_VAR);
		LispVal tag = objTag(condVar);
		LispVal slotMsg = objRef(condVar, 0);
		LispVal isSimpleWithMessage = listToCons(List.of(new LispSymbol(LispNames.AND),
				objIs(condVar, SIMPLE_CONDITION_TAGS), callOf(LispNames.STRINGP, slotMsg)));
		LispVal typeMessage = listToCons(List.of(
				new LispSymbol(LispNames.STRING_CONCAT), listToCons(List.of(new LispSymbol(LispNames.STRING_CONCAT),
						new LispString("Condition of type "), listToCons(List.of(new LispSymbol(LispNames.SUBSEQ),
								callOf(LispNames.PRIN1_TO_STRING, tag), new LispInteger(7))))),
				new LispString(" was signalled.")));
		// A value that is not an instance at all has no tag to name, so it signals as its
		// own printed representation rather than off the end of a nil tag.
		LispVal fallback = makeIf(listToCons(List.of(new LispSymbol(LispNames.OBJ_P), condVar)), typeMessage,
				callOf(LispNames.PRINC_TO_STRING, condVar));
		LispVal message = makeIf(isSimpleWithMessage, slotMsg, fallback);
		if (closRegistry.routesConditionReports()) {
			message = conditionReportOr(condVar, message);
		}
		LispVal stringCase;
		LispVal conditionCase;
		if (warn) {
			LispVal prefixed = listToCons(
					List.of(new LispSymbol(LispNames.STRING_CONCAT), new LispString("WARNING: "), stringMessage));
			stringCase = listToCons(List.of(new LispSymbol(internalName), prefixed));
			conditionCase = listToCons(List.of(new LispSymbol(internalName), listToCons(
					List.of(new LispSymbol(LispNames.STRING_CONCAT), new LispString("WARNING: "), message))));
		}
		else if (LispNames.SIGNAL_COND_INTERNAL.equals(internalName)) {
			LispVal instance = objNew(SIMPLE_CONDITION_TAG, List.of(stringMessage, LispNil.INSTANCE));
			stringCase = listToCons(List.of(new LispSymbol(internalName), instance, stringMessage));
			conditionCase = listToCons(List.of(new LispSymbol(internalName), condVar, message));
		}
		else {
			stringCase = listToCons(List.of(new LispSymbol(LispNames.ERROR_INTERNAL), stringMessage));
			conditionCase = listToCons(List.of(new LispSymbol(LispNames.ERROR_COND_INTERNAL), condVar, message));
		}
		// A runtime SYMBOL datum (the compiled #'error/#'signal/#'warn wrappers forward
		// the datum only) signals its name as a plain message rather than casting the
		// symbol as a condition instance.
		LispVal symbolMessage = callOf(LispNames.PRINC_TO_STRING, condVar);
		LispVal symbolCase;
		if (warn) {
			symbolCase = listToCons(List.of(new LispSymbol(internalName), listToCons(
					List.of(new LispSymbol(LispNames.STRING_CONCAT), new LispString("WARNING: "), symbolMessage))));
		}
		else if (LispNames.SIGNAL_COND_INTERNAL.equals(internalName)) {
			LispVal instance = objNew(SIMPLE_CONDITION_TAG, List.of(symbolMessage, LispNil.INSTANCE));
			symbolCase = listToCons(List.of(new LispSymbol(internalName), instance, symbolMessage));
		}
		else {
			symbolCase = listToCons(List.of(new LispSymbol(LispNames.ERROR_INTERNAL), symbolMessage));
		}
		if (signalHook) {
			// Restart mode: run the handler-bind handlers at the signal point. The
			// string/symbol arms synthesize the same simple-* instance a handler-case
			// would (a fresh instance -- no identity requirement with the one an
			// unhandled signal later carries); the condition arm passes the datum's
			// instance itself.
			String simpleTag = warn ? "%class-SIMPLE-WARNING" : LispNames.SIGNAL_COND_INTERNAL.equals(internalName)
					? SIMPLE_CONDITION_TAG : "%class-SIMPLE-ERROR";
			stringCase = listToCons(List.of(new LispSymbol(LispNames.PROGN), callOf(LispNames.RUN_HANDLERS_INTERNAL,
					objNew(simpleTag, List.of(stringMessage, LispNil.INSTANCE))), stringCase));
			symbolCase = listToCons(List.of(new LispSymbol(LispNames.PROGN),
					callOf(LispNames.RUN_HANDLERS_INTERNAL,
							objNew(simpleTag, List.of(callOf(LispNames.PRINC_TO_STRING, condVar), LispNil.INSTANCE))),
					symbolCase));
			conditionCase = listToCons(List.of(new LispSymbol(LispNames.PROGN),
					callOf(LispNames.RUN_HANDLERS_INTERNAL, condVar), conditionCase));
		}
		if (formatArgs != null) {
			// Rendered once, around the whole string arm (the restart-mode hook reads the
			// message too). The argument forms are evaluated only on this arm: a datum
			// that is not a string carries no format arguments, so the expansion of every
			// other arm -- and of every call with a datum only -- is unchanged.
			stringCase = makeLet(SIG_MSG_VAR, FormatRenderer.call(condVar, formatArgs), stringCase);
		}
		return makeLet(SIGNAL_COND_VAR, datumExpr, makeIf(callOf(LispNames.STRINGP, condVar), stringCase,
				makeIf(callOf(LispNames.SYMBOLP, condVar), symbolCase, conditionCase)));
	}

	/**
	 * Builds the condition-instance construction expression of the typed
	 * {@code error}/{@code signal}/{@code make-condition} paths: the argument expressions
	 * are bound to temps appended to {@code bindings} (evaluated once, left to right;
	 * literal keywords stay in place) and mirrored into {@code items}. When the class is
	 * known and the arguments are keyword pairs, the initargs are mapped onto the
	 * registry's slot layout (missing slots take their {@code :initform}); otherwise the
	 * instance is the raw tagged list {@code (list '%class-<name>
	 * items...)}.
	 */
	private static LispVal buildTypedConstruct(LispSymbol typeSym, List<LispVal> args,
			ClosRegistry.@Nullable ClassInfo cls, List<LispVal> bindings, List<LispVal> items) {
		boolean pairs = args.size() % 2 == 0;
		for (int i = 0; pairs && i < args.size(); i += 2) {
			pairs = args.get(i) instanceof LispSymbol k && k.isKeyword();
		}
		for (int i = 0; i < args.size(); i++) {
			if (pairs && i % 2 == 0) {
				items.add(args.get(i));
				continue;
			}
			LispSymbol g = new LispSymbol(ERROR_ARG_VAR + i);
			bindings.add(listToCons(List.of(g, args.get(i))));
			items.add(g);
		}
		if (cls != null && pairs) {
			// Initarg matching is by exact name: the reader upcases every source
			// initarg, and slot.initargKeyword() is built from the upcased slot name
			// (ClosRegistry.SlotSpec / parseDefclassSlot), so both sides agree.
			java.util.Map<String, LispVal> byInitarg = new java.util.LinkedHashMap<>();
			for (int i = 0; i + 1 < items.size(); i += 2) {
				byInitarg.put(((LispSymbol) items.get(i)).name(), items.get(i + 1));
			}
			List<LispVal> slotValues = new java.util.ArrayList<>();
			for (ClosRegistry.SlotSpec slot : cls.slots()) {
				LispVal supplied = byInitarg.get(slot.initargKeyword());
				slotValues.add(supplied != null ? supplied : slot.initform());
			}
			return objNew(LispLayout.CLASS_TAG_PREFIX + cls.name(), slotValues);
		}
		if (cls == null) {
			// An UNDEFINED condition type: no class of that name is registered anywhere
			// (a library naming a sibling package's condition unqualified, e.g.
			// cl-postgres' 'protocol-error, whose real definition is
			// cl-postgres-error:protocol-violation). There is no layout to build, so the
			// signal degrades to a plain simple-condition naming the type -- the shape
			// the symbol designator already produces. The argument temps stay bound, so
			// their side effects still happen exactly once. A COMPILE error here would
			// make one cold, never-taken branch unbuildable.
			return objNew(SIMPLE_CONDITION_TAG,
					List.of(new LispString("Condition " + typeSym.name() + " was signalled."), LispNil.INSTANCE));
		}
		// Arguments that are not initarg pairs: the values fill the layout positionally
		// (surplus ones are evaluated and dropped by %obj-new). The tag comes from the
		// REGISTERED spelling.
		return objNew(LispLayout.CLASS_TAG_PREFIX + cls.name(), items);
	}

	/**
	 * Builds the message expression of a signal expansion: the format-machinery pieces of
	 * the (literal) control text over already-bound argument temps, folded into nested
	 * {@code %string-concat} calls (left-associative), as the {@code format nil}
	 * destination does.
	 */
	private static LispVal formatMessagePieces(String controlText, List<LispSymbol> argSyms) {
		List<FmtOp> parsed;
		try {
			parsed = new FmtParser(controlText).parseTop(FmtArgs.forTemps(argSyms));
		}
		catch (UnsupportedOperationException unsupportedDirective) {
			// A directive the static expansion cannot lower (justification ~<, ~@?, an
			// uneven ~[) falls back to the runtime renderer, exactly as expandFormat
			// does -- a condition message must never be the reason a library fails to
			// COMPILE (cl-ppcre's hyperdoc printer carries ~< on a cold branch).
			List<LispVal> renderArgs = new java.util.ArrayList<>();
			renderArgs.add(new LispSymbol(LispNames.LIST));
			renderArgs.addAll(argSyms);
			return FormatRenderer.call(new LispString(controlText), listToCons(renderArgs));
		}
		List<LispVal> pieces = opsToPieces(parsed);
		LispVal message = pieces.isEmpty() ? new LispString("") : pieces.get(0);
		for (int i = 1; i < pieces.size(); i++) {
			message = listToCons(List.of(new LispSymbol(LispNames.STRING_CONCAT), message, pieces.get(i)));
		}
		return message;
	}

	/**
	 * Expands {@code (mod a b)} into a {@code rem}-based form whose result takes the sign
	 * of the divisor (Common Lisp modulo), reusing the {@code rem}, {@code *}, {@code <}
	 * and {@code +} primitives:
	 * {@code (let* ((a' a) (b' b) (r (rem a' b'))) (if (< (* r b') 0) (+ r b') r))}. Each
	 * operand is evaluated exactly once.
	 * @param cons the mod expression
	 * @return the expanded expression
	 */
	public static LispVal expandMod(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispSymbol av = new LispSymbol("__mod_a");
		LispSymbol bv = new LispSymbol("__mod_b");
		LispSymbol rv = new LispSymbol("__mod_r");
		LispVal remExpr = listToCons(List.of(new LispSymbol(LispNames.REM), av, bv));
		LispVal bindings = listToCons(List.of(listToCons(List.of(av, parts.get(1))),
				listToCons(List.of(bv, parts.get(2))), listToCons(List.of(rv, remExpr))));
		// mod differs from rem only when the remainder and divisor have opposite signs
		// (then add the divisor). The sign comparison multiplies the signums rather than
		// (* r b) directly, which would overflow the WASM i31 range for large operands
		// and
		// spuriously trigger the correction.
		LispVal sgnR = listToCons(List.of(new LispSymbol(LispNames.SIGNUM), rv));
		LispVal sgnB = listToCons(List.of(new LispSymbol(LispNames.SIGNUM), bv));
		LispVal product = listToCons(List.of(new LispSymbol(LispNames.MUL), sgnR, sgnB));
		LispVal test = listToCons(List.of(new LispSymbol(LispNames.LT), product, new LispInteger(0)));
		LispVal corrected = listToCons(List.of(new LispSymbol(LispNames.ADD), rv, bv));
		LispVal body = makeIf(test, corrected, rv);
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), bindings, body));
	}

	/**
	 * Expands a variadic numeric comparison (= &lt; &gt; &lt;= &gt;=) into nested binary
	 * comparisons so the compilers can reuse the binary comparison code. A two-argument
	 * comparison is left for the caller to compile directly. For {@code n >= 3} arguments
	 * the result is
	 * {@code (let* ((g1 a1) ... (gn an)) (and (op g1 g2) ... (op g(n-1) gn)))},
	 * evaluating each argument exactly once; a single argument expands to
	 * {@code (progn a1 t)}.
	 * @param cons the comparison expression
	 * @return the expanded expression
	 */
	public static LispVal expandComparison(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal op = parts.get(0);
		int n = parts.size() - 1;
		if (n <= 0) {
			throw new IllegalArgumentException(((LispSymbol) op).name() + " requires at least one argument");
		}
		if (n == 1) {
			return makeProgn(List.of(parts.get(1), LispTrue.INSTANCE));
		}
		List<LispVal> bindings = new java.util.ArrayList<>();
		List<LispVal> gsyms = new java.util.ArrayList<>();
		for (int i = 1; i <= n; i++) {
			LispSymbol g = new LispSymbol("__cmp" + i);
			gsyms.add(g);
			bindings.add(listToCons(List.of(g, parts.get(i))));
		}
		List<LispVal> andParts = new java.util.ArrayList<>();
		andParts.add(new LispSymbol(LispNames.AND));
		for (int i = 0; i + 1 < gsyms.size(); i++) {
			andParts.add(listToCons(List.of(op, gsyms.get(i), gsyms.get(i + 1))));
		}
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), listToCons(bindings), listToCons(andParts)));
	}

	/**
	 * Expands a variadic associative reduction (min max gcd lcm) into a left fold of
	 * binary applications, e.g. {@code (min a b c)} becomes {@code (min (min a b) c)}. A
	 * two-argument call is left for the caller to compile directly. The identity cases
	 * follow Common Lisp: {@code (gcd)} is 0, {@code (lcm)} is 1, a single argument to
	 * {@code gcd}/{@code lcm} is its absolute value, and a single argument to
	 * {@code min}/{@code max} is itself.
	 * @param cons the reduction expression
	 * @return the expanded expression
	 */
	public static LispVal expandReduction(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal op = parts.get(0);
		String name = ((LispSymbol) op).name();
		int n = parts.size() - 1;
		boolean gcdLcm = LispNames.GCD.equals(name) || LispNames.LCM.equals(name);
		if (n == 0) {
			if (LispNames.GCD.equals(name) || LispNames.LOGIOR.equals(name) || LispNames.LOGXOR.equals(name)) {
				return new LispInteger(0);
			}
			if (LispNames.LCM.equals(name)) {
				return new LispInteger(1);
			}
			if (LispNames.LOGAND.equals(name)) {
				return new LispInteger(-1);
			}
			throw new IllegalArgumentException(name + " requires at least one argument");
		}
		if (n == 1) {
			return gcdLcm ? listToCons(List.of(new LispSymbol(LispNames.ABS), parts.get(1))) : parts.get(1);
		}
		LispVal acc = listToCons(List.of(op, parts.get(1), parts.get(2)));
		for (int i = 3; i <= n; i++) {
			acc = listToCons(List.of(op, acc, parts.get(i)));
		}
		return acc;
	}

	/**
	 * Expands (list* a b ... z) into nested cons cells whose final tail is the last
	 * argument: {@code (list* a b c) -> (cons a (cons b c))}. A single argument expands
	 * to itself.
	 * @param cons the list* expression
	 * @return the expanded expression
	 */
	public static LispVal expandListStar(LispCons cons) {
		List<LispVal> parts = cons.toList();
		int n = parts.size() - 1;
		if (n == 0) {
			throw new IllegalArgumentException("list* requires at least one argument");
		}
		// The last argument becomes the tail; cons the preceding ones onto it.
		LispVal result = parts.get(n);
		for (int i = n - 1; i >= 1; i--) {
			result = listToCons(List.of(new LispSymbol(LispNames.CONS), parts.get(i), result));
		}
		return result;
	}

	/**
	 * Expands (acons key value alist) into (cons (cons key value) alist).
	 * @param cons the acons expression
	 * @return the expanded expression
	 */
	public static LispVal expandAcons(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal pair = listToCons(List.of(new LispSymbol(LispNames.CONS), parts.get(1), parts.get(2)));
		return listToCons(List.of(new LispSymbol(LispNames.CONS), pair, parts.get(3)));
	}

	/**
	 * Expands (endp x) into (null x). The Common Lisp improper-list error is relaxed.
	 * @param cons the endp expression
	 * @return the expanded expression
	 */
	public static LispVal expandEndp(LispCons cons) {
		return callOf(LispNames.NULL, cons.toList().get(1));
	}

	/**
	 * Expands (elt seq n) into a runtime dispatch on the sequence type: {@code char} for
	 * a string, {@code nth} for a list.
	 * @param cons the elt expression
	 * @return the expanded expression
	 */
	public static LispVal expandElt(LispCons cons) {
		return expandElt(cons, true);
	}

	/**
	 * Like {@link #expandElt(LispCons)}, but lets a backend drop the {@code aref} arm
	 * when no array can exist in this program (see
	 * {@link #expandCoerce(LispCons, boolean)} for the rule and who passes what).
	 * @param cons the elt expression
	 * @param arraysExist whether a general array can exist in this program
	 * @return the expanded expression
	 */
	public static LispVal expandElt(LispCons cons, boolean arraysExist) {
		List<LispVal> parts = cons.toList();
		LispSymbol seq = new LispSymbol("__elt_seq");
		LispSymbol idx = new LispSymbol("__elt_idx");
		LispVal bindings = listToCons(
				List.of(listToCons(List.of(seq, parts.get(1))), listToCons(List.of(idx, parts.get(2)))));
		LispVal stringCase = listToCons(List.of(new LispSymbol(LispNames.CHAR), seq, idx));
		LispVal listCase = listToCons(List.of(new LispSymbol(LispNames.NTH), idx, seq));
		// A non-string, non-list sequence is an array: read it with aref (nil counts as a
		// list here, so listp -- not consp -- guards the list case). With no array in the
		// program that arm cannot be taken, so the dispatch collapses to the list read.
		LispVal arrayCase = listToCons(List.of(new LispSymbol(LispNames.AREF), seq, idx));
		LispVal listOrArray = arraysExist
				? makeIf(listToCons(List.of(new LispSymbol(LispNames.LISTP), seq)), listCase, arrayCase) : listCase;
		LispVal body = makeIf(listToCons(List.of(new LispSymbol(LispNames.STRINGP), seq)), stringCase, listOrArray);
		return listToCons(List.of(new LispSymbol(LispNames.LET), bindings, body));
	}

	/**
	 * Expands (vector e1 ... en) into a {@code make-array} + {@code %aset} sequence
	 * building a fresh rank-1 array, evaluating the elements left to right.
	 * @param cons the vector expression
	 * @return the expanded expression
	 */
	public static LispVal expandVector(LispCons cons) {
		List<LispVal> parts = cons.toList();
		int n = parts.size() - 1;
		LispSymbol v = new LispSymbol("__vector_v");
		LispVal make = listToCons(List.of(new LispSymbol(LispNames.MAKE_ARRAY), new LispInteger(n)));
		List<LispVal> letParts = new java.util.ArrayList<>();
		letParts.add(new LispSymbol(LispNames.LET));
		letParts.add(listToCons(List.of(listToCons(List.of(v, make)))));
		for (int i = 0; i < n; i++) {
			letParts.add(listToCons(List.of(new LispSymbol(LispNames.ASET), v, new LispInteger(i), parts.get(i + 1))));
		}
		letParts.add(v);
		return listToCons(letParts);
	}

	/**
	 * Expands (svref vec i) into (aref vec i): a simple vector is a rank-1 array, so
	 * svref is aref restricted to one subscript.
	 * @param cons the svref expression
	 * @return the expanded expression
	 */
	public static LispVal expandSvref(LispCons cons) {
		List<LispVal> parts = cons.toList();
		return listToCons(List.of(new LispSymbol(LispNames.AREF), parts.get(1), parts.get(2)));
	}

	/**
	 * Expands (array-rank array) into (length (array-dimensions array)).
	 * @param cons the array-rank expression
	 * @return the expanded expression
	 */
	public static LispVal expandArrayRank(LispCons cons) {
		List<LispVal> parts = cons.toList();
		return callOf(LispNames.LENGTH, callOf(LispNames.ARRAY_DIMENSIONS, parts.get(1)));
	}

	/**
	 * Expands (array-dimension array axis) into an (nth axis (array-dimensions array))
	 * lookup, evaluating the array before the axis.
	 * @param cons the array-dimension expression
	 * @return the expanded expression
	 */
	public static LispVal expandArrayDimension(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispSymbol dims = new LispSymbol("__arraydim_dims");
		LispSymbol axis = new LispSymbol("__arraydim_axis");
		LispVal bindings = listToCons(
				List.of(listToCons(List.of(dims, callOf(LispNames.ARRAY_DIMENSIONS, parts.get(1)))),
						listToCons(List.of(axis, parts.get(2)))));
		LispVal body = listToCons(List.of(new LispSymbol(LispNames.NTH), axis, dims));
		return listToCons(List.of(new LispSymbol(LispNames.LET), bindings, body));
	}

	/**
	 * Expands (array-total-size array) into a {@code do} loop multiplying every dimension
	 * size returned by {@code array-dimensions}, so it works for any rank.
	 * @param cons the array-total-size expression
	 * @return the expanded expression
	 */
	public static LispVal expandArrayTotalSize(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispSymbol d = new LispSymbol("__arraysize_d");
		LispSymbol n = new LispSymbol("__arraysize_n");
		// (do ((d (array-dimensions a) (cdr d)) (n 1 (* n (car d)))) ((null d) n))
		LispVal dSpec = listToCons(
				List.of(d, callOf(LispNames.ARRAY_DIMENSIONS, parts.get(1)), callOf(LispNames.CDR, d)));
		LispVal nSpec = listToCons(List.of(n, new LispInteger(1),
				listToCons(List.of(new LispSymbol(LispNames.MUL), n, callOf(LispNames.CAR, d)))));
		LispVal end = listToCons(List.of(callOf(LispNames.NULL, d), n));
		return listToCons(List.of(new LispSymbol(LispNames.DO), listToCons(List.of(dSpec, nSpec)), end));
	}

	/**
	 * Expands (array-element-type array) into {@code (progn array t)} on the compile
	 * path: element types are not tracked, so the answer is always the symbol {@code t}
	 * (matching the interpreter built-in), and the array expression is kept only for its
	 * evaluation.
	 * @param cons the array-element-type expression
	 * @return the expanded expression
	 */
	public static LispVal expandArrayElementType(LispCons cons) {
		List<LispVal> parts = cons.toList();
		return listToCons(List.of(new LispSymbol(LispNames.PROGN), parts.get(1), LispTrue.INSTANCE));
	}

	/**
	 * Expands (array-row-major-index array sub...) into the Horner fold of the subscripts
	 * over {@code array-dimensions}: {@code ((s0 * d1 + s1) * d2 + s2) ...}, so any
	 * static subscript count works. The array's dimensions and the subscripts are bound
	 * in a {@code let*} first (left-to-right, single evaluation).
	 * @param cons the array-row-major-index expression
	 * @return the expanded expression
	 */
	public static LispVal expandArrayRowMajorIndex(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3) {
			throw new UnsupportedOperationException(
					LispNames.ARRAY_ROW_MAJOR_INDEX + " expects an array and at least one subscript");
		}
		int rank = parts.size() - 2;
		LispSymbol dims = new LispSymbol("__rmindex_dims");
		List<LispVal> bindings = new java.util.ArrayList<>();
		bindings.add(listToCons(List.of(dims, callOf(LispNames.ARRAY_DIMENSIONS, parts.get(1)))));
		List<LispSymbol> subs = new java.util.ArrayList<>();
		for (int i = 0; i < rank; i++) {
			LispSymbol sub = new LispSymbol("__rmindex_s" + i);
			subs.add(sub);
			bindings.add(listToCons(List.of(sub, parts.get(2 + i))));
		}
		LispVal flat = subs.get(0);
		for (int k = 1; k < rank; k++) {
			LispVal dimK = callOf(LispNames.CAR, nthCdrOf(dims, k));
			flat = listToCons(List.of(new LispSymbol(LispNames.ADD),
					listToCons(List.of(new LispSymbol(LispNames.MUL), flat, dimK)), subs.get(k)));
		}
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), listToCons(bindings), flat));
	}

	// (cdr (cdr ... expr)) applied n times.
	private static LispVal nthCdrOf(LispVal expr, int n) {
		LispVal result = expr;
		for (int i = 0; i < n; i++) {
			result = callOf(LispNames.CDR, result);
		}
		return result;
	}

	/**
	 * Expands (adjust-array array new-dimensions &amp;key initial-element fill-pointer)
	 * into a build-and-copy over the existing primitives: a fresh array of the new shape
	 * is filled with the elements at the subscripts valid in both shapes (per-subscript,
	 * not flat), then an {@code :adjustable} array is adjusted in place via
	 * {@code %array-become} (returning the array itself) while a non-adjustable one
	 * returns the fresh copy. Without an explicit {@code :fill-pointer} the old fill
	 * pointer is carried over ({@code make-array} range-checks it against the new size).
	 * {@code :displaced-to} is rejected at expansion time; displaced input arrays are
	 * rejected at runtime. Matches the interpreter's {@code adjust-array} built-in.
	 * @param cons the adjust-array expression
	 * @return the expanded expression
	 */
	public static LispVal expandAdjustArray(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3) {
			throw new UnsupportedOperationException("adjust-array expects an array and new dimensions");
		}
		LispVal initExpr = null;
		LispVal fpExpr = null;
		for (int i = 3; i + 1 < parts.size(); i += 2) {
			if (parts.get(i) instanceof LispSymbol kw) {
				switch (kw.name()) {
					case LispNames.INITIAL_ELEMENT_KEYWORD -> initExpr = parts.get(i + 1);
					case LispNames.FILL_POINTER_KEYWORD -> fpExpr = parts.get(i + 1);
					case LispNames.DISPLACED_TO_KEYWORD ->
						throw new UnsupportedOperationException("adjust-array: :displaced-to is not supported");
					default -> {
					}
				}
			}
		}
		LispSymbol a = new LispSymbol("__adj_a");
		LispSymbol nd = new LispSymbol("__adj_nd");
		LispSymbol ndl = new LispSymbol("__adj_ndl");
		LispSymbol od = new LispSymbol("__adj_od");
		LispSymbol fp = new LispSymbol("__adj_fp");
		LispSymbol newArr = new LispSymbol("__adj_new");
		LispSymbol total = new LispSymbol("__adj_total");
		// (make-array ndl [:initial-element E] :fill-pointer fp
		// :adjustable (adjustable-array-p a))
		List<LispVal> makeParts = new java.util.ArrayList<>(List.of(new LispSymbol(LispNames.MAKE_ARRAY), ndl));
		if (initExpr != null) {
			makeParts.add(new LispSymbol(LispNames.INITIAL_ELEMENT_KEYWORD));
			makeParts.add(initExpr);
		}
		makeParts.add(new LispSymbol(LispNames.FILL_POINTER_KEYWORD));
		makeParts.add(fp);
		makeParts.add(new LispSymbol(LispNames.ADJUSTABLE_KEYWORD));
		makeParts.add(callOf(LispNames.ADJUSTABLE_ARRAY_P, a));
		// the carried-over fill pointer: the explicit expression, else the array's own
		LispVal fpInit = fpExpr != null ? fpExpr : makeIf(callOf(LispNames.ARRAY_HAS_FILL_POINTER_P, a),
				callOf(LispNames.FILL_POINTER, a), LispNil.INSTANCE);
		List<LispVal> bindings = List.of(listToCons(List.of(a, parts.get(1))), listToCons(List.of(nd, parts.get(2))),
				listToCons(List.of(ndl,
						makeIf(callOf(LispNames.LISTP, nd), nd, mvCall(LispNames.CONS, nd, LispNil.INSTANCE)))),
				listToCons(List.of(od, callOf(LispNames.ARRAY_DIMENSIONS, a))), listToCons(List.of(fp, fpInit)),
				listToCons(List.of(newArr, listToCons(makeParts))),
				listToCons(List.of(total, callOf(LispNames.ARRAY_TOTAL_SIZE, newArr))));
		LispVal displacedCheck = makeIf(callOf(LispNames.ARRAY_DISP_TARGET, a),
				mvCall(LispNames.ERROR, new LispString("adjust-array: displaced arrays are not supported")),
				LispNil.INSTANCE);
		LispVal rankCheck = makeIf(mvCall(LispNames.EQ, callOf(LispNames.LENGTH, ndl), callOf(LispNames.LENGTH, od)),
				LispNil.INSTANCE, mvCall(LispNames.ERROR, new LispString("adjust-array: rank mismatch")));
		LispVal copyLoop = adjustArrayCopyLoop(a, ndl, od, newArr, total);
		LispVal result = makeIf(callOf(LispNames.ADJUSTABLE_ARRAY_P, a), mvCall(LispNames.ARRAY_BECOME, a, newArr),
				newArr);
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), listToCons(bindings), displacedCheck, rankCheck,
				copyLoop, result));
	}

	// The element-copy loop of expandAdjustArray: for every row-major index of the new
	// array, decompose it into subscripts under the new dimensions (innermost first via
	// the reversed dimension list), keep it only when every subscript is inside the old
	// shape, and copy from the old row-major position (the Horner fold over the old
	// dimensions).
	private static LispVal adjustArrayCopyLoop(LispSymbol a, LispSymbol ndl, LispSymbol od, LispSymbol newArr,
			LispSymbol total) {
		LispSymbol i = new LispSymbol("__adj_i");
		LispSymbol rem = new LispSymbol("__adj_rem");
		LispSymbol subs = new LispSymbol("__adj_subs");
		LispSymbol d = new LispSymbol("__adj_d");
		LispSymbol q = new LispSymbol("__adj_q");
		LispSymbol ok = new LispSymbol("__adj_ok");
		LispSymbol flat = new LispSymbol("__adj_flat");
		LispSymbol s = new LispSymbol("__adj_s");
		LispSymbol o = new LispSymbol("__adj_o");
		// (do ((d (reverse ndl) (cdr d))) ((null d) nil)
		// (let ((q (floor rem (car d))))
		// (setq subs (cons (- rem (* q (car d))) subs)) (setq rem q)))
		LispVal decompose = listToCons(
				List.of(new LispSymbol(LispNames.DO),
						listToCons(List
							.of(listToCons(List.of(d, callOf(LispNames.REVERSE, ndl), callOf(LispNames.CDR, d))))),
						listToCons(List.of(callOf(LispNames.NULL, d),
								LispNil.INSTANCE)),
						makeLet(q.name(), mvCall(LispNames.FLOOR, rem, callOf(LispNames.CAR, d)), makeProgn(List.of(
								mvCall(LispNames.SETQ, subs,
										mvCall(LispNames.CONS,
												mvCall(LispNames.SUB, rem,
														mvCall(LispNames.MUL, q, callOf(LispNames.CAR, d))),
												subs)),
								mvCall(LispNames.SETQ, rem, q))))));
		// (do ((s subs (cdr s)) (o od (cdr o))) ((null s) nil)
		// (if (< (car s) (car o)) nil (setq ok nil))
		// (setq flat (+ (* flat (car o)) (car s))))
		LispVal boundsFold = listToCons(List.of(new LispSymbol(LispNames.DO),
				listToCons(List.of(listToCons(List.of(s, subs, callOf(LispNames.CDR, s))),
						listToCons(List.of(o, od, callOf(LispNames.CDR, o))))),
				listToCons(List.of(callOf(LispNames.NULL, s), LispNil.INSTANCE)),
				makeIf(mvCall(LispNames.LT, callOf(LispNames.CAR, s), callOf(LispNames.CAR, o)), LispNil.INSTANCE,
						mvCall(LispNames.SETQ, ok, LispNil.INSTANCE)),
				mvCall(LispNames.SETQ, flat, mvCall(LispNames.ADD,
						mvCall(LispNames.MUL, flat, callOf(LispNames.CAR, o)), callOf(LispNames.CAR, s)))));
		LispVal copyIfInOld = makeIf(ok,
				mvCall(LispNames.ROW_MAJOR_ASET, newArr, i, mvCall(LispNames.ROW_MAJOR_AREF, a, flat)),
				LispNil.INSTANCE);
		// (let ((ok t) (flat 0)) <boundsFold> <copyIfInOld>)
		LispVal innerLet = listToCons(List.of(new LispSymbol(LispNames.LET), listToCons(
				List.of(listToCons(List.of(ok, LispTrue.INSTANCE)), listToCons(List.of(flat, new LispInteger(0))))),
				boundsFold, copyIfInOld));
		// (let ((rem i) (subs nil)) <decompose> <innerLet>)
		LispVal perIndex = listToCons(List.of(new LispSymbol(LispNames.LET),
				listToCons(List.of(listToCons(List.of(rem, i)), listToCons(List.of(subs, LispNil.INSTANCE)))),
				decompose, innerLet));
		// (do ((i 0 (+ i 1))) ((>= i total) nil) <perIndex>)
		return listToCons(List.of(new LispSymbol(LispNames.DO),
				listToCons(List
					.of(listToCons(List.of(i, new LispInteger(0), mvCall(LispNames.ADD, i, new LispInteger(1)))))),
				listToCons(List.of(mvCall(LispNames.GE, i, total), LispNil.INSTANCE)), perIndex));
	}

	/**
	 * Expands (array-displacement array) in an ordinary (single-value) context into its
	 * primary value {@code (%array-disp-target array)}: the {@code :displaced-to} target
	 * or {@code nil}. The offset second value is only observable through a multiple-value
	 * consumer (see {@code lowerMvProducer}).
	 * @param cons the array-displacement expression
	 * @return the expanded expression
	 */
	public static LispVal expandArrayDisplacement(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new UnsupportedOperationException("array-displacement expects 1 argument");
		}
		return callOf(LispNames.ARRAY_DISP_TARGET, parts.get(1));
	}

	/**
	 * Expands (coerce value 'type) for the literal result types {@code 'list},
	 * {@code 'vector}, and {@code 'string} into a runtime dispatch on the value's actual
	 * type (list, vector, or string), converting only when needed. A non-literal or
	 * unsupported result type is rejected at expansion time, like {@code map} and
	 * {@code concatenate}.
	 * @param cons the coerce expression
	 * @return the expanded expression
	 */
	public static LispVal expandCoerce(LispCons cons) {
		return expandCoerce(cons, true);
	}

	/**
	 * Like {@link #expandCoerce(LispCons)}, but lets a backend drop the branch that READS
	 * a general array when no array can exist in this program. The interpreter and both
	 * WASM backends always pass {@code true} (their array primitives are unconditional);
	 * the JVM backend passes {@code Ctx.usesArrays}, and with the array runtime absent
	 * nothing can construct an array, so {@code (coerce x 'list)} /
	 * {@code (coerce x 'string)} over a vector is dead code that would only drag
	 * {@code _aref1} into every class through the injected built-in wrappers
	 * ({@code .kb/adjustable-arrays.md}). The BUILDING direction ({@code 'vector}) is not
	 * gated: it constructs an array rather than testing for one, so its deadness is not a
	 * local fact -- {@code seqResultDispatchForm} drops it at the guard that knows it.
	 * @param cons the coerce expression
	 * @param arraysExist whether a general array can exist in this program
	 * @return the expanded expression
	 */
	public static LispVal expandCoerce(LispCons cons, boolean arraysExist) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			throw new UnsupportedOperationException("coerce expects a value and a result type");
		}
		String type = quotedSymbolName(parts.get(2));
		if (type != null) {
			// Package-qualified spellings and the "simple" aliases collapse: every
			// rontolisp string is simple, so (coerce s 'simple-string) is the plain
			// string conversion (cl-ppcre's initialize-instance normalization).
			PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(type);
			type = switch (qn == null ? type : qn.member()) {
				case "SIMPLE-STRING", "BASE-STRING", "SIMPLE-BASE-STRING" -> "STRING";
				case "SIMPLE-VECTOR" -> "VECTOR";
				default -> qn == null ? type : qn.member();
			};
		}
		else {
			// A compound type spec: (vector T), (simple-vector T), (array T ...),
			// (vector T dim) collapse to VECTOR; (string N) and (simple-string) to
			// STRING; a bare list of type name to LIST. This handles both the
			// as-written compound specs and a user deftype whose expansion the reader
			// has embedded in the source (uax-15's (coerce ... 'unicode-string) reaches
			// here after macro expansion when the deftype has already been dropped).
			String compound = quotedCompoundTypeHead(parts.get(2));
			if (compound != null) {
				type = compound;
			}
		}
		if (type != null && isFloatTypeName(type)) {
			// Every float type is the same double representation here.
			return mvCall(LispNames.FLOAT, parts.get(1));
		}
		if (type == null && !(parts.get(2) instanceof LispString)) {
			return expandComputedCoerce(parts.get(1), parts.get(2), arraysExist);
		}
		LispSymbol x = new LispSymbol("__coerce_x");
		LispVal body;
		if ("LIST".equals(type)) {
			body = coerceToListBody(x, arraysExist);
		}
		else if ("VECTOR".equals(type)) {
			body = coerceToVectorBody(x);
		}
		else if ("STRING".equals(type)) {
			body = coerceToStringBody(x, arraysExist);
		}
		else if (type != null) {
			// A user deftype name we cannot resolve at expansion time (no deftype
			// registry from here). Common shape in real libraries: the deftype expands
			// to a (vector ...) subtype -- uax-15's unicode-string is `(vector
			// unicode-point)` -- so default to the vector conversion.
			body = coerceToVectorBody(x);
		}
		else {
			throw new UnsupportedOperationException(
					"coerce supports only the 'list, 'vector, or 'string result types, got: " + parts.get(2).print());
		}
		LispVal bindings = listToCons(List.of(listToCons(List.of(x, parts.get(1)))));
		return listToCons(List.of(new LispSymbol(LispNames.LET), bindings, body));
	}

	/**
	 * Expands (coerce value type) where {@code type} is a COMPUTED result type into a
	 * runtime dispatch over the same families the literal path handles: the float
	 * designators, then {@code list}, {@code string} and {@code vector} with their
	 * "simple"/compound spellings.
	 *
	 * <pre>
	 * (let* ((__coerce_x value)
	 *        (__coerce_spec type)
	 *        (__coerce_t (if (consp __coerce_spec) (car __coerce_spec) __coerce_spec)))
	 *   (if (member __coerce_t '(float single-float ...)) (float __coerce_x)
	 *     (if (member __coerce_t '(list cons))            &lt;list conversion&gt;
	 *       (if (member __coerce_t '(string ...))         &lt;string conversion&gt;
	 *         (if (member __coerce_t '(vector ...))       &lt;vector conversion&gt;
	 *           (if (eq __coerce_t t) __coerce_x
	 *             (error "coerce: unsupported result type ~s" __coerce_spec)))))))
	 * </pre>
	 *
	 * The dispatch is on the HEAD of the designator, so a computed compound spec
	 * ({@code (vector t)}, {@code (string 8)}) lands in the same arm as its bare name --
	 * the shape {@code concatenate}'s runtime designator already uses
	 * ({@code BuiltinFunctionWrappers.concatenateWrapper},
	 * {@code .kb/concatenate-result-families.md}), and the sequence families are the same
	 * set. Each arm is the SAME body the literal path emits, so a computed type can never
	 * mean something a literal one does not.
	 *
	 * <p>
	 * The float-only restriction this replaced is what kept
	 * {@code alexandria:copy-sequence} / {@code median} / {@code coercef} dark: they are
	 * all {@code (coerce sequence type)} with the type in a variable ({@code .todo/219}).
	 * @param valueForm the value expression
	 * @param typeForm the result-type expression
	 * @param arraysExist whether a general array can exist in this program
	 * @return the expanded expression
	 */
	private static LispVal expandComputedCoerce(LispVal valueForm, LispVal typeForm, boolean arraysExist) {
		LispSymbol x = new LispSymbol("__coerce_x");
		LispSymbol spec = new LispSymbol("__coerce_spec");
		LispSymbol t = new LispSymbol("__coerce_t");
		LispVal errorCall = listToCons(
				List.of(new LispSymbol(LispNames.ERROR), new LispString("coerce: unsupported result type ~s"), spec));
		// (coerce x t) is the identity in CL; t is the value LispTrue, not a symbol, so
		// it needs its own eq test rather than a member of the name lists.
		LispVal identity = makeIf(mvCall(LispNames.EQ_GENERAL, t, LispTrue.INSTANCE), x, errorCall);
		LispVal vectorArm = makeIf(memberOfTypeNames(t, "VECTOR", "SIMPLE-VECTOR", "ARRAY", "SIMPLE-ARRAY",
				"BIT-VECTOR", "SIMPLE-BIT-VECTOR"), coerceToVectorBody(x), identity);
		LispVal stringArm = makeIf(memberOfTypeNames(t, "STRING", "SIMPLE-STRING", "BASE-STRING", "SIMPLE-BASE-STRING"),
				coerceToStringBody(x, arraysExist), vectorArm);
		LispVal listArm = makeIf(memberOfTypeNames(t, "LIST", "CONS"), coerceToListBody(x, arraysExist), stringArm);
		LispVal body = makeIf(memberOfTypeNames(t, FLOAT_TYPE_NAMES.toArray(new String[0])), mvCall(LispNames.FLOAT, x),
				listArm);
		LispVal head = makeIf(callOf(LispNames.CONSP, spec), callOf(LispNames.CAR, spec), spec);
		LispVal bindings = listToCons(List.of(listToCons(List.of(x, valueForm)), listToCons(List.of(spec, typeForm)),
				listToCons(List.of(t, head))));
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), bindings, body));
	}

	/** {@code (member sym '(NAME...))} over type-designator names. */
	private static LispVal memberOfTypeNames(LispSymbol sym, String... names) {
		List<LispVal> symbols = new java.util.ArrayList<>();
		for (String name : names) {
			symbols.add(new LispSymbol(name));
		}
		return mvCall(LispNames.MEMBER, sym, listToCons(List.of(new LispSymbol(LispNames.QUOTE), listToCons(symbols))));
	}

	/** {@code (map 'list #'identity x)} -- a string's characters as a list. */
	private static LispVal coerceStringToList(LispSymbol x) {
		return listToCons(List.of(new LispSymbol(LispNames.MAP),
				listToCons(List.of(new LispSymbol(LispNames.QUOTE), new LispSymbol("LIST"))),
				listToCons(List.of(new LispSymbol(LispNames.FUNCTION), new LispSymbol(LispNames.IDENTITY))), x));
	}

	/**
	 * The {@code 'list} conversion body:
	 * {@code (if (listp x) x (if (stringp x) (map 'list
	 * #'identity x) <vector scan>))}. With no array in the program the non-list value can
	 * only be a string, so the scan -- and the stringp test guarding it -- fall away.
	 */
	private static LispVal coerceToListBody(LispSymbol x, boolean arraysExist) {
		return arraysExist
				? makeIf(callOf(LispNames.LISTP, x), x,
						makeIf(callOf(LispNames.STRINGP, x), coerceStringToList(x), coerceVectorToList(x)))
				: makeIf(callOf(LispNames.LISTP, x), x, coerceStringToList(x));
	}

	/**
	 * The {@code 'vector} conversion body: {@code (if (or (listp x) (stringp x)) (let
	 * ((__coerce_l (if (stringp x) (map 'list #'identity x) x))) <fill>) x)}.
	 */
	private static LispVal coerceToVectorBody(LispSymbol x) {
		LispSymbol l = new LispSymbol("__coerce_l");
		LispVal asList = makeIf(callOf(LispNames.STRINGP, x), coerceStringToList(x), x);
		LispVal fill = listToCons(List.of(new LispSymbol(LispNames.LET),
				listToCons(List.of(listToCons(List.of(l, asList)))), coerceListToVector(l)));
		LispVal sequencep = listToCons(
				List.of(new LispSymbol(LispNames.OR), callOf(LispNames.LISTP, x), callOf(LispNames.STRINGP, x)));
		return makeIf(sequencep, fill, x);
	}

	/**
	 * The {@code 'string} conversion body: {@code (if (stringp x) x (map 'string
	 * #'identity (if (listp x) x <vector scan>)))}. The vector scan goes with the arrays,
	 * as in {@link #coerceToListBody}.
	 */
	private static LispVal coerceToStringBody(LispSymbol x, boolean arraysExist) {
		LispVal chars = arraysExist ? makeIf(callOf(LispNames.LISTP, x), x, coerceVectorToList(x)) : x;
		LispVal build = listToCons(List.of(new LispSymbol(LispNames.MAP),
				listToCons(List.of(new LispSymbol(LispNames.QUOTE), new LispSymbol("STRING"))),
				listToCons(List.of(new LispSymbol(LispNames.FUNCTION), new LispSymbol(LispNames.IDENTITY))), chars));
		return makeIf(callOf(LispNames.STRINGP, x), x, build);
	}

	/**
	 * Expands {@code (map-into result-sequence function &rest sequences)} into a
	 * {@code let*}/{@code do} loop that destructively stores {@code (funcall function
	 * (elt seq0 i) (elt seq1 i) ...)} into {@code (elt result-sequence i)} for each index
	 * up to the length of the shortest sequence (the result included), then returns the
	 * result sequence. Both lists and vectors are supported via
	 * {@code elt}/{@code length} and the runtime-dispatching {@code (setf (elt ...) ...)}
	 * place; a result with a fill pointer is filled up to that fill pointer (its
	 * {@code length}), matching the lite sequence model elsewhere. With no source
	 * sequences the function is called with no arguments to fill the whole result.
	 * @param cons the map-into expression
	 * @return the expanded expression
	 */
	public static LispVal expandMapInto(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3) {
			throw new UnsupportedOperationException("map-into expects a result sequence and a function");
		}
		LispVal resultForm = parts.get(1);
		// Normalize a literal (quote name) function designator into (function name) so
		// the
		// compilers resolve it against the compile-time function registry (mirrors
		// FunctionDesignators.normalize, inlined to keep this package free of a
		// compiler-package dependency).
		LispVal fnForm = parts.get(2);
		if (fnForm instanceof LispCons fnCons && fnCons.car() instanceof LispSymbol op
				&& LispNames.QUOTE.equals(op.name()) && fnCons.cdr() instanceof LispCons fnRest
				&& fnRest.car() instanceof LispSymbol sym && !sym.isKeyword()) {
			fnForm = listToCons(List.of(new LispSymbol(LispNames.FUNCTION), sym));
		}
		int nSeqs = parts.size() - 3;

		LispSymbol resVar = new LispSymbol("__mi_res");
		LispSymbol fnVar = new LispSymbol("__mi_fn");
		LispSymbol nVar = new LispSymbol("__mi_n");
		LispSymbol iVar = new LispSymbol("__mi_i");

		List<LispSymbol> seqVars = new java.util.ArrayList<>();
		List<LispVal> bindings = new java.util.ArrayList<>();
		bindings.add(listToCons(List.of(resVar, resultForm)));
		bindings.add(listToCons(List.of(fnVar, fnForm)));
		for (int k = 0; k < nSeqs; k++) {
			LispSymbol seqVar = new LispSymbol("__mi_s" + k);
			seqVars.add(seqVar);
			bindings.add(listToCons(List.of(seqVar, parts.get(3 + k))));
		}

		// (min (length res) (length s0) ...) -- each length is a single O(n) pass, so
		// the whole loop below stays O(n) rather than re-walking any list per iteration.
		List<LispVal> minParts = new java.util.ArrayList<>();
		minParts.add(new LispSymbol(LispNames.MIN));
		minParts.add(callOf(LispNames.LENGTH, resVar));
		for (LispSymbol seqVar : seqVars) {
			minParts.add(callOf(LispNames.LENGTH, seqVar));
		}
		bindings.add(listToCons(List.of(nVar, listToCons(minParts))));

		// One cursor per source sequence (and one for the result) advanced alongside the
		// index. A cursor holds the remaining conses of a list operand, or stays pinned
		// to
		// the vector value for a vector operand; the index i handles the vector case.
		// This
		// keeps list element access O(1) per iteration instead of an O(i) head-walk.
		LispSymbol rcurVar = new LispSymbol("__mi_rc");
		List<LispSymbol> curVars = new java.util.ArrayList<>();
		for (int k = 0; k < nSeqs; k++) {
			curVars.add(new LispSymbol("__mi_c" + k));
		}

		// (funcall fn (if (consp c0) (car c0) (elt s0 i)) ...)
		List<LispVal> callParts = new java.util.ArrayList<>();
		callParts.add(new LispSymbol(LispNames.FUNCALL));
		callParts.add(fnVar);
		for (int k = 0; k < nSeqs; k++) {
			callParts.add(readElement(curVars.get(k), seqVars.get(k), iVar));
		}
		LispVal call = listToCons(callParts);

		// (let ((val call))
		// (if (consp rcur) (rplaca rcur val) (setf (elt res i) val)))
		LispSymbol valVar = new LispSymbol("__mi_v");
		LispVal storeList = listToCons(List.of(new LispSymbol(LispNames.RPLACA), rcurVar, valVar));
		LispVal storeVec = listToCons(List.of(new LispSymbol(LispNames.SETF),
				listToCons(List.of(new LispSymbol(LispNames.ELT), resVar, iVar)), valVar));
		LispVal store = listToCons(
				List.of(new LispSymbol(LispNames.LET), listToCons(List.of(listToCons(List.of(valVar, call)))),
						makeIf(callOf(LispNames.CONSP, rcurVar), storeList, storeVec)));

		// (do ((i 0 (+ i 1))
		// (rcur res (if (consp rcur) (cdr rcur) rcur))
		// (c0 s0 (if (consp c0) (cdr c0) c0)) ...)
		// ((>= i n) res) store)
		LispVal iStep = listToCons(List.of(new LispSymbol(LispNames.ADD), iVar, new LispInteger(1)));
		List<LispVal> doBindings = new java.util.ArrayList<>();
		doBindings.add(listToCons(List.of(iVar, new LispInteger(0), iStep)));
		doBindings.add(listToCons(List.of(rcurVar, resVar, advanceCursor(rcurVar))));
		for (int k = 0; k < nSeqs; k++) {
			doBindings.add(listToCons(List.of(curVars.get(k), seqVars.get(k), advanceCursor(curVars.get(k)))));
		}
		LispVal endClause = listToCons(List.of(listToCons(List.of(new LispSymbol(LispNames.GE), iVar, nVar)), resVar));
		LispVal loop = listToCons(List.of(new LispSymbol(LispNames.DO), listToCons(doBindings), endClause, store));

		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), listToCons(bindings), loop));
	}

	// (if (consp cur) (car cur) (elt seq i)) -- read the i-th element of a possibly
	// list-or-vector operand: a list from its cursor (O(1)), a vector by index (O(1)).
	private static LispVal readElement(LispSymbol cur, LispSymbol seq, LispSymbol i) {
		return makeIf(callOf(LispNames.CONSP, cur), callOf(LispNames.CAR, cur),
				listToCons(List.of(new LispSymbol(LispNames.ELT), seq, i)));
	}

	// (if (consp cur) (cdr cur) cur) -- a do-loop step form that walks a list cursor one
	// cons forward while leaving a vector cursor (never a cons) pinned to its value.
	private static LispVal advanceCursor(LispSymbol cur) {
		return makeIf(callOf(LispNames.CONSP, cur), callOf(LispNames.CDR, cur), cur);
	}

	// Builds a (do ...) form collecting the elements of the vector named by {@code vec}
	// into a fresh list, scanning backwards so the conses come out in order.
	private static LispVal coerceVectorToList(LispSymbol vec) {
		LispSymbol i = new LispSymbol("__coerce_i");
		LispSymbol acc = new LispSymbol("__coerce_acc");
		LispVal iInit = listToCons(
				List.of(new LispSymbol(LispNames.SUB), callOf(LispNames.LENGTH, vec), new LispInteger(1)));
		LispVal iStep = listToCons(List.of(new LispSymbol(LispNames.SUB), i, new LispInteger(1)));
		LispVal accStep = listToCons(List.of(new LispSymbol(LispNames.CONS),
				listToCons(List.of(new LispSymbol(LispNames.AREF), vec, i)), acc));
		LispVal bindings = listToCons(
				List.of(listToCons(List.of(i, iInit, iStep)), listToCons(List.of(acc, LispNil.INSTANCE, accStep))));
		LispVal endClause = listToCons(
				List.of(listToCons(List.of(new LispSymbol(LispNames.LT), i, new LispInteger(0))), acc));
		return listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause));
	}

	// Builds a form filling a fresh rank-1 array from the list named by {@code list}.
	private static LispVal coerceListToVector(LispSymbol list) {
		LispSymbol v = new LispSymbol("__coerce_v");
		LispSymbol cur = new LispSymbol("__coerce_cur");
		LispSymbol i = new LispSymbol("__coerce_i");
		LispVal make = listToCons(List.of(new LispSymbol(LispNames.MAKE_ARRAY), callOf(LispNames.LENGTH, list)));
		LispVal doBindings = listToCons(List.of(listToCons(List.of(cur, list, callOf(LispNames.CDR, cur))),
				listToCons(List.of(i, new LispInteger(0),
						listToCons(List.of(new LispSymbol(LispNames.ADD), i, new LispInteger(1)))))));
		LispVal endClause = listToCons(List.of(callOf(LispNames.NULL, cur), v));
		LispVal store = listToCons(List.of(new LispSymbol(LispNames.ASET), v, i, callOf(LispNames.CAR, cur)));
		LispVal loop = listToCons(List.of(new LispSymbol(LispNames.DO), doBindings, endClause, store));
		return listToCons(
				List.of(new LispSymbol(LispNames.LET), listToCons(List.of(listToCons(List.of(v, make)))), loop));
	}

	/**
	 * Expands (rassoc value alist) into a do/return scan returning the first pair whose
	 * cdr matches the value, or nil. The mirror of {@code assoc} (which matches on the
	 * car). The comparison is {@code eql} by default; with a {@code :test} keyword
	 * ({@code (rassoc value alist :test fn)}) it becomes
	 * {@code (funcall fn value (cdr pair))}, and a {@code :key} keyword applies a
	 * selector to each pair's cdr first.
	 * @param cons the rassoc expression
	 * @return the expanded expression
	 */
	public static LispVal expandRassoc(LispCons cons) {
		List<LispVal> parts = cons.toList();
		requireTestKeyKeywords(LispNames.RASSOC, parts, 3);
		LispVal testForm = keywordValue(parts, 3, LispNames.TEST_KEYWORD);
		LispVal keyForm = keywordValue(parts, 3, LispNames.KEY_KEYWORD);
		LispSymbol key = new LispSymbol("__rassoc_key");
		LispSymbol cur = new LispSymbol("__rassoc_cur");
		LispVal pair = callOf(LispNames.CAR, cur);
		LispVal bindings = listToCons(List.of(listToCons(List.of(key, parts.get(1))),
				listToCons(List.of(cur, parts.get(2), callOf(LispNames.CDR, cur)))));
		LispVal endClause = listToCons(List.of(callOf(LispNames.ATOM, cur), LispNil.INSTANCE));
		LispVal comparison = testMatchForm(testForm, key, keyedForm(keyForm, callOf(LispNames.CDR, pair)));
		LispVal match = listToCons(List.of(new LispSymbol(LispNames.AND),
				listToCons(List.of(new LispSymbol(LispNames.CONSP), pair)), comparison));
		LispVal body = makeIf(match, makeReturn(pair), LispNil.INSTANCE);
		return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
	}

	/**
	 * Expands (pairlis keys data) / (pairlis keys data alist) into a do/return scan that
	 * conses each {@code (key . value)} pair, preserving key order, and appends the
	 * optional existing alist as the tail.
	 * @param cons the pairlis expression
	 * @return the expanded expression
	 */
	public static LispVal expandPairlis(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal alist = (parts.size() >= 4) ? parts.get(3) : LispNil.INSTANCE;
		LispSymbol keys = new LispSymbol("__pairlis_keys");
		LispSymbol data = new LispSymbol("__pairlis_data");
		LispSymbol tail = new LispSymbol("__pairlis_tail");
		LispSymbol acc = new LispSymbol("__pairlis_acc");
		// (do ((__pairlis_keys keys (cdr __pairlis_keys))
		// (__pairlis_data data (cdr __pairlis_data))
		// (__pairlis_tail alist) (__pairlis_acc nil))
		// ((or (atom __pairlis_keys) (atom __pairlis_data))
		// (append (reverse __pairlis_acc) __pairlis_tail))
		// (setq __pairlis_acc
		// (cons (cons (car __pairlis_keys) (car __pairlis_data)) __pairlis_acc)))
		LispVal bindings = listToCons(List.of(listToCons(List.of(keys, parts.get(1), callOf(LispNames.CDR, keys))),
				listToCons(List.of(data, parts.get(2), callOf(LispNames.CDR, data))), listToCons(List.of(tail, alist)),
				listToCons(List.of(acc, LispNil.INSTANCE))));
		LispVal endTest = listToCons(
				List.of(new LispSymbol(LispNames.OR), callOf(LispNames.ATOM, keys), callOf(LispNames.ATOM, data)));
		LispVal endResult = listToCons(
				List.of(new LispSymbol(LispNames.APPEND), callOf(LispNames.NREVERSE, acc), tail));
		LispVal endClause = listToCons(List.of(endTest, endResult));
		LispVal pair = listToCons(
				List.of(new LispSymbol(LispNames.CONS), callOf(LispNames.CAR, keys), callOf(LispNames.CAR, data)));
		LispVal body = listToCons(List.of(new LispSymbol(LispNames.SETQ), acc,
				listToCons(List.of(new LispSymbol(LispNames.CONS), pair, acc))));
		return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
	}

	/**
	 * Expands (copy-alist alist) into a do/return scan that copies the alist's spine and
	 * each {@code (key . value)} pair cell; non-pair elements and the keys and values
	 * themselves are shared with the original.
	 * @param cons the copy-alist expression
	 * @return the expanded expression
	 */
	public static LispVal expandCopyAlist(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispSymbol cur = new LispSymbol("__copyalist_cur");
		LispSymbol acc = new LispSymbol("__copyalist_acc");
		LispVal element = callOf(LispNames.CAR, cur);
		// (do ((__copyalist_cur alist (cdr __copyalist_cur)) (__copyalist_acc nil))
		// ((atom __copyalist_cur) (reverse __copyalist_acc))
		// (setq __copyalist_acc
		// (cons (if (consp (car __copyalist_cur))
		// (cons (car (car __copyalist_cur)) (cdr (car __copyalist_cur)))
		// (car __copyalist_cur))
		// __copyalist_acc)))
		LispVal bindings = listToCons(List.of(listToCons(List.of(cur, parts.get(1), callOf(LispNames.CDR, cur))),
				listToCons(List.of(acc, LispNil.INSTANCE))));
		LispVal endClause = listToCons(List.of(callOf(LispNames.ATOM, cur), callOf(LispNames.NREVERSE, acc)));
		LispVal copiedPair = listToCons(List.of(new LispSymbol(LispNames.CONS), callOf(LispNames.CAR, element),
				callOf(LispNames.CDR, element)));
		LispVal copied = makeIf(listToCons(List.of(new LispSymbol(LispNames.CONSP), element)), copiedPair, element);
		LispVal body = listToCons(List.of(new LispSymbol(LispNames.SETQ), acc,
				listToCons(List.of(new LispSymbol(LispNames.CONS), copied, acc))));
		return expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), bindings, endClause, body)));
	}

	/**
	 * Expands (revappend x y) into (append (reverse x) y).
	 * @param cons the revappend expression
	 * @return the expanded expression
	 */
	public static LispVal expandRevappend(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal rev = callOf(LispNames.REVERSE, parts.get(1));
		return listToCons(List.of(new LispSymbol(LispNames.APPEND), rev, parts.get(2)));
	}

	/**
	 * Expands (nreconc x y) into (nconc (nreverse x) y). Like {@code nreverse}, this
	 * implementation is non-destructive.
	 * @param cons the nreconc expression
	 * @return the expanded expression
	 */
	public static LispVal expandNreconc(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal rev = callOf(LispNames.NREVERSE, parts.get(1));
		return listToCons(List.of(new LispSymbol(LispNames.NCONC), rev, parts.get(2)));
	}

	/**
	 * Expands (maplist fn lst...) into a do scan that applies the function to successive
	 * cdrs (tails) of the lists, accumulating the results and reversing them at the end.
	 * @param cons the maplist expression
	 * @return the expanded expression
	 */
	public static LispVal expandMaplist(LispCons cons) {
		return expandMapFamily(cons, LispNames.MAPLIST, true, MapAccumulation.COLLECT);
	}

	/**
	 * Expands (mapcon fn lst...) like {@code maplist} but concatenates the result lists
	 * with {@code append} rather than collecting them.
	 * @param cons the mapcon expression
	 * @return the expanded expression
	 */
	public static LispVal expandMapcon(LispCons cons) {
		return expandMapFamily(cons, LispNames.MAPCON, true, MapAccumulation.CONCATENATE);
	}

	/**
	 * What a {@code map*} family walk does with the value of each call: collect the
	 * values into a fresh list ({@code maplist}), concatenate them ({@code mapcon}), or
	 * discard them and answer the first list ({@code mapl}, {@code mapc}).
	 */
	private enum MapAccumulation {

		COLLECT, CONCATENATE, DISCARD

	}

	/**
	 * Expands one member of the tail-walking {@code map*} family
	 * ({@code maplist}/{@code mapcon}/{@code mapl}) over ANY number of lists, which is
	 * what Common Lisp specifies for all of them: the function is called with one
	 * argument per list, and the walk stops as soon as the shortest list runs out.
	 *
	 * <p>
	 * The three differ only in the two axes this method takes, so they share one
	 * expansion rather than three hand-written ones -- widening a single walk is what let
	 * the N-list case land on all four backends at once ({@code .todo/218}; before it,
	 * every list but the first was silently dropped on the compile backends).
	 *
	 * <pre>
	 * (let ((#fn F) (#l0 L0) (#l1 L1))            ; left-to-right: function, then lists
	 *   (if (listp #l0) nil (error ...))          ; nil is a valid empty list
	 *   (if (listp #l1) nil (error ...))
	 *   (do ((#acc nil)                            ; COLLECT / CONCATENATE only
	 *        (#c0 #l0 (cdr #c0)) (#c1 #l1 (cdr #c1)))
	 *       ((or (atom #c0) (atom #c1)) RESULT)     ; shortest-list termination
	 *     BODY))
	 * </pre>
	 *
	 * With one list the end test is the bare {@code (atom #c0)}, so the single-list
	 * expansion every backend already compiled is unchanged.
	 * @param cons the map* expression
	 * @param name the operator name, for the type-error message
	 * @param tails whether the function receives the successive cdrs themselves
	 * ({@code maplist}) or their cars ({@code mapcar}'s element view)
	 * @param accumulation what to do with each call's value
	 * @return the expanded expression
	 */
	private static LispVal expandMapFamily(LispCons cons, String name, boolean tails, MapAccumulation accumulation) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3) {
			throw new IllegalArgumentException(
					name + " expects at least 2 arguments (a function and one list), got " + (parts.size() - 1));
		}
		int nLists = parts.size() - 2;
		// The expansion's own variables, named after the operator (nesting is safe: an
		// inner expansion's let/do shadows only inside its own scope).
		String prefix = "__" + name.toLowerCase(java.util.Locale.ROOT) + "_";
		LispSymbol fn = new LispSymbol(prefix + "fn");
		LispSymbol acc = new LispSymbol(prefix + "acc");
		List<LispSymbol> lists = new java.util.ArrayList<>();
		List<LispSymbol> cursors = new java.util.ArrayList<>();
		for (int i = 0; i < nLists; i++) {
			lists.add(new LispSymbol(prefix + "l" + i));
			cursors.add(new LispSymbol(prefix + "c" + i));
		}

		// (do ((#acc nil)? (#ci #li (cdr #ci))...) ((or (atom #ci)...) RESULT) BODY)
		List<LispVal> bindings = new java.util.ArrayList<>();
		if (accumulation != MapAccumulation.DISCARD) {
			bindings.add(listToCons(List.of(acc, LispNil.INSTANCE)));
		}
		List<LispVal> exhausted = new java.util.ArrayList<>();
		List<LispVal> callArgs = new java.util.ArrayList<>(List.of(new LispSymbol(LispNames.FUNCALL), fn));
		for (int i = 0; i < nLists; i++) {
			bindings.add(listToCons(List.of(cursors.get(i), lists.get(i), callOf(LispNames.CDR, cursors.get(i)))));
			exhausted.add(callOf(LispNames.ATOM, cursors.get(i)));
			callArgs.add(tails ? cursors.get(i) : callOf(LispNames.CAR, cursors.get(i)));
		}
		LispVal endTest = exhausted.get(0);
		if (nLists > 1) {
			List<LispVal> orParts = new java.util.ArrayList<>();
			orParts.add(new LispSymbol(LispNames.OR));
			orParts.addAll(exhausted);
			endTest = listToCons(orParts);
		}
		LispVal call = listToCons(callArgs);
		LispVal result = switch (accumulation) {
			case COLLECT -> callOf(LispNames.NREVERSE, acc);
			case CONCATENATE -> acc;
			case DISCARD -> lists.get(0);
		};
		LispVal body = switch (accumulation) {
			case COLLECT -> listToCons(List.of(new LispSymbol(LispNames.SETQ), acc,
					listToCons(List.of(new LispSymbol(LispNames.CONS), call, acc))));
			case CONCATENATE -> listToCons(List.of(new LispSymbol(LispNames.SETQ), acc,
					listToCons(List.of(new LispSymbol(LispNames.APPEND), acc, call))));
			case DISCARD -> call;
		};
		LispVal loop = expandDo((LispCons) listToCons(List.of(new LispSymbol(LispNames.DO), listToCons(bindings),
				listToCons(List.of(endTest, result)), body)));
		return wrapMapListGuard(name, fn, parts.get(1), lists, parts.subList(2, parts.size()), loop);
	}

	/**
	 * Whether a {@code string=} / {@code string-equal} call carries the bounding-index
	 * keywords ({@code :start1}/{@code :end1}/{@code :start2}/{@code :end2}), i.e. has
	 * more than the two string arguments.
	 * @param cons the string= / string-equal expression
	 * @return true when the call must go through
	 * {@link #expandStringComparisonBounds(LispCons)} first
	 */
	public static boolean hasStringComparisonBounds(LispCons cons) {
		return cons.toList().size() > 3;
	}

	/**
	 * Normalizes the two operands of a {@code string=}/{@code string-equal} call through
	 * the shared {@code string} designator coercion when they are not already literal
	 * strings.
	 *
	 * <p>
	 * A CL string designator is a string, a symbol (including {@code nil} and {@code t})
	 * or a character, and the compile backends' equality intrinsic takes strings -- so a
	 * runtime symbol reached it unconverted, and {@code nil} reached it as the
	 * null/absent value and crashed. quri's {@code scheme-constructor} asks
	 * {@code (string= scheme "http")} of a relative reference, whose scheme is nil; CL
	 * answers false. Routing through {@code (string ...)} rather than teaching each
	 * intrinsic keeps ONE definition of the coercion. A literal string argument is left
	 * alone, so the common two-literal-strings shape is unchanged.
	 * @param cons the string= / string-equal expression (no bounding keywords)
	 * @return the expression with non-literal operands wrapped in {@code (string ...)}
	 */
	public static LispVal normalizeStringComparisonDesignators(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			return cons;
		}
		List<LispVal> out = new java.util.ArrayList<>();
		out.add(parts.get(0));
		for (int i = 1; i < 3; i++) {
			LispVal arg = parts.get(i);
			out.add(arg instanceof LispString || isStringDesignatorCoercion(arg) ? arg : callOf(LispNames.STRING, arg));
		}
		return listToCons(out);
	}

	// Whether the form is already a (string ...) coercion, so the normalizer does not
	// stack a second one on a hand-written designator call.
	private static boolean isStringDesignatorCoercion(LispVal form) {
		return form instanceof LispCons cons && cons.car() instanceof LispSymbol op
				&& LispNames.STRING.equals(op.name()) && cons.isProperList() && cons.toList().size() == 2;
	}

	/**
	 * Expands (string= s1 s2 :start1 a :end1 b :start2 c :end2 d) -- and the identical
	 * {@code string-equal} shape -- into (string= (subseq s1 a b) (subseq s2 c d)), so
	 * the compile backends keep their two-argument string-equality intrinsic and the
	 * bounding indices cost nothing when absent. The ordering predicates ({@code string<}
	 * and its nine siblings) need no such lowering: they are ordinary {@code defun}s
	 * taking the four keywords in their lambda list.
	 * @param cons the string= / string-equal expression
	 * @return the expanded expression
	 */
	public static LispVal expandStringComparisonBounds(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal start1 = null;
		LispVal end1 = null;
		LispVal start2 = null;
		LispVal end2 = null;
		String name = ((LispSymbol) parts.get(0)).name();
		for (int i = 3; i < parts.size(); i += 2) {
			if (i + 1 >= parts.size() || !(parts.get(i) instanceof LispSymbol key)) {
				throw new IllegalArgumentException(name + " expects :start1/:end1/:start2/:end2 keyword pairs");
			}
			switch (key.name()) {
				case LispNames.START1_KEYWORD -> start1 = parts.get(i + 1);
				case LispNames.END1_KEYWORD -> end1 = parts.get(i + 1);
				case LispNames.START2_KEYWORD -> start2 = parts.get(i + 1);
				case LispNames.END2_KEYWORD -> end2 = parts.get(i + 1);
				default -> throw new IllegalArgumentException(name + ": unsupported keyword " + key.name());
			}
		}
		return listToCons(List.of(parts.get(0), boundedSubstringForm(parts.get(1), start1, end1),
				boundedSubstringForm(parts.get(2), start2, end2)));
	}

	// (subseq s start end) for the bounds actually given -- the string itself when
	// neither is. subseq accepts a nil end (the string's length), so an :end without a
	// :start still becomes a single call.
	private static LispVal boundedSubstringForm(LispVal string, @Nullable LispVal start, @Nullable LispVal end) {
		if (start == null && end == null) {
			return string;
		}
		LispVal startForm = (start == null) ? new LispInteger(0) : start;
		if (end == null) {
			return listToCons(List.of(new LispSymbol(LispNames.SUBSEQ), string, startForm));
		}
		return listToCons(List.of(new LispSymbol(LispNames.SUBSEQ), string, startForm, end));
	}

	/**
	 * Expands (mapl fn lst...) like {@code maplist} but applies the function to
	 * successive cdrs (tails) of the lists for its side effects only, returning the first
	 * list rather than collecting the results.
	 * @param cons the mapl expression
	 * @return the expanded expression
	 */
	public static LispVal expandMapl(LispCons cons) {
		return expandMapFamily(cons, LispNames.MAPL, true, MapAccumulation.DISCARD);
	}

	/**
	 * Wraps a {@code maplist}/{@code mapcon}/{@code mapl} loop in a guard that binds the
	 * function and every list argument once (preserving left-to-right evaluation:
	 * function first, then the lists in order) and signals an error for a list argument
	 * that is not a list. Each list value is bound to the matching symbol, which the loop
	 * walks. nil is a valid empty list.
	 * @param name the operator name (for the error message)
	 * @param fnSym the symbol the function argument is bound to
	 * @param fnArg the (unevaluated) function argument form
	 * @param lstSyms the symbols the list arguments are bound to
	 * @param listArgs the (unevaluated) list argument forms, one per symbol
	 * @param loop the expanded loop that walks the bound lists
	 * @return the guarded expression
	 */
	private static LispVal wrapMapListGuard(String name, LispSymbol fnSym, LispVal fnArg, List<LispSymbol> lstSyms,
			List<LispVal> listArgs, LispVal loop) {
		List<LispVal> letBindings = new java.util.ArrayList<>();
		letBindings.add(listToCons(List.of(fnSym, fnArg)));
		for (int i = 0; i < lstSyms.size(); i++) {
			letBindings.add(listToCons(List.of(lstSyms.get(i), listArgs.get(i))));
		}
		List<LispVal> letForm = new java.util.ArrayList<>();
		letForm.add(new LispSymbol(LispNames.LET));
		letForm.add(listToCons(letBindings));
		for (LispSymbol lstSym : lstSyms) {
			letForm.add(makeIf(listToCons(List.of(new LispSymbol(LispNames.LISTP), lstSym)), LispNil.INSTANCE,
					mapNotAListError(name, lstSym)));
		}
		letForm.add(loop);
		return listToCons(letForm);
	}

	/**
	 * Builds {@code (error "<name>: argument is not a list: ~s ..." valueSym)} for the
	 * map* family list-type guard.
	 * @param name the operator name
	 * @param valueSym the symbol holding the offending value
	 * @return the error expression
	 */
	private static LispVal mapNotAListError(String name, LispSymbol valueSym) {
		return listToCons(List.of(new LispSymbol(LispNames.ERROR),
				new LispString(name + ": argument is not a list: ~s (use map for strings/vectors)"), valueSym));
	}

	/**
	 * Expands (map result-type function seq...) into a {@code do*} index loop that walks
	 * every sequence in parallel up to the shortest length, applying the function to one
	 * element from each. Elements are read with a runtime {@code (if (stringp s) (char s
	 * i) (nth i s))} so the same expansion handles both list and string sequences.
	 *
	 * <p>
	 * The result type is a literal designator (resolved statically, like
	 * {@code concatenate}): {@code 'list} collects the results into a list,
	 * {@code 'string} builds a string from the (character) results, and {@code nil} calls
	 * the function for effect and returns nil. The function designator is normalized so a
	 * {@code 'name} quote resolves in the function namespace before being bound.
	 * @param cons the map expression
	 * @return the expanded expression
	 */
	public static LispVal expandMap(LispCons cons) {
		return expandMap(cons, true);
	}

	/**
	 * Like {@link #expandMap(LispCons)}, but lets a backend drop the {@code aref} arm of
	 * the per-element read when no array can exist in this program (see
	 * {@link #expandCoerce(LispCons, boolean)} for the rule and who passes what). The
	 * {@code 'vector} result type still builds through the ungated {@code coerce}: it
	 * CONSTRUCTS an array, which is not a fact this expansion may assume away.
	 * @param cons the map expression
	 * @param arraysExist whether a general array can exist in this program
	 * @return the expanded expression
	 */
	public static LispVal expandMap(LispCons cons, boolean arraysExist) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 4) {
			throw new UnsupportedOperationException("map expects a result-type, a function, and at least one sequence");
		}
		LispVal resultTypeForm = parts.get(1);
		String resultType = quotedSymbolName(resultTypeForm);
		if (resultType != null) {
			PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(resultType);
			resultType = qn == null ? resultType : qn.member();
			if ("SIMPLE-STRING".equals(resultType) || "BASE-STRING".equals(resultType)) {
				resultType = "STRING";
			}
		}
		boolean nilResult = isNilForm(resultTypeForm);
		if (resultType == null && resultTypeForm instanceof LispCons quoteCons
				&& quoteCons.car() instanceof LispSymbol quoteSym && LispNames.QUOTE.equals(quoteSym.name())
				&& quoteCons.cdr() instanceof LispCons datumCons && datumCons.car() instanceof LispCons typeCons
				&& typeCons.car() instanceof LispSymbol typeHead) {
			// A compound vector designator -- (simple-array (unsigned-byte 8) (*)),
			// (vector t), ... -- collapses to the generic vector family: rontolisp
			// arrays are untyped (cl-postgres's md5 path maps into a byte vector).
			PackageRegistry.QualifiedName typeQn = PackageRegistry.splitQualified(typeHead.name());
			String typeMember = typeQn == null ? typeHead.name() : typeQn.member();
			if ("SIMPLE-ARRAY".equals(typeMember) || "ARRAY".equals(typeMember) || "VECTOR".equals(typeMember)
					|| "SIMPLE-VECTOR".equals(typeMember)) {
				resultType = "VECTOR";
			}
		}
		if ("VECTOR".equals(resultType) || "SIMPLE-VECTOR".equals(resultType) || "ARRAY".equals(resultType)) {
			// (map 'vector fn seq...) -> (coerce (map 'list fn seq...) 'vector): the
			// list expansion below does the walking, coerce fills a fresh vector.
			List<LispVal> mapList = new java.util.ArrayList<>(parts);
			mapList.set(1, listToCons(List.of(new LispSymbol(LispNames.QUOTE), new LispSymbol("LIST"))));
			return expandCoerce((LispCons) listToCons(List.of(new LispSymbol(LispNames.COERCE), listToCons(mapList),
					listToCons(List.of(new LispSymbol(LispNames.QUOTE), new LispSymbol("VECTOR"))))));
		}
		if (!nilResult && !"LIST".equals(resultType) && !"STRING".equals(resultType)) {
			throw new UnsupportedOperationException(
					"map supports only the 'list, 'string, 'vector, or nil result types, got: "
							+ resultTypeForm.print());
		}
		LispVal fnForm = normalizeFunctionDesignator(parts.get(2));
		List<LispVal> seqs = parts.subList(3, parts.size());

		LispSymbol fnVar = new LispSymbol("__map_fn");
		LispSymbol nVar = new LispSymbol("__map_n");
		LispSymbol iVar = new LispSymbol("__map_i");
		LispSymbol accVar = new LispSymbol("__map_acc");

		List<LispVal> bindings = new java.util.ArrayList<>();
		bindings.add(listToCons(List.of(fnVar, fnForm)));
		List<LispSymbol> seqVars = new java.util.ArrayList<>();
		for (int k = 0; k < seqs.size(); k++) {
			LispSymbol sv = new LispSymbol("__map_s" + k);
			seqVars.add(sv);
			bindings.add(listToCons(List.of(sv, seqs.get(k))));
		}
		// n = (length s0) for a single sequence, else (min (length s0) (length s1) ...).
		LispVal lenExpr;
		if (seqVars.size() == 1) {
			lenExpr = callOf(LispNames.LENGTH, seqVars.get(0));
		}
		else {
			List<LispVal> minParts = new java.util.ArrayList<>();
			minParts.add(new LispSymbol(LispNames.MIN));
			for (LispSymbol sv : seqVars) {
				minParts.add(callOf(LispNames.LENGTH, sv));
			}
			lenExpr = listToCons(minParts);
		}
		bindings.add(listToCons(List.of(nVar, lenExpr)));

		// call = (funcall fn (elt s0 i) (elt s1 i) ...) where elt dispatches on
		// stringp/listp (arrays read with aref, like expandElt).
		List<LispVal> callParts = new java.util.ArrayList<>();
		callParts.add(new LispSymbol(LispNames.FUNCALL));
		callParts.add(fnVar);
		for (LispSymbol sv : seqVars) {
			LispVal stringElt = listToCons(List.of(new LispSymbol(LispNames.CHAR), sv, iVar));
			LispVal listElt = listToCons(List.of(new LispSymbol(LispNames.NTH), iVar, sv));
			LispVal arrayElt = listToCons(List.of(new LispSymbol(LispNames.AREF), sv, iVar));
			LispVal listOrArray = arraysExist
					? makeIf(listToCons(List.of(new LispSymbol(LispNames.LISTP), sv)), listElt, arrayElt) : listElt;
			callParts.add(makeIf(listToCons(List.of(new LispSymbol(LispNames.STRINGP), sv)), stringElt, listOrArray));
		}
		LispVal call = listToCons(callParts);

		LispVal accInit;
		LispVal accStep;
		LispVal resultForm;
		if ("STRING".equals(resultType)) {
			accInit = new LispString("");
			accStep = listToCons(List.of(new LispSymbol(LispNames.STRING_CONCAT), accVar,
					listToCons(List.of(new LispSymbol(LispNames.PRINC_TO_STRING), call))));
			resultForm = accVar;
		}
		else if ("LIST".equals(resultType)) {
			accInit = LispNil.INSTANCE;
			accStep = listToCons(List.of(new LispSymbol(LispNames.CONS), call, accVar));
			resultForm = callOf(LispNames.NREVERSE, accVar);
		}
		else {
			// nil: call the function for effect, return nil.
			accInit = LispNil.INSTANCE;
			accStep = call;
			resultForm = LispNil.INSTANCE;
		}
		// The accumulator must be stepped before the index so the element access reads
		// the
		// current i (do* applies steps in source order at the end of each iteration).
		bindings.add(listToCons(List.of(accVar, accInit, accStep)));
		bindings.add(listToCons(
				List.of(iVar, new LispInteger(0), listToCons(List.of(new LispSymbol(LispNames.ONE_PLUS), iVar)))));

		LispVal endTest = listToCons(List.of(new LispSymbol(LispNames.GE), iVar, nVar));
		LispVal endClause = listToCons(List.of(endTest, resultForm));
		LispVal doStar = listToCons(List.of(new LispSymbol(LispNames.DO_STAR), listToCons(bindings), endClause));
		return expandDoStar((LispCons) doStar);
	}

	/** Returns the symbol name inside a {@code (quote name)} form, or null otherwise. */
	/** The float type-specifier names; all map to the one double representation. */
	private static final List<String> FLOAT_TYPE_NAMES = List.of("FLOAT", "SINGLE-FLOAT", "DOUBLE-FLOAT", "SHORT-FLOAT",
			"LONG-FLOAT");

	private static boolean isFloatTypeName(String name) {
		return FLOAT_TYPE_NAMES.contains(name);
	}

	private static @Nullable String quotedSymbolName(LispVal form) {
		if (form instanceof LispCons quoted) {
			List<LispVal> p = quoted.toList();
			if (p.size() == 2 && p.get(0) instanceof LispSymbol q && LispNames.QUOTE.equals(q.name())
					&& p.get(1) instanceof LispSymbol s) {
				return s.name();
			}
		}
		return null;
	}

	/**
	 * When {@code form} is a quoted compound type spec whose head names a collection
	 * kind, returns the canonical spelling of that head: {@code VECTOR} for
	 * {@code (vector T)}/{@code (simple-vector T)}/{@code (array T)}, {@code STRING} for
	 * {@code (string N)}, {@code LIST} for {@code (list T)}. Returns null otherwise.
	 * @param form the quoted type spec form
	 * @return the collection head, or null
	 */
	private static @Nullable String quotedCompoundTypeHead(LispVal form) {
		if (!(form instanceof LispCons quoted)) {
			return null;
		}
		List<LispVal> p = quoted.toList();
		if (p.size() != 2 || !(p.get(0) instanceof LispSymbol q) || !LispNames.QUOTE.equals(q.name())) {
			return null;
		}
		if (!(p.get(1) instanceof LispCons spec) || !(spec.car() instanceof LispSymbol head)) {
			return null;
		}
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(head.name());
		return switch (qn == null ? head.name() : qn.member()) {
			case "VECTOR", "SIMPLE-VECTOR", "ARRAY", "SIMPLE-ARRAY" -> "VECTOR";
			case "STRING", "SIMPLE-STRING", "BASE-STRING", "SIMPLE-BASE-STRING" -> "STRING";
			case "LIST", "CONS" -> "LIST";
			default -> null;
		};
	}

	/**
	 * Returns true when the form denotes nil (the nil literal or the {@code nil} symbol).
	 */
	private static boolean isNilForm(LispVal form) {
		return form instanceof LispNil || (form instanceof LispSymbol s && "NIL".equals(s.name()));
	}

	/**
	 * Normalizes a function designator so a {@code (quote name)} resolves in the function
	 * namespace ({@code (function name)}) once bound to a variable; other forms (a
	 * {@code #'name}/{@code (function ...)} value or a lambda) are returned unchanged.
	 */
	private static LispVal normalizeFunctionDesignator(LispVal form) {
		String name = quotedSymbolName(form);
		if (name != null) {
			return listToCons(List.of(new LispSymbol(LispNames.FUNCTION), new LispSymbol(name)));
		}
		return form;
	}

	/**
	 * Expands (notany pred seq...) into (not (some pred seq...)) -- every sequence is
	 * forwarded, so the multi-sequence form rides on {@link #expandSome(LispCons)}.
	 * @param cons the notany expression
	 * @return the expanded expression
	 */
	public static LispVal expandNotany(LispCons cons) {
		return makeNot(replaceOperator(cons, LispNames.NOTANY, LispNames.SOME));
	}

	/**
	 * Expands (notevery pred seq...) into (not (every pred seq...)) -- every sequence is
	 * forwarded, so the multi-sequence form rides on {@link #expandEvery(LispCons)}.
	 * @param cons the notevery expression
	 * @return the expanded expression
	 */
	public static LispVal expandNotevery(LispCons cons) {
		return makeNot(replaceOperator(cons, LispNames.NOTEVERY, LispNames.EVERY));
	}

	/**
	 * Rebuilds a call form with a different operator name, keeping every argument.
	 * @param cons the call form
	 * @param name the operator name, for the arity-error message
	 * @param replacement the operator to call instead
	 * @return the rebuilt call form
	 */
	private static LispVal replaceOperator(LispCons cons, String name, String replacement) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3) {
			throw new IllegalArgumentException(
					name + " expects at least 2 arguments (a predicate and one sequence), got " + (parts.size() - 1));
		}
		List<LispVal> rebuilt = new java.util.ArrayList<>();
		rebuilt.add(new LispSymbol(replacement));
		rebuilt.addAll(parts.subList(1, parts.size()));
		return listToCons(rebuilt);
	}

	/**
	 * Expands (prog2 first second body...) into (progn first (prog1 second body...)): all
	 * forms are evaluated in order and the value of the second is returned.
	 * @param cons the prog2 expression
	 * @return the expanded expression
	 */
	public static LispVal expandProg2(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal first = parts.get(1);
		List<LispVal> prog1Parts = new java.util.ArrayList<>();
		prog1Parts.add(new LispSymbol(LispNames.PROG1));
		prog1Parts.addAll(parts.subList(2, parts.size()));
		LispVal prog1Expr = expandProg1((LispCons) listToCons(prog1Parts));
		return makeProgn(List.of(first, prog1Expr));
	}

	/**
	 * Expands (psetq v1 e1 v2 e2 ...) into a let that binds every right-hand side to a
	 * temporary before assigning any variable, giving the parallel-assignment semantics
	 * of Common Lisp. The result is nil.
	 * @param cons the psetq expression
	 * @return the expanded expression
	 */
	public static LispVal expandPsetq(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if ((parts.size() - 1) % 2 != 0) {
			throw new IllegalArgumentException("psetq requires an even number of arguments");
		}
		List<LispVal> bindings = new java.util.ArrayList<>();
		List<LispVal> assignments = new java.util.ArrayList<>();
		for (int i = 1; i < parts.size(); i += 2) {
			LispVal var = parts.get(i);
			LispVal val = parts.get(i + 1);
			LispSymbol temp = new LispSymbol("__psetq_" + (i / 2));
			bindings.add(listToCons(List.of(temp, val)));
			assignments.add(listToCons(List.of(new LispSymbol(LispNames.SETQ), var, temp)));
		}
		List<LispVal> letParts = new java.util.ArrayList<>();
		letParts.add(new LispSymbol(LispNames.LET));
		letParts.add(bindings.isEmpty() ? LispNil.INSTANCE : listToCons(bindings));
		letParts.addAll(assignments);
		letParts.add(LispNil.INSTANCE);
		return listToCons(letParts);
	}

	/**
	 * Expands (psetf p1 e1 p2 e2 ...) into a let* that evaluates every place subform and
	 * every right-hand side into a temporary before any assignment, then assigns via
	 * setq/setf, giving the parallel-assignment semantics of Common Lisp (a later place
	 * reading a variable assigned by an earlier pair sees the old value). The result is
	 * nil.
	 * @param cons the psetf expression
	 * @return the expanded expression
	 */
	public static LispVal expandPsetf(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if ((parts.size() - 1) % 2 != 0) {
			throw new IllegalArgumentException(LispNames.PSETF + " requires an even number of arguments");
		}
		List<LispVal> bindings = new java.util.ArrayList<>();
		List<LispVal> assignments = new java.util.ArrayList<>();
		int temp = 0;
		for (int i = 1; i < parts.size(); i += 2) {
			LispVal place = parts.get(i);
			LispVal val = parts.get(i + 1);
			if (place instanceof LispCons placeCons && placeCons.isProperList()) {
				// Accessor place: hoist each argument subform into a temp so it is
				// evaluated before ANY assignment of this psetf.
				List<LispVal> placeParts = placeCons.toList();
				List<LispVal> newPlace = new java.util.ArrayList<>();
				newPlace.add(placeParts.get(0));
				for (int j = 1; j < placeParts.size(); j++) {
					LispSymbol argTemp = new LispSymbol("__psetf_" + temp++);
					bindings.add(listToCons(List.of(argTemp, placeParts.get(j))));
					newPlace.add(argTemp);
				}
				LispSymbol valTemp = new LispSymbol("__psetf_" + temp++);
				bindings.add(listToCons(List.of(valTemp, val)));
				assignments.add(listToCons(List.of(new LispSymbol(LispNames.SETF), listToCons(newPlace), valTemp)));
			}
			else {
				LispSymbol valTemp = new LispSymbol("__psetf_" + temp++);
				bindings.add(listToCons(List.of(valTemp, val)));
				assignments.add(listToCons(List.of(new LispSymbol(LispNames.SETQ), place, valTemp)));
			}
		}
		List<LispVal> letParts = new java.util.ArrayList<>();
		letParts.add(new LispSymbol(LispNames.LET_STAR));
		letParts.add(bindings.isEmpty() ? LispNil.INSTANCE : listToCons(bindings));
		letParts.addAll(assignments);
		letParts.add(LispNil.INSTANCE);
		return listToCons(letParts);
	}

	/**
	 * Expands {@code (char> ...)}/{@code (char>= ...)} for the compilers: the arguments
	 * are hoisted into {@code let*} temps (preserving left-to-right evaluation) and the
	 * chain is delegated to the ascending sibling over the REVERSED temps --
	 * {@code (char> a b c)} holds exactly when {@code (char< c b a)} does.
	 * @param cons the char>/char>= expression
	 * @param ascendingOp the delegate operator ({@code char<} or {@code char<=})
	 * @return the expanded expression
	 */
	public static LispVal expandCharDescending(LispCons cons, String ascendingOp) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException(((LispSymbol) cons.car()).name() + " expects at least one argument");
		}
		List<LispVal> bindings = new java.util.ArrayList<>();
		List<LispVal> temps = new java.util.ArrayList<>();
		for (int i = 1; i < parts.size(); i++) {
			LispSymbol temp = new LispSymbol("__chcmp_" + (i - 1));
			bindings.add(listToCons(List.of(temp, parts.get(i))));
			temps.add(temp);
		}
		List<LispVal> call = new java.util.ArrayList<>();
		call.add(new LispSymbol(ascendingOp));
		for (int i = temps.size() - 1; i >= 0; i--) {
			call.add(temps.get(i));
		}
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), listToCons(bindings), listToCons(call)));
	}

	/**
	 * Expands {@code (char-equal ...)} for the compilers: a case-insensitive
	 * {@code char=} chain over downcased {@code let*} temps.
	 * @param cons the char-equal expression
	 * @return the expanded expression
	 */
	public static LispVal expandCharEqual(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException(LispNames.CHAR_EQUAL + " expects at least one argument");
		}
		List<LispVal> bindings = new java.util.ArrayList<>();
		List<LispVal> temps = new java.util.ArrayList<>();
		for (int i = 1; i < parts.size(); i++) {
			LispSymbol temp = new LispSymbol("__cheq_" + (i - 1));
			bindings.add(listToCons(
					List.of(temp, listToCons(List.of(new LispSymbol(LispNames.CHAR_DOWNCASE), parts.get(i))))));
			temps.add(temp);
		}
		List<LispVal> tests = new java.util.ArrayList<>();
		tests.add(new LispSymbol(LispNames.AND));
		for (int i = 0; i + 1 < temps.size(); i++) {
			tests.add(listToCons(List.of(new LispSymbol(LispNames.CHAR_EQ), temps.get(i), temps.get(i + 1))));
		}
		LispVal body = tests.size() == 1 ? LispTrue.INSTANCE : listToCons(tests);
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), listToCons(bindings), body));
	}

	/**
	 * Expands {@code (char/= ...)} for the compilers: all arguments pairwise distinct
	 * (not just adjacent pairs), as an {@code and} of negated {@code char=} tests over
	 * {@code let*} temps.
	 * @param cons the char/= expression
	 * @return the expanded expression
	 */
	public static LispVal expandCharNe(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException(LispNames.CHAR_NE + " expects at least one argument");
		}
		List<LispVal> bindings = new java.util.ArrayList<>();
		List<LispVal> temps = new java.util.ArrayList<>();
		for (int i = 1; i < parts.size(); i++) {
			LispSymbol temp = new LispSymbol("__chne_" + (i - 1));
			bindings.add(listToCons(List.of(temp, parts.get(i))));
			temps.add(temp);
		}
		List<LispVal> tests = new java.util.ArrayList<>();
		tests.add(new LispSymbol(LispNames.AND));
		for (int i = 0; i < temps.size(); i++) {
			for (int j = i + 1; j < temps.size(); j++) {
				tests.add(makeNot(listToCons(List.of(new LispSymbol(LispNames.CHAR_EQ), temps.get(i), temps.get(j)))));
			}
		}
		LispVal body = tests.size() == 1 ? LispTrue.INSTANCE : listToCons(tests);
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), listToCons(bindings), body));
	}

	/**
	 * {@code --no-gc} lowering of a user {@code (block name body...)}: the name is
	 * dropped and the body wrapped in the internal {@code %block}. The interpreter and
	 * the JVM / wasm-GC compilers do NOT use this -- they implement named blocks (real
	 * name matching; lexical on the compilers).
	 * @param cons the block expression
	 * @return the expanded expression
	 */
	public static LispVal expandBlock(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException(LispNames.BLOCK + " expects a block name: " + cons.print());
		}
		List<LispVal> out = new java.util.ArrayList<>();
		out.add(new LispSymbol(LispNames.BLOCK_INTERNAL));
		out.addAll(parts.subList(2, parts.size()));
		return listToCons(out);
	}

	/**
	 * The instance tags a user {@code print-object} method specializes on, in
	 * registration order -- the exact set the printer has to route through the generic.
	 * Empty when the program defines no {@code print-object} method, which is the gate:
	 * with no method, every printing operator keeps the shape (and the output bytes) it
	 * always had.
	 * @param closRegistry the class registry
	 * @return the instance tags with a user print-object method
	 */
	public static List<String> printObjectTags(ClosRegistry closRegistry) {
		ClosRegistry.GenericInfo generic = closRegistry.generics()
			.values()
			.stream()
			.filter(g -> LispNames.PRINT_OBJECT.equals(plainName(g.name())))
			.findFirst()
			.orElse(null);
		if (generic == null) {
			return List.of();
		}
		List<String> tags = new java.util.ArrayList<>();
		for (ClosRegistry.MethodInfo method : generic.methods().values()) {
			for (ClosRegistry.Specializer specializer : method.specializers()) {
				// A defclass name is a CLASS specializer, a defstruct name a TYPE one
				// carrying the struct name (parseSpecializer); both route the printer, so
				// both descendant-tag families are collected.
				if (specializer.name() == null || (specializer.kind() != ClosRegistry.SpecializerKind.CLASS
						&& specializer.kind() != ClosRegistry.SpecializerKind.TYPE)) {
					continue;
				}
				List<String> descendants = new java.util.ArrayList<>(closRegistry.descendantTags(specializer.name()));
				descendants.addAll(closRegistry.descendantStructTags(specializer.name()));
				for (String tag : descendants) {
					if (tag != null && !tags.contains(tag)) {
						tags.add(tag);
					}
				}
			}
		}
		return tags;
	}

	/**
	 * The generated {@code (%print-object-str x escape)} renderer: the text the printer
	 * writes for a value. An instance of a type some {@code print-object} method
	 * specializes on is rendered by calling the generic into a string stream; everything
	 * else falls back to the RAW ({@code print-object}-free) conversions, which is what
	 * makes the recursion terminate.
	 * @param closRegistry the class registry
	 * @return the {@code %print-object-str} defun
	 */
	public static LispVal printObjectStrDefun(ClosRegistry closRegistry) {
		LispSymbol value = new LispSymbol("__pox");
		LispSymbol escape = new LispSymbol("__poe");
		LispVal fallback = makeIf(escape, listToCons(List.of(new LispSymbol(LispNames.PRIN1_TO_STRING_RAW), value)),
				princRendering(value, closRegistry.routesConditionReports()));
		LispVal body = printObjectRouting(value, fallback, closRegistry, escape);
		return listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.PRINT_OBJECT_STR_INTERNAL),
				listToCons(List.of(value, escape)), body));
	}

	/**
	 * Wraps the escape-mode rendering in the {@code print-object} route, or returns it
	 * unchanged when no method specializes on anything: with an empty tag set the
	 * {@code %obj-is} test is a constant nil, but its dead {@code print-object} branch
	 * would still have to compile, and a program routed here only for its CONDITION
	 * reports has no such generic at all.
	 */
	private static LispVal printObjectRouting(LispVal value, LispVal fallback, ClosRegistry closRegistry,
			LispVal escapeArg) {
		List<String> tags = printObjectTags(closRegistry);
		return tags.isEmpty() ? fallback : makeIf(objIs(value, tags), printObjectCall(value, escapeArg), fallback);
	}

	/**
	 * The {@code princ} (escape-off) rendering: a condition instance answers its
	 * {@code :report}, everything else the RAW conversion. This is the whole of CLHS's
	 * "{@code princ} of a condition runs its report, {@code prin1} prints the unreadable
	 * {@code #<...>} form" -- the escape-on arm is deliberately untouched.
	 */
	private static LispVal princRendering(LispVal value, boolean routesConditionReports) {
		LispVal raw = listToCons(List.of(new LispSymbol(LispNames.PRINC_TO_STRING_RAW), value));
		if (!routesConditionReports) {
			return raw;
		}
		// The %obj-p guard keeps every non-instance print (the overwhelming majority) one
		// test away from the raw conversion instead of walking the renderer's tag cond.
		LispSymbol reportVar = new LispSymbol("__cr" + MV_COUNTER.getAndIncrement());
		LispVal reported = makeLet(reportVar.name(), callOf(LispNames.CONDITION_REPORT_STR_INTERNAL, value),
				makeIf(reportVar, reportVar, raw));
		return makeIf(callOf(LispNames.OBJ_P, value), reported, raw);
	}

	/** Builds {@code (with-output-to-string (s) (print-object value s))}. */
	private static LispVal printObjectCall(LispVal value, LispVal escapeArg) {
		LispSymbol stream = new LispSymbol("__pos");
		// *print-escape* is bound around the method call, so a portable print-object
		// method sees which of prin1/princ is rendering -- CL binds it the same way, and
		// a method that branches on it (quri's uri) is otherwise stuck in one mode.
		LispVal call = listToCons(List.of(new LispSymbol(LispNames.LET),
				listToCons(List.of(listToCons(List.of(new LispSymbol(LispNames.PRINT_ESCAPE_VAR), escapeArg)))),
				listToCons(List.of(new LispSymbol(LispNames.PRINT_OBJECT), value, stream))));
		return listToCons(List.of(new LispSymbol(LispNames.WITH_OUTPUT_TO_STRING), listToCons(List.of(stream)), call));
	}

	/**
	 * One set of condition tags that render their report the same way: either a class's
	 * registered {@code :report} (inherited by every descendant that does not override
	 * it), or the {@code simple-condition} family's specified
	 * {@code format-control}/{@code format-arguments} rendering at a fixed pair of slot
	 * indices.
	 *
	 * @param report the registered report form, or null for the format-control family
	 * @param controlIndex the {@code format-control} slot index (format-control family)
	 * @param argumentsIndex the {@code format-arguments} slot index (format-control
	 * family)
	 * @param tags the instance tags rendered this way
	 */
	private record ConditionReportGroup(@Nullable LispVal report, int controlIndex, int argumentsIndex,
			List<String> tags) {
	}

	/**
	 * Partitions every registered CONDITION class by how its report renders. A class with
	 * no {@code :report} of its own inherits the nearest ancestor's (walking the
	 * slot-layout parent chain, which is the one {@code define-condition} inherits slots
	 * through); a class with neither its own nor an inherited report reports through
	 * {@code format-control}/{@code format-arguments} when it carries those slots, which
	 * is exactly CLHS's specified report for the {@code simple-condition} family; a class
	 * with none of that is left out entirely and keeps the generic {@code #<...>}
	 * rendering.
	 *
	 * <p>
	 * Grouping (rather than one clause per class) is what keeps the generated dispatch
	 * small on a program with a large condition hierarchy -- cl-postgres alone registers
	 * over a hundred -- and the groups partition the tags, so clause order carries no
	 * meaning.
	 */
	private static List<ConditionReportGroup> conditionReportGroups(ClosRegistry closRegistry) {
		java.util.Map<String, ConditionReportGroup> groups = new java.util.LinkedHashMap<>();
		for (ClosRegistry.ClassInfo cls : closRegistry.classes().values()) {
			if (!cls.ancestors().contains("CONDITION")) {
				continue;
			}
			String tag = LispLayout.CLASS_TAG_PREFIX + cls.name();
			String key = null;
			LispVal report = null;
			// The nearest report along the class precedence list (the CPL is the
			// inheritance order CL specifies for the report, and it degenerates to the
			// parent chain under single inheritance).
			for (String walk : cls.cpl()) {
				LispVal own = closRegistry.findConditionReport(walk);
				if (own != null) {
					key = "R:" + ClosRegistry.normalize(walk);
					report = own;
					break;
				}
			}
			int controlIndex = -1;
			int argumentsIndex = -1;
			if (report == null) {
				controlIndex = slotIndexOf(cls, "FORMAT-CONTROL");
				argumentsIndex = slotIndexOf(cls, "FORMAT-ARGUMENTS");
				if (controlIndex < 0 || argumentsIndex < 0) {
					continue;
				}
				key = "F:" + controlIndex + ":" + argumentsIndex;
			}
			ConditionReportGroup group = groups.get(key);
			if (group == null) {
				groups.put(key, new ConditionReportGroup(report, controlIndex, argumentsIndex,
						new java.util.ArrayList<>(List.of(tag))));
			}
			else {
				group.tags().add(tag);
			}
		}
		return List.copyOf(groups.values());
	}

	/**
	 * The 0-based index of a slot by base name, or -1 when the class has no such slot.
	 */
	private static int slotIndexOf(ClosRegistry.ClassInfo cls, String baseName) {
		for (int i = 0; i < cls.slots().size(); i++) {
			if (baseName.equals(cls.slots().get(i).baseName())) {
				return i;
			}
		}
		return -1;
	}

	/**
	 * The generated condition-report runtime: {@code (%condition-report-str c)}, which
	 * answers the text a condition instance REPORTS -- what CL prints for it under
	 * {@code princ}/{@code ~A} and what a signal puts in its message -- or nil when the
	 * value's class has no report at all, and {@code (%format-condition control args)},
	 * the {@code simple-condition} family's specified report.
	 *
	 * <p>
	 * The nil answer is the contract that makes this safe to bolt onto every caller: a
	 * value with no report falls back to whatever that caller printed before, so a
	 * program whose gate ({@link #mayCreateConditions}) is off loses nothing but the
	 * routing.
	 *
	 * <p>
	 * A report is rendered exactly as the SIGNAL path renders it (a literal string
	 * verbatim, a function funcalled on the condition and a string sink), so the message
	 * an uncaught condition prints and the text {@code (format t "~a" c)} writes cannot
	 * drift apart.
	 * @param closRegistry the class registry
	 * @return the two defuns, in dependency order
	 */
	public static List<LispVal> conditionReportDefuns(ClosRegistry closRegistry) {
		LispSymbol value = new LispSymbol("__crv");
		List<LispVal> clauses = new java.util.ArrayList<>();
		clauses.add(new LispSymbol(LispNames.COND));
		for (ConditionReportGroup group : conditionReportGroups(closRegistry)) {
			LispVal rendered;
			if (group.report() instanceof LispString text) {
				rendered = text;
			}
			else if (group.report() != null) {
				LispSymbol stream = new LispSymbol("__crs");
				rendered = renderedToString(stream,
						listToCons(List.of(new LispSymbol(LispNames.FUNCALL), group.report(), value, stream)));
			}
			else {
				rendered = listToCons(List.of(new LispSymbol(LispNames.FORMAT_CONDITION_INTERNAL),
						objRef(value, group.controlIndex()), objRef(value, group.argumentsIndex())));
			}
			clauses.add(listToCons(List.of(objIs(value, group.tags()), rendered)));
		}
		LispVal reportDefun = listToCons(
				List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.CONDITION_REPORT_STR_INTERNAL),
						listToCons(List.<LispVal>of(value)), listToCons(clauses)));
		return List.of(formatConditionDefun(), reportDefun);
	}

	/**
	 * The {@code simple-condition} family's specified report,
	 * {@code (apply #'format stream (simple-condition-format-control c)
	 * (simple-condition-format-arguments c))}, as a defun over the two slot values.
	 *
	 * <p>
	 * A string control goes through the same runtime renderer a computed
	 * {@code (format nil control args)} uses, so the supported directive set is identical
	 * everywhere. A control that is a FUNCTION (the standard allows it) is called on the
	 * stream and the arguments -- through fixed-arity {@code funcall}s rather than
	 * {@code apply}, which would drag the whole eval runtime into every program that
	 * prints a condition. A nil control is no report at all, and answers nil so the
	 * caller falls back.
	 */
	private static LispVal formatConditionDefun() {
		LispSymbol control = new LispSymbol("__fcc");
		LispSymbol args = new LispSymbol("__fca");
		LispSymbol stream = new LispSymbol("__fcs");
		LispVal first = callOf(LispNames.CAR, args);
		LispVal rest = callOf(LispNames.CDR, args);
		LispVal second = callOf(LispNames.CAR, rest);
		LispVal third = callOf(LispNames.CAR, callOf(LispNames.CDR, rest));
		List<LispVal> arity = new java.util.ArrayList<>();
		arity.add(new LispSymbol(LispNames.COND));
		arity.add(listToCons(List.of(callOf(LispNames.NULL, args),
				listToCons(List.of(new LispSymbol(LispNames.FUNCALL), control, stream)))));
		arity.add(listToCons(List.of(callOf(LispNames.NULL, rest),
				listToCons(List.of(new LispSymbol(LispNames.FUNCALL), control, stream, first)))));
		arity.add(listToCons(List.of(callOf(LispNames.NULL, callOf(LispNames.CDR, rest)),
				listToCons(List.of(new LispSymbol(LispNames.FUNCALL), control, stream, first, second)))));
		arity.add(listToCons(List.of(LispTrue.INSTANCE,
				listToCons(List.of(new LispSymbol(LispNames.FUNCALL), control, stream, first, second, third)))));
		LispVal functionControl = renderedToString(stream, listToCons(arity));
		LispVal body = makeIf(callOf(LispNames.STRINGP, control), FormatRenderer.call(control, args),
				makeIf(callOf(LispNames.NULL, control), LispNil.INSTANCE, functionControl));
		return listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.FORMAT_CONDITION_INTERNAL),
				listToCons(List.of(control, args)), body));
	}

	/**
	 * {@code (with-output-to-string (stream) body)}, PRE-EXPANDED to the close-after-body
	 * shape. The macro symbol must not survive into the generated defuns: the wasm-GC
	 * backend decides EH mode by scanning the program for it (its interpreter/JVM
	 * expansion rides {@code unwind-protect}), and that scan runs AFTER these defuns are
	 * spliced in -- so leaving the symbol here would force EH mode, and the
	 * {@code wasmtime -W exceptions=y} flag, on every program that merely signals a typed
	 * condition. The stream is a string sink with nothing to release, so dropping the
	 * cleanup is behavior-identical on the other backends too.
	 */
	private static LispVal renderedToString(LispSymbol stream, LispVal body) {
		return expandWithOutputToString((LispCons) listToCons(
				List.of(new LispSymbol(LispNames.WITH_OUTPUT_TO_STRING), listToCons(List.<LispVal>of(stream)), body)),
				false);
	}

	/**
	 * The report rendering of a condition value, falling back to {@code fallback} when
	 * its class has no report -- the shape every SIGNAL site uses so its message and the
	 * text {@code princ} writes for the same condition agree.
	 * @param value the (temp-bound) condition value form
	 * @param fallback the message form to use when there is no report
	 * @return the message form
	 */
	private static LispVal conditionReportOr(LispVal value, LispVal fallback) {
		LispSymbol reportVar = new LispSymbol("__crm" + MV_COUNTER.getAndIncrement());
		return makeLet(reportVar.name(), callOf(LispNames.CONDITION_REPORT_STR_INTERNAL, value),
				makeIf(reportVar, reportVar, fallback));
	}

	/**
	 * Rewrites one printing operator so it consults {@code print-object}, or null when
	 * the program defines no {@code print-object} method (then the operator keeps its own
	 * compilation and every existing program stays byte-identical).
	 *
	 * <pre>
	 * (princ-to-string x)  -&gt; (%print-object-str x nil)
	 * (prin1-to-string x)  -&gt; (%print-object-str x t)
	 * (princ x s)          -&gt; (let ((v x)) (write-string (%print-object-str v nil) s) v)
	 * (prin1 x s)          -&gt; (let ((v x)) (write-string (%print-object-str v t) s) v)
	 * (print x s)          -&gt; (let ((v x)) (write-string (%print-object-str v t) s) (terpri s) v)
	 * </pre>
	 *
	 * The fallback inside {@code %print-object-str} uses the RAW conversions, so nothing
	 * here re-enters itself. {@code format}'s {@code ~A}/{@code ~S} need no case of their
	 * own: they lower to {@code princ-to-string}/{@code prin1-to-string}, which do.
	 *
	 * <p>
	 * The SECOND reason to rewrite is a condition's {@code :report}
	 * ({@link ClosRegistry#routesConditionReports()}): the escape-off conversions render
	 * a condition through it. The two share this one seam rather than sitting beside each
	 * other, so a {@code print-object} method on a condition class still wins.
	 * @param cons the printing-operator form
	 * @param closRegistry the class registry
	 * @param inline whether to inline the renderer instead of calling the generated defun
	 * (the interpreter re-expands per call, so it always has the current registry; the
	 * compile paths emit the defun once)
	 * @return the rewritten form, or null when the program neither defines a print-object
	 * method nor can build a condition
	 */
	@Nullable public static LispVal expandPrintObjectHook(LispCons cons, ClosRegistry closRegistry, boolean inline) {
		if ((printObjectTags(closRegistry).isEmpty() && !closRegistry.routesConditionReports())
				|| !cons.isProperList()) {
			return null;
		}
		List<LispVal> parts = cons.toList();
		String op = ((LispSymbol) parts.get(0)).name();
		boolean escape = !LispNames.PRINC.equals(op) && !LispNames.PRINC_TO_STRING.equals(op);
		if (LispNames.PRINC_TO_STRING.equals(op) || LispNames.PRIN1_TO_STRING.equals(op)) {
			return parts.size() == 2 ? printObjectStr(parts.get(1), escape, inline, closRegistry) : null;
		}
		if (parts.size() < 2 || parts.size() > 3) {
			return null;
		}
		LispSymbol valueVar = new LispSymbol("__po" + MV_COUNTER.getAndIncrement() + "_v");
		List<LispVal> write = new java.util.ArrayList<>();
		write.add(new LispSymbol(LispNames.WRITE_STRING));
		write.add(printObjectStr(valueVar, escape, inline, closRegistry));
		List<LispVal> terpri = new java.util.ArrayList<>();
		terpri.add(new LispSymbol(LispNames.TERPRI));
		if (parts.size() == 3) {
			write.add(parts.get(2));
			terpri.add(parts.get(2));
		}
		List<LispVal> body = new java.util.ArrayList<>();
		body.add(listToCons(write));
		if (LispNames.PRINT.equals(op)) {
			body.add(listToCons(terpri));
		}
		body.add(valueVar);
		return makeLet(valueVar.name(), parts.get(1), makeProgn(body));
	}

	/**
	 * The renderer call (or its inlined body) for one value. The inlined form binds the
	 * value to a temp first: it is tested before it is rendered, and the argument of a
	 * {@code (princ-to-string (pop x))} must not be evaluated twice.
	 */
	private static LispVal printObjectStr(LispVal value, boolean escape, boolean inline, ClosRegistry closRegistry) {
		LispVal escapeArg = escape ? LispTrue.INSTANCE : LispNil.INSTANCE;
		if (!inline) {
			return listToCons(List.of(new LispSymbol(LispNames.PRINT_OBJECT_STR_INTERNAL), value, escapeArg));
		}
		if (!(value instanceof LispSymbol)) {
			LispSymbol temp = new LispSymbol("__pos" + MV_COUNTER.getAndIncrement() + "_v");
			return makeLet(temp.name(), value, printObjectStr(temp, escape, true, closRegistry));
		}
		LispVal fallback = escape ? listToCons(List.of(new LispSymbol(LispNames.PRIN1_TO_STRING_RAW), value))
				: princRendering(value, closRegistry.routesConditionReports());
		return printObjectRouting(value, fallback, closRegistry, escapeArg);
	}

	/**
	 * The type NAME of a value as a string: the {@code %class-designator} answer with the
	 * {@code %struct-}/{@code %class-} instance-tag prefix stripped (the prelude
	 * {@code type-of}'s rule, minus the {@code intern} a printed name does not need). The
	 * tag spelling is read with {@code prin1-to-string}, since {@code symbol-name} would
	 * drop the package qualifier a canonical type name carries.
	 */
	private static LispVal typeNameOf(LispVal obj) {
		String prefix = "__ptn" + MV_COUNTER.getAndIncrement();
		LispSymbol text = new LispSymbol(prefix + "_s");
		LispSymbol size = new LispSymbol(prefix + "_n");
		List<LispVal> clauses = new java.util.ArrayList<>();
		clauses.add(new LispSymbol(LispNames.COND));
		for (String tagPrefix : List.of(LispLayout.STRUCT_TAG_PREFIX, LispLayout.CLASS_TAG_PREFIX)) {
			int length = tagPrefix.length();
			LispVal test = listToCons(
					List.of(new LispSymbol(LispNames.AND), fmtCall(LispNames.GT, size, new LispInteger(length)),
							fmtCall(LispNames.STRING_EQ,
									fmtCall(LispNames.SUBSEQ, text, new LispInteger(0), new LispInteger(length)),
									new LispString(tagPrefix))));
			clauses.add(listToCons(List.of(test, fmtCall(LispNames.SUBSEQ, text, new LispInteger(length)))));
		}
		clauses.add(listToCons(List.of(LispTrue.INSTANCE, text)));
		LispVal bindings = listToCons(List.of(
				listToCons(List.of(text,
						fmtCall(LispNames.PRIN1_TO_STRING, fmtCall(LispNames.CLASS_DESIGNATOR_INTERNAL, obj)))),
				listToCons(List.of(size, fmtCall(LispNames.LENGTH, text)))));
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), bindings, listToCons(clauses)));
	}

	private static final String PUO_OBJ_VAR = "__puo_obj";

	private static final String PUO_STREAM_VAR = "__puo_stream";

	/**
	 * Expands {@code (print-unreadable-object (object stream &key type identity)
	 * body...)} into writes of {@code #<}...{@code >} around the body over once-evaluated
	 * temps: a literal truthy {@code :type} prints the {@code type-of} designator first
	 * (followed by a space when a body follows it), {@code :identity} is accepted but
	 * prints NO address -- there is no object-identity token in the value model, and a
	 * per-backend one would break the byte-identical cross-backend output the whole test
	 * suite rests on. The whole form yields nil, like CL.
	 * @param cons the print-unreadable-object expression
	 * @return the expanded expression
	 */
	public static LispVal expandPrintUnreadableObject(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2 || !(parts.get(1) instanceof LispCons specCons)) {
			throw new IllegalArgumentException(
					LispNames.PRINT_UNREADABLE_OBJECT + " expects (object stream &key type identity): " + cons.print());
		}
		List<LispVal> spec = specCons.toList();
		if (spec.size() < 2) {
			throw new IllegalArgumentException(
					LispNames.PRINT_UNREADABLE_OBJECT + " expects (object stream &key type identity): " + cons.print());
		}
		LispVal typeArg = LispNil.INSTANCE;
		for (int i = 2; i + 1 < spec.size(); i += 2) {
			if (spec.get(i) instanceof LispSymbol kw && ":TYPE".equals(kw.name())) {
				typeArg = spec.get(i + 1);
			}
		}
		LispSymbol obj = new LispSymbol(PUO_OBJ_VAR);
		LispSymbol stream = new LispSymbol(PUO_STREAM_VAR);
		List<LispVal> body = new java.util.ArrayList<>();
		body.add(new LispSymbol(LispNames.LET_STAR));
		body.add(listToCons(List.of(listToCons(List.of(obj, spec.get(0))), listToCons(List.of(stream, spec.get(1))))));
		body.add(listToCons(List.of(new LispSymbol(LispNames.WRITE_STRING), new LispString("#<"), stream)));
		if (!(typeArg instanceof LispNil)) {
			// The printed designator is the TYPE NAME (PARSER), not the internal instance
			// tag %class-designator yields (%struct-PARSER). The strip is INLINED rather
			// than
			// delegated to the prelude's type-of, because this expansion runs inside the
			// compilers -- long after the prelude pre-pass that would have spliced it.
			body.add(listToCons(List.of(new LispSymbol(LispNames.WRITE_STRING), typeNameOf(obj), stream)));
			if (parts.size() > 2) {
				// CL separates the type from the body with a space; with no body (and no
				// printable identity) there is nothing to separate, so none is written.
				body.add(listToCons(List.of(new LispSymbol(LispNames.WRITE_STRING), new LispString(" "), stream)));
			}
		}
		body.addAll(parts.subList(2, parts.size()));
		body.add(listToCons(List.of(new LispSymbol(LispNames.WRITE_STRING), new LispString(">"), stream)));
		body.add(LispNil.INSTANCE);
		return listToCons(body);
	}

	/**
	 * Expands {@code (with-package-iterator (name package-list-form symbol-type...)
	 * body...)} into the package-list form (evaluated once, for effect) and an
	 * {@code flet} binding {@code name} to a LOCAL FUNCTION -- not CL's {@code macrolet}
	 * -- that always returns {@code (values nil nil)}: symbols are not interned into
	 * enumerable package tables, so the iteration body runs zero times (cl-ppcre's
	 * regex-apropos loop exits on the first call).
	 * @param cons the with-package-iterator expression
	 * @return the expanded expression
	 */
	public static LispVal expandWithPackageIterator(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2 || !(parts.get(1) instanceof LispCons specCons) || specCons.toList().size() < 2) {
			throw new IllegalArgumentException(
					LispNames.WITH_PACKAGE_ITERATOR + " expects (name package-list symbol-type...): " + cons.print());
		}
		List<LispVal> spec = specCons.toList();
		LispVal iterator = listToCons(List.of(spec.get(0), LispNil.INSTANCE,
				listToCons(List.of(new LispSymbol(LispNames.VALUES), LispNil.INSTANCE, LispNil.INSTANCE))));
		List<LispVal> flet = new java.util.ArrayList<>();
		flet.add(new LispSymbol(LispNames.FLET));
		flet.add(listToCons(List.of(iterator)));
		flet.addAll(parts.subList(2, parts.size()));
		return listToCons(List.of(new LispSymbol(LispNames.PROGN), spec.get(1), listToCons(flet)));
	}

	/**
	 * The block name a {@code block}/{@code %fn-block}/{@code return-from} name
	 * designator denotes on the compile path: {@code null} for the {@code nil} block
	 * (which behaves as the plain {@code return} boundary), otherwise the symbol's
	 * resolved name verbatim -- mirroring the interpreter's name matching.
	 * @param designator the name designator form (a symbol or nil)
	 * @return the block name, or {@code null} for the nil block
	 */
	public static @org.jspecify.annotations.Nullable String blockName(LispVal designator) {
		if (designator instanceof LispNil) {
			return null;
		}
		if (designator instanceof LispSymbol sym && !sym.isKeyword()) {
			return "NIL".equals(sym.name()) ? null : sym.name();
		}
		throw new IllegalArgumentException(
				LispNames.BLOCK + ": block name must be a symbol, got " + designator.print());
	}

	private static final String TYPECASE_VAR = "__typecase";

	/**
	 * Expands (typecase keyform (type body...) ... (t default)) into a let/cond that
	 * dispatches on the type of the keyform using the built-in type predicates. An
	 * unknown type symbol is rejected at expansion time.
	 * @param cons the typecase expression
	 * @return the expanded expression
	 */
	public static LispVal expandTypecase(LispCons cons) {
		return expandTypecase(cons, EMPTY_CLOS_REGISTRY);
	}

	/**
	 * Expands (typecase ...) with a class registry, so a clause head may also name a
	 * {@code defclass}/{@code define-condition} class (tested by instance-tag membership)
	 * in addition to the built-in type specifiers.
	 * @param cons the typecase expression
	 * @param closRegistry the class registry
	 * @return the expanded expression
	 */
	public static LispVal expandTypecase(LispCons cons, ClosRegistry closRegistry) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException("typecase expects a keyform");
		}
		LispVal keyform = parts.get(1);
		List<LispVal> clauses = parts.subList(2, parts.size());
		LispSymbol var = new LispSymbol(TYPECASE_VAR);
		List<LispVal> condParts = new java.util.ArrayList<>();
		condParts.add(new LispSymbol(LispNames.COND));
		for (LispVal clauseVal : clauses) {
			if (!(clauseVal instanceof LispCons clause)) {
				throw new IllegalArgumentException("typecase clause must be a list, got: " + clauseVal.print());
			}
			List<LispVal> clauseParts = clause.toList();
			List<LispVal> body = clauseParts.subList(1, clauseParts.size());
			LispVal test = makeTypeTest(var, clauseParts.get(0), closRegistry);
			List<LispVal> condClause = new java.util.ArrayList<>();
			condClause.add(test);
			if (body.isEmpty()) {
				condClause.add(LispNil.INSTANCE);
			}
			else {
				condClause.addAll(body);
			}
			condParts.add(listToCons(condClause));
		}
		return makeLet(TYPECASE_VAR, keyform, listToCons(condParts));
	}

	private static final String ETYPECASE_VAR = "__etypecase";

	/**
	 * Expands {@code (etypecase keyform (type body...) ...)} like {@code typecase} but
	 * appends a final {@code (error ...)} clause so an object whose type matches no
	 * clause signals an error (Common Lisp's exhaustive {@code etypecase}).
	 * @param cons the etypecase expression
	 * @return the expanded expression
	 */
	public static LispVal expandEtypecase(LispCons cons) {
		return expandEtypecase(cons, EMPTY_CLOS_REGISTRY);
	}

	/**
	 * Expands (etypecase ...) with a class registry; see
	 * {@link #expandTypecase(LispCons, ClosRegistry)}.
	 * @param cons the etypecase expression
	 * @param closRegistry the class registry
	 * @return the expanded expression
	 */
	public static LispVal expandEtypecase(LispCons cons, ClosRegistry closRegistry) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException("etypecase expects a keyform");
		}
		LispVal keyform = parts.get(1);
		List<LispVal> clauses = parts.subList(2, parts.size());
		LispSymbol var = new LispSymbol(ETYPECASE_VAR);
		List<LispVal> condParts = new java.util.ArrayList<>();
		condParts.add(new LispSymbol(LispNames.COND));
		for (LispVal clauseVal : clauses) {
			if (!(clauseVal instanceof LispCons clause)) {
				throw new IllegalArgumentException("etypecase clause must be a list, got: " + clauseVal.print());
			}
			List<LispVal> clauseParts = clause.toList();
			List<LispVal> body = clauseParts.subList(1, clauseParts.size());
			LispVal test = makeTypeTest(var, clauseParts.get(0), closRegistry);
			List<LispVal> condClause = new java.util.ArrayList<>();
			condClause.add(test);
			if (body.isEmpty()) {
				condClause.add(LispNil.INSTANCE);
			}
			else {
				condClause.addAll(body);
			}
			condParts.add(listToCons(condClause));
		}
		condParts.add(makeExhaustiveErrorClause(var, "ETYPECASE"));
		return makeLet(ETYPECASE_VAR, keyform, listToCons(condParts));
	}

	/**
	 * Builds a truthy test form checking that {@code value} is of the given type
	 * specifier. Shared by {@code typecase}/{@code etypecase} clause heads and
	 * {@code check-type}. Supports the atomic predicate types plus the compound
	 * specifiers {@code (or ...)}/{@code (and ...)}/{@code (not ...)},
	 * {@code (member ...)}, {@code (eql obj)}, {@code (satisfies fn)}, and numeric range
	 * types like {@code (integer 0 10)} (with {@code *} and {@code (bound)}-exclusive
	 * bounds). The value form may be evaluated multiple times, so callers bind it to a
	 * temporary first.
	 */
	private static LispVal makeTypeTest(LispVal value, LispVal typeSpec) {
		return makeTypeTest(value, typeSpec, EMPTY_CLOS_REGISTRY);
	}

	private static LispVal makeTypeTest(LispVal value, LispVal typeSpec, ClosRegistry closRegistry) {
		if (typeSpec instanceof LispTrue
				|| (typeSpec instanceof LispSymbol s && LispNames.OTHERWISE.equals(s.name()))) {
			return LispTrue.INSTANCE;
		}
		if (typeSpec instanceof LispNil) {
			// The empty type: no object is of type nil.
			return LispNil.INSTANCE;
		}
		if (typeSpec instanceof LispCons compound) {
			return makeCompoundTypeTest(value, compound, closRegistry);
		}
		if (!(typeSpec instanceof LispSymbol sym)) {
			throw new IllegalArgumentException("Unsupported type specifier: " + typeSpec.print());
		}
		String name = plainTypeName(sym);
		switch (name) {
			case "BOOLEAN":
				// (or (null value) (eq value t))
				return listToCons(List.of(new LispSymbol(LispNames.OR), callOf(LispNames.NULL, value),
						listToCons(List.of(new LispSymbol(LispNames.EQ_GENERAL), value, LispTrue.INSTANCE))));
			case "UNSIGNED-BYTE":
				// unsigned-byte = (integer 0 *): a non-negative integer.
				return listToCons(List.of(new LispSymbol(LispNames.AND), callOf(LispNames.INTEGERP, value),
						listToCons(List.of(new LispSymbol(LispNames.GE), value, new LispInteger(0)))));
			case "SIGNED-BYTE":
				// signed-byte with no width = integer.
				return callOf(LispNames.INTEGERP, value);
			case "STANDARD-OBJECT":
				return makeAnyClassInstanceTest(value, closRegistry);
			case "STRUCTURE-OBJECT":
				return makeAnyStructInstanceTest(value, closRegistry);
			case "PATHNAME":
				// No pathname type exists in rontolisp: nothing is a pathname.
				return LispNil.INSTANCE;
			case "VECTOR", "SIMPLE-VECTOR", "ARRAY", "SIMPLE-ARRAY":
				// Strings are vectors (so arrays) in CL. The rank is NOT checked (a
				// rank-n array passes a `vector` test too): the rank read would drag
				// the gated array helpers into every typecase-using program.
				return listToCons(List.of(new LispSymbol(LispNames.OR), callOf(LispNames.STRINGP, value),
						callOf(LispNames.ARRAYP_INTERNAL, value)));
			case "SEQUENCE":
				return listToCons(List.of(new LispSymbol(LispNames.OR), callOf(LispNames.LISTP, value),
						callOf(LispNames.STRINGP, value), callOf(LispNames.ARRAYP_INTERNAL, value)));
			default:
		}
		String pred = atomicTypePredicate(name);
		if (pred == null) {
			// A defclass/define-condition class (incl. the built-in condition
			// hierarchy): instance-of by tag membership, like a class specializer. Use
			// the REGISTERED class name for the tag enumeration -- findClass matches a
			// bare spelling (a quoted 'name in a package resolves unqualified) against
			// a package-qualified registration, and descendantTags needs the canonical
			// key.
			ClosRegistry.ClassInfo classInfo = closRegistry.findClass(sym.name());
			if (classInfo != null) {
				return makeClassInstanceTest(value, classInfo.name(), closRegistry);
			}
			// A defstruct type: instance-of by tag membership over the struct and its
			// :include descendants, the same test the struct predicate compiles to.
			if (closRegistry.findStructTag(sym.name()) != null) {
				return objIs(value, closRegistry.descendantStructTags(sym.name()));
			}
			// A user deftype: resolve its registered expansion and test against that
			// (a zero-parameter (deftype name () 'spec), typically an (satisfies pred)).
			LispVal deftypeExpansion = closRegistry.findDeftype(sym.name());
			if (deftypeExpansion != null) {
				return makeTypeTest(value, deftypeExpansion, closRegistry);
			}
			throw new IllegalArgumentException("Unsupported type specifier: " + sym.name());
		}
		return callOf(pred, value);
	}

	/**
	 * Builds the test for an instance of ANY registered {@code defstruct} type: the
	 * {@code structure-object} type test, the struct-side twin of
	 * {@link #makeAnyClassInstanceTest}.
	 */
	private static LispVal makeAnyStructInstanceTest(LispVal value, ClosRegistry closRegistry) {
		List<String> tags = new java.util.ArrayList<>();
		for (LispLayout layout : closRegistry.layouts().values()) {
			if (layout.kind() == LispLayout.Kind.STRUCT) {
				tags.add(layout.tag());
			}
		}
		return objIs(value, tags);
	}

	/**
	 * Builds the test for an instance of ANY registered class (conditions included): the
	 * union of every class's own tag. Dispatchers with class-testing methods are
	 * regenerated when a new class appears, so the enumeration stays fresh. Used by the
	 * {@code standard-object} type test.
	 */
	private static LispVal makeAnyClassInstanceTest(LispVal value, ClosRegistry closRegistry) {
		List<String> tags = new java.util.ArrayList<>();
		for (ClosRegistry.ClassInfo info : closRegistry.classes().values()) {
			tags.add(LispLayout.CLASS_TAG_PREFIX + info.name());
		}
		return objIs(value, tags);
	}

	/**
	 * Builds the instance-of test of a {@code defclass}/{@code define-condition} class:
	 * {@code (%obj-is v '%class-X ...)} over the class's statically-known descendant tags
	 * -- the same shape a class specializer compiles to.
	 */
	private static LispVal makeClassInstanceTest(LispVal value, String className, ClosRegistry closRegistry) {
		return objIs(value, List.copyOf(closRegistry.descendantTags(className)));
	}

	/**
	 * The package-stripped name of a type-specifier symbol: standard type names are not
	 * all registered CL symbols (only function/macro names are), so inside a user package
	 * the resolver qualifies e.g. {@code unsigned-byte} to {@code my-pkg::unsigned-byte}
	 * -- type matching goes by the plain name.
	 */
	private static String plainTypeName(LispSymbol sym) {
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(sym.name());
		return qn == null ? sym.name() : qn.member();
	}

	/**
	 * Maps an atomic type-specifier name to its predicate function, or null when the type
	 * is not supported.
	 */
	private static @Nullable String atomicTypePredicate(String name) {
		return switch (name) {
			case "INTEGER", "FIXNUM", "BIGNUM" -> LispNames.INTEGERP;
			case "FLOAT", "SINGLE-FLOAT", "DOUBLE-FLOAT", "SHORT-FLOAT", "LONG-FLOAT" -> LispNames.FLOATP;
			case "NUMBER", "REAL" -> LispNames.NUMBERP;
			case "RATIONAL", "RATIO" -> LispNames.RATIONALP;
			case "STRING", "SIMPLE-STRING", "BASE-STRING", "SIMPLE-BASE-STRING" -> LispNames.STRINGP;
			case "SYMBOL" -> LispNames.SYMBOLP;
			case "KEYWORD" -> LispNames.KEYWORDP;
			case "CONS" -> LispNames.CONSP;
			case "LIST" -> LispNames.LISTP;
			case "NULL" -> LispNames.NULL;
			case "ATOM" -> LispNames.ATOM;
			case "CHARACTER", "BASE-CHAR", "STANDARD-CHAR" -> LispNames.CHARACTERP;
			case "HASH-TABLE" -> LispNames.HASH_TABLE_P;
			case "FUNCTION" -> LispNames.FUNCTIONP;
			case "STREAM" -> LispNames.STREAMP;
			default -> null;
		};
	}

	/** The canonical element-type name of an array type specifier's element type. */
	private static String canonicalElementTypeName(LispSymbol sym) {
		return switch (plainTypeName(sym)) {
			case "CHARACTER", "BASE-CHAR", "STANDARD-CHAR" -> "CHARACTER";
			case "T" -> "T";
			default -> plainTypeName(sym);
		};
	}

	/** Builds the test for a compound (list) type specifier; see makeTypeTest. */
	private static LispVal makeCompoundTypeTest(LispVal value, LispCons spec, ClosRegistry closRegistry) {
		List<LispVal> parts = spec.toList();
		if (!(parts.get(0) instanceof LispSymbol head)) {
			throw new IllegalArgumentException("Unsupported type specifier: " + spec.print());
		}
		switch (plainTypeName(head)) {
			case LispNames.OR, LispNames.AND: {
				List<LispVal> tests = new java.util.ArrayList<>();
				tests.add(new LispSymbol(plainTypeName(head)));
				for (int i = 1; i < parts.size(); i++) {
					tests.add(makeTypeTest(value, parts.get(i), closRegistry));
				}
				return listToCons(tests);
			}
			case LispNames.NOT: {
				if (parts.size() != 2) {
					throw new IllegalArgumentException("Unsupported type specifier: " + spec.print());
				}
				return makeNot(makeTypeTest(value, parts.get(1), closRegistry));
			}
			case LispNames.MEMBER: {
				// (member value '(items...)) -- member compares with eql and returns a
				// truthy tail on a hit.
				LispVal items = listToCons(parts.subList(1, parts.size()));
				return listToCons(List.of(new LispSymbol(LispNames.MEMBER), value,
						listToCons(List.of(new LispSymbol(LispNames.QUOTE), items))));
			}
			case LispNames.EQL: {
				if (parts.size() != 2) {
					throw new IllegalArgumentException("Unsupported type specifier: " + spec.print());
				}
				return listToCons(List.of(new LispSymbol(LispNames.EQL), value,
						listToCons(List.of(new LispSymbol(LispNames.QUOTE), parts.get(1)))));
			}
			case "SATISFIES": {
				if (parts.size() != 2 || !(parts.get(1) instanceof LispSymbol)) {
					throw new IllegalArgumentException("Unsupported type specifier: " + spec.print());
				}
				return listToCons(List.of(parts.get(1), value));
			}
			case "ARRAY", "SIMPLE-ARRAY", "VECTOR", "SIMPLE-VECTOR": {
				// (simple-array ELEMENT-TYPE DIMS): the dimensions are not checked (the
				// rank read would drag the gated array helpers in, like the atomic
				// case). A character element type keeps strings in the test; any other
				// declared element type names a SPECIALIZED array and matches only an
				// array whose element type upgraded to the same one -- a packed
				// (unsigned-byte 8|16|32) spec its packed vectors, anything else the
				// general (element-type t) array. A general #(...) is never a
				// (vector (unsigned-byte 8)) (s-sql's sql-escape dispatches on this).
				boolean characterElements = true;
				LispVal packedElement = null;
				if (parts.size() > 1 && !(parts.get(1) instanceof LispSymbol star && "*".equals(plainTypeName(star)))) {
					LispVal elementType = parts.get(1);
					String elementName = elementType instanceof LispSymbol s ? canonicalElementTypeName(s) : "";
					characterElements = "CHARACTER".equals(elementName) || "T".equals(elementName);
					if (!characterElements && elementType instanceof LispCons ub
							&& ub.car() instanceof LispSymbol ubHead && "UNSIGNED-BYTE".equals(plainTypeName(ubHead))
							&& ub.cdr() instanceof LispCons widthCons && widthCons.car() instanceof LispInteger width
							&& widthCons.cdr() instanceof LispNil
							&& (width.value() == 8 || width.value() == 16 || width.value() == 32)) {
						packedElement = listToCons(
								List.of(new LispSymbol("UNSIGNED-BYTE"), new LispInteger(width.value())));
					}
				}
				if (characterElements) {
					return listToCons(List.of(new LispSymbol(LispNames.OR), callOf(LispNames.STRINGP, value),
							callOf(LispNames.ARRAYP_INTERNAL, value)));
				}
				LispVal expectedElementType = packedElement != null ? packedElement : LispTrue.INSTANCE;
				return listToCons(List.of(new LispSymbol(LispNames.AND), callOf(LispNames.ARRAYP_INTERNAL, value),
						listToCons(List.of(new LispSymbol(LispNames.EQUAL), callOf(LispNames.ARRAY_ELEMENT_TYPE, value),
								listToCons(List.of(new LispSymbol(LispNames.QUOTE), expectedElementType))))));
			}
			case "STRING", "SIMPLE-STRING", "BASE-STRING", "SIMPLE-BASE-STRING":
				// (simple-string SIZE): the size is not checked.
				return callOf(LispNames.STRINGP, value);
			case "UNSIGNED-BYTE": {
				// (unsigned-byte N) = (integer 0 (2^N - 1)).
				List<LispVal> tests = new java.util.ArrayList<>();
				tests.add(new LispSymbol(LispNames.AND));
				tests.add(callOf(LispNames.INTEGERP, value));
				tests.add(listToCons(List.of(new LispSymbol(LispNames.GE), value, new LispInteger(0))));
				if (parts.size() > 1 && parts.get(1) instanceof LispInteger width) {
					tests.add(listToCons(List.of(new LispSymbol(LispNames.LE), value,
							new LispBigInteger(java.math.BigInteger.ONE.shiftLeft((int) width.value())
								.subtract(java.math.BigInteger.ONE)))));
				}
				return listToCons(tests);
			}
			case "SIGNED-BYTE": {
				// (signed-byte N) = (integer -2^(N-1) (2^(N-1) - 1)).
				List<LispVal> tests = new java.util.ArrayList<>();
				tests.add(new LispSymbol(LispNames.AND));
				tests.add(callOf(LispNames.INTEGERP, value));
				if (parts.size() > 1 && parts.get(1) instanceof LispInteger width) {
					java.math.BigInteger half = java.math.BigInteger.ONE.shiftLeft((int) width.value() - 1);
					tests.add(listToCons(
							List.of(new LispSymbol(LispNames.GE), value, new LispBigInteger(half.negate()))));
					tests.add(listToCons(List.of(new LispSymbol(LispNames.LE), value,
							new LispBigInteger(half.subtract(java.math.BigInteger.ONE)))));
				}
				return listToCons(tests);
			}
			default: {
				String pred = atomicTypePredicate(plainTypeName(head));
				if (pred == null) {
					throw new IllegalArgumentException("Unsupported type specifier: " + spec.print());
				}
				// A ranged numeric type like (integer 0 10): the base predicate plus
				// bound checks; * is unbounded and (n) is an exclusive bound.
				List<LispVal> tests = new java.util.ArrayList<>();
				tests.add(new LispSymbol(LispNames.AND));
				tests.add(callOf(pred, value));
				if (parts.size() > 1) {
					addRangeBoundTest(tests, value, parts.get(1), true);
				}
				if (parts.size() > 2) {
					addRangeBoundTest(tests, value, parts.get(2), false);
				}
				if (parts.size() > 3) {
					throw new IllegalArgumentException("Unsupported type specifier: " + spec.print());
				}
				return listToCons(tests);
			}
		}
	}

	/** Adds one bound check of a ranged numeric type specifier to the test list. */
	private static void addRangeBoundTest(List<LispVal> tests, LispVal value, LispVal bound, boolean lower) {
		if (bound instanceof LispSymbol s && "*".equals(s.name())) {
			return;
		}
		if (bound instanceof LispCons exclusive && exclusive.cdr() instanceof LispNil) {
			// (n) is an exclusive bound: value > n / value < n.
			tests.add(listToCons(List.of(new LispSymbol(lower ? LispNames.GT : LispNames.LT), value, exclusive.car())));
			return;
		}
		tests.add(listToCons(List.of(new LispSymbol(lower ? LispNames.GE : LispNames.LE), value, bound)));
	}

	private static final String CHECK_TYPE_VAR = "__check-type";

	/**
	 * Expands {@code (check-type place typespec [string])} into a temp-bound type test
	 * that signals an error when the value does not match. Lite version of Common Lisp's
	 * {@code check-type}: no restarts, so the place cannot be re-stored; the error
	 * message reports the place, the offending value, and the expected type (or the given
	 * description string). Type specifiers are the ones {@code makeTypeTest} supports; a
	 * user {@code deftype} name (or any other unsupported specifier) makes the check a
	 * no-op -- the place is still evaluated, but the assertion is skipped rather than
	 * signalling a compile error, since there is no {@code deftype} registry to resolve
	 * the name here. {@code typecase}/{@code etypecase} stay strict.
	 * @param cons the check-type expression
	 * @return the expanded expression
	 */
	public static LispVal expandCheckType(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3 || parts.size() > 4) {
			throw new IllegalArgumentException("check-type expects a place and a type specifier, got: " + cons.print());
		}
		LispVal place = parts.get(1);
		LispVal typeSpec = parts.get(2);
		String expected = parts.size() == 4 && parts.get(3) instanceof LispString desc ? desc.value()
				: "of type " + typeSpec.print();
		LispSymbol var = new LispSymbol(CHECK_TYPE_VAR);
		LispVal errorCall = listToCons(List.of(new LispSymbol(LispNames.ERROR),
				new LispString("The value of " + place.print() + " is ~s, which is not " + expected + "."), var));
		LispVal test;
		try {
			test = makeTypeTest(var, typeSpec);
		}
		catch (IllegalArgumentException unsupportedType) {
			// A user deftype / unsupported specifier: skip the assertion (lite) rather
			// than
			// failing to compile the whole program.
			test = LispTrue.INSTANCE;
		}
		return makeLet(CHECK_TYPE_VAR, place, makeIf(test, LispNil.INSTANCE, errorCall));
	}

	/**
	 * Expands {@code (assert test)} into {@code (if test nil (error "The assertion
	 * ... failed."))}. The full form {@code (assert test (places...) datum args...)} uses
	 * the datum and its arguments as the error format; the places list is ignored (no
	 * restart system, so the interactive re-store loop does not exist).
	 * @param cons the assert expression
	 * @return the expanded expression
	 */
	public static LispVal expandAssert(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException("assert expects a test form");
		}
		LispVal test = parts.get(1);
		List<LispVal> errorParts = new java.util.ArrayList<>();
		errorParts.add(new LispSymbol(LispNames.ERROR));
		if (parts.size() >= 4) {
			errorParts.addAll(parts.subList(3, parts.size()));
		}
		else {
			errorParts.add(new LispString("The assertion " + test.print() + " failed."));
		}
		return makeIf(test, LispNil.INSTANCE, listToCons(errorParts));
	}

	/**
	 * Expands {@code (declare ...)} to {@code nil}: declarations are parsed no-ops. The
	 * arguments are never evaluated or validated, so any standard declaration
	 * ({@code ignore}, {@code type}, {@code optimize}, ...) is accepted anywhere in a
	 * body.
	 * @param cons the declare expression
	 * @return nil
	 */
	public static LispVal expandDeclare(LispCons cons) {
		return LispNil.INSTANCE;
	}

	/**
	 * Expands {@code (declaim ...)} to {@code nil}: file-level declarations are parsed
	 * no-ops, like {@code declare}.
	 * @param cons the declaim expression
	 * @return nil
	 */
	public static LispVal expandDeclaim(LispCons cons) {
		return LispNil.INSTANCE;
	}

	/**
	 * Expands {@code (proclaim ...)} to {@code nil}. Deviates from Common Lisp (where
	 * {@code proclaim} is a function whose argument is evaluated): here it is a parsed
	 * no-op like {@code declaim}, so the argument is not evaluated either.
	 * @param cons the proclaim expression
	 * @return nil
	 */
	public static LispVal expandProclaim(LispCons cons) {
		return LispNil.INSTANCE;
	}

	/**
	 * Expands {@code (deftype name lambda-list body)} to {@code nil}: a parsed no-op like
	 * {@code declaim}. The type name is NOT registered anywhere, so this only supports
	 * the common library shape where the defined type appears in (equally no-op)
	 * {@code declaim} declarations; using it in {@code check-type}/ {@code typecase}
	 * still fails naming the unsupported specifier.
	 * @param cons the deftype expression
	 * @return nil
	 */
	public static LispVal expandDeftype(LispCons cons) {
		return LispNil.INSTANCE;
	}

	/**
	 * Like {@link #expandDeftype(LispCons)}, but additionally registers a zero-parameter
	 * {@code (deftype name () 'spec)} in the class registry so its name resolves as a
	 * type specifier in {@code typep}/{@code typecase}. Only the literal-expansion shape
	 * is registered (an empty lambda list and a quoted-literal body, e.g.
	 * {@code (satisfies alistp)}); a parameterized or computed deftype stays an
	 * unresolved specifier, exactly as before.
	 * @param cons the deftype expression
	 * @param closRegistry mutated: the deftype expansion is registered
	 * @return nil
	 */
	public static LispVal expandDeftype(LispCons cons, ClosRegistry closRegistry) {
		LispVal expansion = literalDeftypeExpansion(cons);
		if (expansion != null && cons.toList().get(1) instanceof LispSymbol nameSym) {
			closRegistry.registerDeftype(nameSym.name(), expansion);
		}
		return LispNil.INSTANCE;
	}

	/**
	 * The literal type specifier a {@code (deftype name () [doc] 'spec)} expands to, or
	 * null when the deftype has a non-empty lambda list or a non-literal body (which
	 * stays an unresolved specifier). The last body form's single {@code (quote spec)} is
	 * unwrapped; an optional leading docstring is skipped.
	 */
	@Nullable private static LispVal literalDeftypeExpansion(LispCons cons) {
		List<LispVal> parts = cons.toList();
		// (deftype name () [doc] body): a name symbol, an empty lambda list, a literal
		// body. A parameterized lambda list would need the body evaluated per call.
		if (parts.size() < 4 || !(parts.get(1) instanceof LispSymbol) || !(parts.get(2) instanceof LispNil)) {
			return null;
		}
		LispVal body = parts.get(parts.size() - 1);
		if (body instanceof LispCons quoted && quoted.car() instanceof LispSymbol op
				&& LispNames.QUOTE.equals(op.name()) && quoted.cdr() instanceof LispCons rest) {
			return rest.car();
		}
		return null;
	}

	/**
	 * Expands {@code (define-condition name parents slots options...)} to {@code nil} --
	 * the registry-less fallback kept for {@code macroexpand-1} and the {@code --no-gc}
	 * backend (no condition objects there). The real definition path is
	 * {@link #defineConditionToDefclass}: the evaluator and the wasm-GC/JVM compilers
	 * route a top-level {@code define-condition} through the CLOS-subset {@code defclass}
	 * machinery instead.
	 * @param cons the define-condition expression
	 * @return nil
	 */
	public static LispVal expandDefineCondition(LispCons cons) {
		return LispNil.INSTANCE;
	}

	/**
	 * Rewrites {@code (define-condition name (parent?) (slots...) options...)} into the
	 * equivalent {@code (defclass name (parent) (slots...))} form -- a condition type is
	 * an ordinary CLOS-subset class over the built-in hierarchy seeded in
	 * {@link ClosRegistry} (the parent defaults to {@code condition}). Slot
	 * specifications use the {@code defclass} subset ({@code :initarg}/{@code :initform}/
	 * {@code :reader}/{@code :accessor}). Of the class options, {@code (:report x)} is
	 * registered in the registry -- a literal string, or a
	 * {@code (lambda (condition stream) ...)} rendered by the typed {@code error} /
	 * {@code signal} expansions -- and {@code (:documentation ...)} is dropped; anything
	 * else is rejected. Lite: at most one parent type (single inheritance).
	 * @param cons the define-condition expression
	 * @param closRegistry mutated: the :report form is registered
	 * @return the equivalent defclass form
	 */
	public static LispVal defineConditionToDefclass(LispCons cons, ClosRegistry closRegistry) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2 || !(parts.get(1) instanceof LispSymbol nameSym)) {
			throw new IllegalArgumentException(
					LispNames.DEFINE_CONDITION + " expects a condition type name: " + cons.print());
		}
		LispVal parentList;
		if (parts.size() > 2 && parts.get(2) instanceof LispCons parentCons) {
			List<LispVal> parents = parentCons.toList();
			// Multiple parents ride defclass's multiple inheritance: every REGISTERED
			// parent becomes a real superclass (slots inherited, CPL ordered); a parent
			// the registry does not know (a forward-referenced type name) joins the
			// ancestor set only, so typep/handler-case still match through it.
			List<LispVal> known = new java.util.ArrayList<>();
			List<String> unknown = new java.util.ArrayList<>();
			for (LispVal parent : parents) {
				if (!(parent instanceof LispSymbol parentSym)) {
					throw new IllegalArgumentException(
							LispNames.DEFINE_CONDITION + " expects parent type names: " + cons.print());
				}
				if (known.isEmpty() && unknown.isEmpty()) {
					// The FIRST parent stays a real superclass unconditionally, keeping
					// the pre-MI "unknown superclass" error for a bad first parent.
					known.add(parent);
				}
				else if (closRegistry.findClass(parentSym.name()) != null) {
					known.add(parent);
				}
				else {
					unknown.add(parentSym.name());
				}
			}
			parentList = listToCons(known);
			if (!unknown.isEmpty()) {
				closRegistry.registerExtraAncestors(nameSym.name(), unknown);
			}
		}
		else {
			parentList = listToCons(List.of(new LispSymbol("CONDITION")));
		}
		LispVal slots = parts.size() > 3 ? parts.get(3) : LispNil.INSTANCE;
		LispVal defaultInitargs = null;
		for (int i = 4; i < parts.size(); i++) {
			if (parts.get(i) instanceof LispCons opt && opt.car() instanceof LispSymbol optSym) {
				switch (optSym.name()) {
					case ":REPORT" -> {
						if (!(opt.cdr() instanceof LispCons reportCell)) {
							throw new IllegalArgumentException(
									LispNames.DEFINE_CONDITION + " :report expects a value: " + cons.print());
						}
						closRegistry.registerConditionReport(nameSym.name(), reportCell.car());
					}
					case ":DEFAULT-INITARGS" -> {
						// Forwarded verbatim to the generated defclass, which supports
						// the
						// option.
						defaultInitargs = opt;
					}
					case ":DOCUMENTATION" -> {
						// Accepted and dropped, like the defclass class option.
					}
					default -> throw new UnsupportedOperationException(LispNames.DEFINE_CONDITION + " option "
							+ optSym.name() + " is not supported: " + cons.print());
				}
			}
			else {
				throw new IllegalArgumentException(
						LispNames.DEFINE_CONDITION + " expects (option value...) options: " + cons.print());
			}
		}
		if (defaultInitargs != null) {
			return listToCons(List.of(new LispSymbol(LispNames.DEFCLASS), nameSym, parentList, slots, defaultInitargs));
		}
		return listToCons(List.of(new LispSymbol(LispNames.DEFCLASS), nameSym, parentList, slots));
	}

	/**
	 * Expands {@code (define-setf-expander name lambda-list body...)} to {@code nil} on
	 * the compile path: the definition itself is registered and applied earlier, by
	 * {@code UserMacroExpander} rewriting {@code (setf/incf/decf (place ...) v)} through
	 * the five-value protocol before the compilers, so the newly defined place is a
	 * usable {@code setf} target on all four backends and only the residual form drops to
	 * nil here.
	 * @param cons the define-setf-expander expression
	 * @return nil
	 */
	public static LispVal expandDefineSetfExpander(LispCons cons) {
		return LispNil.INSTANCE;
	}

	/**
	 * Returns whether {@code designator} names the {@code keyword} package -- the keyword
	 * {@code :keyword}, the symbol {@code keyword}, or the string {@code "KEYWORD"} (case
	 * insensitive). Used to give {@code (intern name :keyword)} keyword semantics;
	 * symbols otherwise compare by name with no intern table, so any other package
	 * argument stays unsupported.
	 * @param designator the package designator argument
	 * @return true if it designates the keyword package
	 */
	public static boolean isKeywordPackageDesignator(LispVal designator) {
		// A literal (find-package :keyword) folds to the quoted keyword ':KEYWORD on
		// the compile path (PackageResolver.resolveCons); unwrap the quote so the
		// fold's result is recognized like the literal designator it stands for
		// (s-sql's from-sql-name).
		if (designator instanceof LispCons quoted && quoted.car() instanceof LispSymbol q
				&& LispNames.QUOTE.equals(q.name()) && quoted.cdr() instanceof LispCons rest) {
			designator = rest.car();
		}
		String name;
		if (designator instanceof LispSymbol s) {
			name = s.name();
			if (!name.isEmpty() && name.charAt(0) == ':') {
				name = name.substring(1);
			}
		}
		else if (designator instanceof LispString str) {
			name = str.value();
		}
		else {
			return false;
		}
		return name.equalsIgnoreCase("KEYWORD");
	}

	/**
	 * Builds {@code (intern (concatenate 'string ":" nameForm))} -- the backend-neutral
	 * lowering of {@code (intern nameForm :keyword)}. A keyword is a symbol whose stored
	 * name begins with {@code :}, so prepending the colon and reusing single-argument
	 * {@code intern} produces the keyword without any per-backend string-representation
	 * handling.
	 * @param nameForm the (unevaluated) symbol-name argument
	 * @return the equivalent single-argument {@code intern} form
	 */
	/**
	 * Lowers {@code (gensym expr)} with a COMPUTED prefix to string construction over the
	 * literal-prefix {@code gensym}: {@code "#:" + (princ-to-string expr)} followed by
	 * the fresh suffix of a plain {@code (gensym)} (its {@code #:} marker dropped). The
	 * compiled backends bake the interned prefix text of a literal {@code gensym} into
	 * the call, so a runtime prefix has no place there; this keeps the uniqueness
	 * guarantee (the suffix carries the counter) and the {@code #:} shape while staying
	 * backend-neutral. Alexandria's {@code format-symbol}/{@code make-gensym} pass such a
	 * prefix.
	 * @param prefixForm the (unevaluated) prefix expression
	 * @return the equivalent string-construction form
	 */
	/**
	 * Expands {@code (hash-table-test h)} to {@code (progn h 'equal)}: the table argument
	 * is still evaluated, the answer is the constant {@code equal}. Every backend keys
	 * its tables structurally, so {@code equal} is the test the lookups implement
	 * whatever {@code :test} the table was created with.
	 * @param cons the hash-table-test expression
	 * @return the expanded expression
	 */
	public static LispVal expandHashTableTest(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException(LispNames.HASH_TABLE_TEST + " expects one hash table: " + cons.print());
		}
		return listToCons(List.of(new LispSymbol(LispNames.PROGN), parts.get(1),
				listToCons(List.of(new LispSymbol(LispNames.QUOTE), new LispSymbol(LispNames.EQUAL)))));
	}

	/**
	 * Expands {@code (hash-table-rehash-size h)} / {@code (hash-table-rehash-threshold
	 * h)} to {@code (progn h <default>)}: the table has no growth knobs of its own here
	 * (the host map grows), so the standard defaults are reported after evaluating the
	 * argument.
	 * @param cons the accessor expression
	 * @param value the reported constant
	 * @return the expanded expression
	 */
	public static LispVal expandHashTableGrowthConstant(LispCons cons, double value) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException(parts.get(0).print() + " expects one hash table: " + cons.print());
		}
		return listToCons(List.of(new LispSymbol(LispNames.PROGN), parts.get(1), new LispDouble(value)));
	}

	/**
	 * Expands a {@code gensym} whose prefix is COMPUTED (not a literal string) into the
	 * intern of an assembled name, for the backends that have no runtime gensym.
	 * @param prefixForm the expression producing the prefix
	 * @return the expression producing the fresh symbol
	 */
	public static LispVal expandComputedGensym(LispVal prefixForm) {
		// The suffix comes from an EMPTY-prefix gensym, so princ-to-string (which drops
		// the "#:" marker, LispSymbol.displayName) yields the bare counter -- the same
		// "#:<prefix><n>" text the interpreter's native computed-prefix gensym prints.
		// intern turns the assembled name back into a symbol (a name starting with "#:"
		// IS the uninterned spelling here).
		LispVal freshSuffix = listToCons(List.of(new LispSymbol(LispNames.PRINC_TO_STRING),
				listToCons(List.of(new LispSymbol(LispNames.GENSYM), new LispString("")))));
		LispVal head = listToCons(List.of(new LispSymbol(LispNames.STRING_CONCAT), new LispString("#:"),
				listToCons(List.of(new LispSymbol(LispNames.PRINC_TO_STRING), prefixForm))));
		return listToCons(List.of(new LispSymbol(LispNames.INTERN),
				listToCons(List.of(new LispSymbol(LispNames.STRING_CONCAT), head, freshSuffix))));
	}

	/**
	 * The expression that interns a computed name as a KEYWORD: the name concatenated
	 * after {@code ":"} and handed to {@code intern}, which is how the keyword spelling
	 * is written throughout.
	 * @param nameForm the expression producing the bare name
	 * @return the expression producing the keyword
	 */
	public static LispVal internKeywordForm(LispVal nameForm) {
		LispVal concat = listToCons(List.of(new LispSymbol(LispNames.CONCATENATE),
				listToCons(List.of(new LispSymbol(LispNames.QUOTE), new LispSymbol(LispNames.STRING))),
				new LispString(":"), nameForm));
		return listToCons(List.of(new LispSymbol(LispNames.INTERN), concat));
	}

	/**
	 * Normalizes {@code (close stream :abort expr)} to plain {@code (close stream)}:
	 * every rontolisp close is effectively an aborting close (no buffered data survives
	 * it), so the option adds nothing. The abort expression is dropped unevaluated (call
	 * sites pass a variable). Returns null when the form is not that shape.
	 * @param cons the close expression
	 * @return the 1-argument close, or null
	 */
	public static @org.jspecify.annotations.Nullable LispVal stripCloseAbort(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() == 4 && parts.get(2) instanceof LispSymbol kw && ":ABORT".equals(kw.name())) {
			return listToCons(List.of(parts.get(0), parts.get(1)));
		}
		return null;
	}

	/**
	 * The call-time stub both WASM backends lower {@code %make-directories} -- and
	 * therefore {@code ensure-directories-exist} -- to. WASI's import set here carries no
	 * directory-creation call, and unlike {@code file-length} / {@code file-write-date}
	 * this primitive has no "cannot be determined" answer in its contract: either the
	 * directory exists afterwards or it does not, so answering anything but an error
	 * would be a lie. Like the other stubs it keeps a library defun merely CONTAINING the
	 * form compilable and signals only if it is actually called.
	 * @return the signaling expression
	 */
	public static LispVal makeDirectoriesStub() {
		return listToCons(List.of(new LispSymbol(LispNames.ERROR),
				new LispString("ensure-directories-exist is not supported on the WASM backends")));
	}

	/**
	 * The call-time stub the compiled backends lower {@code handler-bind} to: an
	 * unconditional {@code error}. Its handlers would have to run at the signal point
	 * without unwinding, which no backend's condition machinery models; the stub keeps a
	 * library defun merely CONTAINING the form compilable (the jzon stub-lowering
	 * precedent) and signals only if it is actually called. The interpreter needs no
	 * stub: the name resolves to no function, so a call errors on its own.
	 * @return the signaling expression
	 */
	public static LispVal handlerBindStub() {
		return listToCons(List.of(new LispSymbol(LispNames.ERROR),
				new LispString("handler-bind is not supported on compiled backends")));
	}

	/**
	 * The call-time stub a call to an UNDEFINED function compiles to, matching the
	 * interpreter's late binding: the interpreter signals "The function X is undefined"
	 * only when the call is executed, so a library whose error path references a function
	 * rontolisp does not provide still loads and runs. The compilers emit this stub (plus
	 * a compile-time warning, so a typo stays visible) instead of rejecting the whole
	 * program.
	 * @param name the undefined function's name
	 * @return the signaling expression
	 */
	public static LispVal undefinedFunctionCallStub(String name) {
		return listToCons(
				List.of(new LispSymbol(LispNames.ERROR), new LispString("The function " + name + " is undefined")));
	}

	/**
	 * The call-time stub for a built-in a backend cannot provide: signals the given
	 * message when the call EXECUTES, so a spliced library whose unsupported branch is
	 * dead code still compiles (cl-postgres' socket layer under s-sql on Preview 1 WASM).
	 * @param message the error message
	 * @return the signaling expression
	 */
	public static LispVal callTimeUnsupportedStub(String message) {
		return listToCons(List.of(new LispSymbol(LispNames.ERROR), new LispString(message)));
	}

	/**
	 * Lowers a nested/computed {@code (asdf:find-system NAME [ERROR-P])} on the compile
	 * paths to its arguments evaluated for effect followed by {@code nil}: a compiled
	 * program carries no system registry (every loadable system was spliced at compile
	 * time; a LITERAL name folds via {@code CompileTimePathnameFolder} before this is
	 * reached), so "no such system" is the honest runtime answer. This serves the probe
	 * shape libraries actually use -- lack's {@code find-package-or-load} guards its
	 * {@code load-system} with {@code (asdf:find-system name nil)}, and nil routes it
	 * onto the not-found branch. Divergence vs the interpreter (which answers from its
	 * live registry) is accepted and documented in {@code .kb/asdf.md}.
	 * @param cons the find-system call
	 * @return the lowered expression
	 */
	public static LispVal expandRuntimeFindSystem(LispCons cons) {
		List<LispVal> parts = cons.toList();
		List<LispVal> progn = new java.util.ArrayList<>();
		progn.add(new LispSymbol(LispNames.PROGN));
		progn.addAll(parts.subList(1, parts.size()));
		progn.add(LispNil.INSTANCE);
		return listToCons(progn);
	}

	/**
	 * The call-time stub the WASM backends lower a {@code funcall} whose arity exceeds
	 * the fixed dispatch-function range to. The WASM dispatch functions occupy a fixed
	 * index range (one per arity up to the backend maximum), so an over-arity site cannot
	 * dispatch -- but it can be a dead branch (cl-postgres' 9-argument make-ssl-stream
	 * funcall, never reached without SSL), so it must stay compilable.
	 * @param arity the call site's argument count
	 * @return the signaling expression
	 */
	public static LispVal overArityFuncallStub(int arity) {
		return listToCons(List.of(new LispSymbol(LispNames.ERROR),
				new LispString("funcall with " + arity + " arguments is not supported on the WASM backends")));
	}

	/**
	 * Expands {@code (define-modify-macro name (params...) function [doc])} into a
	 * {@code defmacro} that rewrites {@code (name place args...)} to
	 * {@code (setf place (function place args...))}. A trailing
	 * {@code &rest}/{@code &body} parameter is spliced into the function call via
	 * {@code list*}; {@code &optional} markers are dropped and the optional variables
	 * passed positionally. Lite: the place subforms may be evaluated more than once (no
	 * {@code get-setf-expansion} single evaluation) and the optional documentation string
	 * is ignored.
	 * @param cons the define-modify-macro expression
	 * @return an equivalent {@code (defmacro ...)} form
	 */
	public static LispVal expandDefineModifyMacro(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 4) {
			throw new IllegalArgumentException(
					"define-modify-macro expects (define-modify-macro name (params...) function [doc])");
		}
		LispVal name = parts.get(1);
		LispVal lambdaList = parts.get(2);
		LispVal function = parts.get(3);
		// Collect the parameter variables, tracking a trailing &rest/&body variable.
		List<LispVal> positional = new ArrayList<>();
		LispVal restVar = null;
		LispVal ll = lambdaList;
		boolean nextIsRest = false;
		while (ll instanceof LispCons llc) {
			LispVal item = llc.car();
			if (item instanceof LispSymbol s
					&& (LispNames.LAMBDA_REST.equals(s.name()) || LispNames.LAMBDA_BODY.equals(s.name()))) {
				nextIsRest = true;
			}
			else if (item instanceof LispSymbol s && LispNames.LAMBDA_OPTIONAL.equals(s.name())) {
				// drop the marker; optional vars are passed positionally
			}
			else if (nextIsRest) {
				restVar = item;
			}
			else {
				// (var default) for &optional -> take the variable name
				positional.add(item instanceof LispCons pc ? pc.car() : item);
			}
			ll = llc.cdr();
		}
		LispSymbol place = new LispSymbol("__modify_place");
		// Build the function call constructor: (list* 'function place pos... restVar) or
		// (list 'function place pos...).
		List<LispVal> builderArgs = new ArrayList<>();
		builderArgs.add(new LispSymbol(restVar != null ? LispNames.LIST_STAR : LispNames.LIST));
		builderArgs.add(listToCons(List.of(new LispSymbol(LispNames.QUOTE), function)));
		builderArgs.add(place);
		builderArgs.addAll(positional);
		if (restVar != null) {
			builderArgs.add(restVar);
		}
		LispVal builder = listToCons(builderArgs);
		// (list 'setf place builder)
		LispVal body = listToCons(List.of(new LispSymbol(LispNames.LIST),
				listToCons(List.of(new LispSymbol(LispNames.QUOTE), new LispSymbol(LispNames.SETF))), place, builder));
		// (defmacro name (place . lambdaList) body)
		LispVal macroLambdaList = new LispCons(place, lambdaList);
		return listToCons(List.of(new LispSymbol(LispNames.DEFMACRO), name, macroLambdaList, body));
	}

	/**
	 * Expands {@code (define-compiler-macro name lambda-list body...)} to {@code nil}: a
	 * compiler macro is only an optimization hint, so dropping it is correct -- the
	 * ordinary function definition remains authoritative (same result, only slower). Same
	 * parsed-no-op pattern as {@link #expandDeclaim}/{@link #expandDeftype}.
	 * @param cons the define-compiler-macro expression
	 * @return nil
	 */
	public static LispVal expandDefineCompilerMacro(LispCons cons) {
		return LispNil.INSTANCE;
	}

	// ------------------------------------------------------------------
	// The restart system (todo-196): handler-bind + the dynamic restart stack +
	// find-restart/invoke-restart, shared by the interpreter and both compilers.
	//
	// Both stacks are TOP-LEVEL GLOBALS mutated with plain setq and restored
	// through unwind-protect over a lexically saved value -- deliberately NOT
	// special-let rebindings, because the compile paths skip the special-binding
	// restore on the error/throw unwind channels (.todo/192) while unwind-protect
	// cleanups run on every channel on every backend. The non-local transfer of an
	// invoked restart-case clause rides catch/throw (runtime cons tag, eq
	// identity), so it crosses functions, runs intervening unwind-protect cleanups
	// and passes through handler-case regions -- all pinned existing behavior.
	// Clause bodies are compiled INLINE in the dispatch (never wrapped in a
	// lambda), so a lexical (go start) out of a clause into an enclosing tagbody
	// stays a same-function go (postmodern's retry-transaction).

	private static final String RC_TAG_VAR = "__rc_tag";

	private static final String RC_RES_VAR = "__rc_res";

	private static final String RC_SAVED_VAR = "__rc_saved";

	private static final String RC_ARGS_VAR = "__rc_args";

	private static final String RC_IDX_VAR = "__rc_idx";

	private static final String HB_SAVED_VAR = "__hb_saved";

	private static final String HB_COND_VAR = "__hb_cond";

	/**
	 * Expands
	 * {@code (restart-case form (restart-name (args...) [options...] body...)...)}: the
	 * primary form runs with one restart record per clause pushed onto the dynamic
	 * restart stack; an invoked restart throws {@code (index . args)} to a fresh
	 * eq-unique catch tag, so control unwinds back to this frame (restoring the stack
	 * through the unwind-protect cleanup) and the clause body runs INLINE in the
	 * restart-case's own lexical environment with the invocation arguments bound
	 * positionally. Normal completion carries the primary form's values through
	 * {@code multiple-value-list}/{@code values-list}. Clause options: {@code :report}
	 * (string or function), {@code :interactive} and {@code :test} are stored in the
	 * record (nothing in-tree renders or invokes them interactively -- no debugger).
	 * Lite: {@code &optional} clause parameters take nil instead of their default when
	 * not supplied, and there is no condition-restart association.
	 * @param cons the restart-case expression
	 * @return the expanded expression
	 */
	public static LispVal expandRestartCase(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			return LispNil.INSTANCE;
		}
		LispVal primary = parts.get(1);
		if (parts.size() == 2) {
			return primary;
		}
		List<RestartClause> clauses = new java.util.ArrayList<>();
		for (int i = 2; i < parts.size(); i++) {
			clauses.add(parseRestartClause(parts.get(i), cons));
		}
		LispSymbol tagVar = new LispSymbol(RC_TAG_VAR);
		LispSymbol resVar = new LispSymbol(RC_RES_VAR);
		LispSymbol savedVar = new LispSymbol(RC_SAVED_VAR);
		LispSymbol argsVar = new LispSymbol(RC_ARGS_VAR);
		LispSymbol idxVar = new LispSymbol(RC_IDX_VAR);
		LispSymbol clustersVar = new LispSymbol(LispNames.RESTART_CLUSTERS_VAR);
		// (list (list '%restart 'name (lambda (__rc_args) (throw __rc_tag (cons i
		// __rc_args))) report interactive test) ...)
		List<LispVal> clusterParts = new java.util.ArrayList<>();
		clusterParts.add(new LispSymbol(LispNames.LIST));
		for (int i = 0; i < clauses.size(); i++) {
			RestartClause clause = clauses.get(i);
			LispVal invoker = listToCons(List.of(new LispSymbol(LispNames.LAMBDA),
					listToCons(List.<LispVal>of(argsVar)), listToCons(List.of(new LispSymbol(LispNames.THROW), tagVar,
							listToCons(List.of(new LispSymbol(LispNames.CONS), new LispInteger(i), argsVar))))));
			clusterParts.add(listToCons(List.of(new LispSymbol(LispNames.LIST), quoteOf(LispNames.RESTART_RECORD_TAG),
					listToCons(List.of(new LispSymbol(LispNames.QUOTE), clause.name())), invoker, clause.report(),
					clause.interactive(), clause.test())));
		}
		LispVal push = listToCons(List.of(new LispSymbol(LispNames.SETQ), clustersVar,
				listToCons(List.of(new LispSymbol(LispNames.CONS), listToCons(clusterParts), clustersVar))));
		LispVal normal = listToCons(List.of(new LispSymbol(LispNames.CONS), new LispInteger(-1),
				callOf(LispNames.MULTIPLE_VALUE_LIST, primary)));
		LispVal restore = listToCons(List.of(new LispSymbol(LispNames.SETQ), clustersVar, savedVar));
		LispVal catchForm = listToCons(List.of(new LispSymbol(LispNames.CATCH), tagVar,
				makeLet(RC_SAVED_VAR, clustersVar, listToCons(List.of(new LispSymbol(LispNames.UNWIND_PROTECT),
						listToCons(List.of(new LispSymbol(LispNames.PROGN), push, normal)), restore)))));
		LispVal dispatch = callOf(LispNames.VALUES_LIST, argsVar);
		for (int i = clauses.size() - 1; i >= 0; i--) {
			dispatch = makeIf(listToCons(List.of(new LispSymbol(LispNames.EQL), idxVar, new LispInteger(i))),
					clauses.get(i).bindParams(argsVar), dispatch);
		}
		LispVal inner = listToCons(List.of(new LispSymbol(LispNames.LET),
				listToCons(List.of(listToCons(List.of(idxVar, callOf(LispNames.CAR, resVar))),
						listToCons(List.of(argsVar, callOf(LispNames.CDR, resVar))))),
				dispatch));
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR),
				listToCons(List.of(
						listToCons(List.of(tagVar, callOf(LispNames.LIST, quoteOf(LispNames.RESTART_RECORD_TAG)))),
						listToCons(List.of(resVar, catchForm)))),
				inner));
	}

	/**
	 * The historical lite lowering of {@code restart-case} to its primary form only, kept
	 * for {@code --no-gc}: its value model has no condition objects (it rejects the
	 * catching forms outright), so restart records cannot exist there and nothing can
	 * invoke a clause -- the lite lowering is behavior-identical for it. Every other
	 * backend uses {@link #expandRestartCase}.
	 * @param cons the restart-case expression
	 * @return the primary form (nil when absent)
	 */
	public static LispVal expandRestartCaseLite(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			return LispNil.INSTANCE;
		}
		return parts.get(1);
	}

	/** One parsed {@code restart-case} clause; see {@link #parseRestartClause}. */
	private record RestartClause(LispSymbol name, List<LispVal> params, LispVal report, LispVal interactive,
			LispVal test, List<LispVal> body) {

		/**
		 * Builds the clause body with the parameters bound positionally from the
		 * invocation-argument list: required (and {@code &optional}, lite: nil when
		 * missing, defaults ignored) parameters read {@code (nth k args)}, a
		 * {@code &rest} parameter reads {@code (nthcdr k args)}.
		 */
		LispVal bindParams(LispSymbol argsVar) {
			List<LispVal> bindings = new java.util.ArrayList<>();
			int pos = 0;
			boolean rest = false;
			for (LispVal p : this.params) {
				if (p instanceof LispSymbol marker && LispNames.LAMBDA_OPTIONAL.equals(marker.name())) {
					continue;
				}
				if (p instanceof LispSymbol marker && LispNames.LAMBDA_REST.equals(marker.name())) {
					rest = true;
					continue;
				}
				LispVal var = p instanceof LispCons pc ? pc.car() : p;
				String reader = rest ? LispNames.NTHCDR : LispNames.NTH;
				bindings.add(listToCons(
						List.of(var, listToCons(List.of(new LispSymbol(reader), new LispInteger(pos), argsVar)))));
				if (!rest) {
					pos++;
				}
			}
			LispVal bodyForm = prognOrNil(this.body);
			if (bindings.isEmpty()) {
				return bodyForm;
			}
			return listToCons(List.of(new LispSymbol(LispNames.LET), listToCons(bindings), bodyForm));
		}
	}

	/**
	 * Parses {@code (name (params...) [:report r] [:interactive i] [:test t] body...)}.
	 */
	private static RestartClause parseRestartClause(LispVal form, LispCons restartCase) {
		if (!(form instanceof LispCons clause) || !(clause.car() instanceof LispSymbol nameSym)) {
			throw new IllegalArgumentException(
					LispNames.RESTART_CASE + " expects (name (params...) body...) clauses: " + restartCase.print());
		}
		List<LispVal> cp = clause.toList();
		if (cp.size() < 2) {
			throw new IllegalArgumentException(
					LispNames.RESTART_CASE + " clause needs a lambda list: " + restartCase.print());
		}
		List<LispVal> params = cp.get(1) instanceof LispCons paramList ? paramList.toList() : List.of();
		LispVal report = LispNil.INSTANCE;
		LispVal interactive = LispNil.INSTANCE;
		LispVal test = LispNil.INSTANCE;
		int i = 2;
		while (i + 1 < cp.size() && cp.get(i) instanceof LispSymbol kw && kw.isKeyword()
				&& (":REPORT".equals(kw.name()) || ":INTERACTIVE".equals(kw.name()) || ":TEST".equals(kw.name()))) {
			LispVal value = restartOptionValue(cp.get(i + 1));
			switch (kw.name()) {
				case ":REPORT" -> report = value;
				case ":INTERACTIVE" -> interactive = value;
				default -> test = value;
			}
			i += 2;
		}
		return new RestartClause(nameSym, params, report, interactive, test, cp.subList(i, cp.size()));
	}

	/**
	 * A restart-clause option value as a stored expression: a string stays itself, a
	 * function NAME becomes {@code (function name)}, anything else (a lambda expression)
	 * is stored as written and evaluated at establishment.
	 */
	private static LispVal restartOptionValue(LispVal value) {
		if (value instanceof LispSymbol sym && !sym.isKeyword()) {
			return listToCons(List.of(new LispSymbol(LispNames.FUNCTION), sym));
		}
		return value;
	}

	/**
	 * Expands {@code (handler-bind ((type handler)...) body...)}: the handler expressions
	 * are evaluated on entry and pushed as one cluster of
	 * {@code (type-test-closure . handler)} entries onto the dynamic handler stack,
	 * restored through unwind-protect on every exit channel. The signal-designator
	 * expansions call {@code %run-handlers} at the signal point BEFORE unwinding, so a
	 * handler runs with the signaling frame's restarts still established; a handler that
	 * returns declines. The type test is the {@code handler-case} clause test compiled
	 * into a closure over the condition.
	 * @param cons the handler-bind expression
	 * @param closRegistry the class registry resolving the clause types
	 * @return the expanded expression
	 */
	public static LispVal expandHandlerBind(LispCons cons, ClosRegistry closRegistry) {
		return expandHandlerBind(cons, closRegistry, false);
	}

	/**
	 * The {@code handler-bind} expansion {@code FreeVarAnalyzer} walks: the clause type
	 * tests are replaced by {@code t}, so an unknown or compound type spec cannot reject
	 * the analysis -- the variable structure (bound temps, handler expressions, body) is
	 * identical to the compile-time expansion's.
	 * @param cons the handler-bind expression
	 * @return the analysis expansion
	 */
	public static LispVal expandHandlerBindForAnalysis(LispCons cons) {
		return expandHandlerBind(cons, EMPTY_CLOS_REGISTRY, true);
	}

	private static LispVal expandHandlerBind(LispCons cons, ClosRegistry closRegistry, boolean analysisOnly) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException(
					LispNames.HANDLER_BIND + " expects ((type handler)...) bindings: " + cons.print());
		}
		LispSymbol clustersVar = new LispSymbol(LispNames.HANDLER_CLUSTERS_VAR);
		LispSymbol savedVar = new LispSymbol(HB_SAVED_VAR);
		LispSymbol condVar = new LispSymbol(HB_COND_VAR);
		List<LispVal> clusterParts = new java.util.ArrayList<>();
		clusterParts.add(new LispSymbol(LispNames.LIST));
		if (parts.get(1) instanceof LispCons bindingList) {
			for (LispVal binding : bindingList.toList()) {
				if (!(binding instanceof LispCons bindingCons) || bindingCons.toList().size() != 2) {
					throw new IllegalArgumentException(
							LispNames.HANDLER_BIND + " expects (type handler) bindings: " + cons.print());
				}
				List<LispVal> bp = bindingCons.toList();
				LispVal test = analysisOnly ? LispTrue.INSTANCE : makeHandlerTypeTest(condVar, bp.get(0), closRegistry);
				LispVal testLambda = listToCons(
						List.of(new LispSymbol(LispNames.LAMBDA), listToCons(List.<LispVal>of(condVar)), test));
				clusterParts.add(listToCons(List.of(new LispSymbol(LispNames.CONS), testLambda, bp.get(1))));
			}
		}
		LispVal push = listToCons(List.of(new LispSymbol(LispNames.SETQ), clustersVar,
				listToCons(List.of(new LispSymbol(LispNames.CONS), listToCons(clusterParts), clustersVar))));
		LispVal restore = listToCons(List.of(new LispSymbol(LispNames.SETQ), clustersVar, savedVar));
		return makeLet(HB_SAVED_VAR, clustersVar,
				listToCons(List.of(new LispSymbol(LispNames.UNWIND_PROTECT), listToCons(
						List.of(new LispSymbol(LispNames.PROGN), push, prognOrNil(parts.subList(2, parts.size())))),
						restore)));
	}

	/**
	 * Expands {@code (restart-bind ((name function ...)...) body...)}: like
	 * {@link #expandRestartCase} the records are pushed for the body's extent, but an
	 * invoked restart CALLS the bound function at the invocation point (no non-local exit
	 * -- the CL semantics; the function must transfer control itself if it wants to).
	 * Trailing per-binding keyword options ({@code :report-function} etc.) are accepted;
	 * {@code :report-function} is stored as the record's report. The bound function
	 * receives the invocation arguments through an arity-dispatched {@code funcall} chain
	 * (0..7 arguments, the WASM dispatch ceiling) -- NOT {@code apply}, whose runtime
	 * helper is gated on a surface scan that cannot see this expansion (and which would
	 * drag the WASM eval runtime into every restart-bind program).
	 * @param cons the restart-bind expression
	 * @return the expanded expression
	 */
	public static LispVal expandRestartBind(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException(
					LispNames.RESTART_BIND + " expects ((name function)...) bindings: " + cons.print());
		}
		LispSymbol clustersVar = new LispSymbol(LispNames.RESTART_CLUSTERS_VAR);
		LispSymbol savedVar = new LispSymbol(RC_SAVED_VAR);
		LispSymbol argsVar = new LispSymbol(RC_ARGS_VAR);
		LispSymbol fnVar = new LispSymbol("__rb_fn");
		List<LispVal> clusterParts = new java.util.ArrayList<>();
		clusterParts.add(new LispSymbol(LispNames.LIST));
		if (parts.get(1) instanceof LispCons bindingList) {
			for (LispVal binding : bindingList.toList()) {
				if (!(binding instanceof LispCons bindingCons) || !(bindingCons.car() instanceof LispSymbol nameSym)
						|| !(bindingCons.cdr() instanceof LispCons fnCons)) {
					throw new IllegalArgumentException(
							LispNames.RESTART_BIND + " expects (name function ...) bindings: " + cons.print());
				}
				List<LispVal> bp = bindingCons.toList();
				LispVal report = LispNil.INSTANCE;
				for (int i = 2; i + 1 < bp.size(); i += 2) {
					if (bp.get(i) instanceof LispSymbol kw && ":REPORT-FUNCTION".equals(kw.name())) {
						report = bp.get(i + 1);
					}
				}
				LispVal invoker = makeLet(fnVar.name(), fnCons.car(),
						listToCons(List.of(new LispSymbol(LispNames.LAMBDA), listToCons(List.<LispVal>of(argsVar)),
								arityDispatchedCall(fnVar, argsVar))));
				clusterParts
					.add(listToCons(List.of(new LispSymbol(LispNames.LIST), quoteOf(LispNames.RESTART_RECORD_TAG),
							listToCons(List.of(new LispSymbol(LispNames.QUOTE), nameSym)), invoker, report,
							LispNil.INSTANCE, LispNil.INSTANCE)));
			}
		}
		LispVal push = listToCons(List.of(new LispSymbol(LispNames.SETQ), clustersVar,
				listToCons(List.of(new LispSymbol(LispNames.CONS), listToCons(clusterParts), clustersVar))));
		LispVal restore = listToCons(List.of(new LispSymbol(LispNames.SETQ), clustersVar, savedVar));
		return makeLet(RC_SAVED_VAR, clustersVar,
				listToCons(List.of(new LispSymbol(LispNames.UNWIND_PROTECT), listToCons(
						List.of(new LispSymbol(LispNames.PROGN), push, prognOrNil(parts.subList(2, parts.size())))),
						restore)));
	}

	/**
	 * Expands {@code (with-simple-restart (name format-control format-args...)
	 * body...)} into the equivalent {@code restart-case} whose named clause returns
	 * {@code (values nil t)} from the form (the CL contract). The format control (and
	 * lite: its arguments, dropped) become the restart's report.
	 * @param cons the with-simple-restart expression
	 * @return the expanded expression
	 */
	public static LispVal expandWithSimpleRestart(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2 || !(parts.get(1) instanceof LispCons spec)
				|| !(spec.car() instanceof LispSymbol nameSym)) {
			throw new IllegalArgumentException(
					LispNames.WITH_SIMPLE_RESTART + " expects (name format-control args...): " + cons.print());
		}
		List<LispVal> specParts = spec.toList();
		LispVal report = specParts.size() > 1 ? specParts.get(1) : LispNil.INSTANCE;
		LispVal valuesForm = listToCons(List.of(new LispSymbol(LispNames.VALUES), LispNil.INSTANCE, LispTrue.INSTANCE));
		LispVal clause = listToCons(List.of(nameSym, LispNil.INSTANCE, new LispSymbol(":REPORT"), report, valuesForm));
		return listToCons(
				List.of(new LispSymbol(LispNames.RESTART_CASE), prognOrNil(parts.subList(2, parts.size())), clause));
	}

	/**
	 * Builds {@code (funcall fn args...)} dispatched on {@code (length args)} for 0..7
	 * arguments (the WASM funcall dispatch ceiling); more signal a call-time error.
	 */
	private static LispVal arityDispatchedCall(LispSymbol fnVar, LispSymbol argsVar) {
		LispVal dispatch = callTimeUnsupportedStub(
				"a restart-bind function takes at most 7 invocation arguments on rontolisp");
		LispSymbol lenVar = new LispSymbol("__rb_n");
		for (int arity = 7; arity >= 0; arity--) {
			List<LispVal> callParts = new java.util.ArrayList<>();
			callParts.add(new LispSymbol(LispNames.FUNCALL));
			callParts.add(fnVar);
			for (int i = 0; i < arity; i++) {
				callParts.add(listToCons(List.of(new LispSymbol(LispNames.NTH), new LispInteger(i), argsVar)));
			}
			dispatch = makeIf(listToCons(List.of(new LispSymbol(LispNames.EQL), lenVar, new LispInteger(arity))),
					listToCons(callParts), dispatch);
		}
		return makeLet(lenVar.name(), callOf(LispNames.LENGTH, argsVar), dispatch);
	}

	/** The surface operators that flip a program into restart mode. */
	private static final java.util.Set<String> RESTART_SYSTEM_MACROS = java.util.Set.of(LispNames.HANDLER_BIND,
			LispNames.RESTART_CASE, LispNames.RESTART_BIND, LispNames.WITH_SIMPLE_RESTART);

	/** The restart-runtime defun names (also restart-mode triggers when called). */
	public static final java.util.Set<String> RESTART_RUNTIME_FUNCTION_NAMES = java.util.Set.of(
			LispNames.INVOKE_RESTART, LispNames.FIND_RESTART, LispNames.COMPUTE_RESTARTS, LispNames.RESTART_NAME,
			LispNames.MUFFLE_WARNING, LispNames.ABORT, LispNames.CONTINUE);

	/**
	 * Whether the program uses the restart system: any {@code handler-bind} /
	 * {@code restart-case} / {@code restart-bind} / {@code with-simple-restart} form, or
	 * a call to (or {@code #'} reference of) a restart-runtime function. The compilers
	 * consume this ONCE per program: it gates the restart-runtime defun injection
	 * ({@code expandTopLevelDefinitions}), the {@code %run-handlers} call in the
	 * signal-designator expansions, the real {@code cerror}, and forces the catch/throw
	 * exit channel (JVM {@code blockExitChannel} / WASM {@code blockExitTag}, which
	 * implies EH mode) because the expansions ride it. A program without any of the
	 * operators stays byte-identical.
	 * @param program the top-level forms (post library splice)
	 * @return whether the restart machinery is needed
	 */
	public static boolean usesRestartSystem(List<LispVal> program) {
		for (LispVal form : program) {
			if (usesRestartSystemForm(form)) {
				return true;
			}
		}
		return false;
	}

	private static boolean usesRestartSystemForm(LispVal form) {
		if (!(form instanceof LispCons cons)) {
			return false;
		}
		if (cons.car() instanceof LispSymbol head) {
			String name = head.name();
			int sep = name.lastIndexOf(':');
			String plain = sep >= 0 ? name.substring(sep + 1) : name;
			if (RESTART_SYSTEM_MACROS.contains(plain) || RESTART_RUNTIME_FUNCTION_NAMES.contains(plain)) {
				return true;
			}
			if (LispNames.FUNCTION.equals(name) && cons.cdr() instanceof LispCons fnCons
					&& fnCons.car() instanceof LispSymbol fnSym
					&& RESTART_RUNTIME_FUNCTION_NAMES.contains(fnSym.name())) {
				return true;
			}
		}
		return usesRestartSystemForm(cons.car()) || usesRestartSystemForm(cons.cdr());
	}

	/**
	 * The restart-runtime forms: the two stack globals plus the defuns
	 * ({@code %run-handlers}, {@code find-restart}, {@code invoke-restart},
	 * {@code compute-restarts}, {@code restart-name}, {@code muffle-warning},
	 * {@code abort}, {@code continue}). The compile path injects them once per
	 * restart-mode program ({@code expandTopLevelDefinitions}); the interpreter evaluates
	 * them on the first restart-system form or the first resolution of one of the
	 * function names (the {@code slotUnboundDefuns} pattern). A restart record is the
	 * list {@code (%restart name invoker report interactive test)} whose invoker takes
	 * the invocation-argument LIST (one fixed-arity funcall -- no apply, which would drag
	 * the WASM eval runtime into every restart-mode program).
	 * @return the defvar and defun forms, in evaluation order
	 */
	public static List<LispVal> restartRuntimeForms() {
		List<LispVal> forms = new java.util.ArrayList<>(restartRuntimeGlobalForms());
		forms.addAll(restartRuntimeDefunForms(java.util.Set.of()));
		return forms;
	}

	/**
	 * The two restart-runtime stack globals, nil-initialized (prepended on the compile
	 * path).
	 * @return the defvar forms for the handler and restart cluster stacks
	 */
	public static List<LispVal> restartRuntimeGlobalForms() {
		return List.of(
				listToCons(List.of(new LispSymbol(LispNames.DEFVAR), new LispSymbol(LispNames.HANDLER_CLUSTERS_VAR),
						LispNil.INSTANCE)),
				listToCons(List.of(new LispSymbol(LispNames.DEFVAR), new LispSymbol(LispNames.RESTART_CLUSTERS_VAR),
						LispNil.INSTANCE)));
	}

	/**
	 * The restart-runtime defuns, skipping names the user program defines itself.
	 * @param userDefinedNames function names defined by the program
	 * @return the defun forms
	 */
	public static List<LispVal> restartRuntimeDefunForms(java.util.Set<String> userDefinedNames) {
		List<LispVal> forms = new java.util.ArrayList<>();
		forms.add(runHandlersDefun());
		if (!userDefinedNames.contains(LispNames.FIND_RESTART)) {
			forms.add(findRestartDefun());
		}
		if (!userDefinedNames.contains(LispNames.INVOKE_RESTART)) {
			forms.add(invokeRestartDefun());
		}
		if (!userDefinedNames.contains(LispNames.COMPUTE_RESTARTS)) {
			forms.add(computeRestartsDefun());
		}
		if (!userDefinedNames.contains(LispNames.RESTART_NAME)) {
			forms.add(restartNameDefun());
		}
		if (!userDefinedNames.contains(LispNames.MUFFLE_WARNING)) {
			forms.add(muffleWarningDefun());
		}
		if (!userDefinedNames.contains(LispNames.ABORT)) {
			forms.add(abortDefun());
		}
		if (!userDefinedNames.contains(LispNames.CONTINUE)) {
			forms.add(continueDefun());
		}
		return forms;
	}

	// (defun %run-handlers (__rh_c)
	// (let ((__rh_clusters %handler-clusters%))
	// (while (consp __rh_clusters)
	// (let ((__rh_cluster (car __rh_clusters)))
	// (setq __rh_clusters (cdr __rh_clusters))
	// (let ((__rh_saved %handler-clusters%))
	// (unwind-protect
	// (progn
	// (setq %handler-clusters% __rh_clusters) ; CLHS: handlers run
	// (let ((__rh_entries __rh_cluster)) ; outside their cluster
	// (while (consp __rh_entries)
	// (when (funcall (car (car __rh_entries)) __rh_c)
	// (funcall (cdr (car __rh_entries)) __rh_c))
	// (setq __rh_entries (cdr __rh_entries)))))
	// (setq %handler-clusters% __rh_saved))))))
	// nil)
	private static LispVal runHandlersDefun() {
		LispSymbol c = new LispSymbol("__rh_c");
		LispSymbol clusters = new LispSymbol("__rh_clusters");
		LispSymbol cluster = new LispSymbol("__rh_cluster");
		LispSymbol saved = new LispSymbol("__rh_saved");
		LispSymbol entries = new LispSymbol("__rh_entries");
		LispSymbol globalVar = new LispSymbol(LispNames.HANDLER_CLUSTERS_VAR);
		LispVal entry = callOf(LispNames.CAR, entries);
		LispVal callEntry = makeIf(
				listToCons(List.of(new LispSymbol(LispNames.FUNCALL), callOf(LispNames.CAR, entry), c)),
				listToCons(List.of(new LispSymbol(LispNames.FUNCALL), callOf(LispNames.CDR, entry), c)),
				LispNil.INSTANCE);
		LispVal entriesLoop = makeLet(entries.name(), cluster,
				listToCons(List.of(new LispSymbol(LispNames.WHILE), callOf(LispNames.CONSP, entries), callEntry,
						listToCons(List.of(new LispSymbol(LispNames.SETQ), entries, callOf(LispNames.CDR, entries))))));
		LispVal runCluster = makeLet(saved.name(), globalVar,
				listToCons(List.of(new LispSymbol(LispNames.UNWIND_PROTECT),
						listToCons(List.of(new LispSymbol(LispNames.PROGN),
								listToCons(List.of(new LispSymbol(LispNames.SETQ), globalVar, clusters)), entriesLoop)),
						listToCons(List.of(new LispSymbol(LispNames.SETQ), globalVar, saved)))));
		LispVal clustersLoop = makeLet(clusters.name(), globalVar, listToCons(List.of(new LispSymbol(LispNames.WHILE),
				callOf(LispNames.CONSP, clusters),
				makeLet(cluster.name(), callOf(LispNames.CAR, clusters),
						listToCons(List.of(new LispSymbol(LispNames.PROGN), listToCons(
								List.of(new LispSymbol(LispNames.SETQ), clusters, callOf(LispNames.CDR, clusters))),
								runCluster))))));
		return listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.RUN_HANDLERS_INTERNAL),
				listToCons(List.<LispVal>of(c)), clustersLoop, LispNil.INSTANCE));
	}

	// (defun find-restart (__fr_id &optional __fr_c)
	// (if (and (consp __fr_id) (eq (car __fr_id) '%restart))
	// __fr_id
	// (let ((__fr_clusters %restart-clusters%) (__fr_found nil))
	// (while (and (null __fr_found) (consp __fr_clusters))
	// (let ((__fr_entries (car __fr_clusters)))
	// (while (and (null __fr_found) (consp __fr_entries))
	// (when (eq (car (cdr (car __fr_entries))) __fr_id)
	// (setq __fr_found (car __fr_entries)))
	// (setq __fr_entries (cdr __fr_entries))))
	// (setq __fr_clusters (cdr __fr_clusters)))
	// __fr_found)))
	private static LispVal findRestartDefun() {
		LispSymbol id = new LispSymbol("__fr_id");
		LispSymbol cond = new LispSymbol("__fr_c");
		LispSymbol clusters = new LispSymbol("__fr_clusters");
		LispSymbol found = new LispSymbol("__fr_found");
		LispSymbol entries = new LispSymbol("__fr_entries");
		LispSymbol globalVar = new LispSymbol(LispNames.RESTART_CLUSTERS_VAR);
		LispVal isRecord = listToCons(List.of(new LispSymbol(LispNames.AND), callOf(LispNames.CONSP, id),
				listToCons(List.of(new LispSymbol(LispNames.EQ_GENERAL), callOf(LispNames.CAR, id),
						quoteOf(LispNames.RESTART_RECORD_TAG)))));
		LispVal entryName = callOf(LispNames.CAR, callOf(LispNames.CDR, callOf(LispNames.CAR, entries)));
		LispVal innerLoop = makeLet(entries.name(), callOf(LispNames.CAR, clusters),
				listToCons(List.of(new LispSymbol(LispNames.WHILE),
						listToCons(List.of(new LispSymbol(LispNames.AND), callOf(LispNames.NULL, found),
								callOf(LispNames.CONSP, entries))),
						makeIf(listToCons(List.of(new LispSymbol(LispNames.EQ_GENERAL), entryName, id)),
								listToCons(
										List.of(new LispSymbol(LispNames.SETQ), found, callOf(LispNames.CAR, entries))),
								LispNil.INSTANCE),
						listToCons(List.of(new LispSymbol(LispNames.SETQ), entries, callOf(LispNames.CDR, entries))))));
		LispVal outerLoop = listToCons(List.of(new LispSymbol(LispNames.WHILE),
				listToCons(List.of(new LispSymbol(LispNames.AND), callOf(LispNames.NULL, found),
						callOf(LispNames.CONSP, clusters))),
				innerLoop,
				listToCons(List.of(new LispSymbol(LispNames.SETQ), clusters, callOf(LispNames.CDR, clusters)))));
		LispVal search = listToCons(List.of(new LispSymbol(LispNames.LET), listToCons(
				List.of(listToCons(List.of(clusters, globalVar)), listToCons(List.of(found, LispNil.INSTANCE)))),
				outerLoop, found));
		return listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.FIND_RESTART),
				listToCons(List.of(id, new LispSymbol(LispNames.LAMBDA_OPTIONAL), cond)),
				makeIf(isRecord, id, search)));
	}

	// (defun invoke-restart (__ir_r &rest __ir_args)
	// (let ((__ir_restart (find-restart __ir_r)))
	// (if (null __ir_restart)
	// (error "No active restart: ~a" __ir_r)
	// (funcall (car (cdr (cdr __ir_restart))) __ir_args))))
	private static LispVal invokeRestartDefun() {
		LispSymbol r = new LispSymbol("__ir_r");
		LispSymbol args = new LispSymbol("__ir_args");
		LispSymbol restart = new LispSymbol("__ir_restart");
		LispVal invoker = callOf(LispNames.CAR, callOf(LispNames.CDR, callOf(LispNames.CDR, restart)));
		LispVal body = makeLet(restart.name(), callOf(LispNames.FIND_RESTART, r),
				makeIf(callOf(LispNames.NULL, restart),
						listToCons(
								List.of(new LispSymbol(LispNames.ERROR), new LispString("No active restart: ~a"), r)),
						listToCons(List.of(new LispSymbol(LispNames.FUNCALL), invoker, args))));
		return listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.INVOKE_RESTART),
				listToCons(List.of(r, new LispSymbol(LispNames.LAMBDA_REST), args)), body));
	}

	// (defun compute-restarts (&optional __cr_c)
	// (let ((__cr_out nil) (__cr_clusters %restart-clusters%))
	// (while (consp __cr_clusters)
	// (let ((__cr_entries (car __cr_clusters)))
	// (while (consp __cr_entries)
	// (setq __cr_out (cons (car __cr_entries) __cr_out))
	// (setq __cr_entries (cdr __cr_entries))))
	// (setq __cr_clusters (cdr __cr_clusters)))
	// (nreverse __cr_out)))
	private static LispVal computeRestartsDefun() {
		LispSymbol cond = new LispSymbol("__cr_c");
		LispSymbol out = new LispSymbol("__cr_out");
		LispSymbol clusters = new LispSymbol("__cr_clusters");
		LispSymbol entries = new LispSymbol("__cr_entries");
		LispSymbol globalVar = new LispSymbol(LispNames.RESTART_CLUSTERS_VAR);
		LispVal innerLoop = makeLet(entries.name(), callOf(LispNames.CAR, clusters), listToCons(List.of(
				new LispSymbol(LispNames.WHILE), callOf(LispNames.CONSP, entries),
				listToCons(List.of(new LispSymbol(LispNames.SETQ), out,
						listToCons(List.of(new LispSymbol(LispNames.CONS), callOf(LispNames.CAR, entries), out)))),
				listToCons(List.of(new LispSymbol(LispNames.SETQ), entries, callOf(LispNames.CDR, entries))))));
		LispVal outerLoop = listToCons(List.of(new LispSymbol(LispNames.WHILE), callOf(LispNames.CONSP, clusters),
				innerLoop,
				listToCons(List.of(new LispSymbol(LispNames.SETQ), clusters, callOf(LispNames.CDR, clusters)))));
		LispVal body = listToCons(List.of(new LispSymbol(LispNames.LET),
				listToCons(
						List.of(listToCons(List.of(out, LispNil.INSTANCE)), listToCons(List.of(clusters, globalVar)))),
				outerLoop, callOf(LispNames.NREVERSE, out)));
		return listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.COMPUTE_RESTARTS),
				listToCons(List.of(new LispSymbol(LispNames.LAMBDA_OPTIONAL), cond)), body));
	}

	// (defun restart-name (__rn_r) (car (cdr __rn_r)))
	private static LispVal restartNameDefun() {
		LispSymbol r = new LispSymbol("__rn_r");
		return listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.RESTART_NAME),
				listToCons(List.<LispVal>of(r)), callOf(LispNames.CAR, callOf(LispNames.CDR, r))));
	}

	// (defun muffle-warning (&optional __mw_c) (invoke-restart 'muffle-warning))
	private static LispVal muffleWarningDefun() {
		LispSymbol cond = new LispSymbol("__mw_c");
		return listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.MUFFLE_WARNING),
				listToCons(List.of(new LispSymbol(LispNames.LAMBDA_OPTIONAL), cond)),
				callOf(LispNames.INVOKE_RESTART, quoteOf(LispNames.MUFFLE_WARNING))));
	}

	// (defun abort (&optional __ab_c) (invoke-restart 'abort))
	private static LispVal abortDefun() {
		LispSymbol cond = new LispSymbol("__ab_c");
		return listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.ABORT),
				listToCons(List.of(new LispSymbol(LispNames.LAMBDA_OPTIONAL), cond)),
				callOf(LispNames.INVOKE_RESTART, quoteOf(LispNames.ABORT))));
	}

	// (defun continue (&optional __ct_c)
	// (let ((__ct_r (find-restart 'continue))) (if (null __ct_r) nil (invoke-restart
	// __ct_r))))
	private static LispVal continueDefun() {
		LispSymbol cond = new LispSymbol("__ct_c");
		LispSymbol r = new LispSymbol("__ct_r");
		LispVal body = makeLet(r.name(), callOf(LispNames.FIND_RESTART, quoteOf(LispNames.CONTINUE)),
				makeIf(callOf(LispNames.NULL, r), LispNil.INSTANCE, callOf(LispNames.INVOKE_RESTART, r)));
		return listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.CONTINUE),
				listToCons(List.of(new LispSymbol(LispNames.LAMBDA_OPTIONAL), cond)), body));
	}

	/**
	 * Expands {@code (make-condition 'type initargs...)} into the construction of a
	 * condition instance -- a CLOS-subset tagged list built through the registry's slot
	 * layout (see {@link #buildTypedConstruct}). A non-literal type falls back to the
	 * registry-less string collapse below.
	 * @param cons the make-condition expression
	 * @param closRegistry the class registry
	 * @return the expanded expression
	 */
	public static LispVal expandMakeCondition(LispCons cons, ClosRegistry closRegistry) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException("make-condition expects a condition type: " + cons.print());
		}
		LispSymbol typeSym = quotedSymbol(parts.get(1));
		if (typeSym == null) {
			return expandMakeCondition(cons);
		}
		List<LispVal> bindings = new java.util.ArrayList<>();
		List<LispVal> items = new java.util.ArrayList<>();
		LispVal construct = buildTypedConstruct(typeSym, parts.subList(2, parts.size()),
				closRegistry.findClass(typeSym.name()), bindings, items);
		if (bindings.isEmpty()) {
			return construct;
		}
		List<LispVal> letParts = new java.util.ArrayList<>();
		letParts.add(new LispSymbol(LispNames.LET_STAR));
		letParts.add(listToCons(bindings));
		letParts.add(construct);
		return listToCons(letParts);
	}

	/**
	 * Expands {@code (make-condition type args...)} to its {@code :format-control} value
	 * when one is given, or to the condition type name as a string otherwise -- the
	 * registry-less fallback kept for {@code macroexpand-1}, the {@code --no-gc} backend
	 * (no condition objects there) and non-literal condition types. With a registry, the
	 * overload above builds a real condition instance instead.
	 * @param cons the make-condition expression
	 * @return the expanded expression
	 */
	public static LispVal expandMakeCondition(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException("make-condition expects a condition type: " + cons.print());
		}
		for (int i = 2; i + 1 < parts.size(); i += 2) {
			if (parts.get(i) instanceof LispSymbol key && ":FORMAT-CONTROL".equals(key.name())) {
				return parts.get(i + 1);
			}
		}
		LispVal type = parts.get(1);
		if (type instanceof LispCons quoted && quoted.car() instanceof LispSymbol quoteOp
				&& LispNames.QUOTE.equals(quoteOp.name()) && quoted.cdr() instanceof LispCons datumCell
				&& datumCell.car() instanceof LispSymbol datum) {
			return new LispString("Condition of type " + datum.name() + " was signalled.");
		}
		return new LispString("Condition of type " + type.print() + " was signalled.");
	}

	/**
	 * Expands {@code (documentation name doc-type)} to {@code nil}: docstrings are not
	 * stored anywhere (a {@code (setf (documentation ...) "...")} discards its value the
	 * same way, see {@link #expandSetf}).
	 * @param cons the documentation expression
	 * @return nil
	 */
	public static LispVal expandDocumentation(LispCons cons) {
		return LispNil.INSTANCE;
	}

	/**
	 * Expands {@code (the type form)} to {@code form}: the type assertion is not checked
	 * (there is no compiler type system to inform).
	 * @param cons the the-expression
	 * @return the value form
	 */
	public static LispVal expandThe(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			throw new IllegalArgumentException("the expects a type and a form, got: " + cons.print());
		}
		return parts.get(2);
	}

	/**
	 * Expands {@code (eval-when (situations...) body...)} to {@code (progn body...)}:
	 * every situation is treated as "evaluate now". The compile path's
	 * expand-before-codegen pipeline already approximates {@code :compile-toplevel} for
	 * macros; top-level forms are additionally spliced by {@link #flattenTopLevel} so
	 * nested {@code defun}/{@code defmacro} definitions are collected.
	 * @param cons the eval-when expression
	 * @return the expanded expression
	 */
	/**
	 * Lowers {@code (make-array dims ... :initial-contents list)} for the compiled
	 * backends to the equivalent allocation plus an element-wise fill: the inner
	 * {@code make-array} keeps every other keyword, and the contents list is walked with
	 * {@code %aset} (rank-1; a literal multi-dimension list is rejected -- the
	 * interpreter fills nested contents natively). Returns {@code null} when the form has
	 * no {@code :initial-contents}.
	 * @param cons the make-array expression
	 * @return the lowering, or null
	 */
	@org.jspecify.annotations.Nullable
	public static LispVal lowerInitialContentsMakeArray(LispCons cons) {
		List<LispVal> parts = cons.toList();
		LispVal contents = null;
		List<LispVal> inner = new java.util.ArrayList<>();
		inner.add(new LispSymbol(LispNames.MAKE_ARRAY));
		if (parts.size() >= 2) {
			inner.add(parts.get(1));
		}
		for (int i = 2; i + 1 < parts.size(); i += 2) {
			if (parts.get(i) instanceof LispSymbol kw && LispNames.INITIAL_CONTENTS_KEYWORD.equals(kw.name())) {
				contents = parts.get(i + 1);
			}
			else {
				inner.add(parts.get(i));
				inner.add(parts.get(i + 1));
			}
		}
		if (contents == null) {
			return null;
		}
		if (parts.get(1) instanceof LispCons dims && dims.car() instanceof LispSymbol q
				&& LispNames.QUOTE.equals(q.name()) && dims.cdr() instanceof LispCons dimList
				&& dimList.car() instanceof LispCons literalDims && literalDims.cdr() instanceof LispCons) {
			throw new UnsupportedOperationException(
					"make-array :initial-contents supports rank-1 arrays only on the compiled backends");
		}
		LispSymbol arrVar = new LispSymbol("__mk_arr");
		LispSymbol idxVar = new LispSymbol("__mk_i");
		LispSymbol contentsVar = new LispSymbol("__mk_c");
		LispSymbol lenVar = new LispSymbol("__mk_n");
		// The contents can be ANY sequence (cl-ppcre passes a string), so the fill
		// indexes it with elt instead of walking it as a list.
		LispVal fill = listToCons(List.of(new LispSymbol(LispNames.DO),
				listToCons(List.of(listToCons(
						List.of(idxVar, new LispInteger(0), fmtCall(LispNames.ADD, idxVar, new LispInteger(1)))))),
				listToCons(List.of(fmtCall(LispNames.GE, idxVar, lenVar), arrVar)), listToCons(List
					.of(new LispSymbol(LispNames.ASET), arrVar, idxVar, fmtCall(LispNames.ELT, contentsVar, idxVar)))));
		return makeLet(arrVar.name(), listToCons(inner), makeLet(contentsVar.name(), contents,
				makeLet(lenVar.name(), callOf(LispNames.LENGTH, contentsVar), fill)));
	}

	/**
	 * Whether a literal {@code make-array :element-type} value designates a character
	 * type ({@code character}/{@code base-char}/{@code standard-char}, quoted or bare,
	 * package-qualified or plain).
	 * @param elementType the {@code :element-type} value expression, or null
	 * @return true when it designates a character type
	 */
	public static boolean isCharacterElementType(@Nullable LispVal elementType) {
		LispVal sym = elementType;
		if (sym instanceof LispCons quoteCons && quoteCons.car() instanceof LispSymbol q
				&& LispNames.QUOTE.equals(q.name()) && quoteCons.cdr() instanceof LispCons rest
				&& rest.cdr() instanceof LispNil) {
			sym = rest.car();
		}
		if (!(sym instanceof LispSymbol typeSym)) {
			return false;
		}
		String name = typeSym.name();
		int colon = name.lastIndexOf(':');
		String local = colon >= 0 ? name.substring(colon + 1) : name;
		return local.equals("CHARACTER") || local.equals("BASE-CHAR") || local.equals("STANDARD-CHAR");
	}

	/**
	 * The bare (unquoted) symbols the compile backends' {@code make-array} recognizers
	 * accept as literal {@code :element-type} designators. Any OTHER bare symbol in that
	 * position is a VARIABLE holding a designator computed at run time -- the distinction
	 * {@link #lowerRuntimeElementTypeMakeArray(LispCons)} needs.
	 */
	private static final java.util.Set<String> LITERAL_ELEMENT_TYPE_NAMES = java.util.Set.of("CHARACTER", "BASE-CHAR",
			"STANDARD-CHAR", "FLOAT", "SINGLE-FLOAT", "DOUBLE-FLOAT", "SHORT-FLOAT", "LONG-FLOAT", "BIT", "FIXNUM",
			"INTEGER", "NUMBER", "ATOM");

	/**
	 * Whether a {@code make-array :element-type} value is computed at RUN time rather
	 * than being one of the literal designators every backend's expansion-time
	 * recognizers accept: a {@code (quote ...)} form, the unquoted compound shape
	 * ({@code (unsigned-byte 8)} -- a type name plus an integer), and the bare symbols in
	 * {@link #LITERAL_ELEMENT_TYPE_NAMES} are all literal; anything else evaluable (a
	 * variable, a call like {@code (stream-element-type s)}) is not.
	 * @param elementType the {@code :element-type} value expression
	 * @return true when the designator is only known at run time
	 */
	private static boolean isRuntimeElementType(LispVal elementType) {
		if (elementType instanceof LispCons cons) {
			if (cons.car() instanceof LispSymbol q && LispNames.QUOTE.equals(q.name())) {
				return false;
			}
			return !(cons.cdr() instanceof LispCons rest && rest.car() instanceof LispInteger);
		}
		if (elementType instanceof LispSymbol sym) {
			String name = sym.name();
			int colon = name.lastIndexOf(':');
			return !LITERAL_ELEMENT_TYPE_NAMES.contains(colon >= 0 ? name.substring(colon + 1) : name);
		}
		return false;
	}

	/**
	 * Lowers {@code (make-array n :element-type et ...)} whose {@code :element-type} is a
	 * VARIABLE into a runtime dispatch between the character-vector allocation and the
	 * general one. Returns null when the designator is literal (every backend's existing
	 * expansion-time recognizers handle those) or absent.
	 *
	 * <pre>
	 * (make-array n :element-type et) ->
	 * (let* ((__mae_n n) (__mae_et et))
	 *   (if (member __mae_et '(character base-char standard-char))
	 *       (make-array __mae_n :element-type 'character)
	 *       (make-array __mae_n)))
	 * </pre>
	 *
	 * The character arm matters because a character vector is the ONE rank-1 array that
	 * answers {@code stringp}, which is what {@code read-sequence} /
	 * {@code write-sequence} dispatch on.
	 * {@code alexandria:read-stream-content-into-string} allocates its buffer as
	 * {@code (make-array size :element-type (stream-element-type stream))}, so without
	 * this the buffer was a general vector on the compile backends and the read fell to
	 * {@code read-byte} against a character stream ({@code .todo/219}). The interpreter
	 * needs no lowering: its {@code make-array} already reads the designator at run time.
	 *
	 * <p>
	 * A non-character runtime designator drops the keyword entirely rather than guessing
	 * a packed representation: the packed float / {@code (unsigned-byte N)} arrays are
	 * OPTIMIZATIONS of the general one, so the general array is always a correct answer.
	 * @param cons the make-array expression
	 * @return the lowered expression, or null when the element type is literal or absent
	 */
	public static @Nullable LispVal lowerRuntimeElementTypeMakeArray(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			return null;
		}
		LispVal elementType = null;
		List<LispVal> others = new java.util.ArrayList<>();
		for (int i = 2; i + 1 < parts.size(); i += 2) {
			if (parts.get(i) instanceof LispSymbol kw && LispNames.ELEMENT_TYPE_KEYWORD.equals(kw.name())) {
				elementType = parts.get(i + 1);
			}
			else {
				others.add(parts.get(i));
				others.add(parts.get(i + 1));
			}
		}
		if (elementType == null || !isRuntimeElementType(elementType)) {
			return null;
		}
		LispSymbol size = new LispSymbol("__mae_n");
		LispSymbol et = new LispSymbol("__mae_et");
		List<LispVal> charCall = new java.util.ArrayList<>(
				List.of(new LispSymbol(LispNames.MAKE_ARRAY), size, new LispSymbol(LispNames.ELEMENT_TYPE_KEYWORD),
						listToCons(List.of(new LispSymbol(LispNames.QUOTE), new LispSymbol("CHARACTER")))));
		charCall.addAll(others);
		List<LispVal> generalCall = new java.util.ArrayList<>(List.of(new LispSymbol(LispNames.MAKE_ARRAY), size));
		generalCall.addAll(others);
		LispVal body = makeIf(memberOfTypeNames(et, "CHARACTER", "BASE-CHAR", "STANDARD-CHAR"), listToCons(charCall),
				listToCons(generalCall));
		LispVal bindings = listToCons(
				List.of(listToCons(List.of(size, parts.get(1))), listToCons(List.of(et, elementType))));
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), bindings, body));
	}

	/**
	 * Lowers a rank-1 {@code (make-array n :element-type 'character :initial-contents
	 * c)} to a string copy of the contents: a string (or fill-pointered character vector)
	 * contents yields a fresh {@code subseq} copy of its active content, any other
	 * sequence goes through {@code (coerce c 'string)}. Returns null when the call has
	 * other keywords (fill pointer / adjustable / displacement fall to the general paths)
	 * or a non-character element type.
	 * @param cons the make-array expression
	 * @return the lowered expression, or null when not applicable
	 */
	public static @Nullable LispVal lowerCharacterInitialContentsMakeArray(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			return null;
		}
		LispVal elementType = null;
		LispVal contents = null;
		for (int i = 2; i + 1 < parts.size(); i += 2) {
			if (!(parts.get(i) instanceof LispSymbol kw)) {
				return null;
			}
			switch (kw.name()) {
				case LispNames.ELEMENT_TYPE_KEYWORD -> elementType = parts.get(i + 1);
				case LispNames.INITIAL_CONTENTS_KEYWORD -> contents = parts.get(i + 1);
				default -> {
					return null;
				}
			}
		}
		if (contents == null || !isCharacterElementType(elementType)) {
			return null;
		}
		// (let* ((__mca_n n) (__mca_c c))
		// (if (stringp __mca_c) (subseq __mca_c 0) (coerce __mca_c 'string)))
		LispSymbol nVar = new LispSymbol("__mca_n");
		LispSymbol cVar = new LispSymbol("__mca_c");
		LispVal copy = fmtCall(LispNames.SUBSEQ, cVar, new LispInteger(0));
		LispVal convert = fmtCall(LispNames.COERCE, cVar, quoteOf("STRING"));
		LispVal body = makeIf(callOf(LispNames.STRINGP, cVar), copy, convert);
		LispVal bindings = listToCons(
				List.of(listToCons(List.of(nVar, parts.get(1))), listToCons(List.of(cVar, contents))));
		return listToCons(List.of(new LispSymbol(LispNames.LET_STAR), bindings, body));
	}

	/**
	 * Expands {@code (write-char char [stream])} to {@code write-string} of the
	 * one-character string, returning the character -- so every backend's existing
	 * stream-aware string output covers it.
	 * @param cons the write-char expression
	 * @return the expanded expression
	 */
	public static LispVal expandWriteChar(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2 || parts.size() > 3) {
			throw new IllegalArgumentException(LispNames.WRITE_CHAR + " expects a character and an optional stream");
		}
		LispSymbol chVar = new LispSymbol("__write_char");
		List<LispVal> write = new java.util.ArrayList<>(
				List.of(new LispSymbol(LispNames.WRITE_STRING), fmtCall(LispNames.STRING, chVar)));
		if (parts.size() == 3) {
			write.add(parts.get(2));
		}
		return makeLet(chVar.name(), parts.get(1), makeProgn(List.of(listToCons(write), chVar)));
	}

	/**
	 * Rewrites {@code (%schar-set var index char)} for the compiled backends. A mutable
	 * character vector (a fill-pointered {@code make-array :element-type 'character}
	 * result, represented as a general vector) is written IN PLACE through
	 * {@code %row-major-aset}; an immutable string is rebuilt with the character replaced
	 * and {@code setq}-bound back to the variable. The branch is chosen at runtime on
	 * {@code %arrayp}; the stored character is the value. Lite semantics: the string
	 * place must be a variable (an immutable string has nowhere else to store the rebuilt
	 * result), and for an immutable string the update is visible through that variable
	 * only -- an alias made before the write still sees the old content (the interpreter
	 * mutates in place).
	 * @param cons the %schar-set call
	 * @return the expanded expression
	 */
	public static LispVal expandScharSetFunctional(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 4) {
			throw new IllegalArgumentException(LispNames.SCHAR_SET + " expects a string, an index and a character");
		}
		if (!(parts.get(1) instanceof LispSymbol var)) {
			throw new UnsupportedOperationException("setf on " + LispNames.SCHAR + "/" + LispNames.CHAR
					+ " requires a variable string place on the compiled backends, got " + parts.get(1).print());
		}
		LispSymbol idxVar = new LispSymbol("__schar_i");
		LispSymbol chVar = new LispSymbol("__schar_c");
		LispVal head = fmtCall(LispNames.SUBSEQ, var, new LispInteger(0), idxVar);
		LispVal mid = fmtCall(LispNames.STRING, chVar);
		LispVal tail = fmtCall(LispNames.SUBSEQ, var, fmtCall(LispNames.ADD, idxVar, new LispInteger(1)));
		LispVal rebuilt = fmtCall(LispNames.STRING_CONCAT, fmtCall(LispNames.STRING_CONCAT, head, mid), tail);
		LispVal assign = listToCons(List.of(new LispSymbol(LispNames.SETQ), var, rebuilt));
		LispVal functional = makeProgn(List.of(assign, chVar));
		LispVal mutating = makeProgn(List.of(fmtCall(LispNames.ROW_MAJOR_ASET, var, idxVar, chVar), chVar));
		LispVal body = makeIf(callOf(LispNames.ARRAYP_INTERNAL, var), mutating, functional);
		return makeLet(idxVar.name(), parts.get(2), makeLet(chVar.name(), parts.get(3), body));
	}

	/**
	 * Expands {@code (locally (declare ...) body...)} to {@code (progn body...)}:
	 * declarations are parsed no-ops everywhere, so {@code locally} is {@code progn} with
	 * its leading {@code declare} forms dropped.
	 * @param cons the locally expression
	 * @return the expanded expression
	 */
	public static LispVal expandLocally(LispCons cons) {
		List<LispVal> parts = cons.toList();
		int start = 1;
		while (start < parts.size() && parts.get(start) instanceof LispCons declCons
				&& declCons.car() instanceof LispSymbol op && LispNames.DECLARE.equals(op.name())) {
			start++;
		}
		List<LispVal> body = parts.subList(start, parts.size());
		if (body.isEmpty()) {
			return LispNil.INSTANCE;
		}
		if (body.size() == 1) {
			return body.get(0);
		}
		return makeProgn(body);
	}

	/**
	 * Expands {@code (with-standard-io-syntax body...)} to {@code (progn body...)}.
	 *
	 * <p>
	 * Common Lisp defines this as a dynamic binding of the whole reader/printer control
	 * set to standard values. rontolisp has no variable in that set whose value can
	 * differ from its standard one at run time, so the binding has nothing to do:
	 * {@code *package*} is resolved to the current package by {@code PackageResolver}
	 * before the program runs and is not a run-time cell at all;
	 * {@code *read-default-float-format*} is informational (every float shares the one
	 * double representation, see {@link LispNames#READ_DEFAULT_FLOAT_FORMAT});
	 * {@code *print-circle*} and {@code *readtable*} are predefined so library code
	 * reading them loads, and no printer or reader consults them; the remaining standard
	 * variables ({@code *print-base*}, {@code *print-escape*}, {@code *read-base*}, ...)
	 * do not exist, which is the same as being permanently standard.
	 *
	 * <p>
	 * That is the reason, and it is also the trigger to revisit: the FIRST reader or
	 * printer control variable this implementation starts to honor at run time must be
	 * bound here, or a {@code with-standard-io-syntax} body will silently inherit the
	 * caller's setting.
	 * @param cons the with-standard-io-syntax expression
	 * @return the expanded expression
	 */
	public static LispVal expandWithStandardIoSyntax(LispCons cons) {
		List<LispVal> parts = cons.toList();
		List<LispVal> body = parts.subList(1, parts.size());
		if (body.isEmpty()) {
			return LispNil.INSTANCE;
		}
		if (body.size() == 1) {
			return body.get(0);
		}
		return makeProgn(body);
	}

	/**
	 * Expands {@code (eval-when (situations...) body...)} to the body wrapped in a
	 * {@code progn} (nil for an empty body). The situation list is validated but not
	 * consulted here -- the compile-time situations are handled where the form is read,
	 * not where it is expanded.
	 * @param cons the eval-when expression
	 * @return the expanded expression
	 */
	public static LispVal expandEvalWhen(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2 || !(parts.get(1) instanceof LispCons || parts.get(1) instanceof LispNil)) {
			throw new IllegalArgumentException("eval-when expects a situation list, got: " + cons.print());
		}
		List<LispVal> body = parts.subList(2, parts.size());
		if (body.isEmpty()) {
			return LispNil.INSTANCE;
		}
		if (body.size() == 1) {
			return body.get(0);
		}
		return makeProgn(body);
	}

	/**
	 * Counter for the variables generated by {@code flet}/{@code labels} expansions. A
	 * per-expansion id keeps the generated names unique so nested expansions never bind
	 * the same variable name (a let init lambda must capture an outer function through a
	 * distinct name, not through same-name shadowing).
	 */
	private static final java.util.concurrent.atomic.AtomicInteger FLET_COUNTER = new java.util.concurrent.atomic.AtomicInteger();

	/**
	 * Expands (flet ((name lambda-list body...)...) body...) into let-bound lambdas.
	 * Lisp-2: only call position {@code (name args...)} and {@code (function name)} in
	 * the body are rewritten to the generated variable; the definition bodies see the
	 * OUTER function bindings (non-recursive).
	 *
	 * <pre>
	 * (flet ((f (x) (+ x 1))) (f 2))
	 * -> (let ((__flet0_f (lambda (x) (+ x 1)))) (funcall __flet0_f 2))
	 * </pre>
	 * @param cons the flet expression
	 * @return the expanded expression
	 */
	public static LispVal expandFlet(LispCons cons) {
		return expandFletLabels(cons, false);
	}

	/**
	 * Expands (labels ((name lambda-list body...)...) body...) like {@link #expandFlet}
	 * but the definitions see each other (mutual recursion): the variables are bound to
	 * nil first and each is then {@code setq}ed to its lambda, so the lambdas close over
	 * the shared (boxed) variables.
	 *
	 * <pre>
	 * (labels ((f (n) (if (= n 0) 1 (* n (f (- n 1)))))) (f 5))
	 * -> (let ((__labels0_f nil))
	 *      (setq __labels0_f (lambda (n) (if (= n 0) 1 (* n (funcall __labels0_f (- n 1))))))
	 *      (funcall __labels0_f 5))
	 * </pre>
	 * @param cons the labels expression
	 * @return the expanded expression
	 */
	public static LispVal expandLabels(LispCons cons) {
		return expandFletLabels(cons, true);
	}

	private static LispVal expandFletLabels(LispCons cons, boolean recursive) {
		String op = recursive ? LispNames.LABELS : LispNames.FLET;
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2 || !(parts.get(1) instanceof LispCons || parts.get(1) instanceof LispNil)) {
			throw new IllegalArgumentException(op + " expects a definition list: " + cons.print());
		}
		List<LispVal> defs = parts.get(1) instanceof LispCons defsCons ? defsCons.toList() : List.of();
		int id = FLET_COUNTER.getAndIncrement();
		java.util.LinkedHashMap<String, LispSymbol> fnVars = new java.util.LinkedHashMap<>();
		List<List<LispVal>> defParts = new java.util.ArrayList<>();
		for (LispVal def : defs) {
			if (!(def instanceof LispCons defCons) || !defCons.isProperList()) {
				throw new IllegalArgumentException(
						op + " definition must be (name lambda-list body...): " + def.print());
			}
			List<LispVal> dp = defCons.toList();
			if (dp.size() < 2 || !(dp.get(0) instanceof LispSymbol name) || name.isKeyword()) {
				throw new IllegalArgumentException(
						op + " definition must be (name lambda-list body...): " + def.print());
			}
			if (PackageRegistry.specialOperatorNames().contains(name.name())) {
				throw new IllegalArgumentException(op + " cannot bind the special operator " + name.name());
			}
			if (fnVars.put(name.name(), new LispSymbol("__" + op + id + "_" + name.name().replace(':', '_'))) != null) {
				throw new IllegalArgumentException(op + " defines " + name.name() + " more than once");
			}
			defParts.add(dp);
		}
		List<LispVal> letParts = new java.util.ArrayList<>();
		letParts.add(new LispSymbol(LispNames.LET));
		List<LispVal> bindings = new java.util.ArrayList<>();
		List<LispVal> setqs = new java.util.ArrayList<>();
		int i = 0;
		for (java.util.Map.Entry<String, LispSymbol> entry : fnVars.entrySet()) {
			List<LispVal> dp = defParts.get(i++);
			// Desugar the lambda list to the native "required + &rest" shape here:
			// LambdaLists.desugarProgram (the compilers' pre-pass) does not see inside
			// flet definition lists, and moving the defaults into the let* prologue
			// also puts them in expression position for the body rewrite below.
			List<LispVal> defBody = dp.size() == 2 ? List.of((LispVal) LispNil.INSTANCE) : dp.subList(2, dp.size());
			// No %fn-block wrap here (the interpreter shares this expansion); instead
			// the body gets the REAL block CL mandates: an flet/labels local
			// establishes a block named after it, so (return-from name v) exits the
			// local function on every backend (cl-ppcre's advance-fn).
			LambdaLists.Expanded e = LambdaLists.expand(dp.get(1), defBody, false);
			List<LispVal> paramParts = new java.util.ArrayList<LispVal>(e.required());
			if (e.rest() != null) {
				paramParts.add(new LispSymbol(LispNames.LAMBDA_REST));
				paramParts.add(e.rest());
			}
			List<LispVal> lambdaParts = new java.util.ArrayList<>();
			lambdaParts.add(new LispSymbol(LispNames.LAMBDA));
			lambdaParts.add(paramParts.isEmpty() ? LispNil.INSTANCE : listToCons(paramParts));
			List<LispVal> blockParts = new java.util.ArrayList<>();
			blockParts.add(new LispSymbol(LispNames.BLOCK));
			blockParts.add(new LispSymbol(entry.getKey()));
			blockParts.addAll(e.body());
			lambdaParts.add(listToCons(blockParts));
			LispVal lambda = listToCons(lambdaParts);
			if (recursive) {
				// labels: the lambdas see every sibling; bind nil first, setq after.
				bindings.add(listToCons(List.of(entry.getValue(), LispNil.INSTANCE)));
				setqs.add(listToCons(
						List.of(new LispSymbol(LispNames.SETQ), entry.getValue(), rewriteLocalCalls(lambda, fnVars))));
			}
			else {
				// flet: the lambdas see the outer function bindings only.
				bindings.add(listToCons(List.of(entry.getValue(), lambda)));
			}
		}
		letParts.add(bindings.isEmpty() ? LispNil.INSTANCE : listToCons(bindings));
		letParts.addAll(setqs);
		if (parts.size() == 2) {
			letParts.add(LispNil.INSTANCE);
		}
		for (LispVal bodyForm : parts.subList(2, parts.size())) {
			letParts.add(rewriteLocalCalls(bodyForm, fnVars));
		}
		return listToCons(letParts);
	}

	/**
	 * Rewrites references to {@code flet}/{@code labels}-bound local functions in an
	 * expression: call position {@code (name args...)} becomes {@code (funcall var
	 * args...)} and {@code (function name)} becomes {@code var}. Lisp-2: a bare symbol is
	 * a variable reference and is never rewritten. The walk knows the special-form shapes
	 * whose subforms are not expressions (binding lists, parameter lists, case keys) and
	 * the scoping of nested {@code flet}/{@code labels} (an inner definition of the same
	 * name shadows the outer one for its scope).
	 */
	private static LispVal rewriteLocalCalls(LispVal form, java.util.Map<String, LispSymbol> fns) {
		if (fns.isEmpty() || !(form instanceof LispCons cons)) {
			return form;
		}
		if (!cons.isProperList()) {
			// An improper list is never a call form; the legitimate appearances are
			// data patterns (a loop destructuring pattern like (value . remaining))
			// whose elements are plain variables, so they pass through verbatim.
			// Tested BEFORE the non-symbol-head branch below: that branch rebuilds the
			// form from cons.toList(), which DROPS an improper tail -- a nested loop
			// pattern ((field . value) . rest) came back as ((field . value)) and the
			// body's reference to rest was unbound (quri's url-encode-params).
			return form;
		}
		if (!(cons.car() instanceof LispSymbol sym)) {
			// Non-symbol head, e.g. ((lambda (x) ...) arg...): every element is an
			// expression (also reached for cond-style clauses via the generic walk).
			return rewriteTail(cons.toList(), 0, fns);
		}
		String name = sym.name();
		if (LispNames.QUOTE.equals(name) || LispNames.DEFMACRO.equals(name) || LispNames.DEFPACKAGE.equals(name)) {
			// quote is data; defmacro bodies run at macro-expansion time where local
			// functions do not exist; defpackage clauses are data.
			return form;
		}
		List<LispVal> parts = cons.toList();
		if (fns.containsKey(name)) {
			// Call position: (f args...) -> (funcall var args...)
			List<LispVal> out = new java.util.ArrayList<>();
			out.add(new LispSymbol(LispNames.FUNCALL));
			out.add(fns.get(name));
			for (int i = 1; i < parts.size(); i++) {
				out.add(rewriteLocalCalls(parts.get(i), fns));
			}
			return listToCons(out);
		}
		switch (name) {
			case LispNames.FUNCTION: {
				if (parts.size() == 2 && parts.get(1) instanceof LispSymbol fnName && fns.containsKey(fnName.name())) {
					return fns.get(fnName.name());
				}
				if (parts.size() == 2 && parts.get(1) instanceof LispCons) {
					// (function (lambda ...)): walk the lambda expression.
					return rewriteTail(parts, 1, fns);
				}
				return form;
			}
			case LispNames.LAMBDA:
				return rewriteKeeping(parts, 2, fns, rewriteLambdaList(parts.get(1), fns));
			case LispNames.DEFUN:
				return rewriteKeeping(parts, 3, fns, parts.get(1), rewriteLambdaList(parts.get(2), fns));
			case LispNames.LET, LispNames.LET_STAR, LispNames.DO, LispNames.DO_STAR:
				// (let ((name init)...) body...) / (do ((var init step)...) (end
				// result...) body...): binding names stay (they are variables, not
				// functions), init/step/end/result and the body are expressions.
				return rewriteKeeping(parts, 2, fns, rewriteBindings(parts.get(1), fns));
			case LispNames.DOLIST, LispNames.DOTIMES, LispNames.WITH_OPEN_FILE: {
				// (dolist (var listform result) body...): var stays.
				LispVal spec = parts.get(1);
				if (spec instanceof LispCons specCons) {
					List<LispVal> specParts = specCons.toList();
					List<LispVal> newSpec = new java.util.ArrayList<>();
					newSpec.add(specParts.get(0));
					for (int i = 1; i < specParts.size(); i++) {
						newSpec.add(rewriteLocalCalls(specParts.get(i), fns));
					}
					spec = listToCons(newSpec);
				}
				return rewriteKeeping(parts, 2, fns, spec);
			}
			case LispNames.MULTIPLE_VALUE_BIND: {
				// (multiple-value-bind (vars...) values-form body...): the variable
				// list stays (they are variables, not functions).
				if (parts.size() < 2) {
					return form; // malformed; the expansion reports it
				}
				return rewriteKeeping(parts, 2, fns, parts.get(1));
			}
			case LispNames.DESTRUCTURING_BIND: {
				// (destructuring-bind pattern form body...): the pattern's variables
				// stay; only default forms inside &optional/&key/&aux specs are
				// expressions.
				if (parts.size() < 2) {
					return form; // malformed; the expansion reports it
				}
				return rewriteKeeping(parts, 2, fns, rewriteDestructuringPattern(parts.get(1), fns));
			}
			case LispNames.CASE, LispNames.ECASE, LispNames.CCASE, LispNames.TYPECASE, LispNames.ETYPECASE: {
				// (case keyform (keys body...)...): keys are unevaluated data.
				List<LispVal> newParts = new java.util.ArrayList<>();
				newParts.add(parts.get(0));
				newParts.add(rewriteLocalCalls(parts.get(1), fns));
				for (int i = 2; i < parts.size(); i++) {
					if (parts.get(i) instanceof LispCons clause) {
						List<LispVal> clauseParts = clause.toList();
						List<LispVal> newClause = new java.util.ArrayList<>();
						newClause.add(clauseParts.get(0));
						for (int j = 1; j < clauseParts.size(); j++) {
							newClause.add(rewriteLocalCalls(clauseParts.get(j), fns));
						}
						newParts.add(listToCons(newClause));
					}
					else {
						newParts.add(parts.get(i));
					}
				}
				return listToCons(newParts);
			}
			case LispNames.DEFSTRUCT: {
				// (defstruct name (slot default)...): only slot defaults are expressions.
				List<LispVal> newParts = new java.util.ArrayList<>();
				newParts.add(parts.get(0));
				newParts.add(parts.get(1));
				for (int i = 2; i < parts.size(); i++) {
					if (parts.get(i) instanceof LispCons slotCons) {
						List<LispVal> slotParts = slotCons.toList();
						List<LispVal> newSlot = new java.util.ArrayList<>();
						newSlot.add(slotParts.get(0));
						for (int j = 1; j < slotParts.size(); j++) {
							newSlot.add(rewriteLocalCalls(slotParts.get(j), fns));
						}
						newParts.add(listToCons(newSlot));
					}
					else {
						newParts.add(parts.get(i));
					}
				}
				return listToCons(newParts);
			}
			case LispNames.FLET, LispNames.LABELS: {
				// A nested flet/labels shadows this level's bindings of the same names
				// for its own scope; the nested form itself is kept (it expands with its
				// own variables later). flet definition bodies still see this level's
				// bindings; labels definition bodies already see the inner ones.
				if (parts.size() < 2) {
					return form; // malformed; the nested expansion reports it
				}
				boolean nestedRecursive = LispNames.LABELS.equals(name);
				List<LispVal> nestedDefs = parts.size() > 1 && parts.get(1) instanceof LispCons defsCons
						? defsCons.toList() : List.of();
				java.util.Map<String, LispSymbol> shadowed = new java.util.LinkedHashMap<>(fns);
				for (LispVal def : nestedDefs) {
					if (def instanceof LispCons defCons && defCons.car() instanceof LispSymbol defName) {
						shadowed.remove(defName.name());
					}
				}
				java.util.Map<String, LispSymbol> defScope = nestedRecursive ? shadowed : fns;
				List<LispVal> newDefs = new java.util.ArrayList<>();
				for (LispVal def : nestedDefs) {
					if (def instanceof LispCons defCons && defCons.isProperList()) {
						List<LispVal> dp = defCons.toList();
						List<LispVal> newDef = new java.util.ArrayList<>();
						newDef.add(dp.get(0));
						if (dp.size() > 1) {
							newDef.add(rewriteLambdaList(dp.get(1), defScope));
						}
						for (int i = 2; i < dp.size(); i++) {
							newDef.add(rewriteLocalCalls(dp.get(i), defScope));
						}
						newDefs.add(listToCons(newDef));
					}
					else {
						newDefs.add(def);
					}
				}
				List<LispVal> newParts = new java.util.ArrayList<>();
				newParts.add(parts.get(0));
				newParts.add(nestedDefs.isEmpty() && !(parts.size() > 1 && parts.get(1) instanceof LispCons)
						? parts.get(1) : listToCons(newDefs));
				for (int i = 2; i < parts.size(); i++) {
					newParts.add(rewriteLocalCalls(parts.get(i), shadowed));
				}
				return listToCons(newParts);
			}
			default:
				// Every other operator (function call, macro call, special form): the
				// head resolves in the function namespace and stays, all arguments are
				// expressions.
				return rewriteTail(parts, 1, fns);
		}
	}

	// Rewrites parts[from..] as expressions, keeping parts[0] and the given fixed
	// subforms verbatim.
	private static LispVal rewriteKeeping(List<LispVal> parts, int from, java.util.Map<String, LispSymbol> fns,
			LispVal... fixed) {
		List<LispVal> newParts = new java.util.ArrayList<>();
		newParts.add(parts.get(0));
		newParts.addAll(List.of(fixed));
		for (int i = from; i < parts.size(); i++) {
			newParts.add(rewriteLocalCalls(parts.get(i), fns));
		}
		return listToCons(newParts);
	}

	// Rewrites parts[from..] as expressions, keeping parts[0..from-1] verbatim.
	private static LispVal rewriteTail(List<LispVal> parts, int from, java.util.Map<String, LispSymbol> fns) {
		List<LispVal> newParts = new java.util.ArrayList<>();
		for (int i = 0; i < parts.size(); i++) {
			newParts.add(i < from ? parts.get(i) : rewriteLocalCalls(parts.get(i), fns));
		}
		return listToCons(newParts);
	}

	// Rewrites the init/step forms of a let/do binding list, keeping the bound names.
	private static LispVal rewriteBindings(LispVal bindings, java.util.Map<String, LispSymbol> fns) {
		if (!(bindings instanceof LispCons bindingsCons) || !bindingsCons.isProperList()) {
			return bindings;
		}
		List<LispVal> newBindings = new java.util.ArrayList<>();
		for (LispVal binding : bindingsCons.toList()) {
			if (binding instanceof LispCons bindingCons && bindingCons.isProperList()) {
				List<LispVal> pair = bindingCons.toList();
				List<LispVal> newPair = new java.util.ArrayList<>();
				newPair.add(pair.get(0));
				for (int i = 1; i < pair.size(); i++) {
					newPair.add(rewriteLocalCalls(pair.get(i), fns));
				}
				newBindings.add(listToCons(newPair));
			}
			else {
				newBindings.add(binding);
			}
		}
		return listToCons(newBindings);
	}

	// Rewrites the default-value forms inside a destructuring pattern (specs after
	// &optional/&key/&aux), keeping the pattern variables, nested sub-patterns, and
	// lambda-list keywords.
	private static LispVal rewriteDestructuringPattern(LispVal pattern, java.util.Map<String, LispSymbol> fns) {
		if (!(pattern instanceof LispCons patternCons) || !patternCons.isProperList()) {
			return pattern;
		}
		boolean specSection = false;
		List<LispVal> newElements = new java.util.ArrayList<>();
		for (LispVal e : patternCons.toList()) {
			if (e instanceof LispSymbol sym && sym.name().startsWith("&")) {
				// &rest/&body take a plain variable; the other keywords start spec
				// sections whose cons elements are (var default [supplied-p]).
				specSection = !LispNames.LAMBDA_REST.equals(sym.name()) && !LispNames.LAMBDA_BODY.equals(sym.name());
				newElements.add(e);
			}
			else if (!specSection && e instanceof LispCons) {
				newElements.add(rewriteDestructuringPattern(e, fns));
			}
			else if (specSection && e instanceof LispCons specCons && specCons.isProperList()) {
				List<LispVal> sp = specCons.toList();
				List<LispVal> newSpec = new java.util.ArrayList<>(sp);
				for (int i = 1; i < sp.size(); i++) {
					newSpec.set(i, rewriteLocalCalls(sp.get(i), fns));
				}
				newElements.add(listToCons(newSpec));
			}
			else {
				newElements.add(e);
			}
		}
		return listToCons(newElements);
	}

	// Rewrites the default-value forms of a lambda list ((var default supplied-p) in
	// &optional/&key/&aux), keeping the parameter names and lambda-list keywords.
	private static LispVal rewriteLambdaList(LispVal lambdaList, java.util.Map<String, LispSymbol> fns) {
		if (!(lambdaList instanceof LispCons listCons) || !listCons.isProperList()) {
			return lambdaList;
		}
		List<LispVal> newParams = new java.util.ArrayList<>();
		for (LispVal param : listCons.toList()) {
			if (param instanceof LispCons paramCons && paramCons.isProperList()) {
				List<LispVal> pp = paramCons.toList();
				List<LispVal> newParam = new java.util.ArrayList<>(pp);
				if (pp.size() > 1) {
					newParam.set(1, rewriteLocalCalls(pp.get(1), fns));
				}
				newParams.add(listToCons(newParam));
			}
			else {
				newParams.add(param);
			}
		}
		return listToCons(newParams);
	}

	/**
	 * Counter for the temporaries generated by the multiple-value expansions. A
	 * per-expansion id keeps nested expansions from binding the same variable name.
	 */
	private static final java.util.concurrent.atomic.AtomicInteger MV_COUNTER = new java.util.concurrent.atomic.AtomicInteger();

	/** A temp binding generated by a multiple-value lowering: {@code (var init)}. */
	private record MvBinding(LispSymbol var, LispVal init) {
	}

	/**
	 * A producer form lowered for a multiple-value consumer: the temp {@code bindings}
	 * are evaluated in order (nested {@code let}s) and the {@code values} expressions
	 * (pure reads over the temps) yield the producer's values. Recognized multi-value
	 * producers -- a literal {@code (values ...)} call and the two-value built-ins
	 * {@code floor}/{@code ceiling}/{@code round}/{@code truncate} (quotient + remainder)
	 * and {@code gethash} (value + present-p) -- lower purely syntactically with
	 * {@code rest} null. Any other producer goes through the {@code %mv-spill} runtime
	 * channel: the spill is cleared, the form is evaluated (a {@code values} tail inside
	 * the callee stores its extra values in the spill as a fresh list), and {@code rest}
	 * snapshots the spill -- the consumer reads value {@code i > 0} as
	 * {@code (nth i-1 rest)}. This is how {@code multiple-value-bind} over a user
	 * function sees the callee's tail values. Snapshotting also CLEARS the channel, so
	 * values one consumer took cannot be read a second time by an enclosing one.
	 * Deviation from CL: a producer that calls {@code values} in a NON-tail position with
	 * no consumer of its own and then returns normally leaves a stale spill behind, so
	 * the extra variables may read leftover values instead of nil.
	 */
	private record MvProducer(List<MvBinding> bindings, List<LispVal> values, @Nullable LispSymbol rest) {
	}

	/**
	 * True when the form is one of the SYNTACTIC multiple-value producers -- the ones
	 * whose extra values exist only inside a consumer's expansion (see
	 * {@code MvProducer}), so a caller that merely evaluates the form sees the primary
	 * value alone. Every other producer publishes through the {@code %mv-spill} runtime
	 * channel and needs no rewrite. Used by {@code LispEvaluator.evalValues} to decide
	 * which route the REPL's echo takes.
	 * @param form the form to test
	 * @return {@code true} when the form is a syntactic multiple-value producer
	 */
	public static boolean isSyntacticMultipleValueProducer(LispVal form) {
		return isMvProducerForm(form);
	}

	/** True when the form is recognized as a multi-value producer (see MvProducer). */
	private static boolean isMvProducerForm(LispVal form) {
		if (!(form instanceof LispCons cons) || !(cons.car() instanceof LispSymbol op) || !cons.isProperList()) {
			return false;
		}
		int size = cons.toList().size();
		return switch (op.name()) {
			case LispNames.VALUES -> true;
			case LispNames.FLOOR, LispNames.CEILING, LispNames.ROUND, LispNames.TRUNCATE -> size == 2 || size == 3;
			case LispNames.GETHASH -> size == 3 || size == 4;
			case LispNames.ARRAY_DISPLACEMENT -> size == 2;
			default -> false;
		};
	}

	private static MvProducer lowerMvProducer(LispVal producer, String prefix) {
		List<MvBinding> bindings = new java.util.ArrayList<>();
		List<LispVal> values = new java.util.ArrayList<>();
		if (isMvProducerForm(producer)) {
			LispCons cons = (LispCons) producer;
			List<LispVal> parts = cons.toList();
			switch (((LispSymbol) cons.car()).name()) {
				case LispNames.VALUES: {
					for (int i = 1; i < parts.size(); i++) {
						LispSymbol tmp = new LispSymbol(prefix + "_" + (i - 1));
						bindings.add(new MvBinding(tmp, parts.get(i)));
						values.add(tmp);
					}
					return new MvProducer(bindings, values, null);
				}
				case LispNames.FLOOR, LispNames.CEILING, LispNames.ROUND, LispNames.TRUNCATE: {
					// (floor x [y]) -> quotient + remainder x - q*y (y defaults to 1).
					// The two-argument form only exists inside a multiple-value
					// consumer; it lowers to the one-argument built-in over x/y.
					String op = ((LispSymbol) cons.car()).name();
					LispSymbol a = new LispSymbol(prefix + "_a");
					bindings.add(new MvBinding(a, parts.get(1)));
					LispSymbol q = new LispSymbol(prefix + "_q");
					if (parts.size() == 3) {
						LispSymbol b = new LispSymbol(prefix + "_b");
						bindings.add(new MvBinding(b, parts.get(2)));
						bindings.add(new MvBinding(q, mvCall(op, mvCall(LispNames.DIV, a, b))));
						values.add(q);
						values.add(mvCall(LispNames.SUB, a, mvCall(LispNames.MUL, q, b)));
					}
					else {
						bindings.add(new MvBinding(q, mvCall(op, a)));
						values.add(q);
						values.add(mvCall(LispNames.SUB, a, q));
					}
					return new MvProducer(bindings, values, null);
				}
				case LispNames.ARRAY_DISPLACEMENT: {
					// (array-displacement array) -> target (or nil) + offset (or 0),
					// read through the two internal accessors over one array temp.
					LispSymbol arr = new LispSymbol(prefix + "_arr");
					bindings.add(new MvBinding(arr, parts.get(1)));
					values.add(mvCall(LispNames.ARRAY_DISP_TARGET, arr));
					values.add(mvCall(LispNames.ARRAY_DISP_OFFSET, arr));
					return new MvProducer(bindings, values, null);
				}
				case LispNames.GETHASH: {
					// (gethash key table [default]) -> value + present-p. A fresh
					// gensym is the not-found default, so a stored nil (or the
					// caller's default) is distinguished from a missing key.
					LispSymbol k = new LispSymbol(prefix + "_k");
					LispSymbol h = new LispSymbol(prefix + "_h");
					bindings.add(new MvBinding(k, parts.get(1)));
					bindings.add(new MvBinding(h, parts.get(2)));
					LispVal dflt = LispNil.INSTANCE;
					if (parts.size() == 4) {
						LispSymbol d = new LispSymbol(prefix + "_d");
						bindings.add(new MvBinding(d, parts.get(3)));
						dflt = d;
					}
					LispSymbol s = new LispSymbol(prefix + "_s");
					bindings.add(new MvBinding(s, listToCons(List.of(new LispSymbol(LispNames.GENSYM)))));
					LispSymbol v = new LispSymbol(prefix + "_v");
					bindings.add(new MvBinding(v, listToCons(List.of(new LispSymbol(LispNames.GETHASH), k, h, s))));
					LispVal missing = mvCall(LispNames.EQ_GENERAL, v, s);
					values.add(makeIf(missing, dflt, v));
					values.add(makeIf(missing, LispNil.INSTANCE, LispTrue.INSTANCE));
					return new MvProducer(bindings, values, null);
				}
				default:
					throw new IllegalStateException("unreachable: " + producer.print());
			}
		}
		if (!(producer instanceof LispCons)) {
			// An atom (a literal, a variable read) is a single-value producer for
			// sure: no spill round-trip needed, extra variables read nil.
			LispSymbol tmp = new LispSymbol(prefix + "_0");
			bindings.add(new MvBinding(tmp, producer));
			values.add(tmp);
			return new MvProducer(bindings, values, null);
		}
		// Unknown call producer: read the callee's extra values back through the
		// spill. The spill is cleared FIRST so a producer that never calls values
		// leaves the extras nil, and snapshotted IMMEDIATELY after so a later
		// producer (multiple-value-call) cannot overwrite it before the values are
		// read. The snapshot also CLEARS the channel: values that this consumer has
		// taken are consumed, so they cannot resurface as an enclosing consumer's
		// (the REPL echo is one -- see LispEvaluator.evalValues -- and a function
		// that internally consumes a callee's values must still look single-valued
		// to ITS caller).
		LispSymbol tmp = new LispSymbol(prefix + "_0");
		bindings.add(new MvBinding(tmp, makeProgn(List.of(setMvSpill(LispNil.INSTANCE), producer))));
		values.add(tmp);
		LispSymbol rest = new LispSymbol(prefix + "_rest");
		bindings.add(new MvBinding(rest, makeProg1(new LispSymbol(LispNames.MV_SPILL), setMvSpill(LispNil.INSTANCE))));
		return new MvProducer(bindings, values, rest);
	}

	/** Builds {@code (setq %mv-spill value)}. */
	private static LispVal setMvSpill(LispVal value) {
		return listToCons(List.of(new LispSymbol(LispNames.SETQ), new LispSymbol(LispNames.MV_SPILL), value));
	}

	/** Wraps the body in nested single-binding {@code let}s, first binding outermost. */
	private static LispVal nestMvBindings(List<MvBinding> bindings, LispVal body) {
		LispVal result = body;
		for (int i = bindings.size() - 1; i >= 0; i--) {
			LispVal binding = listToCons(List.of(bindings.get(i).var(), bindings.get(i).init()));
			result = listToCons(
					List.of(new LispSymbol(LispNames.LET), new LispCons(binding, LispNil.INSTANCE), result));
		}
		return result;
	}

	private static LispVal mvCall(String op, LispVal... args) {
		List<LispVal> parts = new java.util.ArrayList<>();
		parts.add(new LispSymbol(op));
		parts.addAll(List.of(args));
		return listToCons(parts);
	}

	/**
	 * Expands a two-argument {@code floor}/{@code ceiling}/{@code round}/{@code truncate}
	 * call in an ordinary (single-value) context into the one-argument built-in over the
	 * exact division: {@code (floor a b)} -> {@code (floor (/ a b))} (the quotient; the
	 * remainder is only observable through a multiple-value consumer).
	 * @param cons the floor-family expression
	 * @return the expanded expression, or {@code null} for the plain one-argument form
	 */
	public static @Nullable LispVal expandFloorFamilyDivisor(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			return null;
		}
		return mvCall(((LispSymbol) cons.car()).name(), mvCall(LispNames.DIV, parts.get(1), parts.get(2)));
	}

	/**
	 * Expands a {@code (values ...)} call in an ordinary (single-value) context: every
	 * argument is evaluated and the first is the result, like {@code prog1}; zero
	 * arguments yield nil. The multiple-value consumers intercept a literal
	 * {@code values} producer before this expansion, so it only applies where extra
	 * values are discarded (CL semantics).
	 * @param cons the values expression
	 * @return the expanded expression
	 */
	public static LispVal expandValues(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() == 1) {
			return makeProgn(List.of(setMvSpill(LispNil.INSTANCE), LispNil.INSTANCE));
		}
		// Bind every argument in order, publish the extras to the spill (a fresh
		// list; nil when there are none, so a stale spill cannot leak through this
		// call), and return the first.
		String prefix = "__mv" + MV_COUNTER.getAndIncrement();
		List<MvBinding> bindings = new java.util.ArrayList<>();
		List<LispVal> temps = new java.util.ArrayList<>();
		for (int i = 1; i < parts.size(); i++) {
			LispSymbol tmp = new LispSymbol(prefix + "_" + (i - 1));
			bindings.add(new MvBinding(tmp, parts.get(i)));
			temps.add(tmp);
		}
		LispVal extras;
		if (temps.size() == 1) {
			extras = LispNil.INSTANCE;
		}
		else {
			List<LispVal> listParts = new java.util.ArrayList<>();
			listParts.add(new LispSymbol(LispNames.LIST));
			listParts.addAll(temps.subList(1, temps.size()));
			extras = listToCons(listParts);
		}
		return nestMvBindings(bindings, makeProgn(List.of(setMvSpill(extras), temps.get(0))));
	}

	/**
	 * Expands {@code (byte size position)} into a two-element list
	 * {@code (list size position)} -- the internal byte-specifier representation carried
	 * by {@link #expandByteSize}/{@link #expandBytePosition}/{@link #expandLdb}/
	 * {@link #expandDpb} (no new runtime type; a plain cons list works everywhere).
	 * @param cons the byte expression
	 * @return the expanded expression
	 */
	public static LispVal expandByte(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			throw new IllegalArgumentException("byte expects 2 arguments (size position): " + cons.print());
		}
		return mvCall(LispNames.LIST, parts.get(1), parts.get(2));
	}

	/**
	 * Expands {@code (byte-size bytespec)} into {@code (car bytespec)} -- the size stored
	 * in the first slot of the byte specifier built by {@link #expandByte}.
	 * @param cons the byte-size expression
	 * @return the expanded expression
	 */
	public static LispVal expandByteSize(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException("byte-size expects 1 argument: " + cons.print());
		}
		return mvCall(LispNames.CAR, parts.get(1));
	}

	/**
	 * Expands {@code (byte-position bytespec)} into {@code (car (cdr bytespec))} -- the
	 * position stored in the second slot of the byte specifier built by
	 * {@link #expandByte}.
	 * @param cons the byte-position expression
	 * @return the expanded expression
	 */
	public static LispVal expandBytePosition(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException("byte-position expects 1 argument: " + cons.print());
		}
		return mvCall(LispNames.CAR, mvCall(LispNames.CDR, parts.get(1)));
	}

	/**
	 * Expands {@code (make-sequence 'TYPE size &key initial-element)} onto the native
	 * constructors: a string type becomes {@code make-string}, {@code list} becomes
	 * {@code make-list}, and a vector type becomes {@code make-array}. Lite: the result
	 * type must be a literal quoted specifier (every real-library call site is).
	 * @param cons the make-sequence expression
	 * @return the expanded expression
	 */
	public static LispVal expandMakeSequence(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3 || !(parts.get(1) instanceof LispCons quoted)
				|| !(quoted.car() instanceof LispSymbol quoteOp) || !LispNames.QUOTE.equals(plainTypeName(quoteOp))
				|| !(quoted.cdr() instanceof LispCons datumCell)) {
			throw new IllegalArgumentException("make-sequence expects a literal quoted result type: " + cons.print());
		}
		LispVal typeSpec = datumCell.car();
		String typeName = switch (typeSpec) {
			case LispSymbol s -> plainTypeName(s);
			case LispCons c when c.car() instanceof LispSymbol s -> plainTypeName(s);
			default -> "";
		};
		String constructor = switch (typeName) {
			case "STRING", "SIMPLE-STRING", "BASE-STRING", "SIMPLE-BASE-STRING" -> LispNames.MAKE_STRING;
			case "LIST" -> LispNames.MAKE_LIST;
			case "VECTOR", "SIMPLE-VECTOR", "ARRAY", "SIMPLE-ARRAY" -> LispNames.MAKE_ARRAY;
			default -> throw new IllegalArgumentException("make-sequence: unsupported result type " + typeSpec.print());
		};
		List<LispVal> call = new java.util.ArrayList<>();
		call.add(new LispSymbol(constructor));
		call.addAll(parts.subList(2, parts.size()));
		return listToCons(call);
	}

	/**
	 * Expands the {@code logandc1}/{@code logandc2}/{@code logorc1}/{@code logorc2}
	 * complement-operand bit functions over {@code logand}/{@code logior}/{@code lognot}.
	 * Each operand appears exactly once in the expansion, so evaluation order and count
	 * match the function-call semantics.
	 * @param cons the two-argument call expression
	 * @return the expanded expression
	 */
	public static LispVal expandLogComplement(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3 || !(parts.get(0) instanceof LispSymbol op)) {
			throw new IllegalArgumentException("log complement functions expect 2 arguments: " + cons.print());
		}
		String name = plainTypeName(op);
		LispVal x = parts.get(1);
		LispVal y = parts.get(2);
		return switch (name) {
			case LispNames.LOGANDC1 -> mvCall(LispNames.LOGAND, mvCall(LispNames.LOGNOT, x), y);
			case LispNames.LOGANDC2 -> mvCall(LispNames.LOGAND, x, mvCall(LispNames.LOGNOT, y));
			case LispNames.LOGORC1 -> mvCall(LispNames.LOGIOR, mvCall(LispNames.LOGNOT, x), y);
			case LispNames.LOGORC2 -> mvCall(LispNames.LOGIOR, x, mvCall(LispNames.LOGNOT, y));
			default -> throw new IllegalArgumentException("Unknown log complement function: " + cons.print());
		};
	}

	/**
	 * Normalizes a two-argument {@code (float x prototype)} call to the one-argument
	 * shape the backends compile: {@code (float (prog1 x prototype))}. The prototype only
	 * selects the float subtype in CL, and the runtime has a single float representation,
	 * so its value is evaluated (in order, after {@code x}) and discarded. A one-argument
	 * call is returned unchanged.
	 * @param cons the float expression
	 * @return the normalized float expression
	 */
	public static LispCons normalizeFloatCall(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			return cons;
		}
		LispVal prog1 = listToCons(List.of(new LispSymbol(LispNames.PROG1), parts.get(1), parts.get(2)));
		return new LispCons(parts.get(0), new LispCons(prog1, LispNil.INSTANCE));
	}

	/**
	 * The largest byte-specifier size or position the literal fast paths of
	 * {@code ldb}/{@code dpb}/{@code mask-field} fold. Past it the general expansion runs
	 * instead, so a pathological {@code (byte 1000000000 0)} cannot make the expander
	 * build a gigabyte-wide mask constant.
	 */
	private static final int LITERAL_BYTESPEC_LIMIT = 1024;

	/**
	 * The {@code {size, position}} of a byte specifier written with literal integers --
	 * {@code (byte 32 0)}, or the {@code (list 32 0)} it lowers to -- or {@code null}
	 * when either component is computed. A literal one lets {@code ldb}/{@code dpb}/
	 * {@code mask-field} fold their mask arithmetic at expansion time instead of
	 * rebuilding a bytespec list and two lexical scopes per evaluation: SHA-256's
	 * {@code (ldb (byte 32 0) ...)} is ~25 interpreted nodes in the general shape and 3
	 * in the folded one.
	 * @param spec the byte-specifier argument form
	 * @return the size and position, or {@code null}
	 */
	/** A byte specifier whose size and position are both literal integers. */
	private record ByteSpec(long size, long position) {
	}

	@Nullable private static ByteSpec literalByteSpec(LispVal spec) {
		if (!(spec instanceof LispCons call) || !call.isProperList()) {
			return null;
		}
		List<LispVal> parts = call.toList();
		if (parts.size() != 3 || !(parts.get(0) instanceof LispSymbol op)) {
			return null;
		}
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(op.name());
		String member = qn == null ? op.name() : qn.member();
		if (!LispNames.BYTE.equals(member) && !LispNames.LIST.equals(member)) {
			return null;
		}
		if (!(parts.get(1) instanceof LispInteger size) || !(parts.get(2) instanceof LispInteger position)) {
			return null;
		}
		if (size.value() < 0 || position.value() < 0 || size.value() > LITERAL_BYTESPEC_LIMIT
				|| position.value() > LITERAL_BYTESPEC_LIMIT) {
			return null;
		}
		return new ByteSpec(size.value(), position.value());
	}

	/** {@code 2^size - 1}, the right-justified mask of a byte specifier of that size. */
	private static java.math.BigInteger lowBitMask(long size) {
		return java.math.BigInteger.ONE.shiftLeft((int) size).subtract(java.math.BigInteger.ONE);
	}

	/** The integer literal for a value, demoted to a {@code long} when it fits. */
	private static LispVal integerLiteral(java.math.BigInteger value) {
		return value.bitLength() < 64 ? new LispInteger(value.longValueExact()) : new LispBigInteger(value);
	}

	/**
	 * Expands {@code (ldb bytespec integer)} (load byte) over the bit primitives: the
	 * {@code size}-bit field at {@code position} of the integer, right-justified.
	 *
	 * <pre>
	 * (ldb bs n) ->
	 *   (let* ((__ldbN_s bs) (__ldbN_n n))
	 *     (logand (ash __ldbN_n (- 0 (car (cdr __ldbN_s))))
	 *             (- (ash 1 (car __ldbN_s)) 1)))
	 * </pre>
	 * @param cons the ldb expression
	 * @return the expanded expression
	 */
	public static LispVal expandLdb(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			throw new IllegalArgumentException("ldb expects 2 arguments (bytespec integer): " + cons.print());
		}
		ByteSpec literal = literalByteSpec(parts.get(1));
		if (literal != null) {
			// (ldb (byte 32 0) n) -> (logand n #xFFFFFFFF): no bytespec list, no
			// let* scopes, no arithmetic to rebuild the mask. The integer is still
			// evaluated exactly once, and the specifier's forms have no side effects
			// to preserve (they are literals).
			LispVal shifted = literal.position() == 0 ? parts.get(2)
					: mvCall(LispNames.ASH, parts.get(2), new LispInteger(-literal.position()));
			return mvCall(LispNames.LOGAND, shifted, integerLiteral(lowBitMask(literal.size())));
		}
		String prefix = "__ldb" + MV_COUNTER.getAndIncrement();
		LispSymbol s = new LispSymbol(prefix + "_s");
		LispSymbol n = new LispSymbol(prefix + "_n");
		LispVal size = mvCall(LispNames.CAR, s);
		LispVal position = mvCall(LispNames.CAR, mvCall(LispNames.CDR, s));
		LispVal shifted = mvCall(LispNames.ASH, n, mvCall(LispNames.SUB, new LispInteger(0), position));
		LispVal mask = mvCall(LispNames.SUB, mvCall(LispNames.ASH, new LispInteger(1), size), new LispInteger(1));
		LispVal body = mvCall(LispNames.LOGAND, shifted, mask);
		return nestMvBindings(List.of(new MvBinding(s, parts.get(1)), new MvBinding(n, parts.get(2))), body);
	}

	/**
	 * Expands {@code (dpb newbyte bytespec integer)} (deposit byte) over the bit
	 * primitives: the low {@code size} bits of {@code newbyte} replace the byte
	 * specifier's field of the integer, the other bits unchanged.
	 *
	 * <pre>
	 * (dpb nb bs n) ->
	 *   (let* ((__dpbN_b nb) (__dpbN_s bs) (__dpbN_n n)
	 *          (__dpbN_m (ash (- (ash 1 (car __dpbN_s)) 1) (car (cdr __dpbN_s)))))
	 *     (logior (logand __dpbN_n (lognot __dpbN_m))
	 *             (logand (ash __dpbN_b (car (cdr __dpbN_s))) __dpbN_m)))
	 * </pre>
	 * @param cons the dpb expression
	 * @return the expanded expression
	 */
	public static LispVal expandDpb(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 4) {
			throw new IllegalArgumentException("dpb expects 3 arguments (newbyte bytespec integer): " + cons.print());
		}
		ByteSpec literal = literalByteSpec(parts.get(2));
		if (literal != null) {
			// The new-bits operand comes FIRST in the logior so the newbyte form is
			// still evaluated before the integer form, as the general expansion's
			// let* order does; logior over integers does not care about the order.
			java.math.BigInteger mask = lowBitMask(literal.size()).shiftLeft((int) literal.position());
			LispVal placed = literal.position() == 0 ? parts.get(1)
					: mvCall(LispNames.ASH, parts.get(1), new LispInteger(literal.position()));
			return mvCall(LispNames.LOGIOR, mvCall(LispNames.LOGAND, placed, integerLiteral(mask)),
					mvCall(LispNames.LOGAND, parts.get(3), integerLiteral(mask.not())));
		}
		String prefix = "__dpb" + MV_COUNTER.getAndIncrement();
		LispSymbol nb = new LispSymbol(prefix + "_b");
		LispSymbol s = new LispSymbol(prefix + "_s");
		LispSymbol n = new LispSymbol(prefix + "_n");
		LispSymbol m = new LispSymbol(prefix + "_m");
		LispVal size = mvCall(LispNames.CAR, s);
		LispVal position = mvCall(LispNames.CAR, mvCall(LispNames.CDR, s));
		LispVal ones = mvCall(LispNames.SUB, mvCall(LispNames.ASH, new LispInteger(1), size), new LispInteger(1));
		LispVal maskInit = mvCall(LispNames.ASH, ones, position);
		LispVal cleared = mvCall(LispNames.LOGAND, n, mvCall(LispNames.LOGNOT, m));
		LispVal newBits = mvCall(LispNames.LOGAND, mvCall(LispNames.ASH, nb, position), m);
		LispVal body = mvCall(LispNames.LOGIOR, cleared, newBits);
		return nestMvBindings(List.of(new MvBinding(nb, parts.get(1)), new MvBinding(s, parts.get(2)),
				new MvBinding(n, parts.get(3)), new MvBinding(m, maskInit)), body);
	}

	/**
	 * Expands {@code (mask-field bytespec integer)} over the bit primitives: the
	 * {@code ldb} field left in its original position.
	 *
	 * <pre>
	 * (mask-field bs n) ->
	 *   (let* ((__mfN_s bs) (__mfN_n n))
	 *     (logand __mfN_n (ash (- (ash 1 (car __mfN_s)) 1) (car (cdr __mfN_s)))))
	 * </pre>
	 * @param cons the mask-field expression
	 * @return the expanded expression
	 */
	public static LispVal expandMaskField(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			throw new IllegalArgumentException("mask-field expects 2 arguments (bytespec integer): " + cons.print());
		}
		ByteSpec literal = literalByteSpec(parts.get(1));
		if (literal != null) {
			return mvCall(LispNames.LOGAND, parts.get(2),
					integerLiteral(lowBitMask(literal.size()).shiftLeft((int) literal.position())));
		}
		String prefix = "__mf" + MV_COUNTER.getAndIncrement();
		LispSymbol s = new LispSymbol(prefix + "_s");
		LispSymbol n = new LispSymbol(prefix + "_n");
		LispVal size = mvCall(LispNames.CAR, s);
		LispVal position = mvCall(LispNames.CAR, mvCall(LispNames.CDR, s));
		LispVal ones = mvCall(LispNames.SUB, mvCall(LispNames.ASH, new LispInteger(1), size), new LispInteger(1));
		LispVal mask = mvCall(LispNames.ASH, ones, position);
		LispVal body = mvCall(LispNames.LOGAND, n, mask);
		return nestMvBindings(List.of(new MvBinding(s, parts.get(1)), new MvBinding(n, parts.get(2))), body);
	}

	/**
	 * Expands {@code (scale-float f n)} ({@code f * 2^n} with IEEE semantics) into a
	 * chunked power-of-two product: the exponent is clamped to ±2200 (beyond which every
	 * finite double has saturated to 0/infinity anyway) and split into three chunks of at
	 * most ±1000 so each {@code (expt 2.0 chunk)} factor stays finite and nonzero --
	 * multiplying by such a factor is exact until the final step over/underflows, which
	 * reproduces {@code Math.scalb} including the subnormal range.
	 * @param cons the scale-float expression
	 * @return the expanded expression
	 */
	public static LispVal expandScaleFloat(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			throw new IllegalArgumentException("scale-float expects 2 arguments (float n): " + cons.print());
		}
		String prefix = "__sf" + MV_COUNTER.getAndIncrement();
		LispSymbol f = new LispSymbol(prefix + "_f");
		LispSymbol nc = new LispSymbol(prefix + "_n");
		LispSymbol a = new LispSymbol(prefix + "_a");
		LispSymbol b = new LispSymbol(prefix + "_b");
		LispSymbol c = new LispSymbol(prefix + "_c");
		LispVal ncInit = clampInt(parts.get(2), 2200);
		LispVal aInit = clampInt(nc, 1000);
		LispVal bInit = clampInt(mvCall(LispNames.SUB, nc, a), 1000);
		LispVal cInit = mvCall(LispNames.SUB, nc, a, b);
		LispVal product = mvCall(LispNames.MUL, mvCall(LispNames.MUL, mvCall(LispNames.MUL, f, pow2(a)), pow2(b)),
				pow2(c));
		return nestMvBindings(List.of(new MvBinding(f, parts.get(1)), new MvBinding(nc, ncInit),
				new MvBinding(a, aInit), new MvBinding(b, bInit), new MvBinding(c, cInit)), product);
	}

	/** Builds {@code (max -limit (min limit x))}. */
	private static LispVal clampInt(LispVal x, long limit) {
		return mvCall(LispNames.MAX, new LispInteger(-limit), mvCall(LispNames.MIN, new LispInteger(limit), x));
	}

	/** Builds {@code (expt 2.0 e)}. */
	private static LispVal pow2(LispVal e) {
		return mvCall(LispNames.EXPT, new LispDouble(2.0), e);
	}

	/**
	 * Expands {@code (values-list list)}: the list's first element is the primary value
	 * and the rest are published to the {@code %mv-spill} channel, so the consumers see
	 * every element as a value -- {@code (values-list '(1 2))} is {@code (values 1 2)}.
	 * An empty list yields nil with no extra values.
	 *
	 * <pre>
	 * (values-list l) ->
	 *   (let ((__mvN_l l))
	 *     (setq %mv-spill (if (consp __mvN_l) (cdr __mvN_l) nil))
	 *     (if (consp __mvN_l) (car __mvN_l) nil))
	 * </pre>
	 * @param cons the values-list expression
	 * @return the expanded expression
	 */
	public static LispVal expandValuesList(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException(LispNames.VALUES_LIST + " expects exactly one list: " + cons.print());
		}
		LispSymbol l = new LispSymbol("__mv" + MV_COUNTER.getAndIncrement() + "_l");
		LispVal isCons = mvCall(LispNames.CONSP, l);
		LispVal spill = setMvSpill(makeIf(isCons, mvCall(LispNames.CDR, l), LispNil.INSTANCE));
		LispVal primary = makeIf(isCons, mvCall(LispNames.CAR, l), LispNil.INSTANCE);
		return makeLet(l.name(), parts.get(1), makeProgn(List.of(spill, primary)));
	}

	/**
	 * Expands a {@code (values ...)} call to its primary value WITHOUT touching the
	 * {@code %mv-spill} global: the scalar {@code --no-gc} backend has no reference
	 * globals (and no lists), so it keeps the pure prog1 semantics -- extra values are
	 * evaluated and discarded, and cross-function consumers are unsupported there.
	 * @param cons the values expression
	 * @return the expanded expression
	 */
	public static LispVal expandValuesPrimary(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() == 1) {
			return LispNil.INSTANCE;
		}
		if (parts.size() == 2) {
			return parts.get(1);
		}
		List<LispVal> prog1Parts = new java.util.ArrayList<>(parts);
		prog1Parts.set(0, new LispSymbol(LispNames.PROG1));
		return listToCons(prog1Parts);
	}

	/**
	 * Expands (multiple-value-bind (vars...) values-form body...) into nested lets: the
	 * producer's temp bindings evaluate in order, then the variables bind in parallel to
	 * the value expressions (nil for missing values; surplus values are evaluated and
	 * discarded).
	 *
	 * <pre>
	 * (multiple-value-bind (q r) (floor 7 2) (list q r))
	 * -> (let ((__mv0_a 7)) (let ((__mv0_b 2)) (let ((__mv0_q (floor (/ __mv0_a __mv0_b))))
	 *      (let ((q __mv0_q) (r (- __mv0_a (* __mv0_q __mv0_b)))) (list q r)))))
	 * </pre>
	 * @param cons the multiple-value-bind expression
	 * @return the expanded expression
	 */
	public static LispVal expandMultipleValueBind(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3 || !(parts.get(1) instanceof LispCons || parts.get(1) instanceof LispNil)) {
			throw new IllegalArgumentException(
					LispNames.MULTIPLE_VALUE_BIND + " expects a variable list and a values form: " + cons.print());
		}
		List<LispVal> varList = parts.get(1) instanceof LispCons varsCons ? varsCons.toList() : List.of();
		List<LispSymbol> vars = new java.util.ArrayList<>();
		for (LispVal v : varList) {
			if (!(v instanceof LispSymbol sym) || sym.isKeyword()) {
				throw new IllegalArgumentException(
						LispNames.MULTIPLE_VALUE_BIND + " variable must be a symbol: " + v.print());
			}
			vars.add(sym);
		}
		MvProducer producer = lowerMvProducer(parts.get(2), "__mv" + MV_COUNTER.getAndIncrement());
		List<LispVal> letParts = new java.util.ArrayList<>();
		letParts.add(new LispSymbol(LispNames.LET));
		List<LispVal> bindings = new java.util.ArrayList<>();
		for (int i = 0; i < vars.size(); i++) {
			LispVal value;
			if (i < producer.values().size()) {
				value = producer.values().get(i);
			}
			else if (producer.rest() != null) {
				// The extra values of a spill producer live in the rest snapshot (a
				// too-short spill reads nil through nth, CL's missing-value fill).
				value = mvCall(LispNames.NTH, new LispInteger(i - producer.values().size()), producer.rest());
			}
			else {
				value = LispNil.INSTANCE;
			}
			bindings.add(listToCons(List.of(vars.get(i), value)));
		}
		letParts.add(bindings.isEmpty() ? LispNil.INSTANCE : listToCons(bindings));
		if (parts.size() == 3) {
			letParts.add(LispNil.INSTANCE);
		}
		letParts.addAll(parts.subList(3, parts.size()));
		return nestMvBindings(producer.bindings(), listToCons(letParts));
	}

	/**
	 * Counter for the temporaries generated by {@code multiple-value-setq} expansions.
	 */
	private static final java.util.concurrent.atomic.AtomicInteger MVS_COUNTER = new java.util.concurrent.atomic.AtomicInteger();

	/**
	 * Expands (multiple-value-setq (v1 v2 ...) values-form) into a
	 * {@code multiple-value-bind} over gensym temporaries that {@code setq}s each
	 * existing variable and returns the primary value. The producer form is recognized
	 * like {@code multiple-value-bind}; extra variables read nil.
	 *
	 * <pre>
	 * (multiple-value-setq (a b) (floor 17 5))
	 * -&gt; (multiple-value-bind (__mvs0_0 __mvs0_1) (floor 17 5)
	 *      (setq a __mvs0_0) (setq b __mvs0_1) __mvs0_0)
	 * </pre>
	 * @param cons the multiple-value-setq expression
	 * @return the expanded expression
	 */
	public static LispVal expandMultipleValueSetq(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3 || !(parts.get(1) instanceof LispCons || parts.get(1) instanceof LispNil)) {
			throw new IllegalArgumentException(
					LispNames.MULTIPLE_VALUE_SETQ + " expects a variable list and a values form: " + cons.print());
		}
		List<LispVal> varList = parts.get(1) instanceof LispCons varsCons ? varsCons.toList() : List.of();
		for (LispVal v : varList) {
			if (!(v instanceof LispSymbol sym) || sym.isKeyword()) {
				throw new IllegalArgumentException(
						LispNames.MULTIPLE_VALUE_SETQ + " variable must be a symbol: " + v.print());
			}
		}
		int id = MVS_COUNTER.getAndIncrement();
		// At least one gensym so an empty variable list still returns the primary value.
		int gCount = Math.max(varList.size(), 1);
		List<LispVal> gVars = new java.util.ArrayList<>();
		for (int i = 0; i < gCount; i++) {
			gVars.add(new LispSymbol("__mvs" + id + "_" + i));
		}
		List<LispVal> mvbParts = new java.util.ArrayList<>();
		mvbParts.add(new LispSymbol(LispNames.MULTIPLE_VALUE_BIND));
		mvbParts.add(listToCons(gVars));
		mvbParts.add(parts.get(2));
		for (int i = 0; i < varList.size(); i++) {
			mvbParts.add(listToCons(List.of(new LispSymbol(LispNames.SETQ), varList.get(i), gVars.get(i))));
		}
		mvbParts.add(gVars.get(0));
		return listToCons(mvbParts);
	}

	/** Counter for the temporaries generated by {@code multiple-value-prog1}. */
	private static final java.util.concurrent.atomic.AtomicInteger MVP_COUNTER = new java.util.concurrent.atomic.AtomicInteger();

	/**
	 * Expands (multiple-value-prog1 first-form forms...) into a
	 * {@code multiple-value-list} capture of the first form's values, the remaining forms
	 * for effect, and a {@code values-list} republication -- the spill's spread operator,
	 * so every value survives the intervening forms on the syntactic multiple-value tier.
	 *
	 * <pre>
	 * (multiple-value-prog1 (floor 17 5) (cleanup))
	 * -&gt; (let ((__mvp0 (multiple-value-list (floor 17 5))))
	 *      (cleanup)
	 *      (values-list __mvp0))
	 * </pre>
	 * @param cons the multiple-value-prog1 expression
	 * @return the expanded expression
	 */
	public static LispVal expandMultipleValueProg1(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException(
					LispNames.MULTIPLE_VALUE_PROG1 + " expects a first form: " + cons.print());
		}
		LispSymbol tmp = new LispSymbol("__mvp" + MVP_COUNTER.getAndIncrement());
		LispVal capture = listToCons(List.of(new LispSymbol(LispNames.MULTIPLE_VALUE_LIST), parts.get(1)));
		List<LispVal> letParts = new java.util.ArrayList<>();
		letParts.add(new LispSymbol(LispNames.LET));
		letParts.add(listToCons(List.of(listToCons(List.of(tmp, capture)))));
		letParts.addAll(parts.subList(2, parts.size()));
		letParts.add(listToCons(List.of(new LispSymbol(LispNames.VALUES_LIST), tmp)));
		return listToCons(letParts);
	}

	/** Counter for the temporaries generated by {@code rotatef} expansions. */
	private static final java.util.concurrent.atomic.AtomicInteger ROTATEF_COUNTER = new java.util.concurrent.atomic.AtomicInteger();

	/**
	 * Expands (rotatef place1 place2 ... placeN) into a {@code let} that reads every
	 * place into a gensym temporary, then a single {@code setf} rotating the temporaries
	 * left (place1 gets place2's old value, ..., placeN gets place1's old value); returns
	 * nil. The {@code setf} is emitted unexpanded so the surrounding context supplies its
	 * struct accessor registry.
	 *
	 * <pre>
	 * (rotatef a b)
	 * -&gt; (let ((__rotatef0_0 a) (__rotatef0_1 b))
	 *      (setf a __rotatef0_1 b __rotatef0_0) nil)
	 * </pre>
	 * @param cons the rotatef expression
	 * @return the expanded expression
	 */
	public static LispVal expandRotatef(LispCons cons) {
		List<LispVal> places = cons.toList().subList(1, cons.toList().size());
		// Zero or one place: nothing to rotate (a single place is left unchanged in CL).
		if (places.size() < 2) {
			return LispNil.INSTANCE;
		}
		int id = ROTATEF_COUNTER.getAndIncrement();
		List<LispVal> bindings = new java.util.ArrayList<>();
		List<LispVal> temps = new java.util.ArrayList<>();
		for (int i = 0; i < places.size(); i++) {
			LispSymbol temp = new LispSymbol("__rotatef" + id + "_" + i);
			temps.add(temp);
			bindings.add(listToCons(List.of(temp, places.get(i))));
		}
		List<LispVal> setfParts = new java.util.ArrayList<>();
		setfParts.add(new LispSymbol(LispNames.SETF));
		for (int i = 0; i < places.size(); i++) {
			setfParts.add(places.get(i));
			setfParts.add(temps.get((i + 1) % places.size()));
		}
		List<LispVal> letParts = new java.util.ArrayList<>();
		letParts.add(new LispSymbol(LispNames.LET));
		letParts.add(listToCons(bindings));
		letParts.add(listToCons(setfParts));
		letParts.add(LispNil.INSTANCE);
		return listToCons(letParts);
	}

	/**
	 * Expands {@code (shiftf place1 ... placeN new-value)}: every place gets the value of
	 * the place (or new-value) to its right, and the first place's OLD value is returned.
	 * All places and the new value are evaluated once, left to right (lite: place
	 * subforms may evaluate again inside the generated setf).
	 * @param cons the shiftf expression
	 * @return the expanded expression
	 */
	public static LispVal expandShiftf(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3) {
			throw new IllegalArgumentException(LispNames.SHIFTF + " expects at least a place and a value");
		}
		List<LispVal> places = parts.subList(1, parts.size() - 1);
		LispVal newValue = parts.get(parts.size() - 1);
		int id = ROTATEF_COUNTER.getAndIncrement();
		List<LispVal> bindings = new java.util.ArrayList<>();
		List<LispVal> temps = new java.util.ArrayList<>();
		for (int i = 0; i < places.size(); i++) {
			LispSymbol temp = new LispSymbol("__shiftf" + id + "_" + i);
			temps.add(temp);
			bindings.add(listToCons(List.of(temp, places.get(i))));
		}
		LispSymbol newTemp = new LispSymbol("__shiftf" + id + "_new");
		bindings.add(listToCons(List.of(newTemp, newValue)));
		List<LispVal> setfParts = new java.util.ArrayList<>();
		setfParts.add(new LispSymbol(LispNames.SETF));
		for (int i = 0; i < places.size(); i++) {
			setfParts.add(places.get(i));
			setfParts.add(i + 1 < places.size() ? temps.get(i + 1) : newTemp);
		}
		List<LispVal> letParts = new java.util.ArrayList<>();
		letParts.add(new LispSymbol(LispNames.LET_STAR));
		letParts.add(listToCons(bindings));
		letParts.add(listToCons(setfParts));
		letParts.add(temps.get(0));
		return listToCons(letParts);
	}

	/**
	 * Expands {@code (load-time-value form [read-only-p])} to the form itself, for the
	 * paths that do not hoist it ({@link #hoistLoadTimeValues} gives the compile path the
	 * evaluate-once contract; the interpreter memoizes per occurrence). A form left here
	 * re-evaluates at each use, which is only reached for a value cheap enough that
	 * {@link #hoistLoadTimeValues} declines to hoist it in the first place.
	 * @param cons the load-time-value expression
	 * @return the form
	 */
	public static LispVal expandLoadTimeValue(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException(LispNames.LOAD_TIME_VALUE + " expects a form");
		}
		return parts.get(1);
	}

	/**
	 * Gives {@code load-time-value} its "evaluated once" contract on the compile path:
	 * every occurrence whose value form is worth computing (see
	 * {@link #worthHoistingLoadTimeValue}) is replaced by a read of a synthesized global
	 * that fills itself on first use, and one {@code (defvar %LOAD-TIME-VALUE-N nil)} per
	 * occurrence is prepended to the program.
	 *
	 * <pre>
	 * (cl-ppcre:split (load-time-value (cl-ppcre:create-scanner ";")) line)
	 *   -&gt; (defvar %LOAD-TIME-VALUE-1 nil)                              ; prepended
	 *      (cl-ppcre:split (car (or %LOAD-TIME-VALUE-1
	 *                               (setq %LOAD-TIME-VALUE-1
	 *                                     (list (cl-ppcre:create-scanner ";")))))
	 *                      line)
	 * </pre>
	 *
	 * The slot holds a one-element LIST rather than the value itself, so a value of
	 * {@code nil} still counts as computed. Filling is LAZY rather than at program start:
	 * a value form spliced out of a library (cl-ppcre's scanners are the motivating case)
	 * routinely needs that library's own globals, which are initialized by top-level
	 * forms further down the program, so evaluating it at index 0 would read them
	 * unbound. The deviation from CL -- an occurrence never reached is never evaluated --
	 * is the same bargain the macro-time defvar registration makes, and is invisible to a
	 * value form without side effects (which is the only kind {@code load-time-value} is
	 * for).
	 *
	 * <p>
	 * Both compilers reach this through {@link #expandTopLevelDefinitions}; the
	 * {@code --no-gc} numeric subset does not, and keeps the re-evaluating lowering. The
	 * interpreter does not either -- it memoizes each occurrence by identity instead,
	 * which is the same contract without a program rewrite.
	 * @param program the top-level forms
	 * @return the program with load-time values hoisted, itself when nothing was hoisted
	 */
	public static List<LispVal> hoistLoadTimeValues(List<LispVal> program) {
		List<LispVal> slots = new ArrayList<>();
		List<LispVal> out = new ArrayList<>(program.size());
		boolean changed = false;
		for (LispVal form : program) {
			LispVal hoisted = hoistLoadTimeValues(form, slots);
			changed = changed || hoisted != form;
			out.add(hoisted);
		}
		if (!changed) {
			return program;
		}
		out.addAll(0, slots);
		return out;
	}

	private static LispVal hoistLoadTimeValues(LispVal form, List<LispVal> slots) {
		if (!(form instanceof LispCons cons)) {
			return form;
		}
		if (cons.car() instanceof LispSymbol op) {
			String name = operatorMember(op.name());
			if (LispNames.QUOTE.equals(name)) {
				// Quoted data is not code: a (load-time-value ...) inside it is a datum.
				return form;
			}
			if (LispNames.LOAD_TIME_VALUE.equals(name) && cons.cdr() instanceof LispCons rest
					&& worthHoistingLoadTimeValue(rest.car())) {
				LispVal value = hoistLoadTimeValues(rest.car(), slots);
				LispSymbol slot = new LispSymbol(LispNames.LOAD_TIME_VALUE_SLOT_PREFIX + (slots.size() + 1));
				slots.add(listToCons(List.of(new LispSymbol(LispNames.DEFVAR), slot, LispNil.INSTANCE)));
				LispVal fill = listToCons(List.of(new LispSymbol(LispNames.SETQ), slot,
						listToCons(List.of(new LispSymbol(LispNames.LIST), value))));
				return listToCons(List.of(new LispSymbol(LispNames.CAR),
						listToCons(List.of(new LispSymbol(LispNames.OR), slot, fill))));
			}
		}
		LispVal car = hoistLoadTimeValues(cons.car(), slots);
		LispVal cdr = hoistLoadTimeValues(cons.cdr(), slots);
		return car == cons.car() && cdr == cons.cdr() ? form : new LispCons(car, cdr);
	}

	/**
	 * Whether a {@code load-time-value} value form is worth a hoist. Only a call is: an
	 * atom (a literal, or a special-variable read like jzon's
	 * {@code (load-time-value *%offsets*)}) costs nothing to repeat, and {@code quote} /
	 * {@code function} / {@code find-package} wrappers must stay literally where they are
	 * -- {@link #literalPackageDesignator} folds the
	 * {@code (load-time-value (find-package
	 * ...))} idiom into a compile-time package name, and a hoist would hide it.
	 */
	private static boolean worthHoistingLoadTimeValue(LispVal value) {
		if (!(value instanceof LispCons cons) || !cons.isProperList() || !(cons.car() instanceof LispSymbol op)) {
			return false;
		}
		String name = operatorMember(op.name());
		return !LispNames.QUOTE.equals(name) && !LispNames.FUNCTION.equals(name)
				&& !LispNames.FIND_PACKAGE.equals(name);
	}

	/** The member name of a possibly package-qualified operator symbol. */
	private static String operatorMember(String name) {
		PackageRegistry.QualifiedName qualified = PackageRegistry.splitQualified(name);
		return qualified == null ? name : qualified.member();
	}

	/**
	 * Expands {@code (typep value 'type)} through the shared static type-test builder.
	 * Lite: the type specifier must be a literal (quoted) type -- the same set
	 * {@code typecase} supports plus the registered classes; a non-literal specifier is
	 * rejected at expansion time.
	 * @param cons the typep expression
	 * @param closRegistry the class registry for class-name type specifiers
	 * @return the expanded expression
	 */
	public static LispVal expandTypep(LispCons cons, ClosRegistry closRegistry) {
		return expandTypep(cons, closRegistry, true);
	}

	/**
	 * Expands {@code (typep value spec)} like
	 * {@link #expandTypep(LispCons, ClosRegistry)} but with the runtime-specifier
	 * dispatch either inlined (the interpreter, which re-expands per call against the
	 * live registry) or emitted as a call to the shared {@code %typep-runtime} defun (the
	 * compilers: the inline dispatch grows with the number of registered classes and
	 * overflowed the JVM's 16-bit branch offsets at cl-postgres scale;
	 * {@link #expandTopLevelDefinitions} injects the defun and its data table once per
	 * program).
	 * @param cons the typep expression
	 * @param closRegistry the class registry for class-name type specifiers
	 * @param inlineRuntimeDispatch whether a computed specifier expands inline
	 * @return the expanded expression
	 */
	public static LispVal expandTypep(LispCons cons, ClosRegistry closRegistry, boolean inlineRuntimeDispatch) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			throw new IllegalArgumentException(LispNames.TYPEP + " expects a value and a quoted type specifier");
		}
		LispVal typeArg = parts.get(2);
		LispVal spec;
		if (typeArg instanceof LispCons quoted && quoted.car() instanceof LispSymbol q
				&& LispNames.QUOTE.equals(q.name()) && quoted.cdr() instanceof LispCons rest) {
			spec = rest.car();
		}
		else if (typeArg instanceof LispSymbol sym && sym.name().startsWith(":")) {
			spec = typeArg;
		}
		else if (inlineRuntimeDispatch) {
			// A COMPUTED type specifier: dispatch on the runtime type NAME over every
			// type name the registry knows plus the built-in names, each arm carrying
			// the static test it would have compiled to (the runtime-slot-name dispatch
			// precedent, .kb/clos.md). A name outside that set matches nothing.
			return expandRuntimeTypep(parts.get(1), typeArg, closRegistry);
		}
		else {
			return listToCons(List.of(new LispSymbol(LispNames.TYPEP_RUNTIME), parts.get(1), typeArg));
		}
		LispSymbol temp = new LispSymbol("__typep" + ROTATEF_COUNTER.getAndIncrement());
		LispVal test;
		try {
			test = makeTypeTest(temp, spec, closRegistry);
		}
		catch (IllegalArgumentException unsupportedType) {
			// An unknown (user deftype) specifier: lite, matches nothing.
			test = LispNil.INSTANCE;
		}
		return makeLet(temp.name(), parts.get(1), makeIf(test, LispTrue.INSTANCE, LispNil.INSTANCE));
	}

	/**
	 * The built-in type names a runtime {@code typep} specifier can hold, each testable
	 * by the shared static builder. Deliberately the atomic names only: a computed
	 * specifier carrying a COMPOUND specifier (an {@code (integer 0 10)} list) is not
	 * dispatched.
	 */
	private static final List<String> RUNTIME_TYPEP_BUILTINS = List.of("NULL", "BOOLEAN", "KEYWORD", "SYMBOL",
			"INTEGER", "FIXNUM", "RATIONAL", "RATIO", "FLOAT", "REAL", "NUMBER", "CHARACTER", "STRING", "CONS", "LIST",
			"ATOM", "VECTOR", "ARRAY", "SEQUENCE", "HASH-TABLE", "FUNCTION", "STANDARD-OBJECT", "STRUCTURE-OBJECT",
			"UNSIGNED-BYTE", "T");

	/**
	 * Expands a {@code typep} whose type specifier is computed at run time: a
	 * {@code cond} keyed on the specifier symbol, one arm per type the registry knows
	 * (structs, classes and conditions -- matched by their canonical name, which is the
	 * spelling a runtime specifier carries) plus one per built-in name, each arm holding
	 * the very test the literal specifier would have compiled to. An unrecognized
	 * specifier yields nil rather than signalling: this is the lite runtime-dispatch
	 * model (see {@code .kb/clos.md}), not a real type table.
	 */
	private static LispVal expandRuntimeTypep(LispVal value, LispVal typeExpr, ClosRegistry closRegistry) {
		String prefix = "__rtp" + ROTATEF_COUNTER.getAndIncrement();
		LispSymbol v = new LispSymbol(prefix + "_v");
		LispSymbol tn = new LispSymbol(prefix + "_t");
		List<LispVal> clauses = new java.util.ArrayList<>();
		java.util.Set<String> seen = new java.util.HashSet<>();
		for (LispLayout layout : closRegistry.layouts().values()) {
			String typeName = layout.printName();
			if (!seen.add(typeName)) {
				continue;
			}
			LispVal test;
			try {
				test = makeTypeTest(v, new LispSymbol(typeName), closRegistry);
			}
			catch (IllegalArgumentException unsupported) {
				continue;
			}
			clauses.add(listToCons(
					List.of(nameMatchTest(tn, typeName), makeIf(test, LispTrue.INSTANCE, LispNil.INSTANCE))));
		}
		// tn = T accepts everything (makeTypeTest only knows the LispTrue spelling,
		// which a runtime specifier value never is).
		clauses.add(listToCons(List.of(nameMatchTest(tn, "T"), LispTrue.INSTANCE)));
		for (String builtin : RUNTIME_TYPEP_BUILTINS) {
			LispVal test;
			try {
				test = makeTypeTest(v, new LispSymbol(builtin), closRegistry);
			}
			catch (IllegalArgumentException unsupported) {
				continue;
			}
			clauses.add(
					listToCons(List.of(nameMatchTest(tn, builtin), makeIf(test, LispTrue.INSTANCE, LispNil.INSTANCE))));
		}
		clauses.add(listToCons(List.of(LispTrue.INSTANCE, LispNil.INSTANCE)));
		List<LispVal> condParts = new java.util.ArrayList<>();
		condParts.add(new LispSymbol(LispNames.COND));
		condParts.addAll(clauses);
		return makeLet(v.name(), value, makeLet(tn.name(), typeExpr, listToCons(condParts)));
	}

	/**
	 * The runtime-specifier match of one type name: {@code equal} against the canonical
	 * spelling, and -- when the name is package-qualified -- also against its plain
	 * member spelling, since a runtime specifier may carry either (symbols compare by
	 * content on every backend).
	 */
	private static LispVal nameMatchTest(LispSymbol runtimeName, String typeName) {
		LispVal exact = listToCons(List.of(new LispSymbol(LispNames.EQUAL), runtimeName, quoteOf(typeName)));
		PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(typeName);
		if (qn == null) {
			return exact;
		}
		return listToCons(List.of(new LispSymbol(LispNames.OR), exact,
				listToCons(List.of(new LispSymbol(LispNames.EQUAL), runtimeName, quoteOf(qn.member())))));
	}

	/** The immediate supertypes of each built-in type name ({@code subtypep} lattice). */
	private static final java.util.Map<String, List<String>> SUBTYPEP_PARENTS = orderedMap(
			java.util.Map.entry("FIXNUM", List.of("INTEGER")), java.util.Map.entry("BIGNUM", List.of("INTEGER")),
			java.util.Map.entry("bit", List.of("INTEGER")), java.util.Map.entry("UNSIGNED-BYTE", List.of("INTEGER")),
			java.util.Map.entry("SIGNED-BYTE", List.of("INTEGER")), java.util.Map.entry("INTEGER", List.of("RATIONAL")),
			java.util.Map.entry("RATIO", List.of("RATIONAL")), java.util.Map.entry("RATIONAL", List.of("REAL")),
			java.util.Map.entry("FLOAT", List.of("REAL")), java.util.Map.entry("REAL", List.of("NUMBER")),
			java.util.Map.entry("KEYWORD", List.of("SYMBOL")), java.util.Map.entry("BOOLEAN", List.of("SYMBOL")),
			java.util.Map.entry("NULL", List.of("SYMBOL", "LIST")), java.util.Map.entry("CONS", List.of("LIST")),
			java.util.Map.entry("LIST", List.of("SEQUENCE")), java.util.Map.entry("STRING", List.of("VECTOR")),
			java.util.Map.entry("VECTOR", List.of("ARRAY", "SEQUENCE")));

	/**
	 * An immutable map that iterates in DECLARATION order. {@code Map.of}/
	 * {@code Map.ofEntries} deliberately randomize their iteration order once per JVM
	 * run, so any table whose order reaches emitted output must not use them: it would
	 * make the compiler emit a different (still correct) module for the same program on
	 * every invocation, which silently destroys the byte-identity acceptance bar this
	 * project checks changes against.
	 * @param <K> the key type
	 * @param <V> the value type
	 * @param entries the entries, in the order they should iterate
	 * @return an unmodifiable insertion-ordered map
	 */
	@SafeVarargs
	private static <K, V> java.util.Map<K, V> orderedMap(java.util.Map.Entry<K, V>... entries) {
		java.util.Map<K, V> map = new java.util.LinkedHashMap<>();
		for (java.util.Map.Entry<K, V> entry : entries) {
			map.put(entry.getKey(), entry.getValue());
		}
		return java.util.Collections.unmodifiableMap(map);
	}

	/** Collapses the type-name aliases the one runtime representation makes equal. */
	private static String canonicalSubtypeName(String plain) {
		return switch (plain) {
			case "SINGLE-FLOAT", "DOUBLE-FLOAT", "SHORT-FLOAT", "LONG-FLOAT" -> "FLOAT";
			case "BASE-CHAR", "STANDARD-CHAR", "EXTENDED-CHAR" -> "CHARACTER";
			case "SIMPLE-STRING", "BASE-STRING", "SIMPLE-BASE-STRING" -> "STRING";
			case "SIMPLE-VECTOR" -> "VECTOR";
			case "SIMPLE-ARRAY" -> "ARRAY";
			default -> plain;
		};
	}

	/**
	 * Whether {@code sub} names a subtype of {@code super}: exact/alias equality, the
	 * built-in lattice, or the CLOS class registry's ancestor sets. Unknown pairs answer
	 * false (the lite single-value {@code subtypep}).
	 * @param subV the sub type designator (a symbol, {@code t} or {@code nil})
	 * @param superV the super type designator
	 * @param closRegistry the class registry for class-name type specifiers
	 * @return whether {@code sub} is a subtype of {@code super}
	 */
	public static boolean subtypep(LispVal subV, LispVal superV, ClosRegistry closRegistry) {
		if (superV instanceof LispTrue) {
			return true;
		}
		if (subV instanceof LispNil) {
			return true;
		}
		if (!(subV instanceof LispSymbol subSym) || !(superV instanceof LispSymbol superSym)) {
			return false;
		}
		String sub = canonicalSubtypeName(plainTypeName(subSym));
		String sup = canonicalSubtypeName(plainTypeName(superSym));
		if ("T".equals(sup) || sub.equals(sup)) {
			return true;
		}
		ClosRegistry.ClassInfo subClass = closRegistry.findClass(subSym.name());
		if (subClass != null) {
			ClosRegistry.ClassInfo superClass = closRegistry.findClass(superSym.name());
			if (superClass != null) {
				return subClass.ancestors().contains(ClosRegistry.normalize(superClass.name()));
			}
			return "STANDARD-OBJECT".equals(sup);
		}
		// Walk the built-in lattice upward from sub.
		java.util.ArrayDeque<String> queue = new java.util.ArrayDeque<>();
		queue.add(sub);
		java.util.Set<String> seen = new java.util.HashSet<>();
		while (!queue.isEmpty()) {
			String current = queue.poll();
			if (current.equals(sup)) {
				return true;
			}
			if (seen.add(current)) {
				queue.addAll(SUBTYPEP_PARENTS.getOrDefault(current, List.of()));
			}
		}
		return false;
	}

	/**
	 * Expands {@code (subtypep 'sub 'super)} into its constant answer through the shared
	 * lattice + class registry -- the compile-time fold of the evaluator's registered
	 * function. Lite: both type specifiers must be literal (quoted symbols, keywords,
	 * {@code t} or {@code nil}); a non-literal specifier is rejected at expansion time.
	 * @param cons the subtypep expression
	 * @param closRegistry the class registry for class-name type specifiers
	 * @return {@code t} or {@code nil}
	 */
	public static LispVal expandSubtypep(LispCons cons, ClosRegistry closRegistry) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			throw new IllegalArgumentException(LispNames.SUBTYPEP + " expects two type specifiers");
		}
		LispVal sub = literalTypeSpecifier(parts.get(1));
		LispVal sup = literalTypeSpecifier(parts.get(2));
		if (sub != null && sup != null) {
			return subtypep(sub, sup, closRegistry) ? LispTrue.INSTANCE : LispNil.INSTANCE;
		}
		// A runtime specifier: call the shared dispatch defun
		// (expandTopLevelDefinitions injects it once per program -- inlining the
		// dispatch at every call site overflows the 16-bit branch range of a large
		// method).
		return listToCons(List.of(new LispSymbol(LispNames.SUBTYPEP_RUNTIME), parts.get(1), parts.get(2)));
	}

	/**
	 * Whether the program contains a {@code subtypep} call with a non-literal type
	 * specifier -- the condition under which {@link #expandSubtypep} emits a call to the
	 * shared {@code %subtypep-runtime} dispatch defun, which
	 * {@link #expandTopLevelDefinitions} must then inject. Quoted data is skipped.
	 * @param program the top-level forms
	 * @return {@code true} when the shared dispatch defun is needed
	 */
	public static boolean needsRuntimeSubtypep(List<LispVal> program) {
		return program.stream().anyMatch(LispMacroExpander::containsRuntimeSubtypep);
	}

	private static boolean containsRuntimeSubtypep(LispVal form) {
		if (!(form instanceof LispCons cons)) {
			return false;
		}
		if (cons.car() instanceof LispSymbol op) {
			if (LispNames.QUOTE.equals(op.name())) {
				return false;
			}
			PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(op.name());
			String member = qn == null ? op.name() : qn.member();
			if (LispNames.SUBTYPEP.equals(member) && cons.isProperList()) {
				List<LispVal> parts = cons.toList();
				if (parts.size() == 3
						&& (literalTypeSpecifier(parts.get(1)) == null || literalTypeSpecifier(parts.get(2)) == null)) {
					return true;
				}
			}
		}
		return containsRuntimeSubtypep(cons.car()) || containsRuntimeSubtypep(cons.cdr());
	}

	/**
	 * Builds the shared {@code (defun %subtypep-runtime (a b) ...)} dispatch defun; see
	 * {@link #expandRuntimeSubtypep}.
	 */
	private static LispVal runtimeSubtypepDefun() {
		LispSymbol a = new LispSymbol("%st_ra");
		LispSymbol b = new LispSymbol("%st_rb");
		return listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.SUBTYPEP_RUNTIME),
				listToCons(List.of(a, b)), expandRuntimeSubtypep(a, b)));
	}

	/**
	 * Whether the program can call a function through a RUNTIME designator -- a
	 * {@code funcall}/{@code apply} whose function argument is neither {@code #'name} nor
	 * a literal {@code lambda}. Such a call may receive a SYMBOL at run time (cl-postgres
	 * passes {@code 'list-row-reader} through {@code exec-query}), which the compilers
	 * resolve late through the name registry -- so the registry and the real
	 * {@code _lookup} are emitted exactly when this answers true. Gating matters beyond
	 * size: the registry embeds every defun NAME, so emitting it unconditionally would
	 * make two programs that compile to identical CODE differ in bytes (the wit-import
	 * lowering's byte-identity pins).
	 * @param program the top-level forms
	 * @return {@code true} when a runtime function designator can reach a call site
	 */
	public static boolean usesRuntimeFunctionDesignator(List<LispVal> program) {
		return program.stream().anyMatch(LispMacroExpander::containsRuntimeFunctionDesignator);
	}

	private static boolean containsRuntimeFunctionDesignator(LispVal form) {
		if (!(form instanceof LispCons cons)) {
			return false;
		}
		if (cons.car() instanceof LispSymbol op) {
			if (LispNames.QUOTE.equals(op.name())) {
				return false;
			}
			PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(op.name());
			String member = qn == null ? op.name() : qn.member();
			if ((LispNames.FUNCALL.equals(member) || LispNames.APPLY.equals(member)) && cons.isProperList()) {
				List<LispVal> parts = cons.toList();
				if (parts.size() >= 2 && !isStaticFunctionDesignator(parts.get(1))) {
					return true;
				}
			}
			// uiop:symbol-call lowers to (funcall (intern ...) ...) INSIDE the
			// per-expression compilers, after this scan ran -- so the pre-lowering
			// spelling must count as a runtime-designator use itself (todo-229).
			if (LispNames.SYMBOL_CALL.equals(member) && qn != null && LispNames.UIOP_PKG.equals(qn.pkg())
					&& cons.isProperList() && cons.toList().size() >= 3) {
				return true;
			}
		}
		return containsRuntimeFunctionDesignator(cons.car()) || containsRuntimeFunctionDesignator(cons.cdr());
	}

	/** Whether a function-designator form names its target statically. */
	private static boolean isStaticFunctionDesignator(LispVal fnForm) {
		if (!(fnForm instanceof LispCons cons) || !(cons.car() instanceof LispSymbol head)) {
			return false;
		}
		// (quote name) is normalized to (function name) before compilation, so both
		// spellings are static here.
		return LispNames.FUNCTION.equals(head.name()) || LispNames.LAMBDA.equals(head.name())
				|| LispNames.QUOTE.equals(head.name());
	}

	/**
	 * Whether the program contains an {@code error} call with a computed condition-type
	 * datum AND initargs -- the condition under which the compile-path
	 * {@link #expandSignalDesignator} emits a call to the shared {@code %error-runtime}
	 * dispatch defun, which {@link #expandTopLevelDefinitions} must then inject together
	 * with its per-condition-class construction helpers. Quoted data is skipped.
	 * @param program the top-level forms
	 * @return {@code true} when the shared dispatch defun is needed
	 */
	public static boolean needsRuntimeErrorDispatch(List<LispVal> program) {
		return program.stream().anyMatch(LispMacroExpander::containsRuntimeErrorDispatch);
	}

	private static boolean containsRuntimeErrorDispatch(LispVal form) {
		if (!(form instanceof LispCons cons)) {
			return false;
		}
		if (cons.car() instanceof LispSymbol op) {
			if (LispNames.QUOTE.equals(op.name())) {
				return false;
			}
			PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(op.name());
			String member = qn == null ? op.name() : qn.member();
			if (LispNames.ERROR.equals(member) && cons.isProperList()) {
				List<LispVal> parts = cons.toList();
				if (parts.size() > 2 && isRuntimeErrorDatum(parts.get(1))) {
					return true;
				}
			}
		}
		return containsRuntimeErrorDispatch(cons.car()) || containsRuntimeErrorDispatch(cons.cdr());
	}

	/** Whether an error datum takes the runtime condition-type dispatch path. */
	private static boolean isRuntimeErrorDatum(LispVal datum) {
		if (datum instanceof LispString || quotedSymbol(datum) != null) {
			return false;
		}
		return !(datum instanceof LispCons mc && mc.car() instanceof LispSymbol mcOp
				&& LispNames.MAKE_CONDITION.equals(mcOp.name()) && mc.cdr() instanceof LispCons mcArgs
				&& quotedSymbol(mcArgs.car()) != null);
	}

	/**
	 * Builds the shared runtime-{@code error} dispatch machinery the compile path lowers
	 * {@code (error <computed-symbol> initargs...)} to: one small construction helper
	 * defun per registered CONDITION class (the same typed expansion a literal call
	 * compiles to, over {@code getf} reads of the runtime initarg list, each slot's
	 * {@code :initform} as the getf default), and the {@code %error-runtime} dispatch
	 * defun mapping the datum symbol (qualified or plain spelling) to its helper. A
	 * non-condition class name (an invalid CL datum) and any non-symbol fall to the
	 * object-designator path. No single method grows with the registry: the old inline
	 * per-class expansion at each call site reached 90 KB -- past the JVM's 64 KB hard
	 * method limit.
	 */
	private static List<LispVal> runtimeErrorDefuns(ClosRegistry closRegistry) {
		return runtimeErrorDefuns(closRegistry, false);
	}

	private static List<LispVal> runtimeErrorDefuns(ClosRegistry closRegistry, boolean signalHook) {
		List<LispVal> defuns = new java.util.ArrayList<>();
		LispSymbol d = new LispSymbol("%er_rd");
		LispSymbol a = new LispSymbol("%er_ra");
		List<LispVal> clauses = new java.util.ArrayList<>();
		int n = 0;
		for (ClosRegistry.ClassInfo info : closRegistry.classes().values()) {
			if (!info.ancestors().contains("CONDITION")) {
				continue;
			}
			String helperName = "%ERROR-RT-" + n++;
			LispSymbol ha = new LispSymbol("%er_ha");
			List<LispVal> items = new java.util.ArrayList<>();
			for (ClosRegistry.SlotSpec slot : info.slots()) {
				if (slot.initargKeyword() == null) {
					continue;
				}
				items.add(new LispSymbol(slot.initargKeyword()));
				List<LispVal> getfParts = new java.util.ArrayList<>();
				getfParts.add(new LispSymbol(LispNames.GETF));
				getfParts.add(ha);
				getfParts.add(new LispSymbol(slot.initargKeyword()));
				if (!(slot.initform() instanceof LispNil)) {
					getfParts.add(slot.initform());
				}
				items.add(listToCons(getfParts));
			}
			LispVal body = expandTypedSignal(LispNames.ERROR, LispNames.ERROR_INTERNAL, new LispSymbol(info.name()),
					items, closRegistry, signalHook);
			defuns.add(listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(helperName),
					listToCons(List.<LispVal>of(ha)), body)));
			List<String> spellings = new java.util.ArrayList<>();
			spellings.add(info.name());
			PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(info.name());
			if (qn != null && closRegistry.findClass(qn.member()) == info) {
				spellings.add(qn.member());
			}
			clauses.add(listToCons(List.of(mvCall(LispNames.MEMBER, d, quotedSymbolList(spellings)),
					listToCons(List.of(new LispSymbol(helperName), a)))));
		}
		// The fallthrough: a datum that names no condition class. A STRING one is a
		// format control, and then the second argument is its format-argument list
		// rather than an initarg plist, so the object designator renders it (todo-220);
		// every other value keeps the plain object shape, which ignores the list.
		clauses.add(listToCons(List.of(LispTrue.INSTANCE,
				expandObjectSignal(LispNames.ERROR_INTERNAL, d, closRegistry, signalHook, a))));
		List<LispVal> condParts = new java.util.ArrayList<>();
		condParts.add(new LispSymbol(LispNames.COND));
		condParts.addAll(clauses);
		defuns.add(listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.ERROR_RUNTIME),
				listToCons(List.of(d, a)), listToCons(condParts))));
		return defuns;
	}

	/**
	 * Whether the program contains a {@code typep} call with a computed (non-literal)
	 * type specifier -- the condition under which the compile-path
	 * {@link #expandTypep(LispCons, ClosRegistry, boolean)} emits a call to the shared
	 * {@code %typep-runtime} dispatch defun, which {@link #expandTopLevelDefinitions}
	 * must then inject together with its data table. Quoted data is skipped.
	 * @param program the top-level forms
	 * @return {@code true} when the shared dispatch defun is needed
	 */
	public static boolean needsRuntimeTypep(List<LispVal> program) {
		return program.stream().anyMatch(LispMacroExpander::containsRuntimeTypep);
	}

	private static boolean containsRuntimeTypep(LispVal form) {
		if (!(form instanceof LispCons cons)) {
			return false;
		}
		if (cons.car() instanceof LispSymbol op) {
			if (LispNames.QUOTE.equals(op.name())) {
				return false;
			}
			PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(op.name());
			String member = qn == null ? op.name() : qn.member();
			if (LispNames.TYPEP.equals(member) && cons.isProperList()) {
				List<LispVal> parts = cons.toList();
				if (parts.size() == 3 && isComputedTypepSpec(parts.get(2))) {
					return true;
				}
			}
		}
		return containsRuntimeTypep(cons.car()) || containsRuntimeTypep(cons.cdr());
	}

	/** Whether a typep specifier argument takes the computed-specifier dispatch path. */
	private static boolean isComputedTypepSpec(LispVal typeArg) {
		if (typeArg instanceof LispCons quoted && quoted.car() instanceof LispSymbol q
				&& LispNames.QUOTE.equals(q.name()) && quoted.cdr() instanceof LispCons) {
			return false;
		}
		return !(typeArg instanceof LispSymbol sym && sym.name().startsWith(":"));
	}

	/**
	 * Builds the {@code %typep-tag-table%} data-table forms backing the shared
	 * runtime-{@code typep} defun: each entry maps the spellings of one registered
	 * class/struct type name (plus the {@code standard-object} / {@code structure-object}
	 * unions) to the instance tags that name accepts. Pure quoted data, emitted through
	 * {@link #chunkedTableForms}.
	 */
	private static List<LispVal> typepTagTableForms(ClosRegistry closRegistry) {
		java.util.Map<List<String>, java.util.LinkedHashSet<String>> namesByTags = new java.util.LinkedHashMap<>();
		java.util.Set<String> seen = new java.util.HashSet<>();
		for (ClosRegistry.ClassInfo info : closRegistry.classes().values()) {
			if (!seen.add(info.name())) {
				continue;
			}
			List<String> tags = closRegistry.descendantTags(info.name());
			java.util.LinkedHashSet<String> names = namesByTags.computeIfAbsent(tags,
					k -> new java.util.LinkedHashSet<>());
			names.add(info.name());
			PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(info.name());
			if (qn != null) {
				names.add(qn.member());
			}
		}
		List<String> allClassTags = new java.util.ArrayList<>();
		for (ClosRegistry.ClassInfo info : closRegistry.classes().values()) {
			allClassTags.add(LispLayout.CLASS_TAG_PREFIX + info.name());
		}
		List<String> allStructTags = new java.util.ArrayList<>();
		for (LispLayout layout : closRegistry.layouts().values()) {
			if (layout.kind() == LispLayout.Kind.STRUCT) {
				String name = layout.printName();
				allStructTags.add(layout.tag());
				if (seen.add(name)) {
					List<String> tags = closRegistry.descendantStructTags(name);
					java.util.LinkedHashSet<String> names = namesByTags.computeIfAbsent(tags,
							k -> new java.util.LinkedHashSet<>());
					names.add(name);
					PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(name);
					if (qn != null) {
						names.add(qn.member());
					}
				}
			}
		}
		namesByTags.computeIfAbsent(allClassTags, k -> new java.util.LinkedHashSet<>()).add("STANDARD-OBJECT");
		namesByTags.computeIfAbsent(allStructTags, k -> new java.util.LinkedHashSet<>()).add("STRUCTURE-OBJECT");
		List<LispVal> entries = new java.util.ArrayList<>();
		for (java.util.Map.Entry<List<String>, java.util.LinkedHashSet<String>> entry : namesByTags.entrySet()) {
			List<LispVal> entryParts = new java.util.ArrayList<>();
			List<LispVal> nameSyms = new java.util.ArrayList<>();
			for (String name : entry.getValue()) {
				nameSyms.add(new LispSymbol(name));
			}
			entryParts.add(listToCons(nameSyms));
			for (String tag : entry.getKey()) {
				entryParts.add(new LispSymbol(tag));
			}
			entries.add(listToCons(entryParts));
		}
		return chunkedTableForms(LispNames.TYPEP_TAG_TABLE, entries);
	}

	/**
	 * Emits a quoted data table as a bounded SEQUENCE of top-level forms -- a
	 * {@code defvar} holding the first chunk of entries and {@code (setq name (append
	 * 'chunk name))} forms for the rest -- because a quoted constant compiles to
	 * construction code proportional to its size, and one table-sized form would grow a
	 * single top-level chunk method with the registry (the tables' entries are
	 * order-independent, so append-prepending chunks is safe).
	 */
	private static List<LispVal> chunkedTableForms(String varName, List<LispVal> entries) {
		final int chunkSize = 48;
		List<LispVal> forms = new java.util.ArrayList<>();
		for (int start = 0; start == 0 || start < entries.size(); start += chunkSize) {
			LispVal chunk = listToCons(List.of(new LispSymbol(LispNames.QUOTE),
					listToCons(entries.subList(start, Math.min(start + chunkSize, entries.size())))));
			if (start == 0) {
				forms.add(listToCons(List.of(new LispSymbol(LispNames.DEFVAR), new LispSymbol(varName), chunk)));
			}
			else {
				forms.add(listToCons(List.of(new LispSymbol(LispNames.SETQ), new LispSymbol(varName),
						listToCons(List.of(new LispSymbol(LispNames.APPEND), chunk, new LispSymbol(varName))))));
			}
		}
		return forms;
	}

	/**
	 * Builds the shared {@code (defun %typep-runtime (v tn) ...)} dispatch defun the
	 * compile-path {@code typep} lowers a computed type specifier to. An instance answers
	 * through the {@code %typep-tag-table%} data table (tag membership, the same test the
	 * literal specifier compiles to); any other value answers through the built-in atomic
	 * type names' value predicates. The defun's size is bounded by the built-in name
	 * count -- the per-class data lives in the table, so it does not grow with the number
	 * of registered classes (the inline dispatch overflowed the JVM's 16-bit branch
	 * offsets at 165 registered classes).
	 */
	private static LispVal runtimeTypepDefun(ClosRegistry closRegistry) {
		LispSymbol v = new LispSymbol("%tp_rv");
		LispSymbol tn = new LispSymbol("%tp_rt");
		LispSymbol tag = new LispSymbol("%tp_rtag");
		LispSymbol entry = new LispSymbol("%tp_re");
		// (dolist (e table nil) (if (member tn (car e)) (return (if (member tag (cdr
		// e)) t nil)) nil))
		LispVal tableScan = listToCons(List.of(new LispSymbol(LispNames.DOLIST),
				listToCons(List.of(entry, new LispSymbol(LispNames.TYPEP_TAG_TABLE), LispNil.INSTANCE)),
				makeIf(mvCall(LispNames.MEMBER, tn, mvCall(LispNames.CAR, entry)),
						listToCons(List.of(new LispSymbol(LispNames.RETURN),
								makeIf(mvCall(LispNames.MEMBER, tag, mvCall(LispNames.CDR, entry)), LispTrue.INSTANCE,
										LispNil.INSTANCE))),
						LispNil.INSTANCE)));
		LispVal instanceBranch = makeIf(mvCall(LispNames.MEMBER, tn, quotedSymbolList(List.of("T", "ATOM"))),
				LispTrue.INSTANCE, makeLet(tag.name(), objTag(v), tableScan));
		List<LispVal> clauses = new java.util.ArrayList<>();
		clauses.add(listToCons(List.of(callOf(LispNames.OBJ_P, v), instanceBranch)));
		// tn = T accepts everything (makeTypeTest only knows the LispTrue spelling,
		// which a runtime specifier value never is).
		clauses.add(listToCons(List.of(nameMatchTest(tn, "T"), LispTrue.INSTANCE)));
		for (String builtin : RUNTIME_TYPEP_BUILTINS) {
			if ("STANDARD-OBJECT".equals(builtin) || "STRUCTURE-OBJECT".equals(builtin)) {
				// v is not an instance here, so these are constant nil: fall through.
				continue;
			}
			LispVal test;
			try {
				test = makeTypeTest(v, new LispSymbol(builtin), closRegistry);
			}
			catch (IllegalArgumentException unsupported) {
				continue;
			}
			clauses.add(
					listToCons(List.of(nameMatchTest(tn, builtin), makeIf(test, LispTrue.INSTANCE, LispNil.INSTANCE))));
		}
		clauses.add(listToCons(List.of(LispTrue.INSTANCE, LispNil.INSTANCE)));
		List<LispVal> condParts = new java.util.ArrayList<>();
		condParts.add(new LispSymbol(LispNames.COND));
		condParts.addAll(clauses);
		return listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.TYPEP_RUNTIME),
				listToCons(List.of(v, tn)), listToCons(condParts)));
	}

	/**
	 * Builds the {@code %class-meta-table%} data-table forms (and the metaobject memo
	 * global) backing the generated runtime {@code %find-class}: one entry per registered
	 * class or struct layout holding the name spellings that designate it -- the INSTANCE
	 * TAG among them, so a {@code class-of} designator resolves with the same scan -- the
	 * canonical superclass name (nil at a root), and per effective slot the
	 * {@code (name initargs initform type readers)} data its slot-definition metaobject
	 * is materialized from -- the same shape {@code ClosRegistry.classMetaobject} builds
	 * on the interpreter, so the {@code %obj-ref} index contract of the seeded MOP
	 * layouts is served identically (struct slots read type {@code T} and no readers,
	 * like {@code slotDefs}). Pure quoted data, emitted through
	 * {@link #nodeBudgetedTableForms}.
	 */
	private static List<LispVal> classMetaTableForms(ClosRegistry closRegistry) {
		List<LispVal> entries = new java.util.ArrayList<>();
		java.util.Set<String> seen = new java.util.HashSet<>();
		for (ClosRegistry.ClassInfo info : closRegistry.classes().values()) {
			if (!seen.add(info.name())) {
				continue;
			}
			java.util.LinkedHashSet<String> spellings = new java.util.LinkedHashSet<>();
			// The canonical spelling comes FIRST: the generated %find-class memoizes
			// (and names the metaobject) by (car (car entry)).
			spellings.add(info.name());
			PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(info.name());
			if (qn != null) {
				spellings.add(qn.member());
			}
			spellings.add(LispLayout.CLASS_TAG_PREFIX + info.name());
			List<LispVal> spellingSyms = new java.util.ArrayList<>();
			for (String spelling : spellings) {
				spellingSyms.add(new LispSymbol(spelling));
			}
			List<LispVal> slotDefs = new java.util.ArrayList<>();
			for (ClosRegistry.SlotSpec slot : info.slots()) {
				List<String> readerNames = new java.util.ArrayList<>(slot.readers());
				readerNames.addAll(slot.accessors());
				LispVal readers = LispNil.INSTANCE;
				for (int i = readerNames.size() - 1; i >= 0; i--) {
					readers = new LispCons(new LispSymbol(readerNames.get(i)), readers);
				}
				slotDefs.add(listToCons(List.of(new LispSymbol(slot.baseName()),
						listToCons(List.of(new LispSymbol(slot.initargKeyword()))),
						slot.initformSupplied() ? slot.initform() : LispNil.INSTANCE, new LispSymbol(slot.type()),
						readers)));
			}
			LispVal superNames = info.superclasses().isEmpty() ? LispNil.INSTANCE
					: listToCons(info.superclasses().stream().<LispVal>map(LispSymbol::new).toList());
			entries.add(listToCons(List.of(listToCons(spellingSyms), superNames,
					slotDefs.isEmpty() ? LispNil.INSTANCE : listToCons(slotDefs))));
		}
		for (LispLayout layout : closRegistry.layouts().values()) {
			if (!layout.tag().startsWith(LispLayout.STRUCT_TAG_PREFIX) || !seen.add(layout.printName())) {
				continue;
			}
			java.util.LinkedHashSet<String> spellings = new java.util.LinkedHashSet<>();
			spellings.add(layout.printName());
			PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(layout.printName());
			if (qn != null) {
				spellings.add(qn.member());
			}
			spellings.add(layout.tag());
			List<LispVal> spellingSyms = new java.util.ArrayList<>();
			for (String spelling : spellings) {
				spellingSyms.add(new LispSymbol(spelling));
			}
			List<LispVal> slotDefs = new java.util.ArrayList<>();
			List<String> slotNames = layout.slotNames();
			for (int i = 0; i < slotNames.size(); i++) {
				slotDefs.add(listToCons(List.of(new LispSymbol(slotNames.get(i)),
						listToCons(List.of(new LispSymbol(":" + slotNames.get(i)))), layout.initforms().get(i),
						new LispSymbol("T"), LispNil.INSTANCE)));
			}
			String parent = closRegistry.structParent(layout.printName());
			entries.add(listToCons(List.of(listToCons(spellingSyms),
					parent == null ? LispNil.INSTANCE : listToCons(List.<LispVal>of(new LispSymbol(parent))),
					slotDefs.isEmpty() ? LispNil.INSTANCE : listToCons(slotDefs))));
		}
		// Chunked by NODE budget, not entry count: unlike the flat typep/subtypep tag
		// tables, one entry here nests the whole slot-data tree, so a 48-entry chunk of a
		// class-heavy program compiles past the JVM's 65535-byte method ceiling (the
		// ci-spec corpus did, at 70178 bytes).
		List<LispVal> forms = new java.util.ArrayList<>(
				nodeBudgetedTableForms(LispNames.CLASS_META_TABLE, entries, 600));
		forms.add(listToCons(List.of(new LispSymbol(LispNames.DEFVAR), new LispSymbol(LispNames.CLASS_METAOBJECT_MEMO),
				LispNil.INSTANCE)));
		return forms;
	}

	/**
	 * As {@link #chunkedTableForms}, but bounding each chunk by the TOTAL cons-node count
	 * of its entries instead of by entry count -- for tables whose entries are deep trees
	 * (quoted data compiles to construction code proportional to its node count, and a
	 * chunk lands inside one top-level method).
	 */
	private static List<LispVal> nodeBudgetedTableForms(String varName, List<LispVal> entries, int nodeBudget) {
		List<LispVal> forms = new java.util.ArrayList<>();
		List<LispVal> chunk = new java.util.ArrayList<>();
		int chunkNodes = 0;
		boolean first = true;
		for (int i = 0; i <= entries.size(); i++) {
			boolean flush = i == entries.size() || (!chunk.isEmpty() && chunkNodes >= nodeBudget);
			if (flush && (!chunk.isEmpty() || first)) {
				LispVal data = listToCons(List.of(new LispSymbol(LispNames.QUOTE), listToCons(chunk)));
				if (first) {
					forms.add(listToCons(List.of(new LispSymbol(LispNames.DEFVAR), new LispSymbol(varName), data)));
					first = false;
				}
				else {
					forms.add(listToCons(List.of(new LispSymbol(LispNames.SETQ), new LispSymbol(varName),
							listToCons(List.of(new LispSymbol(LispNames.APPEND), data, new LispSymbol(varName))))));
				}
				chunk = new java.util.ArrayList<>();
				chunkNodes = 0;
			}
			if (i < entries.size()) {
				chunk.add(entries.get(i));
				chunkNodes += consNodeCount(entries.get(i));
			}
		}
		return forms;
	}

	/** The cons-cell count of a tree -- the size measure of quoted-data construction. */
	private static int consNodeCount(LispVal value) {
		if (!(value instanceof LispCons cons)) {
			return 0;
		}
		return 1 + consNodeCount(cons.car()) + consNodeCount(cons.cdr());
	}

	/**
	 * Builds the generated metaobject runtime's defuns: the internal {@code %find-class}
	 * resolver (scans the {@code %class-meta-table%} spellings -- instance tags included
	 * -- then falls back to the built-in class names, with CL {@code errorp} semantics),
	 * the {@code %find-class-materialize} helper -- which builds one class metaobject
	 * from its table entry (effective-slot-definition instances, the superclass
	 * metaobject through a recursive {@code %find-class}) and memoizes it under the
	 * canonical name so the answer is {@code eq}-stable across calls and spellings, like
	 * the interpreter's registry memo -- and, when the program references
	 * {@code find-class} without defining it, the public {@code find-class} wrapper. All
	 * are position-independent plain defuns; the size is constant -- the per-class data
	 * lives in the table.
	 * @param publicFindClass whether to emit the public {@code find-class} defun
	 */
	private static List<LispVal> findClassRuntimeDefuns(boolean publicFindClass) {
		LispSymbol sym = new LispSymbol("%fc_sym");
		LispSymbol errorp = new LispSymbol("%fc_errorp");
		LispSymbol env = new LispSymbol("%fc_env");
		LispSymbol entry = new LispSymbol("%fc_e");
		LispSymbol scan = new LispSymbol("%fc_x");
		// (dolist (x table) (if (member sym (car x)) (progn (setq e x) (return nil))
		// nil))
		LispVal tableScan = listToCons(List.of(new LispSymbol(LispNames.DOLIST),
				listToCons(List.of(scan, new LispSymbol(LispNames.CLASS_META_TABLE), LispNil.INSTANCE)),
				makeIf(mvCall(LispNames.MEMBER, sym, mvCall(LispNames.CAR, scan)),
						listToCons(List.of(new LispSymbol(LispNames.PROGN),
								listToCons(List.of(new LispSymbol(LispNames.SETQ), entry, scan)),
								listToCons(List.of(new LispSymbol(LispNames.RETURN), LispNil.INSTANCE)))),
						LispNil.INSTANCE)));
		// The built-in classes (integer, string, ..., t): materialized through the same
		// memo with a synthetic slot-less entry, so (eq (class-of 42) (find-class
		// 'integer)) holds. The boolean t is tested apart from the member scan -- (find-
		// class t) hands the BOOLEAN over, while the %class-designator dispatch yields
		// the symbol spelling.
		List<LispVal> builtinSyms = new java.util.ArrayList<>();
		for (String name : ClosRegistry.BUILTIN_CLASS_NAMES) {
			builtinSyms.add(new LispSymbol(name));
		}
		LispVal builtinList = listToCons(
				List.of(new LispSymbol(LispNames.QUOTE), listToCons(java.util.List.copyOf(builtinSyms))));
		LispVal syntheticEntry = mvCall(LispNames.CONS, mvCall(LispNames.CONS, sym, LispNil.INSTANCE),
				LispNil.INSTANCE);
		LispVal builtinAnswer = makeIf(fmtCall(LispNames.EQ_GENERAL, sym, LispTrue.INSTANCE),
				mvCall(LispNames.FIND_CLASS_MATERIALIZE, quoteOf("T"),
						mvCall(LispNames.CONS, mvCall(LispNames.CONS, quoteOf("T"), LispNil.INSTANCE),
								LispNil.INSTANCE)),
				makeIf(mvCall(LispNames.MEMBER, sym, builtinList),
						mvCall(LispNames.FIND_CLASS_MATERIALIZE, sym, syntheticEntry),
						makeIf(errorp,
								listToCons(List.of(new LispSymbol(LispNames.ERROR),
										new LispString(LispNames.FIND_CLASS + ": there is no class named ~A"), sym)),
								LispNil.INSTANCE)));
		LispVal answer = makeIf(entry,
				mvCall(LispNames.FIND_CLASS_MATERIALIZE, mvCall(LispNames.CAR, mvCall(LispNames.CAR, entry)), entry),
				builtinAnswer);
		LispVal findClassInternal = listToCons(List.of(new LispSymbol(LispNames.DEFUN),
				new LispSymbol(LispNames.FIND_CLASS_INTERNAL), listToCons(List.of(sym, errorp)),
				listToCons(List.of(new LispSymbol(LispNames.LET),
						listToCons(List.of(listToCons(List.of(entry, LispNil.INSTANCE)))), tableScan, answer))));
		LispVal findClass = listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.FIND_CLASS),
				listToCons(List.of(sym, new LispSymbol(LispNames.LAMBDA_OPTIONAL),
						listToCons(List.of(errorp, LispTrue.INSTANCE)), env)),
				mvCall(LispNames.FIND_CLASS_INTERNAL, sym, errorp)));

		LispSymbol name = new LispSymbol("%fc_name");
		LispSymbol hit = new LispSymbol("%fc_hit");
		LispSymbol slots = new LispSymbol("%fc_slots");
		LispSymbol slotDef = new LispSymbol("%fc_s");
		LispSymbol metaobject = new LispSymbol("%fc_mo");
		// (dolist (x memo) (if (eq (car x) name) (progn (setq hit x) (return nil)) nil))
		LispVal memoScan = listToCons(List.of(new LispSymbol(LispNames.DOLIST),
				listToCons(List.of(scan, new LispSymbol(LispNames.CLASS_METAOBJECT_MEMO), LispNil.INSTANCE)),
				makeIf(mvCall(LispNames.EQ_GENERAL, mvCall(LispNames.CAR, scan), name),
						listToCons(List.of(new LispSymbol(LispNames.PROGN),
								listToCons(List.of(new LispSymbol(LispNames.SETQ), hit, scan)),
								listToCons(List.of(new LispSymbol(LispNames.RETURN), LispNil.INSTANCE)))),
						LispNil.INSTANCE)));
		// Slot data (name initargs initform type readers) -> the effective-slot
		// instance, consed in reverse table order.
		LispVal slotData = mvCall(LispNames.CAR, mvCall(LispNames.CDR, mvCall(LispNames.CDR, entry)));
		LispVal s0 = mvCall(LispNames.CAR, slotDef);
		LispVal s1 = mvCall(LispNames.CAR, mvCall(LispNames.CDR, slotDef));
		LispVal s2 = mvCall(LispNames.CAR, mvCall(LispNames.CDR, mvCall(LispNames.CDR, slotDef)));
		LispVal s3 = mvCall(LispNames.CAR,
				mvCall(LispNames.CDR, mvCall(LispNames.CDR, mvCall(LispNames.CDR, slotDef))));
		LispVal s4 = mvCall(LispNames.CAR,
				mvCall(LispNames.CDR, mvCall(LispNames.CDR, mvCall(LispNames.CDR, mvCall(LispNames.CDR, slotDef)))));
		LispVal slotBuild = listToCons(List.of(new LispSymbol(LispNames.DOLIST),
				listToCons(List.of(slotDef, slotData, LispNil.INSTANCE)),
				listToCons(List.of(new LispSymbol(LispNames.SETQ), slots, mvCall(LispNames.CONS,
						objNew(LispLayout.CLASS_TAG_PREFIX + ClosRegistry.STANDARD_EFFECTIVE_SLOT_DEFINITION_NAME,
								List.of(s0, s1, s2, s3, s4)),
						slots)))));
		// The entry's superclass column is a LIST of names (multiple inheritance);
		// materialize each through the recursive resolver, preserving order.
		LispVal superNames = mvCall(LispNames.CAR, mvCall(LispNames.CDR, entry));
		LispSymbol superAcc = new LispSymbol("%fc_sup");
		LispSymbol superVar = new LispSymbol("%fc_sn");
		LispVal supers = listToCons(List.of(new LispSymbol(LispNames.LET),
				listToCons(List.of(listToCons(List.of(superAcc, LispNil.INSTANCE)))),
				listToCons(List.of(new LispSymbol(LispNames.DOLIST),
						listToCons(List.of(superVar, superNames, LispNil.INSTANCE)),
						listToCons(List.of(new LispSymbol(LispNames.SETQ), superAcc, mvCall(LispNames.CONS,
								mvCall(LispNames.FIND_CLASS_INTERNAL, superVar, LispTrue.INSTANCE), superAcc))))),
				mvCall(LispNames.REVERSE, superAcc)));
		LispVal buildMetaobject = objNew(LispLayout.CLASS_TAG_PREFIX + ClosRegistry.STANDARD_CLASS_NAME,
				List.of(name, supers, LispNil.INSTANCE, mvCall(LispNames.REVERSE, slots), LispTrue.INSTANCE));
		LispVal memoize = listToCons(List.of(new LispSymbol(LispNames.SETQ),
				new LispSymbol(LispNames.CLASS_METAOBJECT_MEMO), mvCall(LispNames.CONS,
						mvCall(LispNames.CONS, name, metaobject), new LispSymbol(LispNames.CLASS_METAOBJECT_MEMO))));
		LispVal construct = listToCons(List.of(new LispSymbol(LispNames.LET),
				listToCons(List.of(listToCons(List.of(slots, LispNil.INSTANCE)))), slotBuild,
				listToCons(List.of(new LispSymbol(LispNames.LET),
						listToCons(List.of(listToCons(List.of(metaobject, buildMetaobject)))), memoize, metaobject))));
		LispVal materialize = listToCons(List.of(new LispSymbol(LispNames.DEFUN),
				new LispSymbol(LispNames.FIND_CLASS_MATERIALIZE), listToCons(List.of(name, entry)),
				listToCons(List.of(new LispSymbol(LispNames.LET),
						listToCons(List.of(listToCons(List.of(hit, LispNil.INSTANCE)))), memoScan,
						makeIf(hit, mvCall(LispNames.CDR, hit), construct)))));
		return publicFindClass ? List.of(findClassInternal, findClass, materialize)
				: List.of(findClassInternal, materialize);
	}

	/**
	 * Whether the program references {@code allocate-instance} -- a call, or
	 * {@code #'allocate-instance} taken as a value -- without bringing its own
	 * definition, which is the condition under which {@link #expandTopLevelDefinitions}
	 * injects the generated {@code allocate-instance} defun and its per-class
	 * construction helpers. Quoted data is skipped.
	 * @param program the top-level forms
	 * @return true when the generated allocate-instance runtime is needed
	 */
	private static boolean needsAllocateInstanceRuntime(List<LispVal> program) {
		boolean referenced = false;
		for (LispVal form : program) {
			if (definesFunction(form, LispNames.ALLOCATE_INSTANCE)) {
				return false;
			}
			referenced = referenced || referencesFunction(form, LispNames.ALLOCATE_INSTANCE);
		}
		return referenced;
	}

	/**
	 * Builds the generated {@code allocate-instance} runtime: per-class construction
	 * helper defuns ({@code %ALLOC-INST-<n>}, chunked by cons-node budget so no single
	 * method grows with the registry -- the {@code %error-runtime} lesson), each
	 * answering an instance with EVERY slot unbound for its subset of the registered
	 * classes, and the public {@code allocate-instance} defun resolving the class
	 * designator (a metaobject's name slot, or the name symbol itself) through them.
	 * {@code %obj-new} needs a LITERAL tag on the compile backends, so the dispatch
	 * cannot be data-driven like the metaobject table -- each class gets its own arm.
	 * Only registered CLOS classes allocate; anything else signals, like CL's
	 * built-in-class behavior -- struct classes included (their construction contract is
	 * the positional constructor, not slot filling), matching the interpreter built-in.
	 */
	private static List<LispVal> allocateInstanceDefuns(ClosRegistry closRegistry) {
		LispSymbol name = new LispSymbol("%ai_name");
		List<LispVal> defuns = new java.util.ArrayList<>();
		List<String> helperNames = new java.util.ArrayList<>();
		List<LispVal> clauses = new java.util.ArrayList<>();
		int clauseNodes = 0;
		java.util.Set<String> seen = new java.util.HashSet<>();
		for (ClosRegistry.ClassInfo info : closRegistry.classes().values()) {
			if (!seen.add(info.name())) {
				continue;
			}
			List<String> spellings = new java.util.ArrayList<>();
			spellings.add(info.name());
			PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(info.name());
			if (qn != null && closRegistry.findClass(qn.member()) == info) {
				spellings.add(qn.member());
			}
			List<LispVal> unboundSlots = new java.util.ArrayList<>();
			for (int i = 0; i < info.slots().size(); i++) {
				unboundSlots.add(objNew(ClosRegistry.UNBOUND_TAG, List.of()));
			}
			LispVal clause = listToCons(List.of(mvCall(LispNames.MEMBER, name, quotedSymbolList(spellings)),
					objNew(LispLayout.CLASS_TAG_PREFIX + info.name(), unboundSlots)));
			clauses.add(clause);
			clauseNodes += consNodeCount(clause);
			if (clauseNodes >= 600) {
				defuns.add(allocateInstanceHelperDefun(helperNames, clauses, name));
				clauses = new java.util.ArrayList<>();
				clauseNodes = 0;
			}
		}
		if (!clauses.isEmpty()) {
			defuns.add(allocateInstanceHelperDefun(helperNames, clauses, name));
		}
		LispSymbol cls = new LispSymbol("%ai_class");
		LispSymbol initargs = new LispSymbol("%ai_initargs");
		LispSymbol result = new LispSymbol("%ai_r");
		// (if (%obj-p class) (%obj-ref class 0) class) -- a metaobject designates
		// through its name slot; anything else is taken as the name itself.
		LispVal designator = makeIf(callOf(LispNames.OBJ_P, cls), mvCall(LispNames.OBJ_REF, cls, new LispInteger(0)),
				cls);
		LispVal chain = LispNil.INSTANCE;
		if (!helperNames.isEmpty()) {
			List<LispVal> orParts = new java.util.ArrayList<>();
			orParts.add(new LispSymbol(LispNames.OR));
			for (String helper : helperNames) {
				orParts.add(mvCall(helper, name));
			}
			chain = listToCons(orParts);
		}
		LispVal body = makeLet(name.name(), designator,
				makeLet(result.name(), chain, makeIf(result, result, listToCons(List.of(new LispSymbol(LispNames.ERROR),
						new LispString(LispNames.ALLOCATE_INSTANCE + ": not an allocatable class: ~A"), name)))));
		defuns.add(listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.ALLOCATE_INSTANCE),
				listToCons(List.of(cls, new LispSymbol(LispNames.LAMBDA_REST), initargs)), body)));
		return defuns;
	}

	/** One {@code %ALLOC-INST-<n>} helper: a cond over its chunk's class arms. */
	private static LispVal allocateInstanceHelperDefun(List<String> helperNames, List<LispVal> clauses,
			LispSymbol name) {
		String helperName = "%ALLOC-INST-" + helperNames.size();
		helperNames.add(helperName);
		List<LispVal> condParts = new java.util.ArrayList<>();
		condParts.add(new LispSymbol(LispNames.COND));
		condParts.addAll(clauses);
		condParts.add(listToCons(List.of(LispTrue.INSTANCE, LispNil.INSTANCE)));
		return listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(helperName),
				listToCons(List.<LispVal>of(name)), listToCons(condParts)));
	}

	/** Whether any top-level {@code defclass} carries a {@code (:metaclass M)} option. */
	private static boolean usesMetaclassProtocol(List<LispVal> program) {
		for (LispVal form : program) {
			if (isNamedForm(form, LispNames.DEFCLASS) && defclassUsesMetaclass((LispCons) form)) {
				return true;
			}
		}
		return false;
	}

	/**
	 * Whether the {@code defclass} form carries a {@code (:metaclass M)} class option --
	 * the trigger that loads the metaclass protocol (the interpreter's
	 * {@code ensureMopProtocolLoaded}, the compile paths' {@code MopProtocol} injection).
	 * @param cons the defclass expression
	 * @return true when a {@code :metaclass} option is present
	 */
	public static boolean defclassUsesMetaclass(LispCons cons) {
		List<LispVal> parts = cons.toList();
		for (int i = 4; i < parts.size(); i++) {
			if (parts.get(i) instanceof LispCons optCons && optCons.car() instanceof LispSymbol optSym
					&& ":METACLASS".equals(plainTypeName(optSym))) {
				return true;
			}
		}
		return false;
	}

	/** Whether any top-level {@code defclass} extends a seeded MOP base class. */
	private static boolean namesMopBaseSuperclass(List<LispVal> program) {
		for (LispVal form : program) {
			if (isNamedForm(form, LispNames.DEFCLASS) && defclassNamesMopBaseSuperclass((LispCons) form)) {
				return true;
			}
		}
		return false;
	}

	/**
	 * Whether the {@code defclass} form names one of the seeded MOP base classes
	 * ({@code standard-class}, the two slot-definition classes) as a superclass -- a
	 * metaclass or slot-definition-class definition, which needs
	 * {@code ClosRegistry.ensureMopClassesSeeded()} to have run before the superclass
	 * lookup. Qualified spellings ({@code closer-mop:standard-direct-slot-definition})
	 * match by member name, like the registry's own lookup.
	 * @param cons the defclass expression
	 * @return true when a MOP base class is a superclass
	 */
	public static boolean defclassNamesMopBaseSuperclass(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3 || !(parts.get(2) instanceof LispCons superCons)) {
			return false;
		}
		for (LispVal superName : superCons.toList()) {
			if (superName instanceof LispSymbol sym) {
				PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(sym.name());
				String member = qn == null ? sym.name() : qn.member();
				if (ClosRegistry.STANDARD_CLASS_NAME.equals(member)
						|| ClosRegistry.STANDARD_DIRECT_SLOT_DEFINITION_NAME.equals(member)
						|| ClosRegistry.STANDARD_EFFECTIVE_SLOT_DEFINITION_NAME.equals(member)) {
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Builds the keyword constructors of the three seeded MOP base classes
	 * ({@code %make-standard-class}, ...): their {@code defclass} never ran, so the
	 * {@code expandDefclass}-generated constructor every {@code make-instance} path
	 * dispatches to does not otherwise exist. Same shape as the generated ones -- one
	 * {@code &key} parameter per slot under its seeded {@code :slot-name} initarg (nil
	 * default) plus {@code &allow-other-keys}. Shared by the compile paths (appended with
	 * the metaclass runtime) and the interpreter (evaluated once at protocol load).
	 * @param closRegistry the registry, already seeded
	 * @return the three constructor defuns
	 */
	public static List<LispVal> seededMopConstructorDefuns(ClosRegistry closRegistry) {
		List<LispVal> defuns = new java.util.ArrayList<>();
		for (String name : List.of(ClosRegistry.STANDARD_CLASS_NAME, ClosRegistry.STANDARD_DIRECT_SLOT_DEFINITION_NAME,
				ClosRegistry.STANDARD_EFFECTIVE_SLOT_DEFINITION_NAME)) {
			ClosRegistry.ClassInfo info = java.util.Objects.requireNonNull(closRegistry.findClass(name),
					"MOP base class not seeded: " + name);
			List<LispVal> lambdaList = new java.util.ArrayList<>();
			lambdaList.add(new LispSymbol(LispNames.LAMBDA_KEY));
			List<LispVal> slotVars = new java.util.ArrayList<>();
			for (ClosRegistry.SlotSpec slot : info.slots()) {
				LispVal keywordAndVar = listToCons(
						List.of(new LispSymbol(slot.initargKeyword()), new LispSymbol(slot.name())));
				lambdaList.add(listToCons(List.of(keywordAndVar, slot.initform())));
				slotVars.add(new LispSymbol(slot.name()));
			}
			lambdaList.add(new LispSymbol(LispNames.LAMBDA_ALLOW_OTHER_KEYS));
			defuns.add(
					listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(affixFor("%make-", name) + name),
							listToCons(lambdaList), objNew(LispLayout.CLASS_TAG_PREFIX + name, slotVars))));
		}
		return defuns;
	}

	/**
	 * Builds the generated {@code %mop-make-instance} defun: the runtime-class
	 * {@code make-instance} of the metaclass protocol. The designator (a metaobject's
	 * name slot, or the name symbol itself) dispatches by name to the class's generated
	 * keyword constructor, then runs the program's initialization generic exactly like
	 * the static {@code make-instance} expansion (the user's {@code shared-initialize}
	 * hooks on metaobjects are the point of the exercise). Only the METAOBJECT-ancestored
	 * classes get arms -- the protocol instantiates metaclasses and slot-definition
	 * classes, and bounding the arm set keeps the defun from growing with every class the
	 * program defines. When the program takes {@code make-instance} itself as a VALUE
	 * ({@code allClasses}), the arms widen to every registered class the program can
	 * construct -- and the dispatch is CHUNKED into {@code %MMI-<n>} helper defuns by
	 * cons-node budget (the {@code %ALLOC-INST} pattern: a real library registers enough
	 * classes to push one cond past the JVM's signed 16-bit branch encoding), with the
	 * initialization-generic call hoisted into the public defun so each arm stays one
	 * constructor {@code apply}.
	 */
	private static List<LispVal> mopMakeInstanceDefuns(ClosRegistry closRegistry, boolean allClasses) {
		LispSymbol cls = new LispSymbol("%mmi_class");
		LispSymbol args = new LispSymbol("%mmi_args");
		LispSymbol name = new LispSymbol("%mmi_name");
		LispSymbol obj = new LispSymbol("%mmi_obj");
		ClosRegistry.GenericInfo init = closRegistry.generics()
			.values()
			.stream()
			.filter(g -> "INITIALIZE-INSTANCE".equals(plainName(g.name())))
			.findFirst()
			.orElse(null);
		boolean sharedInit = false;
		if (init == null) {
			init = closRegistry.generics()
				.values()
				.stream()
				.filter(g -> "SHARED-INITIALIZE".equals(plainName(g.name())))
				.findFirst()
				.orElse(null);
			sharedInit = init != null;
		}
		LispVal initCallOnObj = null;
		if (init != null) {
			List<LispVal> initCall = new java.util.ArrayList<>();
			initCall.add(new LispSymbol(LispNames.APPLY));
			initCall.add(functionRef(init.name()));
			initCall.add(obj);
			if (sharedInit) {
				initCall.add(LispTrue.INSTANCE);
			}
			initCall.add(args);
			initCallOnObj = listToCons(initCall);
		}
		LispVal designator = makeIf(callOf(LispNames.OBJ_P, cls), mvCall(LispNames.OBJ_REF, cls, new LispInteger(0)),
				cls);
		LispVal errorForm = listToCons(List.of(new LispSymbol(LispNames.ERROR),
				new LispString(LispNames.MOP_MAKE_INSTANCE + ": not an instantiable class: ~A"), name));
		List<LispVal> defuns = new java.util.ArrayList<>();
		List<LispVal> clauses = new java.util.ArrayList<>();
		// The runtime twin of expandMakeInstance's re-fill: after the initialization
		// generic returns, re-set the declared-initarg slots the call supplied, for the
		// classes an initialization :before method specializes (it runs before CL's
		// initarg fill, but after the constructor's). Bounded by that :before set, so
		// the dispatch stays one defun.
		java.util.Set<String> refillTargets = init == null ? java.util.Set.of() : closRegistry.initRefillTargets();
		List<LispVal> refillClauses = new java.util.ArrayList<>();
		LispVal refillCall = mvCall(MMI_REFILL, name, obj, args);
		java.util.Set<String> seen = new java.util.HashSet<>();
		List<String> helperNames = new java.util.ArrayList<>();
		int clauseNodes = 0;
		for (ClosRegistry.ClassInfo info : closRegistry.classes().values()) {
			if (!seen.add(info.name()) || (!allClasses && !isMetaobjectClass(info))) {
				continue;
			}
			// A seeded class other than the MOP trio (the condition hierarchy) has no
			// generated keyword constructor to dispatch to; the fall-through error arm
			// answers for it.
			if (allClasses && closRegistry.isSeededClass(info.name()) && !isMetaobjectClass(info)) {
				continue;
			}
			List<String> spellings = new java.util.ArrayList<>();
			spellings.add(info.name());
			PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(info.name());
			if (qn != null && closRegistry.findClass(qn.member()) == info) {
				spellings.add(qn.member());
			}
			LispVal refillForms = info.ancestors().stream().anyMatch(refillTargets::contains)
					? initRefillFormsFor(info, obj, args) : null;
			if (refillForms != null) {
				refillClauses
					.add(listToCons(List.of(mvCall(LispNames.MEMBER, name, quotedSymbolList(spellings)), refillForms)));
			}
			String ctor = qn == null ? affixFor("%make-", info.name()) + info.name()
					: qn.pkg() + "::" + affixFor("%make-", qn.member()) + qn.member();
			LispVal construct = listToCons(List.of(new LispSymbol(LispNames.APPLY), functionRef(ctor), args));
			LispVal arm;
			if (allClasses || initCallOnObj == null) {
				// Chunked mode (and the no-init-generic case): the arm only constructs;
				// the public defun runs the initialization generic on the result.
				arm = construct;
			}
			else if (refillForms != null) {
				arm = listToCons(List.of(new LispSymbol(LispNames.LET),
						listToCons(List.of(listToCons(List.of(obj, construct)))), initCallOnObj, refillCall, obj));
			}
			else {
				arm = listToCons(List.of(new LispSymbol(LispNames.LET),
						listToCons(List.of(listToCons(List.of(obj, construct)))), initCallOnObj, obj));
			}
			LispVal clause = listToCons(List.of(mvCall(LispNames.MEMBER, name, quotedSymbolList(spellings)), arm));
			clauses.add(clause);
			if (allClasses) {
				clauseNodes += consNodeCount(clause);
				if (clauseNodes >= 600) {
					defuns.add(mopMakeInstanceHelperDefun(helperNames, clauses, name, args));
					clauses = new java.util.ArrayList<>();
					clauseNodes = 0;
				}
			}
		}
		if (!refillClauses.isEmpty()) {
			defuns.addAll(0, initRefillDefuns(refillClauses, name, obj, args));
		}
		if (!allClasses) {
			List<LispVal> condParts = new java.util.ArrayList<>();
			condParts.add(new LispSymbol(LispNames.COND));
			condParts.addAll(clauses);
			condParts.add(listToCons(List.of(LispTrue.INSTANCE, errorForm)));
			defuns.add(listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.MOP_MAKE_INSTANCE),
					listToCons(List.of(cls, new LispSymbol(LispNames.LAMBDA_REST), args)),
					makeLet(name.name(), designator, listToCons(condParts)))));
			return defuns;
		}
		if (!clauses.isEmpty()) {
			defuns.add(mopMakeInstanceHelperDefun(helperNames, clauses, name, args));
		}
		LispVal chain = LispNil.INSTANCE;
		if (!helperNames.isEmpty()) {
			List<LispVal> orParts = new java.util.ArrayList<>();
			orParts.add(new LispSymbol(LispNames.OR));
			for (String helper : helperNames) {
				orParts.add(mvCall(helper, name, args));
			}
			chain = listToCons(orParts);
		}
		List<LispVal> foundParts = new java.util.ArrayList<>();
		if (initCallOnObj != null) {
			foundParts.add(initCallOnObj);
			if (!refillClauses.isEmpty()) {
				foundParts.add(refillCall);
			}
		}
		foundParts.add(obj);
		LispVal found = foundParts.size() == 1 ? obj : makeProgn(foundParts);
		LispVal body = makeLet(name.name(), designator, makeLet(obj.name(), chain, makeIf(obj, found, errorForm)));
		defuns.add(listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.MOP_MAKE_INSTANCE),
				listToCons(List.of(cls, new LispSymbol(LispNames.LAMBDA_REST), args)), body)));
		return defuns;
	}

	/** The generated re-fill dispatch defun's name. */
	private static final String MMI_REFILL = "%MMI-REFILL";

	/** The generated first-matching-initarg-tail helper's name. */
	private static final String MMI_INIT_TAIL = "%MMI-INIT-TAIL";

	/**
	 * The per-class re-fill body of the {@code %MMI-REFILL} dispatch: for each
	 * declared-initarg slot, the leftmost supplied initarg pair (if any) overwrites the
	 * slot -- CL's shared-initialize fill outcome, replayed after the initialization
	 * generic so a {@code :before}'s write to such a slot does not survive it. Null when
	 * the class declares no initargs.
	 */
	private static @org.jspecify.annotations.Nullable LispVal initRefillFormsFor(ClosRegistry.ClassInfo info,
			LispSymbol obj, LispSymbol args) {
		List<LispVal> forms = new java.util.ArrayList<>();
		List<ClosRegistry.SlotSpec> slots = info.slots();
		for (int s = 0; s < slots.size(); s++) {
			ClosRegistry.SlotSpec slot = slots.get(s);
			if (!slot.initargSupplied()) {
				continue;
			}
			LispSymbol tail = new LispSymbol("%mmi_tail");
			forms.add(makeLet(tail.name(), mvCall(MMI_INIT_TAIL, args, new LispSymbol(slot.initargKeyword())),
					makeIf(tail, mvCall(LispNames.OBJ_SET, obj, new LispInteger(s), callOf(LispNames.CAR, tail)),
							LispNil.INSTANCE)));
		}
		return forms.isEmpty() ? null : makeProgn(forms);
	}

	/**
	 * The {@code %MMI-INIT-TAIL} plist scanner (the leftmost pair whose key is the given
	 * keyword, answered as its value tail, nil when absent) and the {@code %MMI-REFILL}
	 * dispatch over the given per-class clauses.
	 */
	private static List<LispVal> initRefillDefuns(List<LispVal> refillClauses, LispSymbol name, LispSymbol obj,
			LispSymbol args) {
		LispSymbol plist = new LispSymbol("%mmi_plist");
		LispSymbol key = new LispSymbol("%mmi_key");
		LispSymbol cursor = new LispSymbol("%mmi_cursor");
		LispVal step = callOf(LispNames.CDR, callOf(LispNames.CDR, cursor));
		LispVal scan = listToCons(
				List.of(new LispSymbol(LispNames.DO), listToCons(List.of(listToCons(List.of(cursor, plist, step)))),
						listToCons(List.of(callOf(LispNames.NULL, cursor), LispNil.INSTANCE)),
						makeIf(mvCall(LispNames.EQ_GENERAL, callOf(LispNames.CAR, cursor), key),
								listToCons(List.of(new LispSymbol(LispNames.RETURN), callOf(LispNames.CDR, cursor))),
								LispNil.INSTANCE)));
		LispVal tailDefun = listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(MMI_INIT_TAIL),
				listToCons(List.of(plist, key)), scan));
		List<LispVal> condParts = new java.util.ArrayList<>();
		condParts.add(new LispSymbol(LispNames.COND));
		condParts.addAll(refillClauses);
		condParts.add(listToCons(List.of(LispTrue.INSTANCE, LispNil.INSTANCE)));
		LispVal refillDefun = listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(MMI_REFILL),
				listToCons(List.of(name, obj, args)), listToCons(condParts)));
		return List.of(tailDefun, refillDefun);
	}

	/** One {@code %MMI-<n>} helper: a cond over its chunk's construction arms. */
	private static LispVal mopMakeInstanceHelperDefun(List<String> helperNames, List<LispVal> clauses, LispSymbol name,
			LispSymbol args) {
		String helperName = "%MMI-" + helperNames.size();
		helperNames.add(helperName);
		List<LispVal> condParts = new java.util.ArrayList<>();
		condParts.add(new LispSymbol(LispNames.COND));
		condParts.addAll(clauses);
		condParts.add(listToCons(List.of(LispTrue.INSTANCE, LispNil.INSTANCE)));
		return listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(helperName),
				listToCons(List.of(name, args)), listToCons(condParts)));
	}

	/** Whether the class descends from one of the seeded MOP base classes. */
	private static boolean isMetaobjectClass(ClosRegistry.ClassInfo info) {
		return info.ancestors().contains(ClosRegistry.STANDARD_CLASS_NAME)
				|| info.ancestors().contains(ClosRegistry.STANDARD_DIRECT_SLOT_DEFINITION_NAME)
				|| info.ancestors().contains(ClosRegistry.STANDARD_EFFECTIVE_SLOT_DEFINITION_NAME);
	}

	/** Builds a {@code (function name)} reference. */
	private static LispVal functionRef(String name) {
		return listToCons(List.of(new LispSymbol(LispNames.FUNCTION), new LispSymbol(name)));
	}

	/**
	 * Builds the generated {@code %register-class-metaobject} defun: prepends the (name .
	 * metaobject) pair onto the {@code find-class} memo, so the driver-built metaclass
	 * instance SHADOWS the plain materialized view from then on (the memo scan takes the
	 * first hit). Registered under the canonical class name, which is what
	 * {@code %find-class-materialize} both scans and memoizes by.
	 */
	private static LispVal registerClassMetaobjectDefun() {
		LispSymbol name = new LispSymbol("%rcm_name");
		LispSymbol metaobject = new LispSymbol("%rcm_obj");
		LispVal push = listToCons(List.of(new LispSymbol(LispNames.SETQ),
				new LispSymbol(LispNames.CLASS_METAOBJECT_MEMO), mvCall(LispNames.CONS,
						mvCall(LispNames.CONS, name, metaobject), new LispSymbol(LispNames.CLASS_METAOBJECT_MEMO))));
		return listToCons(List.of(new LispSymbol(LispNames.DEFUN), new LispSymbol(LispNames.REGISTER_CLASS_METAOBJECT),
				listToCons(List.of(name, metaobject)), push, metaobject));
	}

	/** The literal type specifier an argument form denotes, or null for a runtime one. */
	@Nullable private static LispVal literalTypeSpecifier(LispVal arg) {
		if (arg instanceof LispCons quoted && quoted.car() instanceof LispSymbol q && LispNames.QUOTE.equals(q.name())
				&& quoted.cdr() instanceof LispCons rest) {
			return rest.car();
		}
		if (arg instanceof LispSymbol sym && sym.name().startsWith(":")) {
			return arg;
		}
		if (arg instanceof LispTrue || arg instanceof LispNil) {
			return arg;
		}
		return null;
	}

	/**
	 * Expands a {@code subtypep} whose specifiers are not both literal into a runtime
	 * dispatch over the compile-time type universe -- the built-in lattice (aliases
	 * included) plus every registered class under both its qualified and plain spelling.
	 * The generated form evaluates both specifiers once, answers the constant edges (a
	 * nil sub or a {@code t} super), and otherwise tests the super against the sub's
	 * precomputed ancestor list, scanned from the {@code %subtypep-ancestor-table%} data
	 * table; each pair's answer comes from the same shared {@link #subtypep} the literal
	 * fold uses, so a runtime name answers exactly like the quoted spelling. Symbols
	 * outside the universe (and non-symbols) answer nil. The per-name data lives in the
	 * table (a top-level defvar of pure quoted data), so the defun stays a fixed size:
	 * the previous inline clause-per-group shape grew past the JVM's 16-bit branch
	 * offsets at cl-postgres scale (59 KB of bytecode at 165 registered classes).
	 */
	private static LispVal expandRuntimeSubtypep(LispVal subExpr, LispVal supExpr) {
		String prefix = "__st" + MV_COUNTER.getAndIncrement();
		LispSymbol a = new LispSymbol(prefix + "_a");
		LispSymbol b = new LispSymbol(prefix + "_b");
		LispSymbol entry = new LispSymbol(prefix + "_e");
		// (dolist (e table nil) (if (member a (car e)) (return (cdr e)) nil))
		LispVal ancestorScan = listToCons(List.of(new LispSymbol(LispNames.DOLIST),
				listToCons(List.of(entry, new LispSymbol(LispNames.SUBTYPEP_ANCESTOR_TABLE), LispNil.INSTANCE)),
				makeIf(mvCall(LispNames.MEMBER, a, mvCall(LispNames.CAR, entry)),
						listToCons(List.of(new LispSymbol(LispNames.RETURN), mvCall(LispNames.CDR, entry))),
						LispNil.INSTANCE)));
		LispVal memberTest = makeIf(mvCall(LispNames.MEMBER, b, ancestorScan), LispTrue.INSTANCE, LispNil.INSTANCE);
		List<LispVal> clauses = new java.util.ArrayList<>();
		clauses.add(listToCons(List.of(mvCall(LispNames.NULL, a), LispTrue.INSTANCE)));
		clauses.add(listToCons(List.of(fmtCall(LispNames.EQ_GENERAL, b, LispTrue.INSTANCE), LispTrue.INSTANCE)));
		clauses.add(listToCons(List.of(LispTrue.INSTANCE, memberTest)));
		List<LispVal> condParts = new java.util.ArrayList<>();
		condParts.add(new LispSymbol(LispNames.COND));
		condParts.addAll(clauses);
		return makeLet(a.name(), subExpr, makeLet(b.name(), supExpr, listToCons(condParts)));
	}

	/**
	 * Builds the {@code %subtypep-ancestor-table%} data-table forms backing
	 * {@link #expandRuntimeSubtypep}: the universe's names grouped by ancestor set so
	 * aliases share one entry. Pure quoted data, emitted through
	 * {@link #chunkedTableForms}.
	 */
	private static List<LispVal> subtypepAncestorTableForms(ClosRegistry closRegistry) {
		List<String> universe = subtypepUniverse(closRegistry);
		java.util.Map<List<String>, List<String>> subsByAncestors = new java.util.LinkedHashMap<>();
		for (String name : universe) {
			List<String> ancestors = new java.util.ArrayList<>();
			for (String candidate : universe) {
				if (subtypep(new LispSymbol(name), new LispSymbol(candidate), closRegistry)) {
					ancestors.add(candidate);
				}
			}
			subsByAncestors.computeIfAbsent(ancestors, k -> new java.util.ArrayList<>()).add(name);
		}
		List<LispVal> entries = new java.util.ArrayList<>();
		for (java.util.Map.Entry<List<String>, List<String>> entry : subsByAncestors.entrySet()) {
			List<LispVal> entryParts = new java.util.ArrayList<>();
			List<LispVal> subSyms = new java.util.ArrayList<>();
			for (String name : entry.getValue()) {
				subSyms.add(new LispSymbol(name));
			}
			entryParts.add(listToCons(subSyms));
			for (String ancestor : entry.getKey()) {
				entryParts.add(new LispSymbol(ancestor));
			}
			entries.add(listToCons(entryParts));
		}
		return chunkedTableForms(LispNames.SUBTYPEP_ANCESTOR_TABLE, entries);
	}

	/** The runtime-subtypep type universe; see {@link #expandRuntimeSubtypep}. */
	private static List<String> subtypepUniverse(ClosRegistry closRegistry) {
		java.util.LinkedHashSet<String> names = new java.util.LinkedHashSet<>();
		for (java.util.Map.Entry<String, List<String>> entry : SUBTYPEP_PARENTS.entrySet()) {
			names.add(entry.getKey());
			names.addAll(entry.getValue());
		}
		names.addAll(List.of("SINGLE-FLOAT", "DOUBLE-FLOAT", "SHORT-FLOAT", "LONG-FLOAT", "BASE-CHAR", "STANDARD-CHAR",
				"EXTENDED-CHAR", "SIMPLE-STRING", "BASE-STRING", "SIMPLE-BASE-STRING", "SIMPLE-VECTOR", "SIMPLE-ARRAY",
				"CHARACTER", "STANDARD-OBJECT", "CONDITION", "ERROR", "SIMPLE-ERROR", "SIMPLE-CONDITION"));
		for (ClosRegistry.ClassInfo info : closRegistry.classes().values()) {
			names.add(info.name());
			PackageRegistry.QualifiedName qn = PackageRegistry.splitQualified(info.name());
			if (qn != null) {
				names.add(qn.member());
			}
		}
		return List.copyOf(names);
	}

	/** Builds {@code '(name...)} from name strings. */
	private static LispVal quotedSymbolList(List<String> names) {
		List<LispVal> syms = new java.util.ArrayList<>();
		for (String name : names) {
			syms.add(new LispSymbol(name));
		}
		return listToCons(List.of(new LispSymbol(LispNames.QUOTE), listToCons(syms)));
	}

	/**
	 * Expands {@code (prog bindings tag-or-form...)} into {@code (%block (let bindings
	 * (tagbody ...)))} -- the CL block-nil + let + tagbody sandwich, so {@code (return
	 * x)} exits the prog and {@code go} jumps between its labels.
	 * @param cons the prog expression
	 * @param sequential whether the bindings are sequential ({@code prog*})
	 * @return the expanded expression
	 */
	public static LispVal expandProg(LispCons cons, boolean sequential) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException(LispNames.PROG + " expects a binding list");
		}
		List<LispVal> tagbody = new java.util.ArrayList<>();
		tagbody.add(new LispSymbol(LispNames.TAGBODY));
		tagbody.addAll(parts.subList(2, parts.size()));
		List<LispVal> let = new java.util.ArrayList<>();
		let.add(new LispSymbol(sequential ? LispNames.LET_STAR : LispNames.LET));
		let.add(parts.get(1));
		let.add(listToCons(tagbody));
		return makeBlock(listToCons(let));
	}

	/**
	 * Expands (multiple-value-list values-form) into a form evaluating to the list of the
	 * producer's values: {@code (list e...)} for a literal {@code values} call, the
	 * lowered two-value form for {@code floor}-family/{@code gethash}, and
	 * {@code (list form)} for any other (single-value) producer.
	 * @param cons the multiple-value-list expression
	 * @return the expanded expression
	 */
	public static LispVal expandMultipleValueList(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 2) {
			throw new IllegalArgumentException(
					LispNames.MULTIPLE_VALUE_LIST + " expects exactly one form: " + cons.print());
		}
		return mvListForm(parts.get(1));
	}

	private static LispVal mvListForm(LispVal producer) {
		if (producer instanceof LispCons cons && cons.car() instanceof LispSymbol op
				&& LispNames.VALUES.equals(op.name()) && cons.isProperList()) {
			// (values e...) -> (list e...): list evaluates left to right.
			List<LispVal> listParts = new java.util.ArrayList<>(cons.toList());
			listParts.set(0, new LispSymbol(LispNames.LIST));
			return listToCons(listParts);
		}
		MvProducer lowered = lowerMvProducer(producer, "__mv" + MV_COUNTER.getAndIncrement());
		if (lowered.rest() != null) {
			// (cons primary rest): the spill list is freshly consed per values call,
			// so sharing its tail is safe.
			return nestMvBindings(lowered.bindings(), mvCall(LispNames.CONS, lowered.values().get(0), lowered.rest()));
		}
		List<LispVal> listParts = new java.util.ArrayList<>();
		listParts.add(new LispSymbol(LispNames.LIST));
		listParts.addAll(lowered.values());
		return nestMvBindings(lowered.bindings(), listToCons(listParts));
	}

	/**
	 * Expands (nth-value n values-form) into {@code (nth n (multiple-value-list form))}
	 * (n evaluates before the form, as in CL).
	 * @param cons the nth-value expression
	 * @return the expanded expression
	 */
	public static LispVal expandNthValue(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() != 3) {
			throw new IllegalArgumentException(LispNames.NTH_VALUE + " expects an index and a form: " + cons.print());
		}
		return listToCons(List.of(new LispSymbol(LispNames.NTH), parts.get(1), mvListForm(parts.get(2))));
	}

	/**
	 * Counter for the temporaries generated by {@code destructuring-bind} expansions. A
	 * per-expansion id keeps nested expansions from binding the same variable name.
	 */
	private static final java.util.concurrent.atomic.AtomicInteger DB_COUNTER = new java.util.concurrent.atomic.AtomicInteger();

	/**
	 * Expands (destructuring-bind pattern form body...) into a {@code let*} binding each
	 * pattern variable to its car/cdr chain over the evaluated form. The pattern is a
	 * macro-style lambda list: nested patterns in required positions and
	 * {@code &optional}/{@code &rest}/{@code &body}/{@code &key}/{@code &aux} (also
	 * inside nested patterns) are supported; {@code &whole}/{@code &environment} are not.
	 * Lite semantics: a mismatch between the pattern and the value does not signal -- a
	 * missing position binds to nil and surplus elements are ignored (only an undeclared
	 * keyword under {@code &key} signals, as in the function lambda lists).
	 *
	 * <pre>
	 * (destructuring-bind (a (b) &amp;optional (c 9)) '(1 (2)) (list a b c))
	 * -> (let* ((__db0_whole '(1 (2)))
	 *           (a (car __db0_whole))
	 *           (b (car (car (cdr __db0_whole))))
	 *           (__db0_r0 (cdr (cdr __db0_whole)))
	 *           (c (if (consp __db0_r0) (car __db0_r0) 9))
	 *           (__db0_r0 (if (consp __db0_r0) (cdr __db0_r0) nil)))
	 *      (list a b c))
	 * </pre>
	 * @param cons the destructuring-bind expression
	 * @return the expanded expression
	 */
	public static LispVal expandDestructuringBind(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 3 || !(parts.get(1) instanceof LispCons || parts.get(1) instanceof LispNil)) {
			throw new IllegalArgumentException(
					LispNames.DESTRUCTURING_BIND + " expects a pattern list and a form: " + cons.print());
		}
		String prefix = "__db" + DB_COUNTER.getAndIncrement();
		LispSymbol whole = new LispSymbol(prefix + "_whole");
		List<LispVal> bindings = new java.util.ArrayList<>();
		bindings.add(listToCons(List.of(whole, parts.get(2))));
		destructuringBindings(parts.get(1), whole, prefix, new int[] { 0 }, bindings);
		List<LispVal> letParts = new java.util.ArrayList<>();
		letParts.add(new LispSymbol(LispNames.LET_STAR));
		letParts.add(listToCons(bindings));
		if (parts.size() == 3) {
			letParts.add(LispNil.INSTANCE);
		}
		letParts.addAll(parts.subList(3, parts.size()));
		return listToCons(letParts);
	}

	/**
	 * Appends the {@code let*} bindings destructuring the pattern over the source
	 * expression. A keyword-free pattern goes through the shared plain walker
	 * ({@link #destructurePairs}, car/cdr accessor chains); a pattern using lambda-list
	 * keywords binds its required prefix positionally and delegates the tail to
	 * {@link LambdaLists#appendTailBindings}. Nested sub-patterns recurse; a
	 * keyword-using sub-pattern goes through its own temporary because the tail machinery
	 * rebinds its rest variable.
	 */
	private static void destructuringBindings(LispVal pattern, LispVal source, String prefix, int[] counter,
			List<LispVal> out) {
		if (pattern instanceof LispNil) {
			return;
		}
		if (!containsLambdaListKeyword(pattern)) {
			List<LispVal[]> pairs = new java.util.ArrayList<>();
			destructurePairs(pattern, source, pairs);
			for (LispVal[] p : pairs) {
				out.add(listToCons(List.of(p[0], p[1])));
			}
			return;
		}
		if (!(pattern instanceof LispCons patternCons) || !patternCons.isProperList()) {
			throw new IllegalArgumentException("invalid destructuring pattern: " + pattern.print());
		}
		List<LispVal> elements = patternCons.toList();
		// &whole var (first element, per CL): bind var to the whole source list, then
		// destructure the remaining pattern over the same source. The source accessor
		// chain is side-effect-free, so evaluating it twice is safe.
		if (elements.size() >= 2 && elements.get(0) instanceof LispSymbol wholeKw
				&& LispNames.LAMBDA_WHOLE.equals(wholeKw.name()) && elements.get(1) instanceof LispSymbol wholeVar
				&& !wholeVar.name().startsWith("&")) {
			out.add(listToCons(List.of(wholeVar, source)));
			elements = elements.subList(2, elements.size());
		}
		int firstKeyword = 0;
		while (firstKeyword < elements.size()
				&& !(elements.get(firstKeyword) instanceof LispSymbol sym && sym.name().startsWith("&"))) {
			firstKeyword++;
		}
		LispVal cursor = source;
		for (int i = 0; i < firstKeyword; i++) {
			LispVal e = elements.get(i);
			LispVal acc = mvCall(LispNames.CAR, cursor);
			if (e instanceof LispSymbol s) {
				out.add(listToCons(List.of(s, acc)));
			}
			else if (e instanceof LispCons nested && containsLambdaListKeyword(nested)) {
				LispSymbol tmp = new LispSymbol(prefix + "_g" + counter[0]++);
				out.add(listToCons(List.of(tmp, acc)));
				destructuringBindings(nested, tmp, prefix, counter, out);
			}
			else if (e instanceof LispCons nested) {
				destructuringBindings(nested, acc, prefix, counter, out);
			}
			else if (!(e instanceof LispNil)) {
				throw new IllegalArgumentException("invalid destructuring pattern: " + pattern.print());
			}
			cursor = mvCall(LispNames.CDR, cursor);
		}
		if (firstKeyword < elements.size()) {
			// The keyword may also sit only inside a nested sub-pattern (handled above).
			LispSymbol restTmp = new LispSymbol(prefix + "_r" + counter[0]++);
			out.add(listToCons(List.of(restTmp, cursor)));
			// &rest/&body may be followed by a destructuring PATTERN instead of a
			// variable (macro lambda lists; alexandria's if-let is
			// (bindings &body (then-form &optional else-form))): route the rest list
			// through a temporary and recurse the pattern over it.
			List<LispVal> tail = new java.util.ArrayList<>(elements.subList(firstKeyword, elements.size()));
			LispVal restPattern = null;
			LispSymbol restPatternTmp = null;
			for (int i = 0; i + 1 < tail.size(); i++) {
				if (tail.get(i) instanceof LispSymbol s
						&& (LispNames.LAMBDA_REST.equals(s.name()) || LispNames.LAMBDA_BODY.equals(s.name()))
						&& tail.get(i + 1) instanceof LispCons pat) {
					restPattern = pat;
					restPatternTmp = new LispSymbol(prefix + "_g" + counter[0]++);
					tail.set(i + 1, restPatternTmp);
					break;
				}
			}
			LambdaLists.appendTailBindings(tail, restTmp, out);
			if (restPattern != null && restPatternTmp != null) {
				destructuringBindings(restPattern, restPatternTmp, prefix, counter, out);
			}
		}
	}

	/**
	 * True when the pattern contains a lambda-list keyword (a {@code &}-symbol) at any
	 * depth.
	 */
	private static boolean containsLambdaListKeyword(LispVal pattern) {
		if (pattern instanceof LispSymbol sym) {
			return sym.name().startsWith("&");
		}
		if (pattern instanceof LispCons cons) {
			return containsLambdaListKeyword(cons.car()) || containsLambdaListKeyword(cons.cdr());
		}
		return false;
	}

	/**
	 * Collects {@code {var, accessor}} pairs binding each symbol of a plain
	 * (keyword-free) destructuring pattern to the matching car/cdr chain over the source
	 * expression. A nil in the pattern ignores that position. Shared by the {@code loop}
	 * destructuring clauses and {@code destructuring-bind}.
	 */
	private static void destructurePairs(LispVal pattern, LispVal source, List<LispVal[]> out) {
		if (pattern instanceof LispNil) {
			return;
		}
		if (pattern instanceof LispSymbol s) {
			out.add(new LispVal[] { s, source });
			return;
		}
		if (pattern instanceof LispCons c) {
			destructurePairs(c.car(), mvCall(LispNames.CAR, source), out);
			destructurePairs(c.cdr(), mvCall(LispNames.CDR, source), out);
			return;
		}
		throw new IllegalArgumentException("invalid destructuring pattern: " + pattern.print());
	}

	/**
	 * Expands (multiple-value-call function values-form...) into a direct {@code funcall}
	 * whose arguments are every producer's values: the function and the producers' temps
	 * bind in nested lets (left-to-right evaluation), so the value count is static -- no
	 * runtime spreading.
	 *
	 * <pre>
	 * (multiple-value-call #'list 1 (values 2 3))
	 * -> (let ((__mv0_fn #'list)) (let ((__mv0_0_0 1)) (let ((__mv0_1_0 2)) (let ((__mv0_1_1 3))
	 *      (funcall __mv0_fn __mv0_0_0 __mv0_1_0 __mv0_1_1)))))
	 * </pre>
	 * @param cons the multiple-value-call expression
	 * @return the expanded expression
	 */
	public static LispVal expandMultipleValueCall(LispCons cons) {
		List<LispVal> parts = cons.toList();
		if (parts.size() < 2) {
			throw new IllegalArgumentException(
					LispNames.MULTIPLE_VALUE_CALL + " expects a function form: " + cons.print());
		}
		String prefix = "__mv" + MV_COUNTER.getAndIncrement();
		List<MvBinding> bindings = new java.util.ArrayList<>();
		LispSymbol fn = new LispSymbol(prefix + "_fn");
		bindings.add(new MvBinding(fn, parts.get(1)));
		List<MvProducer> producers = new java.util.ArrayList<>();
		boolean anySpill = false;
		for (int i = 2; i < parts.size(); i++) {
			MvProducer producer = lowerMvProducer(parts.get(i), prefix + "_" + (i - 2));
			bindings.addAll(producer.bindings());
			producers.add(producer);
			anySpill = anySpill || producer.rest() != null;
		}
		if (anySpill) {
			// A spill producer's value count is dynamic, so the argument list is
			// built at runtime and spread with apply: (apply fn (append seg...)),
			// where a syntactic producer contributes (list v...) and a spill one
			// (cons primary rest).
			List<LispVal> appendParts = new java.util.ArrayList<>();
			appendParts.add(new LispSymbol(LispNames.APPEND));
			for (MvProducer producer : producers) {
				if (producer.rest() != null) {
					appendParts.add(mvCall(LispNames.CONS, producer.values().get(0), producer.rest()));
				}
				else {
					List<LispVal> seg = new java.util.ArrayList<>();
					seg.add(new LispSymbol(LispNames.LIST));
					seg.addAll(producer.values());
					appendParts.add(listToCons(seg));
				}
			}
			LispVal applyCall = mvCall(LispNames.APPLY, fn, listToCons(appendParts));
			return nestMvBindings(bindings, applyCall);
		}
		List<LispVal> callParts = new java.util.ArrayList<>();
		callParts.add(new LispSymbol(LispNames.FUNCALL));
		callParts.add(fn);
		for (MvProducer producer : producers) {
			callParts.addAll(producer.values());
		}
		return nestMvBindings(bindings, listToCons(callParts));
	}

	/**
	 * Splices top-level {@code (progn ...)} and {@code (eval-when (situations) ...)}
	 * forms into the top-level form list (recursively), preserving evaluation order. Used
	 * on the compile path (and by {@code UserMacroExpander}) so Pass 1 defun collection
	 * and the compile-time defmacro scan see definitions nested in the
	 * {@code (eval-when (:compile-toplevel ...) (defmacro ...))} idiom. The interpreter
	 * needs no flattening: it evaluates {@code eval-when} as {@code progn} natively.
	 * @param program the top-level forms
	 * @return the flattened top-level forms
	 */
	/**
	 * Prepends the top-level {@code (setq %mv-spill nil)} creating the multiple-value
	 * spill global (see {@link LispNames#MV_SPILL}) when the program uses any
	 * multiple-value operator; returns the program unchanged otherwise. Both compilers
	 * call this so the global exists for the spill reads/writes their expansions emit
	 * (the interpreter predefines the variable instead).
	 * @param program the top-level forms (package-resolved)
	 * @return the program, with the spill global prepended when needed
	 */
	/**
	 * Normalizes a {@code let}/{@code let*} binding list: a bare symbol entry (CL's
	 * init-less binding, {@code (let (a b) ...)}) becomes {@code (sym nil)} so every
	 * consumer -- the evaluator, the compilers and the analyzers -- only sees the
	 * {@code (name init)} pair shape. Returns the list unchanged when nothing needs
	 * normalizing.
	 * @param bindings the binding list form
	 * @return the normalized binding list
	 */
	public static LispVal normalizeBindingList(LispVal bindings) {
		if (!(bindings instanceof LispCons cons) || !cons.isProperList()) {
			return bindings;
		}
		List<LispVal> entries = cons.toList();
		boolean changed = false;
		List<LispVal> out = new java.util.ArrayList<>(entries.size());
		for (LispVal entry : entries) {
			if (entry instanceof LispSymbol) {
				out.add(listToCons(List.of(entry, LispNil.INSTANCE)));
				changed = true;
			}
			else if (entry instanceof LispCons pair && pair.isProperList() && pair.toList().size() == 1) {
				// (x) is CL shorthand for (x nil): real-library idioms use it to reserve
				// accumulators before the body fills them in.
				out.add(listToCons(List.of(pair.car(), LispNil.INSTANCE)));
				changed = true;
			}
			else if (entry instanceof LispCons pair && pair.car() instanceof LispCons quoted
					&& quoted.car() instanceof LispSymbol qop && LispNames.QUOTE.equals(qop.name())) {
				// A (let ((*package* X)) ...) rebinding: the resolver substitutes a
				// *package* READ with its quoted read-time package, which also hits the
				// binding-name slot. The binding is renamed to the PACKAGE_REBIND_VAR
				// marker; the interpreter's evalLet additionally rebinds its runtime
				// current package (so a macro-time (intern ...) under the binding homes
				// where CL would -- ironclad's optimized-maker-name idiom), while the
				// compilers treat it as a plain throwaway binding.
				out.add(listToCons(List.of(new LispSymbol(PACKAGE_REBIND_VAR), pair.toList().get(1))));
				changed = true;
			}
			else {
				out.add(entry);
			}
		}
		return changed ? listToCons(out) : bindings;
	}

	/**
	 * Injects the top-level {@code (setq %mv-spill nil)} /
	 * {@code (setq *read-default-float-format* ...)} globals the compilers need when the
	 * program uses a multiple-value operator or the float-format variable; returns the
	 * program unchanged otherwise.
	 * @param program the top-level forms
	 * @return the program with the required global initializers prepended
	 */
	public static List<LispVal> injectMvSpillGlobal(List<LispVal> program) {
		boolean usesMv = false;
		boolean usesFloatFormat = false;
		boolean usesPrintEscape = false;
		boolean usesPrintReadably = false;
		// The load-context pathname variables (LispNames.LOAD_TRUENAME_VAR &c) plus
		// *readtable*, which a loader binds in the same let (clack's %load-file binds all
		// four around its read/eval loop). On the compile paths they are all nil and stay
		// nil: a library file is SPLICED into the program at compile time, so nothing is
		// being loaded -- nor compile-file'd -- at run time, and the reader is the
		// frontend's, with no runtime readtable object to name. Declared anyway so a
		// library that reads or rebinds one (local-time's
		// (or *compile-file-truename* *load-truename*) zoneinfo lookup) compiles; nil is
		// also what the interpreter's *readtable* holds, so the value agrees everywhere.
		java.util.List<String> loadContextVars = new java.util.ArrayList<>();
		for (LispVal form : program) {
			usesMv = usesMv || usesMvOperator(form);
			usesFloatFormat = usesFloatFormat || usesSymbol(form, LispNames.READ_DEFAULT_FLOAT_FORMAT);
			usesPrintEscape = usesPrintEscape || usesSymbol(form, LispNames.PRINT_ESCAPE_VAR);
			usesPrintReadably = usesPrintReadably || usesSymbol(form, LispNames.PRINT_READABLY_VAR);
		}
		for (String name : List.of(LispNames.LOAD_PATHNAME_VAR, LispNames.LOAD_TRUENAME_VAR,
				LispNames.COMPILE_FILE_PATHNAME_VAR, LispNames.COMPILE_FILE_TRUENAME_VAR, LispNames.READTABLE_VAR)) {
			for (LispVal form : program) {
				if (usesSymbol(form, name)) {
					loadContextVars.add(name);
					break;
				}
			}
		}
		if (!usesMv && !usesFloatFormat && !usesPrintEscape && !usesPrintReadably && loadContextVars.isEmpty()) {
			return program;
		}
		List<LispVal> out = new java.util.ArrayList<>(program.size() + 4 + loadContextVars.size());
		for (String name : loadContextVars) {
			out.add(listToCons(List.of(new LispSymbol(LispNames.DEFVAR), new LispSymbol(name), LispNil.INSTANCE)));
		}
		// The printer-mode variables: declared with defvar (not setq) because the
		// print-object route BINDS *print-escape* around the method call, and only a
		// proclaimed-special name gets a dynamic binding. This pass runs AFTER
		// expandTopLevelDefinitions, so the route's own reference is already in view.
		if (usesPrintEscape) {
			out.add(listToCons(List.of(new LispSymbol(LispNames.DEFVAR), new LispSymbol(LispNames.PRINT_ESCAPE_VAR),
					LispTrue.INSTANCE)));
		}
		if (usesPrintReadably) {
			out.add(listToCons(List.of(new LispSymbol(LispNames.DEFVAR), new LispSymbol(LispNames.PRINT_READABLY_VAR),
					LispNil.INSTANCE)));
		}
		if (usesMv) {
			out.add(listToCons(
					List.of(new LispSymbol(LispNames.SETQ), new LispSymbol(LispNames.MV_SPILL), LispNil.INSTANCE)));
		}
		if (usesFloatFormat) {
			// The standard reader-control variable: informational here (every float is
			// the one double representation), predefined so library code reading it
			// works. See LispNames.READ_DEFAULT_FLOAT_FORMAT.
			out.add(listToCons(
					List.of(new LispSymbol(LispNames.SETQ), new LispSymbol(LispNames.READ_DEFAULT_FLOAT_FORMAT),
							listToCons(List.of(new LispSymbol(LispNames.QUOTE), new LispSymbol("DOUBLE-FLOAT"))))));
		}
		out.addAll(program);
		return out;
	}

	/** True when the form mentions the symbol name anywhere (quote included). */
	private static boolean usesSymbol(LispVal form, String name) {
		if (form instanceof LispSymbol sym) {
			return name.equals(sym.name());
		}
		if (form instanceof LispCons cons) {
			for (LispVal cur = cons; cur instanceof LispCons cell; cur = cell.cdr()) {
				if (usesSymbol(cell.car(), name)) {
					return true;
				}
				if (!(cell.cdr() instanceof LispCons) && usesSymbol(cell.cdr(), name)) {
					return true;
				}
			}
		}
		return false;
	}

	private static boolean usesMvOperator(LispVal form) {
		if (form instanceof LispSymbol sym) {
			return switch (sym.name()) {
				// values-list spreads through the spill and the parse-integer
				// expansion returns its end position via a literal values, so both
				// need the global too.
				case LispNames.VALUES, LispNames.MULTIPLE_VALUE_BIND, LispNames.MULTIPLE_VALUE_LIST,
						LispNames.MULTIPLE_VALUE_CALL, LispNames.NTH_VALUE, LispNames.VALUES_LIST,
						LispNames.PARSE_INTEGER ->
					true;
				default -> false;
			};
		}
		if (form instanceof LispCons cons) {
			for (LispVal cur = cons; cur instanceof LispCons cell; cur = cell.cdr()) {
				if (usesMvOperator(cell.car())) {
					return true;
				}
				if (!(cell.cdr() instanceof LispCons) && usesMvOperator(cell.cdr())) {
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Splices top-level {@code progn}/{@code eval-when} forms into the surrounding
	 * top-level form list (recursively), so nested {@code defun}/{@code defmacro}
	 * definitions are collected on the compile path. A program with nothing to splice is
	 * returned unchanged (identity preserved for callers' early returns).
	 * @param program the top-level forms
	 * @return the flattened top-level forms
	 */
	public static List<LispVal> flattenTopLevel(List<LispVal> program) {
		// Keep the identity of a program with nothing to splice (callers may rely on
		// "returned unchanged", e.g. UserMacroExpander's no-macro early return).
		if (program.stream().noneMatch(LispMacroExpander::isTopLevelSpliceForm)) {
			return program;
		}
		List<LispVal> out = new java.util.ArrayList<>();
		for (LispVal form : program) {
			flattenTopLevelInto(form, out);
		}
		return out;
	}

	private static boolean isTopLevelSpliceForm(LispVal form) {
		return form instanceof LispCons cons && cons.car() instanceof LispSymbol sym && cons.isProperList()
				&& (LispNames.PROGN.equals(sym.name()) || LispNames.LOCALLY.equals(sym.name())
						|| (LispNames.EVAL_WHEN.equals(sym.name()) && cons.toList().size() >= 2));
	}

	private static void flattenTopLevelInto(LispVal form, List<LispVal> out) {
		if (form instanceof LispCons cons && cons.car() instanceof LispSymbol sym && cons.isProperList()) {
			// locally splices like progn: its declarations are no-ops downstream, and
			// libraries wrap top-level defstruct/defun groups in (locally (declare ...)).
			if (LispNames.PROGN.equals(sym.name()) || LispNames.LOCALLY.equals(sym.name())) {
				List<LispVal> parts = cons.toList();
				for (int i = 1; i < parts.size(); i++) {
					flattenTopLevelInto(parts.get(i), out);
				}
				return;
			}
			if (LispNames.EVAL_WHEN.equals(sym.name())) {
				List<LispVal> parts = cons.toList();
				if (parts.size() >= 2) {
					for (int i = 2; i < parts.size(); i++) {
						flattenTopLevelInto(parts.get(i), out);
					}
					return;
				}
			}
		}
		out.add(form);
	}

	private static LispCons listToCons(List<LispVal> elements) {
		LispVal result = LispNil.INSTANCE;
		for (int i = elements.size() - 1; i >= 0; i--) {
			result = new LispCons(elements.get(i), result);
		}
		return (LispCons) result;
	}

}
